/// <summary>
/// Runs through the exact generated PrologueLevel with one persistent production player. After
/// the pre-tree spawn is selected, this proof advances only through real InputMap events and
/// physics frames; it never writes player position or velocity and never calls stream transitions.
/// </summary>
public static partial class PrologueCanyonGeneratedMainRouteTests
{
    internal enum Task10RouteVariant { Main, Exploration }
    private const string MainPath = "res://scenes/prologue/PrologueLevel.tscn";
    private const int StableLandingFrames = 12;
    private const float LandingMarginRatio = .15f;
    private static readonly PrologueSectorId[] OrderedRoute = Enum.GetValues<PrologueSectorId>();

    internal static async Task RunTask10StorageGuard(SceneTree tree)
    {
        Task10ApplicationPersistenceGuard persistence =
            Task10ApplicationPersistenceGuard.CreateFromArguments();
        PackedScene packed = GD.Load<PackedScene>(MainPath) ??
            throw new InvalidOperationException($"exact generated main scene is missing: {MainPath}");
        PrologueLevelController level = packed.Instantiate<PrologueLevelController>();
        level.Name = "Task10StorageGuard";
        PrologueGameFlowController flow = ConfigureTask10Persistence(level, persistence);
        flow.HeadlessAutoStart = false;
        flow.AutomationAutoStart = false;
        try
        {
            tree.Root.AddChild(level);
            await tree.ToSignal(tree, SceneTree.SignalName.ProcessFrame);
            await tree.ToSignal(tree, SceneTree.SignalName.ProcessFrame);
            TestAssert.Equal(PrologueGameFlowState.Title, flow.State,
                "storage guard reaches Title through the normal initializer");
            TestAssert.True(File.Exists(flow.SettingsPath) &&
                Task10ApplicationPersistenceGuard.IsWithin(flow.SettingsPath,
                    persistence.CaseRoot),
                "normal Title initialization writes settings only inside case storage");
            TestAssert.True(!File.Exists(flow.SavePath),
                "Title initialization does not invent progress before Start");

            SendUiAccept(level, pressed: true);
            await tree.ToSignal(tree, SceneTree.SignalName.ProcessFrame);
            SendUiAccept(level, pressed: false);
            for (int frame = 0; frame < 12 && flow.State != PrologueGameFlowState.Playing; frame++)
                await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
            TestAssert.Equal(PrologueGameFlowState.Playing, flow.State,
                "focused persistence proof starts through actual ui_accept");
            TestAssert.True(File.Exists(flow.SavePath) &&
                new FileInfo(flow.SavePath).Length > 0,
                "normal Start writes a nonempty save only inside case storage");
            GD.Print("TASK10_TITLE_STORAGE_GUARD_OK title=True settings=True start_input=True save=True");
        }
        finally
        {
            ReleaseAll(level.GetNode<CharacterBody2D>("PlayerRoot/Player").GlobalPosition);
            try
            {
                if (GodotObject.IsInstanceValid(level) && level.IsInsideTree())
                    await TestSceneTeardown.FreeSceneAfterAudioDrain(tree, level);
            }
            finally
            {
                persistence.AssertProtectedDefaultsUnchanged();
            }
        }
    }

    internal static void AssertTask10GearPistonOneContract(PrologueSector sector)
    {
        // Inspect the actual streamed scene, not a duplicate off-tree world.
        // The latter bypasses lifecycle cleanup of native shapes owned by scripts.
        TestAssert.True(sector.IsInsideTree(),"Basin geometry contract inspects the running saved scene");
                StaticBody2D support = sector.GetNode<StaticBody2D>(
                    "Gameplay/Collision/GearPistonOne");
                RectangleShape2D shape = (RectangleShape2D)support
                    .GetNode<CollisionShape2D>("Collision").Shape;
                GrappleSurface2D surface = support.GetNode<GrappleSurface2D>(
                    "GrappleSurfaceProfile");
                // Preserve the camp approach and casting station, while allowing
                // the whole40px capsule to miss the lift into the return channel.
                Vector2 boundsMin = support.Position - shape.Size / 2 + new Vector2(1280,3600);
                Vector2 boundsMax = boundsMin + shape.Size;
                TestAssert.Equal(new Vector2(2440,3916), boundsMin,
                    "Task10 running PistonOne preserves the original camp-side approach");
                TestAssert.True(boundsMax.Y==3996 && boundsMax.X>=2512 &&
                    2700-boundsMax.X>=44,
                    $"Task10 running station supports the full capsule and missed lift leaves a44px return gap; max={boundsMax}");
                TestAssert.Equal(GrappleSurfaceMaterial.TempleMetal, surface.Material,
                    "Task10 running PistonOne keeps its authored TempleMetal surface");
    }

    internal static Task<PrologueContinuousRouteResult> RunTask10(SceneTree tree,
        Task10RouteVariant variant) => RunTask10(tree, variant, gearEntryWindowOnly: false);

    internal static async Task RunTask10GearEntryWindow(SceneTree tree) =>
        _ = await RunTask10(tree, Task10RouteVariant.Main, gearEntryWindowOnly: true);

