    {
        TestAssert.True(KeyboardRouteInputDriver.Current == null &&
            Array.Exists(OS.GetCmdlineUserArgs(), value => value == "--keyboard-route"),
            "descent diagnostic requires its own physical InputMap keyboard driver");
        PrologueContinuousRouteResult result = await RunTask10(tree,
            Task10RouteVariant.Exploration, gearEntryWindowOnly: false, descentHandoffOnly: true);
        TestAssert.True(result.StartedFromTitle && result.PersistentPlayer &&
            result.Variant == "DescentHandoffDiagnostic",
            "scoped descent keeps the original title, spawn and persistent Player");
        GD.Print("THRUSTER_DESCENT_HANDOFF_OK actual_saved_main=true title=true original_spawn=true " +
            "native_keyboard=true rift_full_support=true archive_full_stop=true " +
            "original_budgets=true full_route=false human=false");
    }

