                Check(saved.GetProperty("version").GetInt32() == PrologueSaveData.CurrentVersion && saved.GetProperty("layoutVersion").GetInt32() == 2 &&
                    saved.GetProperty("hasActivatedCheckpoint").GetBoolean() &&
