                        swapPreObserverGuard, templeCheckpointSnapshotPath);
                    Check(supply.PlayerId == playerId && supply.BossId == bossId &&
                        supply.EntryHp == hp && supply.MaxHp == health.MaxHealth &&
                        supply.ExitHp == Math.Min(supply.MaxHp, hp + 2) &&
                        supply.EntryNextCast == nextCast + 1UL &&
                        supply.ExitNextCast == supply.EntryNextCast + 1UL &&
                        supply.Requests == requests && supply.Recoveries == recoveries &&
                        supply.Jumps == jumps && supply.Dashes == dashes &&
                        supply.ChainApplications == applications + 1 && supply.HealedEvents == 1 &&
                        supply.BoostEvents == 1 && supply.ReleaseEvents == 1 &&
                        supply.SnapshotHash == Convert.ToHexString(SHA256.HashData(retainedBytes)),
                        "validates immutable optional supply identity/HP/cast/action/event deltas before restoring chain-only guards");
                    Task18FragmentReceipt collected = supply.Fragment;
                    Check(new Node[] { supplyFragment, supplyFragmentShape, supplyHud }.All(Live) &&
                        GodotObject.IsInstanceValid(supplyFragmentShape.Shape) &&
                        collected.StableId == supplyFragmentId && collected.NodeId == supplyFragmentNodeId &&
                        supplyFragment.GetInstanceId() == supplyFragmentNodeId &&
                        collected.ShapeId == supplyFragmentShapeId && supplyFragmentShape.Shape.GetInstanceId() == supplyFragmentShapeId &&
                        supplyFragmentShape.Shape is CircleShape2D { Radius: 18 } && !supplyFragmentShape.Disabled &&
                        collected.WorldPosition == new Vector2(5896, 924) && supplyFragment.GlobalPosition == collected.WorldPosition &&
                        collected.Radius == 18 && collected.EntryIds == supplyEntryIds && collected.ExitIds == supplyExitIds &&
                        collected.EntryCount == supplyBaseline.CollectedFragmentIds.Count && collected.ExitCount == collected.EntryCount + 1 &&
                        collected.EntryFeedback == supplyFragmentFeedback && collected.ExitFeedback == supplyFragmentFeedback + 1 &&
                        supplyFragment.FeedbackCount == collected.ExitFeedback && supplyFragment.IsCollected &&
                        supplyFragment.LastResult == Knight.Prologue.Collections.FragmentCollectionResult.Collected &&
                        collected.CollectionBodyEntries == 1 && collected.ReturnBodyEntries == 1 && collected.CollectedEvents == 1 &&
                        collected.SaveReplacements == 1 && collected.CollectionBodyPlayerId == playerId && collected.ReturnBodyPlayerId == playerId &&
                        collected.CollectionDiskHash.Length == 64 && collected.CollectionDiskHash.All(Uri.IsHexDigit) &&
                        collected.CollectionDiskHash != supply.SnapshotHash && !ReferenceEquals(flow.Save, supplyEntrySave),
                        "value-only receipt proves exact original fragment/node/resource, one collection and a separate non-consuming return entry");
                    string supplyExitDiscoveries = Task18Ids(supplyBaseline.Discoveries.Append(supplyRewardId));
                    Check(Task18SaveExact(supplyEntrySave, supplyBaseline, supplyEntryIds, supplyEntryDiscoveries) &&
                        Task18SaveExact(flow.Save, supplyBaseline, supplyExitIds, supplyExitDiscoveries) &&
                        Task18SaveExact(Task18RawSave(File.ReadAllBytes(flow.SavePath)), supplyBaseline, supplyExitIds, supplyExitDiscoveries) &&
                        Task18Ids(level.Progress.CollectedFragmentIds) == supplyExitIds &&
                        Task18Ids(level.Progress.Discoveries) == supplyExitDiscoveries &&
                        level.Progress.CollectionRuleVersion == supplyBaseline.CollectionRuleVersion &&
                        !level.Progress.LegacyCollectionQuotaExempt && supplyHud.CurrentModel.FragmentCount == collected.ExitCount &&
                        supplyHud.CurrentModel.FragmentRequired == 6 && !supplyHud.CurrentModel.CollectionQuotaExempt &&
                        retainedBytes.SequenceEqual(File.ReadAllBytes(templeCheckpointSnapshotPath)),
                        "caller independently verifies raw disk/live/progress/HUD sole fragment +1 and witnessed reward +1, preserving every other snapshot value");
                    hp = supply.ExitHp;
                    nextCast = supply.ExitNextCast - 1UL;
                }
                catch (Exception error) { supplyFailure = error; throw; }
                finally
                {
                    // Restore even on a detour exception, without waiting or reading components.
                    var restoreFailures = new List<Exception>();
                    void Restore(Action action) { try { action(); } catch (Exception error) { restoreFailures.Add(error); } }
                    Restore(() => swapApproachGuard(Guard));
                    Restore(() => swapPreObserverGuard(PreObserverSafety));
                    Restore(() => { if (GodotObject.IsInstanceValid(claw))
                        { claw.ClawFrameChanged += ObserveCast; clawSubscribed = true; } });
                    if (restoreFailures.Count != 0)
                    {
                        if (supplyFailure != null) restoreFailures.Insert(0, supplyFailure);
                        throw new AggregateException("Task18 normal supply scope restoration", restoreFailures);
                    }
                }
                Safety(); Guard();
            }
            phase = "arena-stage";
            await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 6160f, 100);
            await Settle(arenaFloor, arenaShape);
            Safety();
            Check(Supported(arenaFloor, arenaShape) && !arena.IsEncounterActive &&
                !bossTrigger.GetOverlappingBodies().Contains(player), "stages on full enabled ArenaFloor before actual trigger");
            Check(bodyShape.Shape is CapsuleShape2D && bossTriggerShape.Shape is RectangleShape2D,
                "requires actual capsule and rectangular trigger geometry");
            CapsuleShape2D stagedCapsule = (CapsuleShape2D)bodyShape.Shape;
            RectangleShape2D triggerRect = (RectangleShape2D)bossTriggerShape.Shape;
            float stagedRight = bodyShape.ToGlobal(new Vector2(stagedCapsule.Radius, 0f)).X;
            float triggerLeft = bossTriggerShape.ToGlobal(new Vector2(-triggerRect.Size.X / 2f, 0f)).X;
            Check(!bossTriggerShape.Disabled && bossTrigger.Monitoring &&
                stagedRight < triggerLeft,
                "measures a real capsule-to-enabled-trigger margin after neutral staging");
            Log("PRETRIGGER");
            GD.Print($"TASK10_TEMPLE_PRETRIGGER capsule_right={stagedRight} trigger_left={triggerLeft} " +
                $"margin={triggerLeft - stagedRight} actual_overlap=False boss_active=False neutral=True");
            bossTrigger.BodyEntered += OnBossBody; bossSubscribed = true;
            phase = "boss-approach";
            SendAction(InputActions.MoveLeft, false); SendAction(InputActions.MoveRight, true);
            int approachWaits = 0;
            while (approachWaits < 50 && (!arena.IsEncounterActive || !EntryDoorClear()) && player.GlobalPosition.X < 6260f)
            { await Tick(); approachWaits++; }
            SendAction(InputActions.MoveRight, false);
            Safety(); Check(bossBodySeen && arena.IsEncounterActive && EntryDoorClear(),
                "real ordinary walking toward6260 enters the exact Boss trigger and clears the live enabled EntryDoor by2px without contact within50 waits");
            phase = "boss-gates";
            for (int waited = 0; waited < 12 && !GatesVerified(); waited++) await Tick();
            Safety(); Check(GatesVerified(), "requires actual player overlap, active same Boss, full ArenaFloor, deferred enabled gates and whole-capsule EntryDoor clearance without contact/overlap within12 waits");
            phase = "activation"; Log("ACTIVATION");
        }
        catch (Exception error)
        {
            firstFailure = error; Log("FAILURE");
            SamplingLog("FAILURE", terminal: true);
            try { GD.Print($"TASK10_TEMPLE_ENTRY_FAILURE type={error.GetType().Name} " +
                $"message={error.Message.Replace('\r', ' ').Replace('\n', ' ')}"); } catch { }
            throw;
        }
        finally
        {
            Cleanup(() => { if (clawSubscribed && GodotObject.IsInstanceValid(claw)) claw.ClawFrameChanged -= ObserveCast; });
            Cleanup(() => { if (checkpointBodySubscribed && GodotObject.IsInstanceValid(checkpoint)) checkpoint.BodyEntered -= OnCheckpointBody; });
            Cleanup(() => { if (checkpointSignalSubscribed && GodotObject.IsInstanceValid(checkpoint)) checkpoint.CheckpointActivated -= OnCheckpointSignal; });
            Cleanup(() => { if (bossSubscribed && GodotObject.IsInstanceValid(bossTrigger)) bossTrigger.BodyEntered -= OnBossBody; });
            Cleanup(() => ReleaseAll(Live(player) ? player.GlobalPosition : Vector2.Zero));
            Cleanup(() => swapPreObserverGuard(previousPreObserverGuard));
            Cleanup(() => swapApproachGuard(previousGuard));
            if (cleanupFailure != null && firstFailure != null)
                try { GD.Print($"TASK10_TEMPLE_ENTRY_CLEANUP_GAP type={cleanupFailure.GetType().Name}"); } catch { }
        }
        if (cleanupFailure != null) throw cleanupFailure;
    }

    private static async Task DriveTask10BossPhaseOnePositional(SceneTree tree,
        PrologueLevelController level, SeamlessPrologueWorld world, CharacterBody2D player,
        RouteMonitor monitor, Action observe, Func<Action, Action> swapApproachGuard,
        Func<Action, Action> swapPreObserverGuard)
    {
        // Test-only continuation of the real route: positions are candidate goals, never
        // damage geometry or an alternative authority for the production actor timeline.
        bool Live(Node node) => node != null && GodotObject.IsInstanceValid(node) &&
            node.IsInsideTree() && !node.IsQueuedForDeletion();
        void Check(bool condition, string message) => TestAssert.True(condition,
            "Task10 Boss phase1 positional: " + message);
        Check(GodotObject.IsInstanceValid(tree) && Live(level) && Live(world) &&
            Live(player) && Live(monitor.Player), "requires live original route nodes");
        Check(world.TryGetMountedSector(PrologueSectorId.LostTemple, out PrologueSector temple) &&
            Live(temple), "requires actually mounted LostTemple");
        PrologueGameFlowController flow = level.GetNode<PrologueGameFlowController>("GameFlow");
        BossArenaController arena = temple.GetNode<BossArenaController>("Gameplay/BossArenaController");
        Check(Live(arena), "requires actual arena before reading its Boss");
        FallenBellkeeper boss = arena.CurrentBoss;
        Check(Live(boss), "requires actual spawned Boss");
        HealthComponent health = player.GetNode<HealthComponent>("Health");
        HealthComponent bossHealth = boss.GetNode<HealthComponent>("Health");
        Hurtbox bossHurtbox = boss.GetNode<Hurtbox>(boss.HurtboxPath);
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        PlayerCombat combat = player.GetNode<PlayerCombat>("Combat");
        PlayerActionModeController modes = player.GetNode<PlayerActionModeController>("ActionModes");
        PlayerEnergyController energy = player.GetNode<PlayerEnergyController>("Energy");
        PlayerShieldController shield = player.GetNode<PlayerShieldController>("Shield");
        MechanicalClawController claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
        StaticBody2D floor = temple.GetNode<StaticBody2D>("Gameplay/Collision/ArenaFloor");
        Check(Live(floor), "live actual ArenaFloor before collision lookup");
        CollisionShape2D floorShape = floor.GetNode<CollisionShape2D>("Collision");
        CollisionShape2D bodyShape = player.GetNode<CollisionShape2D>("BodyCollider");
        CollisionShape2D entryDoor = arena.GetNode<CollisionShape2D>(arena.EntryDoorCollisionPath);
        CollisionShape2D exitDoor = arena.GetNode<CollisionShape2D>(arena.ExitDoorCollisionPath);
        Node[] nodes = { level, world, temple, flow, arena, boss, player, monitor.Player,
            health, bossHealth, bossHurtbox, motor, input, combat, modes, energy, shield,
            claw, floor, floorShape, bodyShape, entryDoor, exitDoor };
        Check(nodes.All(Live), "requires live original components before baseline reads");
        Check(GodotObject.IsInstanceValid(combat.Tuning) && GodotObject.IsInstanceValid(motor.Tuning),
            "live actual combat/motion tuning before duration/braking reads");
        ulong playerId = player.GetInstanceId(), bossId = boss.GetInstanceId();
        int hp = health.CurrentHealth, requests = monitor.RecoveryRequested;
        int recoveries = monitor.RecoveryCompleted, jumps = motor.AcceptedJumpCount;
        int dashes = motor.AcceptedDashCount;
        ulong nextCast = claw.CurrentFrame.NextCastId;
        Check(hp > 0 && bossHealth.CurrentHealth == 12 && bossHealth.MaxHealth == 12 &&
            boss.CurrentFrame.State == FallenBellkeeperState.Intro,
            $"requires genuine positive entry HP and Boss12/12 Intro; playerHP={hp} " +
            $"BossHP={bossHealth.CurrentHealth}/{bossHealth.MaxHealth} state={boss.CurrentFrame.State}");
        Check(player.GlobalPosition.IsFinite() && boss.GlobalPosition.IsFinite(), "finite entry poses");
        int flank = player.GlobalPosition.X < boss.GlobalPosition.X ? -1 : 1;
        int inward = -flank, waits = 0, damageHits = 0, pairedHits = 0, accepted = 0;
        int damageEvents = 0, healEvents = 0, deathEvents = 0;
        int lastBossHp = 12, primarySamples = 0;
        ulong pendingId = 0, pendingSweep = 0, issuedSweep = 0, primaryIssueSequence = 0;
        ulong primarySampleSequence = 0, qIssueSequence = 0, qSampleSequence = 0;
        bool keyboardPhaseOne = KeyboardRouteInputDriver.Current != null;
        ulong keyboardAttackReady = 0UL;
        ulong pendingStartPhysics = 0, lastInwardSequence = 0, lastOutwardSequence = 0;
        bool pendingDamage = false, pendingConnect = false, pendingPaired = false;
        bool primaryIssued = false, primaryHeld = false, selecting = false;
        bool retreating = false, connectRetreatStarted = false, subscribed = false;
        bool scopeInstalled = false, preScopeInstalled = false;
        int commandedMove = 0;
        AttackPresentationFrame presentation = default;
        ulong publication = 0, completedPublication = 0;
        ulong loggedAttack = 0;
        AttackPhase loggedPhase = AttackPhase.None;
        bool loggedLock = false;
        ulong lockedSlamId = 0;
        Vector2 lockedSlamTarget = Vector2.Zero;
        string stage = "entry";
        Exception callbackFailure = null, firstFailure = null, cleanupFailure = null;
        Action previousGuard = null, previousPreObserverGuard = null;
        float attackSeconds = combat.Tuning.AttackStartupSeconds + combat.Tuning.AttackActiveSeconds +
            combat.Tuning.AttackRecoverySeconds;
        Check(float.IsFinite(attackSeconds) && attackSeconds > 0f && Engine.PhysicsTicksPerSecond > 0,
            "positive actual attack interval/physics rate");
        int attackInterval = (int)MathF.Ceiling(attackSeconds * Engine.PhysicsTicksPerSecond) + 4;

        Rect2 Bounds(CollisionShape2D shape)
        {
            Check(Live(shape) && GodotObject.IsInstanceValid(shape.Shape), "live bounds authority");
            Transform2D transform = shape.GlobalTransform;
            Check(transform.Origin.IsFinite() && transform.X.IsFinite() && transform.Y.IsFinite(),
                "finite transformed bounds");
            Rect2 local = shape.Shape.GetRect();
            Rect2 bounds = new(transform * local.Position, Vector2.Zero);
            foreach (Vector2 corner in new[] { new Vector2(local.End.X, local.Position.Y),
                local.End, new Vector2(local.Position.X, local.End.Y) }) bounds = bounds.Expand(transform * corner);
            Check(bounds.Position.IsFinite() && bounds.Size.IsFinite(), "finite world bounds");
            return bounds;
        }
        bool Supported()
        {
            if (!TryTask10CapsuleCorridor(player, floorShape, out _, out _, out _, out _) ||
                !player.IsOnFloor()) return false;
            bool contact = false;
            for (int index = 0; index < player.GetSlideCollisionCount(); index++)
            {
                KinematicCollision2D collision = player.GetSlideCollision(index);
                if (!GodotObject.IsInstanceValid(collision)) continue;
                GodotObject collider = collision.GetCollider();
                if (!GodotObject.IsInstanceValid(collider)) continue;
                Check(collider != entryDoor.GetParent() && collider != exitDoor.GetParent() && collider != boss,
                    "no closed-door or Boss slide contact");
                if (collider == floor && collision.GetNormal().Y < -.7f) contact = true;
            }
            return contact;
        }
        float Gap() => flank * (player.GlobalPosition.X - boss.GlobalPosition.X);
        bool CurrentPresentation()
        {
            AttackTimelineFrame raw = boss.CurrentFrame.AttackTimeline;
            AttackTimelineFrame actual = presentation.Timeline;
            return publication > 0 && completedPublication == publication &&
                actual.AttackId == raw.AttackId && actual.Kind == raw.Kind && actual.Phase == raw.Phase &&
                actual.PhaseRemainingSeconds == raw.PhaseRemainingSeconds;
        }
        float Clearance()
        {
            Check(CurrentPresentation(), "uses only completed current actor presentation");
            AttackShapeFrame shape = presentation.Shape;
            Check(shape.Origin.IsFinite() && shape.Extent.IsFinite() &&
                float.IsFinite(shape.RotationRadians), "finite actual attack geometry");
            if (presentation.Timeline.Kind == EnemyAttackKind.BossLeapSlam)
            {
                Check(shape.Kind == AttackShapeKind.Circle && shape.Extent.X > 0f,
                    "actual Slam circle authority");
                return Mathf.Abs(player.GlobalPosition.X - shape.Origin.X) - shape.Extent.X - 28f;
            }
            float left, right;
            if (presentation.Timeline.Kind == EnemyAttackKind.BossSweep)
            {
                Check(shape.Kind == AttackShapeKind.ConvexPolygon && shape.Points != null &&
                    shape.Points.Count >= 3 && shape.Points.All(point => point.IsFinite()),
                    "actual world-space Sweep polygon authority");
                left = shape.Points.Min(point => point.X); right = shape.Points.Max(point => point.X);
            }
            else
            {
                Check(presentation.Timeline.Kind == EnemyAttackKind.BossGroundWave &&
                    shape.Kind == AttackShapeKind.GroundBand && shape.Extent.X > 0f && shape.Extent.Y > 0f,
                    "actual Wave band authority");
                float half = Mathf.Abs(Mathf.Cos(shape.RotationRadians)) * shape.Extent.X +
                    Mathf.Abs(Mathf.Sin(shape.RotationRadians)) * shape.Extent.Y;
                left = shape.Origin.X - half; right = shape.Origin.X + half;
            }
            return flank < 0 ? left - player.GlobalPosition.X - 28f : player.GlobalPosition.X - right - 28f;
        }
        void Safety()
        {
            Check(GodotObject.IsInstanceValid(tree) && nodes.All(Live), "native lifetime before reads/waits");
            Check(new[] { floorShape, bodyShape, entryDoor, exitDoor }.All(shape =>
                GodotObject.IsInstanceValid(shape.Shape)), "live collision resources");
            Check(GodotObject.IsInstanceValid(motor.Tuning), "live braking resource before policy reads");
            Check(player.GetInstanceId() == playerId && monitor.Player.GetInstanceId() == playerId &&
                boss.GetInstanceId() == bossId && arena.CurrentBoss == boss && arena.IsEncounterActive &&
                flow.State == PrologueGameFlowState.Playing && !tree.Paused,
                "same player/Boss and active Playing arena");
            Check(health.CurrentHealth == hp && monitor.RecoveryRequested == requests &&
                monitor.RecoveryCompleted == recoveries && motor.AcceptedJumpCount == jumps &&
                motor.AcceptedDashCount == dashes && damageEvents == 0 && healEvents == 0 && deathEvents == 0,
                "no player damage/heal/death/recovery/jump/dash");
            Check(player.GlobalPosition.IsFinite() && player.Velocity.IsFinite() &&
                boss.GlobalPosition.IsFinite() && boss.Velocity.IsFinite() && Gap() > 60f &&
                float.IsFinite(energy.EnergyRatio) && float.IsFinite(energy.HeatRatio),
                "finite same-flank poses/resources; no crossing Boss");
            Check(!floorShape.Disabled && !bodyShape.Disabled && !entryDoor.Disabled && !exitDoor.Disabled &&
                bodyShape.Shape is CapsuleShape2D capsule && Mathf.Abs(capsule.Radius *
                    bodyShape.GlobalTransform.X.Length() - 20f) < .01f && Supported(),
                "actual full ArenaFloor/contact, enabled gates and 20px player halfwidth");
            Rect2 body = Bounds(bodyShape), entry = Bounds(entryDoor), exit = Bounds(exitDoor);
            Check(body.Position.X >= entry.End.X + 2f && body.End.X <= exit.Position.X - 2f &&
                !body.Intersects(entry) && !body.Intersects(exit), "whole-capsule closed-door containment");
            Check(!input.CurrentFrame.JumpPressed && !input.CurrentFrame.JumpHeld &&
                !input.CurrentFrame.DashPressed && !input.CurrentFrame.ShieldHeld &&
                !input.CurrentFrame.GrappleModePressed && !input.CurrentFrame.ThreadPressed &&
                !input.CurrentFrame.ThreadHeld && !input.CurrentFrame.ThreadReleased &&
                (!input.CurrentFrame.AttackPressed || keyboardPhaseOne && primaryIssued &&
                    input.CurrentFrameSequence > primaryIssueSequence &&
                    (primaryHeld || input.CurrentFrameSequence == primarySampleSequence)) &&
                (!keyboardPhaseOne || !input.CurrentFrame.ClawPressed && !input.CurrentFrame.InteractPressed) &&
                input.CurrentFrame.Aim.Y == 0f && !shield.IsActive &&
                claw.CurrentFrame.State == MechanicalClawState.Idle && claw.CurrentFrame.CastId == 0 &&
                claw.CurrentFrame.NextCastId == nextCast && claw.CurrentTarget == null && claw.ResidencyTarget == null,
                "no shield/legacy attack/vertical aim/E/claw cast or target");
            Check(bossHealth.MaxHealth == 12 && bossHealth.CurrentHealth == lastBossHp &&
                lastBossHp == 12 - damageHits && damageHits <= 5 && accepted <= 5 && pairedHits <= damageHits &&
                !boss.CurrentFrame.ArmorClosed && boss.CurrentFrame.State is FallenBellkeeperState.Intro or
                    FallenBellkeeperState.PhaseOne or FallenBellkeeperState.Transition,
                "exact Boss12→7 trajectory, at most five accepted strikes, no phase2");
            if (callbackFailure != null) throw new InvalidOperationException(
                "Task10 Boss phase1 callback failure", callbackFailure);
        }
        void Log(string boundary, string details = "")
        {
            // Deliberately no diagnostic native reads until their lifetime is validated.
            Check(nodes.All(Live), "live nodes before compact record");
            AttackTimelineFrame timeline = presentation.Timeline;
            string clearance = CurrentPresentation() && timeline.Phase != AttackPhase.None
                ? Clearance().ToString("R") : "unavailable";
            GD.Print($"TASK10_BOSS_PHASE1 boundary={boundary} stage={stage} physics={Engine.GetPhysicsFrames()} " +
                $"input_sequence={input.CurrentFrameSequence} waits={waits}/1800 player={playerId} boss={bossId} " +
                $"pose={player.GlobalPosition} velocity={player.Velocity} boss_pose={boss.GlobalPosition} " +
                $"full_floor={Supported()} HP={health.CurrentHealth}/{hp} energy={energy.EnergyRatio:R} " +
                $"heat={energy.HeatRatio:R} overheated={energy.IsOverheated} bossHP={bossHealth.CurrentHealth} " +
                $"state={boss.CurrentFrame.State} attack={timeline.AttackId}/{timeline.Kind}/{timeline.Phase} " +
                $"remaining={timeline.PhaseRemainingSeconds:R} locked={timeline.HasLockedTarget} " +
                $"target={timeline.LockedWorldTarget} clearance={clearance} shield={shield.IsActive} " +
                $"mode={modes.CurrentMode} slot={modes.ActiveSlot} claw={claw.CurrentFrame.State}/{nextCast} " +
                $"jumps={motor.AcceptedJumpCount}/{jumps} dash={motor.AcceptedDashCount}/{dashes} " +
                $"recovery={monitor.RecoveryRequested}/{monitor.RecoveryCompleted} " +
                $"accepted={accepted} damage_hits={damageHits} paired={pairedHits} {details}");
        }
        void Callback(Action action)
        {
            try { Check(nodes.All(Live), "live callback actors"); action(); }
            catch (Exception error) { callbackFailure ??= error; }
        }
        void Pair()
        {
            if (!pendingDamage || !pendingConnect || pendingPaired) return;
            pendingPaired = true; pairedHits++;
            Log("PAIR", $"player_attack={pendingId} sweep={pendingSweep} delta=1");
        }
        bool PendingInterval() => pendingId != 0 && Engine.GetPhysicsFrames() >= pendingStartPhysics &&
            Engine.GetPhysicsFrames() - pendingStartPhysics <= (ulong)attackInterval && combat.IsAttacking;
        void OnStarted(ulong id, int direction) => Callback(() =>
        {
            Check(primaryIssued && primaryHeld && accepted < 5 &&
                (pendingId == 0 || pendingPaired) && id != 0 && id > pendingId,
                "unique actual accepted attack token; no extra/missed prior strike");
            Check(CurrentPresentation() && presentation.Timeline.AttackId == issuedSweep &&
                presentation.Timeline.Kind == EnemyAttackKind.BossSweep &&
                presentation.Timeline.Phase == AttackPhase.Recovery &&
                presentation.Timeline.PhaseRemainingSeconds >= .22f && Gap() >= 90f && Gap() <= 100f &&
                Mathf.Abs(player.GlobalPosition.Y - boss.GlobalPosition.Y) <= 28f && Supported() &&
                direction == (int)AttackDirection.Horizontal && combat.LastAttackFacing == inward &&
                (input.CurrentFrame.MoveAxis == inward && input.CurrentFrame.Aim == Vector2.Right * inward ||
                    input.CurrentFrame.MoveAxis == 0f && input.CurrentFrame.Aim == Vector2.Zero &&
                    lastInwardSequence > lastOutwardSequence) &&
                !shield.IsActive && modes.CurrentMode == PlayerActionMode.Attack && modes.ActiveSlot == 1,
                "actual SweepRecovery start ≥.22s, gap90..100, real horizontal inward facing/full support");
            pendingId = id; pendingSweep = issuedSweep;
            pendingStartPhysics = Engine.GetPhysicsFrames();
            pendingDamage = pendingConnect = pendingPaired = false; accepted++;
            connectRetreatStarted = false;
            Log("ATTACK_STARTED", $"player_attack={id} direction={direction} facing={combat.LastAttackFacing}");
        });
        void OnConnected(Hurtbox hurtbox) => Callback(() =>
        {
            Check(Live(hurtbox) && hurtbox == bossHurtbox && PendingInterval() && !pendingConnect,
                "exact BossHurtbox connects once within latest actual accepted attack interval");
            pendingConnect = true; Log("ATTACK_CONNECTED", $"player_attack={pendingId} sweep={pendingSweep}"); Pair();
        });
        void OnBossDamaged(int remaining, Vector2 impulse) => Callback(() =>
        {
            Check(PendingInterval() && !pendingDamage && lastBossHp - remaining == 1 &&
                remaining == 11 - damageHits && damageHits < 5 && impulse.IsFinite(),
                "one actual HP decrement attributed to latest accepted token, not callback count/click");
            lastBossHp = remaining; damageHits++; pendingDamage = true;
            Log("HP_DELTA", $"player_attack={pendingId} sweep={pendingSweep} delta=1 remaining={remaining}"); Pair();
        });
        void OnPlayerDamaged(int remaining, Vector2 impulse) => Callback(() => { damageEvents++; });
        void OnPlayerHealed(int restored, int remaining) => Callback(() => { healEvents++; });
        void OnPlayerDied() => Callback(() => { deathEvents++; });
        void OnBossHealed(int restored, int remaining) => Callback(() =>
            Check(false, $"unexpected Boss heal {restored}/{remaining}"));
        void OnBossDied() => Callback(() => Check(false, "unexpected Boss death"));
        void OnPresentation(AttackPresentationFrame frame) => Callback(() =>
        { presentation = frame.Timeline.Phase == AttackPhase.None ? frame : frame.Validate(); publication++; });
        void OnBossFrame(FallenBellkeeperFrame frame, int facing) => Callback(() =>
        { completedPublication = publication; });
        void Guard()
        {
            previousGuard?.Invoke(); Safety();
            if (input.CurrentFrame.MoveAxis == inward) lastInwardSequence = input.CurrentFrameSequence;
            if (input.CurrentFrame.MoveAxis == flank) lastOutwardSequence = input.CurrentFrameSequence;
            if (selecting && input.CurrentFrame.AttackModePressed && input.CurrentFrameSequence > qIssueSequence)
                qSampleSequence = input.CurrentFrameSequence;
            bool attackEdge = keyboardPhaseOne ? input.CurrentFrame.AttackPressed : input.CurrentFrame.PrimaryPressed;
            if (attackEdge && primarySampleSequence != input.CurrentFrameSequence)
            {
                Check(primaryIssued && input.CurrentFrameSequence > primaryIssueSequence &&
                    (keyboardPhaseOne ? keyboardAttackReady > qIssueSequence && primaryIssueSequence >= keyboardAttackReady &&
                        input.CurrentFrame.KeyboardActions && !input.CurrentFrame.PrimaryPressed &&
                        !input.CurrentFrame.AttackModePressed :
                        qSampleSequence > qIssueSequence && primaryIssueSequence > qSampleSequence),
                    "fresh typed J or legacy LMB is separately sampled after actual readiness");
                primarySampleSequence = input.CurrentFrameSequence; primarySamples++;
                Check(primarySamples == accepted && primarySamples <= 5, "one fresh edge per accepted strike");
            }
            AttackTimelineFrame raw = boss.CurrentFrame.AttackTimeline;
            if (raw.Phase == AttackPhase.None) return;
            Check(CurrentPresentation(), "no stale/default shape evidence for live attack");
            AttackTimelineFrame actual = presentation.Timeline;
            bool hazardous = actual.Phase is AttackPhase.Telegraph or AttackPhase.Active;
            float clearance = Clearance();
            if (actual.Kind == EnemyAttackKind.BossLeapSlam && actual.HasLockedTarget)
            {
                if (lockedSlamId != actual.AttackId)
                { lockedSlamId = actual.AttackId; lockedSlamTarget = actual.LockedWorldTarget; }
                Check(actual.LockedWorldTarget == lockedSlamTarget &&
                    presentation.Shape.Origin.DistanceTo(lockedSlamTarget) <= .01f,
                    "same enriched Slam target/actual circle origin remains locked");
            }
            if (hazardous && actual.Kind is EnemyAttackKind.BossSweep or EnemyAttackKind.BossGroundWave)
                Check(clearance >= 0f, "outside actual Sweep/Wave X geometry expanded by20+8 in Telegraph/Active");
            if (actual.Kind == EnemyAttackKind.BossLeapSlam && actual.Phase == AttackPhase.Active)
                Check(actual.HasLockedTarget && clearance >= 0f,
                    "enriched locked Slam circle clear by Active and through Active");
            // Unlocked Slam follows the live player; never demand clearance from its preview.
            if (loggedAttack != actual.AttackId || loggedPhase != actual.Phase || loggedLock != actual.HasLockedTarget)
            {
                loggedAttack = actual.AttackId; loggedPhase = actual.Phase; loggedLock = actual.HasLockedTarget;
                Log("BOSS_BOUNDARY");
            }
        }
        void PreObserverSafety() { Safety(); previousPreObserverGuard?.Invoke(); }
        async Task Tick()
        {
            Safety(); Check(waits < 1800, "shared1800 wait budget exhausted"); waits++;
            await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
            Safety(); observe(); // Combined original observer exactly once, invoking this scoped Guard.
        }
        void Move(int direction)
        {
            if (commandedMove == direction) return;
            SendAction(InputActions.MoveLeft, direction < 0);
            SendAction(InputActions.MoveRight, direction > 0); commandedMove = direction;
        }
        void Primary(bool pressed)
        {
            if (primaryHeld == pressed) return;
            SendMouse(MouseButton.Left, pressed, player, boss.GlobalPosition); primaryHeld = pressed;
        }
        void Approach(float target)
        {
            float difference = Gap() - target;
            float toward = -flank * player.Velocity.X * MathF.Sign(difference);
            Check(float.IsFinite(motor.Tuning.GroundDeceleration) && motor.Tuning.GroundDeceleration > 0f,
                "positive actual ordinary braking tuning");
            float brake = toward > 0f ? toward * toward / (2f * motor.Tuning.GroundDeceleration) + toward / 30f : 0f;
            Move(Mathf.Abs(difference) > Mathf.Max(2f, brake) ? (difference > 0f ? inward : flank) : 0);
        }
        void Cleanup(Action action)
        { try { action(); } catch (Exception error) { cleanupFailure ??= error; } }
        // Passive measurement only: none of these values feeds the existing policy.
        string[] measureNames = { "request_time_ge24", "request_gap_le103_5", "request_gap_gt100", "full_inward_speed",
            "vertical_le28", "inward_horizontal_axis", "inward_latest", "can_begin", "can_afford",
            "shield_off", "primary_notheld", "primary_notpressed", "combat_idle",
            "not_retreating", "unissued_sweep" };
        string[] measureBranchNames = { "late-retreat", "approach", "issue", "neutral", "outerexcluded" };
        int[] measureTrue = new int[15], measureBranches = new int[5];
        string[] measureFalse = new string[15];
        ulong measureId = 0;
        int measureWindows = 0, measureOmitted = 0, measureOmittedEvaluations = 0;
        int measureEvaluations = 0, measureFaults = 0, measureRecords = 0;
        bool measureEnabled = false;
        float measureMinimumGap = float.PositiveInfinity, measureMaximumTime = float.NegativeInfinity;
        string measureEntry = null, measureLast = null, measureMinimum = null;
        string measureLate = null, measureStationary = null, measureFirstFault = null;
        string MeasureSnapshot(AttackTimelineFrame timeline, out bool[] gates, out float gap)
        {
            Check(nodes.All(Live), "live nodes before passive strike-gate reads");
            Check(GodotObject.IsInstanceValid(motor.Tuning), "live full-speed resource before passive request-gate read");
            Vector2 pose = player.GlobalPosition, bossPose = boss.GlobalPosition;
            float vx = player.Velocity.X, axis = input.CurrentFrame.MoveAxis;
            gap = flank * (pose.X - bossPose.X);
            gates = new[] { timeline.PhaseRemainingSeconds >= .24f, gap <= 103.5f, gap > 100f,
                vx == inward * motor.Tuning.MaxRunSpeed, Mathf.Abs(pose.Y - bossPose.Y) <= 28f,
                axis == inward && input.CurrentFrame.Aim == Vector2.Right * inward,
                lastInwardSequence > lastOutwardSequence, modes.CanBeginAttack, modes.CanAffordAttack,
                !shield.IsActive, !input.CurrentFrame.PrimaryHeld, !input.CurrentFrame.PrimaryPressed,
                !combat.IsAttacking, !retreating, issuedSweep != timeline.AttackId };
            return $"physics={Engine.GetPhysicsFrames()} input_sequence={input.CurrentFrameSequence} " +
                $"remaining={timeline.PhaseRemainingSeconds:R} pose={pose} boss_pose={bossPose} " +
                $"vX={vx:R} axis={axis:R} aim={input.CurrentFrame.Aim} fullspeed={motor.Tuning.MaxRunSpeed:R} " +
                $"gap={gap:R} vertical_gap={Mathf.Abs(pose.Y - bossPose.Y):R} " +
                $"last_inward={lastInwardSequence} last_outward={lastOutwardSequence} " +
                $"mode={modes.CurrentMode} slot={modes.ActiveSlot} energy={energy.EnergyRatio:R} " +
                $"heat={energy.HeatRatio:R} bossHP={bossHealth.CurrentHealth} accepted={accepted} paired={pairedHits}";
        }
        void MeasureClose(string reason, AttackTimelineFrame? exitTimeline = null)
        {
            if (measureId == 0) return;
            try
            {
                if (!measureEnabled) return;
                string exit = measureLast;
                if (exitTimeline.HasValue)
                {
                    try { exit = MeasureSnapshot(exitTimeline.Value, out _, out _) + " branch=window-close"; }
                    catch (Exception error) { measureFaults++; measureFirstFault ??= error.GetType().Name; }
                }
                // First-false snapshots are deduplicated, not discarded or inferred from a branch.
                var falseFacts = new Dictionary<string, List<string>>();
                for (int index = 0; index < measureNames.Length; index++)
                {
                    string facts = measureFalse[index] ?? "absent";
                    if (!falseFacts.TryGetValue(facts, out List<string> names))
                        falseFacts[facts] = names = new List<string>();
                    names.Add(measureNames[index]);
                }
                string trueCounts = string.Join(',', measureNames.Select((name, index) => $"{name}:{measureTrue[index]}"));
                string branches = string.Join(',', measureBranchNames.Select((name, index) => $"{name}:{measureBranches[index]}"));
                string firstFalse = string.Join(';', falseFacts.Select(pair => $"{string.Join(',', pair.Value)}=>({pair.Key})"));
                GD.Print($"TASK10_BOSS_PHASE1_GATE boundary=ENTRY sweep={measureId} window={measureWindows}/5 {measureEntry}"); measureRecords++;
                GD.Print($"TASK10_BOSS_PHASE1_GATE boundary=FIRST_LATE sweep={measureId} facts={measureLate ?? "absent"}"); measureRecords++;
                GD.Print($"TASK10_BOSS_PHASE1_GATE boundary=MINIMUM sweep={measureId} {measureMinimum} " +
                    $"stationary_gap90_100_speed_le2={measureStationary ?? "absent"} " +
                    $"maximum_time_all_non_time_gates_true={(float.IsFinite(measureMaximumTime) ? measureMaximumTime.ToString("R") : "absent")}"); measureRecords++;
                GD.Print($"TASK10_BOSS_PHASE1_GATE boundary=END sweep={measureId} reason={reason} " +
                    $"evaluations={measureEvaluations} last_evaluation=({measureLast}) exit=({exit}) " +
                    $"true_counts=[{trueCounts}] branches=[{branches}] first_false=[{firstFalse}]"); measureRecords++;
            }
            catch (Exception error) { measureFaults++; measureFirstFault ??= error.GetType().Name; }
            finally { measureId = 0; measureEnabled = false; }
        }
        void MeasureBefore(AttackTimelineFrame timeline)
        {
            try
            {
                if (timeline.Kind != EnemyAttackKind.BossSweep || timeline.Phase != AttackPhase.Recovery)
                { MeasureClose("phase-exit", timeline); return; }
                if (measureId != timeline.AttackId)
                {
                    MeasureClose("attack-id-exit", timeline);
                    measureId = timeline.AttackId; measureWindows++;
                    measureEnabled = measureWindows <= 5;
                    if (!measureEnabled) { measureOmitted++; measureOmittedEvaluations++; return; }
                    measureTrue = new int[15]; measureBranches = new int[5]; measureFalse = new string[15];
                    measureEvaluations = 0; measureMinimumGap = float.PositiveInfinity;
                    measureMaximumTime = float.NegativeInfinity;
                    measureEntry = measureLast = measureMinimum = measureLate = measureStationary = null;
                }
                if (!measureEnabled) { measureOmittedEvaluations++; return; }
                measureEvaluations++;
                measureLast = MeasureSnapshot(timeline, out bool[] gates, out float gap);
                measureEntry ??= measureLast;
                for (int index = 0; index < gates.Length; index++)
                {
                    if (gates[index]) measureTrue[index]++;
                    else measureFalse[index] ??= measureLast;
                }
                if (gap <= measureMinimumGap) { measureMinimumGap = gap; measureMinimum = measureLast; }
                if (gap >= 90f && gap <= 100f && Mathf.Abs(player.Velocity.X) <= 2f)
                    measureStationary ??= measureLast; // Optional raw fact, not a request predicate.
                if (gates.Skip(1).All(value => value))
                    measureMaximumTime = Mathf.Max(measureMaximumTime, timeline.PhaseRemainingSeconds);
            }
            catch (Exception error) { measureFaults++; measureFirstFault ??= error.GetType().Name; }
        }
        void MeasureBranch(int branch)
        {
            try
            {
                if (!measureEnabled || measureId == 0 || measureLast == null) return;
                measureBranches[branch]++;
                string before = measureLast;
                measureLast += " branch=" + measureBranchNames[branch];
                if (measureEntry == before) measureEntry = measureLast;
                if (measureMinimum == before) measureMinimum = measureLast;
                if (measureStationary == before) measureStationary = measureLast;
                for (int index = 0; index < measureFalse.Length; index++)
                    if (measureFalse[index] == before) measureFalse[index] = measureLast;
                if (branch == 0) measureLate ??= measureLast;
            }
            catch (Exception error) { measureFaults++; measureFirstFault ??= error.GetType().Name; }
        }
        void MeasureTerminal(string reason)
        {
            try
            {
                if (nodes.All(Live)) MeasureClose(reason, boss.CurrentFrame.AttackTimeline);
                else MeasureClose(reason);
                GD.Print($"TASK10_BOSS_PHASE1_GATE boundary=TERMINAL reason={reason} windows={measureWindows} " +
                    $"retained={Math.Min(measureWindows, 5)} omitted_windows={measureOmitted} " +
                    $"omitted_evaluations={measureOmittedEvaluations} window_records={measureRecords}/20 " +
                    $"diagnostic_faults={measureFaults} first_fault={measureFirstFault ?? "none"} diagnostic_only=True");
            }
            catch (Exception error) { measureFaults++; measureFirstFault ??= error.GetType().Name; }
        }
        try
        {
            previousGuard = swapApproachGuard(Guard); scopeInstalled = true;
            previousPreObserverGuard = swapPreObserverGuard(PreObserverSafety); preScopeInstalled = true;
            subscribed = true;
            boss.AttackFrameChanged += OnPresentation; boss.FrameChanged += OnBossFrame;
            combat.AttackStarted += OnStarted; combat.AttackConnected += OnConnected;
            bossHealth.Damaged += OnBossDamaged; bossHealth.Healed += OnBossHealed; bossHealth.Died += OnBossDied;
            health.Damaged += OnPlayerDamaged; health.Healed += OnPlayerHealed; health.Died += OnPlayerDied;
            Safety(); Log("ENTRY");
            // Previous helper has released inputs, but its final sampled D/velocity may remain.
            SendAction(InputActions.MoveLeft, false); SendAction(InputActions.MoveRight, false);
            stage = "initial-approach";
            while (waits < 180 && (Gap() < 200f || Gap() > 210f || Mathf.Abs(player.Velocity.X) > 2f))
            { Approach(205f); await Tick(); }
            Move(0); Check(Gap() >= 200f && Gap() <= 210f && Mathf.Abs(player.Velocity.X) <= 2f,
                "natural initial205 approach/settle within180 shared waits");
            selecting = true; stage = "sample-Q"; qIssueSequence = input.CurrentFrameSequence;
            SendAction(InputActions.SelectAttackMode, true);
            int qWaits = 0;
            if (keyboardPhaseOne)
            {
                await Tick(); qWaits++;
                keyboardAttackReady = input.CurrentFrameSequence;
                Check(keyboardAttackReady > qIssueSequence && input.CurrentFrame.KeyboardActions &&
                    modes.CanBeginAttack && modes.ActiveSlot == 1 && !shield.IsActive &&
                    !Input.IsActionPressed(InputActions.Attack) && !Input.IsActionPressed(InputActions.Claw) &&
                    !input.CurrentFrame.AttackModePressed && !input.CurrentFrame.InteractPressed,
                    "independent J readiness without Q selection or a premature strike");
            }
            else while (qWaits < 8 && (qSampleSequence <= qIssueSequence ||
                input.CurrentFrameSequence <= qSampleSequence || modes.CurrentMode != PlayerActionMode.Attack))
            { await Tick(); qWaits++; }
            SendAction(InputActions.SelectAttackMode, false); selecting = false;
            Check(keyboardPhaseOne ? keyboardAttackReady > qIssueSequence :
                qSampleSequence > qIssueSequence && input.CurrentFrameSequence > qSampleSequence &&
                modes.CurrentMode == PlayerActionMode.Attack && modes.ActiveSlot == 1 && !shield.IsActive,
                "actual independent J readiness or separate legacy Q before any strike");
            Log(keyboardPhaseOne ? "KEYBOARD_ATTACK_READY" : "Q_READY",
                $"keyboard_ready={keyboardAttackReady} Q_issue={qIssueSequence} Q_sample={qSampleSequence}");
            stage = "phase1";
            while (damageHits < 5)
            {
                Safety();
                if (boss.CurrentFrame.State == FallenBellkeeperState.Intro) { Move(0); await Tick(); continue; }
                Check(CurrentPresentation(), "phase1 decisions require completed actual actor publication");
                AttackTimelineFrame timeline = presentation.Timeline;
                if (pendingId != 0 && !pendingPaired &&
                    Engine.GetPhysicsFrames() - pendingStartPhysics > (ulong)attackInterval)
                    Check(false, "accepted attack missed exact paired one-damage connection in its bounded interval");
                if (pendingConnect && !connectRetreatStarted)
                {
                    Check(timeline.Kind != EnemyAttackKind.BossLeapSlam || !timeline.HasLockedTarget,
                        "actual connect initiates retreat before enriched Slam lock");
                    retreating = true; connectRetreatStarted = true;
                    Log("RETREAT_AFTER_CONNECT", $"player_attack={pendingId} sweep={pendingSweep}");
                }
                // A buffered edge may need several physics observations. Preserve the
                // admitted neutral/inward facing until that edge is actually sampled.
                if (primaryHeld && primarySampleSequence <= primaryIssueSequence)
                { Move(0); await Tick(); continue; }
                if (primaryIssued && primaryHeld && primarySampleSequence > primaryIssueSequence)
                { Primary(false); Move(0); }
                if (pendingId != 0 && !pendingConnect)
                { Move(0); await Tick(); continue; }
                MeasureBefore(timeline);
                if (timeline.Kind == EnemyAttackKind.BossSweep && timeline.Phase == AttackPhase.Recovery &&
                    issuedSweep != timeline.AttackId && !combat.IsAttacking && !retreating)
                {
                    if (timeline.PhaseRemainingSeconds < .24f) { MeasureBranch(0); Move(flank); } // Missed request window: skip this cycle.
                    else if (Gap() > 103.5f) { MeasureBranch(1); Move(inward); }
                    else if (Gap() > 100f && Gap() <= 103.5f &&
                        player.Velocity.X == inward * motor.Tuning.MaxRunSpeed &&
                        Mathf.Abs(player.GlobalPosition.Y - boss.GlobalPosition.Y) <= 28f &&
                        input.CurrentFrame.MoveAxis == inward && input.CurrentFrame.Aim == Vector2.Right * inward &&
                        lastInwardSequence > lastOutwardSequence &&
                        modes.CanBeginAttack && modes.CanAffordAttack &&
                        !shield.IsActive && !input.CurrentFrame.PrimaryHeld && !input.CurrentFrame.PrimaryPressed &&
                        (!keyboardPhaseOne || !Input.IsActionPressed(InputActions.Attack) && !input.CurrentFrame.AttackPressed))
                    {
                        MeasureBranch(2);
                        issuedSweep = timeline.AttackId; primaryIssued = true;
                        primaryIssueSequence = input.CurrentFrameSequence;
                        Move(0); // Request only; actual OnStarted still requires gap90..100/remaining≥.22.
                        Primary(true); Log("PRIMARY_ISSUED", $"sweep={issuedSweep} sequence={primaryIssueSequence}");
                    }
                    else { MeasureBranch(3); Move(0); }
                }
                else if (timeline.Kind == EnemyAttackKind.BossLeapSlam)
                {
                    MeasureBranch(4);
                    // Retreat began after actual connect, before half-telegraph lock. Obtain
                    // clearance after the enriched lock; only Active is an enforced Slam hazard.
                    if (timeline.Phase == AttackPhase.Recovery) Approach(305f);
                    else if (!timeline.HasLockedTarget || Clearance() < 8f || Gap() < 285f) Move(flank);
                    else Move(0);
                }
                else if (timeline.Kind == EnemyAttackKind.BossGroundWave)
                {
                    MeasureBranch(4);
                    if (timeline.Phase == AttackPhase.Recovery)
                    { retreating = false; Approach(205f); }
                    else if (Clearance() < 8f || Gap() < 285f) Move(flank);
                    else if (Gap() > 315f) Check(false, "Wave candidate285..315 exceeded; no cross-arena fallback");
                    else Move(0);
                }
                else if (retreating) { MeasureBranch(4); Approach(305f); }
                else { MeasureBranch(4); Approach(205f); }
                await Tick();
            }
            // No sixth strike: stop immediately at the fifth actual decrement, then observe
            // the already accepted token's connection and the production model Transition.
            stage = "transition"; Primary(false); Move(0);
            while (boss.CurrentFrame.State != FallenBellkeeperState.Transition || pairedHits != 5 ||
                Mathf.Abs(player.Velocity.X) > 2f || input.CurrentFrame.PrimaryHeld ||
                keyboardPhaseOne && Input.IsActionPressed(InputActions.Attack) || input.CurrentFrame.MoveAxis != 0f)
                await Tick();
            Safety(); Check(accepted == 5 && primarySamples == 5 && damageHits == 5 && pairedHits == 5 &&
                bossHealth.CurrentHealth == 7, "five unique accepted/connected one-damage Sweep hits, actual HP7 Transition");
            Log("TRANSITION"); Log("SUMMARY", "phase1_local_only=True phase2_unrun=True");
            MeasureTerminal("phase1-end");
        }
        catch (Exception error)
        {
            firstFailure = error;
            MeasureTerminal("failure");
            try { Log("FAIL", $"type={error.GetType().Name} message={error.Message.Replace('\r', ' ').Replace('\n', ' ')}"); }
            catch { /* Preserve first failure even if diagnostic nodes were invalidated. */ }
            throw;
        }
        finally
        {
            if (subscribed)
            {
                Cleanup(() => { if (GodotObject.IsInstanceValid(boss)) { boss.AttackFrameChanged -= OnPresentation; boss.FrameChanged -= OnBossFrame; } });
                Cleanup(() => { if (GodotObject.IsInstanceValid(combat)) { combat.AttackStarted -= OnStarted; combat.AttackConnected -= OnConnected; } });
                Cleanup(() => { if (GodotObject.IsInstanceValid(bossHealth)) { bossHealth.Damaged -= OnBossDamaged; bossHealth.Healed -= OnBossHealed; bossHealth.Died -= OnBossDied; } });
                Cleanup(() => { if (GodotObject.IsInstanceValid(health)) { health.Damaged -= OnPlayerDamaged; health.Healed -= OnPlayerHealed; health.Died -= OnPlayerDied; } });
            }
            Cleanup(() => SendAction(InputActions.MoveLeft, false));
            Cleanup(() => SendAction(InputActions.MoveRight, false));
            Cleanup(() => SendAction(InputActions.SelectAttackMode, false));
            Cleanup(() => SendMouse(MouseButton.Left, false, Live(player) ? player : null,
                Live(boss) ? boss.GlobalPosition : Vector2.Zero));
            Cleanup(() => { if (preScopeInstalled) swapPreObserverGuard(previousPreObserverGuard); });
            Cleanup(() => { if (scopeInstalled) swapApproachGuard(previousGuard); });
            if (firstFailure != null && cleanupFailure != null)
                try { GD.Print($"TASK10_BOSS_PHASE1 cleanup_gap={cleanupFailure.GetType().Name}"); } catch { }
        }
        if (cleanupFailure != null) throw cleanupFailure;
    }

    private sealed record Task10BossOpeningReceipt(ulong PlayerId, ulong BossId, ulong ChainId,
        int PlayerHp, int RecoveryRequests, int Recoveries, int Jumps, int Dashes, int BossHp,
        ulong PlayerAttackId, ulong AttackPhysics, ulong HammerId, ulong ExposureEntryPhysics,
        ulong NextCastId, int Applications, ulong TerminalPhysics, int Waits, string NativeSignature,
        int PhysicsTicks, float PhysicsDelta, Knight.Config.BossSettings BossSettings,
        PlayerCombatSettings CombatSettings, PlayerMotionSettings MotionSettings);

    private enum Task10BossOpeningMode { Nonfatal, Fatal }
    private sealed record Task10BossFatalDamage(ulong PlayerAttackId, ulong AttackPhysics,
        ulong DamagePhysics, ulong ExposureEntryPhysics, float ExposureElapsed, float RemainingLowerBound,
        Vector2 Impulse);
    private sealed record Task10BossDeathReceipt(Task10BossOpeningReceipt Opening,
        Task10BossFatalDamage Damage, int DiedEvents, int ArenaEvents, ulong DefeatedPhysics,
        int DrainWaits, int DeathTailWaits, int SettleWaits);
    private sealed record Task10BossOpeningOutcome(Task10BossOpeningReceipt Opening, Task10BossDeathReceipt Death);

    private static Transform2D Task10BossUniform(CollisionShape2D shape, Action native, Action<bool, string> check)
    {
        native(); Transform2D t = shape.GlobalTransform;
        float x = t.X.Length(), y = t.Y.Length();
        check(t.Origin.IsFinite() && t.X.IsFinite() && t.Y.IsFinite() && float.IsFinite(x) && x > 0f &&
            Mathf.Abs(x - y) <= .0001f && Mathf.Abs(t.X.Dot(t.Y)) <= .0001f * x * y &&
            t.X.Cross(t.Y) > 0f, "finite positive uniform orthogonal collider transform");
        return t;
    }

    private static Rect2 Task10BossBounds(CollisionShape2D shape, Func<CollisionShape2D, Transform2D> uniform,
        Action<bool, string> check)
    {
        Transform2D t = uniform(shape);
        if (shape.Shape is CapsuleShape2D capsule)
        {
            float radius = capsule.Radius * t.X.Length(), half = capsule.Height * .5f * t.Y.Length();
            check(float.IsFinite(radius) && float.IsFinite(half) && radius > 0f && half >= radius, "valid capsule dimensions");
            Vector2 extent = new(radius + Mathf.Abs(Mathf.Sin(t.Rotation)) * (half - radius),
                radius + Mathf.Abs(Mathf.Cos(t.Rotation)) * (half - radius));
            return new Rect2(t.Origin - extent, extent * 2f);
        }
        check(shape.Shape is RectangleShape2D, "only measured capsule/rectangle bounds supported");
        Rect2 local = shape.Shape.GetRect(), bounds = new(t * local.Position, Vector2.Zero);
        foreach (Vector2 corner in new[] { new Vector2(local.End.X, local.Position.Y), local.End,
            new Vector2(local.Position.X, local.End.Y) }) bounds = bounds.Expand(t * corner);
        check(bounds.Position.IsFinite() && bounds.Size.IsFinite(), "finite actual rectangle bounds");
        return bounds;
    }

    private static bool Task10BossSupported(CharacterBody2D player, StaticBody2D floor, FallenBellkeeper boss,
        CollisionShape2D bodyShape, CollisionShape2D floorShape, CollisionShape2D entryDoor, CollisionShape2D exitDoor,
        Action native, Func<CollisionShape2D, Rect2> bounds, Action<bool, string> check)
    {
        native(); Rect2 body = bounds(bodyShape), ground = bounds(floorShape);
        if (!player.IsOnFloor() || body.Position.X < ground.Position.X || body.End.X > ground.End.X) return false;
        bool upward = false;
        for (int i = 0; i < player.GetSlideCollisionCount(); i++)
        {
            KinematicCollision2D contact = player.GetSlideCollision(i);
            if (!GodotObject.IsInstanceValid(contact)) continue;
            GodotObject collider = contact.GetCollider();
            if (!GodotObject.IsInstanceValid(collider)) continue;
            check(collider != boss && collider != entryDoor.GetParent() && collider != exitDoor.GetParent(), "no Boss/door slide contact");
            if (collider == floor && contact.GetNormal().Y < -.7f) upward = true;
        }
        return upward;
    }

    private static async Task<Task10BossOpeningReceipt> DriveTask10BossFirstExposure(SceneTree tree,
        PrologueLevelController level, SeamlessPrologueWorld world, CharacterBody2D player,
        RouteMonitor monitor, Action observe, Func<Action, Action> swapApproachGuard,
        Func<Action, Action> swapPreObserverGuard, int expectedEntryBossHp = 7,
        Task10BossOpeningReceipt priorReceipt = null)
    {
        Task10BossOpeningOutcome outcome = await DriveTask10BossOpeningCore(tree, level, world, player, monitor,
            observe, swapApproachGuard, swapPreObserverGuard, Task10BossOpeningMode.Nonfatal, expectedEntryBossHp, priorReceipt);
        return outcome.Opening;
    }

    private static async Task<Task10BossDeathReceipt> DriveTask10BossFatalOpening(SceneTree tree,
        PrologueLevelController level, SeamlessPrologueWorld world, CharacterBody2D player,
        RouteMonitor monitor, Action observe, Func<Action, Action> swapApproachGuard,
        Func<Action, Action> swapPreObserverGuard, Task10BossOpeningReceipt priorReceipt)
    {
        TestAssert.True(priorReceipt != null && priorReceipt.BossHp == 1 && priorReceipt.Applications == 6,
            "Task10 Boss fatal opening: only qualified living HP1/six applications");
        Task10BossOpeningOutcome outcome = await DriveTask10BossOpeningCore(tree, level, world, player, monitor,
            observe, swapApproachGuard, swapPreObserverGuard, Task10BossOpeningMode.Fatal, 1, priorReceipt);
        TestAssert.True(outcome.Death != null, "Task10 Boss fatal opening: genuine death receipt after cleanup");
        return outcome.Death;
    }

    private static async Task<Task10BossOpeningOutcome> DriveTask10BossOpeningCore(SceneTree tree,
        PrologueLevelController level, SeamlessPrologueWorld world, CharacterBody2D player,
        RouteMonitor monitor, Action observe, Func<Action, Action> swapApproachGuard,
        Func<Action, Action> swapPreObserverGuard, Task10BossOpeningMode mode, int expectedEntryBossHp,
        Task10BossOpeningReceipt priorReceipt)
    {
        bool fatal = mode == Task10BossOpeningMode.Fatal;
        bool keyboardOpening = KeyboardRouteInputDriver.Current != null;
        // One exact runner-owned Root child lookup, only for the final HP1 opening.
        Task11PointerAdmissionTrace pointerTrace = null;
        if (fatal && expectedEntryBossHp == 1)
        {
            try { pointerTrace = tree.Root.GetNodeOrNull<Task11PointerAdmissionTrace>(Task11PointerAdmissionTrace.RootChildName); }
            catch { /* Missing observer remains unarmed/incomplete; never replace route validation. */ }
        }
        bool Live(Node node) => node != null && GodotObject.IsInstanceValid(node) &&
            node.IsInsideTree() && !node.IsQueuedForDeletion();
        void Check(bool condition, string message) => TestAssert.True(condition, "Task10 Boss first exposure: " + message);
        Check(GodotObject.IsInstanceValid(tree) && Live(level) && Live(world) && Live(player) &&
            Live(monitor.Player), "native-valid original route entry");
        Check(world.TryGetMountedSector(PrologueSectorId.LostTemple, out PrologueSector temple) && Live(temple),
            "actual mounted LostTemple");
        BossArenaController arena = temple.GetNode<BossArenaController>("Gameplay/BossArenaController");
        Check(Live(arena) && Live(arena.CurrentBoss), "actual arena/Boss before component reads");
        FallenBellkeeper boss = arena.CurrentBoss;
        PrologueGameFlowController flow = level.GetNode<PrologueGameFlowController>("GameFlow");
        HealthComponent health = player.GetNode<HealthComponent>("Health"), bossHealth = boss.GetNode<HealthComponent>("Health");
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        PlayerCombat combat = player.GetNode<PlayerCombat>("Combat");
