        void Callback(Action action) { try { Native(); action(); } catch (Exception error) { callbackFailure ??= error; } }
        void AdmissionDiagnostic(string boundary, Action capture)
        {
            if (admissionDiagnosticRecords >= 8 || !admissionDiagnosticKeys.Add(boundary + "/" + stage)) return;
            admissionDiagnosticRecords++;
            try { Native(); capture(); }
            catch (Exception error)
            {
                admissionDiagnosticFaults++;
                try { GD.Print($"TASK10_BOSS_PHASE2_ADMISSION boundary={boundary} diagnostic_gap={error.GetType().Name} " +
                    $"records={admissionDiagnosticRecords}/8 diagnostic_faults={admissionDiagnosticFaults}"); }
                catch { /* Passive diagnostics never replace the original admission assertion. */ }
            }
        }
        (bool admitted, Vector2 point, Vector2 local, Vector2 screen, float radius, Transform2D transform) PointerAdmission()
        {
            Native(); Transform2D transform = Uniform(chainShape);
            Check(chainShape.Shape is CircleShape2D, "actual chain circle for sampled pointer containment");
            float radius = ((CircleShape2D)chainShape.Shape).Radius;
            float determinant = transform.Determinant();
            Check(float.IsFinite(radius) && radius > 0f && float.IsFinite(determinant) && determinant > 0f,
                "finite positive chain radius/invertible collider transform");
            Vector2 point = input.CurrentFrame.MouseWorld;
            Vector2 local = transform.AffineInverse() * point;
            Vector2 screen = player.GetViewport().GetCanvasTransform() * point;
            float localDistance = local.Length();
            bool admitted = point.IsFinite() && local.IsFinite() && screen.IsFinite() && float.IsFinite(localDistance) &&
                localDistance < radius && player.GetViewport().GetVisibleRect().HasPoint(screen) &&
                !chainShape.Disabled && chain.IsAvailable;
            return (admitted, point, local, screen, radius, transform);
        }
        void CaptureAimAdmission(MechanicalClawFrame frame, GrappleSurface2D target)
        {
            if (frame.State != MechanicalClawState.Aim) return;
            if (keyboardOpening)
            {
                AdmissionDiagnostic("KEYBOARD_AIM_PRECHECK", () =>
                    GD.Print($"TASK10_BOSS_PHASE2_KEYBOARD_AIM stage={stage} physics={Engine.GetPhysicsFrames()} " +
                        $"sequence={input.CurrentFrameSequence} ready={keyboardCastReady} cast_issue={castIssue} " +
                        $"K={input.CurrentFrame.ClawPressed} J={input.CurrentFrame.AttackPressed} " +
                        $"direction={input.KeyboardAimDirection} axis={input.CurrentFrame.Aim} " +
                        $"target={(Live(target) ? target.GetInstanceId() : 0UL)}/{chainId} " +
                        $"current={(Live(claw.CurrentTarget) ? claw.CurrentTarget.GetInstanceId() : 0UL)} " +
                        $"anchor={frame.AnchorPoint} legacy_primary={input.CurrentFrame.PrimaryPressed}"));
                return;
            }
            AdmissionDiagnostic("AIM_PRECHECK", () =>
            {
                PlayerInputFrame sampled = input.CurrentFrame;
                ulong sequence = input.CurrentFrameSequence;
                Vector2 anchor = chain.WorldAnchor;
                float aimError = sampled.MouseWorld.DistanceTo(anchor);
                bool fresh = sequence > castIssue, modeReady = modes.CanBeginGrapple;
                bool combatInactive = !combat.IsAttacking, mouseFinite = sampled.MouseWorld.IsFinite();
                var pointer = PointerAdmission();
                bool targetLive = Live(target), currentTargetLive = Live(claw.CurrentTarget);
                bool selectedChain = targetLive && currentTargetLive && target == chain && claw.CurrentTarget == chain &&
                    target.GetInstanceId() == chainId && claw.CurrentTarget.GetInstanceId() == chainId &&
                    frame.AnchorPoint.IsFinite() && frame.AnchorPoint.DistanceTo(anchor) <= .01f &&
                    frame.EffectiveVisibility && claw.CurrentFrame == frame;
                bool precedingConjuncts = fresh && sampled.PrimaryPressed && modeReady && combatInactive && pointer.admitted;
                GD.Print($"TASK10_BOSS_PHASE2_ADMISSION boundary=AIM_PRECHECK stage={stage} physics={Engine.GetPhysicsFrames()} " +
                    $"input_sequence={sequence} e_issue={eIssue} e_sample={eSample} cast_issue={castIssue} cast_sample={castSample} " +
                    $"cast_issued={castIssued} E_fresh={eSample > eIssue} cast_after_E={castIssue > eSample} input_after_cast_issue={fresh} " +
                    $"frame={frame.State}/{frame.CastId}/{frame.NextCastId} primary_pressed={sampled.PrimaryPressed} primary_held={sampled.PrimaryHeld} " +
                    $"mode={modes.CurrentMode} can_begin_grapple={modeReady} shield_held={sampled.ShieldHeld} combat_is_attacking={!combatInactive} " +
                    $"sampled_mouse_world={sampled.MouseWorld} live_chain_anchor={anchor} mouse_finite={mouseFinite} anchor_finite={anchor.IsFinite()} " +
                    $"cursor_anchor_error_diagnostic={aimError:R} pointer_gate={pointer.admitted} pointer_local={pointer.local} pointer_screen={pointer.screen} " +
                    $"circle_radius={pointer.radius:R} collider_transform={pointer.transform} pointer_local_finite={pointer.local.IsFinite()} " +
                    $"pointer_screen_finite={pointer.screen.IsFinite()} pointer_inside={pointer.local.Length() < pointer.radius} " +
                    $"pointer_onscreen={player.GetViewport().GetVisibleRect().HasPoint(pointer.screen)} target_collision_disabled={chainShape.Disabled} chain_available={chain.IsAvailable} " +
                    $"event_target_live={targetLive} event_target_id={(targetLive ? target.GetInstanceId() : 0UL)}/{chainId} " +
                    $"current_target_live={currentTargetLive} current_target_id={(currentTargetLive ? claw.CurrentTarget.GetInstanceId() : 0UL)}/{chainId} " +
                    $"event_target_exact={target == chain} current_target_exact={claw.CurrentTarget == chain} frame_anchor={frame.AnchorPoint} " +
                    $"frame_anchor_finite={frame.AnchorPoint.IsFinite()} canonical_anchor_error={frame.AnchorPoint.DistanceTo(anchor):R} " +
                    $"effective_visibility={frame.EffectiveVisibility} current_frame_exact={claw.CurrentFrame == frame} selected_chain={selectedChain} " +
                    $"preceding_outer_conjuncts={precedingConjuncts} " +
                    $"chain_gate={(precedingConjuncts ? "PENDING_EXISTING_EVALUATION" : "NOT_EVALUATED_SHORT_CIRCUIT")} " +
                    $"records={admissionDiagnosticRecords}/8 diagnostic_faults={admissionDiagnosticFaults}");
            });
        }
        void CaptureChainAdmission(int samplingReserve, bool available, MechanicalClawTargetResolution resolution,
            Vector2 anchor, Vector2 screen, float distance)
        {
            AdmissionDiagnostic("CHAIN_GATE_" + samplingReserve, () =>
            {
                bool surfaceLive = Live(resolution.Surface);
                float remaining = presentation.Timeline.PhaseRemainingSeconds;
                float required = distance / settings.ShuttleSpeed + samplingReserve / (float)ticks + .10f;
                GD.Print($"TASK10_BOSS_PHASE2_ADMISSION boundary=CHAIN_GATE_{samplingReserve} stage={stage} physics={Engine.GetPhysicsFrames()} " +
                    $"input_sequence={input.CurrentFrameSequence} chain_gate_evaluated=True available_result={available} time_gate={remaining > required} " +
                    $"keyboard={keyboardOpening} raw_aim={input.CurrentFrame.Aim} direction={input.KeyboardAimDirection} " +
                    $"move={input.CurrentFrame.MoveAxis} velocity={player.Velocity} gap={Gap():R} " +
                    $"cast_stance={ChainStationary()} melee_stance={Stationary()} " +
                    $"remaining={remaining:R} required={required:R} distance={distance:R} target_collision_disabled={chainShape.Disabled} " +
                    $"chain_available={chain.IsAvailable} legacy_kind={chain.Kind.IsLegacyInteraction()} surface_live={surfaceLive} " +
                    $"exact_surface={resolution.Surface == chain} surface_id={(surfaceLive ? resolution.Surface.GetInstanceId() : 0UL)} " +
                    $"snapshot_exists={resolution.Snapshot.Exists} runtime_id={resolution.Snapshot.RuntimeId}/{chainId} " +
