            bool castEdge = keyboardOpening ? input.CurrentFrame.ClawPressed : input.CurrentFrame.PrimaryPressed && !strikeIssued;
            bool strikeEdge = keyboardOpening ? input.CurrentFrame.AttackPressed : input.CurrentFrame.PrimaryPressed && strikeIssued;
            if ((castEdge || strikeEdge) && input.CurrentFrameSequence != castSample && input.CurrentFrameSequence != strikeSample)
            {
