                Check(HammerClearance() >= 2f, "measured enriched locked Telegraph clearance before first Active");
            if (t.Phase == AttackPhase.Active)
            { activeSeen = true; Check(positioned && ChainStationary() && t.HasLockedTarget && HammerClearance() >= 2f,
                "ready before first Active and measured ≥2px clearance throughout Active"); }
