                Check(keyboardStrikeReady > qIssue && input.CurrentFrame.KeyboardActions &&
                    !input.CurrentFrame.AttackPressed && !input.CurrentFrame.ClawPressed &&
                    !Input.IsActionPressed(InputActions.Attack) && !Input.IsActionPressed(InputActions.Claw),
                    "fresh keyboard attack readiness, no synthetic Q mode event");
            }
            else
            {
                int qWaits = 0;
                while (qWaits < 8 && (qSample <= qIssue || input.CurrentFrameSequence <= qSample || modes.CurrentMode != PlayerActionMode.Attack))
                { await Tick(); qWaits++; }
            }
            SendAction(InputActions.SelectAttackMode, false);
            Check((keyboardOpening ? keyboardStrikeReady > qIssue && input.CurrentFrameSequence >= keyboardStrikeReady
                    : qSamples == 1 && qSample > qIssue && input.CurrentFrameSequence > qSample) && modes.CanBeginAttack &&
                modes.CanAffordAttack && modes.ActiveSlot == 1 && Stationary() && Idle() && !shield.IsActive &&
                bossHealth.CurrentHealth == expectedEntryBossHp && ExposureLowerBound() >= .22f && ExposureLowerBound() > 8f / ticks + startup + 4f / ticks,
                "actual Attack mode/CanBeginAttack and remaining lower-bound reserve before only melee LMB");
            strikeIssued = true; strikeIssue = input.CurrentFrameSequence; stage = "sample-strike-LMB";
            SendMouse(MouseButton.Left, true, player, boss.GlobalPosition); int strikeWaits = 0;
            while (strikeWaits < 8 && strikeSample <= strikeIssue) { await Tick(); strikeWaits++; }
            SendMouse(MouseButton.Left, false, player, boss.GlobalPosition);
            Check(strikeSample > strikeIssue && accepted == 1 && primaries == 2, "one unique real accepted strike within8");
            stage = "one-hit";
            while (!paired)
            { Check(Engine.GetPhysicsFrames() - attackPhysics <= (ulong)attackInterval, "one accepted attack bounded hit interval"); await Tick(); }
            Release(); Safety(); Check(Stationary() && bossHealth.CurrentHealth == expectedEntryBossHp - 1 && accepted == 1 && damaged == 1 &&
                connected == 1 && adapter.ApplicationCount == applications + 1 && Idle(), $"same-player supported final HP{expectedEntryBossHp - 1}, one exposure/one attributed hit");
            if (fatal)
            {
                Check(fatalDamage != null && diedEvents == 1 && arenaEvents == 1 && applications == 6 &&
                    adapter.ApplicationCount == 7 && firstHammer != priorReceipt.HammerId && attackId != priorReceipt.PlayerAttackId,
                    "seventh one application/hit and actual unique death/arena signals");
                stage = "fatal-defeat-doors";
                while (defeatedPhysics == 0 || !entryDoor.Disabled || !exitDoor.Disabled) await FatalTailTick(false);
                Safety(); Check(boss.CurrentFrame.State == FallenBellkeeperState.Defeated && bossHealth.CurrentHealth == 0 &&
                    !arena.IsEncounterActive && !boss.CurrentFrame.AttackActive && entryDoor.Disabled && exitDoor.Disabled &&
                    defeatedPhysics >= fatalDamage.DamagePhysics && deathTailWaits <= 8,
                    "actual Defeated publication plus both deferred doors within8, no completion yet");
                Log("FATAL_DEFEAT_DOORS", $"damage_physics={fatalDamage.DamagePhysics} defeated_physics={defeatedPhysics} " +
                    $"Died={diedEvents} arena_defeat={arenaEvents} tail_waits={deathTailWaits}/8");
                stage = "fatal-natural-attack-settle";
                while (combat.IsAttacking) await FatalTailTick(true);
                Safety(); Check(!combat.IsAttacking && Idle() && Stationary() &&
                    level.GetNode<PrologueCompletionController>("Completion").CompletionCount == 0,
                    "final accepted attack naturally idle within60, no completion before physical exit");
                Log("FATAL_SUMMARY", $"drain_waits={fatalDrainWaits}/180 opening_waits={waits}/600 " +
                    $"death_tail_waits={deathTailWaits}/8 settle_waits={finalSettleWaits}/60 " +
                    $"total_pre_exit_waits={fatalDrainWaits + waits + deathTailWaits + finalSettleWaits}/848 physical_exit_unrun=True");
            }
            else Log("SUMMARY", "one_exposure_local_only=True full_Boss_unrun=True");
            receipt = new(playerId, bossId, chainId, hp, requests, recoveries, jumps, dashes, bossHealth.CurrentHealth,
                attackId, attackPhysics, firstHammer, exposureEntryPhysics, claw.CurrentFrame.NextCastId, adapter.ApplicationCount,
                Engine.GetPhysicsFrames(), waits, nativeSignature, ticks, stepDelta, bossSettings, combatSettings, motor.Tuning.ToMotionSettings());
            if (fatal) deathReceipt = new(receipt, fatalDamage, diedEvents, arenaEvents, defeatedPhysics,
                fatalDrainWaits, deathTailWaits, finalSettleWaits);
        }
        catch (Exception error)
        {
            firstFailure = error;
            try { Log("FAIL", $"type={error.GetType().Name} message={error.Message.Replace('\r', ' ').Replace('\n', ' ')}"); }
            catch (Exception diagnosticError)
            { try { GD.Print($"TASK10_BOSS_PHASE2 boundary=FAIL diagnostic_gap={diagnosticError.GetType().Name} type={error.GetType().Name} " +
                $"message={error.Message.Replace('\r', ' ').Replace('\n', ' ')}"); } catch { /* Preserve first failure without native reads. */ } }
            throw;
        }
        finally
        {
            if (subscribed)
            {
                Cleanup(() => { if (GodotObject.IsInstanceValid(boss)) { boss.AttackFrameChanged -= OnPresentation; boss.FrameChanged -= OnBossFrame; } });
                Cleanup(() => { if (GodotObject.IsInstanceValid(claw)) claw.ClawFrameChanged -= OnClaw; });
                Cleanup(() => { if (GodotObject.IsInstanceValid(combat)) { combat.AttackStarted -= OnStarted; combat.AttackConnected -= OnConnected; } });
            }
            if (subscribed || fatalEarlySubscribed)
            {
                Cleanup(() => { if (GodotObject.IsInstanceValid(bossHealth)) { bossHealth.Damaged -= OnBossDamaged; bossHealth.Healed -= OnBossHealed; bossHealth.Died -= OnBossDied; } });
                Cleanup(() => { if (GodotObject.IsInstanceValid(health)) { health.Damaged -= OnPlayerDamaged; health.Healed -= OnPlayerHealed; health.Died -= OnPlayerDied; } });
            }
            Cleanup(() => { if (arenaSubscribed && GodotObject.IsInstanceValid(arena)) arena.EncounterDefeated -= OnArenaDefeated; });
            pointerTrace?.Freeze("opening_core_finally_before_Release");
            Cleanup(Release); Cleanup(() => { if (preInstalled) swapPreObserverGuard(previousPre); });
            Cleanup(() => { if (scopeInstalled) swapApproachGuard(previousGuard); });
            if (firstFailure != null && cleanupFailure != null) try { GD.Print($"TASK10_BOSS_PHASE2 cleanup_gap={cleanupFailure.GetType().Name}"); } catch { }
        }
        if (cleanupFailure != null) throw cleanupFailure;
        return new(receipt, deathReceipt);
    }

    private sealed record Task10BossArmoredReceipt(ulong PublicationPhysics, ulong LastPhysics,
        int CapturedWait, int CompletedWait, int Waits, FallenBellkeeperFrame Frame);

    private static async Task<Task10BossArmoredReceipt> DrainTask10BossOldOpening(SceneTree tree,
        FallenBellkeeper boss, HealthComponent bossHealth, PlayerCombat combat, CharacterBody2D player,
        PlayerInputReader input, MechanicalClawController claw, LegacyThreadInteractionAdapter adapter,
        Task10BossOpeningReceipt current, Action Native, Action FightSafety, Func<bool> Idle,
        Action Release, Action<Action> Callback, Action<string, string> Log, Action<bool, string> Check,
        Action observe, Func<Action, Action> swapApproachGuard, Func<Action, Action> swapPreObserverGuard,
        Func<bool> canWait, Action<int> accountWait, string logPrefix)
    {
        bool armed = false, oldAttackIdle = false, drainSubscribed = false, drainGuardInstalled = false, drainPreInstalled = false;
        ulong lastPhysics = 0, armedPhysics = 0;
        bool drainWaitPending = false;
        int completedDrainWaits = 0, armedDrainWaits = 0;
        Action previousDrainGuard = null, previousDrainPre = null;
        Exception drainFailure = null, drainCleanupFailure = null;
        int drainWaits = 0;
        void DrainSafety()
        {
            FightSafety();
            Check(bossHealth.CurrentHealth == current.BossHp && adapter.ApplicationCount == current.Applications &&
                claw.CurrentFrame.NextCastId == current.NextCastId && Idle(), "no extra cast/application/hit during old-opening drain");
            Check(player.Velocity.Length() <= 2f && boss.GlobalPosition.X - player.GlobalPosition.X >= 80f &&
                boss.GlobalPosition.X - player.GlobalPosition.X <= 90f, "stationary original supported left80..90 drain");
            Check(!input.CurrentFrame.PrimaryPressed && !input.CurrentFrame.GrappleModePressed && !input.CurrentFrame.AttackModePressed,
                "no new primary/mode edge during drain");
            Check(boss.CurrentFrame.State == (armed ? FallenBellkeeperState.PhaseTwoArmored : FallenBellkeeperState.Exposed) &&
                boss.CurrentFrame.ArmorClosed == armed && !boss.CurrentFrame.AttackActive && !boss.CurrentFrame.ChainTargetActive,
                "only old Exposed→first fresh PhaseTwoArmored, no reentry/missed window");
            if (oldAttackIdle) Check(!combat.IsAttacking, "old accepted attack stays naturally idle");
        }
        void OnStarted(ulong id, int direction) => Callback(() => Check(false, "new AttackStarted during drain"));
        void OnConnected(Hurtbox target) => Callback(() => Check(false, "new AttackConnected during drain, including old Active tail"));
        void OnDamaged(int remaining, Vector2 impulse) => Callback(() => Check(false, "additional Boss damage during drain"));
        void OnBossFrame(FallenBellkeeperFrame frame, int facing) => Callback(() =>
        {
            FightSafety(); ulong physics = Engine.GetPhysicsFrames();
            Check(lastPhysics == 0 || physics == lastPhysics + 1, "one monotonic actual drain publication per physics"); lastPhysics = physics;
            Check(frame == boss.CurrentFrame && physics > current.ExposureEntryPhysics, "actual old exposure publication continuity");
            if (frame.State == FallenBellkeeperState.Exposed)
                Check(!armed && !frame.EnteredState, "no old Exposed reentry");
            else
            {
                Check(!armed && frame.State == FallenBellkeeperState.PhaseTwoArmored && frame.EnteredState && oldAttackIdle,
                    "first actual Exposed exit to Armored after natural attack idle");
                Check(drainWaitPending && drainWaits > 0, "first Armored publication during an issued pending drain wait");
                armedDrainWaits = drainWaits;
                armed = true; armedPhysics = physics; Log("OLD_EXPOSED_EXIT", $"actual_exit_physics={armedPhysics}");
            }
        });
        void DrainGuard() { previousDrainGuard?.Invoke(); DrainSafety(); }
        void DrainPreGuard() { DrainSafety(); previousDrainPre?.Invoke(); }
        async Task Tick()
        {
            Check(!drainWaitPending, "only one pending drain wait");
            DrainSafety(); Check(drainWaits < 180 && canWait(), "180 total drain includes natural60, shared3900 exhausted");
            drainWaits++; accountWait(drainWaits);
            drainWaitPending = true;
            await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
            drainWaitPending = false; completedDrainWaits = drainWaits;
            // Boss may just have published Armored; callback records that witness before these reads.
            DrainSafety(); observe();
        }
        void DrainCleanup(Action action) { try { action(); } catch (Exception error) { drainCleanupFailure ??= error; } }
        try
        {
            // Old receipt attributes the possibly Active remainder; public API does not expose its phase/token.
            drainSubscribed = true; boss.FrameChanged += OnBossFrame; bossHealth.Damaged += OnDamaged;
            combat.AttackStarted += OnStarted; combat.AttackConnected += OnConnected;
            previousDrainGuard = swapApproachGuard(DrainGuard); drainGuardInstalled = true;
            previousDrainPre = swapPreObserverGuard(DrainPreGuard); drainPreInstalled = true;
            DrainSafety(); Release(); Log("REPEAT_ENTRY", "");
            while (combat.IsAttacking)
            { Check(drainWaits < 60, "receipt-attributed attack must become naturally idle within60"); await Tick(); }
            oldAttackIdle = true; DrainSafety(); Log("OLD_ATTACK_IDLE", $"idle_physics={Engine.GetPhysicsFrames()} allowance=60_inside180");
            while (!armed) await Tick();
            DrainSafety(); Check(!combat.IsAttacking && input.CurrentFrame.MoveAxis == 0f && !input.CurrentFrame.PrimaryHeld &&
                armedPhysics != 0 && armedPhysics == lastPhysics && boss.CurrentFrame.EnteredState && !drainWaitPending &&
                armedDrainWaits > 0 && armedDrainWaits == completedDrainWaits && completedDrainWaits == drainWaits,
                "first fresh Armored witness with no unobserved handoff wait");
            Log("FIRST_ARMORED_HANDOFF", $"publication_physics={armedPhysics} continuation_physics={Engine.GetPhysicsFrames()} " +
                $"captured_wait={armedDrainWaits} completed_wait={completedDrainWaits} current_wait={drainWaits}");
        }
        catch (Exception error) { drainFailure = error; throw; }
        finally
        {
            if (drainSubscribed)
            {
                DrainCleanup(() => { if (GodotObject.IsInstanceValid(boss)) boss.FrameChanged -= OnBossFrame; });
                DrainCleanup(() => { if (GodotObject.IsInstanceValid(bossHealth)) bossHealth.Damaged -= OnDamaged; });
                DrainCleanup(() => { if (GodotObject.IsInstanceValid(combat)) { combat.AttackStarted -= OnStarted; combat.AttackConnected -= OnConnected; } });
            }
            DrainCleanup(() => { if (drainPreInstalled) swapPreObserverGuard(previousDrainPre); });
            DrainCleanup(() => { if (drainGuardInstalled) swapApproachGuard(previousDrainGuard); });
            if (drainFailure != null && drainCleanupFailure != null)
                try { GD.Print($"{logPrefix} drain_cleanup_gap={drainCleanupFailure.GetType().Name}"); } catch { }
        }
        if (drainCleanupFailure != null) throw drainCleanupFailure;
        Native(); // Successful cleanup precedes immutable witness reads; no intervening wait.
        return new(armedPhysics, lastPhysics, armedDrainWaits, completedDrainWaits, drainWaits, boss.CurrentFrame);
    }

    private static async Task<Task10BossOpeningReceipt> DriveTask10BossNonfatalRepeats(SceneTree tree,
        PrologueLevelController level, SeamlessPrologueWorld world, CharacterBody2D player,
        RouteMonitor monitor, Action observe, Func<Action, Action> swapApproachGuard,
        Func<Action, Action> swapPreObserverGuard, Task10BossOpeningReceipt firstReceipt)
    {
        bool Live(Node node) => node != null && GodotObject.IsInstanceValid(node) &&
            node.IsInsideTree() && !node.IsQueuedForDeletion();
        void Check(bool condition, string message) => TestAssert.True(condition, "Task10 Boss nonfatal repeats: " + message);
        Check(GodotObject.IsInstanceValid(tree) && Live(level) && Live(world) && Live(player) && Live(monitor.Player) &&
            firstReceipt != null, "native-valid original receipt entry");
        Check(world.TryGetMountedSector(PrologueSectorId.LostTemple, out PrologueSector temple) && Live(temple), "actual LostTemple");
        BossArenaController arena = temple.GetNode<BossArenaController>("Gameplay/BossArenaController");
        Check(Live(arena) && Live(arena.CurrentBoss), "actual arena/Boss before component reads");
        FallenBellkeeper boss = arena.CurrentBoss;
        PrologueGameFlowController flow = level.GetNode<PrologueGameFlowController>("GameFlow");
        HealthComponent health = player.GetNode<HealthComponent>("Health"), bossHealth = boss.GetNode<HealthComponent>("Health");
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        PlayerCombat combat = player.GetNode<PlayerCombat>("Combat");
        PlayerActionModeController modes = player.GetNode<PlayerActionModeController>("ActionModes");
        PlayerEnergyController energy = player.GetNode<PlayerEnergyController>("Energy");
        PlayerShieldController shield = player.GetNode<PlayerShieldController>("Shield");
        MechanicalClawController claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
        StaticBody2D floor = temple.GetNode<StaticBody2D>("Gameplay/Collision/ArenaFloor");
        Hurtbox playerHurtbox = player.GetNode<Hurtbox>("Hurtbox"), bossHurtbox = boss.GetNode<Hurtbox>(boss.HurtboxPath);
        Hitbox hammerHitbox = boss.GetNode<Hitbox>(boss.AttackHitboxPath);
        ThreadTarget2D chain = boss.GetNode<ThreadTarget2D>(boss.ChainTargetPath);
        Check(new Node[] { floor, playerHurtbox, bossHurtbox, hammerHitbox, chain }.All(Live), "live original geometry owners");
        CollisionShape2D floorShape = floor.GetNode<CollisionShape2D>("Collision");
        CollisionShape2D bodyShape = player.GetNode<CollisionShape2D>("BodyCollider");
        CollisionShape2D hurtShape = playerHurtbox.GetNode<CollisionShape2D>("HurtboxCollider");
        CollisionShape2D bossHurtShape = bossHurtbox.GetNode<CollisionShape2D>("HurtboxCollider");
        CollisionShape2D hammerShape = hammerHitbox.GetNode<CollisionShape2D>("AttackCollider");
        CollisionShape2D chainShape = chain.GetNode<CollisionShape2D>("TargetCollision/Collision");
        CollisionShape2D entryDoor = arena.GetNode<CollisionShape2D>(arena.EntryDoorCollisionPath);
        CollisionShape2D exitDoor = arena.GetNode<CollisionShape2D>(arena.ExitDoorCollisionPath);
        LegacyThreadInteractionAdapter adapter = chain.GetNode<LegacyThreadInteractionAdapter>("LegacyThreadInteractionAdapter");
        Node[] nodes = { level, world, temple, arena, boss, flow, player, monitor.Player, health, bossHealth,
            motor, input, combat, modes, energy, shield, claw, floor, playerHurtbox, bossHurtbox, hammerHitbox,
            chain, adapter, floorShape, bodyShape, hurtShape, bossHurtShape, hammerShape, chainShape, entryDoor, exitDoor };
        CollisionShape2D[] shapes = { floorShape, bodyShape, hurtShape, bossHurtShape, hammerShape, chainShape, entryDoor, exitDoor };
        void Native()
        {
            Check(GodotObject.IsInstanceValid(tree) && nodes.All(Live), "native lifetime before callback/guard/reads");
            Check(shapes.All(shape => GodotObject.IsInstanceValid(shape.Shape)) && GodotObject.IsInstanceValid(motor.Tuning) &&
                GodotObject.IsInstanceValid(combat.Tuning) && GodotObject.IsInstanceValid(boss.Tuning), "native collision/tuning resources");
        }
        Native();
        Task10BossOpeningReceipt current = firstReceipt;
        bool keyboardOpeningInProgress = false;
        int cycle = 0, drainWaits = 0, totalWaits = 0;
        ulong entryPhysics = Engine.GetPhysicsFrames();
        Exception callbackFailure = null, firstFailure = null, cleanupFailure = null;
        Action previousGuard = null, previousPre = null;
        bool subscribed = false, scopeInstalled = false, preInstalled = false;
        var hammerIds = new HashSet<ulong> { firstReceipt.HammerId };
        var attackIds = new HashSet<ulong> { firstReceipt.PlayerAttackId };
        Check(firstReceipt.BossHp == 6 && firstReceipt.Applications == 1 && firstReceipt.PlayerAttackId != 0 &&
            firstReceipt.HammerId != 0 && firstReceipt.ExposureEntryPhysics > 0 && firstReceipt.TerminalPhysics == entryPhysics &&
            firstReceipt.PhysicsTicks == 60 && firstReceipt.BossSettings.ExposedSeconds == 2f,
            "qualified HP6 receipt and unchanged2s*60+60reserve=180 drain derivation");
        Transform2D Uniform(CollisionShape2D shape) => Task10BossUniform(shape, Native, Check);
        Rect2 Bounds(CollisionShape2D shape) => Task10BossBounds(shape, Uniform, Check);
        bool Supported() => Task10BossSupported(player, floor, boss, bodyShape, floorShape, entryDoor, exitDoor,
            Native, Bounds, Check);
        bool Idle() => claw.CurrentFrame.State == MechanicalClawState.Idle && claw.CurrentFrame.CastId == 0 &&
            claw.CurrentFrame.LockedTargetRuntimeId == 0 && claw.CurrentTarget == null && claw.ResidencyTarget == null;
        void FightSafety()
        {
            Native();
            string signature = string.Join(",", nodes.Select(node => node.GetInstanceId())) + "/" +
                string.Join(",", shapes.Where(shape => shape != hammerShape).Select(shape => shape.Shape.GetInstanceId())) +
                $"/{motor.Tuning.GetInstanceId()}/{combat.Tuning.GetInstanceId()}/{boss.Tuning.GetInstanceId()}";
            Check(signature == firstReceipt.NativeSignature && player.GetInstanceId() == firstReceipt.PlayerId &&
                monitor.Player.GetInstanceId() == firstReceipt.PlayerId && boss.GetInstanceId() == firstReceipt.BossId &&
                chain.GetInstanceId() == firstReceipt.ChainId && arena.CurrentBoss == boss && arena.IsEncounterActive &&
                flow.State == PrologueGameFlowState.Playing && !tree.Paused, "original native/resource identity and active Playing arena");
            Check(health.CurrentHealth == firstReceipt.PlayerHp && health.CurrentHealth > 0 &&
                monitor.RecoveryRequested == firstReceipt.RecoveryRequests && monitor.RecoveryCompleted == firstReceipt.Recoveries &&
                motor.AcceptedJumpCount == firstReceipt.Jumps && motor.AcceptedDashCount == firstReceipt.Dashes,
                "original playerHP/recovery/jump/dash across every drain and opening");
            float delta = (float)boss.GetPhysicsProcessDeltaTime();
            Check(Engine.PhysicsTicksPerSecond == firstReceipt.PhysicsTicks && Engine.TimeScale == 1d &&
                float.IsFinite(delta) && delta > 0f && Mathf.Abs(delta - firstReceipt.PhysicsDelta) <= .000001f &&
                boss.Tuning.ToSettings() == firstReceipt.BossSettings && combat.Tuning.ToCombatSettings() == firstReceipt.CombatSettings &&
                motor.Tuning.ToMotionSettings() == firstReceipt.MotionSettings, "finite unchanged original tuning/rate/timeScale1");
            Check(player.GlobalPosition.IsFinite() && player.Velocity.IsFinite() && boss.GlobalPosition.IsFinite() && boss.Velocity.IsFinite() &&
                boss.GlobalPosition.X - player.GlobalPosition.X > 60f && float.IsFinite(energy.EnergyRatio) && float.IsFinite(energy.HeatRatio),
                "finite left flank/resources without crossing");
            Check(!floorShape.Disabled && !bodyShape.Disabled && !hurtShape.Disabled && !entryDoor.Disabled && !exitDoor.Disabled && Supported(),
                "same full ArenaFloor support and both doors closed");
            Rect2 body = Bounds(bodyShape), entry = Bounds(entryDoor), exit = Bounds(exitDoor);
            Check(body.Position.X > entry.End.X && body.End.X < exit.Position.X && !body.Intersects(entry) && !body.Intersects(exit),
                "positive whole-body closed-door clearance");
            Check(!shield.IsActive && !motor.IsDashing && !input.CurrentFrame.JumpPressed && !input.CurrentFrame.JumpHeld &&
                !input.CurrentFrame.DashPressed && !input.CurrentFrame.ShieldHeld &&
                (!input.CurrentFrame.AttackPressed || KeyboardRouteInputDriver.Current != null && keyboardOpeningInProgress) &&
                !input.CurrentFrame.ThreadPressed && !input.CurrentFrame.ThreadHeld && !input.CurrentFrame.ThreadReleased,
                "no shield/jump/dash/legacy input");
            Check(bossHealth.CurrentHealth > 0 && bossHealth.CurrentHealth >= current.BossHp - 1 && bossHealth.CurrentHealth <= current.BossHp &&
                adapter.ApplicationCount >= current.Applications && adapter.ApplicationCount <= current.Applications + 1 &&
                claw.CurrentFrame.NextCastId >= current.NextCastId && claw.CurrentFrame.NextCastId <= current.NextCastId + 1 &&
                claw.CurrentFrame.Failure == MechanicalClawFailure.None && !claw.CurrentFrame.BoostConsumed, "bounded next unique nonfatal opening continuity");
            if (callbackFailure != null) throw new InvalidOperationException("Task10 nonfatal repeat callback failure", callbackFailure);
        }
        void Log(string boundary, string details = "")
        {
            Native(); GD.Print($"TASK10_BOSS_NONFATAL boundary={boundary} cycle={cycle}/5 physics={Engine.GetPhysicsFrames()} " +
                $"physics_delta={Engine.GetPhysicsFrames() - entryPhysics} waits={totalWaits}/3900 drain_waits={drainWaits}/180 " +
                $"player={firstReceipt.PlayerId} boss={firstReceipt.BossId} chain={firstReceipt.ChainId} HP={health.CurrentHealth}/{firstReceipt.PlayerHp} " +
                $"bossHP={bossHealth.CurrentHealth} state={boss.CurrentFrame.State} pose={player.GlobalPosition} velocity={player.Velocity} " +
                $"gap={boss.GlobalPosition.X - player.GlobalPosition.X:R} full_floor={Supported()} claw={claw.CurrentFrame.State}/{claw.CurrentFrame.NextCastId} " +
                $"applications={adapter.ApplicationCount} old_attack={current.PlayerAttackId}/{current.AttackPhysics} combat_active={combat.IsAttacking} " +
                $"exposure_entry_physics={current.ExposureEntryPhysics} {details}");
        }
        void Callback(Action action) { try { Native(); action(); } catch (Exception error) { callbackFailure ??= error; } }
        void OnPlayerDamaged(int remaining, Vector2 impulse) => Callback(() => Check(false, "additional player damage"));
        void OnPlayerHealed(int restored, int remaining) => Callback(() => Check(false, "additional player heal"));
        void OnPlayerDied() => Callback(() => Check(false, "unexpected player death"));
        void OnBossHealed(int restored, int remaining) => Callback(() => Check(false, "unexpected Boss heal"));
        void OnBossDied() => Callback(() => Check(false, "unexpected nonfatal Boss death"));
        void FightGuard() { previousGuard?.Invoke(); FightSafety(); }
        void FightPreGuard() { FightSafety(); previousPre?.Invoke(); }
        void Release()
        {
            SendAction(InputActions.MoveLeft, false); SendAction(InputActions.MoveRight, false);
            SendAction(InputActions.SelectGrappleMode, false); SendAction(InputActions.SelectAttackMode, false);
            SendMouse(MouseButton.Left, false, Live(player) ? player : null, Live(chain) ? chain.WorldAnchor : Vector2.Zero);
        }
        void Cleanup(Action action) { try { action(); } catch (Exception error) { cleanupFailure ??= error; } }
        async Task DrainOldOpening()
        {
            drainWaits = 0;
            await DrainTask10BossOldOpening(tree, boss, bossHealth, combat, player, input, claw, adapter,
                current, Native, FightSafety, Idle, Release, Callback, Log, Check, observe,
                swapApproachGuard, swapPreObserverGuard, () => totalWaits < 3900,
                issued => { drainWaits = issued; totalWaits++; }, "TASK10_BOSS_NONFATAL");
        }
        try
        {
            subscribed = true; health.Damaged += OnPlayerDamaged; health.Healed += OnPlayerHealed; health.Died += OnPlayerDied;
            bossHealth.Healed += OnBossHealed; bossHealth.Died += OnBossDied;
            previousGuard = swapApproachGuard(FightGuard); scopeInstalled = true;
            previousPre = swapPreObserverGuard(FightPreGuard); preInstalled = true;
            FightSafety(); Check(bossHealth.CurrentHealth == 6 && boss.CurrentFrame.State == FallenBellkeeperState.Exposed &&
                !boss.CurrentFrame.ArmorClosed && Idle(), "actual qualified first-opening terminal");
            for (int expectedEntryHp = 6; expectedEntryHp >= 2; expectedEntryHp--)
            {
                cycle++; Check(current.BossHp == expectedEntryHp, "exact five ordered nonfatal openings, no retries");
                await DrainOldOpening(); // Finally has synchronously detached ALL drain-only listeners/guards.
                FightSafety(); Log("CYCLE_START", $"expected_entry_hp={expectedEntryHp}");
                Task10BossOpeningReceipt next;
                keyboardOpeningInProgress = KeyboardRouteInputDriver.Current != null;
                try
                {
                    next = await DriveTask10BossFirstExposure(tree, level, world, player, monitor,
                        observe, swapApproachGuard, swapPreObserverGuard, expectedEntryHp, current);
                }
                finally { keyboardOpeningInProgress = false; }
                Check(next != null && next.PlayerId == firstReceipt.PlayerId && next.BossId == firstReceipt.BossId && next.ChainId == firstReceipt.ChainId &&
                    next.PlayerHp == firstReceipt.PlayerHp && next.RecoveryRequests == firstReceipt.RecoveryRequests && next.Recoveries == firstReceipt.Recoveries &&
                    next.Jumps == firstReceipt.Jumps && next.Dashes == firstReceipt.Dashes && next.NativeSignature == firstReceipt.NativeSignature &&
                    next.BossHp == expectedEntryHp - 1 && next.Applications == current.Applications + 1 && next.NextCastId == current.NextCastId + 1 &&
                    next.ExposureEntryPhysics > current.TerminalPhysics && next.AttackPhysics >= next.ExposureEntryPhysics &&
                    next.TerminalPhysics == Engine.GetPhysicsFrames() && next.Waits <= 600 && next.Waits > 0 &&
                    hammerIds.Add(next.HammerId) && attackIds.Add(next.PlayerAttackId), "actual fresh unique Hammer/cast/attack and one nonfatal decrement");
                totalWaits += next.Waits; current = next; FightSafety();
                Check(totalWaits <= cycle * (180 + 600) && totalWaits <= 3900, "exact five bounded drain180+opening600 additional waits");
                Log("CYCLE_RESULT", $"actual_hp={expectedEntryHp}→{current.BossHp} hammer={current.HammerId} cast={current.NextCastId - 1} " +
                    $"player_attack={current.PlayerAttackId}/{current.AttackPhysics} opening_waits={current.Waits}");
            }
            Release(); FightSafety();
            Check(cycle == 5 && bossHealth.CurrentHealth == 1 && current.BossHp == 1 && boss.CurrentFrame.State == FallenBellkeeperState.Exposed &&
                !boss.CurrentFrame.ArmorClosed && !boss.CurrentFrame.AttackActive && adapter.ApplicationCount == 6 &&
                current.Applications == firstReceipt.Applications + 5 && current.NextCastId == firstReceipt.NextCastId + 5 &&
                hammerIds.Count == 6 && attackIds.Count == 6 && Idle() && player.Velocity.Length() <= 2f &&
                input.CurrentFrame.MoveAxis == 0f && boss.GlobalPosition.X - player.GlobalPosition.X >= 80f &&
                boss.GlobalPosition.X - player.GlobalPosition.X <= 90f && totalWaits <= 3900,
                "living BossHP1/open actual Exposed, exactly five additional unique hits/six applications, unchanged supported player");
            Log("SUMMARY", $"additional_unique_hits=5 phase2_applications=6 pending_last_attack={current.PlayerAttackId}/{current.AttackPhysics} " +
                "nonfatal_checkpoint_only=True fatal_death_exit_unrun=True");
        }
        catch (Exception error)
        {
            firstFailure = error;
            try { Log("FAIL", $"type={error.GetType().Name} message={error.Message.Replace('\r', ' ').Replace('\n', ' ')}"); }
            catch (Exception diagnosticError)
            { try { GD.Print($"TASK10_BOSS_NONFATAL boundary=FAIL diagnostic_gap={diagnosticError.GetType().Name} type={error.GetType().Name} " +
                $"message={error.Message.Replace('\r', ' ').Replace('\n', ' ')}"); } catch { } }
            throw;
        }
        finally
        {
            if (subscribed)
            {
                Cleanup(() => { if (GodotObject.IsInstanceValid(health)) { health.Damaged -= OnPlayerDamaged; health.Healed -= OnPlayerHealed; health.Died -= OnPlayerDied; } });
                Cleanup(() => { if (GodotObject.IsInstanceValid(bossHealth)) { bossHealth.Healed -= OnBossHealed; bossHealth.Died -= OnBossDied; } });
            }
            Cleanup(Release); Cleanup(() => { if (preInstalled) swapPreObserverGuard(previousPre); });
            Cleanup(() => { if (scopeInstalled) swapApproachGuard(previousGuard); });
            if (firstFailure != null && cleanupFailure != null)
                try { GD.Print($"TASK10_BOSS_NONFATAL cleanup_gap={cleanupFailure.GetType().Name}"); } catch { }
        }
        if (cleanupFailure != null) throw cleanupFailure;
        return current;
    }

    private static async Task<Task10TerminalProof> DriveTask10BossPhysicalExit(SceneTree tree,
        PrologueLevelController level, SeamlessPrologueWorld world, CharacterBody2D player,
        RouteMonitor monitor, Action observe, Func<Action, Action> swapApproachGuard,
        Func<Action, Action> swapPreObserverGuard, Task10BossDeathReceipt death)
    {
        bool Live(Node node) => node != null && GodotObject.IsInstanceValid(node) &&
            node.IsInsideTree() && !node.IsQueuedForDeletion();
        void Check(bool condition, string message) => TestAssert.True(condition, "Task10 Boss physical exit: " + message);
        Check(GodotObject.IsInstanceValid(tree) && Live(level) && Live(world) && Live(player) && Live(monitor.Player) &&
            death?.Opening != null && death.Damage != null, "native-valid genuine death receipt entry");
        Task10BossOpeningReceipt receipt = death.Opening;
        Check(world.TryGetMountedSector(PrologueSectorId.LostTemple, out PrologueSector temple) && Live(temple), "actual LostTemple");
        BossArenaController arena = temple.GetNode<BossArenaController>("Gameplay/BossArenaController");
        Check(Live(arena) && Live(arena.CurrentBoss), "same actual arena/Boss before component reads");
        FallenBellkeeper boss = arena.CurrentBoss;
        PrologueGameFlowController flow = level.GetNode<PrologueGameFlowController>("GameFlow");
        PrologueCompletionController completion = level.GetNode<PrologueCompletionController>("Completion");
        Control panel = level.GetNode<Control>("Hud/FormalHud/Completion");
        HealthComponent health = player.GetNode<HealthComponent>("Health"), bossHealth = boss.GetNode<HealthComponent>("Health");
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        PlayerCombat combat = player.GetNode<PlayerCombat>("Combat");
        PlayerActionModeController modes = player.GetNode<PlayerActionModeController>("ActionModes");
        PlayerEnergyController energy = player.GetNode<PlayerEnergyController>("Energy");
        PlayerShieldController shield = player.GetNode<PlayerShieldController>("Shield");
        MechanicalClawController claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
        StaticBody2D floor = temple.GetNode<StaticBody2D>("Gameplay/Collision/ArenaFloor");
        Hurtbox playerHurtbox = player.GetNode<Hurtbox>("Hurtbox"), bossHurtbox = boss.GetNode<Hurtbox>(boss.HurtboxPath);
        Hitbox hammerHitbox = boss.GetNode<Hitbox>(boss.AttackHitboxPath);
        ThreadTarget2D chain = boss.GetNode<ThreadTarget2D>(boss.ChainTargetPath);
        Check(new Node[] { floor, playerHurtbox, bossHurtbox, hammerHitbox, chain }.All(Live), "live original geometry owners");
        CollisionShape2D floorShape = floor.GetNode<CollisionShape2D>("Collision");
        CollisionShape2D bodyShape = player.GetNode<CollisionShape2D>("BodyCollider");
        CollisionShape2D hurtShape = playerHurtbox.GetNode<CollisionShape2D>("HurtboxCollider");
        CollisionShape2D bossHurtShape = bossHurtbox.GetNode<CollisionShape2D>("HurtboxCollider");
        CollisionShape2D hammerShape = hammerHitbox.GetNode<CollisionShape2D>("AttackCollider");
        CollisionShape2D chainShape = chain.GetNode<CollisionShape2D>("TargetCollision/Collision");
        CollisionShape2D entryDoor = arena.GetNode<CollisionShape2D>(arena.EntryDoorCollisionPath);
        CollisionShape2D exitDoor = arena.GetNode<CollisionShape2D>(arena.ExitDoorCollisionPath);
        LegacyThreadInteractionAdapter adapter = chain.GetNode<LegacyThreadInteractionAdapter>("LegacyThreadInteractionAdapter");
        Node[] nodes = { level, world, temple, arena, boss, flow, player, monitor.Player, health, bossHealth,
            motor, input, combat, modes, energy, shield, claw, floor, playerHurtbox, bossHurtbox, hammerHitbox,
            chain, adapter, floorShape, bodyShape, hurtShape, bossHurtShape, hammerShape, chainShape, entryDoor, exitDoor };
        CollisionShape2D[] shapes = { floorShape, bodyShape, hurtShape, bossHurtShape, hammerShape, chainShape, entryDoor, exitDoor };
        void Native()
        {
            Check(GodotObject.IsInstanceValid(tree) && nodes.All(Live) && Live(completion) && Live(panel), "native lifetime before all reads/events/waits");
            Check(shapes.All(shape => GodotObject.IsInstanceValid(shape.Shape)) && GodotObject.IsInstanceValid(motor.Tuning) &&
                GodotObject.IsInstanceValid(combat.Tuning) && GodotObject.IsInstanceValid(boss.Tuning), "original native resources");
        }
        Native();
        Transform2D Uniform(CollisionShape2D shape) => Task10BossUniform(shape, Native, Check);
        Rect2 Bounds(CollisionShape2D shape) => Task10BossBounds(shape, Uniform, Check);
        Check(bodyShape.Shape is CapsuleShape2D && exitDoor.Shape is RectangleShape2D && floorShape.Shape is RectangleShape2D &&
            Mathf.Abs(Uniform(floorShape).Rotation) <= .0001f && Mathf.Abs(Uniform(exitDoor).Rotation) <= .0001f,
            "actual transformed capsule and horizontal rectangular floor/exit face");
        Rect2 ground = Bounds(floorShape), exit = Bounds(exitDoor), initialBody = Bounds(bodyShape);
        Transform2D floorTransform = floorShape.GlobalTransform, exitTransform = exitDoor.GlobalTransform;
        string savePath = flow.SavePath;
        string storageArgument = Array.Find(OS.GetCmdlineUserArgs(), value => value.StartsWith("--case-storage-root=", StringComparison.Ordinal));
        Check(storageArgument != null && Path.IsPathFullyQualified(savePath) &&
            Task10ApplicationPersistenceGuard.IsWithin(savePath, storageArgument["--case-storage-root=".Length..]) && File.Exists(savePath),
            "existing injected case-owned absolute save, never real application storage");
        PrologueCheckpointSnapshot checkpoint = level.Progress.RestoreCheckpoint();
        string CheckpointSignature(Knight.Save.PrologueSaveData save) =>
            $"{save.HasActivatedCheckpoint}/{save.CheckpointId}/{save.CheckpointSector}/{save.CheckpointWorldX:R}/{save.CheckpointWorldY:R}/{save.ShortcutOpen}";
        Knight.Save.PrologueSaveData beforeSave = Knight.Save.PrologueSaveStore.LoadOrNew(savePath, CanyonWorldLayout.CurrentLayoutVersion);
        string checkpointSignature = CheckpointSignature(beforeSave);
        Check(!beforeSave.WasRecovered && !beforeSave.Completed && beforeSave.BossDefeated &&
            beforeSave.LayoutVersion == CanyonWorldLayout.CurrentLayoutVersion && beforeSave.HasActivatedCheckpoint &&
            beforeSave.CheckpointId == checkpoint.CheckpointId && beforeSave.CheckpointSector == checkpoint.SectorId.ToString() &&
            beforeSave.CheckpointWorldPosition == checkpoint.WorldPosition && checkpoint.HasActivatedCheckpoint &&
            checkpoint.SectorId == PrologueSectorId.LostTemple && checkpoint.Progress.BossDefeated,
            "genuine pre-exit disk BossDefeated/Completed=false and unchanged authored checkpoint");
        byte[] beforeBytes = File.ReadAllBytes(savePath), completedBytes = null;
        float delta = (float)player.GetPhysicsProcessDeltaTime(), scale = motor.EffectiveMovementScale;
        float speed = motor.Tuning.MaxRunSpeed * scale, acceleration = motor.Tuning.GroundAcceleration;
        Check(float.IsFinite(delta) && delta > 0f && Mathf.Abs(delta - receipt.PhysicsDelta) <= .000001f &&
            float.IsFinite(scale) && scale > 0f && scale <= 1f && float.IsFinite(speed) && speed > 0f &&
            float.IsFinite(acceleration) && acceleration > 0f && player.Velocity == Vector2.Zero,
            "actual pinned normal stationary V=MaxRunSpeed*scale/A=unscaled GroundAcceleration/delta");
        float distance = exit.End.X - initialBody.Position.X, step = speed * delta;
        double walk = Math.Ceiling(speed / (acceleration * delta)) + Math.Ceiling((distance + step) / step);
        Check(float.IsFinite(distance) && distance > 0f && float.IsFinite(step) && step > 0f &&
            double.IsFinite(walk) && walk > 0d && walk <= int.MaxValue - 16 &&
            initialBody.End.X + distance + 17f * step < ground.End.X,
            "derived strict whole-body crossing plus fresh8/witness8 step room within actual enabled ArenaFloor");
        int walkBudget = (int)walk, overallBudget = walkBudget + 8 + 8;
        int exitWaits = 0, heldWaits = 0, completionEvents = 0;
        ulong rightIssue = 0, rightSample = 0, crossingPhysics = 0;
        int crossingWait = 0;
        Vector2 eventPose = Vector2.Zero, eventVelocity = Vector2.Zero;
        Rect2 eventBody = default;
        ulong eventPhysics = 0;
        Rect2 eventFloor = default, eventDoor = default;
        bool eventSupported = false, eventPlayerPhysicsEnabled = false, eventPanelVisible = false;
        bool eventSavedBossDefeated = false, eventSavedCompleted = false;
        PrologueGameFlowState eventFlow = default;
        int eventCompletionCount = 0;
        string eventCheckpointSignature = null;
        Task10TerminalProof terminalProof = null;
        bool subscribed = false, scopeInstalled = false, preInstalled = false, moving = false;
        Action previousGuard = null, previousPre = null;
        Exception callbackFailure = null, firstFailure = null, cleanupFailure = null;
        bool Supported()
        {
            Native(); Rect2 body = Bounds(bodyShape), actualGround = Bounds(floorShape);
            if (!player.IsOnFloor() || body.Position.X < actualGround.Position.X || body.End.X > actualGround.End.X) return false;
            for (int index = 0; index < player.GetSlideCollisionCount(); index++)
            {
                KinematicCollision2D contact = player.GetSlideCollision(index);
                if (!GodotObject.IsInstanceValid(contact)) continue;
                GodotObject collider = contact.GetCollider();
                if (GodotObject.IsInstanceValid(collider) && collider == floor && contact.GetNormal().Dot(Vector2.Up) > .7f) return true;
            }
            return false; // Corpse collision is not disabled or replaced by test geometry.
        }
        bool BeyondExit() => Bounds(bodyShape).Position.X > Bounds(exitDoor).End.X;
        void CommonSafety()
        {
            Native();
            string signature = string.Join(",", nodes.Select(node => node.GetInstanceId())) + "/" +
                string.Join(",", shapes.Where(shape => shape != hammerShape).Select(shape => shape.Shape.GetInstanceId())) +
                $"/{motor.Tuning.GetInstanceId()}/{combat.Tuning.GetInstanceId()}/{boss.Tuning.GetInstanceId()}";
            Check(signature == receipt.NativeSignature && player.GetInstanceId() == receipt.PlayerId &&
                monitor.Player.GetInstanceId() == receipt.PlayerId && boss.GetInstanceId() == receipt.BossId &&
                chain.GetInstanceId() == receipt.ChainId && arena.CurrentBoss == boss && !arena.IsEncounterActive &&
                bossHealth.CurrentHealth == 0 && boss.CurrentFrame.State == FallenBellkeeperState.Defeated &&
                !boss.CurrentFrame.AttackActive && !boss.CurrentFrame.ChainTargetActive && entryDoor.Disabled && exitDoor.Disabled,
                "same original actually defeated/inactive Boss and both disabled doors");
            Check(health.CurrentHealth == receipt.PlayerHp && health.CurrentHealth > 0 &&
                monitor.RecoveryRequested == receipt.RecoveryRequests && monitor.RecoveryCompleted == receipt.Recoveries &&
                motor.AcceptedJumpCount == receipt.Jumps && motor.AcceptedDashCount == receipt.Dashes,
                "alive original playerHP/recovery/jump/dash counters unchanged");
            Check(Engine.PhysicsTicksPerSecond == receipt.PhysicsTicks && Engine.TimeScale == 1d && !tree.Paused &&
                Mathf.Abs((float)player.GetPhysicsProcessDeltaTime() - delta) <= .000001f &&
                Mathf.Abs((float)boss.GetPhysicsProcessDeltaTime() - receipt.PhysicsDelta) <= .000001f &&
                boss.Tuning.ToSettings() == receipt.BossSettings && combat.Tuning.ToCombatSettings() == receipt.CombatSettings &&
                motor.Tuning.ToMotionSettings() == receipt.MotionSettings && motor.EffectiveMovementScale == scale &&
                motor.Tuning.MaxRunSpeed * motor.EffectiveMovementScale == speed && motor.Tuning.GroundAcceleration == acceleration,
                "unchanged native tuning/rate/delta and actual unscaled movement bound");
            Check(player.GlobalPosition.IsFinite() && player.Velocity.IsFinite() && boss.GlobalPosition.IsFinite() && boss.Velocity.IsFinite() &&
                float.IsFinite(energy.EnergyRatio) && float.IsFinite(energy.HeatRatio) && !floorShape.Disabled && !bodyShape.Disabled &&
                !hurtShape.Disabled && floorShape.GlobalTransform == floorTransform && exitDoor.GlobalTransform == exitTransform &&
                Bounds(floorShape) == ground && Bounds(exitDoor) == exit && Supported(), "finite supported full-body original actual floor/door geometry");
            Check(!combat.IsAttacking && claw.CurrentFrame.State == MechanicalClawState.Idle && claw.CurrentFrame.CastId == 0 &&
                claw.CurrentFrame.LockedTargetRuntimeId == 0 && claw.CurrentTarget == null && claw.ResidencyTarget == null &&
                claw.CurrentFrame.NextCastId == receipt.NextCastId && adapter.ApplicationCount == 7 &&
                adapter.ApplicationCount == receipt.Applications && claw.CurrentFrame.Failure == MechanicalClawFailure.None &&
                !claw.CurrentFrame.BoostConsumed && motor.GrappleMovementScale == 1f && !motor.HasGrappleReleaseMomentum &&
                !motor.IsDashing && !shield.IsActive, "target-free Idle/normal grounded motion, no new cast/attack/dash/shield");
            Check(!input.CurrentFrame.PrimaryPressed && !input.CurrentFrame.PrimaryHeld && !input.CurrentFrame.GrappleModePressed &&
                !input.CurrentFrame.AttackModePressed && !input.CurrentFrame.JumpPressed && !input.CurrentFrame.JumpHeld &&
                !input.CurrentFrame.DashPressed && !input.CurrentFrame.ShieldHeld && !input.CurrentFrame.AttackPressed &&
                !input.CurrentFrame.ThreadPressed && !input.CurrentFrame.ThreadHeld && !input.CurrentFrame.ThreadReleased,
                "normal right walk only, no primary/mode/jump/dash/shield/legacy input");
            PrologueCheckpointSnapshot actualCheckpoint = level.Progress.RestoreCheckpoint();
            Check(world.CurrentSector == PrologueSectorId.LostTemple && level.CurrentSector == PrologueSectorId.LostTemple &&
                level.CurrentSectorRoot == temple && level.Progress.BossDefeated && completion.CurrentObjective == PrologueObjective.Complete &&
                actualCheckpoint.CheckpointId == checkpoint.CheckpointId && actualCheckpoint.SectorId == checkpoint.SectorId &&
                actualCheckpoint.WorldPosition == checkpoint.WorldPosition && actualCheckpoint.HasActivatedCheckpoint == checkpoint.HasActivatedCheckpoint &&
                flow.SavePath == savePath, "real LostTemple/objective Complete/BossDefeated and authored checkpoint/save path unchanged");
            if (callbackFailure != null) throw new InvalidOperationException("Task10 physical exit callback failure", callbackFailure);
        }
        void Safety()
        {
            CommonSafety();
            if (completionEvents == 0)
                Check(flow.State == PrologueGameFlowState.Playing && player.IsPhysicsProcessing() && completion.CompletionCount == 0 &&
                    flow.Save.BossDefeated && !flow.Save.Completed,
                    "pre-event Playing/enabled with zero normal completion");
            else
                Check(completionEvents == 1 && completion.CompletionCount == 1 && flow.State == PrologueGameFlowState.Completed &&
                    !player.IsPhysicsProcessing() && flow.Save.Completed && flow.Save.BossDefeated &&
                    BeyondExit() && player.GlobalPosition == eventPose && player.Velocity == eventVelocity &&
                    Bounds(bodyShape) == eventBody && panel.IsVisibleInTree(), "post-event Completed/disabled, fixed supported event pose and ordinary visible completion panel");
        }
        void Log(string boundary, string details = "")
        {
            Native(); GD.Print($"TASK10_BOSS_PHYSICAL_EXIT boundary={boundary} physics={Engine.GetPhysicsFrames()} " +
                $"waits={exitWaits}/{overallBudget} walk_bound={walkBudget} fresh_allowance=8 witness_allowance=8 held_waits={heldWaits}/60 " +
                $"V={speed:R} A={acceleration:R} scale={scale:R} delta={delta:R} D={distance:R} player={receipt.PlayerId} boss={receipt.BossId} " +
                $"HP={health.CurrentHealth}/{receipt.PlayerHp} pose={player.GlobalPosition} velocity={player.Velocity} body={Bounds(bodyShape)} " +
                $"exit={exit} floor={ground} supported={Supported()} beyond_right_face={BeyondExit()} flow={flow.State} " +
                $"player_physics={player.IsPhysicsProcessing()} count={completion.CompletionCount} events={completionEvents} " +
                $"right_input={rightIssue}/{rightSample} checkpoint={checkpoint.CheckpointId} {details}");
        }
        void Callback(Action action) { try { Native(); action(); } catch (Exception error) { callbackFailure ??= error; } }
        void OnCompleted() => Callback(() =>
        {
            CommonSafety();
            Check(moving && completionEvents == 0 && completion.CompletionCount == 1 && rightSample > rightIssue &&
                input.CurrentFrame.MoveAxis == 1f && BeyondExit() && Supported() &&
                flow.State == PrologueGameFlowState.Completed && !player.IsPhysicsProcessing(),
                "one actual completion signal at whole-body supported crossing; earlier flow listener may already disable player");
            eventPose = player.GlobalPosition; eventVelocity = player.Velocity; eventBody = Bounds(bodyShape);
            eventPhysics = Engine.GetPhysicsFrames(); completionEvents++;
            completedBytes = File.ReadAllBytes(savePath);
            Knight.Save.PrologueSaveData actual = Knight.Save.PrologueSaveStore.LoadOrNew(savePath, CanyonWorldLayout.CurrentLayoutVersion);
            Check(!actual.WasRecovered && actual.Completed && actual.BossDefeated && actual.LayoutVersion == CanyonWorldLayout.CurrentLayoutVersion &&
                actual.Objective == nameof(PrologueObjective.Complete) && CheckpointSignature(actual) == checkpointSignature &&
                !completedBytes.SequenceEqual(beforeBytes) && panel.IsVisibleInTree(), "actual false→true disk save/current layout/checkpoint and ordinary completion panel");
            eventFloor = Bounds(floorShape); eventDoor = Bounds(exitDoor); eventSupported = Supported();
            eventFlow = flow.State; eventPlayerPhysicsEnabled = player.IsPhysicsProcessing();
            eventPanelVisible = panel.IsVisibleInTree(); eventCompletionCount = completion.CompletionCount;
            eventSavedBossDefeated = actual.BossDefeated; eventSavedCompleted = actual.Completed;
            eventCheckpointSignature = CheckpointSignature(actual);
            Log("ACTUAL_COMPLETION", $"event_physics={eventPhysics} actual_save_transition=True measured_OS_write_count=unavailable");
        });
        void OnPlayerDamaged(int remaining, Vector2 impulse) => Callback(() => Check(false, "additional player damage"));
        void OnPlayerHealed(int restored, int remaining) => Callback(() => Check(false, "additional player heal"));
        void OnPlayerDied() => Callback(() => Check(false, "unexpected player death"));
        void OnBossDamaged(int remaining, Vector2 impulse) => Callback(() => Check(false, "new Boss damage after death"));
        void OnBossHealed(int restored, int remaining) => Callback(() => Check(false, "unexpected Boss heal"));
        void OnBossDied() => Callback(() => Check(false, "duplicate Boss death"));
        void OnArenaDefeated() => Callback(() => Check(false, "duplicate arena defeat"));
        void OnStarted(ulong id, int direction) => Callback(() => Check(false, "new AttackStarted during exit/held completion"));
        void OnConnected(Hurtbox target) => Callback(() => Check(false, "new AttackConnected during exit/held completion"));
        void Guard()
        {
            previousGuard?.Invoke(); Safety();
            if (moving && input.CurrentFrameSequence > rightIssue && input.CurrentFrame.MoveAxis == 1f && rightSample == 0)
            { rightSample = input.CurrentFrameSequence; Log("FRESH_RIGHT_INPUT"); }
            if (completionEvents == 0 && BeyondExit() && crossingPhysics == 0)
            { crossingPhysics = Engine.GetPhysicsFrames(); crossingWait = exitWaits; Log("SUPPORTED_RIGHT_CROSSING"); }
        }
        void PreGuard() { Safety(); previousPre?.Invoke(); }
        async Task Tick(bool held)
        {
            Safety();
            if (held) { Check(heldWaits < 60 && completionEvents == 1, "exactly60 completed held-input waits"); heldWaits++; }
            else
            {
                Check(exitWaits < overallBudget && (crossingPhysics == 0 || exitWaits - crossingWait < 8), "derived exit cap and crossing witness8 exhausted");
                Check(Bounds(bodyShape).End.X + step < ground.End.X, "no held walk beyond safe actual floor while awaiting completion");
                exitWaits++;
            }
            await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
            Safety(); observe();
            if (held) Check(Input.IsActionPressed(InputActions.MoveRight) && completedBytes != null &&
                File.ReadAllBytes(savePath).SequenceEqual(completedBytes), "normal right input remains held and actual completed save bytes unchanged");
        }
        void Release()
        {
            SendAction(InputActions.MoveLeft, false); SendAction(InputActions.MoveRight, false);
            SendAction(InputActions.SelectGrappleMode, false); SendAction(InputActions.SelectAttackMode, false);
            SendMouse(MouseButton.Left, false, Live(player) ? player : null, Live(player) ? player.GlobalPosition : Vector2.Zero);
        }
        void Cleanup(Action action) { try { action(); } catch (Exception error) { cleanupFailure ??= error; } }
        try
        {
            subscribed = true; completion.PrologueCompleted += OnCompleted;
            health.Damaged += OnPlayerDamaged; health.Healed += OnPlayerHealed; health.Died += OnPlayerDied;
            bossHealth.Damaged += OnBossDamaged; bossHealth.Healed += OnBossHealed; bossHealth.Died += OnBossDied;
            arena.EncounterDefeated += OnArenaDefeated; combat.AttackStarted += OnStarted; combat.AttackConnected += OnConnected;
            previousGuard = swapApproachGuard(Guard); scopeInstalled = true;
            previousPre = swapPreObserverGuard(PreGuard); preInstalled = true;
            Safety(); Check(receipt.BossHp == 0 && receipt.Applications == 7 && death.DiedEvents == 1 && death.ArenaEvents == 1 &&
                death.DefeatedPhysics != 0 && death.DrainWaits <= 180 && receipt.Waits <= 600 && death.DeathTailWaits <= 8 && death.SettleWaits <= 60 &&
                receipt.TerminalPhysics == Engine.GetPhysicsFrames() && input.CurrentFrame.MoveAxis == 0f &&
                player.Velocity == Vector2.Zero && !BeyondExit() && !flow.Save.Completed && flow.Save.BossDefeated,
                "genuine cleaned-up fatal receipt and stationary Playing pre-exit baseline");
            Release(); Log("ENTRY", $"completion_count=0 saved_completed=False saved_boss_defeated=True save={savePath}");
            rightIssue = input.CurrentFrameSequence; moving = true; SendAction(InputActions.MoveRight, true);
            while (rightSample <= rightIssue && completionEvents == 0)
            { Check(exitWaits < 8, "fresh normal right-input observation8 exhausted"); await Tick(false); }
            Check(rightSample > rightIssue, "one fresh actual right-input sample before crossing");
            while (completionEvents == 0) await Tick(false);
            Safety(); Check(completedBytes != null && completionEvents == 1 && completion.CompletionCount == 1, "normal completion observed within derived bound");
            while (heldWaits < 60) await Tick(true);
            Safety(); Check(heldWaits == 60 && Input.IsActionPressed(InputActions.MoveRight) &&
                File.ReadAllBytes(savePath).SequenceEqual(completedBytes), "60 actual held-input waits: no movement/fall/recovery/duplicate completion/save drift");
            terminalProof = new Task10TerminalProof
            {
                PlayerInstanceId = receipt.PlayerId, BossInstanceId = receipt.BossId,
                FatalAttackId = death.Damage.PlayerAttackId, ExposurePhysics = death.Damage.ExposureEntryPhysics,
                AttackPhysics = death.Damage.AttackPhysics, DamagePhysics = death.Damage.DamagePhysics,
                DefeatedPhysics = death.DefeatedPhysics, CompletionPhysics = eventPhysics,
                HeldEndPhysics = Engine.GetPhysicsFrames(), BossDiedEvents = death.DiedEvents,
                ArenaDefeatedEvents = death.ArenaEvents, CompletionEvents = completionEvents,
                CompletionCount = eventCompletionCount, RightInputIssueSequence = rightIssue,
                RightInputSampleSequence = rightSample, CompletionBody = eventBody,
                CompletionFloor = eventFloor, CompletionDoor = eventDoor, SupportedAtCompletion = eventSupported,
                CompletionFlowState = eventFlow, PlayerPhysicsEnabledAtCompletion = eventPlayerPhysicsEnabled,
                CompletionPanelVisible = eventPanelVisible, SavedBossDefeatedBeforeExit = beforeSave.BossDefeated,
                SavedBossDefeatedAfterExit = eventSavedBossDefeated, SavedCompletedBeforeExit = beforeSave.Completed,
                SavedCompletedAfterExit = eventSavedCompleted, CheckpointBeforeExit = checkpointSignature,
                CheckpointAfterExit = eventCheckpointSignature, HeldInputFrameCount = heldWaits,
                CompletionPosition = eventPose, HeldEndPosition = player.GlobalPosition,
                CompletionVelocity = eventVelocity, HeldEndVelocity = player.Velocity, HeldEndBody = Bounds(bodyShape),
                CompletionSaveSha256 = Convert.ToHexString(SHA256.HashData(completedBytes)),
                HeldEndSaveSha256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(savePath)))
            };
            Log("SUMMARY", $"event_physics={eventPhysics} physical_supported_exit=True completed_save_bytes_unchanged=True " +
                "completion_signal_count=1 completion_count=1 held_input_frames=60 measured_OS_write_count=unavailable whole_route_GREEN=False");
        }
        catch (Exception error)
        {
            firstFailure = error;
            try { Log("FAIL", $"type={error.GetType().Name} message={error.Message.Replace('\r', ' ').Replace('\n', ' ')}"); }
            catch { try { GD.Print($"TASK10_BOSS_PHYSICAL_EXIT boundary=FAIL type={error.GetType().Name} diagnostic_gap=True"); } catch { } }
            throw;
        }
        finally
        {
            if (subscribed)
            {
                Cleanup(() => { if (GodotObject.IsInstanceValid(completion)) completion.PrologueCompleted -= OnCompleted; });
                Cleanup(() => { if (GodotObject.IsInstanceValid(health)) { health.Damaged -= OnPlayerDamaged; health.Healed -= OnPlayerHealed; health.Died -= OnPlayerDied; } });
                Cleanup(() => { if (GodotObject.IsInstanceValid(bossHealth)) { bossHealth.Damaged -= OnBossDamaged; bossHealth.Healed -= OnBossHealed; bossHealth.Died -= OnBossDied; } });
                Cleanup(() => { if (GodotObject.IsInstanceValid(arena)) arena.EncounterDefeated -= OnArenaDefeated; });
                Cleanup(() => { if (GodotObject.IsInstanceValid(combat)) { combat.AttackStarted -= OnStarted; combat.AttackConnected -= OnConnected; } });
            }
            Cleanup(Release); Cleanup(() => { if (preInstalled) swapPreObserverGuard(previousPre); });
            Cleanup(() => { if (scopeInstalled) swapApproachGuard(previousGuard); });
            if (firstFailure != null && cleanupFailure != null)
                try { GD.Print($"TASK10_BOSS_PHYSICAL_EXIT cleanup_gap={cleanupFailure.GetType().Name}"); } catch { }
        }
        if (cleanupFailure != null) throw cleanupFailure;
        return terminalProof;
    }

    private static async Task ReachTask10KeyboardAscentGrip2(SceneTree tree,
        CharacterBody2D player, RouteMonitor monitor, Action observe,
        Func<Action, Action> swapApproachGuard, StaticBody2D previous, StaticBody2D support,
        Action armGroundJump)
    {
        // Explore uses one ordinary supported jump before K. The old standing
        // left-face pull intersects Grip1's post. Keep its failed evidence;
        // this legal jump/cast route has a different, explicit launch contract.
        // Preparation/rise share52; every original Task4 await/tail shares300.
        ulong stageStart = Engine.GetPhysicsFrames();
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        HealthComponent health = player.GetNode<HealthComponent>("Health");
        MechanicalClawController claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
        KeyboardRouteInputDriver keyboard = KeyboardRouteInputDriver.Current;
        CollisionShape2D previousShape = previous.GetNode<CollisionShape2D>("Collision");
        CollisionShape2D supportShape = support.GetNode<CollisionShape2D>("Collision");
        CollisionShape2D body = player.GetNode<CollisionShape2D>("BodyCollider");
        var capsule = (CapsuleShape2D)body.Shape;
        var rectangle = (RectangleShape2D)supportShape.Shape;
        StaticBody2D post = support.GetParent().GetNode<StaticBody2D>("AscentGrip2Grip");
        CollisionShape2D postShape = post.GetNode<CollisionShape2D>("Collision");
        var postRectangle = (RectangleShape2D)postShape.Shape;
        StaticBody2D oldPost = previous.GetParent().GetNode<StaticBody2D>(previous.Name + "Grip");
        CollisionShape2D oldPostShape = oldPost.GetNode<CollisionShape2D>("Collision");
        var oldPostRectangle = (RectangleShape2D)oldPostShape.Shape;
        GrappleSurface2D target = post.GetNode<GrappleSurface2D>("GrappleSurfaceProfile");
        GrappleSurface2D platform = support.GetNode<GrappleSurface2D>("GrappleSurfaceProfile");
        Vector2 aim = new(post.GlobalPosition.X,
            post.GlobalPosition.Y - postRectangle.Size.Y / 2f + 10f);
        Vector2 half = new(capsule.Radius * Mathf.Abs(body.GlobalTransform.X.X),
            capsule.Height * .5f * Mathf.Abs(body.GlobalTransform.Y.Y));
        Vector2 from = player.GlobalPosition;
        float near = supportShape.ToGlobal(new Vector2(-rectangle.Size.X / 2f, 0f)).X;
        float top = supportShape.ToGlobal(new Vector2(0f, -rectangle.Size.Y / 2f)).Y;
        const float margin = 4f;
        float originLimit = near - (half.X + margin + from.Y - top + half.Y + margin);
        Vector2 postLeftBottom = postShape.ToGlobal(new Vector2(-postRectangle.Size.X / 2f,
            postRectangle.Size.Y / 2f));
        float sideLimit = postLeftBottom.X - (from.Y - postLeftBottom.Y);
        float oldRight = oldPostShape.ToGlobal(new Vector2(oldPostRectangle.Size.X / 2f, 0f)).X;
        float stanceX = oldRight + half.X + margin + half.X / 2f + margin;
        ulong playerId = player.GetInstanceId(), nextCast = claw.CurrentFrame.NextCastId;
        int hp = health.CurrentHealth, requests = monitor.RecoveryRequested,
            recoveries = monitor.RecoveryCompleted, jumps = motor.AcceptedJumpCount,
            dashes = motor.AcceptedDashCount, rawClaws = keyboard.ClawEdges, rawAttacks = keyboard.AttackEdges;
        ulong approachFrames = 0UL, settleFrames = 0UL;
        ulong jumpIssueSequence = 0UL, launchSequence = 0UL, observedSequence = input.CurrentFrameSequence;
        int lastJumps = jumps, spaceEdges = 0;
        bool jumpArmed = false, launched = false, priorFullSupport = false, boostSeen = false;
        Vector2 launchPosition = Vector2.Zero, preflightDock = Vector2.Zero;
        bool nativeClear = false;
        string phase = "prepare";
        var stancePlans = new List<string>(16);
        int omittedPlans = 0;
        var resolver = new MechanicalClawTargetResolver();
        Vector2 Planned() => PlayerKeyboardAimModel.ResolveDirection(aim - player.GlobalPosition, 1);
        bool Ready() => Mathf.Abs(player.GlobalPosition.X - stanceX) <= 3f && player.Velocity.Length() <= 3f;
        float Clearance() => top - (player.GlobalPosition.Y -
            (near - half.X - margin - player.GlobalPosition.X) + half.Y);
        bool FullPrevious() => TryTask10CapsuleCorridor(player, previousShape,
            out float left, out float right, out float supportLeft, out float supportRight) &&
            left >= supportLeft + margin && right <= supportRight - margin &&
            player.IsOnFloor() && HasFloorContact(player, previous);
        void ObserveBoost(MechanicalClawFrame frame, GrappleSurface2D surface) =>
            boostSeen |= frame.State == MechanicalClawState.Boost || frame.BoostConsumed ||
                frame.ReleaseKind == MechanicalClawReleaseKind.Boost;
        bool ClearDock(MechanicalClawTargetResolution selected)
        {
            nativeClear = false;
            if (selected.Surface != target || !selected.Snapshot.Exists ||
                !selected.Snapshot.HasLineOfSight || selected.Snapshot.SurfaceNormal.Dot(Vector2.Left) <= .99f)
                return false;
            var settings = MechanicalClawSettings.Default;
            preflightDock = MechanicalClawArrivalGeometry.DockPoint(selected.Snapshot.WorldAnchor,
                selected.Snapshot.SurfaceNormal, capsule, settings.MinimumRopeLength, settings.ArrivalMargin);
            using var contact = new KinematicCollision2D();
            nativeClear = preflightDock.IsFinite() && !player.TestMove(player.GlobalTransform,
                preflightDock - player.GlobalPosition, contact, player.SafeMargin, false);
            return nativeClear;
        }
        string Snapshot()
        {
            MechanicalClawTargetResolution selected = resolver.ResolveKeyboard(player, Planned());
            bool full = TryTask10CapsuleCorridor(player, previousShape,
                out float left, out float right, out float supportLeft, out float supportRight);
            string failureContacts = string.Empty;
            if (claw.CurrentFrame.Failure != MechanicalClawFailure.None)
            {
                try
                {
                    int count = player.GetSlideCollisionCount();
                    var contacts = new List<string>(4);
                    for (int index = 0; index < Math.Min(count, 4); index++)
                    {
                        using KinematicCollision2D contact = player.GetSlideCollision(index);
                        contacts.Add($"{(contact.GetCollider() as Node)?.GetPath()}:{contact.GetNormal()}");
                    }
                    failureContacts = $" actual_contacts={contacts.Count}/{count}[{string.Join(";", contacts)}]";
                }
                catch (Exception error) { failureContacts = $" actual_contacts_error={error.GetType().Name}"; }
            }
            return $"phase={phase} frames={Engine.GetPhysicsFrames() - stageStart}/300 " +
                $"approach={approachFrames}/40 settle={settleFrames}/12 from={from} target_x={stanceX} " +
                $"limit_x={originLimit} body_half={half} corner={new Vector2(near, top)} margin={margin} " +
                $"side_limit_x={sideLimit} post_left_bottom={postLeftBottom} " +
                $"clearance={Clearance()} player={player.GlobalPosition} velocity={player.Velocity} " +
                $"full_previous_support={full}/{HasFloorContact(player, previous)} " +
                $"capsule_x={left}/{right} support_x={supportLeft}/{supportRight} sample={input.CurrentFrameSequence} " +
                $"move={input.CurrentFrame.MoveAxis} planned={Planned()} sampled_aim={input.KeyboardAimDirection} " +
                $"selected={selected.Surface?.GetPath()} material={selected.Snapshot.Material} " +
                $"anchor={selected.Snapshot.WorldAnchor} normal={selected.Snapshot.SurfaceNormal} " +
                $"los={selected.Snapshot.HasLineOfSight} locked_target={claw.CurrentFrame.LockedTargetRuntimeId} " +
                $"locked_normal={claw.CurrentFrame.SurfaceNormal} dock={claw.CurrentFrame.DockPoint} " +
                $"claw_state={claw.CurrentFrame.State} failure={claw.CurrentFrame.Failure} " +
                $"release={claw.CurrentFrame.ReleaseKind} cast={claw.CurrentFrame.CastId} " +
                $"ground_armed={jumpArmed} launched={launched} launch={launchPosition}/{launchSequence} " +
                $"space_edges={spaceEdges} boost_seen={boostSeen} native_clear={nativeClear} preflight_dock={preflightDock} " +
                $"jumps={jumps}->{motor.AcceptedJumpCount} dashes={dashes}->{motor.AcceptedDashCount} " +
                $"player_id={playerId}->{player.GetInstanceId()} monitor_player_same={monitor.Player == player} " +
                $"hp={hp}->{health.CurrentHealth} recovery={requests}/{recoveries}->" +
                $"{monitor.RecoveryRequested}/{monitor.RecoveryCompleted} next_cast={nextCast}->{claw.CurrentFrame.NextCastId}{failureContacts}";
        }
        void Guard()
        {
            if (input.CurrentFrameSequence > observedSequence)
            {
                observedSequence = input.CurrentFrameSequence;
                if (input.CurrentFrame.JumpPressed) spaceEdges++;
            }
            if (motor.AcceptedJumpCount != lastJumps)
            {
                TestAssert.True(jumpArmed && !launched && priorFullSupport &&
                    motor.AcceptedJumpCount == jumps + 1 && input.CurrentFrameSequence > jumpIssueSequence &&
                    input.CurrentFrame.JumpPressed && input.CurrentFrame.JumpHeld &&
                    Input.IsPhysicalKeyPressed(Key.Space) && input.CurrentFrame.MoveAxis == 0f &&
                    !player.IsOnFloor() && player.Velocity.Y < 0f &&
                    claw.CurrentFrame.State == MechanicalClawState.Idle &&
                    claw.CurrentFrame.NextCastId == nextCast && claw.CurrentTarget == null,
                    $"Grip2's only ordinary jump is a fresh neutral Space from actual full Grip1 support; {Snapshot()}");
                launched = true;
                launchSequence = input.CurrentFrameSequence;
                launchPosition = player.GlobalPosition;
                GD.Print($"TASK10_ASCENT_GRIP2_GROUND_LAUNCH {Snapshot()}");
            }
            lastJumps = motor.AcceptedJumpCount;
            priorFullSupport = FullPrevious();
            TestAssert.True(Engine.GetPhysicsFrames() - stageStart <= 300UL &&
                player.GetInstanceId() == playerId && monitor.Player == player &&
                player.GlobalPosition.IsFinite() && player.Velocity.IsFinite() &&
                health.CurrentHealth == hp && hp > 0 && monitor.RecoveryRequested == requests &&
                monitor.RecoveryCompleted == recoveries &&
                (motor.AcceptedJumpCount == jumps && !launched || motor.AcceptedJumpCount == jumps + 1 && launched) &&
                spaceEdges <= 1 && (!launched || spaceEdges == 1) && !boostSeen &&
                motor.AcceptedDashCount == dashes && claw.CurrentFrame.Failure == MechanicalClawFailure.None &&
                claw.CurrentFrame.NextCastId >= nextCast && claw.CurrentFrame.NextCastId <= nextCast + 1UL,
                $"Task10 Grip2 ground-jump transfer shares300 with same HP/player/recovery, one grounded jump/no Boost and at most one cast; {Snapshot()}");
            if (claw.CurrentFrame.LockedTargetRuntimeId != 0UL)
                TestAssert.True(claw.CurrentFrame.LockedTargetRuntimeId == target.GetInstanceId() &&
                    claw.CurrentFrame.CastId == nextCast && claw.CurrentFrame.SurfaceNormal.Dot(Vector2.Left) > .99f,
                    $"Task10 Grip2 actual unique cast locks the same post's real left face, not a bottom dock; {Snapshot()}");
        }
        void PrepareGuard()
        {
            Guard();
            bool full = TryTask10CapsuleCorridor(player, previousShape,
                out float left, out float right, out float supportLeft, out float supportRight);
            PlayerInputFrame sampled = input.CurrentFrame;
            TestAssert.True(full && left >= supportLeft + margin && right <= supportRight - margin &&
                HasFloorContact(player, previous) && Mathf.Abs(player.GlobalPosition.Y - from.Y) <= 1f &&
                !jumpArmed && !launched && spaceEdges == 0 && motor.AcceptedJumpCount == jumps &&
                claw.CurrentFrame.State == MechanicalClawState.Idle && claw.CurrentFrame.CastId == 0UL &&
                claw.CurrentFrame.NextCastId == nextCast && claw.CurrentTarget == null &&
                claw.ResidencyTarget == null && claw.CurrentFrame.LockedTargetRuntimeId == 0UL &&
                keyboard.ClawEdges == rawClaws && keyboard.AttackEdges == rawAttacks &&
                sampled.KeyboardActions && !sampled.JumpPressed &&
                !sampled.JumpHeld && !sampled.DashPressed && !sampled.AttackPressed && !sampled.ClawPressed &&
                !sampled.InteractPressed && !sampled.ShieldHeld && !sampled.PrimaryPressed &&
                !sampled.PrimaryHeld && !sampled.PrimaryReleased && !sampled.AttackModePressed &&
                !sampled.GrappleModePressed && !sampled.LegacyShieldHeld &&
                !Input.IsActionPressed(InputActions.Claw) && !Input.IsActionPressed(InputActions.Attack) &&
                !Input.IsActionPressed(InputActions.Jump) && !Input.IsActionPressed(InputActions.Dash) &&
                !Input.IsActionPressed(InputActions.MoveUp) && !Input.IsActionPressed(InputActions.MoveDown),
                $"Task10 Grip2 preparation uses only A/D on full original Grip1, without extra action edges; {Snapshot()}");
        }
        void Steer(int neutralBudget)
        {
            var stop = FreeMotionForecast.Neutral(player.Velocity.X, true, motor.MotionSettings,
                motor.ThrusterState.Module, 1d / Engine.PhysicsTicksPerSecond, neutralBudget, 3f);
            TestAssert.True(stop.SpeedThresholdReached,
                "Grip2 neutral endpoint fits the remaining original preparation/settle budget");
            float stopX = player.GlobalPosition.X + stop.NetDistance;
            float stopError = stanceX - stopX;
            bool right = !Ready() && stopError > 1.5f;
            bool left = !Ready() && stopError < -1.5f;
            if (stancePlans.Count < 16)
                stancePlans.Add($"TASK10_ASCENT_GRIP2_NEUTRAL_PLAN physics={Engine.GetPhysicsFrames()} " +
                    $"sample={input.CurrentFrameSequence} neutral_budget={neutralBudget} x={player.GlobalPosition.X:R} " +
                    $"vx={player.Velocity.X:R} predicted_stop_x={stopX:R} forecast_steps={stop.Steps} " +
                    $"target_x={stanceX:R} decision_axis={(right ? 1 : left ? -1 : 0)} " +
                    "timing=callsite-before-next-input-sample actual_immutable_motion_module=true");
            else omittedPlans++;
            SendAction(InputActions.MoveLeft, left); SendAction(InputActions.MoveRight, right);
        }
        async Task Tick()
        {
            PrepareGuard();
            await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
            observe();
            PrepareGuard();
        }
        Action previousGuard = swapApproachGuard(Guard);
        claw.ClawFrameChanged += ObserveBoost;
        try
        {
            GD.Print($"TASK10_ASCENT_GRIP2_KEYBOARD_STANCE_ENTRY {Snapshot()}");
            PrepareGuard();
            MechanicalClawTargetResolution initial = resolver.ResolveKeyboard(player, Planned());
            TryTask10CapsuleCorridor(player, previousShape, out float left, out float right,
                out float supportLeft, out float supportRight);
            TestAssert.True(initial.Surface == platform && previous.GetParent() == support.GetParent() &&
                target.Material == GrappleSurfaceMaterial.TempleMetal && target.UseCollisionHitPoint &&
                half.IsFinite() && half.X > 0f && half.Y >= half.X &&
                Mathf.Abs(body.GlobalTransform.X.Y) < .001f && Mathf.Abs(body.GlobalTransform.Y.X) < .001f &&
                !supportShape.Disabled && !postShape.Disabled &&
                !body.Disabled && !oldPostShape.Disabled &&
                Mathf.Abs(supportShape.GlobalTransform.X.Y) < .001f && Mathf.Abs(supportShape.GlobalTransform.Y.X) < .001f &&
                Mathf.Abs(postShape.GlobalTransform.X.Y) < .001f && Mathf.Abs(postShape.GlobalTransform.Y.X) < .001f &&
                float.IsFinite(motor.MotionSettings.GroundAcceleration) && motor.MotionSettings.GroundAcceleration > 0f &&
                Mathf.Abs(from.X - stanceX) <= 110f && stanceX - 3f - half.X >= supportLeft + margin &&
                stanceX - 3f - half.X >= oldRight + margin &&
                stanceX + 3f + half.X <= supportRight - margin,
                $"Task10 Grip2 prepares one full-support launch stance to the right of its old solid post; {Snapshot()}");
            keyboard.ReleaseAll();
            while (Engine.GetPhysicsFrames() - stageStart < 40UL && !Ready())
            {
                // The existing preparation, settle and vertical rise still share52.
                Steer(52 - checked((int)(Engine.GetPhysicsFrames() - stageStart))); await Tick();
                approachFrames = Engine.GetPhysicsFrames() - stageStart;
            }
            SendAction(InputActions.MoveLeft, false); SendAction(InputActions.MoveRight, false);
            ulong releasedSequence = input.CurrentFrameSequence, settleStart = Engine.GetPhysicsFrames();
            bool correctionHeld = false;
            while (Engine.GetPhysicsFrames() - settleStart < 12UL && Engine.GetPhysicsFrames() - stageStart < 52UL)
            {
                Steer(Math.Min(12 - checked((int)(Engine.GetPhysicsFrames() - settleStart)),
                    52 - checked((int)(Engine.GetPhysicsFrames() - stageStart))));
                bool moving = Input.IsActionPressed(InputActions.MoveLeft) || Input.IsActionPressed(InputActions.MoveRight);
                if (moving || correctionHeld) releasedSequence = input.CurrentFrameSequence;
                correctionHeld = moving;
                await Tick(); settleFrames = Engine.GetPhysicsFrames() - settleStart;
                if (Ready() && input.CurrentFrameSequence > releasedSequence && input.CurrentFrame.MoveAxis == 0f) break;
            }
            GD.Print($"TASK10_ASCENT_GRIP2_KEYBOARD_STANCE_END {Snapshot()}");
            TestAssert.True(Ready() && approachFrames <= 40UL && settleFrames <= 12UL &&
                Engine.GetPhysicsFrames() - stageStart <= 52UL && input.CurrentFrameSequence > releasedSequence &&
                input.CurrentFrame.MoveAxis == 0f && FullPrevious() &&
                !input.CurrentFrame.JumpPressed && !input.CurrentFrame.JumpHeld &&
                !Input.IsPhysicalKeyPressed(Key.Space) && armGroundJump != null,
                $"Grip2 arms only from stopped full original Grip1 with sampled released Space; {Snapshot()}");
            armGroundJump();
            jumpArmed = true;
            priorFullSupport = FullPrevious();
            jumpIssueSequence = input.CurrentFrameSequence;
            phase = "ground-jump";
            SendAction(InputActions.Jump, true);
            bool readyToCast = false;
            while (Engine.GetPhysicsFrames() - stageStart < 52UL)
            {
                Guard();
                await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
                ulong risePhysics = Engine.GetPhysicsFrames();
                await tree.ToSignal(tree.CreateTimer(0d, true, true), SceneTreeTimer.SignalName.Timeout);
                TestAssert.Equal(risePhysics, Engine.GetPhysicsFrames(),
                    "Grip2 reads the completed rise in the same budgeted physics tick");
                observe();
                Guard();
                TestAssert.True(Engine.GetPhysicsFrames() - stageStart <= 52UL &&
                    claw.CurrentFrame.State == MechanicalClawState.Idle && claw.CurrentFrame.NextCastId == nextCast &&
                    Mathf.Abs(player.GlobalPosition.X - stanceX) <= 3f && input.CurrentFrame.MoveAxis == 0f &&
                    input.CurrentFrame.JumpHeld && Input.IsPhysicalKeyPressed(Key.Space),
                    $"Grip2 rises vertically with its single held Space before any cast; {Snapshot()}");
                if (launched && !player.IsOnFloor() && player.Velocity.Y >= -100f && player.Velocity.Y < 0f &&
                    player.Velocity.Y >= -motor.Tuning.JumpCutSpeed &&
                    ClearDock(resolver.ResolveKeyboard(player, Planned())))
                { readyToCast = true; break; }
                TestAssert.True(!launched || player.Velocity.Y < 0f,
                    $"Grip2 must find its exact clear left-face cast while still rising; {Snapshot()}");
            }
            TestAssert.True(readyToCast && launched && spaceEdges == 1 &&
                player.GlobalPosition.DistanceTo(resolver.ResolveKeyboard(player, Planned()).Snapshot.WorldAnchor) <=
                    MechanicalClawSettings.Default.MaxRange &&
                player.GetViewportRect().HasPoint(player.GetCanvasTransform() * aim),
                $"Grip2 near-apex handoff has one real ground jump, exact on-screen left-face target and native clear body path; {Snapshot()}");
            GD.Print($"TASK10_ASCENT_GRIP2_APEX_CAST_READY {Snapshot()}");
            phase = "original-Task4";
            await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player, support, clawRequired: true);
            Guard();
            TestAssert.True(motor.AcceptedJumpCount == jumps + 1 && launched && spaceEdges == 1 && !boostSeen &&
                claw.CurrentFrame.NextCastId == nextCast + 1UL &&
                TryTask10CapsuleCorridor(player, supportShape, out _, out _, out _, out _) &&
                HasFloorContact(player, support),
                $"Grip2 finishes one grounded jump plus unchanged K/cancel with one cast and full target support; {Snapshot()}");
            for (int tail = 0; tail < 3; tail++)
            {
                await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
                observe(); Guard();
                TestAssert.True(TryTask10CapsuleCorridor(player, supportShape, out _, out _, out _, out _) &&
                    player.IsOnFloor() && HasFloorContact(player, support),
                    $"Grip2's complete capsule remains supported through every neutral tail; {Snapshot()}");
            }
            GD.Print($"TASK10_ASCENT_GRIP2_GROUND_JUMP_TRANSFER_OK {Snapshot()}");
        }
        catch { GD.Print($"TASK10_ASCENT_GRIP2_KEYBOARD_STANCE_FAILED {Snapshot()}"); throw; }
        finally
        {
            try { keyboard.ReleaseAll(); }
            finally
            {
                claw.ClawFrameChanged -= ObserveBoost;
                swapApproachGuard(previousGuard);
                foreach (string row in stancePlans) GD.Print(row);
                GD.Print($"TASK10_ASCENT_GRIP2_NEUTRAL_PLAN_END rows={stancePlans.Count}/16 omitted={omittedPlans} " +
                    "original_approach_cap=40 original_settle_cap=12 shared_prepare_rise_cap=52 original_stage_cap=300");
            }
        }
    }

    private static async Task PrepareTask10KeyboardAscentGrip1(SceneTree tree,
        CharacterBody2D player, RouteMonitor monitor, Action observe,
        StaticBody2D landing, StaticBody2D gripPost, ulong readyStart)
    {
        // Explore arrives to the right of LiftBackLanding's own post. Its NW axis
        // hits that nearer post, so walk below it before the original Grip1 cast.
        // Natural retract above keeps its no-input/2px contract; this preparation
        // consumes only the unused part of the same 60-physics-frame stage.
        ulong preparationStart = Engine.GetPhysicsFrames();
        ulong waitFrames = preparationStart - readyStart;
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        HealthComponent health = player.GetNode<HealthComponent>("Health");
        MechanicalClawController claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
        CollisionShape2D landingShape = landing.GetNode<CollisionShape2D>("Collision");
        CollisionShape2D gripShape = gripPost.GetNode<CollisionShape2D>("Collision");
        var rectangle = (RectangleShape2D)gripShape.Shape;
        GrappleSurface2D target = gripPost.GetNode<GrappleSurface2D>("GrappleSurfaceProfile");
        GrappleSurface2D previous = landing.GetParent().GetNode<GrappleSurface2D>(
            "LiftBackLandingGrip/GrappleSurfaceProfile");
        Vector2 aim = new(gripPost.GlobalPosition.X,
            gripPost.GlobalPosition.Y - rectangle.Size.Y / 2f + 10f);
        float postRight = gripShape.ToGlobal(new Vector2(rectangle.Size.X / 2f, 0f)).X;
        float stanceX = postRight + player.GlobalPosition.Y - aim.Y;
        Vector2 start = player.GlobalPosition;
        ulong playerId = player.GetInstanceId(), nextCast = claw.CurrentFrame.NextCastId;
        int hp = health.CurrentHealth, requests = monitor.RecoveryRequested,
            recoveries = monitor.RecoveryCompleted, jumps = motor.AcceptedJumpCount,
            dashes = motor.AcceptedDashCount;
        var resolver = new MechanicalClawTargetResolver();
        Vector2 Planned() => PlayerKeyboardAimModel.ResolveDirection(aim - player.GlobalPosition, -1);
        bool Ready() => Mathf.Abs(player.GlobalPosition.X - stanceX) <= 3f &&
            player.Velocity.Length() <= 3f;
        var stancePlans = new List<string>(16);
        int omittedPlans = 0;
        string Snapshot()
        {
            MechanicalClawTargetResolution selected = resolver.ResolveKeyboard(player, Planned());
            bool full = TryTask10CapsuleCorridor(player, landingShape,
                out float left, out float right, out float supportLeft, out float supportRight);
            return $"wait_frames={waitFrames} preparation_frames={Engine.GetPhysicsFrames() - preparationStart} " +
                $"total_frames={Engine.GetPhysicsFrames() - readyStart}/60 from={start} target_x={stanceX} " +
                $"post_right={postRight} aim={aim} player={player.GlobalPosition} velocity={player.Velocity} " +
                $"full_support={full} upward_contact={HasFloorContact(player, landing)} " +
                $"capsule_x={left}/{right} support_x={supportLeft}/{supportRight} " +
                $"sample={input.CurrentFrameSequence} move={input.CurrentFrame.MoveAxis} " +
                $"sampled_aim={input.KeyboardAimDirection} planned={Planned()} " +
                $"selected={selected.Surface?.GetPath()} material={selected.Snapshot.Material} " +
                $"anchor={selected.Snapshot.WorldAnchor} los={selected.Snapshot.HasLineOfSight} " +
                $"hp={hp}->{health.CurrentHealth} recovery={requests}/{recoveries}->" +
                $"{monitor.RecoveryRequested}/{monitor.RecoveryCompleted} next_cast={nextCast}->" +
                $"{claw.CurrentFrame.NextCastId}";
        }
        void Guard()
        {
            bool full = TryTask10CapsuleCorridor(player, landingShape,
                out float left, out float right, out float supportLeft, out float supportRight);
            PlayerInputFrame sampled = input.CurrentFrame;
            TestAssert.True(Engine.GetPhysicsFrames() - readyStart <= 60UL &&
                player.GetInstanceId() == playerId && monitor.Player == player &&
                player.GlobalPosition.IsFinite() && player.Velocity.IsFinite() &&
                full && left >= supportLeft + 2f && right <= supportRight - 2f &&
                HasFloorContact(player, landing) && Mathf.Abs(player.GlobalPosition.Y - start.Y) <= 2f &&
                health.CurrentHealth == hp && hp > 0 && monitor.RecoveryRequested == requests &&
                monitor.RecoveryCompleted == recoveries && motor.AcceptedJumpCount == jumps &&
                motor.AcceptedDashCount == dashes && claw.CurrentFrame.State == MechanicalClawState.Idle &&
                claw.CurrentFrame.Failure == MechanicalClawFailure.None && claw.CurrentFrame.CastId == 0UL &&
                claw.CurrentFrame.NextCastId == nextCast && claw.CurrentTarget == null &&
                claw.ResidencyTarget == null && claw.CurrentFrame.LockedTargetRuntimeId == 0UL &&
                sampled.KeyboardActions && !sampled.JumpPressed &&
                !sampled.JumpHeld && !sampled.DashPressed && !sampled.AttackPressed &&
                !sampled.ClawPressed && !Input.IsPhysicalKeyPressed(Key.K) && !sampled.InteractPressed &&
                !sampled.ShieldHeld && !sampled.PrimaryPressed && !sampled.PrimaryHeld &&
                !sampled.PrimaryReleased && !sampled.AttackModePressed &&
                !sampled.GrappleModePressed && !sampled.LegacyShieldHeld,
                $"Task10 keyboard Grip1 stance preserves full original landing, HP/recovery, Idle and input edges; {Snapshot()}");
        }
        GD.Print($"TASK10_ASCENT_GRIP1_KEYBOARD_STANCE_ENTRY {Snapshot()}");
        try
        {
            Guard();
            MechanicalClawTargetResolution initial = resolver.ResolveKeyboard(player, Planned());
            TestAssert.True(initial.Surface == previous || initial.Surface == target,
                $"Task10 Grip1 preparation only handles the exact previous landing post; {Snapshot()}");
            TryTask10CapsuleCorridor(player, landingShape, out float left, out float right,
                out float supportLeft, out float supportRight);
            float radius = (right - left) / 2f;
            TestAssert.True(float.IsFinite(motor.MotionSettings.GroundAcceleration) &&
                motor.MotionSettings.GroundAcceleration > 0f && stanceX - 3f - radius >= supportLeft + 2f &&
                stanceX + 3f + radius <= supportRight - 2f,
                "Task10 Grip1 analytical NW stance fits fully within the original landing");
            KeyboardRouteInputDriver.Current.ReleaseAll();
            ulong releasedSequence = input.CurrentFrameSequence;
            bool correctionHeld = false;
            while (Engine.GetPhysicsFrames() - readyStart < 60UL)
            {
                int remaining = 60 - checked((int)(Engine.GetPhysicsFrames() - readyStart));
                var stop = FreeMotionForecast.Neutral(player.Velocity.X, true, motor.MotionSettings,
                    motor.ThrusterState.Module, 1d / Engine.PhysicsTicksPerSecond, remaining, 3f);
                TestAssert.True(stop.SpeedThresholdReached,
                    "Grip1 neutral endpoint fits only the unused original60 stage budget");
                float stopX = player.GlobalPosition.X + stop.NetDistance;
                float stopError = stanceX - stopX;
                bool rightward = !Ready() && stopError > 1.5f;
                bool leftward = !Ready() && stopError < -1.5f;
                if (stancePlans.Count < 16)
                    stancePlans.Add($"TASK10_ASCENT_GRIP1_NEUTRAL_PLAN physics={Engine.GetPhysicsFrames()} " +
                        $"sample={input.CurrentFrameSequence} remaining={remaining}/60 x={player.GlobalPosition.X:R} " +
                        $"vx={player.Velocity.X:R} predicted_stop_x={stopX:R} forecast_steps={stop.Steps} " +
                        $"target_x={stanceX:R} decision_axis={(rightward ? 1 : leftward ? -1 : 0)} " +
                        "timing=callsite-before-next-input-sample actual_immutable_motion_module=true");
                else omittedPlans++;
                SendAction(InputActions.MoveLeft, leftward);
                SendAction(InputActions.MoveRight, rightward);
                bool moving = leftward || rightward;
                if (moving || correctionHeld) releasedSequence = input.CurrentFrameSequence;
                correctionHeld = moving;
                await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
                observe();
                Guard();
                if (Ready() && input.CurrentFrameSequence > releasedSequence &&
                    input.CurrentFrame.MoveAxis == 0f) break;
            }
            MechanicalClawTargetResolution final = resolver.ResolveKeyboard(player, Planned());
            GD.Print($"TASK10_ASCENT_GRIP1_KEYBOARD_STANCE_END {Snapshot()}");
            TestAssert.True(Ready() && input.CurrentFrameSequence > releasedSequence &&
                input.CurrentFrame.MoveAxis == 0f && Planned().Dot(new Vector2(-1f, -1f).Normalized()) > .99f &&
                final.Surface == target && final.Snapshot.HasLineOfSight &&
                player.GlobalPosition.DistanceTo(final.Snapshot.WorldAnchor) <= MechanicalClawSettings.Default.MaxRange &&
                player.GetViewportRect().HasPoint(player.GetCanvasTransform() * aim),
                $"Task10 keyboard Grip1 stops and resolves the same on-screen above-post target in the original60; {Snapshot()}");
        }
        catch { GD.Print($"TASK10_ASCENT_GRIP1_KEYBOARD_STANCE_FAILED {Snapshot()}"); throw; }
        finally
        {
            SendAction(InputActions.MoveLeft, false);
            SendAction(InputActions.MoveRight, false);
            foreach (string row in stancePlans) GD.Print(row);
            GD.Print($"TASK10_ASCENT_GRIP1_NEUTRAL_PLAN_END rows={stancePlans.Count}/16 omitted={omittedPlans} original_stage_cap=60");
        }
        // Planner evidence only. Task4ReachSupport still proves its fresh real K,
        // actual NW target/LOS/cast identity and original above-post/full landing.
    }

    private static async Task WaitTask10SupportedClawReady(SceneTree tree,
        CharacterBody2D player, RouteMonitor monitor, Action observe, StaticBody2D landing,
        string context = "Grip1", string logPrefix = "TASK10_ASCENT_GRIP1_READY")
    {
        MechanicalClawController claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        HealthComponent health = player.GetNode<HealthComponent>("Health");
        Vector2 entryPosition = player.GlobalPosition;
        int entryHealth = health.CurrentHealth;
        int entryRequests = monitor.RecoveryRequested;
        int entryRecoveries = monitor.RecoveryCompleted;
        int entryJumps = motor.AcceptedJumpCount;
        int entryDashes = motor.AcceptedDashCount;
        ulong entryNextCast = claw.CurrentFrame.NextCastId;
        int waited = 0;
        bool retractSeen = false;

        string Snapshot() => $"physics={Engine.GetPhysicsFrames()} input_sequence=" +
            $"{input.CurrentFrameSequence} waited_frames={waited}/60 " +
            $"state={claw.CurrentFrame.State} cast={claw.CurrentFrame.CastId} " +
            $"next_cast={entryNextCast}->{claw.CurrentFrame.NextCastId} " +
            $"failure={claw.CurrentFrame.Failure} target={claw.CurrentTarget?.Name} " +
            $"locked_target={claw.CurrentFrame.LockedTargetRuntimeId} " +
            $"residency_target={claw.ResidencyTarget?.Name} entry_position={entryPosition} " +
            $"position={player.GlobalPosition} velocity={player.Velocity} " +
            $"support={landing.GetPath()}#{landing.GetInstanceId()} " +
            $"upward_contact={HasFloorContact(player, landing)} " +
            $"hp={entryHealth}->{health.CurrentHealth} recoveries=" +
            $"{entryRequests}/{entryRecoveries}->{monitor.RecoveryRequested}/{monitor.RecoveryCompleted} " +
            $"jumps={entryJumps}->{motor.AcceptedJumpCount} dashes={entryDashes}->{motor.AcceptedDashCount}";

        void CheckObservation()
        {
            MechanicalClawFrame frame = claw.CurrentFrame;
            TestAssert.True(frame.Failure == MechanicalClawFailure.None &&
                (frame.State is MechanicalClawState.Released or MechanicalClawState.Retract or
                    MechanicalClawState.Idle) &&
                !(retractSeen && frame.State == MechanicalClawState.Released) &&
                frame.NextCastId == entryNextCast &&
                player.GlobalPosition.IsFinite() && player.Velocity.IsFinite() &&
                player.GlobalPosition.DistanceTo(entryPosition) <= 2f &&
                HasFloorContact(player, landing) && health.CurrentHealth == entryHealth &&
                monitor.RecoveryRequested == entryRequests &&
                monitor.RecoveryCompleted == entryRecoveries &&
                motor.AcceptedJumpCount == entryJumps && motor.AcceptedDashCount == entryDashes,
                $"Task10 {context} readiness preserves the supported no-input natural retract; {Snapshot()}");
            retractSeen |= frame.State == MechanicalClawState.Retract;
        }

        GD.Print($"{logPrefix}_ENTRY {Snapshot()}");
        try
        {
            CheckObservation();
            while (claw.CurrentFrame.State != MechanicalClawState.Idle && waited < 60)
            {
                await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
                waited++;
                observe(); // Original monitor + evidence on every awaited physics observation.
                CheckObservation();
            }
            TestAssert.True(claw.CurrentFrame.State == MechanicalClawState.Idle &&
                claw.CurrentFrame.Failure == MechanicalClawFailure.None &&
                claw.CurrentTarget == null && claw.ResidencyTarget == null &&
                claw.CurrentFrame.LockedTargetRuntimeId == 0UL,
                $"Task10 {context} readiness reaches actual target-free Idle within 60 physics waits; {Snapshot()}");
            GD.Print($"{logPrefix}_OK {Snapshot()}");
        }
        catch
        {
            GD.Print($"{logPrefix}_FAILED {Snapshot()}");
            throw;
        }
    }

    // Passive and local to the Grip5 encounter. PhysicsFrame covers CastAt's inner waits;
    // it precedes node _PhysicsProcess, so neither its input nor contacts are same-tick final data.
    private sealed class Task10PendulumEntryDiagnostic : IDisposable
    {
        private const string Encounter = "canyon.v2.encounter.pendulum-gallery";
        private readonly SceneTree _tree;
        private readonly CharacterBody2D _player;
        private readonly RouteMonitor _monitor;
        private readonly StaticBody2D _shelf;
        private readonly string _variant;
        private readonly ulong _start = Engine.GetPhysicsFrames();
        private PlayerInputReader _input;
        private PlayerMotor _motor;
        private PlayerActionModeController _modes;
        private HealthComponent _health;
        private MechanicalClawController _claw;
        private CanyonEncounterGroup _group;
        private ulong? _lastPhysics;
        private string _lastClaw;
        private string _lastGroup;
        private string _lastSupport;
        private int _lastJumps;
        private int _lastDashes;
        private bool _lostSupport;
        private bool _laterSupport;
        private bool _belowShelf;
        private float? _lastBottomMinusShelfTop;
        private int _physicsObservations;
        private int _lines;
        private int _transitionLines;
        private int _suppressed;
        private int _faults;
        private bool _physicsSubscribed;
        private bool _clawSubscribed;
        private bool _disposed;

        public Task10PendulumEntryDiagnostic(SceneTree tree, CharacterBody2D player,
            RouteMonitor monitor, SeamlessPrologueWorld world, StaticBody2D shelf,
            Task10RouteVariant variant)
        {
            _tree = tree; _player = player; _monitor = monitor;
            _shelf = shelf; _variant = variant.ToString();
            Safely(() =>
            {
                _input = player.GetNodeOrNull<PlayerInputReader>("Input");
                _motor = player.GetNodeOrNull<PlayerMotor>("Motor");
                _modes = player.GetNodeOrNull<PlayerActionModeController>("ActionModes");
                _health = player.GetNodeOrNull<HealthComponent>("Health");
                _claw = player.GetNodeOrNull<MechanicalClawController>("MechanicalClaw");
                _group = world.FindChildren("*", "", true, false).OfType<CanyonEncounterGroup>()
                    .SingleOrDefault(group => group.EncounterId.ToString() == Encounter);
                _lastJumps = GodotObject.IsInstanceValid(_motor) ? _motor.AcceptedJumpCount : 0;
                _lastDashes = GodotObject.IsInstanceValid(_motor) ? _motor.AcceptedDashCount : 0;
                _lastSupport = Support(player);
                if (TryBounds(player, "BodyCollider", out Rect2 pb) &&
                    TryBounds(shelf, "Collision", out Rect2 sb))
                    _lastBottomMinusShelfTop = pb.End.Y - sb.Position.Y;
                _tree.PhysicsFrame += ObservePhysics;
                _physicsSubscribed = true;
                if (GodotObject.IsInstanceValid(_claw))
                {
                    _claw.ClawFrameChanged += ObserveClaw;
                    _clawSubscribed = true;
                }
            });
            Boundary("before-original-encounter");
        }

        public void ObserveDriver() => Safely(() => Observe("driver-after-original-observe",
            "await-resume/prior-node-input-and-contact-possible", false));
        private void ObservePhysics() => Safely(() => Observe("PhysicsFrame",
            "before-node-PhysicsProcess/prior-input-and-slide-contacts", true));
        private void ObserveClaw(MechanicalClawFrame frame, GrappleSurface2D target) =>
            Safely(() => Observe("ClawFrameChanged",
                "after-claw-publication/node-order-dependent/edges-may-be-consumed", false,
                frame, target));

        private void Observe(string source, string timing, bool actualPhysics,
            MechanicalClawFrame? published = null, GrappleSurface2D publishedTarget = null)
        {
            if (_disposed || Engine.GetPhysicsFrames() - _start > 240) return;
            bool first90 = false;
            if (actualPhysics && _lastPhysics != Engine.GetPhysicsFrames())
            {
                _lastPhysics = Engine.GetPhysicsFrames();
                _physicsObservations++;
                first90 = _physicsObservations <= 90;
            }
            if (!GodotObject.IsInstanceValid(_player))
            {
                if (first90) Write(source, timing, "player-invalid", firstPhysics: true);
                return;
            }
            string support = Support(_player);
            var transitions = new List<string>();
            if (support != _lastSupport) transitions.Add("support-change");
            if (!_lostSupport && _lastSupport != "none" && support == "none")
            { _lostSupport = true; transitions.Add("first-lost-support"); }
            if (_lostSupport && !_laterSupport && support != "none")
            { _laterSupport = true; transitions.Add("first-later-support"); }
            _lastSupport = support;
            if (GodotObject.IsInstanceValid(_motor))
            {
                if (_motor.AcceptedJumpCount != _lastJumps) transitions.Add("jump-accepted");
                if (_motor.AcceptedDashCount != _lastDashes) transitions.Add("dash-accepted");
                _lastJumps = _motor.AcceptedJumpCount; _lastDashes = _motor.AcceptedDashCount;
            }
            if (TryBounds(_player, "BodyCollider", out Rect2 playerBounds) &&
                TryBounds(_shelf, "Collision", out Rect2 shelfBounds))
            {
                float bottomMinusTop = playerBounds.End.Y - shelfBounds.Position.Y;
                if (!_belowShelf && _lastBottomMinusShelfTop.HasValue &&
                    _lastBottomMinusShelfTop.Value <= 0.5f && bottomMinusTop > 0.5f &&
                    _player.Velocity.Y > 0)
                { _belowShelf = true; transitions.Add("first-downward-below-entry-shelf"); }
                _lastBottomMinusShelfTop = bottomMinusTop;
            }
            MechanicalClawFrame claw = published ?? (GodotObject.IsInstanceValid(_claw)
                ? _claw.CurrentFrame : MechanicalClawFrame.Idle());
            GrappleSurface2D target = published.HasValue ? publishedTarget :
                GodotObject.IsInstanceValid(_claw) ? _claw.CurrentTarget : null;
            string clawState = $"{claw.State}/{claw.CastId}/{claw.NextCastId}/{claw.Failure}/" +
                $"{claw.LockedTargetRuntimeId}/{Identity(target)}";
            if (clawState != _lastClaw) transitions.Add("claw-state-cast-target-change");
            _lastClaw = clawState;
            string groupState = GroupState();
            if (groupState != _lastGroup) transitions.Add("group-active-batch-live-change");
            _lastGroup = groupState;
            if (first90 || transitions.Count > 0)
                Write(source, timing, string.Join(',', transitions), published, publishedTarget,
                    firstPhysics: first90);
        }

        public void Boundary(string moment) => Safely(() => Write("boundary",
            "synchronous-boundary/not-extra-physics", moment, boundary: true));
        public void Failure(Exception error) => Boundary($"original-failure type={error.GetType().Name} " +
            $"message={OneLine(error.Message)}");

        private void Write(string source, string timing, string transition,
            MechanicalClawFrame? published = null, GrappleSurface2D publishedTarget = null,
            bool boundary = false, bool firstPhysics = false)
        {
            // Reserve 90 lines for distinct PhysicsFrame samples, irrespective of event density.
            if (!boundary && (_lines >= 160 || !firstPhysics && _transitionLines >= 70))
            { _suppressed++; return; }
            if (!boundary) { _lines++; if (!firstPhysics) _transitionLines++; }
            string prefix = $"TASK10_PENDULUM_ENTRY_DIAGNOSTIC variant={_variant} source={source} " +
                $"physics={Engine.GetPhysicsFrames()} elapsed={Engine.GetPhysicsFrames() - _start}/240 " +
                $"distinct_physics_observations={_physicsObservations} timing={timing} transition={transition}";
            if (!GodotObject.IsInstanceValid(_player))
            { GD.Print($"{prefix} player=invalid {GroupState()}"); return; }
            PlayerInputFrame input = GodotObject.IsInstanceValid(_input) ? _input.CurrentFrame : default;
            MechanicalClawFrame claw = published ?? (GodotObject.IsInstanceValid(_claw)
                ? _claw.CurrentFrame : MechanicalClawFrame.Idle());
            GrappleSurface2D target = published.HasValue ? publishedTarget :
                GodotObject.IsInstanceValid(_claw) ? _claw.CurrentTarget : null;
            string bounds = "player_bounds=unavailable shelf_bounds=unavailable support_margin=unavailable";
            if (TryBounds(_player, "BodyCollider", out Rect2 pb) &&
                TryBounds(_shelf, "Collision", out Rect2 sb))
                bounds = $"player_shape_world_aabb={pb} shelf_shape_world_aabb={sb} " +
                    $"entry_shelf={Identity(_shelf)} horizontal_overlap=" +
                    $"{Mathf.Min(pb.End.X, sb.End.X) - Mathf.Max(pb.Position.X, sb.Position.X)} " +
                    $"left_inset={pb.Position.X - sb.Position.X} right_inset={sb.End.X - pb.End.X} " +
                    $"bottom_minus_shelf_top={pb.End.Y - sb.Position.Y}";
            GD.Print($"{prefix} input_sequence=" +
                $"{(GodotObject.IsInstanceValid(_input) ? _input.CurrentFrameSequence.ToString() : "invalid")} " +
                $"sampled_move={input.MoveAxis} sampled_aim_up_vector={input.Aim} " +
                $"sampled_jump_edge_held={input.JumpPressed}/{input.JumpHeld} sampled_dash_edge={input.DashPressed} " +
                $"sampled_primary_edge_held_release={input.PrimaryPressed}/{input.PrimaryHeld}/{input.PrimaryReleased} " +
                $"sampled_shield={input.ShieldHeld} sampled_attack_grapple_mode_edges=" +
                $"{input.AttackModePressed}/{input.GrappleModePressed} sampled_slot={input.RequestedSlot} " +
                $"sampled_mouse_world={input.MouseWorld} raw_not_accepted_left_right_up=" +
                $"{Input.IsActionPressed(InputActions.MoveLeft)}/{Input.IsActionPressed(InputActions.MoveRight)}/" +
                $"{Input.IsActionPressed(InputActions.MoveUp)} raw_not_accepted_jump_held_edge=" +
                $"{Input.IsActionPressed(InputActions.Jump)}/{Input.IsActionJustPressed(InputActions.Jump)} " +
                $"raw_not_accepted_primary_shield_attackmode_grapplemode=" +
                $"{Input.IsActionPressed(InputActions.PrimaryAction)}/{Input.IsActionPressed(InputActions.Shield)}/" +
                $"{Input.IsActionPressed(InputActions.SelectAttackMode)}/{Input.IsActionPressed(InputActions.SelectGrappleMode)} " +
                $"raw_mouse_buttons={Input.IsMouseButtonPressed(MouseButton.Left)}/{Input.IsMouseButtonPressed(MouseButton.Right)} " +
                $"mouse_viewport={(GodotObject.IsInstanceValid(_input) ? _input.LastObservedMouseViewportPosition.ToString() : "invalid")} " +
                $"mode={(GodotObject.IsInstanceValid(_modes) ? _modes.CurrentMode.ToString() : "invalid")} " +
                $"player={_player.GlobalPosition} velocity={_player.Velocity} floor={_player.IsOnFloor()} " +
                $"support={Support(_player)} contacts={Contacts(_player)} {bounds} " +
                $"accepted_jumps_dashes={(GodotObject.IsInstanceValid(_motor) ? $"{_motor.AcceptedJumpCount}/{_motor.AcceptedDashCount}" : "invalid")} " +
                $"hp={(GodotObject.IsInstanceValid(_health) ? _health.CurrentHealth.ToString() : "invalid")} " +
                $"recovery_requested_completed={_monitor.RecoveryRequested}/{_monitor.RecoveryCompleted} " +
                $"claw_valid={GodotObject.IsInstanceValid(_claw)} claw={claw.State} cast={claw.CastId} next_cast={claw.NextCastId} " +
                $"failure={claw.Failure} anchor={claw.AnchorPoint} locked_target={claw.LockedTargetRuntimeId} " +
                $"target={Identity(target)} residency_target=" +
                $"{Identity(GodotObject.IsInstanceValid(_claw) ? _claw.ResidencyTarget : null)} {GroupState()} {Actors()}");
        }

        private string GroupState() => GodotObject.IsInstanceValid(_group)
            ? $"group={Identity(_group)} active={_group.IsActive} batch={_group.CurrentBatch} " +
              $"live={_group.LiveActorCount} complete={_group.IsComplete}" : "group=invalid";
        private string Actors()
        {
            if (!GodotObject.IsInstanceValid(_group)) return "actors=unavailable";
            Node root = _group.GetNodeOrNull(_group.ActorRootPath);
            if (!GodotObject.IsInstanceValid(root)) return "actors=root-invalid";
            var actors = new List<string>();
            foreach (Node child in root.GetChildren())
            {
                if (!GodotObject.IsInstanceValid(child) || child is not Node2D actor ||
                    !actor.Name.ToString().StartsWith(Encounter.Replace('.', '_'), StringComparison.Ordinal)) continue;
                string state = actor switch
                {
                    RustShellSquire rust => rust.CurrentState.ToString(),
                    GraveLampMoth moth => moth.CurrentState.ToString(),
                    BellBackLaborer laborer => laborer.CurrentState.ToString(),
                    BellBoltSentry sentry => sentry.CurrentFrame.State.ToString(),
                    Knight.Enemies.Skitter.CanyonSkitter skitter => skitter.CurrentFrame.State.ToString(),
                    _ => "not-exposed-by-known-actor-type"
                };
                actors.Add($"identity={Identity(actor)} type={actor.GetType().Name} position={actor.GlobalPosition} " +
                    (actor is CharacterBody2D body ? $"velocity={body.Velocity} floor={body.IsOnFloor()} " +
                        $"support={Support(body)} contacts={Contacts(body)} " : "velocity_support=not-character-body ") +
                    $"state={state}");
            }
            return $"actors=[{string.Join(';', actors)}]";
        }
        private static string Support(CharacterBody2D body)
        {
            if (!GodotObject.IsInstanceValid(body)) return "invalid";
            if (!body.IsOnFloor()) return "none";
            var supports = new List<string>();
            for (int i = 0; i < body.GetSlideCollisionCount(); i++)
            {
                KinematicCollision2D contact = body.GetSlideCollision(i);
                if (GodotObject.IsInstanceValid(contact) && contact.GetNormal().Y < -0.5f)
                    supports.Add(Identity(contact.GetCollider() as GodotObject));
            }
            return supports.Count == 0 ? "none" : string.Join(',', supports);
        }
        private static string Contacts(CharacterBody2D body)
        {
            var contacts = new List<string>();
            for (int i = 0; i < body.GetSlideCollisionCount(); i++)
            {
                KinematicCollision2D contact = body.GetSlideCollision(i);
                if (GodotObject.IsInstanceValid(contact)) contacts.Add($"index={i} collider=" +
                    $"{Identity(contact.GetCollider() as GodotObject)} normal={contact.GetNormal()} position={contact.GetPosition()}");
            }
            return $"[{string.Join(';', contacts)}]";
        }
        private static bool TryBounds(Node body, string path, out Rect2 bounds)
        {
            bounds = default;
            if (!GodotObject.IsInstanceValid(body)) return false;
            CollisionShape2D collider = body.GetNodeOrNull<CollisionShape2D>(path);
            if (!GodotObject.IsInstanceValid(collider) || !GodotObject.IsInstanceValid(collider.Shape)) return false;
            Rect2 local = collider.Shape.GetRect();
            bounds = new Rect2(collider.GlobalTransform * local.Position, Vector2.Zero);
            foreach (Vector2 corner in new[] { new Vector2(local.End.X, local.Position.Y),
                local.End, new Vector2(local.Position.X, local.End.Y) })
                bounds = bounds.Expand(collider.GlobalTransform * corner);
            return true;
        }
        private static string Identity(GodotObject value) => !GodotObject.IsInstanceValid(value)
            ? "none-or-invalid" : value is Node node
                ? $"{(node.IsInsideTree() ? node.GetPath().ToString() : "outside-tree")}#{node.GetInstanceId()}"
                : $"#{value.GetInstanceId()}";
        private static string OneLine(string value) => value.Replace('\r', ' ').Replace('\n', ' ');
        private void Safely(Action action)
        {
            try { action(); }
            catch (Exception error)
            {
                _faults++;
                if (_faults > 8) return;
                try { GD.Print($"TASK10_PENDULUM_ENTRY_DIAGNOSTIC source=diagnostic-error " +
                    $"variant={_variant} physics={Engine.GetPhysicsFrames()} type={error.GetType().Name} " +
                    $"message={OneLine(error.Message)} fault={_faults}/8"); }
                catch { /* Never replace the original route exception. */ }
            }
        }
        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            Safely(() =>
            {
                if (_physicsSubscribed && GodotObject.IsInstanceValid(_tree)) _tree.PhysicsFrame -= ObservePhysics;
                _physicsSubscribed = false;
            });
            Safely(() =>
            {
                if (_clawSubscribed && GodotObject.IsInstanceValid(_claw)) _claw.ClawFrameChanged -= ObserveClaw;
                _clawSubscribed = false;
            });
            Safely(() => GD.Print($"TASK10_PENDULUM_ENTRY_DIAGNOSTIC source=finally-cleanup " +
                $"variant={_variant} physics={Engine.GetPhysicsFrames()} elapsed={Engine.GetPhysicsFrames() - _start} " +
                $"distinct_physics_observations={_physicsObservations} lines={_lines}/160 " +
                $"suppressed={_suppressed} faults={_faults} physics_observer_removed={!_physicsSubscribed} " +
                $"claw_observer_removed={!_clawSubscribed} input_mutation=False extra_waits=0"));
        }
    }

    private sealed class Task10AscentGrip1Diagnostic : IDisposable
    {
        private const int LineCap = 100;
        private readonly CharacterBody2D _player;
        private readonly RouteMonitor _monitor;
        private PlayerInputReader _input;
        private PlayerActionModeController _modes;
        private HealthComponent _health;
        private MechanicalClawController _claw;
        private readonly MechanicalClawTargetResolver _resolver = new();
        private readonly HashSet<ulong> _firstPhysicsFrames = new();
        private string _phase = "lift-control";
        private string _lastState;
        private ulong? _lastDriverFrame;
        private ulong? _lastEventFrame;
        private string _lastEventState;
        private ulong? _lastEdgeSequence;
        private ulong? _lastResolvedSequence;
        private int _lines;
        private int _suppressed;
        private bool _disposed;
        private bool _subscribed;

        public Task10AscentGrip1Diagnostic(CharacterBody2D player, RouteMonitor monitor)
        {
            _player = player;
            _monitor = monitor;
            Safely(() =>
            {
                if (!GodotObject.IsInstanceValid(player)) return;
                _input = player.GetNodeOrNull<PlayerInputReader>("Input");
                _modes = player.GetNodeOrNull<PlayerActionModeController>("ActionModes");
                _health = player.GetNodeOrNull<HealthComponent>("Health");
                _claw = player.GetNodeOrNull<MechanicalClawController>("MechanicalClaw");
                if (GodotObject.IsInstanceValid(_claw))
                {
                    _claw.ClawFrameChanged += ObserveClaw;
                    _subscribed = true;
                }
            });
        }

        public void Boundary(string phase, string moment) => Safely(() =>
        {
            if (_phase != phase)
            {
                _phase = phase;
                _firstPhysicsFrames.Clear();
                _lastDriverFrame = null;
            }
            Write("boundary", moment, summary: true);
        });

        public void Failure(Exception error) => Safely(() =>
            Write("boundary", $"original-failure type={error.GetType().Name} " +
                $"message={OneLine(error.Message)}", summary: true));

        public void ObserveDriver() => Safely(() =>
        {
            ulong physics = Engine.GetPhysicsFrames();
            if (_lastDriverFrame == physics) return;
            _lastDriverFrame = physics;
            Observe("driver-callback", "PhysicsFrame-resume/prior-sample-possible", null, null);
        });

        private void ObserveClaw(MechanicalClawFrame frame, GrappleSurface2D target) =>
            Safely(() => Observe("claw-event", "post-publication/sample-may-have-consumed-edges",
                frame, target));

        private void Observe(string source, string timing, MechanicalClawFrame? published,
            GrappleSurface2D publishedTarget)
        {
            if (_disposed) return;
            ulong physics = Engine.GetPhysicsFrames();
            bool first20 = _firstPhysicsFrames.Contains(physics);
            if (!first20 && _firstPhysicsFrames.Count < 20)
            {
                _firstPhysicsFrames.Add(physics);
                first20 = true;
            }
            MechanicalClawFrame frame = published ?? (GodotObject.IsInstanceValid(_claw)
                ? _claw.CurrentFrame : MechanicalClawFrame.Idle());
            GrappleSurface2D target = published.HasValue ? publishedTarget :
                GodotObject.IsInstanceValid(_claw) ? _claw.CurrentTarget : null;
            string state = $"{frame.State}/{frame.CastId}/{frame.NextCastId}/{frame.Failure}/" +
                $"{Identity(target)}/{frame.LockedTargetRuntimeId}";
            bool changed = state != _lastState;
            _lastState = state;
            PlayerInputFrame input = GodotObject.IsInstanceValid(_input) ? _input.CurrentFrame : default;
            bool edge = GodotObject.IsInstanceValid(_input) &&
                _lastEdgeSequence != _input.CurrentFrameSequence &&
                (input.PrimaryPressed || input.PrimaryReleased || input.GrappleModePressed);
            if (edge) _lastEdgeSequence = _input.CurrentFrameSequence;
            if (published.HasValue)
            {
                if (_lastEventFrame == physics && _lastEventState == state && !edge) return;
                _lastEventFrame = physics;
                _lastEventState = state;
            }
            if (!first20 && !changed && !edge) return;
            Write(source, $"timing={timing} state_change={changed} sampled_edge={edge}",
                published: published, publishedTarget: publishedTarget);
        }

        private void Write(string source, string detail, bool summary = false,
            MechanicalClawFrame? published = null, GrappleSurface2D publishedTarget = null)
        {
            if (!summary && _lines >= LineCap) { _suppressed++; return; }
            if (!summary) _lines++;
            string prefix = $"TASK10_ASCENT_GRIP1_DIAGNOSTIC phase={_phase} source={source} " +
                $"physics={Engine.GetPhysicsFrames()} {detail}";
            if (!GodotObject.IsInstanceValid(_player))
            {
                GD.Print($"{prefix} player=invalid recoveries=" +
                    $"{_monitor.RecoveryRequested}/{_monitor.RecoveryCompleted}");
                return;
            }
            PlayerInputFrame input = GodotObject.IsInstanceValid(_input) ? _input.CurrentFrame : default;
            MechanicalClawFrame frame = published ?? (GodotObject.IsInstanceValid(_claw)
                ? _claw.CurrentFrame : MechanicalClawFrame.Idle());
            GrappleSurface2D target = published.HasValue ? publishedTarget :
                GodotObject.IsInstanceValid(_claw) ? _claw.CurrentTarget : null;
            var contacts = new List<string>();
            for (int index = 0; index < _player.GetSlideCollisionCount(); index++)
            {
                KinematicCollision2D contact = _player.GetSlideCollision(index);
                if (!GodotObject.IsInstanceValid(contact)) continue;
                contacts.Add($"{Identity(contact.GetCollider() as GodotObject)}:{contact.GetNormal()}");
            }
            string resolution = "sampled_primary_resolution=not-requested";
            if (input.PrimaryPressed && GodotObject.IsInstanceValid(_input) &&
                _lastResolvedSequence != _input.CurrentFrameSequence)
            {
                _lastResolvedSequence = _input.CurrentFrameSequence;
                resolution = ResolveSampledMouse(input.MouseWorld);
            }
            GD.Print($"{prefix} input_sequence=" +
                $"{(GodotObject.IsInstanceValid(_input) ? _input.CurrentFrameSequence.ToString() : "invalid")} " +
                $"sampled_E={input.GrappleModePressed} sampled_primary={input.PrimaryPressed}/{input.PrimaryHeld} " +
                $"sampled_primary_released={input.PrimaryReleased} sampled_mouse_world={input.MouseWorld} " +
                $"raw_not_accepted_primary={Input.IsActionPressed(InputActions.PrimaryAction)}/" +
                $"{Input.IsActionJustPressed(InputActions.PrimaryAction)} " +
                $"raw_not_accepted_E={Input.IsActionPressed(InputActions.SelectGrappleMode)}/" +
                $"{Input.IsActionJustPressed(InputActions.SelectGrappleMode)} " +
                $"mode={(GodotObject.IsInstanceValid(_modes) ? _modes.CurrentMode.ToString() : "invalid")} " +
                $"can_begin_grapple={(GodotObject.IsInstanceValid(_modes) && _modes.CanBeginGrapple)} " +
                $"claw_valid={GodotObject.IsInstanceValid(_claw)} state={frame.State} cast={frame.CastId} " +
                $"next_cast={frame.NextCastId} failure={frame.Failure} target={Identity(target)} " +
                $"locked_target={frame.LockedTargetRuntimeId} anchor={frame.AnchorPoint} " +
                $"effective_visibility={frame.EffectiveVisibility} player={_player.GlobalPosition} " +
                $"velocity={_player.Velocity} floor={_player.IsOnFloor()} contacts={string.Join(';', contacts)} " +
                $"hp={(GodotObject.IsInstanceValid(_health) ? _health.CurrentHealth.ToString() : "invalid")} " +
                $"recoveries={_monitor.RecoveryRequested}/{_monitor.RecoveryCompleted} {resolution}");
        }

        private string ResolveSampledMouse(Vector2 mouse)
        {
            MechanicalClawTargetResolution resolution = _resolver.Resolve(_player, mouse);
            // Report the exact terrain first-hit independently of main-anchor assistance.
            using PhysicsRayQueryParameters2D ray = PhysicsRayQueryParameters2D.Create(
                _player.GlobalPosition, mouse);
            ray.CollideWithAreas = true;
            ray.CollideWithBodies = true;
            ray.CollisionMask = CombatCollisionLayers.World | CombatCollisionLayers.ThreadTarget;
            var exclude = new Godot.Collections.Array<Rid>();
            AddCollisionRids(_player, exclude);
            ray.Exclude = exclude;
            Godot.Collections.Dictionary hit = _player.GetWorld2D().DirectSpaceState.IntersectRay(ray);
            Node collider = hit.ContainsKey("collider") ? hit["collider"].AsGodotObject() as Node : null;
            GrappleSurface2D firstSurface = null;
            for (Node node = collider; GodotObject.IsInstanceValid(node); node = node.GetParent())
            {
                firstSurface = node as GrappleSurface2D ??
                    node.GetNodeOrNull<GrappleSurface2D>("GrappleSurfaceProfile");
                if (GodotObject.IsInstanceValid(firstSurface)) break;
            }
            Vector2 hitPoint = hit.ContainsKey("position") ? hit["position"].AsVector2() : Vector2.Zero;
            return $"sampled_primary_resolution=read-only-query first_hit={Identity(collider)} " +
                $"first_surface={Identity(firstSurface)} first_hit_point={hitPoint} " +
                $"resolved_surface={Identity(resolution.Surface)} resolved_runtime={resolution.Snapshot.RuntimeId} " +
                $"resolved_exists={resolution.Snapshot.Exists} resolved_anchor={resolution.Snapshot.WorldAnchor} " +
                $"resolved_distance={_player.GlobalPosition.DistanceTo(resolution.Snapshot.WorldAnchor)} " +
                $"resolved_visibility={resolution.Snapshot.HasLineOfSight} cursor_distance={resolution.CursorDistance} " +
                $"max_range={MechanicalClawSettings.Default.MaxRange}";
        }

        private static void AddCollisionRids(Node node, Godot.Collections.Array<Rid> rids)
        {
            if (!GodotObject.IsInstanceValid(node)) return;
            if (node is CollisionObject2D collision) rids.Add(collision.GetRid());
            foreach (Node child in node.GetChildren()) AddCollisionRids(child, rids);
        }

        private static string Identity(GodotObject value) => !GodotObject.IsInstanceValid(value)
            ? "none-or-invalid" : value is Node node
                ? $"{node.GetPath()}#{node.GetInstanceId()}" : $"#{value.GetInstanceId()}";

        private static string OneLine(string value) => value.Replace('\r', ' ').Replace('\n', ' ');

        private void Safely(Action observe)
        {
            try { observe(); }
            catch (Exception error)
            {
                // Diagnostic errors are evidence gaps, never a replacement route failure.
                if (_lines >= LineCap) { _suppressed++; return; }
                _lines++;
                try { GD.Print($"TASK10_ASCENT_GRIP1_DIAGNOSTIC phase={_phase} source=diagnostic-error " +
                    $"type={error.GetType().Name} message={OneLine(error.Message)}"); }
                catch { /* Preserve the original failure even during invalid-node cleanup. */ }
            }
        }

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            Safely(() =>
            {
                if (_subscribed && GodotObject.IsInstanceValid(_claw))
                    _claw.ClawFrameChanged -= ObserveClaw;
                _subscribed = false;
            });
            Safely(() => Write("boundary", $"cleanup lines={_lines} suppressed={_suppressed} " +
                $"claw_observer_removed={!_subscribed} input_mutation=False extra_waits=0", summary: true));
        }
    }

    private static async Task ShieldJumpToSupport(SceneTree tree, CharacterBody2D player,
        RouteMonitor monitor, CanyonShieldLaneHazard shieldLane, StaticBody2D target)
    {
        Vector2 aim = player.GlobalPosition + Vector2.Right * 240f;
        PlayerShieldController shield = player.GetNode<PlayerShieldController>("Shield");
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        MechanicalClawController claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
        RectangleShape2D targetShape = (RectangleShape2D)target
            .GetNode<CollisionShape2D>("Collision").Shape;
        SendMouse(MouseButton.Right, true, player, aim);
        Vector2 takeoff = player.GlobalPosition;
        int acceptedJumps = motor.AcceptedJumpCount;
        int acceptedDashes = motor.AcceptedDashCount;
        ulong castId = claw.CurrentFrame.CastId;
        int recoveryCompletions = monitor.RecoveryCompleted;
        SendAction(InputActions.MoveRight, true);
        SendAction(InputActions.Jump, true);
        bool movementReleased = false;
        bool departed = false;
        float minimumY = player.GlobalPosition.Y;
        float maximumSpeed = 0f;
        bool sawLaneOverlap = false;
        bool shieldHeldThroughoutOverlap = true;
        int stableLandingFrames = 0;
        string acceptedJumpTransition = "not-observed";
        string firstTargetCollision = "none";
        for (int frame = 0; frame < 180 && stableLandingFrames < StableLandingFrames; frame++)
        {
            MoveMouse(player, player.GlobalPosition + Vector2.Right * 240f);
            if (!movementReleased && player.GlobalPosition.X >= target.GlobalPosition.X)
            {
                SendAction(InputActions.MoveRight, false);
                movementReleased = true;
            }
            await PhysicsFrames(tree, monitor, 1);
            departed |= !player.IsOnFloor();
            minimumY = Mathf.Min(minimumY, player.GlobalPosition.Y);
            maximumSpeed = Mathf.Max(maximumSpeed, Mathf.Abs(player.Velocity.X));
            bool overlapsLane = shieldLane.GetOverlappingBodies().Contains(player);
            sawLaneOverlap |= overlapsLane;
            if (overlapsLane && (!input.Current.ShieldHeld || !shield.IsActive))
                shieldHeldThroughoutOverlap = false;
            if (acceptedJumpTransition == "not-observed" &&
                motor.AcceptedJumpCount > acceptedJumps)
                acceptedJumpTransition = $"frame={frame} position={player.GlobalPosition} " +
                    $"velocity={player.Velocity}";
            if (firstTargetCollision == "none")
            {
                for (int collisionIndex = 0;
                     collisionIndex < player.GetSlideCollisionCount(); collisionIndex++)
                {
                    KinematicCollision2D collision = player.GetSlideCollision(collisionIndex);
                    if (!ReferenceEquals(collision.GetCollider(), target)) continue;
                    firstTargetCollision = $"frame={frame} position={collision.GetPosition()} " +
                        $"normal={collision.GetNormal()} player={player.GlobalPosition} " +
                        $"velocity={player.Velocity}";
                    break;
                }
            }
            bool safelyInsideTarget = Mathf.Abs(player.GlobalPosition.X -
                target.GlobalPosition.X) <= targetShape.Size.X / 2f - 20f;
            stableLandingFrames = HasFloorContact(player, target) && safelyInsideTarget
                ? stableLandingFrames + 1
                : 0;
        }
        SendAction(InputActions.Jump, false);
        SendAction(InputActions.MoveRight, false);
        TestAssert.True(sawLaneOverlap && shieldHeldThroughoutOverlap && departed &&
                        motor.AcceptedJumpCount == acceptedJumps + 1 &&
                        motor.AcceptedDashCount == acceptedDashes &&
                        claw.CurrentFrame.CastId == castId &&
                        monitor.RecoveryCompleted == recoveryCompletions &&
                        stableLandingFrames >= StableLandingFrames &&
                        HasFloorContact(player, target) &&
                        !shieldLane.GetOverlappingBodies().Contains(player),
            $"Task10 shield-lane ordinary jump reaches {target.Name}; player={player.GlobalPosition} " +
            $"takeoff={takeoff} minimum_y={minimumY:0.000} accepted_jumps=" +
            $"{acceptedJumps}->{motor.AcceptedJumpCount} maximum_speed=" +
            $"{maximumSpeed:0.000} shield_held_through_overlap={shieldHeldThroughoutOverlap} " +
            $"movement_released={movementReleased} accepted_transition={acceptedJumpTransition} " +
            $"first_target_collision={firstTargetCollision} stable={stableLandingFrames} " +
            $"dashes={acceptedDashes}->{motor.AcceptedDashCount} cast={castId}->" +
            $"{claw.CurrentFrame.CastId} recoveries={recoveryCompletions}->" +
            $"{monitor.RecoveryCompleted} overlap=" +
            $"{shieldLane.GetOverlappingBodies().Contains(player)}");
        GD.Print($"TASK10_SHIELD_LANE_JUMP_OK target={target.Name} takeoff={takeoff} " +
            $"player={player.GlobalPosition} minimum_y={minimumY:0.000} accepted_jumps=" +
            $"{acceptedJumps}->{motor.AcceptedJumpCount} maximum_speed=" +
            $"{maximumSpeed:0.000} shield_held_through_overlap={shieldHeldThroughoutOverlap} " +
            $"movement_released={movementReleased} accepted_transition={acceptedJumpTransition} " +
            $"first_target_collision={firstTargetCollision} stable={stableLandingFrames} " +
            $"dashes={acceptedDashes}->{motor.AcceptedDashCount} cast={castId}->" +
            $"{claw.CurrentFrame.CastId} recoveries={recoveryCompletions}->" +
            $"{monitor.RecoveryCompleted} overlap=" +
            $"{shieldLane.GetOverlappingBodies().Contains(player)}");
    }

    private static async Task EnterTask10SteamWalkway(SceneTree tree,
        PrologueLevelController level, CharacterBody2D player, PrologueSector basin, RouteMonitor monitor)
    {
        var driver = KeyboardRouteInputDriver.Current;
        var pistonOne = basin.GetNode<StaticBody2D>("Gameplay/Collision/GearPistonOne");
        var pistonTwo = basin.GetNode<StaticBody2D>("Gameplay/Collision/GearPistonTwo");
        var walkway = basin.GetNode<StaticBody2D>("Gameplay/Collision/ShortcutBasinWalkway");
        var health = player.GetNode<HealthComponent>("Health");
        var motor = player.GetNode<PlayerMotor>("Motor");
        var input = player.GetNode<PlayerInputReader>("Input");
        var claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
        ulong playerId = player.GetInstanceId(), cast = claw.CurrentFrame.CastId,
            nextCast = claw.CurrentFrame.NextCastId, started = Engine.GetPhysicsFrames();
        int hp = health.CurrentHealth, requests = monitor.RecoveryRequested,
            recoveries = monitor.RecoveryCompleted, jumps = motor.AcceptedJumpCount,
            dashes = motor.AcceptedDashCount, damage = 0, healing = 0, frames = 0;
        const int budget = 80 + 90;
        bool keepWalkway = false, complete = false;
        string stage = "PistonTwo";
        var entryLift = basin.GetNode<CanyonCounterweightLift>("Gameplay/Mechanisms/BasinCounterweightLift");
        var entryPiston = basin.GetNode<CanyonGearPiston>("Gameplay/Mechanisms/GearPiston");
        int entryTraceRows = 0, entryTraceOmitted = 0;
        string entryTraceIdentity = "";
        Exception observedFailure = null;
        HealthComponent.DamagedEventHandler onDamage = (_, _) => damage++;
        HealthComponent.HealedEventHandler onHeal = (_, _) => healing++;
        bool FullSupport(StaticBody2D support)
        {
            if (!player.IsOnFloor() || !TryTask10CapsuleCorridor(player,
                support.GetNode<CollisionShape2D>("Collision"), out _, out _, out _, out _)) return false;
            for (int index = 0; index < player.GetSlideCollisionCount(); index++)
            {
                using KinematicCollision2D contact = player.GetSlideCollision(index);
                if (contact.GetCollider() == support && contact.GetNormal().Y < -.7f) return true;
            }
            return false;
        }
        bool HasLowerPlatformTopContact()
        {
            if (!player.IsOnFloor()) return false;
            for (int index = 0; index < player.GetSlideCollisionCount(); index++)
            {
                KinematicCollision2D contact = player.GetSlideCollision(index);
                if (contact.GetCollider() == pistonOne && contact.GetNormal().Y < -.7f) return true;
            }
            return false;
        }
        bool ReversePeakAllowed(float currentX, float peakX, float vx, float left, float right) =>
            currentX < left || currentX > right || (vx < 0f ? peakX >= left : peakX <= right);
        string Floor()
        {
            if (!player.IsOnFloor()) return "airborne";
            for (int index = 0; index < player.GetSlideCollisionCount(); index++)
            {
                using KinematicCollision2D contact = player.GetSlideCollision(index);
                if (contact.GetNormal().Y < -.7f && contact.GetCollider() is Node node)
                    return $"{node.GetPath()}#{node.GetInstanceId()}";
            }
            return "floor_without_slide_collider";
        }
        string Snapshot() => $"stage={stage} observations={frames}/{budget} " +
            $"physics={Engine.GetPhysicsFrames()-started}/{budget} hp={hp}->{health.CurrentHealth} " +
            $"damage={damage} healing={healing} " +
            (GodotObject.IsInstanceValid(player)
                ? $"player={player.GlobalPosition} velocity={player.Velocity} floor={Floor()} move={input.Current.MoveAxis}"
                : "player=invalid");
        Rect2 TraceBounds(CollisionShape2D shape)
        {
            Vector2 half = ((RectangleShape2D)shape.Shape).Size * .5f;
            Vector2 a = shape.ToGlobal(-half), b = shape.ToGlobal(half);
            Vector2 c = shape.ToGlobal(new(half.X, -half.Y)), d = shape.ToGlobal(new(-half.X, half.Y));
            float left = MathF.Min(MathF.Min(a.X, b.X), MathF.Min(c.X, d.X));
            float top = MathF.Min(MathF.Min(a.Y, b.Y), MathF.Min(c.Y, d.Y));
            float right = MathF.Max(MathF.Max(a.X, b.X), MathF.Max(c.X, d.X));
            float bottom = MathF.Max(MathF.Max(a.Y, b.Y), MathF.Max(c.Y, d.Y));
            return new(left, top, right - left, bottom - top);
        }
        void ObserveEntry()
        {
            string floor = Floor();
            string identity = $"{stage}/{floor}/{input.Current.MoveAxis}/{entryPiston.Collision.Disabled}/" +
                $"{entryLift.Frame.HazardActive}/{entryLift.Frame.Telegraphing}";
            bool nearGap = stage.StartsWith("gap", StringComparison.Ordinal) &&
                player.GlobalPosition.X <= 2760f && player.GlobalPosition.Y <= 3950f && frames % 4 == 0;
            if (identity == entryTraceIdentity && !nearGap) return;
            entryTraceIdentity = identity;
            if (entryTraceRows >= 40) { entryTraceOmitted++; return; }
            entryTraceRows++;
            var contacts = new List<string>();
            for (int index = 0; index < player.GetSlideCollisionCount(); index++)
            {
                KinematicCollision2D contact = player.GetSlideCollision(index);
                GodotObject collider = contact.GetCollider();
                contacts.Add($"{(collider is Node node ? node.GetPath().ToString() : "non-node")} " +
                    $"normal={contact.GetNormal()} point={contact.GetPosition()}");
            }
            GD.Print($"TASK10_STEAM_ENTRY_CONTACT row={entryTraceRows}/40 physics={Engine.GetPhysicsFrames()} " +
                $"sample={input.CurrentFrameSequence} {Snapshot()} raw_axis={input.RawFrame.MoveAxis} " +
                $"raw_AD={Input.IsPhysicalKeyPressed(Key.A)}/{Input.IsPhysicalKeyPressed(Key.D)} " +
                $"contacts=[{string.Join(";", contacts)}] motor_priority={motor.ProcessPhysicsPriority} observer_priority=100 " +
                $"lift={entryLift.GetInstanceId()} bounds={TraceBounds(entryLift.GetNode<CollisionShape2D>("Collision"))} " +
                $"lift_elapsed={entryLift.ElapsedSeconds:R} activated={entryLift.IsActivated} lift_phase={entryLift.Frame.Phase01:R} " +
                $"piston={entryPiston.GetInstanceId()} bounds={TraceBounds(entryPiston.Collision)} " +
                $"piston_elapsed={entryPiston.ElapsedSeconds:R} piston_phase={entryPiston.Frame.Phase01:R} " +
                $"piston_disabled={entryPiston.Collision.Disabled} telegraph={entryPiston.Frame.Telegraphing} " +
                "diagnostic_only=true descent_control=actual_motion_reverse_or_neutral");
        }
        void Check()
        {
            TestAssert.True(stage != "gap-descent" || !HasLowerPlatformTopContact(),
                $"Steam descent cannot land on PistonOne and silently retry; {Snapshot()}");
            TestAssert.True(GodotObject.IsInstanceValid(player) && player.IsInsideTree() &&
                level.Player == player && monitor.Player == player && player.GetInstanceId() == playerId &&
                hp > 0 && health.CurrentHealth == hp && damage == 0 && healing == 0 &&
                monitor.RecoveryRequested == requests && monitor.RecoveryCompleted == recoveries &&
                motor.AcceptedJumpCount == jumps && motor.AcceptedDashCount == dashes &&
                claw.CurrentFrame.CastId == cast && claw.CurrentFrame.NextCastId == nextCast &&
                frames <= budget && Engine.GetPhysicsFrames()-started <= (ulong)budget &&
                (!keepWalkway || FullSupport(walkway)),
                $"Steam entry preserves same player/HP, no recovery/actions and bounded real support; {Snapshot()}");
        }
        async Task Until(Func<bool> done, Action control = null)
        {
            while (!done())
            {
                if (observedFailure != null) throw observedFailure;
                Check();
                TestAssert.True(frames < budget && Engine.GetPhysicsFrames()-started < (ulong)budget,
                    $"Steam entry shares the original 80+90 cap without retry; {Snapshot()}");
                control?.Invoke();
                frames++;
                await PhysicsFrames(tree, monitor, 1);
                if (observedFailure != null) throw observedFailure;
                Check();
            }
            if (observedFailure != null) throw observedFailure;
            Check();
        }
        var observer = new BasinBoardingTickObserver { ProcessPhysicsPriority = 100 };
        observer.Sample = _ => { try { Check(); ObserveEntry(); } catch (Exception error) { observedFailure ??= error; } };
        try
        {
            health.Damaged += onDamage; health.Healed += onHeal;
            player.AddChild(observer);
            GD.Print($"TASK10_STEAM_ENTRY_BEGIN {Snapshot()}");
            TestAssert.True(driver != null && FullSupport(pistonTwo) &&
                float.IsFinite(motor.ThrusterState.Module.GroundReverseBrake) &&
                motor.ThrusterState.Module.GroundReverseBrake > 0f,
                "keyboard Steam entry starts on actual full PistonTwo with validated module reverse braking");
            TestAssert.True(ReversePeakAllowed(2685.441f, 2685.441f, 6.666667f, 2672.5f, 2679.5f) &&
                ReversePeakAllowed(2679.743f, 2679.743f, 12.500001f, 2672.5f, 2679.5f),
                "Steam reverse guard permits both independently observed outside-to-inside correction states");
            TestAssert.True(!ReversePeakAllowed(2676f, 2671f, -260f, 2672.5f, 2679.5f) &&
                !ReversePeakAllowed(2676f, 2680f, 260f, 2672.5f, 2679.5f) &&
                ReversePeakAllowed(2676f, 2673f, -260f, 2672.5f, 2679.5f),
                "Steam reverse guard still rejects both unsafe in-corridor peaks, not all braking assertions");
            Check(); driver.ReleaseAll();
            // Reuse the already traversed missed-lift gap, not the carriage's x2760 shaft.
            stage = "gap-approach";
            SendAction(InputActions.MoveLeft, true);
            await Until(() => player.GlobalPosition.X <= 2690f);
            SendAction(InputActions.MoveLeft, false);
            stage = "gap-descent";
            GD.Print($"TASK10_STEAM_ENTRY_DESCENT {Snapshot()}");
            // The old neutral-only fall retained -260px/s and landed on the
            // enabled moving piston, then PistonOne. Keep this same gap/170:
            // compare its actual passive endpoint each tick and use real reverse
            // keys before residual travel can cross the static lower platform.
            // Dynamic contacts are not predicted as free flight: re-read the
            // actual completed body/floor and live bounds after every step.
            int descentBrakes = 0, descentNeutral = 0, outsideCorrections = 0;
            void ControlDescent()
            {
                float radius = ((CapsuleShape2D)player.GetNode<CollisionShape2D>("BodyCollider").Shape).Radius;
                Rect2 lower = TraceBounds(pistonOne.GetNode<CollisionShape2D>("Collision"));
                Rect2 carriage = TraceBounds(entryLift.GetNode<CollisionShape2D>("Collision"));
                float safeLeft = lower.End.X + radius + .5f;
                float safeRight = carriage.Position.X - radius - .5f;
                TestAssert.True(safeLeft < safeRight,
                    "Steam descent derives a real capsule corridor from saved static platform and live carriage");
                float vx = player.Velocity.X;
                var passive = FreeMotionForecast.Neutral(vx, player.IsOnFloor(), motor.MotionSettings,
                    motor.ThrusterState.Module, 1d / Engine.PhysicsTicksPerSecond, budget - frames, 0f);
                float neutralEndpointX = player.GlobalPosition.X + passive.NetDistance;
                int direction = neutralEndpointX < safeLeft ? 1 : neutralEndpointX > safeRight ? -1 : 0;
                bool outside = player.GlobalPosition.X < safeLeft || player.GlobalPosition.X > safeRight;
                if (outside && direction != 0) outsideCorrections++;
                if (direction != 0 && vx * direction < 0f)
                {
                    var reverse = FreeMotionForecast.Reverse(vx, player.IsOnFloor(), motor.MotionSettings,
                        motor.ThrusterState.Module, 1d / Engine.PhysicsTicksPerSecond, budget - frames, 0f);
                    float peakX = player.GlobalPosition.X + MathF.Sign(vx) * reverse.ForwardDistance;
                    TestAssert.True(ReversePeakAllowed(player.GlobalPosition.X, peakX, vx, safeLeft, safeRight),
                        $"Steam descent can brake before its remaining original-direction travel leaves the corridor; " +
                        $"peak_x={peakX:R} corridor={safeLeft:R}/{safeRight:R} {Snapshot()}");
                    descentBrakes++;
                }
                else if (direction == 0) descentNeutral++;
                SendAction(InputActions.MoveLeft, direction < 0);
                SendAction(InputActions.MoveRight, direction > 0);
            }
            await Until(() => FullSupport(walkway), ControlDescent);
            SendAction(InputActions.MoveLeft, false);
            SendAction(InputActions.MoveRight, false);
            keepWalkway = true;
            GD.Print($"TASK10_STEAM_ENTRY_LANDED brakes={descentBrakes} neutral={descentNeutral} " +
                $"outside_corrections={outsideCorrections} lower_platform_retry=false " +
                $"actual_module={motor.ThrusterState.Module.ModuleId} movement_scale={motor.EffectiveMovementScale:R} {Snapshot()}");
            // Restore the old valve approach's starting region before its unchanged100+20.
            stage = "walkway-return";
            HorizontalForecastResult ReturnBrake() => FreeMotionForecast.Reverse(
                Mathf.Max(0f, player.Velocity.X), true, motor.MotionSettings,
                motor.ThrusterState.Module, 1d / Engine.PhysicsTicksPerSecond, budget - frames, 2f);
            SendAction(InputActions.MoveRight, true);
            await Until(() => 2760f - player.GlobalPosition.X <= ReturnBrake().ForwardDistance);
            SendAction(InputActions.MoveRight, false);
            var returnBrake = ReturnBrake();
            TestAssert.True(returnBrake.BrakeReachedZero || returnBrake.SpeedThresholdReached,
                "Steam walkway actual reverse forecast must fit the remaining original shared cap");
            GD.Print($"TASK10_STEAM_ENTRY_RETURN_BRAKE predicted_peak_x=" +
                $"{player.GlobalPosition.X + returnBrake.ForwardDistance:R} " +
                $"reverse_steps={returnBrake.Steps} {Snapshot()}");
            stage = "walkway-brake";
            SendAction(InputActions.MoveLeft, true);
            await Until(() => player.Velocity.X <= 0f);
            SendAction(InputActions.MoveLeft, false);
            ulong releaseSequence = input.CurrentFrameSequence;
            stage = "walkway-settle";
            await Until(() => input.CurrentFrameSequence > releaseSequence &&
                Mathf.Abs(input.Current.MoveAxis) <= .001f &&
                Mathf.Abs(player.Velocity.X) <= 2f && Mathf.Abs(player.Velocity.Y) <= 2f);
            TestAssert.True(Mathf.Abs(player.GlobalPosition.X - 2760f) <= 8f && FullSupport(walkway),
                $"keyboard Steam entry hands off stopped near the original x2760 on full walkway; {Snapshot()}");
            complete = true;
        }
        finally
        {
            try
            {
                GD.Print($"TASK10_STEAM_ENTRY_END complete={complete} {Snapshot()}");
                GD.Print($"TASK10_STEAM_ENTRY_TRACE_END rows={entryTraceRows}/40 omitted={entryTraceOmitted} " +
                    "observer_priority=100 descent_control=actual_motion_reverse_or_neutral original_budget=170");
            }
            finally
            {
                try
                {
                    observer.Sample = null;
                    if (GodotObject.IsInstanceValid(observer)) { observer.GetParent()?.RemoveChild(observer); observer.QueueFree(); }
                    if (GodotObject.IsInstanceValid(health)) { health.Damaged -= onDamage; health.Healed -= onHeal; }
                }
                finally { driver?.ReleaseAll(); }
            }
        }
    }

    private static async Task TraverseTask10SteamBranch(SceneTree tree,
        PrologueLevelController level, SeamlessPrologueWorld world, CharacterBody2D player,
        RouteMonitor monitor, Func<PrologueSectorId, string, StaticBody2D> body,
        bool headlessNormalPlan = false)
    {
        PrologueSector basin = world.TryGetMountedSector(PrologueSectorId.CanyonBasin,
            out PrologueSector mounted) ? mounted : throw new InvalidOperationException(
            "Task10 steam route requires mounted basin");
        if (KeyboardRouteInputDriver.Current != null)
            await EnterTask10SteamWalkway(tree, level, player, basin, monitor);
        else
        {
            await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 2760f, 80);
            await PrologueCanyonTraversalTests.Task4WaitSupport(tree, player, basin,
                "ShortcutBasinWalkway");
        }
        StaticBody2D walkway = body(PrologueSectorId.CanyonBasin,
            "ShortcutBasinWalkway");
        CanyonSteamValve valve = basin.GetNode<CanyonSteamValve>(
            "Gameplay/Mechanisms/SteamValve");
        CanyonSteamJet pairedJet = valve.GetNode<CanyonSteamJet>(valve.PairedJetPath);
        GrappleSurface2D control = basin.GetNode<GrappleSurface2D>(
            "Gameplay/GrappleSurfaces/SteamValveControl");
        HealthComponent health = player.GetNode<HealthComponent>("Health");
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        MechanicalClawController claw = player.GetNode<MechanicalClawController>(
            "MechanicalClaw");
        int healthBefore = health.CurrentHealth;
        int recoveryRequestsBefore = monitor.RecoveryRequested;
        int recoveryCompletionsBefore = monitor.RecoveryCompleted;
        int jumpsBefore = motor.AcceptedJumpCount;
        int dashesBefore = motor.AcceptedDashCount;
        ulong castBefore = claw.CurrentFrame.CastId;
        ulong nextCastBefore = claw.CurrentFrame.NextCastId;

        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        bool keyboardValve = KeyboardRouteInputDriver.Current != null &&
            control.Name.ToString() == "SteamValveControl";
        int approachFrames = 0;
        int neutralFrames = 0;
        if (keyboardValve)
        {
            // A diagonal K also presses D. Prepare directly below the same control
            // so the original stationary cast uses only W+K, not a moving NE cast.
            float stanceX = control.WorldAnchor.X;
            CollisionShape2D stanceSupport = walkway.GetNode<CollisionShape2D>("Collision");
            bool StanceReady() => Mathf.Abs(player.GlobalPosition.X - stanceX) <= 3f &&
                Mathf.Abs(player.Velocity.X) <= 3f;
            void StanceGuard()
            {
                bool fullSupport = TryTask10CapsuleCorridor(player, stanceSupport,
                    out float left, out float right, out float supportLeft, out float supportRight) &&
                    left >= supportLeft + 2f && right <= supportRight - 2f &&
                    HasFloorContact(player, walkway);
                TestAssert.True(level.Player == player && fullSupport &&
                    health.CurrentHealth == healthBefore &&
                    monitor.RecoveryRequested == recoveryRequestsBefore &&
                    monitor.RecoveryCompleted == recoveryCompletionsBefore &&
                    motor.AcceptedJumpCount == jumpsBefore && motor.AcceptedDashCount == dashesBefore &&
                    claw.CurrentFrame.CastId == castBefore && claw.CurrentFrame.NextCastId == nextCastBefore,
                    $"keyboard valve stance retains the same player, full walkway, HP/recovery/actions and cast identity; " +
                    $"position={player.GlobalPosition} velocity={player.Velocity} full_support={fullSupport} " +
                    $"hp={healthBefore}->{health.CurrentHealth} recovery={recoveryRequestsBefore}/" +
                    $"{recoveryCompletionsBefore}->{monitor.RecoveryRequested}/{monitor.RecoveryCompleted} " +
                    $"frames={approachFrames}/100+{neutralFrames}/20 sample={input.CurrentFrameSequence}");
            }
            bool DriveStance()
            {
                var stop = FreeMotionForecast.Neutral(player.Velocity.X, true, motor.MotionSettings,
                    motor.ThrusterState.Module, 1d / Engine.PhysicsTicksPerSecond,
                    100 - approachFrames + 20 - neutralFrames, 2f);
                TestAssert.True(stop.SpeedThresholdReached,
                    "keyboard valve neutral forecast fits original100+20 remaining budget");
                float stopError = stanceX - player.GlobalPosition.X - stop.NetDistance;
                bool right = stopError > 1.5f;
                bool left = stopError < -1.5f;
                SendAction(InputActions.MoveLeft, left);
                SendAction(InputActions.MoveRight, right);
                return left || right;
            }
            TestAssert.True(float.IsFinite(motor.Tuning.GroundAcceleration) &&
                motor.Tuning.GroundAcceleration > 0f,
                "keyboard valve retains positive authored acceleration; stopping uses actual immutable snapshots");
            StanceGuard();
            Vector2 stanceStart = player.GlobalPosition;
            while (approachFrames < 100 && !StanceReady())
            {
                DriveStance(); approachFrames++;
                await PhysicsFrames(tree, monitor, 1);
                StanceGuard();
            }
            SendAction(InputActions.MoveLeft, false);
            SendAction(InputActions.MoveRight, false);
            ulong stanceReleaseSequence = input.CurrentFrameSequence;
            bool correctionHeld = false;
            // Final braking/correction and fresh neutral sampling share the original
            // 20 settling frames; neither phase can add to the original 100+20.
            while (neutralFrames < 20)
            {
                bool moving = !StanceReady() && DriveStance();
                if (!moving)
                {
                    SendAction(InputActions.MoveLeft, false);
                    SendAction(InputActions.MoveRight, false);
                }
                if (moving || correctionHeld) stanceReleaseSequence = input.CurrentFrameSequence;
                correctionHeld = moving;
                neutralFrames++;
                await PhysicsFrames(tree, monitor, 1);
                StanceGuard();
                if (StanceReady() && input.CurrentFrameSequence > stanceReleaseSequence &&
                    input.CurrentFrame.MoveAxis == 0f) break;
            }
            SendAction(InputActions.MoveLeft, false);
            SendAction(InputActions.MoveRight, false);
            MechanicalClawTargetResolution stanceSelection = new MechanicalClawTargetResolver()
                .ResolveKeyboard(player, Vector2.Up);
            GD.Print($"TASK10_STEAM_VALVE_KEYBOARD_STANCE from={stanceStart} target_x={stanceX} " +
                $"position={player.GlobalPosition} velocity={player.Velocity} frames={approachFrames}/100+" +
                $"{neutralFrames}/20 sample={stanceReleaseSequence}->{input.CurrentFrameSequence} " +
                $"move={input.CurrentFrame.MoveAxis} planned=Up selected={stanceSelection.Surface?.GetPath()} " +
                $"material={stanceSelection.Snapshot.Material} anchor={stanceSelection.Snapshot.WorldAnchor} " +
                $"los={stanceSelection.Snapshot.HasLineOfSight}");
            TestAssert.True(StanceReady() && input.CurrentFrameSequence > stanceReleaseSequence &&
                input.CurrentFrame.MoveAxis == 0f && stanceSelection.Surface == control &&
                stanceSelection.Snapshot.HasLineOfSight,
                "keyboard valve reaches within3px, stops and resolves the original control with Up within100+20");
        }
        else
        {
            await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 3080f, 100);
            await PrologueCanyonTraversalTests.Task4WaitSupport(tree, player, basin,
                "ShortcutBasinWalkway");
            for (; neutralFrames < 20; neutralFrames++)
            {
                await PhysicsFrames(tree, monitor, 1);
                if (input.Current.MoveAxis == 0f &&
                    Mathf.Abs(player.Velocity.X) <= 3f && HasFloorContact(player, walkway))
                {
                    neutralFrames++;
                    break;
                }
            }
        }
        TestAssert.True(input.Current.MoveAxis == 0f &&
                        Mathf.Abs(player.Velocity.X) <= 3f &&
                        HasFloorContact(player, walkway),
            $"Task10 valve approach requires a newly sampled neutral, stationary, supported " +
            $"pose within 20 ordinary frames; waited={neutralFrames} " +
            $"move_axis={input.Current.MoveAxis} player={player.GlobalPosition} " +
            $"velocity={player.Velocity} floor_contact={HasFloorContact(player, walkway)}");
        CollisionShape2D walkwayCollision = walkway.GetNode<CollisionShape2D>("Collision");
        RectangleShape2D walkwayShape = (RectangleShape2D)walkwayCollision.Shape;
        CollisionShape2D playerCollision = player.GetNode<CollisionShape2D>("BodyCollider");
        CapsuleShape2D playerShape = (CapsuleShape2D)playerCollision.Shape;
        float walkwayLeft = walkwayCollision.ToGlobal(
            new Vector2(-walkwayShape.Size.X / 2f, 0f)).X;
        float walkwayRight = walkwayCollision.ToGlobal(
            new Vector2(walkwayShape.Size.X / 2f, 0f)).X;
        float capsuleLeft = playerCollision.ToGlobal(
            new Vector2(-playerShape.Radius, 0f)).X;
        float capsuleRight = playerCollision.ToGlobal(
            new Vector2(playerShape.Radius, 0f)).X;
        TestAssert.True(HasFloorContact(player, walkway) &&
                        capsuleLeft >= walkwayLeft + 2f &&
                        capsuleRight <= walkwayRight - 2f,
            $"Task10 valve approach keeps the whole capsule inset on the real walkway; " +
            $"player={player.GlobalPosition} velocity={player.Velocity} " +
            $"capsule_x=[{capsuleLeft:0.###},{capsuleRight:0.###}] " +
            $"walkway_x=[{walkwayLeft:0.###},{walkwayRight:0.###}] " +
            $"floor_contact={HasFloorContact(player, walkway)}");
        Vector2 anchor = control.WorldAnchor;
        Viewport viewport = player.GetViewport();
        Vector2 logicalTarget = viewport.GetCanvasTransform() * anchor;
        Rect2 aimable = viewport.GetVisibleRect().Grow(-32f);
        float targetRange = player.GlobalPosition.DistanceTo(anchor);
        Vector2 plannedValveDirection = PlayerKeyboardAimModel.ResolveDirection(anchor - player.GlobalPosition, 1);
        MechanicalClawTargetResolver valveResolver = new();
        MechanicalClawTargetResolution resolution = keyboardValve
            ? valveResolver.ResolveKeyboard(player, plannedValveDirection)
            : valveResolver.Resolve(player, anchor);
        TestAssert.True(!valve.IsActivated && !pairedJet.DisabledForRun &&
                        control.IsAvailable && control.GetWorld2D() == player.GetWorld2D() &&
                        aimable.HasPoint(logicalTarget) &&
                        targetRange <= MechanicalClawSettings.Default.MaxRange &&
                        (!keyboardValve || plannedValveDirection.Dot(Vector2.Up) > .999f) &&
                        resolution.Surface == control &&
                        resolution.Snapshot.HasLineOfSight,
            $"Task10 upper valve input requires inactive valve, live jet, logical viewport, " +
            $"range, exact resolver target and LOS; player={player.GlobalPosition} " +
            $"control={control.GetPath()}#{control.GetInstanceId()} anchor={anchor} " +
            $"logical_target={logicalTarget} aimable={aimable} range={targetRange:0.###}/" +
            $"{MechanicalClawSettings.Default.MaxRange:0.###} " +
            $"keyboard={keyboardValve} planned={plannedValveDirection} " +
            $"resolved={resolution.Surface?.GetInstanceId() ?? 0} path={resolution.Surface?.GetPath()} " +
            $"material={resolution.Snapshot.Material} selected_anchor={resolution.Snapshot.WorldAnchor} " +
            $"los={resolution.Snapshot.HasLineOfSight} available={control.IsAvailable} " +
            $"same_world={control.GetWorld2D() == player.GetWorld2D()} " +
            $"valve={valve.IsActivated} " +
            $"jet_disabled={pairedJet.DisabledForRun}");
        Vector2 settledStart = player.GlobalPosition;
        float maxDisplacement = 0f;
        void ObserveDisplacement() => maxDisplacement = Mathf.Max(maxDisplacement,
            player.GlobalPosition.DistanceTo(settledStart));
        ulong observedCast = 0UL;
        int lifecycleStage = 0;
        bool invalidLifecycle = false;
        bool pullStateSeen = false;
        string lifecycle = "none";
        void ObserveValveCast(MechanicalClawFrame frame, GrappleSurface2D target)
        {
            if (target == control && frame.CastId != 0UL)
                observedCast = frame.CastId;
            if (frame.CastId == nextCastBefore &&
                (frame.State is MechanicalClawState.Reel or MechanicalClawState.Swing or
                    MechanicalClawState.Boost || frame.BoostConsumed))
                pullStateSeen = true;
            if (frame.CastId != nextCastBefore &&
                !(frame.State == MechanicalClawState.Idle &&
                    frame.NextCastId == nextCastBefore + 1UL)) return;
            switch (frame.State)
            {
                case MechanicalClawState.Latched:
                    if (lifecycleStage == 0 && target == control)
                    {
                        lifecycleStage = 1;
                        lifecycle = "Latched";
                    }
                    else invalidLifecycle = true;
                    break;
                case MechanicalClawState.Released:
                    if (lifecycleStage == 1)
                    {
                        lifecycleStage = 2;
                        lifecycle += ">Released";
                    }
                    else invalidLifecycle = true;
                    break;
                case MechanicalClawState.Retract:
                    if (lifecycleStage == 2)
                    {
                        lifecycleStage = 3;
                        lifecycle += ">Retract";
                    }
                    else if (lifecycleStage != 3) invalidLifecycle = true;
                    break;
                case MechanicalClawState.Idle:
                    if (lifecycleStage == 3 && frame.CastId == 0UL)
                    {
                        lifecycleStage = 4;
                        lifecycle += ">Idle";
                    }
                    else if (lifecycleStage != 4) invalidLifecycle = true;
                    break;
            }
        }
        claw.ClawFrameChanged += ObserveValveCast;
        tree.PhysicsFrame += ObserveDisplacement;
        try
        {
            await CastAt(tree, monitor, player, control, () => valve.IsActivated, 120);
            for (int frame = 0; frame < 20 && claw.CurrentFrame.State != MechanicalClawState.Idle;
                 frame++)
                await PhysicsFrames(tree, monitor, 1);
        }
        finally
        {
            tree.PhysicsFrame -= ObserveDisplacement;
            claw.ClawFrameChanged -= ObserveValveCast;
        }
        maxDisplacement = Mathf.Max(maxDisplacement,
            player.GlobalPosition.DistanceTo(settledStart));
        capsuleLeft = playerCollision.ToGlobal(new Vector2(-playerShape.Radius, 0f)).X;
        capsuleRight = playerCollision.ToGlobal(new Vector2(playerShape.Radius, 0f)).X;
        TestAssert.True(valve.IsActivated && pairedJet.DisabledForRun &&
                        !pairedJet.Frame.HazardActive &&
                        observedCast == nextCastBefore &&
                        claw.CurrentFrame.NextCastId == nextCastBefore + 1UL &&
                        lifecycleStage == 4 && !invalidLifecycle && !pullStateSeen &&
                        claw.CurrentFrame.State == MechanicalClawState.Idle &&
                        claw.CurrentFrame.CastId == 0UL &&
                        maxDisplacement <= 2f &&
                        capsuleLeft >= walkwayLeft + 2f &&
                        capsuleRight <= walkwayRight - 2f &&
                        health.CurrentHealth == healthBefore &&
                        monitor.RecoveryRequested == recoveryRequestsBefore &&
                        monitor.RecoveryCompleted == recoveryCompletionsBefore &&
                        motor.AcceptedJumpCount == jumpsBefore &&
                        motor.AcceptedDashCount == dashesBefore &&
                        HasFloorContact(player, walkway),
            $"Task10 real upper valve cast must activate and disable its paired jet without " +
            $"damage, recovery or extra movement actions; player={player.GlobalPosition} " +
            $"velocity={player.Velocity} control={control.GetPath()}#{control.GetInstanceId()} " +
            $"cast={castBefore}->{observedCast} next_cast={nextCastBefore}->" +
            $"{claw.CurrentFrame.NextCastId} valve={valve.IsActivated} " +
            $"settled_start={settledStart} end={player.GlobalPosition} " +
            $"max_displacement={maxDisplacement:0.###} lifecycle={lifecycle} " +
            $"stage={lifecycleStage} invalid_lifecycle={invalidLifecycle} " +
            $"pull_state_seen={pullStateSeen} final_claw={claw.CurrentFrame.State}/" +
            $"{claw.CurrentFrame.CastId} " +
            $"jet_disabled={pairedJet.DisabledForRun} hazard={pairedJet.Frame.HazardActive} " +
            $"capsule_x=[{capsuleLeft:0.###},{capsuleRight:0.###}] " +
            $"walkway_x=[{walkwayLeft:0.###},{walkwayRight:0.###}] " +
            $"health={healthBefore}->{health.CurrentHealth} " +
            $"recovery_requests={recoveryRequestsBefore}->{monitor.RecoveryRequested} " +
            $"recovery_completions={recoveryCompletionsBefore}->{monitor.RecoveryCompleted} " +
            $"jumps={jumpsBefore}->{motor.AcceptedJumpCount} " +
            $"dashes={dashesBefore}->{motor.AcceptedDashCount} " +
            $"floor_contact={HasFloorContact(player, walkway)}");
        GD.Print($"TASK10_STEAM_VALVE_INPUT_OK physics={Engine.GetPhysicsFrames()} " +
            $"player={player.GlobalPosition} velocity={player.Velocity} " +
            $"control={control.GetPath()}#{control.GetInstanceId()} " +
            $"cast={castBefore}->{observedCast} next_cast={nextCastBefore}->" +
            $"{claw.CurrentFrame.NextCastId} valve=false->{valve.IsActivated} " +
            $"settled_start={settledStart} end={player.GlobalPosition} " +
            $"max_displacement={maxDisplacement:0.###} lifecycle={lifecycle} " +
            $"stage={lifecycleStage} final_claw={claw.CurrentFrame.State}/" +
            $"{claw.CurrentFrame.CastId} " +
            $"jet_disabled=false->{pairedJet.DisabledForRun} " +
            $"hazard={pairedJet.Frame.HazardActive} health={healthBefore}->" +
            $"{health.CurrentHealth} recovery_requests={recoveryRequestsBefore}->" +
            $"{monitor.RecoveryRequested} recovery_completions={recoveryCompletionsBefore}->" +
            $"{monitor.RecoveryCompleted} jumps={jumpsBefore}->{motor.AcceptedJumpCount} " +
            $"dashes={dashesBefore}->{motor.AcceptedDashCount}");
        await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 3800f, 270);
        await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player,
            body(PrologueSectorId.CanyonBasin, "ShortcutStep4116"), clawRequired: false);
        await DriveTask10SteamTrenchDrop(tree, player, basin, monitor);
        await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 3380f, 210);
        await DefeatTask10Encounter(tree, level, world, player, monitor,
            "canyon.v2.encounter.steam-valves", headlessNormalPlan);
        await ExitTask10SteamTrench(tree, basin, world, player, monitor);
        for (int index = 1; index <= 8; index++)
            await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player,
                body(PrologueSectorId.CanyonBasin, $"SteamRejoinStep{index}"),
                clawRequired: false);
        await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player,
            body(PrologueSectorId.CanyonBasin, "SteamRejoinTop"), clawRequired: false);
        await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player,
            body(PrologueSectorId.CanyonAscent, "LiftBackLanding"), clawRequired: true);
    }

    private static async Task DriveTask10SteamTrenchDrop(SceneTree tree,
        CharacterBody2D player, PrologueSector basin, RouteMonitor monitor)
    {
        if (KeyboardRouteInputDriver.Current == null)
        {
            await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 4040f, 100);
            await PrologueCanyonTraversalTests.Task4WaitSupport(tree, player, basin, "SteamTrenchFloor");
            return;
        }
        // Keyboard route consumer only: original100 approach/brake and original90
        // neutral descent/settle. Damage and AreaEntered remain passive, distinct
        // facts; prediction never writes pose, velocity, hazards or their clocks.
        var health = player.GetNode<HealthComponent>("Health");
        var input = player.GetNode<PlayerInputReader>("Input");
        var motor = player.GetNode<PlayerMotor>("Motor");
        var hurtbox = player.GetNode<Hurtbox>("Hurtbox");
        var floor = basin.GetNode<StaticBody2D>("Gameplay/Collision/SteamTrenchFloor");
        var source = basin.GetNode<StaticBody2D>("Gameplay/Collision/ShortcutStep4116");
        var bodyShape = player.GetNode<CollisionShape2D>("BodyCollider");
        var bodyCapsule = (CapsuleShape2D)bodyShape.Shape;
        int hpBefore = health.CurrentHealth, jumpsBefore = motor.AcceptedJumpCount,
            dashesBefore = motor.AcceptedDashCount;
        int approachFrames = 0, neutralFrames = 0;
        ulong dropStarted = Engine.GetPhysicsFrames();
        float observedMaxX = player.GlobalPosition.X;
        bool braking = false, coasting = false;
        var pair = basin.GetNode<CanyonSteamDiverter>("Gameplay/Mechanisms/SteamDiverterTrench");
        var jets = new[] {
            basin.GetNode<CanyonSteamJet>("Gameplay/Mechanisms/SteamJet"),
            pair.GetNode<CanyonSteamJet>("LeftJet"),
            pair.GetNode<CanyonSteamJet>("RightJet") };
        var hurtShape = hurtbox.GetNode<CollisionShape2D>("HurtboxCollider");
        Rect2 DropBounds(CollisionShape2D collision, Vector2 half) =>
            new Rect2(collision.ToGlobal(-half), collision.ToGlobal(half) - collision.ToGlobal(-half)).Abs();
        Rect2 DropHurtBounds()
        {
            var capsule = (CapsuleShape2D)hurtShape.Shape;
            return DropBounds(hurtShape, new(capsule.Radius, capsule.Height / 2f));
        }
        Rect2 DropJetBounds(CanyonSteamJet jet) => DropBounds(jet.Collision,
            ((RectangleShape2D)jet.Collision.Shape).Size / 2f);
        Exception dropSafetyFailure = null;
        void CheckDropFootprint()
        {
            TestAssert.True(health.CurrentHealth == hpBefore && hpBefore > 0 &&
                motor.AcceptedJumpCount == jumpsBefore && motor.AcceptedDashCount == dashesBefore &&
                Engine.GetPhysicsFrames() - dropStarted <= 190UL,
                "Steam drop keeps original HP/actions and original100+90 physics cap");
            Rect2 hurt = DropHurtBounds();
            foreach (var jet in jets.Skip(1))
                TestAssert.True(!hurt.Intersects(DropJetBounds(jet)),
                    $"Steam drop avoids the fixed jet footprint even during a safe phase: " +
                    $"physics={Engine.GetPhysicsFrames()} player={player.GlobalPosition} velocity={player.Velocity} " +
                    $"hurt={hurt} jet={jet.GetPath()} bounds={DropJetBounds(jet)} " +
                    $"hazard={jet.Frame.HazardActive} sample={input.CurrentFrameSequence}");
        }
        var rows = new List<string>(64);
        int omitted = 0, faults = 0, samples = 0, damageCount = 0;
        ulong lastDamagePhysics = 0;
        bool wasFloor = player.IsOnFloor();
        string stage = "entry", lastJetState = string.Empty;
        string fatalStack = null;
        void Snapshot(string edge, bool reserved = false)
        {
            try
            {
                if (rows.Count >= (reserved ? 64 : 60)) { omitted++; return; }
                var contacts = new List<string>();
                for (int index = 0; index < Math.Min(player.GetSlideCollisionCount(), 8); index++)
                {
                    using var contact = player.GetSlideCollision(index);
                    contacts.Add($"{(contact.GetCollider() as Node)?.GetPath()}:{contact.GetNormal()}");
                }
                string jetFacts = string.Join(";", jets.Select(jet =>
                    $"{jet.GetPath()}#{jet.GetInstanceId()}:disabled={jet.DisabledForRun}," +
                    $"active={jet.Frame.HazardActive},warning={jet.Frame.Telegraphing},monitoring={jet.Monitoring}," +
                    $"elapsed={jet.ElapsedSeconds:R},overlapsPlayer=" +
                    (jet.Monitoring ? jet.GetOverlappingAreas().Contains(hurtbox).ToString() : "unavailable_monitoring_off")));
                rows.Add($"TASK10_STEAM_DROP_TRACE row={rows.Count + 1}/64 edge={edge} stage={stage} " +
                    $"physics={Engine.GetPhysicsFrames()} sample={input.CurrentFrameSequence} player={player.GlobalPosition} " +
                    $"velocity={player.Velocity} floor={player.IsOnFloor()} hp={health.CurrentHealth} " +
                    $"rawAD={Input.IsPhysicalKeyPressed(Key.A)}/{Input.IsPhysicalKeyPressed(Key.D)} " +
                    $"sampleAxis={input.CurrentFrame.MoveAxis} jump={motor.AcceptedJumpCount} dash={motor.AcceptedDashCount} " +
                    $"landing={motor.LandingCount} fall={motor.LastFallHeight}/{motor.LastFallDamage} " +
                    $"pair={pair.SelectedSide}/{pair.IsHandingOff} contacts=[{string.Join(";", contacts)}] " +
                    $"jets=[{jetFacts}] observer_only=true");
            }
            catch (Exception) { faults++; }
        }
        HealthComponent.DamagedEventHandler damaged = (remaining, impulse) =>
        {
            damageCount++; lastDamagePhysics = Engine.GetPhysicsFrames();
            Snapshot($"HealthDamaged:remaining={remaining}:impulse={impulse}", reserved: true);
            if (remaining == 0 && fatalStack == null)
            {
                string stack = System.Environment.StackTrace;
                fatalStack = stack.Length <= 32768 ? stack : stack[..32768];
                if (rows.Count < 64)
                    rows.Add($"TASK10_STEAM_DROP_FATAL_STACK physics={lastDamagePhysics} " +
                        $"retained_chars={fatalStack.Length} truncated={stack.Length > 32768} stack={fatalStack}");
                else omitted++;
            }
        };
        var listeners = new List<(CanyonSteamJet Jet, Area2D.AreaEnteredEventHandler Handler)>();
        var observer = new BasinBoardingTickObserver { ProcessPhysicsPriority = 100 };
        observer.Sample = _ =>
        {
            observedMaxX = Mathf.Max(observedMaxX, player.GlobalPosition.X);
            try { CheckDropFootprint(); }
            catch (Exception error) { dropSafetyFailure ??= error; }
            try
            {
                samples++;
                bool floor = player.IsOnFloor();
                string jetState = string.Join(";", jets.Select(jet =>
                    $"{jet.DisabledForRun}/{jet.Frame.HazardActive}/{jet.Frame.Telegraphing}"));
                if (samples <= 4 || samples % 10 == 0 || floor != wasFloor || jetState != lastJetState)
                    Snapshot("post-Motor-priority100");
                wasFloor = floor; lastJetState = jetState;
            }
            catch (Exception) { faults++; }
        };
        try
        {
            health.Damaged += damaged;
            foreach (var jet in jets)
            {
                ulong boundId = jet.GetInstanceId();
                Area2D.AreaEnteredEventHandler entered = area =>
                {
                    if (area == hurtbox)
                        Snapshot($"AreaEntered:boundSource={boundId}:targetPlayer=true:" +
                            $"lastDamagePhysics={lastDamagePhysics}:samePhysics={lastDamagePhysics == Engine.GetPhysicsFrames()}", reserved: true);
                };
                jet.AreaEntered += entered;
                listeners.Add((jet, entered));
            }
            player.AddChild(observer);
            CheckDropFootprint();
            Snapshot("before-original-Walk4040");
            stage = "approach-and-reverse-100";
            while (approachFrames < 100 && !coasting)
            {
                if (dropSafetyFailure != null) throw dropSafetyFailure;
                CheckDropFootprint();
                if (!braking && !player.IsOnFloor())
                {
                    var reverse = FreeMotionForecast.Reverse(player.Velocity.X, false,
                        motor.MotionSettings, motor.ThrusterState.Module,
                        1d / Engine.PhysicsTicksPerSecond, 100 - approachFrames, 0f);
                    if (reverse.BrakeReachedZero && player.GlobalPosition.X + reverse.ForwardDistance >= 4040f)
                    {
                        Rect2 sourceBounds = DropBounds(source.GetNode<CollisionShape2D>("Collision"),
                            ((RectangleShape2D)source.GetNode<CollisionShape2D>("Collision").Shape).Size / 2f);
                        Rect2 bodyBounds = DropBounds(bodyShape, new(bodyCapsule.Radius, bodyCapsule.Height / 2f));
                        TestAssert.True(bodyBounds.Position.X > sourceBounds.End.X &&
                            player.Velocity.X > 0f &&
                            DropHurtBounds().End.X + reverse.ForwardDistance < DropJetBounds(jets[2]).Position.X,
                            "Steam reverse begins only after full source-lip clearance and predicts no right-jet incursion");
                        braking = true;
                        GD.Print($"TASK10_STEAM_DROP_REVERSE_BEGIN physics={Engine.GetPhysicsFrames()} " +
                            $"frames={approachFrames}/100 player={player.GlobalPosition} velocity={player.Velocity} " +
                            $"predicted_peak_x={player.GlobalPosition.X + reverse.ForwardDistance:R} " +
                            $"reverse_steps={reverse.Steps} actual_module={motor.ThrusterState.Module.ModuleId}");
                    }
                }
                if (braking && player.Velocity.X <= 0f)
                {
                    SendAction(InputActions.MoveLeft, false);
                    SendAction(InputActions.MoveRight, false);
                    coasting = true;
                    break;
                }
                SendAction(InputActions.MoveLeft, braking);
                SendAction(InputActions.MoveRight, !braking);
                approachFrames++;
                await PhysicsFrames(tree, monitor, 1);
            }
            TestAssert.True(coasting, "Steam real reverse crosses zero in original100 without a retry");
            Snapshot("after-reverse-zero-not-stable-yet");
            stage = "neutral-descent-and-settle-90";
            bool settled = false;
            while (neutralFrames < 90 && !settled)
            {
                neutralFrames++;
                await PhysicsFrames(tree, monitor, 1);
                if (dropSafetyFailure != null) throw dropSafetyFailure;
                CheckDropFootprint();
                var floorShape = floor.GetNode<CollisionShape2D>("Collision");
                Rect2 floorBounds = DropBounds(floorShape, ((RectangleShape2D)floorShape.Shape).Size / 2f);
                Rect2 bodyBounds = DropBounds(bodyShape, new(bodyCapsule.Radius, bodyCapsule.Height / 2f));
                settled = HasFloorContact(player, floor) && player.IsOnFloor() &&
                    bodyBounds.Position.X >= floorBounds.Position.X && bodyBounds.End.X <= floorBounds.End.X &&
                    Mathf.Abs(bodyBounds.End.Y - floorBounds.Position.Y) <= 1f &&
                    Mathf.Abs(player.Velocity.X) <= 2f && Mathf.Abs(player.Velocity.Y) <= 2f &&
                    input.CurrentFrame.MoveAxis == 0f &&
                    !Input.IsPhysicalKeyPressed(Key.A) && !Input.IsPhysicalKeyPressed(Key.D);
            }
            if (dropSafetyFailure != null) throw dropSafetyFailure;
            TestAssert.True(settled && Mathf.Abs(player.GlobalPosition.X - 4040f) <= 3f,
                $"Steam neutral descent keeps original90 and real4040±3 stop: player={player.GlobalPosition} " +
                $"velocity={player.Velocity} frames={approachFrames}/100+{neutralFrames}/90");
            CheckDropFootprint();
            Snapshot("settled-original-floor");
            GD.Print($"TASK10_STEAM_DROP_SAFE_OK physics={Engine.GetPhysicsFrames()} " +
                $"frames={approachFrames}/100+{neutralFrames}/90 player={player.GlobalPosition} velocity={player.Velocity} " +
                $"observed_max_player_x={observedMaxX:R} hp={hpBefore}->{health.CurrentHealth} " +
                $"jumps={jumpsBefore}->{motor.AcceptedJumpCount} dashes={dashesBefore}->{motor.AcceptedDashCount} " +
                "fixed_footprint_checked_every_completed_tick=true neutral_tail=true");
        }
        finally
        {
            SendAction(InputActions.MoveLeft, false);
            SendAction(InputActions.MoveRight, false);
            observer.Sample = null;
            if (GodotObject.IsInstanceValid(observer)) observer.QueueFree();
            if (GodotObject.IsInstanceValid(health)) health.Damaged -= damaged;
            foreach (var listener in listeners)
                if (GodotObject.IsInstanceValid(listener.Jet)) listener.Jet.AreaEntered -= listener.Handler;
            foreach (string row in rows) GD.Print(row);
            GD.Print($"TASK10_STEAM_DROP_TRACE_END rows={rows.Count}/64 omitted={omitted} faults={faults} " +
                $"post_motor_samples={samples} damage={damageCount} original_budgets=100/90 " +
                $"actual_frames={approachFrames}/{neutralFrames} consumer=actual_reverse_then_neutral");
        }
    }

    private static async Task ExitTask10SteamTrench(SceneTree tree, PrologueSector basin,
        SeamlessPrologueWorld world, CharacterBody2D player, RouteMonitor monitor)
    {
        StaticBody2D floor = basin.GetNode<StaticBody2D>("Gameplay/Collision/SteamTrenchFloor");
        CanyonSteamValve oldValve = basin.GetNode<CanyonSteamValve>("Gameplay/Mechanisms/SteamValve");
        CanyonSteamJet oldJet = basin.GetNode<CanyonSteamJet>("Gameplay/Mechanisms/SteamJet");
        CanyonSteamDiverter pair = basin.GetNode<CanyonSteamDiverter>(
            "Gameplay/Mechanisms/SteamDiverterTrench");
        CanyonSteamJet left = pair.GetNode<CanyonSteamJet>("LeftJet");
        CanyonSteamJet right = pair.GetNode<CanyonSteamJet>("RightJet");
        ThreadTarget2D control = basin.GetNode<ThreadTarget2D>(
            "Gameplay/GrappleSurfaces/SteamDiverterTrenchControl");
        LegacyThreadInteractionAdapter adapter = control.GetNode<LegacyThreadInteractionAdapter>(
            "LegacyThreadInteractionAdapter");
        CanyonEncounterGroup encounter = world.FindChildren("*", "", true, false)
            .OfType<CanyonEncounterGroup>().Single(group =>
                group.EncounterId.ToString() == "canyon.v2.encounter.steam-valves");
        HealthComponent health = player.GetNode<HealthComponent>("Health");
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        PlayerActionModeController modes = player.GetNode<PlayerActionModeController>("ActionModes");
        MechanicalClawController claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
        KeyboardRouteInputDriver keyboardDriver = KeyboardRouteInputDriver.Current;
        bool keyboardRoute = keyboardDriver != null;
        int keyboardClawsBefore = keyboardDriver?.ClawEdges ?? 0;
        int keyboardPressSamples = 0;
        ulong keyboardAimSequence = 0;
        ulong keyboardAimTarget = 0;
        Vector2 keyboardAimDirection = Vector2.Zero;
        bool keyboardAimSource = false;
        CollisionShape2D bodyShape = player.GetNode<CollisionShape2D>("BodyCollider");
        CollisionShape2D hurtShape = player.GetNode<CollisionShape2D>("Hurtbox/HurtboxCollider");
        CollisionShape2D floorShape = floor.GetNode<CollisionShape2D>("Collision");
        int initialHealth = health.CurrentHealth;
        int initialRequests = monitor.RecoveryRequested;
        int initialRecoveries = monitor.RecoveryCompleted;
        int initialJumps = motor.AcceptedJumpCount;
        int initialDashes = motor.AcceptedDashCount;
        string phase = "combat-end";
        int phaseFrame = 0;
        int phaseBudget = 0;
        float phaseTarget = player.GlobalPosition.X;
        int noProgress = 0;
        ulong castBefore = claw.CurrentFrame.NextCastId;
        ulong latchedCast = 0;
        ulong sampledPress = 0;
        ulong aimPhysics = 0;
        ulong assignedPhysics = 0;
        int lifecycleStage = 0;
        bool invalidLifecycle = false;
        bool pullingSeen = false;
        string lifecycle = "none";
        var castIds = new HashSet<ulong>();
        Vector2 operationStart = Vector2.Zero;
        float operationMaxDisplacement = 0f;
        bool observingOperation = false;

        Rect2 Bounds(CollisionShape2D shape, Vector2 half) => new Rect2(
            shape.ToGlobal(-half), shape.ToGlobal(half) - shape.ToGlobal(-half)).Abs();
        Rect2 HurtBounds()
        {
            var capsule = (CapsuleShape2D)hurtShape.Shape;
            return Bounds(hurtShape, new Vector2(capsule.Radius, capsule.Height / 2f));
        }
        Rect2 JetBounds(CanyonSteamJet jet)
        {
            var rectangle = (RectangleShape2D)jet.Collision.Shape;
            return Bounds(jet.Collision, rectangle.Size / 2f);
        }
        bool Dormant(CanyonSteamJet jet) => jet.DisabledForRun &&
            !jet.Frame.Telegraphing && !jet.Frame.HazardActive &&
            jet.Collision.Disabled && !jet.Monitoring;
        bool Supported()
        {
            var capsule = (CapsuleShape2D)bodyShape.Shape;
            var rectangle = (RectangleShape2D)floorShape.Shape;
            Rect2 floorBounds = Bounds(floorShape, rectangle.Size / 2f);
            float capsuleLeft = bodyShape.ToGlobal(new Vector2(-capsule.Radius, 0f)).X;
            float capsuleRight = bodyShape.ToGlobal(new Vector2(capsule.Radius, 0f)).X;
            return HasFloorContact(player, floor) && !floorShape.Disabled &&
                capsuleLeft >= floorBounds.Position.X + 2f &&
                capsuleRight <= floorBounds.End.X - 2f;
        }
        bool KeyboardSource() => input.CurrentFrame.KeyboardActions &&
            !input.CurrentFrame.PrimaryPressed && !input.CurrentFrame.PrimaryHeld &&
            !input.CurrentFrame.PrimaryReleased && !input.CurrentFrame.AttackModePressed &&
            !input.CurrentFrame.GrappleModePressed && !input.CurrentFrame.LegacyShieldHeld &&
            !input.CurrentFrame.AttackPressed && !input.CurrentFrame.InteractPressed;
        string JetFacts(CanyonSteamJet jet) =>
            $"{jet.Name}#{jet.GetInstanceId()} bounds={JetBounds(jet)} " +
            $"disabled={jet.DisabledForRun} warning={jet.Frame.Telegraphing} " +
            $"active={jet.Frame.HazardActive} collision_disabled={jet.Collision.Disabled} " +
            $"monitoring={jet.Monitoring}";
        string Snapshot() =>
            $"phase={phase} phase_frame={phaseFrame}/{phaseBudget} target_x={phaseTarget:R} " +
            $"no_progress={noProgress} physics={Engine.GetPhysicsFrames()} " +
            $"input_seq={input.CurrentFrameSequence} move={input.CurrentFrame.MoveAxis} " +
            $"E={input.CurrentFrame.GrappleModePressed} LMB={input.CurrentFrame.PrimaryPressed}/" +
            $"{input.CurrentFrame.PrimaryHeld} source={(keyboardRoute ? "keyboard-WK" : "legacy-ELMB")} " +
            $"K={input.CurrentFrame.ClawPressed}/{Input.IsPhysicalKeyPressed(Key.K)} " +
            $"W={Input.IsPhysicalKeyPressed(Key.W)} aim={input.KeyboardAimDirection} " +
            $"K_samples={keyboardPressSamples} K_edges={keyboardClawsBefore}->" +
            $"{keyboardDriver?.ClawEdges ?? 0} admitted={keyboardAimSequence}/{keyboardAimTarget}/" +
            $"{keyboardAimDirection}/{keyboardAimSource} player={player.GlobalPosition} velocity={player.Velocity} " +
            $"on_floor={player.IsOnFloor()} floor_contact={HasFloorContact(player, floor)} " +
            $"full_support={Supported()} hurt={HurtBounds()} " +
            $"pair={pair.GetPath()}#{pair.GetInstanceId()} side={pair.SelectedSide} " +
            $"activated={pair.HasActivated} handoff={pair.IsHandingOff} " +
            $"control={control.GetPath()}#{control.GetInstanceId()} anchor={control.WorldAnchor} " +
            $"adapter={adapter.GetPath()}#{adapter.GetInstanceId()} applications={adapter.ApplicationCount} " +
            $"cast={claw.CurrentFrame.CastId}/{claw.CurrentFrame.State}/" +
            $"{claw.CurrentFrame.Failure} next={claw.CurrentFrame.NextCastId} " +
            $"latched={latchedCast} lifecycle={lifecycle} invalid={invalidLifecycle} " +
            $"pulling={pullingSeen} operation_displacement={operationMaxDisplacement:R} " +
            $"health={initialHealth}->{health.CurrentHealth} " +
            $"recovery={initialRequests}/{initialRecoveries}->" +
            $"{monitor.RecoveryRequested}/{monitor.RecoveryCompleted} " +
            $"jumps={initialJumps}->{motor.AcceptedJumpCount} " +
            $"dashes={initialDashes}->{motor.AcceptedDashCount} " +
            $"old_valve={oldValve.IsActivated} old_jet={JetFacts(oldJet)} " +
            $"left={JetFacts(left)} right={JetFacts(right)}";
        void Check(string condition, bool passed)
        {
            if (!passed) TestAssert.True(false,
                $"Task10 Steam trench exit {condition}; {Snapshot()}");
        }
        void CheckSafety()
        {
            Check("keeps completed combat, old valve disabled, HP, recoveries and ordinary actions",
                encounter.IsComplete && encounter.LiveActorCount == 0 &&
                oldValve.IsActivated && Dormant(oldJet) &&
                health.CurrentHealth == initialHealth && initialHealth > 0 &&
                monitor.RecoveryRequested == initialRequests &&
                monitor.RecoveryCompleted == initialRecoveries &&
                motor.AcceptedJumpCount == initialJumps &&
                motor.AcceptedDashCount == initialDashes);
            Check("keeps full named trench-floor support", Supported());
            Rect2 hurt = HurtBounds();
            Check("never overlaps an active jet or its live collision",
                !(left.Frame.HazardActive && hurt.Intersects(JetBounds(left))) &&
                !(right.Frame.HazardActive && hurt.Intersects(JetBounds(right))) &&
                !(oldJet.Frame.HazardActive && hurt.Intersects(JetBounds(oldJet))));
            Check("keeps the outgoing side genuinely dormant",
                pair.SelectedSide == CanyonSteamDiverterSide.Right
                    ? !pair.HasActivated && !pair.IsHandingOff &&
                      adapter.ApplicationCount == 0 && Dormant(left)
                    : pair.HasActivated && pair.SelectedSide == CanyonSteamDiverterSide.Left &&
                      adapter.ApplicationCount == 1 && Dormant(right));
            if (pair.IsHandingOff)
                Check("handoff keeps both real jets harmless",
                    Dormant(left) && Dormant(right));
            if (observingOperation)
            {
                operationMaxDisplacement = Mathf.Max(operationMaxDisplacement,
                    player.GlobalPosition.DistanceTo(operationStart));
                Check("stationary cast remains inside the safe pocket",
                    operationMaxDisplacement <= 2f &&
                    !hurt.Intersects(JetBounds(left)) && !hurt.Intersects(JetBounds(right)));
            }
        }
        async Task Tick()
        {
            if (keyboardRoute && phase == "central-control")
                Check("keeps W preparation, K admission, latch and handoff inside the original shared120",
                    phaseFrame < phaseBudget);
            await PhysicsFrames(tree, monitor, 1);
            phaseFrame++;
            CheckSafety();
        }
        async Task Walk(float target)
        {
            phase = $"walk-{target:0}";
            phaseTarget = target;
            phaseFrame = 0;
            noProgress = 0;
            float speed = motor.Tuning.MaxRunSpeed * motor.EffectiveMovementScale;
            float acceleration = motor.Tuning.GroundAcceleration * motor.EffectiveMovementScale;
            float deceleration = motor.Tuning.GroundDeceleration;
            float rate = Engine.PhysicsTicksPerSecond;
            float distance = Mathf.Abs(target - player.GlobalPosition.X);
            Check("has finite positive real movement permission and physics rate",
                float.IsFinite(speed) && speed > 0f && float.IsFinite(acceleration) &&
                acceleration > 0f && float.IsFinite(deceleration) && deceleration > 0f &&
                float.IsFinite(rate) && rate > 0f && float.IsFinite(distance));
            // Reserve 12 input/observation, 24 neutral-settle, and 24 short-correction
            // ticks inside the segment's 480-frame ceiling. A longer walk fails visibly.
            phaseBudget = Mathf.Min(480, Mathf.CeilToInt(rate *
                (distance / speed + speed / acceleration + speed / deceleration)) + 60);
            int direction = Math.Sign(target - player.GlobalPosition.X);
            GD.Print($"TASK10_STEAM_EXIT_WALK_START {Snapshot()} speed={speed:R} " +
                $"acceleration={acceleration:R} deceleration={deceleration:R} rate={rate:R}");
            async Task WalkTick()
            {
                Check("stays inside the distance-derived 480-frame segment budget",
                    phaseFrame < phaseBudget);
                await Tick();
            }
            void Move(bool pressed)
            {
                SendAction(InputActions.MoveLeft, pressed && direction < 0);
                SendAction(InputActions.MoveRight, pressed && direction > 0);
            }
            async Task Settle(int cap)
            {
                ulong releasedAt = input.CurrentFrameSequence;
                for (int frame = 0; frame < cap; frame++)
                {
                    await WalkTick();
                    if (input.CurrentFrameSequence > releasedAt &&
                        Mathf.IsZeroApprox(input.CurrentFrame.MoveAxis) &&
                        Mathf.Abs(player.Velocity.X) <= .5f &&
                        Mathf.Abs(player.Velocity.Y) <= .5f) break;
                }
                Check("samples released neutral and an actually stopped motor",
                    input.CurrentFrameSequence > releasedAt &&
                    Mathf.IsZeroApprox(input.CurrentFrame.MoveAxis) &&
                    Mathf.Abs(player.Velocity.X) <= .5f &&
                    Mathf.Abs(player.Velocity.Y) <= .5f);
            }
            Move(true);
            try
            {
                float previousX = player.GlobalPosition.X;
                while (phaseFrame < phaseBudget - 48)
                {
                    float remaining = direction * (target - player.GlobalPosition.X);
                    float towardSpeed = Mathf.Max(0f, direction * player.Velocity.X);
                    float brakeDistance = towardSpeed * towardSpeed / (2f * deceleration) +
                        towardSpeed / rate + 1f;
                    if (remaining <= brakeDistance) break;
                    await WalkTick();
                    float progress = direction * (player.GlobalPosition.X - previousX);
                    noProgress = progress < .05f ? noProgress + 1 : 0;
                    Check("does not stall under held real movement input for 18 frames",
                        noProgress < 18);
                    previousX = player.GlobalPosition.X;
                }
            }
            finally { Move(false); }
            GD.Print($"TASK10_STEAM_EXIT_BRAKE {Snapshot()}");
            await Settle(24);
            for (int correction = 0;
                 correction < 12 && direction * (target - player.GlobalPosition.X) > 0f;
                 correction++)
            {
                float remaining = direction * (target - player.GlobalPosition.X);
                float before = player.GlobalPosition.X;
                Move(true);
                try
                {
                    // One or two grounded acceleration ticks from rest, never a blind long run.
                    for (int pulse = 0; pulse < (remaining > 3f ? 2 : 1); pulse++)
                        await WalkTick();
                }
                finally { Move(false); }
                Check("short real corrective input makes forward progress",
                    direction * (player.GlobalPosition.X - before) > .05f);
                await Settle(8);
            }
            Check("reaches the target with measured early braking/correction",
                direction * (player.GlobalPosition.X - target) >= 0f);
            Check("samples released neutral and a stopped, fully supported endpoint",
                Mathf.IsZeroApprox(input.CurrentFrame.MoveAxis) &&
                Mathf.Abs(player.Velocity.X) <= .5f && Mathf.Abs(player.Velocity.Y) <= .5f &&
                Supported());
            GD.Print($"TASK10_STEAM_EXIT_WALK_OK {Snapshot()}");
        }
        void ObserveCast(MechanicalClawFrame frame, GrappleSurface2D target)
        {
            if (!observingOperation) return;
            if (frame.State == MechanicalClawState.Aim && aimPhysics == 0)
            {
                aimPhysics = Engine.GetPhysicsFrames();
                if (keyboardRoute)
                {
                    keyboardAimSequence = input.CurrentFrameSequence;
                    keyboardAimTarget = target?.GetInstanceId() ?? 0;
                    keyboardAimDirection = input.KeyboardAimDirection;
                    keyboardAimSource = KeyboardSource() && input.CurrentFrame.ClawPressed &&
                        input.CurrentFrame.MoveAxis == 0f && Input.IsPhysicalKeyPressed(Key.W) &&
                        Input.IsPhysicalKeyPressed(Key.K) && target == control &&
                        claw.KeyboardPreview.Surface == control &&
                        claw.KeyboardPreview.Snapshot.HasLineOfSight;
                }
            }
            if (frame.CastId == castBefore && assignedPhysics == 0)
                assignedPhysics = Engine.GetPhysicsFrames();
            if (frame.CastId != 0UL) castIds.Add(frame.CastId);
            if (frame.CastId == castBefore && frame.State is MechanicalClawState.Reel or
                MechanicalClawState.Swing or MechanicalClawState.Boost ||
                frame.CastId == castBefore && frame.BoostConsumed)
                pullingSeen = true;
            if (frame.CastId != castBefore && !(frame.State == MechanicalClawState.Idle &&
                frame.NextCastId == castBefore + 1UL)) return;
            switch (frame.State)
            {
                case MechanicalClawState.Latched:
                    if (lifecycleStage == 0 && target == control &&
                        frame.LockedTargetRuntimeId == control.GetInstanceId())
                    { lifecycleStage = 1; latchedCast = frame.CastId; lifecycle = "Latched"; }
                    else invalidLifecycle = true;
                    break;
                case MechanicalClawState.Released:
                    if (lifecycleStage == 1) { lifecycleStage = 2; lifecycle += ">Released"; }
                    else invalidLifecycle = true;
                    break;
                case MechanicalClawState.Retract:
                    if (lifecycleStage == 2) { lifecycleStage = 3; lifecycle += ">Retract"; }
                    else if (lifecycleStage != 3) invalidLifecycle = true;
                    break;
                case MechanicalClawState.Idle:
                    if (lifecycleStage == 3 && frame.CastId == 0UL)
                    { lifecycleStage = 4; lifecycle += ">Idle"; }
                    else if (lifecycleStage != 4) invalidLifecycle = true;
                    break;
                case MechanicalClawState.Failed:
                    invalidLifecycle = true;
                    break;
            }
        }
        claw.ClawFrameChanged += ObserveCast;
        try
        {
            Check("starts after real completed Steam combat and with fresh right-selected pair",
                encounter.IsComplete && encounter.LiveActorCount == 0 &&
                oldValve.IsActivated && Dormant(oldJet) &&
                !pair.HasActivated && pair.SelectedSide == CanyonSteamDiverterSide.Right &&
                !pair.IsHandingOff && adapter.ApplicationCount == 0 && Dormant(left) &&
                claw.CurrentFrame.State == MechanicalClawState.Idle && Supported());
            Check("uses upright actual capsule and rectangular floor/jet footprints",
                hurtShape.Shape is CapsuleShape2D && bodyShape.Shape is CapsuleShape2D &&
                floorShape.Shape is RectangleShape2D &&
                left.Collision.Shape is RectangleShape2D && right.Collision.Shape is RectangleShape2D &&
                Mathf.Abs(hurtShape.GlobalTransform.X.Y) < .001f &&
                Mathf.Abs(hurtShape.GlobalTransform.Y.X) < .001f &&
                Mathf.Abs(left.Collision.GlobalTransform.X.Y) < .001f &&
                Mathf.Abs(left.Collision.GlobalTransform.Y.X) < .001f &&
                Mathf.Abs(right.Collision.GlobalTransform.X.Y) < .001f &&
                Mathf.Abs(right.Collision.GlobalTransform.Y.X) < .001f);
            CheckSafety();
            GD.Print($"TASK10_STEAM_EXIT_START {Snapshot()}");
            await Walk(3830f);
            await Walk(4000f);
            phase = "central-control";
            phaseFrame = 0;
            phaseBudget = 120;
            Check("stops in actual central pocket clear of both jet footprints",
                player.GlobalPosition.X > 3942f && player.GlobalPosition.X < 4058f &&
                !HurtBounds().Intersects(JetBounds(left)) &&
                !HurtBounds().Intersects(JetBounds(right)) && Supported());
            Vector2 anchor = control.WorldAnchor;
            MechanicalClawTargetResolver resolver = new();
            Vector2 plannedDirection = PlayerKeyboardAimModel.ResolveDirection(anchor - player.GlobalPosition, 1);
            MechanicalClawTargetResolution resolution = keyboardRoute
                ? resolver.ResolveKeyboard(player, plannedDirection) : resolver.Resolve(player, anchor);
            if (keyboardRoute)
                GD.Print($"TASK10_STEAM_EXIT_KEYBOARD_PREFLIGHT {Snapshot().Replace(" warning=", " telegraph_visible=", StringComparison.Ordinal)} planned={plannedDirection} " +
                    $"selected={resolution.Surface?.GetPath()} material={resolution.Snapshot.Material} " +
                    $"selected_anchor={resolution.Snapshot.WorldAnchor} los={resolution.Snapshot.HasLineOfSight}");
            Check("has exact visible, reachable, same-world control and LOS",
                control.IsAvailable && control.GetWorld2D() == player.GetWorld2D() &&
                IsTargetVisible(player, anchor) &&
                player.GlobalPosition.DistanceTo(anchor) <= MechanicalClawSettings.Default.MaxRange &&
                (!keyboardRoute || plannedDirection.Dot(Vector2.Up) > .999f) &&
                resolution.Surface == control && resolution.Snapshot.HasLineOfSight);
            operationStart = player.GlobalPosition;
            observingOperation = true;
            if (!keyboardRoute) MoveMouse(player, anchor);
            ulong beforeMode = input.CurrentFrameSequence;
            ulong sampledMode = 0UL;
            SendAction(keyboardRoute ? InputActions.MoveUp : InputActions.SelectGrappleMode, true);
            try
            {
                for (int frame = 0; frame < 8; frame++)
                {
                    await Tick();
                    if (input.CurrentFrameSequence > beforeMode && (keyboardRoute
                            ? KeyboardSource() && input.CurrentFrame.MoveAxis == 0f &&
                              input.KeyboardAimDirection.Dot(Vector2.Up) > .999f &&
                              Input.IsPhysicalKeyPressed(Key.W) && !Input.IsPhysicalKeyPressed(Key.K)
                            : input.CurrentFrame.GrappleModePressed))
                        sampledMode = input.CurrentFrameSequence;
                    if (sampledMode != 0UL && modes.CanBeginGrapple &&
                        claw.CurrentFrame.State == MechanicalClawState.Idle) break;
                }
            }
            finally { if (!keyboardRoute) SendAction(InputActions.SelectGrappleMode, false); }
            Check(keyboardRoute ? "samples fresh stationary physical W before the K cast" :
                "samples fresh E before the LMB cast",
                sampledMode > beforeMode && modes.CanBeginGrapple &&
                claw.CurrentFrame.State == MechanicalClawState.Idle);
            if (keyboardRoute)
            {
                resolution = resolver.ResolveKeyboard(player, input.KeyboardAimDirection);
                Check("actual fresh W resolves the same visible in-range LOS control before K",
                    resolution.Surface == control && resolution.Snapshot.HasLineOfSight &&
                    control.IsAvailable && control.GetWorld2D() == player.GetWorld2D() &&
                    IsTargetVisible(player, anchor) &&
                    player.GlobalPosition.DistanceTo(anchor) <= MechanicalClawSettings.Default.MaxRange &&
                    keyboardDriver.ClawEdges == keyboardClawsBefore);
            }
            GD.Print($"TASK10_STEAM_EXIT_MODE_OK {Snapshot()} " +
                $"{(keyboardRoute ? "sampled_W" : "sampled_E")}={sampledMode}");
            if (keyboardRoute) SendAction(InputActions.Claw, false);
            else SendMouse(MouseButton.Left, false, player, anchor);
            ulong neutralBefore = input.CurrentFrameSequence;
            await Tick();
            Check(keyboardRoute ? "samples released K and stationary W before the unique press" :
                "samples released LMB and neutral input before the unique press",
                input.CurrentFrameSequence > neutralBefore &&
                !input.CurrentFrame.PrimaryHeld && !input.CurrentFrame.PrimaryPressed &&
                Mathf.IsZeroApprox(input.CurrentFrame.MoveAxis) &&
                (!keyboardRoute || KeyboardSource() && !input.CurrentFrame.ClawPressed &&
                    !Input.IsPhysicalKeyPressed(Key.K) && Input.IsPhysicalKeyPressed(Key.W) &&
                    input.KeyboardAimDirection.Dot(Vector2.Up) > .999f) &&
                claw.CurrentFrame.State == MechanicalClawState.Idle);
            if (!keyboardRoute) await tree.ToSignal(tree, SceneTree.SignalName.ProcessFrame);
            CheckSafety();
            ulong pressBefore = input.CurrentFrameSequence;
            ulong lastPressSequence = pressBefore;
            if (keyboardRoute) SendAction(InputActions.Claw, true);
            else SendMouse(MouseButton.Left, true, player, anchor);
            try
            {
                for (int frame = 0; frame < 12 &&
                     (sampledPress == 0 || aimPhysics == 0 || assignedPhysics == 0);
                     frame++)
                {
                    await Tick();
                    if (input.CurrentFrameSequence > lastPressSequence)
                    {
                        lastPressSequence = input.CurrentFrameSequence;
                        if (keyboardRoute ? input.CurrentFrame.ClawPressed : input.CurrentFrame.PrimaryPressed)
                        {
                            if (keyboardRoute) keyboardPressSamples++;
                            if (sampledPress == 0) sampledPress = input.CurrentFrameSequence;
                        }
                    }
                }
            }
            finally
            {
                if (keyboardRoute)
                {
                    SendAction(InputActions.Claw, false);
                    SendAction(InputActions.MoveUp, false);
                }
                else SendMouse(MouseButton.Left, false, player, anchor);
            }
            Check(keyboardRoute ? "one safe-boundary physical W+K samples a real edge, exact Aim, then one assigned cast" :
                "one safe-boundary LMB samples a real edge, Aim, then one assigned cast",
                sampledPress > pressBefore && aimPhysics != 0 && assignedPhysics >= aimPhysics &&
                (!keyboardRoute || keyboardPressSamples == 1 && keyboardDriver.ClawEdges == keyboardClawsBefore + 1 &&
                    keyboardAimSequence == sampledPress && keyboardAimSource &&
                    keyboardAimDirection.Dot(Vector2.Up) > .999f && keyboardAimTarget == control.GetInstanceId()) &&
                castIds.Count == 1 && castIds.Contains(castBefore) &&
                claw.CurrentFrame.NextCastId == castBefore + 1UL);
            GD.Print($"TASK10_STEAM_EXIT_PRESS_OK {Snapshot()} press_seq={sampledPress} " +
                $"aim_physics={aimPhysics} assigned_physics={assignedPhysics}");
            for (int frame = 0; frame < 90 && adapter.ApplicationCount == 0; frame++)
            { if (!keyboardRoute) MoveMouse(player, anchor); await Tick(); }
            Check("one exact target latch applies the diverter once, Right to Left",
                latchedCast == castBefore && lifecycleStage >= 1 && !invalidLifecycle &&
                castIds.Count == 1 && adapter.ApplicationCount == 1 && pair.HasActivated &&
                pair.SelectedSide == CanyonSteamDiverterSide.Left && pair.IsHandingOff);
            GD.Print($"TASK10_STEAM_EXIT_CAST_OK {Snapshot()}");
            for (int frame = 0; frame < 60 && pair.IsHandingOff; frame++) await Tick();
            Check("natural bounded handoff ends with outgoing Right dormant",
                !pair.IsHandingOff && Dormant(right));
            for (int frame = 0; frame < 30 && claw.CurrentFrame.State != MechanicalClawState.Idle;
                frame++) await Tick();
            Check("real stationary claw completes Latched>Released>Retract>Idle without pulling",
                lifecycleStage == 4 && !invalidLifecycle && !pullingSeen &&
                claw.CurrentFrame.State == MechanicalClawState.Idle &&
                claw.CurrentFrame.CastId == 0UL &&
                claw.CurrentFrame.NextCastId == castBefore + 1UL &&
                operationMaxDisplacement <= 2f && Supported());
            observingOperation = false;
            GD.Print($"TASK10_STEAM_EXIT_HANDOFF_OK {Snapshot()}");
            await Walk(4170f);
            phase = "staircase-staging";
            Check("stages an ordinary jump on unchanged trench floor beyond dormant Right",
                player.GlobalPosition.X >= 4170f && player.GlobalPosition.X <= 4178f &&
                Dormant(right) && Supported() &&
                Mathf.IsZeroApprox(input.CurrentFrame.MoveAxis) &&
                Mathf.Abs(player.Velocity.X) <= .5f);
            GD.Print($"TASK10_STEAM_EXIT_STAGE_OK {Snapshot()}");
        }
        finally
        {
            claw.ClawFrameChanged -= ObserveCast;
            SendAction(InputActions.MoveLeft, false);
            SendAction(InputActions.MoveRight, false);
            SendAction(InputActions.SelectGrappleMode, false);
            if (keyboardRoute)
            {
                SendAction(InputActions.Claw, false);
                SendAction(InputActions.MoveUp, false);
            }
            SendMouse(MouseButton.Left, false, player,
                GodotObject.IsInstanceValid(player) ? player.GlobalPosition : Vector2.Zero);
        }
    }

    // Only observes the two original post-Split calls; no driver/input/await changes.
    private sealed class Task10PostSplitControlDiagnostic : IDisposable
    {
        private readonly SceneTree _tree;
        private readonly CharacterBody2D _player;
        private readonly RouteMonitor _monitor;
        private readonly GrappleSurface2D _target;
        private readonly Node _mechanism;
        private readonly ulong _start = Engine.GetPhysicsFrames();
        private PlayerInputReader _input;
        private PlayerActionModeController _modes;
        private PlayerEnergyController _energy;
        private PlayerShieldController _shield;
        private HealthComponent _health;
        private MechanicalClawController _claw;
        private LegacyThreadInteractionAdapter _adapter;
        private bool _physicsSubscribed, _clawSubscribed, _disposed;
        private int _lines, _suppressed, _errors, _publications, _primarySamples;
        private ulong _lastPrimarySequence;
        private string _lastKey, _lastError = "none";
        private string _ray = "not-yet-observed";
        private ulong _rayPhysics;

        public Task10PostSplitControlDiagnostic(SceneTree tree, CharacterBody2D player,
            RouteMonitor monitor, GrappleSurface2D target, Node mechanism)
        {
            _tree = tree; _player = player; _monitor = monitor;
            _target = target; _mechanism = mechanism;
            Safely(() =>
            {
                if (Live(player))
                {
                    _input = player.GetNodeOrNull<PlayerInputReader>("Input");
                    _modes = player.GetNodeOrNull<PlayerActionModeController>("ActionModes");
                    _energy = player.GetNodeOrNull<PlayerEnergyController>("Energy");
                    _shield = player.GetNodeOrNull<PlayerShieldController>("Shield");
                    _health = player.GetNodeOrNull<HealthComponent>("Health");
                    _claw = player.GetNodeOrNull<MechanicalClawController>("MechanicalClaw");
                }
                if (Live(target)) _adapter = target.GetNodeOrNull<LegacyThreadInteractionAdapter>(
                    "LegacyThreadInteractionAdapter");
                if (Live(tree)) { tree.PhysicsFrame += ObservePhysics; _physicsSubscribed = true; }
                if (Live(_claw)) { _claw.ClawFrameChanged += ObserveClaw; _clawSubscribed = true; }
            });
            Boundary("entry-before-original-CastAt");
        }

        private static bool Live(GodotObject value) => GodotObject.IsInstanceValid(value);
        private static string Identity(GodotObject value) => !Live(value) ? "invalid-or-none" :
            value is Node node ? $"{(node.IsInsideTree() ? node.GetPath().ToString() : "off-tree")}#{node.GetInstanceId()}"
            : $"#{value.GetInstanceId()}";
        private static string Compact(string value) => value.Replace('\r', ' ').Replace('\n', ' ')
            .Substring(0, Math.Min(value.Length, 240));

        private void ObservePhysics() => Safely(() =>
        {
            if (_disposed) return;
            // Original CastAt: 2 mode + 1 primary + at most 120 loop + 3 tail frames.
            if (Engine.GetPhysicsFrames() - _start > 126) return;
            PlayerInputFrame input = Live(_input) ? _input.CurrentFrame : default;
            if (Live(_input) && input.PrimaryPressed && _lastPrimarySequence != _input.CurrentFrameSequence)
            { _lastPrimarySequence = _input.CurrentFrameSequence; _primarySamples++; }
            MechanicalClawFrame claw = Live(_claw) ? _claw.CurrentFrame : MechanicalClawFrame.Idle();
            string key = $"{input.GrappleModePressed}/{input.PrimaryPressed}/{input.PrimaryHeld}/" +
                $"{input.PrimaryReleased}/{(Live(_modes) ? _modes.CurrentMode.ToString() : "invalid")}/" +
                $"{claw.CastId}/{claw.NextCastId}/{claw.State}/{claw.Failure}";
            if (key == _lastKey) return;
            _lastKey = key;
            if (_lines >= 12) { _suppressed++; return; }
            // Only in an existing physics signal. Cached results are not same-tick resolver evidence.
            Safely(() => { _ray = AdmissionRay(); _rayPhysics = Engine.GetPhysicsFrames(); });
            Write("PhysicsFrame-prior-node-input-and-slide-contacts", false);
        });
        private void ObserveClaw(MechanicalClawFrame frame, GrappleSurface2D target) => Safely(() =>
        {
            if (_disposed) return;
            _publications++;
            Write($"ClawFrameChanged-published state={frame.State} cast={frame.CastId} " +
                $"next_cast={frame.NextCastId} failure={frame.Failure} chosen={Identity(target)} " +
                $"published_visibility={frame.EffectiveVisibility}", false);
        });
        public void Boundary(string moment) => Safely(() => Write(moment, true));
        public void Failure(Exception error) => Boundary($"original-failure={error.GetType().Name}:{Compact(error.Message)}");

        private string AdmissionRay()
        {
            if (!Live(_player) || !_player.IsInsideTree() || !Live(_target) || !_target.IsInsideTree())
                return "unavailable-caster-or-target";
            Vector2 origin = _player.GlobalPosition, anchor = _target.WorldAnchor;
            if (!origin.IsFinite() || !anchor.IsFinite()) return "unavailable-nonfinite";
            if (origin.IsEqualApprox(anchor)) return "not-needed-origin-equals-anchor";
            var excluded = new Godot.Collections.Array<Rid>();
            void AddCasterRids(Node node)
            {
                if (!Live(node)) return;
                if (node is CollisionObject2D body) excluded.Add(body.GetRid());
                foreach (Node child in node.GetChildren()) AddCasterRids(child);
            }
            AddCasterRids(_player);
            using PhysicsRayQueryParameters2D query = PhysicsRayQueryParameters2D.Create(origin, anchor);
            if (!Live(query)) return "unavailable-query";
            query.CollideWithAreas = true; query.CollideWithBodies = true; query.HitFromInside = false;
            query.CollisionMask = CombatCollisionLayers.World | CombatCollisionLayers.Enemy |
                CombatCollisionLayers.ThreadTarget;
            query.Exclude = excluded;
            World2D world = _player.GetWorld2D();
            if (!Live(world)) return "unavailable-world";
            PhysicsDirectSpaceState2D space = world.DirectSpaceState;
            if (!Live(space)) return "unavailable-space";
            Godot.Collections.Dictionary hit = space.IntersectRay(query);
            if (hit.Count == 0) return $"clear origin={origin} anchor={anchor}";
            GodotObject collider = hit.ContainsKey("collider") ? hit["collider"].AsGodotObject() : null;
            return $"first_collider={Identity(collider)} hit_point=" +
                $"{(hit.ContainsKey("position") ? hit["position"].AsVector2().ToString() : "unavailable")} " +
                $"origin={origin} anchor={anchor}";
        }

        private void Write(string source, bool boundary)
        {
            if (!boundary && _lines >= 12) { _suppressed++; return; }
            if (!boundary) _lines++;
            PlayerInputFrame input = Live(_input) ? _input.CurrentFrame : default;
            MechanicalClawFrame claw = Live(_claw) ? _claw.CurrentFrame : MechanicalClawFrame.Idle();
            var contacts = new List<string>();
            if (Live(_player))
                for (int i = 0; i < Math.Min(8, _player.GetSlideCollisionCount()); i++)
                {
                    KinematicCollision2D contact = _player.GetSlideCollision(i);
                    if (Live(contact)) contacts.Add($"{Identity(contact.GetCollider() as GodotObject)}:" +
                        $"normal={contact.GetNormal()}:point={contact.GetPosition()}");
                }
            string mechanismState = !Live(_mechanism) ? "invalid" : _mechanism switch
            {
                CanyonSteamValve linkage => $"linkage.IsActivated={linkage.IsActivated}",
                CanyonShortcutWinch winch => $"winch.IsOpen={winch.IsOpen}",
                _ => "unavailable"
            };
            GD.Print($"TASK10_POST_SPLIT_CONTROL_DIAGNOSTIC source={source} " +
                $"physics={Engine.GetPhysicsFrames()} elapsed={Engine.GetPhysicsFrames() - _start} loop_budget=120 " +
                $"sample_sequence={(Live(_input) ? _input.CurrentFrameSequence.ToString() : "invalid")} " +
                $"sampled_mode_edge={input.GrappleModePressed} primary_pressed_held_released=" +
                $"{input.PrimaryPressed}/{input.PrimaryHeld}/{input.PrimaryReleased} sampled_mouse={input.MouseWorld} " +
                $"player={(Live(_player) ? _player.GlobalPosition.ToString() : "invalid")} " +
                $"velocity={(Live(_player) ? _player.Velocity.ToString() : "invalid")} " +
                $"floor={(Live(_player) ? _player.IsOnFloor().ToString() : "invalid")} contacts_first8=[{string.Join(';', contacts)}] " +
                $"target={Identity(_target)} anchor={(Live(_target) ? _target.WorldAnchor.ToString() : "invalid")} " +
                $"distance={(Live(_player) && Live(_target) ? _player.GlobalPosition.DistanceTo(_target.WorldAnchor).ToString() : "invalid")} " +
                $"maxrange_public_default={MechanicalClawSettings.Default.MaxRange} " +
                $"mode={(Live(_modes) ? _modes.CurrentMode.ToString() : "invalid")} " +
                $"CanBeginGrapple={(Live(_modes) && Live(_input) ? _modes.CanBeginGrapple.ToString() : "invalid")} " +
                $"energy_heat_overheated={(Live(_energy) ? $"{_energy.EnergyRatio}/{_energy.HeatRatio}/{_energy.IsOverheated}" : "invalid")} " +
                $"shield_sampled_active={input.ShieldHeld}/{(Live(_shield) ? _shield.IsActive.ToString() : "invalid")} " +
                $"claw_valid={Live(_claw)} state={claw.State} cast={claw.CastId} next_cast={claw.NextCastId} failure={claw.Failure} " +
                $"current_target={Identity(Live(_claw) ? _claw.CurrentTarget : null)} effective_visibility={claw.EffectiveVisibility} " +
                $"production_resolver_result=not-public diagnostic_admission_ray_physics={_rayPhysics} " +
                $"diagnostic_not_production_ray=[{_ray}] " +
                $"ApplicationCount={(Live(_adapter) ? _adapter.ApplicationCount.ToString() : "invalid")} {mechanismState} " +
                $"hp={(Live(_health) ? _health.CurrentHealth.ToString() : "invalid")} " +
                $"recovery={_monitor.RecoveryRequested}/{_monitor.RecoveryCompleted} " +
                $"primary_samples={_primarySamples} claw_publications={_publications} lines={_lines} suppressed={_suppressed} " +
                $"diagnostic_errors={_errors} last_error={_lastError} disposed={_disposed} " +
                $"listeners_attached={_physicsSubscribed}/{_clawSubscribed}");
        }
        private void Safely(Action action)
        {
            try { action(); }
            catch (Exception error) { _errors++; _lastError = $"{error.GetType().Name}:{Compact(error.Message)}"; }
        }
        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            Safely(() => { if (_physicsSubscribed && Live(_tree)) _tree.PhysicsFrame -= ObservePhysics;
                _physicsSubscribed = false; });
            Safely(() => { if (_clawSubscribed && Live(_claw)) _claw.ClawFrameChanged -= ObserveClaw;
                _clawSubscribed = false; });
            Boundary("finally-summary");
            // Even if a full snapshot fails, expose the evidence gap without replacing route failure.
            Safely(() => GD.Print($"TASK10_POST_SPLIT_CONTROL_SUMMARY physics={Engine.GetPhysicsFrames()} " +
                $"target={Identity(_target)} primary_samples={_primarySamples} claw_publications={_publications} " +
                $"lines={_lines} suppressed={_suppressed} diagnostic_errors={_errors} last_error={_lastError} " +
                $"listeners_attached={_physicsSubscribed}/{_clawSubscribed}"));
        }
    }

    // Passive, scoped to the two original post-control helper windows. No driver hook or input writes.
    private sealed class Task10PostControlHandoffDiagnostic : IDisposable
    {
        private readonly SceneTree _tree;
        private readonly CharacterBody2D _player;
        private readonly RouteMonitor _monitor;
        private readonly PrologueLevelController _level;
        private readonly PrologueSector _entrySector;
        private readonly bool _exploration;
        private readonly ulong _start = Engine.GetPhysicsFrames();
        private PlayerInputReader _input;
        private PlayerActionModeController _modes;
        private MechanicalClawController _claw;
        private HealthComponent _health;
        private bool _physicsAttached, _clawAttached, _requestedAttached, _completedAttached;
        private bool _damageAttached, _deathAttached, _disposed;
        private bool _priorStepContact, _supportLossSeen, _dropSeen;
        private int _samples, _changes, _clawChanges, _suppressed, _faults, _publications;
        private int _requests, _completions, _damages, _deaths, _primaryEdges;
        private ulong _lastPhysics = ulong.MaxValue, _lastPrimarySequence = ulong.MaxValue;
        private string _lastKey, _lastPublication, _lastFault = "none";
        private string _requestReasons = "none", _completionReasons = "none";

        public Task10PostControlHandoffDiagnostic(SceneTree tree, CharacterBody2D player,
            RouteMonitor monitor, PrologueLevelController level, PrologueSector sector, bool exploration)
        {
            _tree = tree; _player = player; _monitor = monitor; _level = level;
            _entrySector = sector; _exploration = exploration;
            Safely(() =>
            {
                if (!Live(player)) return;
                _input = player.GetNodeOrNull<PlayerInputReader>("Input");
                _modes = player.GetNodeOrNull<PlayerActionModeController>("ActionModes");
                _claw = player.GetNodeOrNull<MechanicalClawController>("MechanicalClaw");
                _health = player.GetNodeOrNull<HealthComponent>("Health");
            });
            Safely(() => { if (Live(tree)) { tree.PhysicsFrame += ObservePhysics; _physicsAttached = true; } });
            Safely(() => { if (Live(_claw) && !exploration) { _claw.ClawFrameChanged += ObserveClaw; _clawAttached = true; } });
            Safely(() => { if (Live(level) && exploration) { level.RecoveryRequested += Requested; _requestedAttached = true; } });
            Safely(() => { if (Live(level) && exploration) { level.RecoveryCompleted += Completed; _completedAttached = true; } });
            Safely(() => { if (Live(_health) && exploration) { _health.Damaged += Damaged; _damageAttached = true; } });
            Safely(() => { if (Live(_health) && exploration) { _health.Died += Died; _deathAttached = true; } });
            Safely(() => _priorStepContact = UpwardContact(Support("ShortcutStep4116")));
            Boundary("entry-before-original-helper");
        }

        private static bool Live(GodotObject value) => GodotObject.IsInstanceValid(value);
        private static string Id(GodotObject value) => !Live(value) ? "unavailable" : value is Node node
            ? $"{(node.IsInsideTree() ? node.GetPath().ToString() : "off-tree")}#{node.GetInstanceId()}"
            : $"#{value.GetInstanceId()}";
        private static string Compact(string value) => (value ?? "none").Replace('\r', ' ').Replace('\n', ' ')
            .Substring(0, Math.Min((value ?? "none").Length, 240));
        private PrologueSector CurrentBasin()
        {
            SeamlessPrologueWorld world = _monitor.World;
            return Live(world) && world.TryGetMountedSector(PrologueSectorId.CanyonBasin, out PrologueSector basin)
                && Live(basin) ? basin : null;
        }
        private StaticBody2D Support(string name)
        {
            PrologueSector sector = _exploration ? CurrentBasin() : _entrySector;
            return Live(sector) ? sector.GetNodeOrNull<StaticBody2D>($"Gameplay/Collision/{name}") : null;
        }
        private bool UpwardContact(StaticBody2D support)
        {
            if (!Live(_player) || !Live(support)) return false;
            for (int i = 0; i < _player.GetSlideCollisionCount(); i++)
            {
                KinematicCollision2D contact = _player.GetSlideCollision(i);
                if (Live(contact) && contact.GetCollider() is GodotObject body && Live(body) &&
                    body.GetInstanceId() == support.GetInstanceId() && contact.GetNormal().Y < -.5f) return true;
            }
            return false;
        }
        private string SupportFacts(string name)
        {
            StaticBody2D support = Support(name);
            CollisionShape2D shape = Live(support) ? support.GetNodeOrNull<CollisionShape2D>("Collision") : null;
            CollisionShape2D capsuleShape = Live(_player) ? _player.GetNodeOrNull<CollisionShape2D>("BodyCollider") : null;
            bool upward = UpwardContact(support);
            if (!Live(shape) || !Live(capsuleShape) || !Live(shape.Shape) || !Live(capsuleShape.Shape) ||
                shape.Shape is not RectangleShape2D rectangle || capsuleShape.Shape is not CapsuleShape2D capsule)
                return $"{name}={Id(support)} upward_contact={upward} full_capsule_x_containment=unavailable";
            Rect2 bounds = new Rect2(shape.ToGlobal(-rectangle.Size / 2f),
                shape.ToGlobal(rectangle.Size / 2f) - shape.ToGlobal(-rectangle.Size / 2f)).Abs();
            float left = capsuleShape.ToGlobal(new Vector2(-capsule.Radius, 0)).X;
            float right = capsuleShape.ToGlobal(new Vector2(capsule.Radius, 0)).X;
            bool contained = left >= bounds.Position.X + 2f && right <= bounds.End.X - 2f;
            return $"{name}={Id(support)} bounds={bounds} collider_disabled={shape.Disabled} " +
                $"capsule_x={left}/{right} full_capsule_x_containment={contained} upward_contact={upward} " +
                $"full_upward_support={contained && upward && !shape.Disabled}";
        }
        private string TrenchFacts()
        {
            PrologueSector basin = CurrentBasin();
            CanyonSteamDiverter pair = Live(basin) ? basin.GetNodeOrNull<CanyonSteamDiverter>(
                "Gameplay/Mechanisms/SteamDiverterTrench") : null;
            CanyonSteamJet left = Live(pair) ? pair.GetNodeOrNull<CanyonSteamJet>("LeftJet") : null;
            CollisionShape2D shape = Live(left) ? left.GetNodeOrNull<CollisionShape2D>("Collision") : null;
            return $"trench_pair={Id(pair)} selected_side={(Live(pair) ? pair.SelectedSide.ToString() : "unavailable")} " +
                $"handoff={(Live(pair) ? pair.IsHandingOff.ToString() : "unavailable")} left_jet={Id(left)} " +
                $"left_jet_frame={(Live(left) ? left.Frame.ToString() : "unavailable")} " +
                $"left_disabled_for_run={(Live(left) ? left.DisabledForRun.ToString() : "unavailable")} " +
                $"left_monitoring={(Live(left) ? left.Monitoring.ToString() : "unavailable")} " +
                $"left_collider_disabled={(Live(shape) ? shape.Disabled.ToString() : "unavailable")}";
        }
        private void ObservePhysics() => Safely(() =>
        {
            if (_disposed || _lastPhysics == Engine.GetPhysicsFrames()) return;
            _lastPhysics = Engine.GetPhysicsFrames();
            PlayerInputFrame input = Live(_input) ? _input.CurrentFrame : default;
            if (Live(_input) && input.PrimaryPressed && _lastPrimarySequence != _input.CurrentFrameSequence)
            { _lastPrimarySequence = _input.CurrentFrameSequence; _primaryEdges++; }
            MechanicalClawFrame claw = Live(_claw) ? _claw.CurrentFrame : MechanicalClawFrame.Idle();
            bool stepContact = _exploration && UpwardContact(Support("ShortcutStep4116"));
            string reason = "state-or-input-change";
            if (_exploration && !_supportLossSeen && _priorStepContact && !stepContact)
            { _supportLossSeen = true; reason = "first-step-upward-support-loss"; }
            _priorStepContact = stepContact;
            if (_exploration && !_dropSeen && Live(_player) && _player.GlobalPosition.Y > 4116f)
            { _dropSeen = true; reason += "+first-player-origin-below-step-top"; }
            string key = $"{input.MoveAxis}/{input.JumpPressed}/{input.JumpHeld}/{input.GrappleModePressed}/" +
                $"{input.PrimaryPressed}/{input.PrimaryHeld}/{input.PrimaryReleased}/{_primaryEdges}/" +
                $"{claw.State}/{claw.CastId}/{claw.NextCastId}/{claw.Failure}/" +
                $"{(Live(_modes) ? _modes.CurrentMode.ToString() : "unavailable")}/" +
                $"{(Live(_health) ? _health.CurrentHealth : -1)}/{_monitor.RecoveryRequested}/" +
                $"{_monitor.RecoveryCompleted}/{stepContact}/{_supportLossSeen}/{_dropSeen}";
            if (_samples < 8) { _samples++; Write("first8-PhysicsFrame-prior-node-processing", false); }
            if (key != _lastKey) { _lastKey = key; Change(reason); }
        });
        private void ObserveClaw(MechanicalClawFrame frame, GrappleSurface2D target) => Safely(() =>
        {
            if (_disposed) return;
            _publications++;
            string key = $"{frame.State}/{frame.CastId}/{frame.NextCastId}/{frame.Failure}/{Id(target)}";
            if (key == _lastPublication) return;
            _lastPublication = key;
            if (_clawChanges >= 12) { _suppressed++; return; }
            _clawChanges++;
            Write($"ClawFrameChanged-published state={frame.State} cast={frame.CastId} " +
                $"next={frame.NextCastId} failure={frame.Failure} target={Id(target)}");
        });
        private void Requested(string reason) => Safely(() =>
        {
            _requests++;
            if (_requests <= 2) { _requestReasons += $";{_requests}:{Compact(reason)}"; Change($"RecoveryRequested actual_public_reason={Compact(reason)}"); }
            else _suppressed++;
        });
        private void Completed(string reason) => Safely(() =>
        {
            _completions++;
            if (_completions <= 2) { _completionReasons += $";{_completions}:{Compact(reason)}"; Change($"RecoveryCompleted actual_public_reason={Compact(reason)}"); }
            else _suppressed++;
        });
        private void Damaged(int remaining, Vector2 impulse) => Safely(() =>
        { _damages++; Change($"Health.Damaged remaining={remaining} impulse={impulse} cause=not-public"); });
        private void Died() => Safely(() => { _deaths++; Change("Health.Died actual-public-event"); });
        private void Change(string reason)
        {
            if (_changes >= (_exploration ? 24 : 12)) { _suppressed++; return; }
            _changes++;
            Write(reason, false);
        }
        public void Boundary(string reason) => Safely(() => Write(reason, true));
        public void Failure(Exception error) => Boundary($"original-helper-failure={error.GetType().Name}:{Compact(error.Message)}");
        private void Write(string reason, bool boundary = false)
        {
            PlayerInputFrame input = Live(_input) ? _input.CurrentFrame : default;
            MechanicalClawFrame claw = Live(_claw) ? _claw.CurrentFrame : MechanicalClawFrame.Idle();
            var contacts = new List<string>();
            if (Live(_player))
                for (int i = 0; i < _player.GetSlideCollisionCount(); i++)
                {
                    KinematicCollision2D contact = _player.GetSlideCollision(i);
                    if (Live(contact)) contacts.Add($"{Id(contact.GetCollider() as GodotObject)} " +
                        $"normal={contact.GetNormal()} point={contact.GetPosition()}");
                }
            SeamlessPrologueWorld world = _monitor.World;
            PrologueGameFlowController flow = Live(_level) ? _level.GetNodeOrNull<PrologueGameFlowController>("GameFlow") : null;
            GD.Print($"TASK10_POST_CONTROL_HANDOFF window={(_exploration ? "Explore-step-walkway" : "Main-final-catch")} " +
                $"reason={reason} boundary={boundary} physics={Engine.GetPhysicsFrames()} elapsed={Engine.GetPhysicsFrames() - _start} " +
                $"input_sequence={(Live(_input) ? _input.CurrentFrameSequence.ToString() : "unavailable")} " +
                $"move={input.MoveAxis} jump_pressed_held={input.JumpPressed}/{input.JumpHeld} E={input.GrappleModePressed} " +
                $"primary_pressed_held_released={input.PrimaryPressed}/{input.PrimaryHeld}/{input.PrimaryReleased} " +
                $"mouse={input.MouseWorld} mode={(Live(_modes) ? _modes.CurrentMode.ToString() : "unavailable")} " +
                $"CanBeginGrapple={(Live(_modes) ? _modes.CanBeginGrapple.ToString() : "unavailable")} " +
                $"player={Id(_player)} position={(Live(_player) ? _player.GlobalPosition.ToString() : "unavailable")} " +
                $"velocity={(Live(_player) ? _player.Velocity.ToString() : "unavailable")} contacts=[{string.Join(';', contacts)}] " +
                $"claw_valid={Live(_claw)} state={claw.State} cast={claw.CastId} next_cast={claw.NextCastId} " +
                $"rope_length={claw.RopeLength} failure={claw.Failure} target={Id(Live(_claw) ? _claw.CurrentTarget : null)} " +
                $"production_resolver=not-public independent_resolution=original-helper-only " +
                $"supports=[{(_exploration ? SupportFacts("ShortcutStep4116") + ";" + SupportFacts("ShortcutBasinWalkway") : SupportFacts("AscentGrip9") + ";" + SupportFacts("AscentFinalCatch"))}] " +
                $"hp={(Live(_health) ? _health.CurrentHealth.ToString() : "unavailable")} recovery_monitor={_monitor.RecoveryRequested}/{_monitor.RecoveryCompleted} " +
                $"recovery_public_events={_requests}/{_completions} damages_deaths={_damages}/{_deaths} primary_edges={_primaryEdges} " +
                $"flow={(Live(flow) ? flow.State.ToString() : "unavailable")} current_sector={(Live(world) ? world.CurrentSector.ToString() : "unavailable")} " +
                $"mounted={(Live(world) ? string.Join(",", world.MountedSectorIds) : "unavailable")} live_basin={Id(CurrentBasin())} " +
                $"entry_sector={Id(_entrySector)} {(_exploration ? TrenchFacts() : "trench=out-of-window")} " +
                $"samples={_samples}/8 changes={_changes}/{(_exploration ? 24 : 12)} suppressed={_suppressed} " +
                $"claw_publications={_publications} claw_changes={_clawChanges}/12 request_reasons=[{_requestReasons}] " +
                $"completion_reasons=[{_completionReasons}] faults={_faults} last_fault={_lastFault} disposed={_disposed} " +
                $"attached_physics_claw_recovery_damage_death={_physicsAttached}/{_clawAttached}/{_requestedAttached}/{_completedAttached}/{_damageAttached}/{_deathAttached}");
        }
        private void Safely(Action action)
        {
            try { action(); }
            catch (Exception error) { _faults++; _lastFault = $"{error.GetType().Name}:{Compact(error.Message)}"; }
        }
        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            Safely(() => { if (_physicsAttached && Live(_tree)) _tree.PhysicsFrame -= ObservePhysics; _physicsAttached = false; });
            Safely(() => { if (_clawAttached && Live(_claw)) _claw.ClawFrameChanged -= ObserveClaw; _clawAttached = false; });
            Safely(() => { if (_requestedAttached && Live(_level)) _level.RecoveryRequested -= Requested; _requestedAttached = false; });
            Safely(() => { if (_completedAttached && Live(_level)) _level.RecoveryCompleted -= Completed; _completedAttached = false; });
            Safely(() => { if (_damageAttached && Live(_health)) _health.Damaged -= Damaged; _damageAttached = false; });
            Safely(() => { if (_deathAttached && Live(_health)) _health.Died -= Died; _deathAttached = false; });
            Boundary("finally-after-listener-detach");
            Safely(() => GD.Print($"TASK10_POST_CONTROL_HANDOFF_SUMMARY exploration={_exploration} " +
                $"samples={_samples} changes={_changes} claw_changes={_clawChanges} suppressed={_suppressed} publications={_publications} " +
                $"recovery_events={_requests}/{_completions} damages_deaths={_damages}/{_deaths} " +
                $"request_reasons=[{_requestReasons}] completion_reasons=[{_completionReasons}] " +
                $"first_step_support_loss={_supportLossSeen} first_origin_below_step_top={_dropSeen} " +
                $"faults={_faults} last_fault={_lastFault} " +
                $"attached={_physicsAttached}/{_clawAttached}/{_requestedAttached}/{_completedAttached}/{_damageAttached}/{_deathAttached}"));
        }
    }

    private static async Task StageTask10Grip9ControlApproach(SceneTree tree,
        PrologueLevelController level, CharacterBody2D player, RouteMonitor monitor,
        PrologueSector ascent, GrappleSurface2D control, Action observe,
        Func<Action, Action> swapApproachGuard, Func<Task> keyboardFinalCatchTransfer = null)
    {
        bool Live(Node node) => node != null && GodotObject.IsInstanceValid(node) &&
            node.IsInsideTree();
        TestAssert.True(Live(player) && Live(level) && Live(ascent) && Live(control),
            "Task10 Grip9 control approach requires native-valid live entry nodes");
        StaticBody2D gallery = ascent.GetNode<StaticBody2D>("Gameplay/Collision/SplitUpperGallery");
        StaticBody2D grip9 = ascent.GetNode<StaticBody2D>("Gameplay/Collision/AscentGrip9");
        CollisionShape2D galleryShape = gallery.GetNode<CollisionShape2D>("Collision");
        CollisionShape2D grip9Shape = grip9.GetNode<CollisionShape2D>("Collision");
        bool keyboardLinkage = KeyboardRouteInputDriver.Current != null &&
            control == ascent.GetNode<GrappleSurface2D>(
                "Gameplay/GrappleSurfaces/CourtyardSealLinkageControl");
        TestAssert.True(keyboardLinkage == (keyboardFinalCatchTransfer != null),
            "only the exact keyboard courtyard linkage stage moves its real FinalCatch transfer ahead of control");
        StaticBody2D finalCatch = keyboardLinkage
            ? ascent.GetNode<StaticBody2D>("Gameplay/Collision/AscentFinalCatch") : null;
        CollisionShape2D finalCatchShape = finalCatch?.GetNode<CollisionShape2D>("Collision");
        HealthComponent health = player.GetNode<HealthComponent>("Health");
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        PrologueGameFlowController flow = level.GetNode<PrologueGameFlowController>("GameFlow");
        TestAssert.True(Live(health) && Live(motor) && Live(input) && Live(flow),
            "Task10 Grip9 control approach requires live player components");
        ulong playerId = player.GetInstanceId();
        int entryHealth = health.CurrentHealth;
        int entryRequests = monitor.RecoveryRequested;
        int entryRecoveries = monitor.RecoveryCompleted;
        int entryJumps = motor.AcceptedJumpCount;
        int entryDashes = motor.AcceptedDashCount;
        int lastJumps = entryJumps;
        bool previousGallerySupport = false;
        bool groundedJumpSeen = false;
        bool preparingLaunch = true;
        bool requireGrip9Support = false;
        bool requireFinalCatchSupport = false;
        string phase = "entry";
        int walkFrames = 0, settleFrames = 0, cameraFrames = 0;
        int guardTraceCount = 0, physicsTraceCount = 0, diagnosticFaults = 0;
        string previousGuardFacts = "none", previousPhysicsFacts = "none";
        string lastDiagnosticFault = "none";
        bool physicsTraceAttached = false;

        bool Supported(StaticBody2D body, CollisionShape2D shape) =>
            Live(player) && Live(body) && Live(shape) &&
            TryTask10CapsuleCorridor(player, shape, out _, out _, out _, out _) &&
            HasFloorContact(player, body);
        void Check(bool passed, string condition) => TestAssert.True(passed,
            $"Task10 Grip9 control approach {condition}; phase={phase} player_id={playerId} " +
            $"walk_settle_camera_frames={walkFrames}/90,{settleFrames}/12,{cameraFrames}/30");
        void DiagnosticSafely(Action read)
        {
            try { read(); }
            catch (Exception error)
            { diagnosticFaults++; lastDiagnosticFault = error.GetType().Name; }
        }
        string DiagnosticFacts()
        {
            bool playerLive = Live(player), inputLive = Live(input), motorLive = Live(motor);
            var contacts = new List<string>();
            if (playerLive)
                for (int index = 0; index < Math.Min(4, player.GetSlideCollisionCount()); index++)
                {
                    KinematicCollision2D collision = player.GetSlideCollision(index);
                    if (!GodotObject.IsInstanceValid(collision)) { contacts.Add("invalid"); continue; }
                    GodotObject collider = collision.GetCollider();
                    string identity = GodotObject.IsInstanceValid(collider)
                        ? $"{(collider as Node)?.Name}#{collider.GetInstanceId()}" : "invalid";
                    contacts.Add($"{identity}:{collision.GetNormal()}");
                }
            bool? countChanged = motorLive ? motor.AcceptedJumpCount != lastJumps : null;
            bool? exactlyOne = motorLive ? motor.AcceptedJumpCount == entryJumps + 1 : null;
            bool? edge = inputLive ? input.CurrentFrame.JumpPressed : null;
            bool? right = inputLive ? input.CurrentFrame.MoveAxis > 0f : null;
            return $"phase={phase} physics={Engine.GetPhysicsFrames()} " +
                $"input_seq={(inputLive ? input.CurrentFrameSequence.ToString() : "invalid")} " +
                $"counts=entry:{entryJumps}/guard_previous:{lastJumps}/current:" +
                $"{(motorLive ? motor.AcceptedJumpCount.ToString() : "invalid")} " +
                $"conj_not_seen={!groundedJumpSeen} conj_exact_one={exactlyOne} " +
                $"conj_previous_gallery={previousGallerySupport} conj_jump_edge={edge} " +
                $"conj_right={right} count_changed={countChanged} " +
                $"gallery_full={Supported(gallery, galleryShape)} grip9_full={Supported(grip9, grip9Shape)} " +
                $"move={(inputLive ? input.CurrentFrame.MoveAxis.ToString("R") : "invalid")} " +
                $"jump_edge_held={(inputLive ? $"{input.CurrentFrame.JumpPressed}/{input.CurrentFrame.JumpHeld}" : "invalid")} " +
                $"position={(playerLive ? player.GlobalPosition.ToString() : "invalid")} " +
                $"velocity={(playerLive ? player.Velocity.ToString() : "invalid")} " +
                $"contacts=[{string.Join(';', contacts)}] " +
                $"hp={entryHealth}/{(Live(health) ? health.CurrentHealth.ToString() : "invalid")} " +
                $"recoveries={entryRequests}/{entryRecoveries}->{monitor.RecoveryRequested}/{monitor.RecoveryCompleted} " +
                $"dash={entryDashes}/{(motorLive ? motor.AcceptedDashCount.ToString() : "invalid")} " +
                $"player_id={playerId}/{(playerLive ? player.GetInstanceId().ToString() : "invalid")} " +
                $"monitor_player_id={(Live(monitor.Player) ? monitor.Player.GetInstanceId().ToString() : "invalid")}";
        }
        void ObservePhysicsTrace()
        {
            // Passive signal sampling only: no Guard/observe, wait, input or gameplay writes.
            if (physicsTraceCount >= 8) return;
            physicsTraceCount++;
            DiagnosticSafely(() =>
            {
                string current = DiagnosticFacts();
                GD.Print($"TASK10_GRIP9_PAIRED source=physics-signal index={physicsTraceCount}/8 " +
                    $"previous=[{previousPhysicsFacts}] current=[{current}]");
                previousPhysicsFacts = current;
            });
        }
        void Guard()
        {
            // Validate native wrappers before reading any current player/component properties.
            Check(Live(player) && Live(health) && Live(motor) && Live(input) && Live(flow) &&
                Live(control) && Live(gallery) && Live(grip9), "keeps native-valid live nodes");
            Check(Live(monitor.Player) && monitor.Player.GetInstanceId() == playerId &&
                player.GetInstanceId() == playerId && flow.State == PrologueGameFlowState.Playing &&
                entryHealth > 0 && health.CurrentHealth == entryHealth &&
                monitor.RecoveryRequested == entryRequests &&
                monitor.RecoveryCompleted == entryRecoveries &&
                player.GlobalPosition.IsFinite() && player.Velocity.IsFinite() &&
                motor.AcceptedDashCount == entryDashes &&
                motor.AcceptedJumpCount >= entryJumps && motor.AcceptedJumpCount <= entryJumps + 1,
                "preserves same Playing player, HP, recoveries and one jump/no dash");
            DiagnosticSafely(() =>
            {
                string current = DiagnosticFacts();
                if (guardTraceCount < 8)
                {
                    guardTraceCount++;
                    GD.Print($"TASK10_GRIP9_PAIRED source=guard index={guardTraceCount}/8 " +
                        $"previous=[{previousGuardFacts}] current=[{current}]");
                }
                if (motor.AcceptedJumpCount != lastJumps)
                {
                    GD.Print($"TASK10_GRIP9_JUMP_TRANSITION source=guard " +
                        $"previous=[{previousGuardFacts}] current=[{current}]");
                    if (!(!groundedJumpSeen && motor.AcceptedJumpCount == entryJumps + 1 &&
                          previousGallerySupport && input.CurrentFrame.JumpPressed &&
                          input.CurrentFrame.MoveAxis > 0f))
                        GD.Print($"TASK10_GRIP9_JUMP_CONJUNCTION_FAILED source=guard " +
                            $"previous=[{previousGuardFacts}] current=[{current}]");
                }
                previousGuardFacts = current;
            });
            if (motor.AcceptedJumpCount != lastJumps)
            {
                Check(!groundedJumpSeen && motor.AcceptedJumpCount == entryJumps + 1 &&
                    previousGallerySupport && input.CurrentFrame.JumpPressed &&
                    input.CurrentFrame.MoveAxis > 0f,
                    "accepts exactly one rightward jump initiated from complete Gallery support");
                groundedJumpSeen = true;
            }
            lastJumps = motor.AcceptedJumpCount;
            previousGallerySupport = Supported(gallery, galleryShape);
            if (preparingLaunch)
                Check(previousGallerySupport && motor.AcceptedJumpCount == entryJumps,
                    "prepares launch with full Gallery upward contact and unchanged jump count");
            if (requireGrip9Support)
                Check(Supported(grip9, grip9Shape), "retains full capsule Grip9 upward contact");
            if (requireFinalCatchSupport)
                Check(Supported(finalCatch, finalCatchShape), "retains full capsule FinalCatch upward contact");
        }
        void Log(string boundary) => GD.Print($"TASK10_GRIP9_CONTROL_{boundary} " +
            $"phase={phase} physics={Engine.GetPhysicsFrames()} player_id={playerId} " +
            $"position={player.GlobalPosition} velocity={player.Velocity} " +
            $"gallery_full={Supported(gallery, galleryShape)} grip9_full={Supported(grip9, grip9Shape)} " +
            $"final_catch_full={Supported(finalCatch, finalCatchShape)} keyboard_linkage={keyboardLinkage} " +
            $"hp={entryHealth}->{health.CurrentHealth} recoveries={entryRequests}/{entryRecoveries}->" +
            $"{monitor.RecoveryRequested}/{monitor.RecoveryCompleted} jumps={entryJumps}->" +
            $"{motor.AcceptedJumpCount} dashes={entryDashes}->{motor.AcceptedDashCount} " +
            $"sample={input.CurrentFrameSequence} move={input.CurrentFrame.MoveAxis} " +
            $"jump={input.CurrentFrame.JumpPressed}/{input.CurrentFrame.JumpHeld} " +
            $"walk_settle_camera_frames={walkFrames}/90,{settleFrames}/12,{cameraFrames}/30");
        async Task Tick()
        {
            await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
            observe(); // Same original monitor/evidence/diagnostics, then this scoped guard.
        }
        bool Stationary() => Mathf.Abs(player.Velocity.X) <= 2f &&
            Mathf.Abs(player.Velocity.Y) <= 2f;
        async Task<ulong> WalkAndSettle(float targetX, string stance)
        {
            // All three stances share the original90 walk /12 settle allowances.
            bool keyboardGround = KeyboardRouteInputDriver.Current != null;
            bool finalCatchGroundBraking = keyboardLinkage && stance == "final-catch-control";
            int entryWalkFrames = walkFrames, entrySettleFrames = settleFrames;
            float predictedStopX = float.NaN;
            int forecastSteps = 0;
            phase = $"{stance}-walk-brake";
            while (walkFrames < 90 &&
                (Mathf.Abs(player.GlobalPosition.X - targetX) > 3f || !Stationary()))
            {
                float delta = targetX - player.GlobalPosition.X;
                float speed = player.Velocity.X;
                bool right, left;
                if (keyboardGround)
                {
                    var stop = FreeMotionForecast.Neutral(speed, true, motor.MotionSettings,
                        motor.ThrusterState.Module, 1d / Engine.PhysicsTicksPerSecond,
                        90 - walkFrames + 12 - settleFrames, 2f);
                    Check(stop.SpeedThresholdReached,
                        "neutral stop forecast fits the remaining original shared walk/settle budget");
                    predictedStopX = player.GlobalPosition.X + stop.NetDistance;
                    forecastSteps = stop.Steps;
                    // Once the actual module's neutral endpoint is in the
                    // inset band, coast instead of reversing every near-target
                    // sample using the obsolete air-acceleration estimate.
                    float stopError = targetX - predictedStopX;
                    right = stopError > 2f;
                    left = stopError < -2f;
                }
                else
                {
                    float brakingAcceleration = finalCatchGroundBraking
                        ? motor.Tuning.GroundAcceleration : motor.Tuning.AirAcceleration;
                    float brake = speed * speed / (2f * brakingAcceleration) + 4f;
                    right = delta > 2f && (speed <= 0f || brake < delta);
                    left = delta < -2f && (speed >= 0f || brake < -delta);
                    if (!right && !left && Mathf.Abs(speed) > 20f)
                    { left = speed > 0f; right = speed < 0f; }
                }
                SendAction(InputActions.MoveLeft, left);
                SendAction(InputActions.MoveRight, right);
                walkFrames++;
                await Tick();
            }
            if (finalCatchGroundBraking) Log("KEYBOARD_FINAL_CATCH_WALK_END");
            SendAction(InputActions.MoveLeft, false);
            SendAction(InputActions.MoveRight, false);
            SendAction(InputActions.Jump, false);
            ulong releasedSequence = input.CurrentFrameSequence;
            phase = $"{stance}-neutral-settle";
            while (settleFrames < 12 &&
                (input.CurrentFrameSequence <= releasedSequence ||
                 input.CurrentFrame.MoveAxis != 0f || input.CurrentFrame.JumpHeld || !Stationary()))
            { settleFrames++; await Tick(); }
            if (finalCatchGroundBraking) Log("KEYBOARD_FINAL_CATCH_SETTLE_END");
            if (keyboardGround)
                GD.Print($"TASK10_GRIP9_STANCE_STOP stance={stance} target_x={targetX:R} " +
                    $"player={player.GlobalPosition} velocity={player.Velocity} predicted_stop_x={predictedStopX:R} " +
                    $"forecast_steps={forecastSteps} walk={entryWalkFrames}->{walkFrames}/90 " +
                    $"settle={entrySettleFrames}->{settleFrames}/12 camera={cameraFrames}/30 " +
                    $"sample={releasedSequence}->{input.CurrentFrameSequence} move={input.CurrentFrame.MoveAxis} " +
                    "original_shared_budgets=true no_pose_or_velocity_write=true");
            return releasedSequence;
        }
        bool Visible()
        {
            Viewport viewport = player.GetViewport();
            Vector2 logicalTarget = viewport.GetCanvasTransform() * control.WorldAnchor;
            return logicalTarget.IsFinite() && viewport.GetVisibleRect().Grow(-32f).HasPoint(logicalTarget);
        }

        Action previousGuard = swapApproachGuard(Guard);
        try
        {
            DiagnosticSafely(() =>
            {
                GD.Print($"TASK10_GRIP9_PAIRED_ENTRY source=entry current=[{DiagnosticFacts()}]");
                if (GodotObject.IsInstanceValid(tree))
                {
                    tree.PhysicsFrame += ObservePhysicsTrace;
                    physicsTraceAttached = true;
                }
                else { diagnosticFaults++; lastDiagnosticFault = "invalid-tree"; }
            });
            Guard();
            Check(previousGallerySupport, "enters on complete actual Gallery support/upward contact");
            Log("ENTRY");
            ulong launchReleasedSequence = await WalkAndSettle(4200f, "gallery-launch");
            Guard();
            Check(input.CurrentFrameSequence > launchReleasedSequence && input.CurrentFrame.MoveAxis == 0f &&
                !input.CurrentFrame.JumpHeld && !input.CurrentFrame.JumpPressed && Stationary() &&
                Mathf.Abs(player.GlobalPosition.X - 4200f) <= 3f && Supported(gallery, galleryShape) &&
                !groundedJumpSeen && motor.AcceptedJumpCount == entryJumps,
                "releases sampled movement/jump and prepares full Gallery launch at X4200 +/-3 with finite velocity <=2");
            Log("LAUNCH");
            preparingLaunch = false;
            phase = "grounded-transfer";
            await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player, grip9, clawRequired: false);
            Guard();
            Check(groundedJumpSeen && motor.AcceptedJumpCount == entryJumps + 1 &&
                Supported(grip9, grip9Shape), "lands through exactly one actual grounded jump");
            requireGrip9Support = true;
            Log("LANDING");
            float grip9Stance = keyboardLinkage ? 4436f : 4340f;
            ulong releasedSequence = await WalkAndSettle(grip9Stance,
                keyboardLinkage ? "grip9-final-catch" : "grip9-control");
            Check(input.CurrentFrameSequence > releasedSequence && input.CurrentFrame.MoveAxis == 0f &&
                !input.CurrentFrame.JumpHeld && !input.CurrentFrame.JumpPressed && Stationary() &&
                Mathf.Abs(player.GlobalPosition.X - grip9Stance) <= 3f && Supported(grip9, grip9Shape) &&
                groundedJumpSeen && motor.AcceptedJumpCount == entryJumps + 1,
                $"releases sampled movement/jump and settles at X{grip9Stance} +/-3 with finite velocity <=2");
            float controlStance = grip9Stance;
            if (keyboardLinkage)
            {
                // Grip9's previous post ends at X4412. X4436 places the actual
                // capsule to its right, so NE can select the authored FinalCatch
                // post. The unchanged transfer callback proves real attachment,
                // above-post release and complete landing; no ordinary jump is added.
                GrappleSurface2D finalCatchGrip = ascent.GetNode<GrappleSurface2D>(
                    "Gameplay/Collision/AscentFinalCatchGrip/GrappleSurfaceProfile");
                CollisionShape2D postCollision = finalCatchGrip.GetParent().GetNode<CollisionShape2D>("Collision");
                Check(!postCollision.Disabled && postCollision.Shape is RectangleShape2D,
                    "FinalCatch preflight uses its actual enabled authored post rectangle");
                var postRectangle = (RectangleShape2D)postCollision.Shape;
                Vector2 postAim = postCollision.ToGlobal(new Vector2(0f, -postRectangle.Size.Y * .5f + 10f));
                Vector2 postDirection = PlayerKeyboardAimModel.ResolveDirection(postAim - player.GlobalPosition, 1);
                MechanicalClawTargetResolution postSelection = new MechanicalClawTargetResolver().ResolveKeyboard(player, postDirection);
                Check(postDirection.Dot(new Vector2(1f, -1f).Normalized()) > .999f && postSelection.Surface == finalCatchGrip,
                    $"real planned NE selects the authored FinalCatch post before any transfer K; " +
                    $"position={player.GlobalPosition} direction={postDirection} selected={postSelection.Surface?.GetPath()}");
                phase = "keyboard-final-catch-transfer";
                requireGrip9Support = false;
                await keyboardFinalCatchTransfer();
                requireFinalCatchSupport = true;
                Guard();
                // FinalCatch top is Y1320, so the real supported body is near
                // Y1284. From X4780 the control offset is (140,-24): Right wins.
                // Keep the real resolver/LOS check; this is not a forced target.
                // This walk spends the SAME stage-wide 90/12/30 allowances.
                controlStance = 4780f;
                releasedSequence = await WalkAndSettle(controlStance, "final-catch-control");
                Guard();
                MechanicalClawController readyClaw = player.GetNode<MechanicalClawController>("MechanicalClaw");
                Vector2 plannedControl = PlayerKeyboardAimModel.ResolveDirection(control.WorldAnchor - player.GlobalPosition, 1);
                // Evaluate the real query before the conjunction, so an exhausted
                // walk budget cannot hide the final pose or selection behind short-circuiting.
                MechanicalClawTargetResolution controlSelection =
                    new MechanicalClawTargetResolver().ResolveKeyboard(player, plannedControl);
                bool freshSample = input.CurrentFrameSequence > releasedSequence;
                bool neutralMove = input.CurrentFrame.MoveAxis == 0f;
                bool noJumpHeld = !input.CurrentFrame.JumpHeld;
                bool noJumpEdge = !input.CurrentFrame.JumpPressed;
                bool stationary = Stationary();
                bool atControlStance = Mathf.Abs(player.GlobalPosition.X - controlStance) <= 3f;
                bool fullFinalCatch = Supported(finalCatch, finalCatchShape);
                bool clawIdle = readyClaw.CurrentFrame.State == MechanicalClawState.Idle;
                bool clawFailureNone = readyClaw.CurrentFrame.Failure == MechanicalClawFailure.None;
                bool plannedRight = plannedControl.Dot(Vector2.Right) > .999f;
                bool exactControl = controlSelection.Surface == control;
                DiagnosticSafely(() => GD.Print($"TASK10_GRIP9_KEYBOARD_CONTROL_SNAPSHOT " +
                    $"phase={phase} physics={Engine.GetPhysicsFrames()} player_id={playerId} " +
                    $"position={player.GlobalPosition} velocity={player.Velocity} " +
                    $"sample={input.CurrentFrameSequence} released_sequence={releasedSequence} " +
                    $"fresh={freshSample} neutral_move={neutralMove} no_jump_held={noJumpHeld} " +
                    $"no_jump_edge={noJumpEdge} stationary={stationary} at_stance={atControlStance} " +
                    $"full_final_catch={fullFinalCatch} claw_idle={clawIdle} claw_failure_none={clawFailureNone} " +
                    $"planned_Right={plannedRight} exact_control={exactControl} direction={plannedControl} " +
                    $"selected={controlSelection.Surface?.GetPath()} material={controlSelection.Snapshot.Material} " +
                    $"anchor={controlSelection.Snapshot.WorldAnchor} los={controlSelection.Snapshot.HasLineOfSight} " +
                    $"walk_settle_camera_frames={walkFrames}/90,{settleFrames}/12,{cameraFrames}/30"));
                Check(freshSample && neutralMove && noJumpHeld && noJumpEdge && stationary &&
                    atControlStance && fullFinalCatch && clawIdle && clawFailureNone && plannedRight && exactControl,
                    "fresh neutral full FinalCatch stance admits exact courtyard control through production Right before K");
                Log("KEYBOARD_LINKAGE_STANCE");
            }
            phase = "neutral-camera-settle";
            while (cameraFrames < 30 && !Visible())
            { cameraFrames++; await Tick(); }
            Guard();
            Check(Visible() && control.WorldAnchor.IsFinite() &&
                player.GlobalPosition.DistanceTo(control.WorldAnchor) <= MechanicalClawSettings.Default.MaxRange &&
                input.CurrentFrame.MoveAxis == 0f && !input.CurrentFrame.JumpHeld &&
                !input.CurrentFrame.JumpPressed && Stationary() &&
                Mathf.Abs(player.GlobalPosition.X - controlStance) <= 3f,
                "original control cast is in range and inside logical visibleRect.Grow(-32) from supported neutral stance");
            Log("FINAL");
        }
        finally
        {
            DiagnosticSafely(() =>
            {
                if (physicsTraceAttached && GodotObject.IsInstanceValid(tree))
                {
                    tree.PhysicsFrame -= ObservePhysicsTrace;
                    physicsTraceAttached = false;
                }
            });
            DiagnosticSafely(() => GD.Print($"TASK10_GRIP9_PAIRED_SUMMARY " +
                $"source=finally phase={phase} guard_samples={guardTraceCount}/8 " +
                $"physics_samples={physicsTraceCount}/8 ordinary_cap=16 " +
                $"diagnostic_faults={diagnosticFaults} last_fault={lastDiagnosticFault} " +
                $"listener_attached={physicsTraceAttached}"));
            swapApproachGuard(previousGuard);
            // Only this stage's injected directional/jump keys; no Begin/End/reset operation.
            SendAction(InputActions.MoveLeft, false);
            SendAction(InputActions.MoveRight, false);
            SendAction(InputActions.Jump, false);
        }
    }

    private static async Task TraverseTask10ShortcutBothDirections(SceneTree tree,
        CharacterBody2D player, RouteMonitor monitor, PrologueSector ascent,
        PrologueSector basin, PrologueLevelController level, Action observe,
        Func<Action, Action> swapApproachGuard)
    {
        CanyonShortcutWinch winch = ascent.GetNode<CanyonShortcutWinch>(
            "Gameplay/Mechanisms/UpperBasinShortcutWinch");
        GrappleSurface2D control = ascent.GetNode<GrappleSurface2D>(
            "Gameplay/GrappleSurfaces/UpperBasinShortcutControl");
        await StageTask10Grip9ControlApproach(tree, level, player, monitor, ascent,
            control, observe, swapApproachGuard);
        using (var diagnostic = new Task10PostSplitControlDiagnostic(tree, player, monitor,
            control, winch))
        {
            try
            {
                await CastAt(tree, monitor, player, control, () => winch.IsOpen, 120);
                diagnostic.Boundary("CastAt-return");
                TestAssert.True(winch.IsOpen,
                    "Task10 opens the persistent upper-basin shortcut through grapple input");
            }
            catch (Exception error) { diagnostic.Failure(error); throw; }
        }

        StaticBody2D AscentStep(int y) => ascent.GetNode<StaticBody2D>(
            $"Gameplay/Collision/ShortcutStep{y}");
        StaticBody2D BasinStep(int y) => basin.GetNode<StaticBody2D>(
            $"Gameplay/Collision/ShortcutStep{y}");
        await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player,
            ascent.GetNode<StaticBody2D>("Gameplay/Collision/SplitUpperGallery"), false);
        for (int y = 1556; y <= 3476; y += 160)
            await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player, AscentStep(y), false);
        for (int y = 3636; y <= 4116; y += 160)
            await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player, BasinStep(y), false);
        using (var diagnostic = new Task10PostControlHandoffDiagnostic(tree, player, monitor,
            level, basin, exploration: true))
        {
            try
            {
                await ReturnTask10ShortcutBottom(tree, player, monitor, basin, level,
                    winch, observe, swapApproachGuard);
                diagnostic.Boundary("safe-two-way-bottom-return");
            }
            catch (Exception error) { diagnostic.Failure(error); throw; }
        }
        await ReachTask10ShortcutFirstAscent(tree, player, monitor, basin, level,
            observe, swapApproachGuard);
        async Task ReachReturnStep(StaticBody2D target, bool sideBoost)
        {
            if(!sideBoost)
            {
                await PrologueCanyonTraversalTests.Task4ReachSupport(tree,player,target,true);
                return;
            }
            ulong start=Engine.GetPhysicsFrames(), playerId=player.GetInstanceId();
            var claw=player.GetNode<MechanicalClawController>("MechanicalClaw");
            var health=player.GetNode<HealthComponent>("Health");
            var motor=player.GetNode<PlayerMotor>("Motor");
            ulong nextCast=claw.CurrentFrame.NextCastId;
            int hp=health.CurrentHealth, jumps=motor.AcceptedJumpCount, dashes=motor.AcceptedDashCount;
            int requests=monitor.RecoveryRequested, recoveries=monitor.RecoveryCompleted;
            Action previous=null;
            void Guard()
            {
                previous?.Invoke();
                TestAssert.True(Engine.GetPhysicsFrames()-start<=300UL &&
                    GodotObject.IsInstanceValid(player) && level.Player==player && monitor.Player==player &&
                    player.GetInstanceId()==playerId && health.CurrentHealth==hp && hp>0 &&
                    monitor.RecoveryRequested==requests && monitor.RecoveryCompleted==recoveries &&
                    motor.AcceptedDashCount==dashes && motor.AcceptedJumpCount>=jumps && motor.AcceptedJumpCount<=jumps+1 &&
                    claw.CurrentFrame.NextCastId>=nextCast && claw.CurrentFrame.NextCastId<=nextCast+1UL,
                    $"Task10 keyboard {target.Name} side/Boost preparation/rise/cast/landing/tail share original300 with same player/HP/noRecovery/one jump/cast; " +
                    $"physics={Engine.GetPhysicsFrames()-start}/300 valid={GodotObject.IsInstanceValid(player)} " +
                    $"identity={player.GetInstanceId()}/{playerId} level_same={level.Player==player} monitor_same={monitor.Player==player} " +
                    $"position={player.GlobalPosition} velocity={player.Velocity} floor={player.IsOnFloor()} " +
                    $"hp={hp}->{health.CurrentHealth} recovery={requests}/{recoveries}->{monitor.RecoveryRequested}/{monitor.RecoveryCompleted} " +
                    $"jump={jumps}->{motor.AcceptedJumpCount} dash={dashes}->{motor.AcceptedDashCount} next_cast={nextCast}->{claw.CurrentFrame.NextCastId} " +
                    $"claw={claw.CurrentFrame.State} landing={motor.LandingCount} fall={motor.LastFallHeight}/{motor.LastFallDamage}/{motor.LastFallDamageApplied}");
            }
            previous=swapApproachGuard(Guard);
            try
            {
                Guard();
                await PrologueCanyonTraversalTests.Task4ReachSupport(tree,player,target,true,
                    keyboardShortcutSideBoost:true);
                Guard();
                TestAssert.True(motor.AcceptedJumpCount==jumps+1 &&
                    claw.CurrentFrame.NextCastId==nextCast+1UL,
                    "keyboard shortcut side/Boost finishes exactly one ordinary jump and one original-platform cast; attached Space is not a second jump");
                GD.Print($"TASK10_SHORTCUT_SIDE_SHARED_BUDGET_OK target={target.Name} " +
                    $"physics={Engine.GetPhysicsFrames()-start}/300 hp={hp}->{health.CurrentHealth} " +
                    $"recovery={requests}/{recoveries} next_cast={nextCast}->{claw.CurrentFrame.NextCastId}");
            }
            finally { swapApproachGuard(previous); }
        }
        for (int y = 3796; y >= 3636; y -= 160)
            await ReachReturnStep(BasinStep(y),KeyboardRouteInputDriver.Current!=null && y is 3796 or 3636);
        for (int y = 3476; y >= 1556; y -= 160)
            await ReachReturnStep(AscentStep(y),KeyboardRouteInputDriver.Current!=null && y is 2996 or 2676 or 2036 or 1716);
        await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player,
            ascent.GetNode<StaticBody2D>("Gameplay/Collision/SplitUpperGallery"), false);
        GD.Print($"TASK10_SHORTCUT_BIDIRECTIONAL_INPUT_OK player={player.GlobalPosition} " +
            $"open={winch.IsOpen}");
    }

    private static async Task ReachTask10ShortcutFirstAscent(SceneTree tree,
        CharacterBody2D player, RouteMonitor monitor, PrologueSector basin,
        PrologueLevelController level, Action observe, Func<Action, Action> swapApproachGuard)
    {
        bool Live(Node node) => node != null && GodotObject.IsInstanceValid(node) &&
            node.IsInsideTree() && !node.IsQueuedForDeletion();
        TestAssert.True(GodotObject.IsInstanceValid(tree) && Live(player) && Live(basin) && Live(level),
            "Task10 shortcut first ascent requires native-valid live entry nodes");
        StaticBody2D step = basin.GetNode<StaticBody2D>("Gameplay/Collision/ShortcutStep4116");
        StaticBody2D landing = basin.GetNode<StaticBody2D>("Gameplay/Collision/ShortcutStep3956");
        StaticBody2D post = basin.GetNode<StaticBody2D>("Gameplay/Collision/ShortcutStep3956Grip");
        GrappleSurface2D grip = post.GetNode<GrappleSurface2D>("GrappleSurfaceProfile");
        CollisionShape2D stepShape = step.GetNode<CollisionShape2D>("Collision");
        CollisionShape2D landingShape = landing.GetNode<CollisionShape2D>("Collision");
        CollisionShape2D postShape = post.GetNode<CollisionShape2D>("Collision");
        CollisionShape2D controlShape = basin.GetNode<CollisionShape2D>(
            "Gameplay/GrappleSurfaces/SteamDiverterTrenchControl/TargetCollision/Collision");
        Area2D controlCollider = controlShape.GetParent<Area2D>();
        CanyonSteamDiverter pair = basin.GetNode<CanyonSteamDiverter>("Gameplay/Mechanisms/SteamDiverterTrench");
        CanyonSteamJet left = pair.GetNode<CanyonSteamJet>("LeftJet");
        CanyonSteamJet right = pair.GetNode<CanyonSteamJet>("RightJet");
        CollisionShape2D hurtShape = player.GetNode<CollisionShape2D>("Hurtbox/HurtboxCollider");
        HealthComponent health = player.GetNode<HealthComponent>("Health");
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        MechanicalClawController claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
        PlayerActionModeController modes = player.GetNode<PlayerActionModeController>("ActionModes");
        PrologueGameFlowController flow = level.GetNode<PrologueGameFlowController>("GameFlow");
        Node[] nodes = { player, basin, level, step, landing, post, grip, stepShape, landingShape,
            postShape, controlShape, controlCollider, pair, left, right, hurtShape, health, motor, input, claw, modes, flow };
        TestAssert.True(nodes.All(Live) && Live(left.Collision) && Live(right.Collision),
            "Task10 shortcut first ascent requires original live components and jet colliders");
        ulong playerId = player.GetInstanceId(), gripId = grip.GetInstanceId();
        ulong nextCast = claw.CurrentFrame.NextCastId, inputSequence = input.CurrentFrameSequence;
        int hp = health.CurrentHealth, requests = monitor.RecoveryRequested;
        int recoveries = monitor.RecoveryCompleted, jumps = motor.AcceptedJumpCount, dashes = motor.AcceptedDashCount;
        int jumpWaits = 0, lastJumps = jumps;
        float startX = player.GlobalPosition.X;
        bool launched = false, previousSupport = false, helperStarted = false;
        bool castStarted = false, attached = false, manualRelease = false, invalidCast = false;
        bool spaceReleased = false, arrivedSeen = false, manualCancelIssued = false;
        int postClearWaits = 0;
        ulong launchSequence = 0UL, spaceReleaseSequence = 0UL;
        KeyboardRouteInputDriver keyboard = KeyboardRouteInputDriver.Current;
        bool keyboardRoute = keyboard != null, keyboardDirectionWindow = false, keyboardAimSource = false;
        int keyboardEdges = keyboard?.ClawEdges ?? 0, keyboardSamples = 0;
        ulong lastKeyboardSequence = 0UL, castIssueSequence = 0UL, keyboardAimSequence = 0UL;
        ulong directionReleaseSequence = 0UL, castReleaseSequence = 0UL;
        ulong cancelIssueSequence = 0UL, cancelSampleSequence = 0UL, cancelReleaseSequence = 0UL;
        ulong postClearPhysics = 0UL;
        Vector2 keyboardDirection = new Vector2(1f, -1f).Normalized();
        MechanicalClawTargetSnapshot keyboardAimSnapshot = default;
        MechanicalClawTargetResolution lastClearResolution = MechanicalClawTargetResolution.None;
        bool keyboardRiseReady = false;
        int keyboardRisePostPhysicsSamples = 0;
        float keyboardControlClearance = float.NaN, keyboardLandingClearance = float.NaN;
        ulong keyboardFirstHit = 0UL;
        Vector2 keyboardFirstHitPoint = Vector2.Zero;
        string phase = "entry", callbackFailure = null;
        Action previousGuard = null;
        var resolver = new MechanicalClawTargetResolver();
        // Passive trace state is separate from all acceptance/validation flags.
        MechanicalClawFrame? diagnosticPreviousFrame = null;
        string diagnosticPreviousFacts = null;
        ulong diagnosticLastTarget = 0UL, diagnosticLastResidency = 0UL;
        int diagnosticEvents = 0, diagnosticRecords = 0, diagnosticReserved = 0;
        int diagnosticSuppressed = 0, diagnosticFaults = 0;
        bool diagnosticAttached = false, diagnosticTerminated = false, diagnosticDetached = false;

        bool Supported(StaticBody2D body, CollisionShape2D shape) =>
            TryTask10CapsuleCorridor(player, shape, out _, out _, out _, out _) && HasFloorContact(player, body);
        bool AxisAligned(CollisionShape2D shape) => shape.GlobalTransform.Origin.IsFinite() &&
            shape.GlobalTransform.X.IsFinite() && shape.GlobalTransform.Y.IsFinite() &&
            Mathf.Abs(shape.GlobalTransform.X.Y) < .001f && Mathf.Abs(shape.GlobalTransform.Y.X) < .001f &&
            shape.GlobalTransform.X.X != 0f && shape.GlobalTransform.Y.Y != 0f;
        Rect2 Bounds(CollisionShape2D shape, Vector2 half) => new Rect2(
            shape.ToGlobal(-half), shape.ToGlobal(half) - shape.ToGlobal(-half)).Abs();
        Rect2 HurtBounds() => Bounds(hurtShape, new Vector2(
            ((CapsuleShape2D)hurtShape.Shape).Radius, ((CapsuleShape2D)hurtShape.Shape).Height / 2f));
        Rect2 JetBounds(CanyonSteamJet jet) => Bounds(jet.Collision,
            ((RectangleShape2D)jet.Collision.Shape).Size / 2f);
        float ControlTop() => controlShape.GlobalPosition.Y -
            Mathf.Abs(controlShape.GlobalTransform.Y.Y) * ((CircleShape2D)controlShape.Shape).Radius;
        float SafeY() => Mathf.Min(4040f, ControlTop() - 8f);
        Vector2 OriginalAim() => new(post.GlobalPosition.X, post.GlobalPosition.Y -
            ((RectangleShape2D)postShape.Shape).Size.Y / 2f + 10f);
        bool RightDormant() => right.DisabledForRun && right.Collision.Disabled && !right.Monitoring &&
            !right.Frame.HazardActive && !right.Frame.Telegraphing;
        bool KeyboardSource() => input.CurrentFrame.KeyboardActions &&
            !input.CurrentFrame.PrimaryPressed && !input.CurrentFrame.PrimaryHeld &&
            !input.CurrentFrame.PrimaryReleased && !input.CurrentFrame.AttackModePressed &&
            !input.CurrentFrame.GrappleModePressed && !input.CurrentFrame.LegacyShieldHeld &&
            !input.CurrentFrame.AttackPressed && !input.CurrentFrame.InteractPressed &&
            !input.CurrentFrame.DashPressed && !input.CurrentFrame.ShieldHeld;
        bool DirectionsReleased() => !Input.IsPhysicalKeyPressed(Key.A) && !Input.IsPhysicalKeyPressed(Key.D) &&
            !Input.IsPhysicalKeyPressed(Key.W) && !Input.IsPhysicalKeyPressed(Key.S);
        bool NeutralDirection() => input.CurrentFrame.MoveAxis == 0f && input.CurrentFrame.Aim == Vector2.Zero;
        bool SampledNE() => input.CurrentFrame.MoveAxis == 1f &&
            input.CurrentFrame.Aim.Dot(keyboardDirection) > .999f &&
            input.KeyboardAimDirection.Dot(keyboardDirection) > .999f;
        bool KeyboardRaySafe(MechanicalClawTargetResolution resolution)
        {
            keyboardControlClearance = keyboardLandingClearance = float.NaN;
            keyboardFirstHit = 0UL; keyboardFirstHitPoint = Vector2.Zero;
            if (resolution.Surface != grip || !resolution.Snapshot.Exists ||
                resolution.Snapshot.RuntimeId != gripId || !resolution.Snapshot.HasLineOfSight ||
                !resolution.Snapshot.WorldAnchor.IsFinite() || !resolution.Snapshot.SurfaceNormal.IsFinite()) return false;
            Vector2 origin = player.GlobalPosition, anchor = resolution.Snapshot.WorldAnchor;
            Vector2 segment = anchor - origin;
            if (!segment.IsFinite() || segment.LengthSquared() <= .0001f || segment.Length() > 620f) return false;
            float radius = ((CircleShape2D)controlShape.Shape).Radius *
                Mathf.Max(Mathf.Abs(controlShape.GlobalTransform.X.X), Mathf.Abs(controlShape.GlobalTransform.Y.Y));
            float fraction = Mathf.Clamp((controlShape.GlobalPosition - origin).Dot(segment) /
                segment.LengthSquared(), 0f, 1f);
            keyboardControlClearance = controlShape.GlobalPosition.DistanceTo(origin + segment * fraction) - radius;
            Rect2 landingBounds = Bounds(landingShape, ((RectangleShape2D)landingShape.Shape).Size / 2f);
            if (origin.X >= landingBounds.Position.X || anchor.X <= landingBounds.Position.X || segment.Y >= 0f) return false;
            float edgeY = origin.Y + segment.Y * (landingBounds.Position.X - origin.X) / segment.X;
            keyboardLandingClearance = landingBounds.Position.Y - edgeY;
            if (keyboardControlClearance < 8f || keyboardLandingClearance < 8f) return false;

            // The old center-Y line only kept the pointer ray above a ThreadTarget
            // circle. Verify the selected keyboard segment itself, without moving
            // or disabling that circle, its landing, or any real World collision.
            var excluded = new Godot.Collections.Array<Rid>();
            void AddCasterRids(Node node)
            {
                if (node is CollisionObject2D body) excluded.Add(body.GetRid());
                foreach (Node child in node.GetChildren()) AddCasterRids(child);
            }
            AddCasterRids(player);
            using PhysicsRayQueryParameters2D query = PhysicsRayQueryParameters2D.Create(
                origin, anchor + segment.Normalized() * .25f);
            query.CollideWithAreas = true; query.CollideWithBodies = true; query.HitFromInside = false;
            query.CollisionMask = CombatCollisionLayers.World | CombatCollisionLayers.Enemy |
                CombatCollisionLayers.ThreadTarget;
            query.Exclude = excluded;
            Godot.Collections.Dictionary hit = player.GetWorld2D().DirectSpaceState.IntersectRay(query);
            if (!hit.ContainsKey("collider") || !hit.ContainsKey("position") || !hit.ContainsKey("normal") ||
                hit["collider"].AsGodotObject() is not Node collider || !Live(collider)) return false;
            keyboardFirstHit = collider.GetInstanceId(); keyboardFirstHitPoint = hit["position"].AsVector2();
            return collider == post && keyboardFirstHitPoint.IsFinite() &&
                keyboardFirstHitPoint.DistanceTo(anchor) <= .5f &&
                hit["normal"].AsVector2().Dot(resolution.Snapshot.SurfaceNormal) > .99f;
        }
        void ObserveKeyboardSample()
        {
            if (!keyboardRoute || !input.CurrentFrame.ClawPressed ||
                input.CurrentFrameSequence == lastKeyboardSequence) return;
            lastKeyboardSequence = input.CurrentFrameSequence;
            Check(KeyboardSource() && Input.IsPhysicalKeyPressed(Key.K) &&
                input.CurrentFrameSequence > (manualCancelIssued ? cancelIssueSequence : castIssueSequence) &&
                (manualCancelIssued ? cancelIssueSequence > 0UL && keyboardSamples == 1 :
                    castIssueSequence > 0UL && keyboardSamples == 0),
                "samples only the two owned fresh physical K edges, one cast and one same-cast cancel");
            keyboardSamples++;
            if (manualCancelIssued) cancelSampleSequence = input.CurrentFrameSequence;
        }
        void Check(bool passed, string condition) => TestAssert.True(passed,
            $"Task10 shortcut first ascent {condition}; phase={phase} physics={Engine.GetPhysicsFrames()}");
        void Safety()
        {
            Check(GodotObject.IsInstanceValid(tree) && nodes.All(Live) &&
                Live(left.Collision) && Live(right.Collision), "keeps native-valid original nodes");
            Check(hurtShape.Shape is CapsuleShape2D capsule && GodotObject.IsInstanceValid(capsule) &&
                float.IsFinite(capsule.Radius) && capsule.Radius > 0f && float.IsFinite(capsule.Height) &&
                controlShape.Shape is CircleShape2D circle && GodotObject.IsInstanceValid(circle) &&
                float.IsFinite(circle.Radius) && circle.Radius > 0f &&
                new[] { stepShape, landingShape, postShape, left.Collision, right.Collision }.All(shape =>
                    shape.Shape is RectangleShape2D rectangle && GodotObject.IsInstanceValid(rectangle) &&
                    rectangle.Size.IsFinite() && rectangle.Size.X > 0f && rectangle.Size.Y > 0f) &&
                new[] { stepShape, landingShape, postShape, controlShape, hurtShape, left.Collision,
                    right.Collision }.All(AxisAligned), "uses real finite capsule, circle, post, support and jet geometry");
            Check(Live(monitor.Player) && Live(level.Player) && player.GetInstanceId() == playerId &&
                monitor.Player.GetInstanceId() == playerId && level.Player.GetInstanceId() == playerId &&
                grip.GetInstanceId() == gripId && hp == 1 && health.CurrentHealth == hp &&
                monitor.RecoveryRequested == requests && monitor.RecoveryCompleted == recoveries &&
                flow.State == PrologueGameFlowState.Playing && !tree.Paused &&
                player.GlobalPosition.IsFinite() && player.Velocity.IsFinite() &&
                motor.AcceptedDashCount == dashes, "preserves same Playing HP1 player, recovery totals and no dash");
            Check(pair.HasActivated && !pair.IsHandingOff && pair.SelectedSide == CanyonSteamDiverterSide.Left &&
                RightDormant(), "keeps the restored pair role and actual Right Dormant");
            Check(!(left.Frame.HazardActive && HurtBounds().Intersects(JetBounds(left))) &&
                !(right.Frame.HazardActive && HurtBounds().Intersects(JetBounds(right))), "never overlaps an actual active jet");
            Check(!invalidCast && callbackFailure == null && !claw.CurrentFrame.BoostConsumed &&
                motor.AcceptedJumpCount >= jumps && motor.AcceptedJumpCount <= jumps + 1 &&
                claw.CurrentFrame.NextCastId >= nextCast &&
                claw.CurrentFrame.NextCastId <= nextCast + (helperStarted ? 1UL : 0UL),
                "admits only one ordinary jump and the one unchanged-helper cast without boost");
            if (keyboardRoute)
                Check(controlCollider.CollisionLayer == CombatCollisionLayers.ThreadTarget &&
                    (controlCollider.CollisionLayer & CombatCollisionLayers.World) == 0u &&
                    (player.CollisionMask & CombatCollisionLayers.World) != 0u && KeyboardSource() &&
                    keyboardSamples <= (manualCancelIssued ? 2 : castIssueSequence > 0UL ? 1 : 0) &&
                    keyboard.ClawEdges == keyboardEdges + (manualCancelIssued ? 2 : castIssueSequence > 0UL ? 1 : 0),
                    "keeps real keyboard source, no legacy events and exactly the issued K edges");
        }
        void ClearRay()
        {
            Vector2 aim = OriginalAim();
            MechanicalClawTargetResolution resolution = keyboardRoute
                ? resolver.ResolveKeyboard(player, keyboardDirection) : resolver.Resolve(player, aim);
            lastClearResolution = resolution;
            Check(aim.DistanceTo(new Vector2(4232f, 3826f)) < .01f &&
                Mathf.Abs(ControlTop() - 4048f) < .01f &&
                (keyboardRoute ? KeyboardRaySafe(resolution) : player.GlobalPosition.Y <= SafeY()) &&
                player.GetViewportRect().HasPoint(player.GetCanvasTransform() * aim) &&
                player.GlobalPosition.DistanceTo(aim) <= 620f && resolution.Surface == grip &&
                resolution.Snapshot.RuntimeId == gripId && resolution.Snapshot.Exists &&
                resolution.Snapshot.HasLineOfSight &&
                (!keyboardRoute || PlayerKeyboardAimModel.ResolveDirection(aim - player.GlobalPosition, 1)
                    .Dot(keyboardDirection) > .999f && resolution.Snapshot.Material == grip.Material) &&
                player.GlobalPosition.DistanceTo(resolution.Snapshot.WorldAnchor) <= 620f,
                "uses the exact original logical onscreen aim, <=620 range and clear original-grip resolver (real NE for keyboard)");
        }
        void Log(string boundary) => GD.Print($"TASK10_SHORTCUT_FIRST_ASCENT_{boundary} " +
            $"phase={phase} physics={Engine.GetPhysicsFrames()} jump_waits={jumpWaits}/16 post_clear_waits={postClearWaits}/300 " +
            $"input_seq={input.CurrentFrameSequence} entry_seq={inputSequence} move={input.CurrentFrame.MoveAxis} " +
            $"jump={input.CurrentFrame.JumpPressed}/{input.CurrentFrame.JumpHeld} primary={input.CurrentFrame.PrimaryPressed}/{input.CurrentFrame.PrimaryHeld} " +
            $"player_id={playerId}/{player.GetInstanceId()} player={player.GlobalPosition} velocity={player.Velocity} " +
            $"step_full={Supported(step, stepShape)} landing_full={Supported(landing, landingShape)} " +
            $"previous_full={previousSupport} grounded_launch={launched} jumps={jumps}/{motor.AcceptedJumpCount} " +
            $"dashes={dashes}/{motor.AcceptedDashCount} hp={hp}/{health.CurrentHealth} " +
            $"recovery={requests}/{recoveries}->{monitor.RecoveryRequested}/{monitor.RecoveryCompleted} " +
            $"aim={OriginalAim()} control_top={ControlTop()} safe_y={SafeY()} right_dormant={RightDormant()} " +
            $"claw={claw.CurrentFrame.State}/{claw.CurrentFrame.CastId}/{claw.CurrentFrame.NextCastId}/{claw.CurrentFrame.Failure} " +
            $"exact_target={grip.GetPath()}#{gripId} locked_target={claw.CurrentFrame.LockedTargetRuntimeId} " +
            $"attached={attached} space_released={spaceReleased} arrived_seen={arrivedSeen} manual_cancel_issued={manualCancelIssued} " +
            $"manual_release={manualRelease} invalid_cast={invalidCast} callback_failure={callbackFailure} " +
            $"source={(keyboardRoute ? "keyboard-NE-K" : "legacy-ELMB")} K={input.CurrentFrame.ClawPressed}/{Input.IsPhysicalKeyPressed(Key.K)} " +
            $"raw_K={Input.IsActionPressed(InputActions.Claw)}/{Input.IsActionJustPressed(InputActions.Claw)} " +
            $"rise_post_physics_samples={keyboardRisePostPhysicsSamples}/{jumpWaits} " +
            $"K_samples={keyboardSamples} K_edges={keyboardEdges}->{keyboard?.ClawEdges ?? 0} " +
            $"actual_aim={input.KeyboardAimDirection} direction_window={keyboardDirectionWindow} " +
            $"cast_issue_aim_release={castIssueSequence}/{keyboardAimSequence}/{castReleaseSequence} " +
            $"direction_release={directionReleaseSequence} cancel_issue_sample_release={cancelIssueSequence}/{cancelSampleSequence}/{cancelReleaseSequence} " +
            $"actual_aim_receipt={keyboardAimSource}/{keyboardAimSnapshot.RuntimeId}/{keyboardAimSnapshot.Material}/{keyboardAimSnapshot.WorldAnchor}/{keyboardAimSnapshot.HasLineOfSight} " +
            $"preflight={lastClearResolution.Surface?.GetPath()}#{lastClearResolution.Snapshot.RuntimeId}/" +
            $"{lastClearResolution.Snapshot.Material}/{lastClearResolution.Snapshot.WorldAnchor}/{lastClearResolution.Snapshot.HasLineOfSight} " +
            $"keyboard_ray_ready={keyboardRiseReady} control_layer={controlCollider.CollisionLayer} player_mask={player.CollisionMask} " +
            $"control_segment_clearance={keyboardControlClearance:R} landing_above_clearance={keyboardLandingClearance:R} " +
            $"native_first_hit={keyboardFirstHit}/{post.GetInstanceId()} point={keyboardFirstHitPoint}");
        void Guard()
        {
            previousGuard?.Invoke();
            Safety();
            ObserveKeyboardSample();
            if (keyboardRoute && keyboardDirectionWindow && directionReleaseSequence > 0UL &&
                input.CurrentFrameSequence > directionReleaseSequence)
            {
                Check(NeutralDirection() && DirectionsReleased(),
                    "samples fresh neutral direction after the one bounded real NE admission window");
                keyboardDirectionWindow = false;
            }
            bool permittedDirection = NeutralDirection() || keyboardRoute && keyboardDirectionWindow && SampledNE() &&
                (directionReleaseSequence == 0UL || input.CurrentFrameSequence <= directionReleaseSequence);
            if (motor.AcceptedJumpCount != lastJumps)
            {
                Check(!launched && motor.AcceptedJumpCount == jumps + 1 && previousSupport &&
                    input.CurrentFrameSequence > inputSequence && input.CurrentFrame.JumpPressed &&
                    input.CurrentFrame.JumpHeld && input.CurrentFrame.MoveAxis == 0f && input.CurrentFrame.Aim == Vector2.Zero,
                    "samples one fresh accepted neutral grounded Space edge from previous full Step4116 support");
                launched = true; launchSequence = input.CurrentFrameSequence; Log("LAUNCH");
            }
            lastJumps = motor.AcceptedJumpCount;
            previousSupport = Supported(step, stepShape);
            if (!castStarted)
            {
                Check(Mathf.Abs(player.GlobalPosition.X - startX) <= 2f &&
                    TryTask10CapsuleCorridor(player, stepShape, out _, out _, out _, out _) &&
                    permittedDirection &&
                    claw.CurrentFrame.State == MechanicalClawState.Idle && claw.CurrentTarget == null &&
                    claw.ResidencyTarget == null, "keeps the original safe footprint and target-free Idle until cast admission");
                if (helperStarted) ClearRay(); // Includes admission sampling, stops once the real cast begins.
                else if (launched) Check(input.CurrentFrame.JumpHeld, "holds Space until actual rising clear-ray height");
            }
            if (helperStarted)
            {
                Check(motor.AcceptedJumpCount == jumps + 1 && permittedDirection &&
                    (input.CurrentFrameSequence <= launchSequence || !input.CurrentFrame.JumpPressed),
                    "preserves one launch edge and neutral input outside the bounded real NE admission window");
                if (!spaceReleased) Check(input.CurrentFrame.JumpHeld, "continuously holds the original Space through first exact attachment");
                else if (input.CurrentFrameSequence > spaceReleaseSequence)
                    Check(!input.CurrentFrame.JumpHeld, "samples the single driver Space release without a re-press");
            }
        }
        bool MatchingAttachment() => Live(claw.CurrentTarget) && claw.CurrentTarget.GetInstanceId() == gripId &&
            claw.CurrentFrame.CastId == nextCast && claw.CurrentFrame.LockedTargetRuntimeId == gripId &&
            claw.CurrentFrame.State is MechanicalClawState.Latched or MechanicalClawState.Reel or MechanicalClawState.Swing;
        bool SettledLanding() => Supported(landing, landingShape) &&
            claw.CurrentFrame.State == MechanicalClawState.Idle && claw.CurrentFrame.CastId == 0UL &&
            claw.CurrentFrame.Failure == MechanicalClawFailure.None && claw.CurrentTarget == null && claw.ResidencyTarget == null &&
            input.CurrentFrame.MoveAxis == 0f && input.CurrentFrame.Aim == Vector2.Zero &&
            !input.CurrentFrame.JumpPressed && !input.CurrentFrame.JumpHeld &&
            !input.CurrentFrame.PrimaryPressed && !input.CurrentFrame.PrimaryHeld &&
            (!keyboardRoute || KeyboardSource() && DirectionsReleased() && !keyboardDirectionWindow &&
                !input.CurrentFrame.ClawPressed && !Input.IsPhysicalKeyPressed(Key.K) &&
                cancelReleaseSequence > 0UL && input.CurrentFrameSequence > cancelReleaseSequence) &&
            Mathf.Abs(player.Velocity.X) <= 2f && Mathf.Abs(player.Velocity.Y) <= 2f;
        async Task PostClearTick()
        {
            Check(postClearWaits < 300, "bounds all post-clear mode/cast/pull/retract/landing/settle waits to one total300 budget");
            if (keyboardRoute) Check(Engine.GetPhysicsFrames() - postClearPhysics < 300UL,
                "bounds every keyboard post-clear wait to the original actual300 physics frames");
            Safety();
            await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
            postClearWaits++;
            observe(); // Same combined observer exactly once; scoped Guard composes the prior guard.
            if (keyboardRoute) Check(Engine.GetPhysicsFrames() - postClearPhysics <= 300UL,
                "includes keyboard sampling, releases, pull, cancel, landing and tail in actual300 physics frames");
        }
        string DiagnosticIdentity(Node node) => node == null ? "null" :
            !GodotObject.IsInstanceValid(node) ? "native-invalid" :
            $"{(node.IsInsideTree() ? node.GetPath().ToString() : node.Name.ToString())}#{node.GetInstanceId()}" +
            $"/tree={node.IsInsideTree()}/queued={node.IsQueuedForDeletion()}";
        void DiagnosticGap(Exception error)
        {
            diagnosticFaults++;
            if (diagnosticFaults > 4) return;
            try { GD.Print($"TASK10_SHORTCUT_FIRST_ASCENT_TRACE_GAP faults={diagnosticFaults} " +
                $"event={diagnosticEvents} type={error.GetType().Name} message={error.Message.Replace('\r', ' ').Replace('\n', ' ')}"); }
            catch { }
        }
        string DiagnosticContacts(MechanicalClawFrame frame)
        {
            if (!Live(player)) return "contacts=player-unavailable";
            int count = player.GetSlideCollisionCount();
            var contacts = new List<string>();
            for (int index = 0; index < Math.Min(count, 8); index++)
            {
                KinematicCollision2D contact = player.GetSlideCollision(index);
                if (!GodotObject.IsInstanceValid(contact)) { contacts.Add("native-invalid-contact"); continue; }
                Node collider = contact.GetCollider() as Node;
                bool belongs = Live(collider) && Live(grip) &&
                    MechanicalClawTargetResolver.ColliderBelongsToSurface(collider, grip);
                contacts.Add($"collider={DiagnosticIdentity(collider)},normal={contact.GetNormal()}," +
                    $"travel={contact.GetTravel()},belongs_expected_grip={belongs}," +
                    $"normal_dot_saved={contact.GetNormal().Normalized().Dot(frame.SurfaceNormal.Normalized())}");
            }
            return $"slide_count={count} contacts=[{string.Join(';', contacts)}] contacts_omitted={Math.Max(0, count - 8)}";
        }
        string DiagnosticFacts(MechanicalClawFrame frame, GrappleSurface2D target)
        {
            GrappleSurface2D current = Live(claw) ? claw.CurrentTarget : null;
            GrappleSurface2D resident = Live(claw) ? claw.ResidencyTarget : null;
            string facts = $"event_physics={Engine.GetPhysicsFrames()} " +
                $"input_seq={(Live(input) ? input.CurrentFrameSequence.ToString() : "unavailable")} " +
                $"player={(Live(player) ? player.GlobalPosition.ToString() : "unavailable")} " +
                $"velocity={(Live(player) ? player.Velocity.ToString() : "unavailable")} " +
                $"same_player={(Live(player) && Live(monitor.Player) && Live(level) && Live(level.Player) &&
                    player.GetInstanceId() == playerId && monitor.Player.GetInstanceId() == playerId && level.Player.GetInstanceId() == playerId)} " +
                $"hp={(Live(health) ? health.CurrentHealth.ToString() : "unavailable")} " +
                $"recovery={monitor.RecoveryRequested}/{monitor.RecoveryCompleted} " +
                $"step_full={(Live(player) && Live(step) && Live(stepShape) ? Supported(step, stepShape).ToString() : "unavailable")} " +
                $"landing_full={(Live(player) && Live(landing) && Live(landingShape) ? Supported(landing, landingShape).ToString() : "unavailable")} " +
                $"dock_distance={(Live(player) ? player.GlobalPosition.DistanceTo(frame.DockPoint).ToString("R") : "unavailable")} " +
                $"callback_target={DiagnosticIdentity(target)} current_target={DiagnosticIdentity(current)} " +
                $"residency_target={DiagnosticIdentity(resident)} previous_valid_target={diagnosticLastTarget} " +
                $"previous_valid_residency={diagnosticLastResidency} expected_grip={DiagnosticIdentity(grip)} " +
                $"expected_available={(Live(grip) ? grip.IsAvailable.ToString() : "unavailable")} " + DiagnosticContacts(frame);
            if (Live(input))
                facts += $" sampled_primary={input.CurrentFrame.PrimaryPressed}/{input.CurrentFrame.PrimaryHeld}/{input.CurrentFrame.PrimaryReleased}" +
                    $" sampled_jump={input.CurrentFrame.JumpPressed}/{input.CurrentFrame.JumpHeld} sampled_dash={input.CurrentFrame.DashPressed}" +
                    $" sampled_shield={input.CurrentFrame.ShieldHeld} sampled_attack_mode={input.CurrentFrame.AttackModePressed}";
            if (Live(target)) diagnosticLastTarget = target.GetInstanceId();
            if (Live(resident)) diagnosticLastResidency = resident.GetInstanceId();
            return facts;
        }
        string DiagnosticFrame(MechanicalClawFrame frame) =>
            $"state={frame.State} cast={frame.CastId}/{frame.NextCastId} failure={frame.Failure} release={frame.ReleaseKind} " +
            $"arrived={frame.Arrived} boost={frame.BoostConsumed} locked_target={frame.LockedTargetRuntimeId} " +
            $"published_pose={frame.CasterWorldPosition} published_velocity={frame.CasterVelocity} " +
            $"anchor={frame.AnchorPoint} dock={frame.DockPoint} normal={frame.SurfaceNormal} " +
            $"correction={frame.VelocityCorrection} effective_visibility={frame.EffectiveVisibility}";
        void DiagnosticRecord(string kind, MechanicalClawFrame frame, MechanicalClawFrame? previous, string facts)
        {
            string query = "OBSERVER_QUERY=unavailable";
            try
            {
                if (Live(player) && Live(grip) && frame.AnchorPoint.IsFinite() && frame.SurfaceNormal.IsFinite())
                {
                    MechanicalClawTargetSnapshot snapshot = resolver.SnapshotLocked(player, grip, frame.AnchorPoint, frame.SurfaceNormal);
                    query = $"OBSERVER_QUERY_at_physics={Engine.GetPhysicsFrames()} origin={player.GlobalPosition} exists={snapshot.Exists} " +
                        $"runtime_id={snapshot.RuntimeId} LOS={snapshot.HasLineOfSight}";
                }
            }
            catch (Exception error) { DiagnosticGap(error); }
            GD.Print($"TASK10_SHORTCUT_FIRST_ASCENT_TRACE kind={kind} event={diagnosticEvents} " +
                $"callback_phase=published-before-ApplyMotor contacts_phase=prior-MoveAndSlide-not-new-motion-collision " +
                $"previous=[{(previous.HasValue ? DiagnosticFrame(previous.Value) : "none")}] " +
                $"published=[{DiagnosticFrame(frame)}] facts=[{facts}] {query} " +
                $"query_note=observer-query-not-controller-captured-snapshot;expected-target-clearing-is-not-target-loss");
        }
        void DiagnosticFirstHit(MechanicalClawFrame frame)
        {
            try
            {
                if (!Live(player) || !player.GlobalPosition.IsFinite() || !frame.AnchorPoint.IsFinite())
                {
                    GD.Print($"TASK10_SHORTCUT_FIRST_ASCENT_OBSERVER_FIRST_HIT physics={Engine.GetPhysicsFrames()} " +
                        $"input_seq={(Live(input) ? input.CurrentFrameSequence.ToString() : "unavailable")} end={frame.AnchorPoint} " +
                        "hitFromInside=False gap=native-player-or-finite-ray-unavailable");
                    return;
                }
                Vector2 origin = player.GlobalPosition;
                // Exact existing controller LOS query: Node2D, origin, anchor, hitFromInside=false.
                System.Reflection.MethodInfo trace = typeof(MechanicalClawTargetResolver).GetMethod(
                    "TraceLineOfSight", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic,
                    null, new[] { typeof(Node2D), typeof(Vector2), typeof(Vector2), typeof(bool) }, null);
                if (trace == null || trace.ReturnType != typeof(Godot.Collections.Dictionary))
                    throw new InvalidOperationException("Existing TraceLineOfSight signature/return type unavailable");
                var hit = (Godot.Collections.Dictionary)trace.Invoke(null, new object[] { player, origin, frame.AnchorPoint, false });
                GodotObject collider = hit.ContainsKey("collider") ? hit["collider"].AsGodotObject() : null;
                bool native = collider != null && GodotObject.IsInstanceValid(collider);
                string identity = collider is Node node ? DiagnosticIdentity(node) : native ? $"non-node#{collider.GetInstanceId()}" : "null";
                string colliderGap = hit.Count == 0 ? "no-hit" : !hit.ContainsKey("collider") ? "missing-collider-field" :
                    collider == null ? "null-collider" : !native ? "native-invalid-collider" : "none";
                GD.Print($"TASK10_SHORTCUT_FIRST_ASCENT_OBSERVER_FIRST_HIT physics={Engine.GetPhysicsFrames()} " +
                    $"input_seq={(Live(input) ? input.CurrentFrameSequence.ToString() : "unavailable")} origin={origin} end={frame.AnchorPoint} " +
                    $"hitFromInside=False hit={hit.Count > 0} collider_native_valid={native} collider={identity} " +
                    $"collider_type={(native ? collider.GetClass().ToString() + "/" + collider.GetType().Name : "unavailable")} " +
                    $"position={(hit.ContainsKey("position") ? hit["position"].AsVector2().ToString() : "unavailable")} " +
                    $"normal={(hit.ContainsKey("normal") ? hit["normal"].AsVector2().ToString() : "unavailable")} " +
                    $"shape={(hit.ContainsKey("shape") ? hit["shape"].AsInt32().ToString() : "unavailable")} " +
                    $"rid={(hit.ContainsKey("rid") ? hit["rid"].AsRid().ToString() : "unavailable")} collider_gap={colliderGap} " +
                    "query_note=observer-query-now-not-predecessor-or-controller-captured-snapshot-or-branch");
            }
            catch (Exception error) { DiagnosticGap(error); }
        }
        void DiagnosticCast(MechanicalClawFrame frame, GrappleSurface2D target)
        {
            diagnosticEvents++;
            string facts = "native-facts-unavailable";
            try
            {
                MechanicalClawFrame? previous = diagnosticPreviousFrame;
                bool attachment = frame.State is MechanicalClawState.Latched or MechanicalClawState.Reel or MechanicalClawState.Swing;
                bool firstAttachment = attachment && !diagnosticAttached;
                bool terminal = !diagnosticTerminated && (frame.State is MechanicalClawState.Released or MechanicalClawState.Failed ||
                    frame.State == MechanicalClawState.Retract && (!previous.HasValue || previous.Value.State != MechanicalClawState.Released) ||
                    diagnosticAttached && frame.State == MechanicalClawState.Idle);
                bool transition = !previous.HasValue || frame.State != previous.Value.State || frame.CastId != previous.Value.CastId ||
                    frame.NextCastId != previous.Value.NextCastId || frame.LockedTargetRuntimeId != previous.Value.LockedTargetRuntimeId ||
                    frame.Arrived != previous.Value.Arrived || firstAttachment;
                bool ordinary = transition && !terminal && diagnosticRecords < 16;
                if (transition && !terminal && !ordinary) diagnosticSuppressed++;
                // Cache cheap native facts until first termination; physics-space queries occur only on selected records.
                if (!diagnosticTerminated || ordinary || terminal)
                {
                    try { facts = DiagnosticFacts(frame, target); }
                    catch (Exception error) { DiagnosticGap(error); }
                }
                if (terminal)
                {
                    diagnosticTerminated = true;
                    if (previous.HasValue)
                    {
                        diagnosticReserved++;
                        try { DiagnosticRecord("IMMEDIATE_PREDECESSOR", previous.Value, null, diagnosticPreviousFacts); }
                        catch (Exception error) { DiagnosticGap(error); }
                    }
                    diagnosticReserved++;
                    try { DiagnosticRecord("FIRST_TERMINATION", frame, previous, facts); }
                    catch (Exception error) { DiagnosticGap(error); }
                    DiagnosticFirstHit(frame);
                }
                else if (ordinary)
                {
                    diagnosticRecords++;
                    try { DiagnosticRecord(firstAttachment ? "FIRST_ATTACHMENT" : "TRANSITION", frame, previous, facts); }
                    catch (Exception error) { DiagnosticGap(error); }
                }
                diagnosticAttached |= attachment;
            }
            catch (Exception error) { DiagnosticGap(error); }
            finally { diagnosticPreviousFrame = frame; diagnosticPreviousFacts = facts; }
        }
        void DiagnosticSummary()
        {
            try { GD.Print($"TASK10_SHORTCUT_FIRST_ASCENT_TRACE_SUMMARY events={diagnosticEvents} " +
                $"ordinary_records={diagnosticRecords}/16 reserved_records={diagnosticReserved}/2 " +
                $"suppressed={diagnosticSuppressed} faults={diagnosticFaults} terminal_seen={diagnosticTerminated} " +
                $"listener_detached={diagnosticDetached} claw_native_valid={GodotObject.IsInstanceValid(claw)} " +
                $"last_valid_target={diagnosticLastTarget} last_valid_residency={diagnosticLastResidency}"); }
            catch (Exception error) { DiagnosticGap(error); }
        }
        void ObserveCast(MechanicalClawFrame frame, GrappleSurface2D target)
        {
            DiagnosticCast(frame, target); // Passive, independently protected from acceptance validation below.
            try
            {
                if (!nodes.All(Live)) { callbackFailure = "native node invalid during claw publication"; return; }
                if (keyboardRoute && frame.State != MechanicalClawState.Aim) ObserveKeyboardSample();
                if (frame.State == MechanicalClawState.Aim)
                {
                    if (!helperStarted) invalidCast = true;
                    castStarted = true;
                    if (keyboardRoute)
                    {
                        try
                        {
                            ObserveKeyboardSample();
                            MechanicalClawTargetResolution actual = claw.KeyboardPreview;
                            MechanicalClawTargetResolution fresh = resolver.ResolveKeyboard(player, input.KeyboardAimDirection);
                            keyboardAimSequence = input.CurrentFrameSequence;
                            keyboardAimSnapshot = actual.Snapshot;
                            keyboardAimSource = helperStarted && !manualCancelIssued &&
                                keyboardAimSequence > castIssueSequence && castIssueSequence > 0UL &&
                                keyboardSamples == 1 && KeyboardSource() && SampledNE() &&
                                Input.IsPhysicalKeyPressed(Key.K) && Input.IsPhysicalKeyPressed(Key.D) &&
                                Input.IsPhysicalKeyPressed(Key.W) && !Input.IsPhysicalKeyPressed(Key.A) &&
                                !Input.IsPhysicalKeyPressed(Key.S) && input.CurrentFrame.ClawPressed &&
                                input.CurrentFrame.JumpHeld && !input.CurrentFrame.JumpPressed &&
                                frame.CastId == 0UL && frame.NextCastId == nextCast &&
                                Mathf.Abs(player.GlobalPosition.X - startX) <= 2f &&
                                TryTask10CapsuleCorridor(player, stepShape, out _, out _, out _, out _) &&
                                KeyboardRaySafe(fresh) &&
                                actual.Surface == grip && Live(target) && target.GetInstanceId() == gripId &&
                                actual.Snapshot.Exists && actual.Snapshot.RuntimeId == gripId &&
                                actual.Snapshot.Material == grip.Material && actual.Snapshot.HasLineOfSight &&
                                fresh.Surface == grip && fresh.Snapshot.Exists && fresh.Snapshot.RuntimeId == gripId &&
                                fresh.Snapshot.Material == grip.Material && fresh.Snapshot.HasLineOfSight &&
                                fresh.Snapshot.WorldAnchor.DistanceTo(actual.Snapshot.WorldAnchor) < .01f &&
                                actual.Snapshot.WorldAnchor.DistanceTo(frame.AnchorPoint) < .01f &&
                                player.GlobalPosition.DistanceTo(actual.Snapshot.WorldAnchor) <= 620f &&
                                player.GlobalPosition.DistanceTo(fresh.Snapshot.WorldAnchor) <= 620f &&
                                player.GetViewportRect().HasPoint(player.GetCanvasTransform() * OriginalAim());
                            if (!keyboardAimSource) invalidCast = true;
                            Log("KEYBOARD_ACTUAL_AIM");
                        }
                        finally
                        {
                            // Cache the accepted sample/selection BEFORE releasing directions.
                            // Motor still consumes this real NE sample; no player state is written.
                            directionReleaseSequence = input.CurrentFrameSequence;
                            SendAction(InputActions.MoveRight, false);
                            SendAction(InputActions.MoveUp, false);
                        }
                    }
                }
                if (frame.State == MechanicalClawState.Failed || frame.BoostConsumed ||
                    frame.CastId != 0UL && (frame.CastId != nextCast || !helperStarted ||
                        frame.LockedTargetRuntimeId != 0UL && frame.LockedTargetRuntimeId != gripId)) invalidCast = true;
                if (frame.State is MechanicalClawState.Latched or MechanicalClawState.Reel or MechanicalClawState.Swing)
                {
                    if (!Live(target) || target.GetInstanceId() != gripId || frame.CastId != nextCast ||
                        frame.LockedTargetRuntimeId != gripId) invalidCast = true;
                    else
                    {
                        if (!attached && (spaceReleased || !input.CurrentFrame.JumpHeld || input.CurrentFrame.JumpPressed ||
                            postClearWaits > 32 || keyboardRoute &&
                                (Engine.GetPhysicsFrames() - postClearPhysics > 32UL || !keyboardAimSource))) invalidCast = true;
                        attached = true;
                        arrivedSeen |= frame.Arrived;
                    }
                }
                if (frame.State == MechanicalClawState.Released)
                {
                    if (frame.ReleaseKind == MechanicalClawReleaseKind.Cancel && frame.Failure == MechanicalClawFailure.None &&
                        frame.CastId == nextCast && frame.LockedTargetRuntimeId == gripId && attached && arrivedSeen &&
                        manualCancelIssued && spaceReleased && !input.CurrentFrame.JumpPressed &&
                        !input.CurrentFrame.JumpHeld && (keyboardRoute ? KeyboardSource() && NeutralDirection() &&
                            DirectionsReleased() && input.CurrentFrame.ClawPressed && Input.IsPhysicalKeyPressed(Key.K) &&
                            cancelSampleSequence > cancelIssueSequence && keyboardSamples == 2 &&
                            input.CurrentFrameSequence > spaceReleaseSequence : input.CurrentFrame.PrimaryPressed))
                    {
                        manualRelease = true;
                        if (keyboardRoute)
                        {
                            Log("KEYBOARD_ACTUAL_CANCEL");
                            cancelReleaseSequence = input.CurrentFrameSequence;
                            SendAction(InputActions.Claw, false);
                        }
                    }
                    else invalidCast = true;
                }
            }
            catch (Exception error) { callbackFailure ??= error.GetType().Name + ":" + error.Message; }
        }
        previousGuard = swapApproachGuard(Guard);
        claw.ClawFrameChanged += ObserveCast;
        try
        {
            Safety();
            previousSupport = Supported(step, stepShape);
            Check(previousSupport && requests == 0 && recoveries == 0 &&
                Mathf.Abs(player.Velocity.X) <= 2f && Mathf.Abs(player.Velocity.Y) <= 2f &&
                input.CurrentFrame.MoveAxis == 0f && input.CurrentFrame.Aim == Vector2.Zero &&
                !input.CurrentFrame.JumpPressed && !input.CurrentFrame.JumpHeld &&
                !input.CurrentFrame.PrimaryPressed && !input.CurrentFrame.PrimaryHeld &&
                (!keyboardRoute || KeyboardSource() && DirectionsReleased() &&
                    !input.CurrentFrame.ClawPressed && !Input.IsPhysicalKeyPressed(Key.K)) &&
                claw.CurrentFrame.State == MechanicalClawState.Idle && claw.CurrentFrame.CastId == 0UL &&
                claw.CurrentFrame.Failure == MechanicalClawFailure.None && claw.CurrentTarget == null &&
                claw.ResidencyTarget == null, "enters on full stopped neutral Step4116 with released Space and target-free Idle");
            Guard(); Log("ENTRY"); phase = "vertical-jump";
            SendAction(InputActions.Jump, true);
            do
            {
                Safety();
                await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
                jumpWaits++;
                if (keyboardRoute)
                {
                    // PhysicsFrame precedes Input/Claw/Motor. A key edge parsed there
                    // is scheduled for the NEXT tick, although held D/W act immediately.
                    // Observe after this tick's Motor so the next fresh K sees this same
                    // real safe pose; the zero physics timer consumes no extra tick.
                    ulong risePhysics = Engine.GetPhysicsFrames();
                    Safety();
                    await tree.ToSignal(tree.CreateTimer(0d, true, true), SceneTreeTimer.SignalName.Timeout);
                    Check(Engine.GetPhysicsFrames() == risePhysics,
                        "observes the completed keyboard rise in the same budgeted physics tick, without a hidden wait");
                    keyboardRisePostPhysicsSamples++;
                }
                observe(); // Existing combined observer exactly once, including this scoped Guard.
                if (keyboardRoute && launched && player.Velocity.Y < 0f)
                {
                    lastClearResolution = resolver.ResolveKeyboard(player, keyboardDirection);
                    keyboardRiseReady = KeyboardRaySafe(lastClearResolution);
                    Log("KEYBOARD_RISE_PREFLIGHT"); // At most the original16 jump waits; never an accepted K receipt.
                }
            } while (jumpWaits < 16 && (!launched ||
                (keyboardRoute ? !keyboardRiseReady : player.GlobalPosition.Y > SafeY()) || player.Velocity.Y >= 0f));
            Check(launched && motor.AcceptedJumpCount == jumps + 1 &&
                (keyboardRoute ? keyboardRiseReady : player.GlobalPosition.Y <= SafeY()) && player.Velocity.Y < 0f,
                "reaches real rising clear-ray height within 16 new physics waits");
            ClearRay(); Log("CLEAR_RAY"); phase = "held-cast-admission"; helperStarted = true;
            postClearPhysics = Engine.GetPhysicsFrames();
            Log("HELD_ADMISSION");
            if (keyboardRoute)
            {
                Check(modes.CanBeginGrapple && KeyboardSource() && NeutralDirection() && DirectionsReleased() &&
                    input.CurrentFrame.JumpHeld && !input.CurrentFrame.ClawPressed &&
                    !Input.IsPhysicalKeyPressed(Key.K),
                    "admits original exact NE preflight from released K and held Space without a legacy mode edge");
                castIssueSequence = input.CurrentFrameSequence;
                keyboardDirectionWindow = true;
                SendAction(InputActions.MoveRight, true);
                SendAction(InputActions.MoveUp, true);
                SendAction(InputActions.Claw, true);
                Log("KEYBOARD_KEYS_ISSUED");
                try
                {
                    while (keyboardAimSequence == 0UL && postClearWaits < 8) await PostClearTick();
                }
                finally
                {
                    castReleaseSequence = input.CurrentFrameSequence;
                    SendAction(InputActions.Claw, false);
                    SendAction(InputActions.MoveRight, false);
                    SendAction(InputActions.MoveUp, false);
                    if (directionReleaseSequence == 0UL) directionReleaseSequence = input.CurrentFrameSequence;
                }
                Check(keyboardAimSequence > castIssueSequence && keyboardAimSource && keyboardSamples == 1 &&
                    keyboard.ClawEdges == keyboardEdges + 1 && castStarted,
                    "admits one fresh physical NE K and actual exact original-grip Aim within the shared32/300 budget");
                Log("KEYBOARD_CAST_RELEASE_ISSUED");
            }
            else
            {
                SendAction(InputActions.SelectGrappleMode, true);
                await PostClearTick();
                SendAction(InputActions.SelectGrappleMode, false);
                ClearRay();
                Check(modes.CanBeginGrapple && input.CurrentFrame.JumpHeld &&
                    !input.CurrentFrame.PrimaryPressed && !input.CurrentFrame.PrimaryHeld,
                    "admits the original exact clear-ray cast in real grapple mode without releasing Space");
                SendMouse(MouseButton.Left, true, player, OriginalAim());
                await PostClearTick();
                SendMouse(MouseButton.Left, false, player, OriginalAim());
            }
            phase = "held-to-attachment";
            while (!attached && postClearWaits < 32) await PostClearTick();
            Safety();
            Check(attached && MatchingAttachment() && postClearWaits <= 32 &&
                claw.CurrentFrame.NextCastId == nextCast + 1UL && input.CurrentFrame.JumpHeld && !input.CurrentFrame.JumpPressed &&
                (!keyboardRoute || keyboardAimSource && !keyboardDirectionWindow && NeutralDirection() &&
                    DirectionsReleased() && input.CurrentFrameSequence > castReleaseSequence &&
                    !input.CurrentFrame.ClawPressed && !Input.IsPhysicalKeyPressed(Key.K)),
                "observes the exact held-Space attachment within32 post-clear waits with no fresh Space edge");
            Log("HELD_ATTACHMENT");
            spaceReleaseSequence = input.CurrentFrameSequence;
            spaceReleased = true;
            SendAction(InputActions.Jump, false);
            phase = "space-release-and-pull"; Log("SPACE_RELEASE_ISSUED");
            while (postClearWaits < 300 && (input.CurrentFrameSequence <= spaceReleaseSequence ||
                input.CurrentFrame.JumpHeld)) await PostClearTick();
            Check(input.CurrentFrameSequence > spaceReleaseSequence && !input.CurrentFrame.JumpHeld,
                "samples the single release-only Space after real attachment");
            Log("SPACE_RELEASE_SAMPLED"); phase = "pull-to-arrival";
            while (postClearWaits < 300 && (!MatchingAttachment() || !claw.CurrentFrame.Arrived)) await PostClearTick();
            Check(MatchingAttachment() && claw.CurrentFrame.Arrived && arrivedSeen,
                "samples release-only Space and actual matching frame.Arrived, not positional arrival");
            Log("ARRIVED");
            Check(!input.CurrentFrame.PrimaryPressed && !input.CurrentFrame.PrimaryHeld &&
                (!keyboardRoute || KeyboardSource() && NeutralDirection() && DirectionsReleased() &&
                    !input.CurrentFrame.ClawPressed && !Input.IsPhysicalKeyPressed(Key.K) &&
                    input.CurrentFrameSequence > castReleaseSequence && keyboardSamples == 1),
                "has sampled released Primary before the one actual manual Cancel edge");
            Vector2 cancelAim = claw.CurrentFrame.AnchorPoint;
            manualCancelIssued = true;
            phase = "manual-cancel";
            if (keyboardRoute)
            {
                cancelIssueSequence = input.CurrentFrameSequence;
                SendAction(InputActions.Claw, true);
            }
            else
            {
                SendMouse(MouseButton.Left, true, player, cancelAim);
                await PostClearTick();
                SendMouse(MouseButton.Left, false, player, cancelAim);
            }
            while (!manualRelease && postClearWaits < 300) await PostClearTick();
            Check(manualRelease && (!keyboardRoute || keyboardSamples == 2 &&
                keyboard.ClawEdges == keyboardEdges + 2 && cancelSampleSequence > cancelIssueSequence &&
                cancelReleaseSequence >= cancelSampleSequence),
                "observes the matching actual Cancel/manual retract from the unique second fresh input edge");
            Log("MANUAL_CANCEL"); phase = "landing-and-idle";
            while (!SettledLanding() && postClearWaits < 300) await PostClearTick();
            Check(SettledLanding(), "reaches full named Step3956 support and natural target-free Idle within the shared300 waits");
            for (int settled = 0; settled < 3; settled++)
            {
                await PostClearTick();
                Check(SettledLanding(), "retains full Step3956, target-free Idle and neutral input for each of3 settle waits");
            }
            Safety();
            Check(attached && arrivedSeen && manualRelease && spaceReleased && SettledLanding() &&
                motor.AcceptedJumpCount == jumps + 1 && claw.CurrentFrame.NextCastId == nextCast + 1UL,
                "finishes exact-grip attachment/actual arrival/manual retract/full settled Step3956 with one ordinary jump");
            phase = "settled-landing"; Log("LANDING");
        }
        catch (Exception error)
        {
            try
            {
                GD.Print($"TASK10_SHORTCUT_FIRST_ASCENT_FAILURE phase={phase} first_exception={error}");
                if (nodes.All(Live) && Live(left.Collision) && Live(right.Collision)) Log("FAILURE_STATE");
            }
            catch (Exception diagnosticError)
            {
                try { GD.Print($"TASK10_SHORTCUT_FIRST_ASCENT_DIAGNOSTIC_FAILURE {diagnosticError}"); } catch { }
            }
            throw;
        }
        finally
        {
            // Cleanup diagnostics must not replace the first route exception; try each owned release.
            void Cleanup(Action release)
            {
                try { release(); }
                catch (Exception error)
                { try { GD.Print($"TASK10_SHORTCUT_FIRST_ASCENT_CLEANUP_FAILURE {error}"); } catch { } }
            }
            Cleanup(() => { if (GodotObject.IsInstanceValid(claw)) { claw.ClawFrameChanged -= ObserveCast; diagnosticDetached = true; } });
            Cleanup(() => swapApproachGuard(previousGuard));
            Cleanup(() => SendAction(InputActions.Jump, false));
            if (keyboardRoute)
            {
                Cleanup(() => SendAction(InputActions.Claw, false));
                Cleanup(() => SendAction(InputActions.MoveRight, false));
                Cleanup(() => SendAction(InputActions.MoveUp, false));
            }
            Cleanup(() => SendAction(InputActions.SelectGrappleMode, false));
            Cleanup(() => SendMouse(MouseButton.Left, false, Live(player) ? player : null, Vector2.Zero));
            DiagnosticSummary();
        }
    }

    private static async Task ReturnTask10ShortcutBottom(SceneTree tree,
        CharacterBody2D player, RouteMonitor monitor, PrologueSector basin,
        PrologueLevelController level, CanyonShortcutWinch winch, Action observe,
        Func<Action, Action> swapApproachGuard)
    {
        bool Live(Node node) => node != null && GodotObject.IsInstanceValid(node) &&
            node.IsInsideTree() && !node.IsQueuedForDeletion();
        TestAssert.True(GodotObject.IsInstanceValid(tree) && Live(player) && Live(level) && Live(basin) && Live(winch),
            "Task10 shortcut bottom requires native-valid live entry nodes");
        StaticBody2D step = basin.GetNode<StaticBody2D>("Gameplay/Collision/ShortcutStep4116");
        StaticBody2D walkway = basin.GetNode<StaticBody2D>("Gameplay/Collision/ShortcutBasinWalkway");
        CollisionShape2D stepShape = step.GetNode<CollisionShape2D>("Collision");
        CollisionShape2D walkwayShape = walkway.GetNode<CollisionShape2D>("Collision");
        CanyonSteamDiverter pair = basin.GetNode<CanyonSteamDiverter>("Gameplay/Mechanisms/SteamDiverterTrench");
        CanyonSteamJet left = pair.GetNode<CanyonSteamJet>("LeftJet");
        CanyonSteamJet right = pair.GetNode<CanyonSteamJet>("RightJet");
        ThreadTarget2D control = basin.GetNode<ThreadTarget2D>("Gameplay/GrappleSurfaces/SteamDiverterTrenchControl");
        LegacyThreadInteractionAdapter adapter = control.GetNode<LegacyThreadInteractionAdapter>("LegacyThreadInteractionAdapter");
        HealthComponent health = player.GetNode<HealthComponent>("Health");
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        PlayerEnergyController energy = player.GetNode<PlayerEnergyController>("Energy");
        PlayerActionModeController modes = player.GetNode<PlayerActionModeController>("ActionModes");
        MechanicalClawController claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
        CollisionShape2D hurtShape = player.GetNode<CollisionShape2D>("Hurtbox/HurtboxCollider");
        PrologueGameFlowController flow = level.GetNode<PrologueGameFlowController>("GameFlow");
        TestAssert.True(new Node[] { step, walkway, stepShape, walkwayShape, pair, left, right,
            control, adapter, health, motor, input, energy, modes, claw, hurtShape, flow }.All(Live),
            "Task10 shortcut bottom requires live original components");
        ulong playerId = player.GetInstanceId(), controlId = control.GetInstanceId();
        ulong adapterId = adapter.GetInstanceId(), pairId = pair.GetInstanceId();
        int hp = health.CurrentHealth, requests = monitor.RecoveryRequested;
        int recoveries = monitor.RecoveryCompleted, jumps = motor.AcceptedJumpCount;
        int dashes = motor.AcceptedDashCount, applications = adapter.ApplicationCount;
        ulong initialNextCast = claw.CurrentFrame.NextCastId;
        KeyboardRouteInputDriver keyboard = KeyboardRouteInputDriver.Current;
        bool keyboardRoute = keyboard != null;
        int initialKeyboardEdges = keyboard?.ClawEdges ?? 0, operationKeyboardEdges = 0;
        int keyboardSamples = 0, operationKeyboardSamples = 0;
        ulong lastKeyboardSequence = 0UL, sampledRight = 0UL, keyboardAimSequence = 0UL, keyboardReleaseSequence = 0UL;
        ulong keyboardAimTarget = 0UL;
        Vector2 keyboardAimDirection = Vector2.Zero;
        MechanicalClawTargetSnapshot keyboardAimSnapshot = default;
        bool keyboardAimSource = false;
        int completedLegs = 0, completedControls = 0, lastJumps = jumps;
        int phaseFrames = 0, primarySamples = 0, operationPrimarySamples = 0;
        ulong lastPrimarySequence = 0, operationCast = 0, sampledE = 0, operationPhysics = 0;
        bool flight = false, groundedLaunch = false, previousLaunchSupport = false;
        bool operation = false, exactLatch = false, invalidCast = false, pulling = false;
        int direction = 0;
        StaticBody2D requiredSupport = step, launchSupport = step;
        string phase = "entry";
        Vector2 operationStart = Vector2.Zero;
        float maxOperationDisplacement = 0f;
        Action previousGuard = null;

        bool Supported(StaticBody2D body) => Live(body) &&
            TryTask10CapsuleCorridor(player, body == step ? stepShape : walkwayShape,
                out _, out _, out _, out _) && HasFloorContact(player, body);
        Rect2 Bounds(CollisionShape2D shape, Vector2 half) => new Rect2(
            shape.ToGlobal(-half), shape.ToGlobal(half) - shape.ToGlobal(-half)).Abs();
        Rect2 HurtBounds() => Bounds(hurtShape, new Vector2(
            ((CapsuleShape2D)hurtShape.Shape).Radius, ((CapsuleShape2D)hurtShape.Shape).Height / 2f));
        Rect2 JetBounds(CanyonSteamJet jet) => Bounds(jet.Collision,
            ((RectangleShape2D)jet.Collision.Shape).Size / 2f);
        bool Dormant(CanyonSteamJet jet) => jet.DisabledForRun && jet.Collision.Disabled &&
            !jet.Monitoring && !jet.Frame.HazardActive && !jet.Frame.Telegraphing;
        bool Stationary() => player.Velocity.IsFinite() &&
            Mathf.Abs(player.Velocity.X) <= 2f && Mathf.Abs(player.Velocity.Y) <= 2f;
        bool KeyboardSource() => input.CurrentFrame.KeyboardActions &&
            !input.CurrentFrame.PrimaryPressed && !input.CurrentFrame.PrimaryHeld &&
            !input.CurrentFrame.PrimaryReleased && !input.CurrentFrame.AttackModePressed &&
            !input.CurrentFrame.GrappleModePressed && !input.CurrentFrame.LegacyShieldHeld &&
            !input.CurrentFrame.AttackPressed && !input.CurrentFrame.InteractPressed &&
            !input.CurrentFrame.DashPressed && !input.CurrentFrame.ShieldHeld;
        bool DirectionsReleased() => !Input.IsPhysicalKeyPressed(Key.A) && !Input.IsPhysicalKeyPressed(Key.D) &&
            !Input.IsPhysicalKeyPressed(Key.W) && !Input.IsPhysicalKeyPressed(Key.S);
        bool NeutralRight() => KeyboardSource() && DirectionsReleased() &&
            input.CurrentFrame.MoveAxis == 0f && input.CurrentFrame.Aim == Vector2.Zero &&
            input.KeyboardAimDirection.Dot(Vector2.Right) > .999f;
        bool Neutral() => input.CurrentFrame.MoveAxis == 0f &&
            input.CurrentFrame.Aim == Vector2.Zero && !input.CurrentFrame.JumpHeld &&
            !input.CurrentFrame.JumpPressed && !input.CurrentFrame.PrimaryHeld &&
            !input.CurrentFrame.PrimaryPressed && (!keyboardRoute || KeyboardSource() &&
                !input.CurrentFrame.ClawPressed && !Input.IsPhysicalKeyPressed(Key.K));
        string JetFacts(CanyonSteamJet jet) => $"{jet.Name}:disabled={jet.DisabledForRun}," +
            $"collider_disabled={jet.Collision.Disabled},monitoring={jet.Monitoring}," +
            $"hazard={jet.Frame.HazardActive},warning={jet.Frame.Telegraphing}";
        string Snapshot() => $"phase={phase} phase_frames={phaseFrames} physics={Engine.GetPhysicsFrames()} " +
            $"input_seq={input.CurrentFrameSequence} move={input.CurrentFrame.MoveAxis} " +
            $"jump={input.CurrentFrame.JumpPressed}/{input.CurrentFrame.JumpHeld} " +
            $"E={input.CurrentFrame.GrappleModePressed} primary={input.CurrentFrame.PrimaryPressed}/{input.CurrentFrame.PrimaryHeld} " +
            $"primary_samples={primarySamples} sampled_E={sampledE} player_id={playerId}/{player.GetInstanceId()} " +
            $"source={(keyboardRoute ? "keyboard-neutralRight-K" : "legacy-ELMB")} " +
            $"K={input.CurrentFrame.ClawPressed}/{Input.IsPhysicalKeyPressed(Key.K)} " +
            $"directions_released={DirectionsReleased()} actual_aim={input.KeyboardAimDirection} sampled_right={sampledRight} " +
            $"K_samples={keyboardSamples}/{operationKeyboardSamples} K_edges={initialKeyboardEdges}->{keyboard?.ClawEdges ?? 0} " +
            $"admitted={keyboardAimSequence}/{keyboardAimTarget}/{keyboardAimDirection}/{keyboardAimSource} " +
            $"player={player.GlobalPosition} velocity={player.Velocity} step_full={Supported(step)} walkway_full={Supported(walkway)} " +
            $"previous_launch_full={previousLaunchSupport} grounded_launch={groundedLaunch} " +
            $"hp={hp}/{health.CurrentHealth} recovery={requests}/{recoveries}->{monitor.RecoveryRequested}/{monitor.RecoveryCompleted} " +
            $"energy_heat={energy.EnergyRatio}/{energy.HeatRatio}/{energy.IsOverheated} jumps={jumps}/{motor.AcceptedJumpCount} " +
            $"dashes={dashes}/{motor.AcceptedDashCount} pair={pair.GetPath()}#{pairId} side={pair.SelectedSide} handoff={pair.IsHandingOff} " +
            $"control={control.GetPath()}#{controlId} adapter={adapter.GetPath()}#{adapterId} applications={applications}/{adapter.ApplicationCount} " +
            $"cast={claw.CurrentFrame.CastId}/{claw.CurrentFrame.NextCastId}/{claw.CurrentFrame.State}/{claw.CurrentFrame.Failure} " +
            $"operation_cast={operationCast} exact_latch={exactLatch} invalid_cast={invalidCast} pulling={pulling} displacement={maxOperationDisplacement:R} " +
            $"left=[{JetFacts(left)}] right=[{JetFacts(right)}] winch_open={winch.IsOpen} flow={flow.State}";
        void Check(bool passed, string condition) => TestAssert.True(passed,
            $"Task10 shortcut bottom {condition}; phase={phase} physics={Engine.GetPhysicsFrames()}");
        void Log(string boundary) => GD.Print($"TASK10_SHORTCUT_BOTTOM_{boundary} {Snapshot()}");
        void Safety()
        {
            Check(GodotObject.IsInstanceValid(tree) && new Node[] { player, level, winch, step,
                walkway, stepShape, walkwayShape, pair, left, right, control, adapter, health, motor,
                input, energy, modes, claw, hurtShape, flow }.All(Live), "keeps native-valid original nodes");
            Check(Live(left.Collision) && Live(right.Collision), "keeps live original jet colliders");
            Check(Live(monitor.Player) && Live(level.Player) &&
                monitor.Player.GetInstanceId() == playerId && level.Player.GetInstanceId() == playerId &&
                player.GetInstanceId() == playerId && control.GetInstanceId() == controlId &&
                adapter.GetInstanceId() == adapterId && pair.GetInstanceId() == pairId &&
                hp > 0 && health.CurrentHealth == hp && monitor.RecoveryRequested == requests &&
                monitor.RecoveryCompleted == recoveries && winch.IsOpen &&
                flow.State == PrologueGameFlowState.Playing && !tree.Paused &&
                player.GlobalPosition.IsFinite() && player.Velocity.IsFinite() &&
                motor.AcceptedDashCount == dashes, "preserves same Playing player, HP, recovery, winch and no dash");
            Check(!invalidCast && !pulling, "never targets another control or pulls/boosts");
            Check(!(left.Frame.HazardActive && HurtBounds().Intersects(JetBounds(left))) &&
                !(right.Frame.HazardActive && HurtBounds().Intersects(JetBounds(right))), "never overlaps an actual active jet");
            if (completedControls == 1 && !operation)
                Check(pair.SelectedSide == CanyonSteamDiverterSide.Right && Dormant(left), "keeps Left actually dormant throughout both legs");
            Check(pair.HasActivated && (pair.SelectedSide == CanyonSteamDiverterSide.Right ? Dormant(left) : Dormant(right)),
                "keeps the nonselected side actually dormant");
            if (pair.IsHandingOff) Check(Dormant(left) && Dormant(right), "handoff disarms both real jets");
            Check(motor.AcceptedJumpCount >= jumps + completedLegs &&
                motor.AcceptedJumpCount <= jumps + completedLegs + (flight ? 1 : 0), "admits only the two scoped ordinary jumps");
            Check(adapter.ApplicationCount >= applications + completedControls &&
                adapter.ApplicationCount <= applications + completedControls + (operation ? 1 : 0) &&
                claw.CurrentFrame.NextCastId >= initialNextCast + (ulong)completedControls &&
                claw.CurrentFrame.NextCastId <= initialNextCast + (ulong)completedControls + (operation ? 1UL : 0UL),
                "admits exactly one cast/application per control operation and none while walking/jumping");
            if (!flight) Check(Supported(requiredSupport), "retains full named support outside flight");
            if (operation)
            {
                Check(Engine.GetPhysicsFrames() - operationPhysics <= 120UL,
                    "bounds the whole control operation to 120 actual physics frames");
                maxOperationDisplacement = Mathf.Max(maxOperationDisplacement, player.GlobalPosition.DistanceTo(operationStart));
                Check(Supported(step) && Stationary() && input.CurrentFrame.MoveAxis == 0f &&
                    input.CurrentFrame.Aim == Vector2.Zero && !input.CurrentFrame.JumpHeld &&
                    !input.CurrentFrame.JumpPressed && maxOperationDisplacement <= 2f &&
                    (!keyboardRoute || NeutralRight()) &&
                    !HurtBounds().Intersects(JetBounds(left)) && !HurtBounds().Intersects(JetBounds(right)),
                    "control operation stays neutral within 2px and clear of both jet footprints");
            }
        }
        void Guard()
        {
            previousGuard?.Invoke();
            Safety();
            if (input.CurrentFrame.PrimaryPressed && lastPrimarySequence != input.CurrentFrameSequence)
            { lastPrimarySequence = input.CurrentFrameSequence; primarySamples++; if (operation) operationPrimarySamples++; }
            if (keyboardRoute && input.CurrentFrame.ClawPressed && lastKeyboardSequence != input.CurrentFrameSequence)
            { lastKeyboardSequence = input.CurrentFrameSequence; keyboardSamples++; if (operation) operationKeyboardSamples++; }
            if (motor.AcceptedJumpCount != lastJumps)
            {
                Check(flight && !groundedLaunch && motor.AcceptedJumpCount == jumps + completedLegs + 1 &&
                    previousLaunchSupport && input.CurrentFrame.JumpPressed && direction * input.CurrentFrame.MoveAxis > 0f,
                    "samples one accepted grounded launch from previous full support with current Space/direction");
                groundedLaunch = true;
                Log("LAUNCH");
            }
            lastJumps = motor.AcceptedJumpCount;
            previousLaunchSupport = Supported(launchSupport);
        }
        async Task Tick()
        {
            Safety();
            await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
            phaseFrames++;
            observe(); // Original combined observer exactly once; its scoped callback invokes Guard.
        }
        void ReleaseMovement()
        {
            SendAction(InputActions.MoveLeft, false); SendAction(InputActions.MoveRight, false);
            SendAction(InputActions.MoveUp, false); SendAction(InputActions.MoveDown, false);
            SendAction(InputActions.Jump, false);
        }
        void Steer(float target)
        {
            if (keyboardRoute && !flight)
            {
                Check(player.IsOnFloor() && Supported(requiredSupport),
                    "keyboard ground stance prediction starts from original full named support");
                // Only this Walk's original90 plus its original12 settle are available.
                var stop = FreeMotionForecast.Neutral(player.Velocity.X, true, motor.MotionSettings,
                    motor.ThrusterState.Module, 1d / Engine.PhysicsTicksPerSecond, 90 - phaseFrames + 12, 2f);
                Check(stop.SpeedThresholdReached, "ground neutral endpoint fits original Walk/settle allowance");
                float stopError = target - (player.GlobalPosition.X + stop.NetDistance);
                SendAction(InputActions.MoveLeft, stopError < -1.5f);
                SendAction(InputActions.MoveRight, stopError > 1.5f);
                return;
            }
            // The pointer and airborne Leg consumers have not yet been migrated.
            float delta = target - player.GlobalPosition.X, speed = player.Velocity.X;
            float brake = speed * speed / (2f * motor.Tuning.AirAcceleration) + 4f;
            bool toRight = delta > 2f && (speed <= 0f || brake < delta);
            bool toLeft = delta < -2f && (speed >= 0f || brake < -delta);
            if (!toRight && !toLeft && Mathf.Abs(speed) > 20f)
            { toLeft = speed > 0f; toRight = speed < 0f; }
            SendAction(InputActions.MoveLeft, toLeft); SendAction(InputActions.MoveRight, toRight);
        }
        async Task Settle(float target, string stance)
        {
            ReleaseMovement();
            ulong releaseSequence = input.CurrentFrameSequence;
            phase = stance + "-settle"; phaseFrames = 0;
            bool rightControlStance = keyboardRoute && (stance == "initial-control" || stance == "return-control");
            if (rightControlStance && input.KeyboardAimDirection.Dot(Vector2.Right) <= .999f)
            {
                // A reverse brake can leave facing left. A bounded real D sample,
                // then neutral deceleration, spends this SAME 12-frame settle budget.
                ulong directionBefore = input.CurrentFrameSequence;
                bool sampledD = false;
                SendAction(InputActions.MoveRight, true);
                try
                {
                    for (int frame = 0; frame < 4 && phaseFrames < 12; frame++)
                    {
                        await Tick();
                        if (input.CurrentFrameSequence > directionBefore && input.CurrentFrame.MoveAxis > 0f &&
                            input.KeyboardAimDirection.Dot(Vector2.Right) > .999f && Input.IsPhysicalKeyPressed(Key.D))
                        { sampledD = true; break; }
                    }
                    Check(sampledD, "samples a real rightward D preparation inside the original settle allowance");
                }
                finally { SendAction(InputActions.MoveRight, false); releaseSequence = input.CurrentFrameSequence; }
                var stop = FreeMotionForecast.Neutral(player.Velocity.X, true, motor.MotionSettings,
                    motor.ThrusterState.Module, 1d / Engine.PhysicsTicksPerSecond, 12 - phaseFrames, 2f);
                GD.Print($"TASK10_SHORTCUT_BOTTOM_RIGHT_PREP_NEUTRAL_PLAN physics={Engine.GetPhysicsFrames()} " +
                    $"sample={input.CurrentFrameSequence} target_x={target:R} x={player.GlobalPosition.X:R} " +
                    $"vx={player.Velocity.X:R} predicted_stop_x={player.GlobalPosition.X + stop.NetDistance:R} " +
                    $"forecast_steps={stop.Steps} reached={stop.SpeedThresholdReached} remaining={12 - phaseFrames}/12 " +
                    "timing=callsite-after-D-release-before-next-input-sample observer_only=true");
            }
            while (phaseFrames < 12 &&
                (input.CurrentFrameSequence <= releaseSequence || !Neutral() || !Stationary() ||
                    rightControlStance && !NeutralRight())) await Tick();
            Check(input.CurrentFrameSequence > releaseSequence && Neutral() && Stationary() &&
                (!rightControlStance || NeutralRight()) &&
                Mathf.Abs(player.GlobalPosition.X - target) <= 3f && Supported(requiredSupport),
                "samples neutral finite <=2 velocity, full support and target +/-3 within 12 settle frames");
        }
        async Task Walk(float target, string stance)
        {
            phase = stance + "-walk"; phaseFrames = 0;
            while (phaseFrames < 90 && (Mathf.Abs(player.GlobalPosition.X - target) > 3f || !Stationary()))
            { Steer(target); await Tick(); }
            Log("WALK_END");
            await Settle(target, stance);
            Check(claw.CurrentFrame.State == MechanicalClawState.Idle && claw.CurrentTarget == null &&
                claw.ResidencyTarget == null, "walk stance has actual target-free Idle");
        }
        async Task Leg(StaticBody2D from, StaticBody2D to, float target, int axis)
        {
            launchSupport = from; previousLaunchSupport = Supported(from);
            groundedLaunch = false; direction = axis; phase = axis < 0 ? "left-leg" : "right-leg";
            phaseFrames = 0;
            Check(previousLaunchSupport && Neutral() && Stationary(), "launches from full stopped sampled support");
            flight = true;
            SendAction(InputActions.MoveLeft, axis < 0); SendAction(InputActions.MoveRight, axis > 0);
            SendAction(InputActions.Jump, true);
            do
            {
                await Tick();
                if (groundedLaunch) Steer(target);
            } while (phaseFrames < 120 && (!groundedLaunch || !Supported(to)));
            Check(groundedLaunch && Supported(to) && motor.AcceptedJumpCount == jumps + completedLegs + 1,
                "lands through one accepted ordinary jump on actual upward contact/full capsule within 120 flight frames");
            completedLegs++; flight = false; requiredSupport = to;
            await Settle(target, phase);
            Log("LANDING");
        }
        void ObserveCast(MechanicalClawFrame frame, GrappleSurface2D target)
        {
            if (!operation) return;
            if (keyboardRoute && frame.State == MechanicalClawState.Aim && keyboardAimSequence == 0UL)
            {
                keyboardAimSequence = input.CurrentFrameSequence;
                keyboardAimTarget = target?.GetInstanceId() ?? 0UL;
                keyboardAimDirection = input.KeyboardAimDirection;
                keyboardAimSnapshot = claw.KeyboardPreview.Snapshot;
                keyboardAimSource = NeutralRight() && input.CurrentFrame.ClawPressed &&
                    Input.IsPhysicalKeyPressed(Key.K) && frame.CastId == 0UL && frame.NextCastId == operationCast &&
                    target == control && claw.KeyboardPreview.Surface == control &&
                    keyboardAimSnapshot.Exists && keyboardAimSnapshot.RuntimeId == controlId &&
                    keyboardAimSnapshot.HasLineOfSight &&
                    player.GlobalPosition.DistanceTo(keyboardAimSnapshot.WorldAnchor) <= 620f;
            }
            if (frame.State is MechanicalClawState.Reel or MechanicalClawState.Swing or MechanicalClawState.Boost || frame.BoostConsumed)
                pulling = true;
            if (frame.State == MechanicalClawState.Failed ||
                frame.CastId != 0UL && frame.CastId != operationCast) invalidCast = true;
            if (frame.State == MechanicalClawState.Latched)
            {
                exactLatch = frame.CastId == operationCast && target == control && frame.LockedTargetRuntimeId == controlId;
                if (!exactLatch) invalidCast = true;
            }
        }
        async Task Switch(CanyonSteamDiverterSide from, CanyonSteamDiverterSide to, CanyonSteamJet outgoing)
        {
            phase = $"control-{completedControls + 1}"; phaseFrames = 0;
            Check(pair.HasActivated && !pair.IsHandingOff && pair.SelectedSide == from && control.IsAvailable &&
                claw.CurrentFrame.State == MechanicalClawState.Idle && Neutral() && Stationary() && Supported(step),
                "starts enabled repeatable control from original activated side and full neutral Step");
            Vector2 anchor = control.WorldAnchor;
            MechanicalClawTargetResolver resolver = new();
            MechanicalClawTargetResolution resolution = keyboardRoute
                ? resolver.ResolveKeyboard(player, input.KeyboardAimDirection) : resolver.Resolve(player, anchor);
            if (keyboardRoute)
                GD.Print($"TASK10_SHORTCUT_BOTTOM_KEYBOARD_PREFLIGHT {Snapshot().Replace(",warning=", ",telegraph_visible=", StringComparison.Ordinal)} " +
                    $"selected={resolution.Surface?.GetPath()} material={resolution.Snapshot.Material} " +
                    $"anchor={resolution.Snapshot.WorldAnchor} los={resolution.Snapshot.HasLineOfSight}");
            Check(anchor.IsFinite() && control.GetWorld2D() == player.GetWorld2D() &&
                player.GlobalPosition.DistanceTo(anchor) <= 620f &&
                player.GetViewport().GetVisibleRect().Grow(-32f).HasPoint(ToViewport(player, anchor)) &&
                (!keyboardRoute || NeutralRight() &&
                    PlayerKeyboardAimModel.ResolveDirection(anchor - player.GlobalPosition, 1).Dot(Vector2.Right) > .999f &&
                    resolution.Snapshot.Exists && resolution.Snapshot.RuntimeId == controlId) &&
                resolution.Surface == control && resolution.Snapshot.HasLineOfSight,
                "resolves exact real control with LOS/range <=620/logical visibleRect.Grow(-32)");
            operation = true; operationStart = player.GlobalPosition; maxOperationDisplacement = 0f;
            operationPhysics = Engine.GetPhysicsFrames();
            operationCast = claw.CurrentFrame.NextCastId; exactLatch = false; operationPrimarySamples = 0;
            if (keyboardRoute)
            {
                operationKeyboardEdges = keyboard.ClawEdges; operationKeyboardSamples = 0;
                sampledRight = 0UL; keyboardAimSequence = 0UL; keyboardAimTarget = 0UL;
                keyboardAimDirection = Vector2.Zero; keyboardAimSnapshot = default; keyboardAimSource = false;
                keyboardReleaseSequence = 0UL;
                ulong releasedBefore = input.CurrentFrameSequence;
                SendAction(InputActions.Claw, false);
                while (phaseFrames < 10 && sampledRight == 0UL)
                {
                    await Tick();
                    if (input.CurrentFrameSequence > releasedBefore && Neutral() && NeutralRight() &&
                        modes.CanBeginGrapple && claw.CurrentFrame.State == MechanicalClawState.Idle)
                        sampledRight = input.CurrentFrameSequence;
                }
                Check(sampledRight > releasedBefore && keyboard.ClawEdges == operationKeyboardEdges,
                    "samples fresh stationary physical neutral Right with released K before its unique press");
                resolution = resolver.ResolveKeyboard(player, input.KeyboardAimDirection);
                Check(resolution.Surface == control && resolution.Snapshot.Exists &&
                    resolution.Snapshot.RuntimeId == controlId && resolution.Snapshot.HasLineOfSight &&
                    player.GlobalPosition.DistanceTo(resolution.Snapshot.WorldAnchor) <= 620f,
                    "actual fresh neutral Right resolves the same original control before K");
                ulong pressBefore = input.CurrentFrameSequence;
                SendAction(InputActions.Claw, true);
                try
                {
                    while (phaseFrames < 24 && (operationKeyboardSamples == 0 || keyboardAimSequence == 0UL ||
                        claw.CurrentFrame.NextCastId == operationCast)) await Tick();
                }
                finally
                {
                    SendAction(InputActions.Claw, false);
                    keyboardReleaseSequence = input.CurrentFrameSequence;
                }
                Check(operationKeyboardSamples == 1 && keyboard.ClawEdges == operationKeyboardEdges + 1 &&
                    keyboardAimSequence > pressBefore && keyboardAimSource && keyboardAimTarget == controlId &&
                    keyboardAimDirection.Dot(Vector2.Right) > .999f && keyboardAimSnapshot.Material == control.Material &&
                    claw.CurrentFrame.NextCastId == operationCast + 1UL,
                    "one fresh physical K sample and actual Right Aim admit exactly the original next control cast");
            }
            else
            {
                ulong modeBefore = input.CurrentFrameSequence; sampledE = 0;
                SendAction(InputActions.SelectGrappleMode, false); MoveMouse(player, anchor);
                await Tick();
                Check(input.CurrentFrameSequence > modeBefore && !input.CurrentFrame.GrappleModePressed,
                    "samples released E before its fresh press");
                modeBefore = input.CurrentFrameSequence;
                SendAction(InputActions.SelectGrappleMode, true);
                while (phaseFrames < 10 && (sampledE == 0 || !modes.CanBeginGrapple))
                {
                    await Tick();
                    if (input.CurrentFrameSequence > modeBefore && input.CurrentFrame.GrappleModePressed)
                        sampledE = input.CurrentFrameSequence;
                }
                SendAction(InputActions.SelectGrappleMode, false);
                Check(sampledE > modeBefore && modes.CanBeginGrapple, "samples fresh E before unique LMB");
                SendMouse(MouseButton.Left, false, player, anchor);
                ulong released = input.CurrentFrameSequence;
                await Tick();
                Check(input.CurrentFrameSequence > released && Neutral(), "samples released LMB before one fresh press");
                Safety();
                ulong processPhysics = Engine.GetPhysicsFrames();
                await tree.ToSignal(tree, SceneTree.SignalName.ProcessFrame);
                Safety();
                Check(Engine.GetPhysicsFrames() == processPhysics,
                    "safe mouse dispatch boundary adds no unobserved physics frame");
                SendMouse(MouseButton.Left, true, player, anchor);
                while (phaseFrames < 24 && (operationPrimarySamples == 0 || claw.CurrentFrame.NextCastId == operationCast))
                { MoveMouse(player, anchor); await Tick(); }
                SendMouse(MouseButton.Left, false, player, anchor);
                Check(operationPrimarySamples == 1 && claw.CurrentFrame.NextCastId == operationCast + 1UL,
                    "samples exactly one actual Primary and admits exactly one cast");
            }
            while (phaseFrames < 120 && adapter.ApplicationCount == applications + completedControls)
            { if (!keyboardRoute) MoveMouse(player, anchor); await Tick(); }
            Check(exactLatch && adapter.ApplicationCount == applications + completedControls + 1 &&
                pair.SelectedSide == to && pair.HasActivated, "exact latch applies once and switches requested side");
            Log("CONTROL_ACCEPTED");
            while (phaseFrames < 120 && (pair.IsHandingOff || claw.CurrentFrame.State != MechanicalClawState.Idle)) await Tick();
            Check(!pair.IsHandingOff && Dormant(outgoing) && pair.SelectedSide == to &&
                claw.CurrentFrame.State == MechanicalClawState.Idle && claw.CurrentFrame.CastId == 0UL &&
                claw.CurrentFrame.Failure == MechanicalClawFailure.None &&
                claw.CurrentTarget == null && claw.ResidencyTarget == null &&
                claw.CurrentFrame.NextCastId == operationCast + 1UL &&
                (keyboardRoute ? operationKeyboardSamples == 1 && keyboardAimSource && NeutralRight() &&
                    keyboard.ClawEdges == operationKeyboardEdges + 1 && input.CurrentFrameSequence > keyboardReleaseSequence
                    : operationPrimarySamples == 1) &&
                adapter.ApplicationCount == applications + completedControls + 1 && Neutral() && Stationary(),
                "whole operation <=120 physics frames naturally hands off to target-free Idle and outgoing Dormant");
            completedControls++; operation = false;
            Log("CONTROL_IDLE");
        }

        previousGuard = swapApproachGuard(Guard);
        claw.ClawFrameChanged += ObserveCast;
        try
        {
            Check(Live(left.Collision) && Live(right.Collision) && hurtShape.Shape is CapsuleShape2D &&
                left.Collision.Shape is RectangleShape2D &&
                right.Collision.Shape is RectangleShape2D && float.IsFinite(motor.Tuning.AirAcceleration) &&
                Mathf.Abs(hurtShape.GlobalTransform.X.Y) < .001f &&
                Mathf.Abs(hurtShape.GlobalTransform.Y.X) < .001f &&
                Mathf.Abs(left.Collision.GlobalTransform.X.Y) < .001f &&
                Mathf.Abs(left.Collision.GlobalTransform.Y.X) < .001f &&
                Mathf.Abs(right.Collision.GlobalTransform.X.Y) < .001f &&
                Mathf.Abs(right.Collision.GlobalTransform.Y.X) < .001f &&
                motor.Tuning.AirAcceleration > 0f, "has real capsule/jet geometry and finite positive steering acceleration");
            Check(pair.HasActivated && !pair.IsHandingOff && pair.SelectedSide == CanyonSteamDiverterSide.Left &&
                applications > 0 && claw.CurrentFrame.State == MechanicalClawState.Idle,
                "enters with original activated Left-selected pair and application baseline");
            ReleaseMovement(); Guard(); Log("ENTRY");
            await Walk(3960f, "initial-control");
            await Switch(CanyonSteamDiverterSide.Left, CanyonSteamDiverterSide.Right, left);
            await Walk(3880f, "step-launch");
            await Leg(step, walkway, 3760f, -1);
            await Leg(walkway, step, 3880f, 1);
            await Walk(3960f, "return-control");
            await Switch(CanyonSteamDiverterSide.Right, CanyonSteamDiverterSide.Left, right);
            Guard();
            Check(completedLegs == 2 && motor.AcceptedJumpCount == jumps + 2 && completedControls == 2 &&
                (keyboardRoute ? keyboardSamples == 2 && primarySamples == 0 &&
                    keyboard.ClawEdges == initialKeyboardEdges + 2 : primarySamples == 2) &&
                adapter.ApplicationCount == applications + 2 &&
                claw.CurrentFrame.NextCastId == initialNextCast + 2UL && Dormant(right) &&
                pair.SelectedSide == CanyonSteamDiverterSide.Left && Supported(step),
                "restores original pair role after exactly two jumps, two applications and no dash/HP/recovery/player change");
            Log("SUMMARY");
        }
        catch (Exception error)
        {
            GD.Print($"TASK10_SHORTCUT_BOTTOM_FAILURE phase={phase} first_exception={error}");
            if (Live(player) && Live(input) && Live(motor) && Live(health) && Live(claw) && Live(pair))
            {
                try { Log("FAILURE_STATE"); }
                catch (Exception diagnosticError) { GD.Print($"TASK10_SHORTCUT_BOTTOM_DIAGNOSTIC_FAILURE {diagnosticError}"); }
            }
            throw;
        }
        finally
        {
            if (GodotObject.IsInstanceValid(claw)) claw.ClawFrameChanged -= ObserveCast;
            swapApproachGuard(previousGuard);
            ReleaseMovement();
            if (keyboardRoute) SendAction(InputActions.Claw, false);
            else
            {
                SendAction(InputActions.SelectGrappleMode, false);
                SendMouse(MouseButton.Left, false, Live(player) ? player : null,
                    Live(control) ? control.WorldAnchor : Vector2.Zero);
            }
        }
    }

    private static async Task<bool> DefeatTask10GearSafeEncounter(SceneTree tree,
        PrologueLevelController level, SeamlessPrologueWorld world, CharacterBody2D player,
        RouteMonitor monitor, StaticBody2D gearEntry, StaticBody2D pistonOne,
        StaticBody2D pistonTwo, CanyonShieldLaneHazard shieldLane)
    {
        const string encounterId = "canyon.v2.encounter.gear-pistons";
        CanyonEncounterGroup group = world.FindChildren("*", "", true, false)
            .OfType<CanyonEncounterGroup>()
            .Single(encounter => encounter.EncounterId.ToString() == encounterId);
        Node actorRoot = group.GetNode(group.ActorRootPath);
        HealthComponent health = player.GetNode<HealthComponent>("Health");
        PlayerEnergyController energy = player.GetNode<PlayerEnergyController>("Energy");
        PlayerShieldController shield = player.GetNode<PlayerShieldController>("Shield");
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        PlayerActionModeController modes = player.GetNode<PlayerActionModeController>("ActionModes");
        PlayerCombat combat = player.GetNode<PlayerCombat>("Combat");
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        int startingHealth = health.CurrentHealth;
        int startingRecoveries = monitor.RecoveryCompleted;
        int startingRequests = monitor.RecoveryRequested;
        Rect2 arena = group.Definition.ArenaBounds;
        BellBackLaborer supportBell = null;
        bool supportBellSubscribed = false, supportObserved = false, supportWasOnFloor = false;
        int supportSlideCount = -1, supportSuppressed = 0, supportErrors = 0;
        string supportStage = "passenger-route", supportLastError = "none";
        var supportRows = new List<string>(16);
        var supportColliderIds = new ulong[8];
        var supportFloorContacts = new bool[8];

        void ObserveBellSupport(string boundary, bool force = false)
        {
            if (supportBell == null) return;
            try
            {
                if (!GodotObject.IsInstanceValid(supportBell) || !supportBell.IsInsideTree()) return;
                bool onFloor = supportBell.IsOnFloor();
                int slides = supportBell.GetSlideCollisionCount();
                int recordedSlides = Math.Min(slides, supportColliderIds.Length);
                bool changed = !supportObserved || onFloor != supportWasOnFloor || slides != supportSlideCount;
                for (int index = 0; index < recordedSlides; index++)
                {
                    using KinematicCollision2D contact = supportBell.GetSlideCollision(index);
                    GodotObject collider = contact.GetCollider();
                    ulong id = GodotObject.IsInstanceValid(collider) ? collider.GetInstanceId() : 0;
                    bool floorContact = contact.GetNormal().Y < -.7f;
                    changed |= id != supportColliderIds[index] || floorContact != supportFloorContacts[index];
                    supportColliderIds[index] = id;
                    supportFloorContacts[index] = floorContact;
                }
                supportObserved = true;
                supportWasOnFloor = onFloor;
                supportSlideCount = slides;
                if (!force && !changed) return;
                // Reserve room for the handoff and unwind; never print during Bell physics.
                if (supportRows.Count >= (force ? 16 : 14)) { supportSuppressed++; return; }
                var contacts = new List<string>(recordedSlides);
                for (int index = 0; index < recordedSlides; index++)
                {
                    using KinematicCollision2D contact = supportBell.GetSlideCollision(index);
                    GodotObject collider = contact.GetCollider();
                    string identity = !GodotObject.IsInstanceValid(collider) ? "invalid"
                        : collider is Node node && node.IsInsideTree()
                            ? $"{node.GetPath()}#{node.GetInstanceId()}" : $"detached#{collider.GetInstanceId()}";
                    contacts.Add($"{identity}:normal={contact.GetNormal()}:position={contact.GetPosition()}");
                }
                supportRows.Add($"TASK10_GEAR_BELL_SUPPORT boundary={boundary} stage={supportStage} " +
                    $"timing={(force ? "existing_driver_boundary" : "bell_post_MoveAndSlide")} " +
                    $"physics={Engine.GetPhysicsFrames()} actor={supportBell.GetInstanceId()} " +
                    $"bell={supportBell.GlobalPosition} velocity={supportBell.Velocity} " +
                    $"state={supportBell.CurrentState} floor={onFloor} " +
                    $"slides={recordedSlides}/{slides} contacts=[{string.Join(";", contacts)}] " +
                    $"player={player.GlobalPosition} player_floor={DescribeFloorCollider(player)}");
            }
            catch (Exception error)
            {
                supportErrors++;
                supportLastError = error.GetType().Name;
            }
        }
        void BellSupportFrame(BellBackLaborerFrame _, int __) => ObserveBellSupport("support-change");

        void CheckLive(string stage)
        {
            TestAssert.True(health.CurrentHealth > 0 &&
                            monitor.RecoveryCompleted == startingRecoveries &&
                            monitor.RecoveryRequested == startingRequests &&
                            group.IsActive && arena.HasPoint(player.GlobalPosition),
                $"Task10 gear {stage} keeps the same live encounter and player; " +
                $"player={player.GlobalPosition} health={health.CurrentHealth} " +
                $"recoveries={startingRecoveries}->{monitor.RecoveryCompleted} " +
                $"requests={startingRequests}->{monitor.RecoveryRequested} " +
                $"active={group.IsActive} batch={group.CurrentBatch}");
        }

        RustShellSquire LiveRust() => actorRoot.GetChildren().OfType<RustShellSquire>()
            .SingleOrDefault(actor => GodotObject.IsInstanceValid(actor) &&
                actor.Name.ToString().StartsWith(encounterId.Replace('.', '_'),
                    StringComparison.Ordinal));

        async Task CoolOnSafeFloor(StaticBody2D support, string stage)
        {
            SendMouse(MouseButton.Right, false, player, player.GlobalPosition + Vector2.Right * 240f);
            SendAction(InputActions.MoveLeft, false);
            SendAction(InputActions.MoveRight, false);
            for (int frame = 0; frame < 210 &&
                 (energy.HeatRatio > .02f || energy.EnergyRatio < .95f ||
                  energy.IsOverheated); frame++)
            {
                await PhysicsFrames(tree, monitor, 1);
                CheckLive(stage);
                TestAssert.True(HasFloorContact(player, support),
                    $"Task10 gear {stage} remains on {support.Name}; player={player.GlobalPosition}");
            }
            TestAssert.True(energy.HeatRatio <= .02f && energy.EnergyRatio >= .95f &&
                            !energy.IsOverheated && !input.Current.ShieldHeld &&
                            health.CurrentHealth == startingHealth,
                $"Task10 gear {stage} cools without healing or damage; " +
                $"energy={energy.EnergyRatio:0.000} heat={energy.HeatRatio:0.000} " +
                $"overheated={energy.IsOverheated} health={startingHealth}->{health.CurrentHealth}");
        }

        TestAssert.True(group.IsActive && group.CurrentBatch == 0 &&
                        HasFloorContact(player, pistonOne) && LiveRust() != null,
            $"Task10 gear starts on supported PistonOne with the real Rust batch; " +
            $"player={player.GlobalPosition} batch={group.CurrentBatch}");
        try
        {
            await CoolOnSafeFloor(pistonOne, "initial cool");
            SendAction(InputActions.MoveLeft, true);
            for (int frame = 0; frame < 100 && player.GlobalPosition.X > 2444f; frame++)
            {
                await PhysicsFrames(tree, monitor, 1);
                CheckLive("PistonOne approach");
            }
            SendAction(InputActions.MoveLeft, false);
            TestAssert.True(player.GlobalPosition.X <= 2446f &&
                            HasFloorContact(player, pistonOne),
                $"Task10 gear reaches x2444 on PistonOne by walking; player={player.GlobalPosition}");

            if (KeyboardRouteInputDriver.Current != null)
            {
                // A is also left aim. Unlike the legacy pointer route, keyboard play
                // cannot backpedal left while continuously guarding right.
                int pulsesAtStart = shieldLane.PulseCount;
                int guardedResults = 0, crossingFrames = 0;
                const float leftExitX = 2102f;
                int terminalSamples = 0;
                Action<PlayerShieldResult, ulong> guardObserved = (result, _) =>
                {
                    if (result.Guarded && result.DamageAmount == 0 &&
                        shield.GuardDirection.Dot(Vector2.Right) > .99f) guardedResults++;
                };
                shield.ShieldResolved += guardObserved;
                async Task CrossingTick()
                {
                    TestAssert.True(++crossingFrames <= 480,
                        "keyboard gear left crossing has a finite real-frame budget");
                    await PhysicsFrames(tree, monitor, 1);
                    CheckLive("keyboard pulse crossing");
                    TestAssert.True(health.CurrentHealth == startingHealth &&
                        !energy.IsOverheated && guardedResults >= shieldLane.PulseCount-pulsesAtStart,
                        $"keyboard gear guards every actual pulse without damage/recovery; " +
                        $"player={player.GlobalPosition} pulses={shieldLane.PulseCount-pulsesAtStart} " +
                        $"guards={guardedResults} heat={energy.HeatRatio:0.000}");
                }
                async Task FaceRightAndGuard()
                {
                    SendAction(InputActions.MoveLeft, false);
                    SendAction(InputActions.MoveRight, true);
                    SendMouse(MouseButton.Right, true, player, player.GlobalPosition+Vector2.Right*240f);
                    await CrossingTick();
                    SendAction(InputActions.MoveRight, false);
                    // This reads the real sampled facing; no position, velocity or
                    // private input/model state is assigned by the route driver.
                    SendMouse(MouseButton.Right, true, player, player.GlobalPosition+Vector2.Right*240f);
                }
                try
                {
                    SendAction(InputActions.MoveLeft, true);
                    while(player.GlobalPosition.X > 2412f) await CrossingTick();
                    await FaceRightAndGuard();
                    int pulse = shieldLane.PulseCount;
                    for(int frame=0; frame<30 && shieldLane.PulseCount==pulse; frame++)
                        await CrossingTick();
                    TestAssert.True(shieldLane.PulseCount>pulse,
                        $"keyboard gear enters the real lane behind a right guard; player={player.GlobalPosition}");
                    while(player.GlobalPosition.X > leftExitX || !HasFloorContact(player,gearEntry))
                    {
                        pulse=shieldLane.PulseCount;
                        SendMouse(MouseButton.Right,false,player,Vector2.Zero);
                        SendAction(InputActions.MoveLeft,true);
                        for(int frame=0;frame<9 && player.GlobalPosition.X>leftExitX;frame++)
                        {
                            bool terminal = player.GlobalPosition.X <= 2110f &&
                                HasFloorContact(player, gearEntry) &&
                                !shieldLane.GetOverlappingBodies().Contains(player);
                            bool coast = false;
                            float projectedStop = float.NaN;
                            if (terminal)
                            {
                                var stop = FreeMotionForecast.Neutral(player.Velocity.X, true,
                                    motor.MotionSettings, motor.ThrusterState.Module,
                                    1d / Engine.PhysicsTicksPerSecond, 9 - frame, .5f);
                                projectedStop = player.GlobalPosition.X + stop.NetDistance;
                                coast = stop.SpeedThresholdReached && projectedStop >= 2080f &&
                                    projectedStop <= leftExitX;
                                SendAction(InputActions.MoveLeft, !coast);
                                terminalSamples++;
                            }
                            await CrossingTick();
                            if (terminal)
                                GD.Print($"KEYBOARD_GEAR_TERMINAL_TAIL sample={terminalSamples} " +
                                    $"position={player.GlobalPosition} velocity={player.Velocity} " +
                                    $"input_sequence={input.CurrentFrameSequence} " +
                                    $"sampled_axis={input.Current.MoveAxis} sampled_shield={input.Current.ShieldHeld} " +
                                    $"coast={coast} projected_stop={projectedStop:0.000} " +
                                    $"heat={energy.HeatRatio:0.000} pulses={shieldLane.PulseCount-pulsesAtStart} " +
                                    "observation=physics_signal_before_node_process");
                        }
                        // Once fully out on the original safe shelf, do not
                        // re-face/re-raiseL merely to bridge the old2110 dead zone.
                        if (player.GlobalPosition.X <= leftExitX && HasFloorContact(player, gearEntry) &&
                            !shieldLane.GetOverlappingBodies().Contains(player)) break;
                        await FaceRightAndGuard();
                        for(int frame=0;frame<20;frame++)
                        {
                            await CrossingTick();
                            if(shieldLane.PulseCount>pulse ||
                                player.GlobalPosition.X<=leftExitX && HasFloorContact(player,gearEntry) &&
                                !shieldLane.GetOverlappingBodies().Contains(player)) break;
                        }
                    }
                    GD.Print($"KEYBOARD_GEAR_LEFT_CROSSING_OK frames={crossingFrames} " +
                        $"pulses={shieldLane.PulseCount-pulsesAtStart} guards={guardedResults} " +
                        $"player={player.GlobalPosition} health={startingHealth}->{health.CurrentHealth} heat={energy.HeatRatio:0.000} " +
                        $"terminal_samples={terminalSamples} original_budget=480");
                }
                finally { shield.ShieldResolved -= guardObserved; }
            }
            else
            {
            SendMouse(MouseButton.Right, true, player,
                player.GlobalPosition + Vector2.Right * 240f);
            SendAction(InputActions.MoveLeft, true);
            bool shieldHeldAcrossLane = true;
            for (int frame = 0; frame < 180 && player.GlobalPosition.X > 2102f; frame++)
            {
                MoveMouse(player, player.GlobalPosition + Vector2.Right * 240f);
                await PhysicsFrames(tree, monitor, 1);
                CheckLive("shielded left crossing");
                if (shieldLane.GetOverlappingBodies().Contains(player) &&
                    (!input.Current.ShieldHeld || !shield.IsActive))
                    shieldHeldAcrossLane = false;
            }
            TestAssert.True(shieldHeldAcrossLane,
                "legacy gear crossing retains continuous pointer-aimed shielding");
            }
            SendAction(InputActions.MoveLeft, false);
            SendMouse(MouseButton.Right, false, player,
                player.GlobalPosition + Vector2.Right * 240f);
            await PhysicsFrames(tree, monitor, 1);
            CheckLive("GearEntry arrival");
            TestAssert.True(player.GlobalPosition.X is >= 2080f and <= 2102f &&
                            HasFloorContact(player, gearEntry) &&
                            !shieldLane.GetOverlappingBodies().Contains(player) &&
                            health.CurrentHealth == startingHealth && group.CurrentBatch == 0,
                $"Task10 gear reaches the safe left GearEntry floor through real shielded input; " +
                $"player={player.GlobalPosition} health={startingHealth}->{health.CurrentHealth} " +
                $"heat={energy.HeatRatio:0.000} lane_overlap=" +
                $"{shieldLane.GetOverlappingBodies().Contains(player)}");
            GD.Print($"TASK10_GEAR_SAFE_SHELF_OK player={player.GlobalPosition} " +
                $"health={health.CurrentHealth} heat={energy.HeatRatio:0.000} " +
                $"lane_overlap={shieldLane.GetOverlappingBodies().Contains(player)} " +
                $"batch={group.CurrentBatch} recoveries={monitor.RecoveryCompleted}");

            SendAction(InputActions.MoveRight, true);
            await PhysicsFrames(tree, monitor, 1);
            SendAction(InputActions.MoveRight, false);
            CheckLive("right-facing pulse");
            TestAssert.True(player.GlobalPosition.X <= 2109f &&
                            !shieldLane.GetOverlappingBodies().Contains(player) &&
                            HasFloorContact(player, gearEntry),
                $"Task10 gear right-facing pulse remains outside ShieldLane; player={player.GlobalPosition}");
            SendAction(InputActions.SelectAttackMode, true);
            await PhysicsFrames(tree, monitor, 1);
            SendAction(InputActions.SelectAttackMode, false);
            CheckLive("attack selection");

            RustShellSquire rust = LiveRust();
            TestAssert.True(GodotObject.IsInstanceValid(rust),
                "Task10 gear keeps the first-batch Rust actor alive before combat");
            ulong rustId = rust.GetInstanceId();
            HealthComponent rustHealth = rust.GetNode<HealthComponent>("Health");
            int rustHealthAtStart = rustHealth.CurrentHealth;
            int rustDamageEvents = 0;
            int attackStarts = 0;
            int attackCompletions = 0;
            int attackConnections = 0;
            int lateShieldStarts = 0;
            int attackActiveSamples = 0;
            string firstUnguardedActiveSample = null;
            bool wasAttacking = combat.IsAttacking;
            HealthComponent.DamagedEventHandler rustDamaged = (_, _) => rustDamageEvents++;
            PlayerCombat.AttackStartedEventHandler attackStarted = (_, _) => attackStarts++;
            PlayerCombat.AttackConnectedEventHandler attackConnected = _ => attackConnections++;
            Action<RustShellFrame, int> rustFrameObserved = (frame, _) =>
            {
                if (frame.AttackTimeline.Phase != AttackPhase.Active) return;
                attackActiveSamples++;
                if (input.Current.ShieldHeld && shield.IsActive &&
                    shield.GuardDirection.Dot(Vector2.Right) >= .9f &&
                    !energy.IsOverheated) return;
                firstUnguardedActiveSample ??=
                    $"sample={input.CurrentFrameSequence} player={player.GlobalPosition} " +
                    $"rust={rust.GlobalPosition} held={input.Current.ShieldHeld} " +
                    $"active={shield.IsActive} direction={shield.GuardDirection} " +
                    $"heat={energy.HeatRatio:0.000} state={frame.State}";
            };
            rustHealth.Damaged += rustDamaged;
            rust.FrameChanged += rustFrameObserved;
            combat.AttackStarted += attackStarted;
            combat.AttackConnected += attackConnected;
            try
            {
                for (int frame = 0; frame < 900 && GodotObject.IsInstanceValid(rust) &&
                     rustHealth.CurrentHealth > 0; frame++)
                {
                    CheckLive("Rust combat");
                    TestAssert.True(group.CurrentBatch == 0 &&
                                    rust.GetInstanceId() == rustId &&
                                    player.GlobalPosition.X <= 2109f &&
                                    !shieldLane.GetOverlappingBodies().Contains(player) &&
                                    HasFloorContact(player, gearEntry),
                        $"Task10 Rust combat stays on the safe supported shelf; " +
                        $"player={player.GlobalPosition} rust={rust.GlobalPosition} " +
                        $"batch={group.CurrentBatch}");
                    Vector2 target = rust.GlobalPosition;
                    float dx = target.X - player.GlobalPosition.X;
                    float dy = target.Y - player.GlobalPosition.Y;
                    AttackTimelineFrame timeline = rust.CurrentFrame.AttackTimeline;
                    bool lateShield = rust.CurrentState == RustShellState.Attack ||
                        rust.CurrentState == RustShellState.Telegraph &&
                        timeline.PhaseRemainingSeconds <= .12f;
                    if (lateShield && !input.Current.ShieldHeld)
                    {
                        TestAssert.True(energy.HeatRatio <= .84f && !energy.IsOverheated,
                            $"Task10 Rust late-guard onset retains heat headroom; " +
                            $"state={rust.CurrentState} remaining={timeline.PhaseRemainingSeconds:0.000} " +
                            $"heat={energy.HeatRatio:0.000} energy={energy.EnergyRatio:0.000}");
                        lateShieldStarts++;
                    }
                    MoveMouse(player, target);
                    SendMouse(MouseButton.Right, lateShield, player, target);
                    if (rust.CurrentState == RustShellState.Recover &&
                        dx > 0f && dx <= 74f && MathF.Abs(dy) <= 10f &&
                        !input.Current.ShieldHeld && !shield.IsActive &&
                        modes.CanBeginAttack && !combat.IsAttacking)
                    {
                        SendMouse(MouseButton.Left, true, player, target);
                        await PhysicsFrames(tree, monitor, 2);
                        SendMouse(MouseButton.Left, false, player, target);
                    }
                    else
                    {
                        await PhysicsFrames(tree, monitor, 1);
                    }
                    CheckLive("Rust combat frame");
                    TestAssert.True(firstUnguardedActiveSample == null,
                        $"Task10 Rust attack-active physics sample has real right-facing shield; " +
                        firstUnguardedActiveSample);
                    if (wasAttacking && !combat.IsAttacking) attackCompletions++;
                    wasAttacking = combat.IsAttacking;
                }
            }
            finally
            {
                SendMouse(MouseButton.Left, false, player, player.GlobalPosition + Vector2.Right * 240f);
                SendMouse(MouseButton.Right, false, player, player.GlobalPosition + Vector2.Right * 240f);
                if (GodotObject.IsInstanceValid(rustHealth)) rustHealth.Damaged -= rustDamaged;
                if (GodotObject.IsInstanceValid(rust)) rust.FrameChanged -= rustFrameObserved;
                combat.AttackStarted -= attackStarted;
                combat.AttackConnected -= attackConnected;
            }
            await PhysicsFrames(tree, monitor, 2);
            CheckLive("Rust defeat");
            TestAssert.True(!GodotObject.IsInstanceValid(rust) &&
                            group.CurrentBatch == 1 && !group.IsComplete &&
                            rustDamageEvents > 0 && attackStarts > 0 &&
                            attackConnections > 0 && attackCompletions > 0 &&
                            lateShieldStarts > 0 && attackActiveSamples > 0 &&
                            firstUnguardedActiveSample == null,
                $"Task10 real attack input defeats Rust before Bell batch; " +
                $"rust_health={rustHealthAtStart}->0 damage_events={rustDamageEvents} " +
                $"attacks_started={attackStarts} completed={attackCompletions} " +
                $"connected={attackConnections} late_guard_starts={lateShieldStarts} " +
                $"active_guard_samples={attackActiveSamples} " +
                $"unguarded={firstUnguardedActiveSample ?? "none"} batch={group.CurrentBatch}");
            GD.Print($"TASK10_GEAR_RUST_INPUT_OK rust_id={rustId} " +
                $"damage_events={rustDamageEvents} attacks_started={attackStarts} " +
                $"completed={attackCompletions} connected={attackConnections} " +
                $"late_guard_starts={lateShieldStarts} active_guard_samples={attackActiveSamples} " +
                $"health={health.CurrentHealth} recovery={monitor.RecoveryCompleted}");

            await CoolOnSafeFloor(gearEntry, "post-Rust cool");
            SendMouse(MouseButton.Right, true, player,
                player.GlobalPosition + Vector2.Right * 240f);
            SendAction(InputActions.MoveRight, true);
            int returnHealth = health.CurrentHealth;
            int returnLaneSamples = 0;
            bool returnShieldHeldAcrossLane = true;
            for (int frame = 0; frame < 180 && player.GlobalPosition.X < 2350f; frame++)
            {
                MoveMouse(player, player.GlobalPosition + Vector2.Right * 240f);
                await PhysicsFrames(tree, monitor, 1);
                CheckLive("Bell return crossing");
                if (!shieldLane.GetOverlappingBodies().Contains(player)) continue;
                returnLaneSamples++;
                if (!input.Current.ShieldHeld || !shield.IsActive ||
                    shield.GuardDirection.Dot(Vector2.Right) < .9f)
                    returnShieldHeldAcrossLane = false;
            }
            SendAction(InputActions.MoveRight, false);
            TestAssert.True(player.GlobalPosition.X >= 2348f &&
                            HasFloorContact(player, gearEntry) && group.CurrentBatch == 1 &&
                            returnLaneSamples > 0 && returnShieldHeldAcrossLane &&
                            health.CurrentHealth == returnHealth,
                $"Task10 gear returns to x2350 by guarded ShieldLane walk; " +
                $"player={player.GlobalPosition} lane_samples={returnLaneSamples} " +
                $"shielded={returnShieldHeldAcrossLane} health={returnHealth}->{health.CurrentHealth}");
            GD.Print($"TASK10_GEAR_RETURN_LANE_OK player={player.GlobalPosition} " +
                $"lane_samples={returnLaneSamples} shielded={returnShieldHeldAcrossLane} " +
                $"health={returnHealth}->{health.CurrentHealth}");
            await ShieldJumpToSupport(tree, player, monitor, shieldLane, pistonOne);
            SendMouse(MouseButton.Right, false, player,
                player.GlobalPosition + Vector2.Right * 240f);
            CheckLive("PistonOne return");
            if (KeyboardRouteInputDriver.Current != null)
            {
                TestAssert.True(world.TryGetMountedSector(PrologueSectorId.CanyonBasin,out var basin),
                    "actual Basin remains mounted for the passenger route");
                var liveBell=actorRoot.GetChildren().OfType<BellBackLaborer>().Single(actor=>
                    actor.Name.ToString().StartsWith(encounterId.Replace('.','_'),StringComparison.Ordinal));
                ulong liveBellId=liveBell.GetInstanceId();
                var liveBellHealth=liveBell.GetNode<HealthComponent>("Health");
                int bellHp=liveBellHealth.CurrentHealth;
                TestAssert.True(bellHp>0 && group.CurrentBatch==1,"passenger route starts with naturally spawned living Bell batch");
                supportBell = liveBell;
                supportBell.FrameChanged += BellSupportFrame;
                supportBellSubscribed = true;
                ObserveBellSupport("PistonOne-return", force: true);
                await BasinCounterweightRuntimeTests.TraverseForFullRoute(player,basin,
                    async count =>
                    {
                        for(int i=0;i<count;i++)
                        {
                            await PhysicsFrames(tree,monitor,1);
                            TestAssert.True(group.IsActive && !group.IsComplete && group.CurrentBatch==1 &&
                                group.LiveActorCount==1 && GodotObject.IsInstanceValid(liveBell) &&
                                liveBell.IsInsideTree() && liveBell.GetInstanceId()==liveBellId &&
                                liveBell.GetParent()==actorRoot && liveBellHealth.CurrentHealth==bellHp,
                                $"BasinActualBellRetention: passenger route must keep the same living Bell through every frame; player={player.GlobalPosition} active={group.IsActive} batch={group.CurrentBatch}");
                        }
                    });
                GD.Print($"TASK10_BASIN_LIVE_BELL_RETAINED actor={liveBellId} health={bellHp} batch={group.CurrentBatch}");
            }
            else await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player,
                pistonTwo, clawRequired: false);
            CheckLive("PistonTwo Bell approach");
            TestAssert.True(group.CurrentBatch == 1 &&
                            actorRoot.GetChildren().OfType<BellBackLaborer>().Any(actor =>
                                GodotObject.IsInstanceValid(actor) &&
                                actor.GetNode<HealthComponent>("Health").CurrentHealth > 0),
                $"Task10 gear observes live second-batch Bell on PistonTwo; " +
                $"player={player.GlobalPosition} batch={group.CurrentBatch}");
            supportStage = "generic-fight";
            ObserveBellSupport("PistonTwo-handoff", force: true);
            bool lowerBellRoundTrip = false;
            if (KeyboardRouteInputDriver.Current != null &&
                GodotObject.IsInstanceValid(supportBell) &&
                world.TryGetMountedSector(PrologueSectorId.CanyonBasin, out var returnBasin) &&
                HasFloorContact(supportBell,
                    returnBasin.GetNode<StaticBody2D>("Gameplay/Collision/ShortcutBasinWalkway")))
            {
                supportStage = "lower-Bell-round-trip";
                await DefeatTask10LowerBellAndReturn(tree, level, world, player, monitor,
                    returnBasin, group, supportBell, gearEntry, pistonOne, pistonTwo, shieldLane);
                lowerBellRoundTrip = true;
            }
            else await DefeatTask10Encounter(tree, level, world, player, monitor, encounterId);
            TestAssert.True(group.IsComplete &&
                            monitor.RecoveryCompleted == startingRecoveries &&
                            monitor.RecoveryRequested == startingRequests,
                "Task10 gear completes only after real Rust and Bell defeats without recovery");
            return lowerBellRoundTrip;
        }
        finally
        {
            ObserveBellSupport("unwind", force: true);
            try
            {
                if (supportBellSubscribed && GodotObject.IsInstanceValid(supportBell))
                    supportBell.FrameChanged -= BellSupportFrame;
            }
            catch (Exception error)
            {
                supportErrors++;
                supportLastError = error.GetType().Name;
            }
            try
            {
                SendAction(InputActions.MoveLeft, false);
                SendAction(InputActions.MoveRight, false);
                SendAction(InputActions.SelectAttackMode, false);
                SendMouse(MouseButton.Left, false, player,
                    player.GlobalPosition + Vector2.Right * 240f);
                SendMouse(MouseButton.Right, false, player,
                    player.GlobalPosition + Vector2.Right * 240f);
            }
            finally
            {
                if (supportBell != null)
                {
                    try
                    {
                        foreach (string row in supportRows) GD.Print(row);
                        GD.Print($"TASK10_GEAR_BELL_SUPPORT_SUMMARY rows={supportRows.Count}/16 " +
                            $"suppressed_changes={supportSuppressed} diagnostic_errors={supportErrors} " +
                            $"last_error={supportLastError}");
                    }
                    catch (Exception) { /* Preserve the original route result if reporting fails. */ }
                }
            }
        }
    }

    private static async Task DefeatTask10LowerBellAndReturn(SceneTree tree,
        PrologueLevelController level, SeamlessPrologueWorld world, CharacterBody2D player,
        RouteMonitor monitor, PrologueSector basin, CanyonEncounterGroup group, BellBackLaborer bell,
        StaticBody2D gearEntry, StaticBody2D pistonOne, StaticBody2D pistonTwo,
        CanyonShieldLaneHazard shieldLane)
    {
        var driver = KeyboardRouteInputDriver.Current;
        var walkway = basin.GetNode<StaticBody2D>("Gameplay/Collision/ShortcutBasinWalkway");
        var returnStep = basin.GetNode<StaticBody2D>("Gameplay/Collision/ShortcutCampReturnStep");
        var health = player.GetNode<HealthComponent>("Health");
        var bellHealth = bell.GetNode<HealthComponent>("Health");
        var energy = player.GetNode<PlayerEnergyController>("Energy");
        var motor = player.GetNode<PlayerMotor>("Motor");
        var shield = player.GetNode<PlayerShieldController>("Shield");
        var input = player.GetNode<PlayerInputReader>("Input");
        Node actorRoot = bell.GetParent();
        ulong playerId = player.GetInstanceId(), bellId = bell.GetInstanceId(), groupId = group.GetInstanceId();
        int hp = health.CurrentHealth, bellHp = bellHealth.CurrentHealth;
        int recoveries = monitor.RecoveryCompleted, requests = monitor.RecoveryRequested;
        int dashes = motor.AcceptedDashCount, defeats = 0, damage = 0, healing = 0;
        int approachJumps = motor.AcceptedJumpCount;
        int guardedPulses = 0, pulseStart = 0, returnJumpFrames = 0;
        int runupJumps = 0;
        bool combatStarted = false, checkPulses = false, shieldRunup = false;
        string stage = "lower-approach";
        Exception observedFailure = null;
        HealthComponent.DamagedEventHandler onDamage = (_, _) => damage++;
        HealthComponent.HealedEventHandler onHeal = (_, _) => healing++;
        Action onDefeat = () => defeats++;
        Action<PlayerShieldResult, ulong> onGuard = (result, _) =>
        {
            if (result.Guarded && result.DamageAmount == 0 &&
                shield.GuardDirection.Dot(Vector2.Right) > .99f) guardedPulses++;
        };
        bool FullFloor(StaticBody2D support) => HasFloorContact(player, support) &&
            Mathf.Abs(player.GlobalPosition.X - support.GlobalPosition.X) <=
            ((RectangleShape2D)support.GetNode<CollisionShape2D>("Collision").Shape).Size.X / 2f - 20f + .1f;
        void Check()
        {
            TestAssert.True(GodotObject.IsInstanceValid(player) && player.IsInsideTree() &&
                player == monitor.Player && player.GetInstanceId() == playerId &&
                health.CurrentHealth == hp && hp > 0 && damage == 0 && healing == 0 &&
                monitor.RecoveryCompleted == recoveries && monitor.RecoveryRequested == requests &&
                motor.AcceptedDashCount == dashes && group.IsInsideTree() && group.GetInstanceId() == groupId,
                $"LowerBellRoundTrip {stage}: same live player/HP, no healing, recovery or dash; " +
                $"player={player.GlobalPosition} hp={hp}->{health.CurrentHealth} damage={damage} healing={healing}");
            TestAssert.True(defeats == 0
                ? group.IsActive && !group.IsComplete && group.CurrentBatch == 1 && group.LiveActorCount == 1 &&
                  GodotObject.IsInstanceValid(bell) && bell.IsInsideTree() && bell.GetParent() == actorRoot &&
                  bell.GetInstanceId() == bellId && bellHealth.CurrentHealth > 0 &&
                  (combatStarted || bellHealth.CurrentHealth == bellHp)
                : defeats == 1 && combatStarted && group.IsComplete && group.LiveActorCount == 0,
                $"LowerBellRoundTrip {stage}: original Bell survives until real combat defeat, never retires/restarts; " +
                $"actor={bellId} defeats={defeats} active={group.IsActive} batch={group.CurrentBatch}");
            TestAssert.True(!checkPulses || !energy.IsOverheated &&
                guardedPulses >= shieldLane.PulseCount - pulseStart,
                $"LowerBellRoundTrip {stage}: every actual lane pulse is guarded; " +
                $"pulses={shieldLane.PulseCount-pulseStart} guards={guardedPulses} player={player.GlobalPosition}");
            TestAssert.True(stage != "lower-combat-stance" || FullFloor(walkway) &&
                HasFloorContact(bell, walkway) && motor.AcceptedJumpCount == approachJumps,
                "lower Bell stance retreat keeps both real walkway supports and uses no jump");
            TestAssert.True(!shieldRunup || FullFloor(gearEntry) && player.GlobalPosition.X <= 2354f &&
                motor.AcceptedJumpCount == runupJumps && !input.Current.JumpHeld &&
                input.Current.ShieldHeld && shield.IsActive && shield.GuardDirection.Dot(Vector2.Right) > .99f,
                $"lower Bell right-shield run-up retains full GearEntry support, released Space and launch window; " +
                $"player={player.GlobalPosition} velocity={player.Velocity}");
        }
        async Task Step(int count = 1)
        {
            for (int index = 0; index < count; index++)
            {
                if (stage == "guarded-return-jump")
                    TestAssert.True(++returnJumpFrames <= 140, "lower Bell return uses one bounded 80px jump, never retries");
                await PhysicsFrames(tree, monitor, 1);
                if (observedFailure != null) throw observedFailure;
                Check();
            }
        }
        async Task Until(Func<bool> done, int cap, string label)
        {
            for (int frame = 0; frame < cap && !done(); frame++) await Step();
            if (observedFailure != null) throw observedFailure;
            Check();
            TestAssert.True(done(), $"LowerBellRoundTrip {stage}: {label}; " +
                $"player={player.GlobalPosition} velocity={player.Velocity} floor={DescribeFloorCollider(player)}");
        }
        async Task FaceRightAndGuard()
        {
            SendAction(InputActions.MoveLeft, false);
            SendAction(InputActions.MoveRight, true);
            ulong sequence = input.CurrentFrameSequence;
            SendMouse(MouseButton.Right, true, player, player.GlobalPosition + Vector2.Right * 240f);
            await Until(() => input.CurrentFrameSequence > sequence && input.Current.ShieldHeld &&
                shield.IsActive && shield.GuardDirection.Dot(Vector2.Right) > .99f, 4, "actual right guard admitted");
            SendAction(InputActions.MoveRight, false);
            SendMouse(MouseButton.Right, true, player, player.GlobalPosition + Vector2.Right * 240f);
        }
        TestAssert.True(driver != null && FullFloor(pistonTwo) && HasFloorContact(bell, walkway),
            "lower Bell branch requires actual PistonTwo player support and original Bell walkway support");
        var observer = new BasinBoardingTickObserver { ProcessPhysicsPriority = 100 };
        observer.Sample = _ => { try { Check(); } catch (Exception error) { observedFailure ??= error; } };
        try
        {
            health.Damaged += onDamage; health.Healed += onHeal;
            bell.Defeated += onDefeat; shield.ShieldResolved += onGuard;
            player.AddChild(observer);
            Check(); driver.ReleaseAll();
            SendAction(InputActions.MoveLeft, true);
            await Until(() => player.GlobalPosition.X <= 2690f, 110, "A reaches the real missed-lift gap");
            SendAction(InputActions.MoveLeft, false);
            await Until(() => HasFloorContact(player, walkway), 140, "natural fall lands on original lower walkway");
            TestAssert.True(HasFloorContact(bell, walkway) &&
                Mathf.Abs(player.GlobalPosition.Y - bell.GlobalPosition.Y) <= 46f,
                "same living Bell and player are on the original lower combat floor");
            // Start in the original melee band's outer portion. Near-overlap L/K
            // uses diagonal WASD aim, which can move the player through Bell's cone.
            stage = "lower-combat-stance";
            TestAssert.True(float.IsFinite(motor.Tuning.GroundDeceleration) && motor.Tuning.GroundDeceleration > 0f,
                "lower Bell stance uses the actual finite ground braking setting");
            GD.Print($"TASK10_GEAR_LOWER_STANCE_BEGIN actor={bellId} gap={bell.GlobalPosition.X-player.GlobalPosition.X:0.000} " +
                $"velocity={player.Velocity} bell_state={bell.CurrentState} remaining={bell.CurrentFrame.AttackTimeline.PhaseRemainingSeconds:0.000} hp={hp}");
            SendAction(InputActions.MoveLeft, true);
            await Until(() => player.GlobalPosition.X - (bell.GlobalPosition.X - 60f) <=
                Mathf.Pow(Mathf.Max(0f, -player.Velocity.X), 2f) / (2f * motor.Tuning.GroundDeceleration),
                45, "real A retreats toward the same Bell's 60px melee stance");
            SendAction(InputActions.MoveLeft, false);
            await Until(() => Mathf.Abs(player.Velocity.X) <= 2f && Mathf.Abs(input.Current.MoveAxis) <= .001f,
                12, "A release is sampled and the supported player actually stops");
            float handoffGap = bell.GlobalPosition.X - player.GlobalPosition.X;
            TestAssert.True(handoffGap is >= 56f and <= 64f &&
                Mathf.Abs(player.GlobalPosition.Y - bell.GlobalPosition.Y) <= 46f,
                $"lower Bell handoff retains the original horizontal strike band; gap={handoffGap} player={player.GlobalPosition}");
            GD.Print($"TASK10_GEAR_LOWER_STANCE actor={bellId} gap={handoffGap:0.000} " +
                $"velocity={player.Velocity} bell_state={bell.CurrentState} remaining={bell.CurrentFrame.AttackTimeline.PhaseRemainingSeconds:0.000} " +
                $"player={player.GlobalPosition} hp={hp}");
            GD.Print($"TASK10_GEAR_LOWER_HANDOFF actor={bellId} bell={bell.GlobalPosition} player={player.GlobalPosition} hp={hp}");
            stage = "original-900-frame-combat"; combatStarted = true;
            await DefeatTask10Encounter(tree, level, world, player, monitor, group.EncounterId.ToString());
            if (observedFailure != null) throw observedFailure;
            Check(); TestAssert.True(defeats == 1, "original lower Bell is defeated by the unchanged combat driver");

            stage = "lower-return"; driver.ReleaseAll();
            int returnJumps = motor.AcceptedJumpCount;
            var recoveryTuning = energy.Tuning;
            float energyAtCooling = energy.EnergyRatio, heatAtCooling = energy.HeatRatio;
            float energyNeeded = Mathf.Max(0f, .95f - energyAtCooling) * recoveryTuning.MaxEnergy;
            float heatToCool = Mathf.Max(0f, heatAtCooling - .02f) * 100f;
            TestAssert.True(float.IsFinite(energyNeeded) && float.IsFinite(heatToCool) &&
                float.IsFinite(recoveryTuning.MaxEnergy) && recoveryTuning.MaxEnergy > 0f &&
                float.IsFinite(recoveryTuning.RegenDelaySeconds) && recoveryTuning.RegenDelaySeconds >= 0f &&
                float.IsFinite(recoveryTuning.HeatCoolDelaySeconds) && recoveryTuning.HeatCoolDelaySeconds >= 0f &&
                (energyNeeded == 0f || float.IsFinite(recoveryTuning.RegenPerSecond) && recoveryTuning.RegenPerSecond > 0f) &&
                (heatToCool == 0f || float.IsFinite(recoveryTuning.HeatCoolPerSecond) && recoveryTuning.HeatCoolPerSecond > 0f),
                "post-Bell natural recovery has finite delays and positive required recovery rates");
            double energySeconds = energyNeeded > 0f
                ? recoveryTuning.RegenDelaySeconds + energyNeeded / recoveryTuning.RegenPerSecond : 0d;
            double heatSeconds = heatToCool > 0f
                ? recoveryTuning.HeatCoolDelaySeconds + heatToCool / recoveryTuning.HeatCoolPerSecond : 0d;
            double recoveryFrames = Math.Ceiling(Math.Max(energySeconds, heatSeconds) * Engine.PhysicsTicksPerSecond);
            // Full configured delays overestimate their unexposed remaining values;
            // four fixed observations cover input release and pre-physics sampling, never retry the budget.
            const int recoverySamplingMargin = 4;
            TestAssert.True(Engine.PhysicsTicksPerSecond > 0 && double.IsFinite(recoveryFrames) &&
                recoveryFrames >= 0d && recoveryFrames <= int.MaxValue - recoverySamplingMargin,
                "post-Bell recovery has a finite model-derived observation budget");
            int recoveryCap = (int)recoveryFrames + recoverySamplingMargin;
            ulong recoveryPhysics = Engine.GetPhysicsFrames();
            GD.Print($"TASK10_GEAR_LOWER_COOL_BEGIN energy={energyAtCooling:R} heat={heatAtCooling:R} " +
                $"regen_delay={recoveryTuning.RegenDelaySeconds:R} regen_rate={recoveryTuning.RegenPerSecond:R} " +
                $"cool_delay={recoveryTuning.HeatCoolDelaySeconds:R} cool_rate={recoveryTuning.HeatCoolPerSecond:R} " +
                $"energy_seconds={energySeconds:R} heat_seconds={heatSeconds:R} cap={recoveryCap} " +
                $"sampling_margin={recoverySamplingMargin} physics={recoveryPhysics}");
            try
            {
                await Until(() => energy.HeatRatio <= .02f && energy.EnergyRatio >= .95f && !energy.IsOverheated,
                    recoveryCap, "natural post-combat cooling without health recovery");
            }
            finally
            {
                GD.Print($"TASK10_GEAR_LOWER_COOL_END energy={energy.EnergyRatio:R} heat={energy.HeatRatio:R} " +
                    $"overheated={energy.IsOverheated} shield={input.Current.ShieldHeld}/{shield.IsActive}/{energy.IsShieldSustained} " +
                    $"physics={Engine.GetPhysicsFrames()} elapsed_physics={Engine.GetPhysicsFrames()-recoveryPhysics} cap={recoveryCap}");
            }
            TestAssert.True(HasFloorContact(player, walkway), "post-combat cooling retains actual walkway support");
            SendAction(InputActions.MoveLeft, true);
            await Until(() => player.GlobalPosition.X <= 2488f, 180, "A walks to the original 40px return step");
            SendAction(InputActions.Jump, true);
            await Until(() => motor.AcceptedJumpCount == returnJumps + 1, 4, "first original Space is consumed");
            await Step(2); SendAction(InputActions.Jump, false);
            await Until(() => HasFloorContact(player, returnStep), 100, "single short jump lands on 40px return step");
            SendAction(InputActions.MoveLeft, false); await Step(4);
            TestAssert.True(float.IsFinite(motor.Tuning.GroundDeceleration) && motor.Tuning.GroundDeceleration > 0f,
                "return staging uses the actual finite ground braking setting");
            SendAction(InputActions.MoveLeft, true);
            await Until(() => FullFloor(returnStep) && player.GlobalPosition.X - 2402f <=
                Mathf.Pow(Mathf.Max(0f, -player.Velocity.X), 2f) / (2f * motor.Tuning.GroundDeceleration),
                30, "actual stance braking targets x2402 below ShieldLane and clears PistonOne's low ceiling");
            SendAction(InputActions.MoveLeft, false);
            await Until(() => Mathf.Abs(player.Velocity.X) <= 2f, 12, "settles on original step");
            TestAssert.True(FullFloor(returnStep) && player.GlobalPosition.X is >= 2399.75f and <= 2406f,
                "80px return jump starts fully supported below the lane, without repositioning");

            // Pre-arm below the lane; the first real pulse must be guarded before any left-aim interval.
            stage = "guarded-return-jump"; pulseStart = shieldLane.PulseCount;
            guardedPulses = 0; checkPulses = true;
            await FaceRightAndGuard();
            SendAction(InputActions.Jump, true);
            await Until(() => motor.AcceptedJumpCount == returnJumps + 2, 4, "second original Space is consumed once");
            await Until(() => shieldLane.PulseCount > pulseStart, 30, "first overlapping pulse is actually guarded");
            while (!FullFloor(gearEntry) || player.GlobalPosition.X > 2352f)
            {
                int pulse = shieldLane.PulseCount;
                ulong movedAt = Engine.GetPhysicsFrames();
                SendMouse(MouseButton.Right, false, player, Vector2.Zero);
                SendAction(InputActions.MoveLeft, true);
                for (int frame = 0; frame < 9 && Engine.GetPhysicsFrames() - movedAt < 9 &&
                     player.GlobalPosition.X > 2352f; frame++) await Step();
                await FaceRightAndGuard();
                await Until(() => shieldLane.PulseCount > pulse ||
                    FullFloor(gearEntry) && player.GlobalPosition.X <= 2352f, 20, "next real pulse or supported GearEntry");
            }
            SendAction(InputActions.Jump, false);
            await Until(() => !input.Current.JumpHeld, 4, "release is actually sampled before the next original jump");
            TestAssert.True(motor.AcceptedJumpCount == returnJumps + 2,
                "80px climb uses one held ordinary jump, no hidden re-jump");
            GD.Print($"TASK10_GEAR_LOWER_RETURN_ENTRY player={player.GlobalPosition} hp={hp} " +
                $"frames={returnJumpFrames} pulses={shieldLane.PulseCount-pulseStart} guards={guardedPulses}");
            // The proven original jump starts at rightward shield speed, not while
            // braking from the leftward landing. Keep D down through its new Space edge.
            float fullShieldSpeed = motor.Tuning.MaxRunSpeed * PlayerShieldSettings.Approved.MovementScale;
            int runupCap = 140 - returnJumpFrames;
            TestAssert.True(float.IsFinite(fullShieldSpeed) && fullShieldSpeed > 0f && runupCap > 0,
                "right-shield run-up uses current tuning and only the existing 140-frame stage remainder");
            Vector2 runupStart = player.GlobalPosition;
            float runupStartVx = player.Velocity.X;
            ulong runupPhysics = Engine.GetPhysicsFrames();
            runupJumps = motor.AcceptedJumpCount;
            bool runupReady = false;
            shieldRunup = true;
            try
            {
                Check();
                SendAction(InputActions.MoveLeft, false);
                SendAction(InputActions.MoveRight, true);
                SendMouse(MouseButton.Right, true, player, player.GlobalPosition + Vector2.Right * 240f);
                await Until(() => player.GlobalPosition.X is >= 2350f and <= 2354f &&
                    Mathf.Abs(player.Velocity.X - fullShieldSpeed) <= .1f &&
                    Mathf.Abs(motor.EffectiveMovementScale - PlayerShieldSettings.Approved.MovementScale) <= .001f &&
                    input.Current.MoveAxis >= .999f && input.KeyboardAimDirection.Dot(Vector2.Right) > .999f,
                    runupCap, "actual D/right-L reaches the proven running jump handoff before leaving its window");
                runupReady = true;
            }
            finally
            {
                shieldRunup = false;
                GD.Print($"TASK10_GEAR_LOWER_RUNUP ready={runupReady} x={runupStart.X:R}->{player.GlobalPosition.X:R} " +
                    $"vx={runupStartVx:R}->{player.Velocity.X:R} required_vx={fullShieldSpeed:R} " +
                    $"elapsed_physics={Engine.GetPhysicsFrames()-runupPhysics} stage_frames={returnJumpFrames}/140 " +
                    $"axis={input.Current.MoveAxis:R} shield={input.Current.ShieldHeld}/{shield.IsActive}/{shield.GuardDirection} hp={health.CurrentHealth}");
            }
            stage = "original-shield-jump";
            await ShieldJumpToSupport(tree, player, monitor, shieldLane, pistonOne);
            if (observedFailure != null) throw observedFailure;
            Check(); checkPulses = false;
            SendMouse(MouseButton.Right, false, player, player.GlobalPosition + Vector2.Right * 240f);
            stage = "original-lift-gallery-return";
            await BasinCounterweightRuntimeTests.TraverseForFullRoute(player, basin, count => Step(count));
            Check(); TestAssert.True(FullFloor(pistonTwo) && motor.AcceptedJumpCount == returnJumps + 3,
                "lower Bell round trip returns to full PistonTwo support via three original jumps and original lift/gallery");
            GD.Print($"TASK10_GEAR_LOWER_ROUNDTRIP_OK actor={bellId} defeats={defeats} hp={hp} " +
                $"player={player.GlobalPosition} return_jumps={motor.AcceptedJumpCount-returnJumps}");
        }
        finally
        {
            try
            {
                observer.Sample = null;
                if (GodotObject.IsInstanceValid(observer)) { observer.GetParent()?.RemoveChild(observer); observer.QueueFree(); }
                if (GodotObject.IsInstanceValid(health)) { health.Damaged -= onDamage; health.Healed -= onHeal; }
                if (GodotObject.IsInstanceValid(bell)) bell.Defeated -= onDefeat;
                if (GodotObject.IsInstanceValid(shield)) shield.ShieldResolved -= onGuard;
            }
            finally { driver.ReleaseAll(); }
        }
    }

    private static async Task ApproachTask10LiftEncounter(SceneTree tree,
        SeamlessPrologueWorld world, CharacterBody2D player, RouteMonitor monitor,
        Action observe, StaticBody2D entry, StaticBody2D publicShelf, StaticBody2D stepOne,
        StaticBody2D stepTwo, StaticBody2D landing)
    {
        const string encounterId = "canyon.v2.encounter.counterweight-lift";
        CanyonEncounterGroup group = world.FindChildren("*", "", true, false)
            .OfType<CanyonEncounterGroup>()
            .Single(encounter => encounter.EncounterId.ToString() == encounterId);
        Node actorRoot = group.GetNode(group.ActorRootPath);
        HealthComponent health = player.GetNode<HealthComponent>("Health");
        MechanicalClawController claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
        PlayerActionModeController modes = player.GetNode<PlayerActionModeController>("ActionModes");
        PlayerMotor liftMotor = player.GetNode<PlayerMotor>("Motor");
        int requests = monitor.RecoveryRequested;
        int recoveries = monitor.RecoveryCompleted;
        GraveLampMoth moth = null;
        ulong mothId = 0;
        string stage = "entry";
        string transferDetail = "none";
        string firstTraversalViolation = null;

        bool InTree(Node node) => GodotObject.IsInstanceValid(node) && node.IsInsideTree();

        float LureSupportMargin()
        {
            if (!InTree(player) || !InTree(landing)) return float.NaN;
            CollisionShape2D body = player.GetNodeOrNull<CollisionShape2D>("BodyCollider");
            CollisionShape2D shelf = landing.GetNodeOrNull<CollisionShape2D>("Collision");
            if (!InTree(body) || !InTree(shelf) || body.Disabled || shelf.Disabled ||
                body.Shape is not CapsuleShape2D capsule || !GodotObject.IsInstanceValid(capsule) ||
                shelf.Shape is not RectangleShape2D rectangle || !GodotObject.IsInstanceValid(rectangle))
                return float.NaN;
            Transform2D bodyTransform = body.GlobalTransform;
            Transform2D shelfTransform = shelf.GlobalTransform;
            // The real authored capsule and landing are axis-aligned. Reject changed geometry
            // instead of treating a rotated rectangle's enclosing box as physical support.
            bool AxisAligned(Transform2D transform) => transform.Origin.IsFinite() &&
                transform.X.IsFinite() && transform.Y.IsFinite() &&
                transform.X.Y == 0f && transform.Y.X == 0f &&
                transform.X.X != 0f && transform.Y.Y != 0f;
            if (!AxisAligned(bodyTransform) || !AxisAligned(shelfTransform) ||
                !float.IsFinite(capsule.Radius) || capsule.Radius <= 0f ||
                !rectangle.Size.IsFinite() || rectangle.Size.X <= 0f || rectangle.Size.Y <= 0f)
                return float.NaN;
            float radius = capsule.Radius * Mathf.Abs(bodyTransform.X.X);
            float halfWidth = rectangle.Size.X * Mathf.Abs(shelfTransform.X.X) / 2f;
            float leftMargin = bodyTransform.Origin.X - radius -
                (shelfTransform.Origin.X - halfWidth);
            float rightMargin = shelfTransform.Origin.X + halfWidth -
                (bodyTransform.Origin.X + radius);
            return Mathf.Min(leftMargin, rightMargin);
        }

        float LureDistance() => InTree(player) && InTree(moth)
            ? player.GlobalPosition.DistanceTo(moth.GlobalPosition) : float.NaN;

        float LureDetectionRange() => InTree(moth) && GodotObject.IsInstanceValid(moth.Tuning)
            ? moth.Tuning.DetectionRange : float.NaN;

        bool FullySupportedLure()
        {
            float margin = LureSupportMargin();
            return InTree(player) && player.GlobalPosition.IsFinite() && player.Velocity.IsFinite() &&
                float.IsFinite(margin) && margin >= 0f && HasFloorContact(player, landing);
        }

        bool StationaryLureInRange()
        {
            float distance = LureDistance();
            float range = LureDetectionRange();
            return FullySupportedLure() && Mathf.Abs(player.Velocity.X) <= 2f &&
                float.IsFinite(distance) && float.IsFinite(range) && range > 0f && distance <= range;
        }

        // Align proves the actor responded to detection, not that it is aligned for a strike.
        bool LureReady() => Live() && StationaryLureInRange() &&
            moth.CurrentState == GraveLampMothState.Align;

        string FloorSnapshot()
        {
            if (!InTree(player)) return "player-unavailable";
            if (!player.IsOnFloor()) return "airborne";
            for (int index = 0; index < player.GetSlideCollisionCount(); index++)
            {
                KinematicCollision2D contact = player.GetSlideCollision(index);
                if (!GodotObject.IsInstanceValid(contact) || contact.GetNormal().Y >= -.7f)
                    continue;
                return contact.GetCollider() is Node collider && InTree(collider)
                    ? $"{collider.GetPath()}#{collider.GetInstanceId()}"
                    : "floor-collider-unavailable";
            }
            return "floor_without_slide_collider";
        }

        string Snapshot()
        {
            bool playerAvailable = InTree(player);
            bool groupAvailable = InTree(group) && group.Definition != null;
            bool mothAvailable = InTree(moth);
            bool clawAvailable = InTree(claw);
            return $"stage={stage} physics={Engine.GetPhysicsFrames()} " +
                $"player={(playerAvailable ? player.GlobalPosition.ToString() : "unavailable")} " +
                $"velocity={(playerAvailable ? player.Velocity.ToString() : "unavailable")} " +
                $"floor={FloorSnapshot()} " +
                $"health={(InTree(health) ? health.CurrentHealth.ToString() : "unavailable")} " +
                $"recovery_requests={requests}->{monitor.RecoveryRequested} " +
                $"recovery_completions={recoveries}->{monitor.RecoveryCompleted} " +
                $"group={(groupAvailable ? $"active={group.IsActive}/batch={group.CurrentBatch}/live={group.LiveActorCount}" : "unavailable")} " +
                $"arena_inside={(playerAvailable && groupAvailable && group.Definition.ArenaBounds.HasPoint(player.GlobalPosition))} " +
                $"arena_bottom={(groupAvailable ? group.Definition.ArenaBounds.End.Y.ToString("R") : "unavailable")} " +
                $"bottom_clearance={(playerAvailable && groupAvailable ? (group.Definition.ArenaBounds.End.Y - player.GlobalPosition.Y).ToString("R") : "unavailable")} " +
                $"moth_id={mothId} moth_available={mothAvailable} " +
                $"moth_position={(mothAvailable ? moth.GlobalPosition.ToString() : "unavailable")} " +
                $"moth_state={(mothAvailable ? moth.CurrentState.ToString() : "unavailable")} " +
                $"claw={(clawAvailable ? $"cast={claw.CurrentFrame.CastId}/state={claw.CurrentFrame.State}/failure={claw.CurrentFrame.Failure}" : "unavailable")} " +
                $"target={(clawAvailable && InTree(claw.CurrentTarget) ? claw.CurrentTarget.GetPath().ToString() : "unavailable")} " +
                $"mode={(InTree(modes) ? modes.CurrentMode.ToString() : "unavailable")} " +
                $"transfer_detail={transferDetail}" +
                (stage == "Moth-lure-edge" ?
                    $" lure_distance={LureDistance():R} detection_range={LureDetectionRange():R}" +
                    $" support_margin={LureSupportMargin():R}" : "");
        }

        bool Live() => InTree(player) && InTree(health) && InTree(group) &&
            InTree(actorRoot) && group.Definition != null && health.CurrentHealth > 0 &&
            monitor.RecoveryRequested == requests && monitor.RecoveryCompleted == recoveries &&
            group.IsActive && group.CurrentBatch == 0 && !group.IsComplete &&
            group.Definition.ArenaBounds.HasPoint(player.GlobalPosition) &&
            InTree(moth) && moth.GetInstanceId() == mothId &&
            moth.GetNode<HealthComponent>("Health").CurrentHealth > 0 &&
            actorRoot.GetChildren().Contains(moth);

        void Check(string condition, bool passed)
        {
            TestAssert.True(passed, $"Task10 lift {condition}: {Snapshot()}" +
                (firstTraversalViolation == null ? "" :
                    $" first_traversal_violation=[{firstTraversalViolation}]"));
        }

        async Task Tick()
        {
            await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
            GuardTraversalFrame();
            observe();
            Check("same live Moth and arena every observed approach frame",
                firstTraversalViolation == null && Live());
            if (stage is "Moth-safe-shelf" or "Moth-real-claw" or "Moth-combat-handoff")
                Check("Moth staging/cast/handoff keeps full capsule on LiftBackLanding",
                    FullySupportedLure());
        }

        async Task WalkOn(StaticBody2D support, float x, int budget)
        {
            int direction = x > player.GlobalPosition.X ? 1 : -1;
            SendAction(InputActions.MoveLeft, direction < 0);
            SendAction(InputActions.MoveRight, direction > 0);
            try
            {
                for (int frame = 0; frame < budget &&
                     (x - player.GlobalPosition.X) * direction > 2f; frame++)
                {
                    await Tick();
                    Check("walk remains supported", HasFloorContact(player, support));
                }
            }
            finally
            {
                SendAction(InputActions.MoveLeft, false);
                SendAction(InputActions.MoveRight, false);
            }
            Check($"walk reaches x={x:0}", (x - player.GlobalPosition.X) * direction <= 2f &&
                HasFloorContact(player, support));
        }

        // Retain the exact combined monitor/evidence callback once per observed helper tick,
        // then fail immediately on a real boundary/actor violation. Do not continue stale input
        // until the shared helper's transfer budget expires after an encounter retirement.
        void GuardTraversalFrame()
        {
            if (firstTraversalViolation == null && !Live())
                firstTraversalViolation = Snapshot();
        }

        async Task Transfer(StaticBody2D support, bool clawRequired)
        {
            string supportName = support.Name.ToString();
            stage = $"transfer-{supportName}";
            firstTraversalViolation = null;
            void ObserveTransfer()
            {
                GuardTraversalFrame();
                observe();
                Check("every transfer tick preserved the encounter",
                    firstTraversalViolation == null && Live());
            }
            PrologueCanyonTraversalTests.BeginTask10InputDrive(tree, player, ObserveTransfer);
            try
            {
                Check("transfer starts with same live encounter", Live());
                await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player, support,
                    clawRequired);
            }
            catch (Exception error)
            {
                throw new InvalidOperationException(
                    $"Task10 lift transfer to {supportName} failed: {Snapshot()} " +
                    $"first_traversal_violation=[{firstTraversalViolation ?? "none"}] " +
                    $"cause={error.Message}", error);
            }
            finally
            {
                PrologueCanyonTraversalTests.BeginTask10InputDrive(tree, player, observe);
            }
            Check("every transfer tick preserved the encounter", firstTraversalViolation == null);
            Check("real arrival support and live encounter", Live() &&
                HasFloorContact(player, support));
            GD.Print($"TASK10_LIFT_SUPPORT_OK {Snapshot()} support={supportName} " +
                $"claw_required={clawRequired}");
        }

        try
        {
            Check("starts grounded on LiftEntryFloor without recovery",
                HasFloorContact(player, entry) && health.CurrentHealth > 0 &&
                monitor.RecoveryRequested == requests && monitor.RecoveryCompleted == recoveries);
            stage = "activation-walk";
            SendAction(InputActions.MoveRight, true);
            try
            {
                for (int frame = 0; frame < 45 && player.GlobalPosition.X < 3950f; frame++)
                {
                    await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
                    observe();
                    Check("activation walk stays on entry floor without recovery",
                        HasFloorContact(player, entry) && health.CurrentHealth > 0 &&
                        monitor.RecoveryRequested == requests &&
                        monitor.RecoveryCompleted == recoveries);
                    if (group.IsActive && moth == null)
                    {
                        moth = actorRoot.GetChildren().OfType<GraveLampMoth>()
                            .SingleOrDefault(actor => GodotObject.IsInstanceValid(actor));
                        if (moth != null) mothId = moth.GetInstanceId();
                    }
                    if (moth != null) Check("activation retains first live Moth", Live());
                }
            }
            finally { SendAction(InputActions.MoveRight, false); }
            Check("real x3950 activation has batch-zero Moth",
                player.GlobalPosition.X >= 3950f && Live() && HasFloorContact(player, entry));
            GD.Print($"TASK10_LIFT_ENTRY_OK {Snapshot()} activation={group.Definition.ActivationBounds}");

            // This is the authored public junction, not the locked shortcut shaft above it.
            // The shared helper uses its actual grip and LMB retract, never a Space boost.
            // Standing clearance from the exclusive arena bottom must be measured, not padded.
            transferDetail = "public-junction-grip-and-manual-release";
            await Transfer(publicShelf, clawRequired: true);
            stage = "public-junction-east-takeoff";
            await WalkOn(publicShelf, 4276f, 70);
            Check("public east takeoff remains on real shelf inside actual arena",
                Live() && HasFloorContact(player, publicShelf));
            GD.Print($"TASK10_LIFT_PUBLIC_EAST_TAKEOFF_OK {Snapshot()} support={publicShelf.Name}");
            transferDetail = "public-east-supported-jump";
            await Transfer(stepOne, clawRequired: false);
            await Transfer(stepTwo, clawRequired: false);
            await Transfer(landing, clawRequired: false);

            stage = "Moth-lure-edge";
            await WalkOn(landing, 4763f, 50);
            Check("lure braking starts with full capsule support", FullySupportedLure());
            var lureStop = FreeMotionForecast.Neutral(player.Velocity.X, true,
                liftMotor.MotionSettings, liftMotor.ThrusterState.Module,
                1d / Engine.PhysicsTicksPerSecond, 20, 2f);
            Vector2 lureStopPosition = player.GlobalPosition + Vector2.Right * lureStop.NetDistance;
            float lureStopMargin = LureSupportMargin() - Mathf.Abs(lureStop.NetDistance);
            bool coastToLure = KeyboardRouteInputDriver.Current != null && lureStop.SpeedThresholdReached &&
                lureStopMargin >= 0f && lureStopPosition.DistanceTo(moth.GlobalPosition) <= LureDetectionRange();
            GD.Print($"TASK10_LIFT_LURE_STOP_PLAN player={player.GlobalPosition} velocity={player.Velocity} " +
                $"predicted={lureStopPosition} margin={lureStopMargin:R} steps={lureStop.Steps}/20 " +
                $"distance={lureStopPosition.DistanceTo(moth.GlobalPosition):R} range={LureDetectionRange():R} " +
                $"coast={coastToLure} original_brake_settle_budget=12+8");
            // Preserve the old12+8 window. The new stronger reverse brake can
            // stop short of detection; use neutral only when its actual module
            // endpoint is both in range and fully inside the original shelf.
            SendAction(InputActions.MoveLeft, !coastToLure);
            try
            {
                for (int frame = 0; frame < 12 && player.Velocity.X > 20f; frame++)
                {
                    await Tick();
                    Check("braking remains on LiftBackLanding before its edge",
                        FullySupportedLure());
                }
            }
            finally { SendAction(InputActions.MoveLeft, false); }
            for (int frame = 0; frame < 8 && Mathf.Abs(player.Velocity.X) > 2f; frame++)
            {
                await Tick();
                Check("lure settles with full capsule support on the real landing", FullySupportedLure());
            }
            Check("stationary lure is inside Moth detection without leaving support",
                StationaryLureInRange());
            for (int frame = 0; frame < 180 && !LureReady(); frame++)
            {
                await Tick();
                Check("Moth lure wait remains stationary, fully supported and in actual range",
                    StationaryLureInRange());
            }
            Check("Moth responds in Align to supported in-range lure", LureReady());
            GD.Print($"TASK10_LIFT_LURE_OK {Snapshot()}");

            stage = "Moth-safe-shelf";
            // Stop east of the real Grip (right edge 4716), leaving braking room on the
            // same 4600..4800 landing. The actual pose and live LOS still decide admission.
            await WalkOn(landing, 4758f, 50);
            ThreadTarget2D target = moth.GetNode<ThreadTarget2D>("ThreadTarget");
            float GripRightEdge()
            {
                StaticBody2D grip = InTree(landing)
                    ? landing.GetParent()?.GetNodeOrNull<StaticBody2D>("LiftBackLandingGrip")
                    : null;
                CollisionShape2D shape = InTree(grip)
                    ? grip.GetNodeOrNull<CollisionShape2D>("Collision") : null;
                if (!InTree(shape) || shape.Disabled ||
                    shape.Shape is not RectangleShape2D rectangle ||
                    !GodotObject.IsInstanceValid(rectangle)) return float.NaN;
                Transform2D transform = shape.GlobalTransform;
                if (!transform.Origin.IsFinite() || !transform.X.IsFinite() ||
                    !transform.Y.IsFinite() || transform.X.Y != 0f || transform.Y.X != 0f ||
                    transform.X.X == 0f || transform.Y.Y == 0f ||
                    !rectangle.Size.IsFinite() || rectangle.Size.X <= 0f)
                    return float.NaN;
                return transform.Origin.X + rectangle.Size.X * Mathf.Abs(transform.X.X) / 2f;
            }
            bool EastOfGrip()
            {
                float right = GripRightEdge();
                return float.IsFinite(right) && InTree(player) && InTree(target) &&
                    player.GlobalPosition.X > right && target.WorldAnchor.X > right;
            }
            Check("Moth staging starts fully supported east of the real Grip",
                FullySupportedLure() && EastOfGrip());
            MechanicalClawTargetResolution resolution = MechanicalClawTargetResolution.None;
            bool finalAimAdmissionProbe = false;
            bool firstResolverRejectionCaptured = false;

            // Diagnostic only: match the resolver's cast-admission LOS query, including the
            // complete caster-subtree exclusion set. Never use the presentation occlusion ray.
            string AdmissionRay(Vector2 anchor)
            {
                if (!InTree(player) || !InTree(target) || !anchor.IsFinite())
                    return "ray=unavailable (caster/target/anchor invalid or off-tree)";
                Vector2 origin = player.GlobalPosition;
                if (origin.IsEqualApprox(anchor)) return "ray=not-needed (origin~=anchor)";
                var excluded = new Godot.Collections.Array<Rid>();
                void AddCasterRids(Node node)
                {
                    if (!GodotObject.IsInstanceValid(node)) return;
                    if (node is CollisionObject2D body) excluded.Add(body.GetRid());
                    foreach (Node child in node.GetChildren()) AddCasterRids(child);
                }
                AddCasterRids(player);
                PhysicsRayQueryParameters2D query = PhysicsRayQueryParameters2D.Create(origin, anchor);
                query.CollideWithAreas = true;
                query.CollideWithBodies = true;
                query.HitFromInside = false;
                query.CollisionMask = CombatCollisionLayers.World | CombatCollisionLayers.Enemy |
                    CombatCollisionLayers.ThreadTarget;
                query.Exclude = excluded;
                Godot.Collections.Dictionary hit = player.GetWorld2D().DirectSpaceState.IntersectRay(query);
                if (hit.Count == 0) return $"ray=clear origin={origin} anchor={anchor}";
                Node collider = hit.ContainsKey("collider")
                    ? hit["collider"].AsGodotObject() as Node : null;
                bool colliderAvailable = InTree(collider);
                string colliderIdentity = colliderAvailable
                    ? $"{collider.GetPath()}#{collider.GetInstanceId()}" : "unavailable";
                string point = hit.ContainsKey("position")
                    ? hit["position"].AsVector2().ToString() : "unavailable";
                string normal = hit.ContainsKey("normal")
                    ? hit["normal"].AsVector2().ToString() : "unavailable";
                string belongs = colliderAvailable
                    ? MechanicalClawTargetResolver.ColliderBelongsToSurface(collider, target).ToString()
                    : "unavailable";
                return $"ray=hit origin={origin} anchor={anchor} collider={colliderIdentity} " +
                    $"point={point} normal={normal} belongs_to_target={belongs}";
            }

            void RecordAimRejection(string gate, bool resolverEvaluated, Vector2 anchor)
            {
                bool firstResolver = resolverEvaluated && !firstResolverRejectionCaptured;
                if (!firstResolver && !finalAimAdmissionProbe) return;
                if (firstResolver) firstResolverRejectionCaptured = true;
                bool playerAvailable = InTree(player);
                bool mothAvailable = InTree(moth);
                bool targetAvailable = InTree(target);
                Viewport viewport = playerAvailable ? player.GetViewport() : null;
                bool viewportAvailable = GodotObject.IsInstanceValid(viewport);
                Camera2D activeCamera = viewportAvailable ? viewport.GetCamera2D() : null;
                Camera2D playerCamera = playerAvailable
                    ? player.GetNodeOrNull<Camera2D>("Camera2D") : null;
                bool activeCameraAvailable = InTree(activeCamera);
                string CameraIdentity(Camera2D camera)
                {
                    if (camera is null) return "none";
                    if (!GodotObject.IsInstanceValid(camera)) return "invalid";
                    bool inTree = camera.IsInsideTree();
                    if (!inTree) return "off-tree/valid=True";
                    return $"{camera.GetPath()}#{camera.GetInstanceId()}" +
                        $"/valid=True/in_tree=True/enabled={camera.Enabled}" +
                        $"/current={activeCameraAvailable &&
                            camera.GetInstanceId() == activeCamera.GetInstanceId()}";
                }
                bool selectedAvailable = resolverEvaluated && InTree(resolution.Surface);
                string selected = selectedAvailable
                    ? $"{resolution.Surface.GetPath()}#{resolution.Surface.GetInstanceId()}"
                    : resolverEvaluated ? "none/unavailable" : "not-resolved";
                string viewportPoint = viewportAvailable && targetAvailable
                    ? ToViewport(player, anchor).ToString() : "unavailable";
                string playerViewportPoint = viewportAvailable
                    ? ToViewport(player, player.GlobalPosition).ToString() : "unavailable";
                string mouseFormulaPoint = viewportAvailable && targetAvailable
                    ? (viewport.GetFinalTransform() *
                        (player.GetGlobalTransformWithCanvas() * player.ToLocal(anchor))).ToString()
                    : "unavailable";
                string visibleRect = viewportAvailable
                    ? viewport.GetVisibleRect().ToString() : "unavailable";
                string aimableRect = viewportAvailable
                    ? viewport.GetVisibleRect().Grow(-32f).ToString() : "unavailable";
                string visible = viewportAvailable && targetAvailable
                    ? IsTargetVisible(player, anchor).ToString() : "unavailable";
                string canvasTransform = viewportAvailable
                    ? viewport.GetCanvasTransform().ToString() : "unavailable";
                string finalTransform = viewportAvailable
                    ? viewport.GetFinalTransform().ToString() : "unavailable";
                string windowSize = viewport is Window window ? window.Size.ToString() : "not-window";
                string contentScaleSize = viewport is Window scaledWindow
                    ? scaledWindow.ContentScaleSize.ToString() : "not-window";
                string activeCameraIdentity = CameraIdentity(activeCamera);
                string playerCameraIdentity = CameraIdentity(playerCamera);
                string activeCameraPose = activeCameraAvailable
                    ? $"screen_center={activeCamera.GetScreenCenterPosition()}/global={activeCamera.GlobalPosition}" +
                        $"/local={activeCamera.Position}/offset={activeCamera.Offset}/zoom={activeCamera.Zoom}"
                    : "unavailable";
                string playerPose = playerAvailable
                    ? $"{player.GlobalPosition} velocity={player.Velocity}" : "unavailable";
                string mothPose = mothAvailable
                    ? $"{moth.GlobalPosition} state={moth.CurrentState}" : "unavailable";
                string distance = playerAvailable && targetAvailable
                    ? player.GlobalPosition.DistanceTo(anchor).ToString("R") : "unavailable";
                string horizontal = playerAvailable && mothAvailable
                    ? Mathf.Abs(moth.GlobalPosition.X - player.GlobalPosition.X).ToString("R")
                    : "unavailable";
                string vertical = playerAvailable && mothAvailable
                    ? (moth.GlobalPosition.Y - player.GlobalPosition.Y).ToString("R")
                    : "unavailable";
                string ray = AdmissionRay(anchor);
                string detail = $"stage={stage} physics={Engine.GetPhysicsFrames()} gate={gate} " +
                    $"target_in_tree={targetAvailable} target_anchor={anchor} " +
                    $"target_logical_viewport_point={viewportPoint} " +
                    $"player_logical_viewport_point={playerViewportPoint} " +
                    $"target_window_event_point={mouseFormulaPoint} " +
                    $"logical_visible_rect={visibleRect} logical_aimable_rect={aimableRect} " +
                    $"is_target_visible={visible} " +
                    $"canvas_transform={canvasTransform} final_transform={finalTransform} " +
                    $"window_size={windowSize} content_scale_size={contentScaleSize} " +
                    $"active_camera={activeCameraIdentity} player_camera={playerCameraIdentity} " +
                    $"active_camera_pose={activeCameraPose} " +
                    $"player={playerPose} moth={mothPose} distance={distance} " +
                    $"max_range={MechanicalClawSettings.Default.MaxRange:R} " +
                    $"horizontal_gap={horizontal} horizontal_limit=100 " +
                    $"moth_minus_player_y={vertical} vertical_limit=-250 " +
                    $"grip_right_edge={GripRightEdge():R} east_of_grip={EastOfGrip()} " +
                    $"selected_surface={selected} " +
                    $"snapshot={(resolverEvaluated ? $"runtime_id={resolution.Snapshot.RuntimeId}/exists={resolution.Snapshot.Exists}/anchor={resolution.Snapshot.WorldAnchor}/los={resolution.Snapshot.HasLineOfSight}/cursor_distance={resolution.CursorDistance:R}" : "not-resolved")} " +
                    $"{ray} original=[{Snapshot()}]";
                if (firstResolver) GD.Print($"TASK10_MOTH_ADMISSION_FIRST_RESOLVER_REJECTION {detail}");
                if (finalAimAdmissionProbe) GD.Print($"TASK10_MOTH_ADMISSION_FINAL_FAILURE {detail}");
            }

            bool Aimable()
            {
                if (!GodotObject.IsInstanceValid(target))
                {
                    RecordAimRejection("target-invalid", false, Vector2.Zero);
                    return false;
                }
                Vector2 aim = target.WorldAnchor;
                if (!IsTargetVisible(player, aim) ||
                    player.GlobalPosition.DistanceTo(aim) > MechanicalClawSettings.Default.MaxRange ||
                    Mathf.Abs(moth.GlobalPosition.X - player.GlobalPosition.X) > 100f ||
                    moth.GlobalPosition.Y < player.GlobalPosition.Y - 250f ||
                    !EastOfGrip())
                {
                    if (finalAimAdmissionProbe)
                    {
                        string gate = !target.IsInsideTree() ? "target-off-tree" :
                            !IsTargetVisible(player, aim) ? "outside-aimable-inset" :
                            player.GlobalPosition.DistanceTo(aim) > MechanicalClawSettings.Default.MaxRange
                                ? "beyond-max-range" :
                            Mathf.Abs(moth.GlobalPosition.X - player.GlobalPosition.X) > 100f
                                ? "horizontal-proximity" :
                            moth.GlobalPosition.Y < player.GlobalPosition.Y - 250f
                                ? "vertical-proximity" : "not-east-of-grip";
                        RecordAimRejection(gate, false, aim);
                    }
                    return false;
                }
                resolution = KeyboardRouteInputDriver.Current != null
                    ? new MechanicalClawTargetResolver().ResolveKeyboard(player,
                        player.GetNode<PlayerInputReader>("Input").KeyboardAimDirection)
                    : new MechanicalClawTargetResolver().Resolve(player, aim);
                bool admitted = resolution.Surface == target && resolution.Snapshot.HasLineOfSight;
                if (!admitted)
                    RecordAimRejection(!target.IsInsideTree() ? "target-off-tree" :
                        resolution.Surface == target ? "los-failure" :
                        "selected-surface-mismatch", true, aim);
                return admitted;
            }
            if(KeyboardRouteInputDriver.Current!=null)
            {
                // Let the approaching enemy become the actual visible W candidate;
                // a valid legacy pointer target alone does not admit a keyboard K.
                SendAction(InputActions.MoveUp,true);
                await Tick();
            }
            for (int frame = 0; frame < 180 && !Aimable(); frame++)
            {
                await Tick();
                Check("Moth staging keeps full capsule on real landing", FullySupportedLure());
            }
            finalAimAdmissionProbe = true;
            Check("Moth is onscreen, in range, and actually resolves", Aimable() &&
                FullySupportedLure());
            finalAimAdmissionProbe = false;

            stage = "Moth-real-claw";
            LegacyThreadInteractionAdapter adapter = target.GetNode<LegacyThreadInteractionAdapter>(
                "LegacyThreadInteractionAdapter");
            int applications = adapter.ApplicationCount;
            ulong castId = 0;
            void ObserveClaw(MechanicalClawFrame frame, GrappleSurface2D observed)
            {
                if (frame.State == MechanicalClawState.Latched && observed == target)
                    castId = frame.CastId;
            }
            claw.ClawFrameChanged += ObserveClaw;
            try
            {
                MoveMouse(player, target.WorldAnchor);
                SendAction(InputActions.SelectGrappleMode, true);
                for (int frame = 0; frame < 6 && !modes.CanBeginGrapple; frame++)
                    await Tick();
                SendAction(InputActions.SelectGrappleMode, false);
                Check("selected real grapple mode on landing", modes.CanBeginGrapple &&
                    claw.CurrentFrame.State == MechanicalClawState.Idle &&
                    FullySupportedLure());
                Check("moving Moth still resolves at the actual input edge",
                    EastOfGrip() && Aimable() && FullySupportedLure());
                Viewport inputViewport = player.GetViewport();
                Vector2 inputPlayerWorld = player.GlobalPosition;
                Vector2 inputTargetWorld = target.WorldAnchor;
                Rect2 inputVisibleRect = inputViewport.GetVisibleRect();
                Transform2D inputCanvas = inputViewport.GetCanvasTransform();
                Transform2D inputFinal = inputViewport.GetFinalTransform();
                Vector2 inputPlayerLogical = inputCanvas * inputPlayerWorld;
                Vector2 inputTargetLogical = inputCanvas * inputTargetWorld;
                Vector2 inputTargetWindow = inputFinal *
                    (player.GetGlobalTransformWithCanvas() * player.ToLocal(inputTargetWorld));
                string inputSurface = InTree(resolution.Surface)
                    ? $"{resolution.Surface.GetPath()}#{resolution.Surface.GetInstanceId()}"
                    : "unavailable";
                GD.Print($"TASK10_MOTH_ADMISSION_INPUT_EDGE_OK stage={stage} " +
                    $"physics={Engine.GetPhysicsFrames()} player_world={inputPlayerWorld} " +
                    $"target_world={inputTargetWorld} player_logical={inputPlayerLogical} " +
                    $"target_logical={inputTargetLogical} logical_visible_rect={inputVisibleRect} " +
                    $"logical_aimable_rect={inputVisibleRect.Grow(-32f)} " +
                    $"canvas_transform={inputCanvas} final_transform={inputFinal} " +
                    $"target_window_event_point={inputTargetWindow} " +
                    $"selected_surface={inputSurface} snapshot_los={resolution.Snapshot.HasLineOfSight}");
                SendMouse(MouseButton.Left, true, player, target.WorldAnchor);
                for (int frame = 0; frame < 6 &&
                     claw.CurrentFrame.State == MechanicalClawState.Idle; frame++)
                    await Tick();
                Check("Moth LMB press entered a real claw cast",
                    (claw.CurrentFrame.State is MechanicalClawState.Aim or
                        MechanicalClawState.Windup or MechanicalClawState.Travel) &&
                    FullySupportedLure());
                SendMouse(MouseButton.Left, false, player, target.WorldAnchor);
                for (int frame = 0; frame < 50 && adapter.ApplicationCount == applications;
                     frame++)
                {
                    if (GodotObject.IsInstanceValid(target)) MoveMouse(player, target.WorldAnchor);
                    await Tick();
                }
            }
            finally
            {
                claw.ClawFrameChanged -= ObserveClaw;
                SendAction(InputActions.SelectGrappleMode, false);
                SendMouse(MouseButton.Left, false, player, player.GlobalPosition);
            }
            Check("real Moth claw flight applied to observed target",
                castId != 0 && adapter.ApplicationCount == applications + 1 &&
                FullySupportedLure());
            GD.Print($"TASK10_LIFT_CLAW_OK {Snapshot()} target={target.GetInstanceId()} " +
                $"cast={castId} applications={applications}->{adapter.ApplicationCount} " +
                $"resolver_surface={resolution.Surface?.GetInstanceId() ?? 0}");

            stage = "Moth-combat-handoff";
            bool SafeHandoff()
            {
                float dx = moth.GlobalPosition.X - player.GlobalPosition.X;
                float dy = moth.GlobalPosition.Y - player.GlobalPosition.Y;
                bool verticalStrike = dy is >= -74f and <= -10f && Mathf.Abs(dx) <= 36f;
                bool horizontalStrike = Mathf.Abs(dy) <= 32f &&
                    Mathf.Abs(dx) is >= 8f and <= 64f;
                return FullySupportedLure() &&
                    moth.GlobalPosition.X is >= 4620f and <= 4780f &&
                    (verticalStrike || horizontalStrike);
            }
            for (int frame = 0; frame < 75 && !SafeHandoff(); frame++)
            {
                await Tick();
                Check("Moth handoff wait keeps supported player", HasFloorContact(player, landing));
            }
            Check("Moth is on safe shelf in existing combat strike geometry",
                Live() && SafeHandoff());
            GD.Print($"TASK10_LIFT_COMBAT_HANDOFF_OK {Snapshot()}");
        }
        finally
        {
            SendAction(InputActions.MoveLeft, false);
            SendAction(InputActions.MoveRight, false);
            SendAction(InputActions.Jump, false);
            SendAction(InputActions.SelectGrappleMode, false);
            SendMouse(MouseButton.Left, false, player, player.GlobalPosition);
            SendMouse(MouseButton.Right, false, player, player.GlobalPosition);
            if(KeyboardRouteInputDriver.Current!=null) SendAction(InputActions.MoveUp,false);
        }
    }

    internal static bool Task10EnemyThreat(Node2D actor, bool skitterThreat,
        List<AttackTelegraphVisual> leaves)
    {
        leaves.Clear();
        if (actor is RangedWeaponEnemy ranged)
        {
            if (!GodotObject.IsInstanceValid(ranged) || ranged.IsQueuedForDeletion() ||
                !ranged.IsInsideTree() || ranged.GetTree().Paused || !ranged.HasPresentationAuthority)
                return skitterThreat;
            ranged.AppendAuthorizedAttackLeaves(leaves);
            bool authorizedThreat = false;
            foreach (AttackTelegraphVisual leaf in leaves)
            {
                if (GodotObject.IsInstanceValid(leaf) && leaf.IsInsideTree() && !leaf.IsQueuedForDeletion() &&
                    leaf.CurrentFrame.Timeline.Phase is AttackPhase.Telegraph or AttackPhase.Active)
                    authorizedThreat = true;
            }
            leaves.Clear(); // Do not retain actor-owned native wrappers between policy samples.
            return authorizedThreat || skitterThreat;
        }
        bool threat = actor switch
        {
            RustShellSquire rust => rust.CurrentState is RustShellState.Telegraph or RustShellState.Attack,
            BellBackLaborer bell => bell.CurrentState is BellBackLaborerState.Telegraph or BellBackLaborerState.Attack,
            GraveLampMoth moth => moth.CurrentState is GraveLampMothState.Telegraph or GraveLampMothState.Dive,
            _ => false
        };
        return threat || skitterThreat;
    }

    internal static bool Task10GeneralDefendWindow(PlayerCombat combat, PlayerEnergyController energy,
        bool enemyThreat, bool strikeRange, int frame, int nextAttackFrame) =>
        !combat.IsAttacking && energy.EnergyRatio > .35f &&
        (enemyThreat || (strikeRange ? frame < nextAttackFrame : frame % 120 < 24));

    // The saved-scene HIGH and LOW beam counterexamples require the same late
    // warning window and native guard availability as the mixed encounter policy.
    internal static bool Task10GalleryLaserDefendWindow(PlayerCombat combat, PlayerEnergyController energy,
        PlayerShieldController shield, Task10EncounterDanger danger, bool strikeRange,
        int frame, int nextAttackFrame) =>
        !combat.IsAttacking && Task10MixedDefendWindow(shield, danger);

    internal readonly record struct Task10SteamMissileDecision(bool Defend, bool AllowShieldApproach, bool CanCounter);

    internal static Task10SteamMissileDecision Task10SteamMissileKeyboardDecision(CharacterBody2D player,
        RangedWeaponEnemy actor, PlayerCombat combat, PlayerEnergyController energy, PlayerShieldController shield,
        Task10EncounterDanger danger, bool strikeRange, int frame, int nextAttackFrame,
        List<AttackTelegraphVisual> leaves)
    {
        bool Live(Node node) => GodotObject.IsInstanceValid(node) && node.IsInsideTree() &&
            !node.IsQueuedForDeletion();
        // The post-L sample can cross actor retirement. Never read native owner
        // state before checking it, and never authorize a counter from a dead owner.
        if (!Live(player) || !Live(actor) || !Live(combat) || !Live(energy) || !Live(shield) ||
            actor is not FurnaceMissileGunner || actor.SceneFilePath != CanyonEncounterCatalog.MissileScene ||
            actor.GetNodeOrNull<HealthComponent>("Health")?.CurrentHealth is not > 0)
            return default;
        bool defend = !combat.IsAttacking && Task10MixedDefendWindow(shield, danger);
        bool counter = Task10MixedCounterWindow(combat, energy, danger);
        Vector2 delta = actor.GlobalPosition - player.GlobalPosition;
        if (!defend || strikeRange || !delta.IsFinite() || MathF.Abs(delta.X) <= 64f ||
            MathF.Abs(delta.Y) > 46f || danger.SourceActorId != actor.GetInstanceId() || !player.IsOnFloor())
            return new(defend, false, counter);

        bool supported = false;
        for (int index = 0; index < player.GetSlideCollisionCount(); index++)
        {
            using KinematicCollision2D contact = player.GetSlideCollision(index);
            if (contact.GetNormal().Y >= -.7f || contact.GetCollider() is not StaticBody2D floor ||
                !Live(floor) || floor.ShapeOwnerGetOwner(floor.ShapeFindOwner(contact.GetColliderShapeIndex()))
                    is not CollisionShape2D shape || !Live(shape) ||
                !TryTask10CapsuleCorridor(player, shape, out _, out _, out _, out _)) continue;
            supported = true;
            break;
        }
        if (!supported) return new(defend, false, counter);

        float side = MathF.Sign(delta.X);
        bool AheadHorizontal(Vector2 source)
        {
            Vector2 fromPlayer = source - player.GlobalPosition;
            // L uses the same eight-way WASD aim as movement. Only the horizontal
            // octant toward this actor is an approach, never a back/diagonal aim.
            return fromPlayer.IsFinite() && fromPlayer.X * side > 0f &&
                MathF.Abs(fromPlayer.Y) < MathF.Abs(fromPlayer.X) * .414f;
        }
        if (!AheadHorizontal(danger.GuardSource)) return new(defend, false, counter);
        leaves.Clear();
        try
        {
            actor.AppendAuthorizedAttackLeaves(leaves);
            if (leaves.Count == 0) return new(defend, false, counter);
            foreach (AttackTelegraphVisual leaf in leaves)
            {
                if (!Live(leaf) || leaf.CurrentFrame.Timeline.Kind != EnemyAttackKind.FurnaceMissileShot ||
                    leaf.CurrentFrame.Timeline.Phase is not (AttackPhase.Telegraph or AttackPhase.Active))
                    return new(defend, false, counter);
                Node2D origin = leaf.GetParent() is RangedWeaponProjectile projectile
                    ? projectile : actor.GetNodeOrNull<Node2D>("Muzzle");
                if (!Live(origin) || !AheadHorizontal(origin.GlobalPosition)) return new(defend, false, counter);
            }
            return new(defend, true, counter);
        }
        finally { leaves.Clear(); } // Borrowed actor leaves never outlive this policy sample.
    }

    internal static bool Task10MixedDefendWindow(PlayerShieldController shield, Task10EncounterDanger danger) =>
        // This is guard demand, not the complete-counter window. Active
        // includes authorized inter-shot gaps/live tails; their lifetime is NOT ETA.
        shield.CanBeginGuard && danger.Threat &&
        (danger.Phase == AttackPhase.Active ||
         danger.Phase == AttackPhase.Telegraph &&
         danger.RemainingSeconds <= 8f / Engine.PhysicsTicksPerSecond);

    internal static bool Task10MixedCounterWindow(PlayerCombat combat, PlayerEnergyController energy,
        Task10EncounterDanger danger)
    {
        // Current saved tuning is not mutated by this consumer. Keep a complete
        // attack plus input/re-guard margin, not merely an instantaneous clear leaf.
        float fullAttack = combat.Tuning.AttackStartupSeconds + combat.Tuning.AttackActiveSeconds +
            combat.Tuning.AttackRecoverySeconds;
        // Actor clocks can still describe the previous node tick at PhysicsFrame;
        // J is consumed on a later input/combat tick. Native .41666663 warning
        // crossed Active before the sixth post-completion tick. Reserve those
        // two discrete sample/command ticks separately from the six actual margin ticks.
        float sampleAndCommandLead = 2f / Engine.PhysicsTicksPerSecond;
        return !combat.IsAttacking && float.IsFinite(fullAttack) && fullAttack > 0f &&
            danger.SafeCounterSeconds >= fullAttack + 6f / Engine.PhysicsTicksPerSecond + sampleAndCommandLead &&
            energy.EnergyRatio * energy.Tuning.MaxEnergy >= 2f * energy.Tuning.AttackCost;
    }

    internal readonly record struct Task10EncounterDanger(bool Threat, Vector2 GuardSource, bool HasRanged)
    {
        public ulong SourceActorId { get; init; }
        public ulong AttackId { get; init; }
        public AttackPhase Phase { get; init; }
        public float RemainingSeconds { get; init; }
        public bool FromActiveGap { get; init; }
        public float SafeCounterSeconds { get; init; }
    }

    internal static Task10EncounterDanger Task10ObserveEncounterDanger(Node actorRoot, string encounterId,
        Node2D selected, bool skitterThreat, List<AttackTelegraphVisual> leaves)
    {
        leaves.Clear();
        if (!GodotObject.IsInstanceValid(actorRoot) || !actorRoot.IsInsideTree() || actorRoot.GetTree().Paused)
            return default;
        for (Node ancestor = actorRoot; ancestor != null; ancestor = ancestor.GetParent())
            if (ancestor.IsQueuedForDeletion()) return default;
        string prefix = encounterId.Replace('.', '_');
        bool threat = false, hasRanged = false;
        float earliest = float.PositiveInfinity;
        Vector2 guardSource = Vector2.Zero;
        ulong winningActorId = 0, winningAttackId = 0;
        AttackPhase winningPhase = AttackPhase.None;
        float winningRemaining = 0f;
        bool winningGap = false;
        float safeCounter = float.PositiveInfinity;
        int counterSources = 0;
        void ConsiderCounter(AttackTimelineFrame timeline)
        {
            counterSources++;
            safeCounter = MathF.Min(safeCounter,
                timeline.Phase is AttackPhase.Recovery or AttackPhase.Telegraph && float.IsFinite(timeline.PhaseRemainingSeconds)
                    ? MathF.Max(0f, timeline.PhaseRemainingSeconds) : 0f);
        }
        void Consider(AttackTimelineFrame timeline, Vector2 source, ulong actorId, bool activeGap = false)
        {
            if (!float.IsFinite(source.X) || !float.IsFinite(source.Y)) return;
            // An already live attack precedes a merely warned one. A warning's
            // own remaining time, not child/selected order, resolves that priority.
            float urgency = timeline.Phase == AttackPhase.Telegraph
                ? MathF.Max(0f, timeline.PhaseRemainingSeconds) : 0f;
            threat = true;
            if (urgency < earliest)
            {
                earliest = urgency; guardSource = source;
                winningActorId = actorId; winningAttackId = timeline.AttackId;
                winningPhase = timeline.Phase; winningRemaining = timeline.PhaseRemainingSeconds;
                winningGap = activeGap;
            }
        }
        // This newly returned array is ours; its Nodes and their resources are borrowed.
        Godot.Collections.Array<Node> children = actorRoot.GetChildren();
        using Godot.Collections.Array childrenBacking = (Godot.Collections.Array)children;
        foreach (Node child in children)
        {
            if (child is not Node2D source || !GodotObject.IsInstanceValid(source) ||
                !source.IsInsideTree() || source.IsQueuedForDeletion() || source.GetParent() != actorRoot ||
                !source.Name.ToString().StartsWith(prefix, StringComparison.Ordinal) ||
                source.GetNodeOrNull<HealthComponent>("Health")?.CurrentHealth is not > 0) continue;
            if (source is RangedWeaponEnemy ranged)
            {
                hasRanged = true;
                ConsiderCounter(ranged.HasPresentationAuthority ? ranged.CurrentFrame.AttackTimeline : default);
                if (!ranged.HasPresentationAuthority) continue;
                try
                {
                    ranged.AppendAuthorizedAttackLeaves(leaves);
                    foreach (AttackTelegraphVisual leaf in leaves)
                    {
                        if (!GodotObject.IsInstanceValid(leaf) || !leaf.IsInsideTree() || leaf.IsQueuedForDeletion() ||
                            leaf.CurrentFrame.Timeline.Phase is not (AttackPhase.Telegraph or AttackPhase.Active)) continue;
                        // Only this actor's current warning owns its known next-Active clock.
                        // Live projectiles (including Recovery tails), Active leaves and
                        // unrecognized owners cannot borrow that future counter allowance.
                        bool actorWarning = leaf == ranged.GetNodeOrNull<AttackTelegraphVisual>("VisualRoot/AttackTelegraph") &&
                            leaf.CurrentFrame.Timeline.Phase == AttackPhase.Telegraph &&
                            ranged.CurrentFrame.AttackTimeline.Phase == AttackPhase.Telegraph &&
                            leaf.CurrentFrame.Timeline.AttackId == ranged.CurrentFrame.AttackTimeline.AttackId;
                        if (!actorWarning) safeCounter = 0f;
                        Node2D origin = leaf.GetParent() is RangedWeaponProjectile projectile
                            ? projectile : ranged.GetNodeOrNull<Node2D>("Muzzle");
                        Consider(leaf.CurrentFrame.Timeline,
                            GodotObject.IsInstanceValid(origin) ? origin.GlobalPosition : ranged.GlobalPosition,
                            ranged.GetInstanceId());
                    }
                    // Retired rounds can leave no current geometric leaf while
                    // this authorized actor still owns the same Active burst.
                    // That gap is not a counter window before the next round.
                    if (leaves.Count == 0 && ranged.CurrentFrame.AttackTimeline.Phase == AttackPhase.Active)
                    {
                        Node2D muzzle = ranged.GetNodeOrNull<Node2D>("Muzzle");
                        Consider(ranged.CurrentFrame.AttackTimeline,
                            GodotObject.IsInstanceValid(muzzle) ? muzzle.GlobalPosition : ranged.GlobalPosition,
                            ranged.GetInstanceId(), activeGap: true);
                    }
                }
                finally { leaves.Clear(); } // Never retain owned leaf wrappers across samples.
                continue;
            }
            AttackTimelineFrame melee = source switch
            {
                RustShellSquire rust => rust.CurrentFrame.AttackTimeline,
                BellBackLaborer bell => bell.CurrentFrame.AttackTimeline,
                GraveLampMoth moth => moth.CurrentFrame.AttackTimeline,
                CanyonSkitter skitter => skitter.CurrentFrame.AttackTimeline,
                _ => default
            };
            ConsiderCounter(melee); // Unknown/Idle/None is not an infinite safe window.
            if (!Task10EnemyThreat(source, source == selected && skitterThreat, leaves)) continue;
            Node2D hitbox = source.GetNodeOrNull<Hitbox>("AttackHitbox");
            Consider(melee, GodotObject.IsInstanceValid(hitbox) ? hitbox.GlobalPosition : source.GlobalPosition,
                source.GetInstanceId());
        }
        return new Task10EncounterDanger(threat, guardSource, hasRanged)
        {
            SourceActorId = winningActorId, AttackId = winningAttackId,
            Phase = winningPhase, RemainingSeconds = winningRemaining, FromActiveGap = winningGap,
            SafeCounterSeconds = counterSources > 0 ? safeCounter : 0f
        };
    }

    private static async Task DefeatTask10Encounter(SceneTree tree,
        PrologueLevelController level, SeamlessPrologueWorld world, CharacterBody2D player,
        RouteMonitor monitor, string encounterId, bool headlessNormalPlan = false)
    {
        CanyonEncounterGroup group = world.FindChildren("*", "", true, false)
            .OfType<CanyonEncounterGroup>()
            .Single(encounter => encounter.EncounterId.ToString() == encounterId);
        for (int frame = 0; frame < 12 && !group.IsActive; frame++)
            await PhysicsFrames(tree, monitor, 1);
        TestAssert.True(group.IsActive,
            $"Task10 movement activates {encounterId}; player={player.GlobalPosition} " +
            $"batch={group.CurrentBatch} live={group.LiveActorCount}");

        Node actorRoot = group.GetNode(group.ActorRootPath);
        var rangedThreatLeaves = new List<AttackTelegraphVisual>(8);
        int attacks = 0;
        int attacksStarted = 0;
        int attacksConnected = 0;
        int threadCasts = 0;
        int nextAttackFrame = 0;
        int currentFrame = -1;
        int lastAttackStartedFrame = -1;
        int lastAttackConnectedFrame = -1;
        int strikeBandEntries = 0;
        int shieldReleaseSamples = 0;
        int healthDamageEvents = 0;
        int lastAttackDirection = 0;
        int lastDamagedHealth = -1;
        ulong trackedActorId = 0;
        float desiredActorSide = 1f;
        float lastDx = float.NaN;
        float lastDy = float.NaN;
        float lastSignedGap = float.NaN;
        bool wasInStrikeRange = false;
        Vector2 lastActorPosition = Vector2.Zero;
        int? lastEnemyHealth = null;
        int startingRecoveries = monitor.RecoveryCompleted;
        HealthComponent observedEnemyHealth = null;
        HealthComponent.DamagedEventHandler damaged = (remaining, _) =>
        {
            healthDamageEvents++;
            lastDamagedHealth = remaining;
        };
        PlayerCombat combat = player.GetNode<PlayerCombat>("Combat");
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        PlayerActionModeController modes =
            player.GetNode<PlayerActionModeController>("ActionModes");
        PlayerShieldController shield = player.GetNode<PlayerShieldController>("Shield");
        PlayerEnergyController energy = player.GetNode<PlayerEnergyController>("Energy");
        HealthComponent playerHealth = player.GetNode<HealthComponent>("Health");
        int playerHealthAtStart = playerHealth.CurrentHealth;
        // Stage 2 responds only to the actual NORMAL Main RED's suppressed mixed arrival.
        // It does not pre-position before suppression, restart batch0 or add a movement budget.
        bool counterweightSuppressionKeyboard = (tree is Knight.Tests.RunRealtimePrologueProbe || headlessNormalPlan) &&
            KeyboardRouteInputDriver.Current != null &&
            encounterId == "canyon.v2.encounter.counterweight-lift";
        const int mixedRecordCapacity = 4096;
        List<string> mixedRecords = counterweightSuppressionKeyboard ? new(mixedRecordCapacity) : null;
        int mixedDecisionId = 0, mixedDropped = 0, mixedObservationErrors = 0;
        bool mixedClosed = false, mixedEnergyKnown = false;
        ulong mixedEnergyPhysics = 0, mixedEnergySequence = 0;
        PlayerEnergyState mixedEnergyState = default;
        float mixedEnergyGateThreshold = energy.Tuning.MaxEnergy * .35f;
        Task10EncounterDanger mixedLastDanger = default;
        void MixedResourceSnapshot(string boundary, string details = "")
        {
            if (!counterweightSuppressionKeyboard || mixedClosed) return;
            if (mixedRecords.Count >= mixedRecordCapacity) { mixedDropped++; return; }
            try
            {
                // Only value snapshots/strings survive this callback. No printing or file I/O
                // occurs in the live battle. Event rows associate with the LAST decision,
                // not a second danger scan or an invented post-physics observation.
                mixedRecords.Add($"MIXED_RESOURCE record={mixedRecords.Count + 1} decision={mixedDecisionId} " +
                    $"boundary={boundary} physics={Engine.GetPhysicsFrames()} loop={currentFrame} sample={input.CurrentFrameSequence} " +
                    $"selected={trackedActorId} threat={mixedLastDanger.Threat} ranged={mixedLastDanger.HasRanged} " +
                    $"winner={mixedLastDanger.SourceActorId} attack_id={mixedLastDanger.AttackId} " +
                    $"phase={mixedLastDanger.Phase} remaining={mixedLastDanger.RemainingSeconds:R} gap={mixedLastDanger.FromActiveGap} " +
                    $"source={mixedLastDanger.GuardSource} energy={energy.EnergyRatio:R} heat={energy.HeatRatio:R} " +
                    $"overheated={energy.IsOverheated} sustained={energy.IsShieldSustained} can_guard={shield.CanBeginGuard} " +
                    $"held={input.Current.ShieldHeld} active={shield.IsActive} guard_direction={shield.GuardDirection} " +
                    $"aim={input.KeyboardAimDirection} move={input.Current.MoveAxis:R} attacking={combat.IsAttacking} " +
                    $"can_attack={modes.CanBeginAttack} afford_attack={modes.CanAffordAttack} hp={playerHealth.CurrentHealth} " +
                    $"player={player.GlobalPosition} velocity={player.Velocity} on_floor={player.IsOnFloor()} " +
                    $"raw_known={mixedEnergyKnown} raw_physics={mixedEnergyPhysics} raw_sample={mixedEnergySequence} " +
                    $"raw_energy={mixedEnergyState.Energy:R} raw_heat={mixedEnergyState.Heat:R} " +
                    $"regen_delay={mixedEnergyState.RegenDelayRemaining:R} cool_delay={mixedEnergyState.HeatCoolDelayRemaining:R} " +
                    $"raw_overheated={mixedEnergyState.Overheated} {details}");
            }
            catch (Exception) { mixedObservationErrors++; } // Never interrupt a production event.
        }
        Action<PlayerEnergyFrame> mixedEnergyChanged = frame =>
        {
            if (mixedClosed) return;
            try
            {
                bool boundary = !mixedEnergyKnown || mixedEnergyState.Overheated != frame.State.Overheated ||
                    (mixedEnergyState.Energy > mixedEnergyGateThreshold) != (frame.State.Energy > mixedEnergyGateThreshold);
                mixedEnergyState = frame.State; mixedEnergyKnown = true;
                mixedEnergyPhysics = Engine.GetPhysicsFrames(); mixedEnergySequence = input.CurrentFrameSequence;
                if (boundary) MixedResourceSnapshot("energy_state_event_after_apply");
            }
            catch (Exception) { mixedObservationErrors++; }
        };
        Action<bool> mixedShieldChanged = _ => MixedResourceSnapshot("shield_state_event_after_apply");
        Action<PlayerShieldResult, ulong> mixedShieldResolved = (result, transition) =>
            MixedResourceSnapshot("shield_resolved_pre_resource", $"transition={transition} guarded={result.Guarded} " +
                $"damage_amount={result.DamageAmount} broke_guard={result.BrokeGuard} request_source=unknown");
        bool counterweightSuppressionRecovery = false;
        StaticBody2D counterweightSuppressionFloor = null;
        CollisionShape2D counterweightSuppressionFloorShape = null;
        PlayerMotor counterweightSuppressionMotor = null;
        ulong counterweightSuppressionPlayerId = player.GetInstanceId(),
            counterweightSuppressionTelegraphPhysics = 0;
        int counterweightSuppressionHealth = -1, counterweightSuppressionJumps = -1,
            counterweightSuppressionDashes = -1, counterweightSuppressionIterations = 0;
        bool counterweightSuppressionSettledLogged = false;
        void GuardCounterweightSuppression()
        {
            TestAssert.True(group.IsActive && group.CurrentBatch == 1 &&
                player.GetInstanceId() == counterweightSuppressionPlayerId &&
                monitor.Player.GetInstanceId() == counterweightSuppressionPlayerId &&
                playerHealth.CurrentHealth == counterweightSuppressionHealth && playerHealth.CurrentHealth > 0 &&
                monitor.RecoveryRequested == 0 && monitor.RecoveryCompleted == 0 &&
                counterweightSuppressionMotor.AcceptedJumpCount == counterweightSuppressionJumps &&
                counterweightSuppressionMotor.AcceptedDashCount == counterweightSuppressionDashes &&
                player.GlobalPosition.IsFinite() && player.Velocity.IsFinite() &&
                HasFloorContact(player, counterweightSuppressionFloor) &&
                TryTask10CapsuleCorridor(player, counterweightSuppressionFloorShape,
                    out _, out _, out _, out _),
                "RANGED_COUNTERWEIGHT_SUPPRESSION_RED recovery preserves the original player, " +
                "actual full LiftBackLanding contact, HP, batch1 and zero jump/dash/recovery");
        }
        bool CounterweightSuppressionSettled() =>
            Mathf.Abs(player.GlobalPosition.X - 4700f) <= 6f && Mathf.Abs(player.Velocity.X) <= 2f &&
            input.CurrentFrame.MoveAxis == 0f && !input.CurrentFrame.PrimaryHeld &&
            !input.CurrentFrame.ShieldHeld && !input.CurrentFrame.JumpHeld &&
            !Input.IsPhysicalKeyPressed(Key.J) && !Input.IsPhysicalKeyPressed(Key.K) &&
            !Input.IsPhysicalKeyPressed(Key.L) && !Input.IsPhysicalKeyPressed(Key.Space) &&
            !Input.IsPhysicalKeyPressed(Key.Shift) && !Input.IsPhysicalKeyPressed(Key.W) &&
            !Input.IsPhysicalKeyPressed(Key.S);
        void LogCounterweightSuppression(string boundary) => GD.Print(
            $"RANGED_COUNTERWEIGHT_SUPPRESSION boundary={boundary} loop={currentFrame}/900 " +
            $"recovery_iterations={counterweightSuppressionIterations} physics={Engine.GetPhysicsFrames()} " +
            $"sample_boundary=SceneTree_PhysicsFrame_pre_node player_id={counterweightSuppressionPlayerId} " +
            $"player={player.GlobalPosition} velocity={player.Velocity} sample={input.CurrentFrameSequence} " +
            $"move={input.CurrentFrame.MoveAxis} telegraph_active={group.IsArrivalWarningActive} " +
            $"suppressed={group.SpawnSuppressed} batch={group.CurrentBatch} live={group.LiveActorCount} " +
            $"hp={playerHealth.CurrentHealth} recoveries={monitor.RecoveryRequested}/{monitor.RecoveryCompleted}");
        bool splitBellDiagnostic = KeyboardRouteInputDriver.Current != null &&
            encounterId == "canyon.v2.encounter.split-level";
        bool splitBellKeyboard = splitBellDiagnostic;
        PlayerMotor splitBellMotor = splitBellKeyboard ? player.GetNode<PlayerMotor>("Motor") : null;
        StaticBody2D splitBellFloor = splitBellKeyboard
            ? group.GetNode<StaticBody2D>("../../Collision/SplitUpperGallery") : null;
        CollisionShape2D splitBellFloorShape = splitBellFloor?.GetNode<CollisionShape2D>("Collision");
        ulong splitBellPlayerId = player.GetInstanceId(), splitBellActorId = 0;
        ulong splitBellStartPhysics = Engine.GetPhysicsFrames();
        int splitBellJumps = splitBellMotor?.AcceptedJumpCount ?? 0,
            splitBellDashes = splitBellMotor?.AcceptedDashCount ?? 0,
            splitBellRequests = monitor.RecoveryRequested;
        float splitBellCastStanceX = float.NaN;
        void GuardSplitBellPlayer()
        {
            TestAssert.True(player.GetInstanceId() == splitBellPlayerId &&
                monitor.Player.GetInstanceId() == splitBellPlayerId &&
                playerHealth.CurrentHealth == playerHealthAtStart &&
                monitor.RecoveryRequested == splitBellRequests && monitor.RecoveryCompleted == startingRecoveries &&
                splitBellMotor.AcceptedJumpCount == splitBellJumps && splitBellMotor.AcceptedDashCount == splitBellDashes &&
                Engine.GetPhysicsFrames() - splitBellStartPhysics <= 900 &&
                TryTask10CapsuleCorridor(player, splitBellFloorShape, out _, out _, out _, out _) &&
                HasFloorContact(player, splitBellFloor) &&
                player.GlobalPosition.IsFinite() && player.Velocity.IsFinite(),
                "keyboard split Bell including final hit preserves same player, full gallery support, HP, no jump/dash/recovery and original900 budget");
        }
        void GuardSplitBell(BellBackLaborer bell)
        {
            GuardSplitBellPlayer();
            TestAssert.True(bell.GetInstanceId() == splitBellActorId && HasFloorContact(bell, splitBellFloor),
                "keyboard split Bell rearm keeps the same live enemy on the actual gallery");
        }
        BellBackLaborer splitDiagnosticBell = null;
        string splitBellLastState = "";
        int splitBellDiagnosticLines = 0, splitBellDiagnosticErrors = 0;
        void ObserveSplitBell(string boundary, BellBackLaborer selected = null, Vector2? impulse = null)
        {
            if (!splitBellDiagnostic) return;
            try
            {
                if (selected != null) splitDiagnosticBell = selected;
                if (!GodotObject.IsInstanceValid(splitDiagnosticBell)) return;
                MechanicalClawController observedClaw = player.GetNode<MechanicalClawController>("MechanicalClaw");
                ThreadTarget2D observedTarget = splitDiagnosticBell.GetNode<ThreadTarget2D>("ThreadTarget");
                LegacyThreadInteractionAdapter observedAdapter =
                    observedTarget.GetNode<LegacyThreadInteractionAdapter>("LegacyThreadInteractionAdapter");
                HealthComponent observedHealth = splitDiagnosticBell.GetNode<HealthComponent>("Health");
                MechanicalClawFrame observedFrame = observedClaw.CurrentFrame;
                string state = $"{splitDiagnosticBell.CurrentState}/{observedHealth.CurrentHealth}/" +
                    $"{observedAdapter.ApplicationCount}/{observedFrame.State}/{observedFrame.Failure}/" +
                    $"{combat.IsAttacking}/{input.Current.ShieldHeld}/{shield.IsActive}";
                if (boundary == "state" && state == splitBellLastState) return;
                splitBellLastState = state;
                if (splitBellDiagnosticLines >= 40) return;
                splitBellDiagnosticLines++;
                GD.Print($"TASK10_SPLIT_BELL_DIAGNOSTIC boundary={boundary} record={splitBellDiagnosticLines}/40 " +
                    $"loop={currentFrame}/900 physics={Engine.GetPhysicsFrames()} sample={input.CurrentFrameSequence} " +
                    $"bell={splitDiagnosticBell.GetInstanceId()} state={splitDiagnosticBell.CurrentState} " +
                    $"enemy_hp={observedHealth.CurrentHealth} receiver={splitDiagnosticBell.GetNode<Hurtbox>("Hurtbox").DamageReceiverPath} " +
                    $"applications={observedAdapter.ApplicationCount} claw={observedFrame.State}/{observedFrame.Failure}/" +
                    $"{observedFrame.ReleaseKind} cast={observedFrame.CastId}/{observedFrame.NextCastId} " +
                    $"attacking={combat.IsAttacking} shield={input.Current.ShieldHeld}/{shield.IsActive} " +
                    $"energy={energy.EnergyRatio:R} hp={playerHealthAtStart}->{playerHealth.CurrentHealth} " +
                    $"player={player.GlobalPosition} velocity={player.Velocity} actor={splitDiagnosticBell.GlobalPosition} " +
                    $"damage_impulse={(impulse.HasValue ? impulse.Value.ToString() : "not_supplied")}");
            }
            catch (Exception) { splitBellDiagnosticErrors++; } // Diagnostics cannot replace the route failure.
        }
        bool frozenLowerKeyboard = KeyboardRouteInputDriver.Current != null &&
            encounterId == "canyon.v2.encounter.frozen-lower";
        PlayerMotor frozenLowerMotor = frozenLowerKeyboard ? player.GetNode<PlayerMotor>("Motor") : null;
        StaticBody2D frozenLowerFloor = frozenLowerKeyboard
            ? group.GetNode<StaticBody2D>("../../Collision/FrozenExit") : null;
        CollisionShape2D frozenLowerFloorShape = frozenLowerFloor?.GetNode<CollisionShape2D>("Collision");
        int frozenLowerJumps = frozenLowerMotor?.AcceptedJumpCount ?? 0;
        int frozenLowerDashes = frozenLowerMotor?.AcceptedDashCount ?? 0;
        int frozenLowerRequests = monitor.RecoveryRequested, frozenLowerLines = 0, frozenMothLines = 0;
        // Share the already verified neutral Bell keyboard policy, not its
        // old generic rushing/idle-guard policy, with the Steam batch0 Bell.
        // Legacy helper/log names remain compatible; every receipt names its encounter.
        bool gearBellKeyboard = KeyboardRouteInputDriver.Current != null &&
            (encounterId == "canyon.v2.encounter.gear-pistons" ||
             encounterId == "canyon.v2.encounter.steam-valves");
        PlayerMotor gearBellMotor = gearBellKeyboard ? player.GetNode<PlayerMotor>("Motor") : null;
        ulong gearBellStanceActor = 0, gearBellStanceFloor = 0, gearBellStanceSample = 0;
        int gearBellSupportSamples = 0, gearBellLines = 0;
        bool GearBellNeutralSupport(BellBackLaborer bell)
        {
            bool supported = TryTask10FullFloorSupport(player, out ulong floorId);
            bool fresh = input.CurrentFrameSequence > gearBellStanceSample;
            bool neutral = MathF.Abs(player.Velocity.X) <= 2f &&
                MathF.Abs(input.Current.MoveAxis) <= .001f &&
                !Input.IsPhysicalKeyPressed(Key.A) && !Input.IsPhysicalKeyPressed(Key.D);
            if (gearBellStanceActor != bell.GetInstanceId() || !supported || !neutral ||
                gearBellStanceFloor != floorId)
                gearBellSupportSamples = 0;
            if (fresh && supported && neutral) gearBellSupportSamples++;
            gearBellStanceActor = bell.GetInstanceId();
            gearBellStanceFloor = supported ? floorId : 0;
            gearBellStanceSample = input.CurrentFrameSequence;
            Vector2 delta = bell.GlobalPosition - player.GlobalPosition;
            float side = MathF.Sign(delta.X);
            return supported && neutral && gearBellSupportSamples >= 2 &&
                MathF.Abs(delta.Y) <= 46f && MathF.Abs(delta.X) is >= 55f and <= 64f &&
                input.KeyboardAimDirection.Dot(Vector2.Right * side) > .99f &&
                !gearBellMotor.IsDashing && !input.Current.JumpPressed && !input.Current.JumpHeld &&
                !Input.IsPhysicalKeyPressed(Key.Space) && !Input.IsPhysicalKeyPressed(Key.Shift);
        }
        bool courtyardKeyboardJump = KeyboardRouteInputDriver.Current != null &&
            encounterId == "canyon.v2.encounter.sealed-courtyard";
        StaticBody2D courtyardJumpStep = courtyardKeyboardJump
            ? group.GetNode<StaticBody2D>("../../Collision/CourtyardStep") : null;
        StaticBody2D courtyardJumpFloor = courtyardKeyboardJump
            ? group.GetNode<StaticBody2D>("../../Collision/CheckpointFloor") : null;
        CollisionShape2D courtyardJumpStepShape = courtyardJumpStep?.GetNode<CollisionShape2D>("Collision");
        CollisionShape2D courtyardJumpFloorShape = courtyardJumpFloor?.GetNode<CollisionShape2D>("Collision");
        PlayerMotor courtyardJumpMotor = courtyardKeyboardJump ? player.GetNode<PlayerMotor>("Motor") : null;
        bool courtyardJumpPreparing = false, courtyardJumpIssued = false,
            courtyardJumpReleased = false, courtyardJumpLanded = false, courtyardJumpComplete = false;
        int courtyardJumpBaseline = 0, courtyardDashBaseline = 0, courtyardRequestBaseline = 0,
            courtyardRecoveryBaseline = 0, courtyardJumpEdges = 0, courtyardHeldSamples = 0,
            courtyardJumpLines = 0;
        ulong courtyardJumpPlayerId = 0, courtyardJumpActorId = 0, courtyardNeutralSequence = 0,
            courtyardIssueSequence = 0, courtyardLastSequence = 0, courtyardEdgeSequence = 0,
            courtyardReleaseSequence = 0, courtyardIssuePhysics = 0, courtyardLastHeldPhysics = 0;
        float courtyardFirstLandingX = float.NaN;
        bool CourtyardJumpSupport(StaticBody2D body, CollisionShape2D shape) =>
            TryTask10CapsuleCorridor(player, shape, out _, out _, out _, out _) && HasFloorContact(player, body);
        void CourtyardJumpSnapshot(string boundary, Node2D actor)
        {
            if (courtyardJumpLines >= 16) return;
            courtyardJumpLines++;
            // Only selected boundaries of this one jump; queries are read-only, not cast receipts.
            ThreadTarget2D target = actor.GetNode<ThreadTarget2D>("ThreadTarget");
            Vector2 planned = PlayerKeyboardAimModel.ResolveDirection(target.WorldAnchor - player.GlobalPosition, 1);
            MechanicalClawTargetResolution selected = new MechanicalClawTargetResolver().ResolveKeyboard(player, planned);
            GD.Print($"TASK10_COURTYARD_KEYBOARD_JUMP boundary={boundary} record={courtyardJumpLines}/16 " +
                $"physics={Engine.GetPhysicsFrames()} loop={currentFrame}/900 sample={input.CurrentFrameSequence} " +
                $"issue_sequence={courtyardIssueSequence} edge_sequence={courtyardEdgeSequence} " +
                $"jump_edge_held={input.CurrentFrame.JumpPressed}/{input.CurrentFrame.JumpHeld} " +
                $"raw_space={Input.IsPhysicalKeyPressed(Key.Space)} edges={courtyardJumpEdges}/1 held_samples={courtyardHeldSamples}/12 " +
                $"accepted_jumps={courtyardJumpBaseline}->{courtyardJumpMotor.AcceptedJumpCount} " +
                $"position={player.GlobalPosition} velocity={player.Velocity} move={input.CurrentFrame.MoveAxis} " +
                $"step_full={CourtyardJumpSupport(courtyardJumpStep, courtyardJumpStepShape)} " +
                $"checkpoint_full={CourtyardJumpSupport(courtyardJumpFloor, courtyardJumpFloorShape)} " +
                $"floor={DescribeFloorCollider(player)} hp={playerHealthAtStart}->{playerHealth.CurrentHealth} " +
                $"recoveries={courtyardRequestBaseline}/{courtyardRecoveryBaseline}->" +
                $"{monitor.RecoveryRequested}/{monitor.RecoveryCompleted} " +
                $"planned={planned} selected={selected.Surface?.GetPath()} material={selected.Snapshot.Material} " +
                $"anchor={selected.Snapshot.WorldAnchor} los={selected.Snapshot.HasLineOfSight}");
        }
        MechanicalClawController courtyardBellClaw = courtyardKeyboardJump
            ? player.GetNode<MechanicalClawController>("MechanicalClaw") : null;
        BellBackLaborer courtyardBell = null;
        ThreadTarget2D courtyardBellTarget = null;
        LegacyThreadInteractionAdapter courtyardBellAdapter = null;
        bool courtyardBellPreparing = false, courtyardBellIssued = false, courtyardBellKeyReleased = false,
            courtyardBellReceipt = false, courtyardBellReleased = false, courtyardBellComplete = false,
            courtyardBellInvalidReceipt = false, courtyardBellDamageLogged = false, courtyardBellFatalLogged = false;
        int courtyardBellApplications = 0, courtyardBellRawEdges = 0, courtyardBellEdges = 0,
            courtyardBellFirstApplications = 0, courtyardBellFirstRawEdges = 0,
            courtyardBellCycle = 0, courtyardBellSpacingPhase = 0, courtyardBellLines = 0;
        ulong courtyardBellNeutralSequence = 0, courtyardBellIssueSequence = 0,
            courtyardBellLastSequence = 0, courtyardBellEdgeSequence = 0,
            courtyardBellReceiptSequence = 0, courtyardBellReceiptPhysics = 0, courtyardBellCast = 0;
        Vector2 courtyardBellPlanned = Vector2.Zero;
        float courtyardBellCastStanceX = float.NaN;
        string courtyardBellLastState = "";
        void CourtyardBellSnapshot(string boundary, bool damage = false, string detail = "")
        {
            if (!courtyardBellPreparing || group.CurrentBatch != 1 || !GodotObject.IsInstanceValid(courtyardBell)) return;
            bool fatal = playerHealth.CurrentHealth <= 0;
            if (damage ? (fatal ? courtyardBellFatalLogged : courtyardBellDamageLogged) : courtyardBellLines >= 48) return;
            if (damage)
            {
                if (fatal) courtyardBellFatalLogged = true; else courtyardBellDamageLogged = true;
            }
            else courtyardBellLines++;
            MechanicalClawFrame clawFrame = courtyardBellClaw.CurrentFrame;
            GD.Print($"TASK10_COURTYARD_BELL boundary={boundary} record={courtyardBellLines}/48 damage={damage} player_dead={fatal} cycle={courtyardBellCycle}/900 " +
                $"physics={Engine.GetPhysicsFrames()} loop={currentFrame}/900 sample={input.CurrentFrameSequence} " +
                $"state={courtyardBell.CurrentState} phase={courtyardBell.CurrentFrame.AttackTimeline.Phase} " +
                $"remaining={courtyardBell.CurrentFrame.AttackTimeline.PhaseRemainingSeconds:R} " +
                $"receiver={courtyardBell.GetNode<Hurtbox>("Hurtbox").DamageReceiverPath} " +
                $"enemy_hp={courtyardBell.GetNode<HealthComponent>("Health").CurrentHealth} " +
                $"player={player.GlobalPosition} velocity={player.Velocity} " +
                $"checkpoint_full={CourtyardJumpSupport(courtyardJumpFloor, courtyardJumpFloorShape)} " +
                $"hp={playerHealthAtStart}->{playerHealth.CurrentHealth} recoveries={monitor.RecoveryRequested}/{monitor.RecoveryCompleted} " +
                $"energy={energy.EnergyRatio:R} heat={energy.HeatRatio:R} can_guard={shield.CanBeginGuard} " +
