        string SplitObservation(out string key, out string castIds)
        {
            // These are previous actually sampled inputs, never acknowledgement of the
            // intended movement whose SendAction calls have not happened at this location.
            bool playerLive = DiagnosticLive(player), mothLive = DiagnosticLive(splitMoth);
            bool inputLive = DiagnosticLive(input), modesLive = DiagnosticLive(modes);
            bool clawLive = DiagnosticLive(splitClaw), shieldLive = DiagnosticLive(shield);
            PlayerInputFrame sampled = inputLive ? input.CurrentFrame : default;
            MechanicalClawFrame claw = clawLive ? splitClaw.CurrentFrame : default;
            HealthComponent mothHealth = mothLive
                ? splitMoth.GetNodeOrNull<HealthComponent>("Health") : null;
            string mothState = mothLive ? splitMoth.CurrentState.ToString() : "unavailable";
            string hp = DiagnosticLive(playerHealth) ? playerHealth.CurrentHealth.ToString() : "unavailable";
            string enemyHp = DiagnosticLive(mothHealth) ? mothHealth.CurrentHealth.ToString() : "unavailable";
            string mode = modesLive ? modes.CurrentMode.ToString() : "unavailable";
            string slot = modesLive ? modes.ActiveSlot.ToString() : "unavailable";
            string canGrapple = modesLive ? modes.CanBeginGrapple.ToString() : "unavailable";
            string shieldActive = shieldLive ? shield.IsActive.ToString() : "unavailable";
            string clawTarget = clawLive ? SplitIdentity(splitClaw.CurrentTarget) : "unavailable";
            var contacts = new List<string>();
            var contactKey = new List<string>();
            if (playerLive)
                for (int index = 0; index < player.GetSlideCollisionCount(); index++)
                {
                    KinematicCollision2D collision = player.GetSlideCollision(index);
                    if (!GodotObject.IsInstanceValid(collision)) continue;
                    GodotObject collider = collision.GetCollider();
                    string identity = GodotObject.IsInstanceValid(collider)
                        ? collider is Node node ? SplitIdentity(node) : $"#{collider.GetInstanceId()}"
                        : "unavailable";
                    Vector2 normal = collision.GetNormal();
                    contacts.Add($"{identity}:normal={normal}:point={collision.GetPosition()}");
                    contactKey.Add($"{identity}:{normal}");
                }
            bool dyGate = lastDy < -74f,
                cadence = mothLive && SplitMothCastWindow(splitMoth);
            castIds = clawLive ? $"{claw.CastId}/{claw.NextCastId}" : "unavailable";
            key = $"{mothLive}|{mothState}|{enemyHp}|{mode}|{slot}|{canGrapple}|{shieldActive}|" +
                $"{sampled.MoveAxis}|{sampled.PrimaryPressed}|{sampled.PrimaryHeld}|{sampled.ShieldHeld}|" +
                $"{clawLive}|{claw.State}|{claw.Failure}|{castIds}|{clawTarget}|" +
                $"{dyGate}|{cadence}|{splitStrikeEligible}|{splitIntendedLeft}|{splitIntendedRight}|" +
                $"{(playerLive && player.IsOnFloor())}|{hp}|{monitor.RecoveryRequested}|{monitor.RecoveryCompleted}|" +
                string.Join(';', contactKey);
            Vector2 playerPosition = playerLive ? player.GlobalPosition : Vector2.Zero;
            Vector2 mothPosition = mothLive ? splitMoth.GlobalPosition : Vector2.Zero;
            string actualGap = playerLive && mothLive
                ? $"dx={mothPosition.X - playerPosition.X:R} dy={mothPosition.Y - playerPosition.Y:R}"
                : "dx=unavailable dy=unavailable";
            return $"physics={Engine.GetPhysicsFrames()} loop={currentFrame} moth={splitMothIdentity} " +
                $"moth_live={mothLive} moth_xy={(mothLive ? mothPosition.ToString() : "unavailable")} " +
                $"moth_velocity={(mothLive ? splitMoth.Velocity.ToString() : "unavailable")} moth_state={mothState} moth_hp={enemyHp} " +
                $"player_live={playerLive} player_xy={(playerLive ? playerPosition.ToString() : "unavailable")} " +
                $"player_velocity={(playerLive ? player.Velocity.ToString() : "unavailable")} floor={(playerLive && player.IsOnFloor())} " +
                $"{actualGap} intended_left={splitIntendedLeft} intended_right={splitIntendedRight} " +
                $"dy_gate={dyGate} cadence_gate={cadence} gate_kind={(splitBellKeyboard ? "early_non_dive" : "legacy60")} " +
                $"combined_gate={dyGate && cadence} strike_eligible={splitStrikeEligible} " +
                $"input_live={inputLive} previous_sample_sequence={(inputLive ? input.CurrentFrameSequence : 0)} " +
                $"previous_sample_move={sampled.MoveAxis} primary={sampled.PrimaryPressed}/{sampled.PrimaryHeld} shield_held={sampled.ShieldHeld} " +
                $"mode={mode} slot={slot} can_begin_grapple={canGrapple} shield_active={shieldActive} " +
                $"claw_live={clawLive} claw_state={claw.State} claw_failure={claw.Failure} cast_id={claw.CastId} next_cast_id={claw.NextCastId} " +
                $"claw_target={clawTarget} locked_target_id={claw.LockedTargetRuntimeId} player_hp={hp} " +
                $"recoveries={monitor.RecoveryRequested}/{monitor.RecoveryCompleted} contacts=[{string.Join(';', contacts)}]";
        }
        void ObserveSplitMoth(Node2D selectedActor, bool moveLeft, bool moveRight, bool eligible)
        {
            if (!splitMothDiagnostic || selectedActor is not GraveLampMoth selectedMoth) return;
            try
            {
                if (!DiagnosticLive(selectedMoth)) return;
                if (splitMothId == 0)
                {
                    splitMoth = selectedMoth;
                    splitMothId = selectedMoth.GetInstanceId();
                    splitMothIdentity = SplitIdentity(selectedMoth);
                    splitSelectionPhysics = Engine.GetPhysicsFrames();
                    splitSelectionLoop = currentFrame;
                    splitClaw = DiagnosticLive(player)
                        ? player.GetNodeOrNull<MechanicalClawController>("MechanicalClaw") : null;
                }
                if (selectedMoth.GetInstanceId() != splitMothId) return;
                splitSelectedIterations++;
                if (lastDy < -74f) splitDyPass++;
                if (SplitMothCastWindow(selectedMoth)) splitCadencePass++;
                if (lastDy < -74f && SplitMothCastWindow(selectedMoth)) splitCombinedPass++;
                splitMinDx = Math.Min(splitMinDx, lastDx); splitMaxDx = Math.Max(splitMaxDx, lastDx);
                splitMinDy = Math.Min(splitMinDy, lastDy); splitMaxDy = Math.Max(splitMaxDy, lastDy);
                splitIntendedLeft = moveLeft; splitIntendedRight = moveRight; splitStrikeEligible = eligible;
                string observation = SplitObservation(out string key, out string castIds);
                splitLastObservation = observation; splitLastCastIds = castIds;
                if (splitSelectedIterations == 1)
                { splitFirstObservation = observation; splitFirstCastIds = castIds; }
                bool changed = key != splitStateKey;
                splitStateKey = key;
                if (Engine.GetPhysicsFrames() - splitSelectionPhysics >= 180)
                { splitWindowExpiredSamples++; return; }
                if (!changed) return;
                if (splitStateLines >= 24) { splitStateSuppressed++; return; }
                splitStateLines++;
                GD.Print($"TASK10_SPLIT_MOTH_STATE timing=driver_pre_input {observation}");
            }
            catch (Exception error) { SplitDiagnosticError(error); }
        }
        void SplitMothEdge(GraveLampMoth selectedMoth, bool returned)
        {
            if (!splitMothDiagnostic || splitMothId == 0) return;
            try
            {
                if (!ReferenceEquals(selectedMoth, splitMoth)) return;
                if (returned) splitCastReturns++; else splitBranchEntries++;
                if (splitEdgeLines >= 6) { splitEdgeSuppressed++; return; }
                string observation = SplitObservation(out _, out _);
                bool live = DiagnosticLive(selectedMoth);
                // Keyboard split combat requires a live stun, never retirement caused by recovery.
                bool completed = (!splitBellKeyboard && !GodotObject.IsInstanceValid(selectedMoth)) ||
                    live && selectedMoth.CurrentState == GraveLampMothState.ThreadStunned;
                splitEdgeLines++;
                GD.Print($"TASK10_SPLIT_MOTH_EDGE timing={(returned ? "CastAt_return" : "before_CastAt")} " +
                    $"completed_predicate={completed} predicate_observable={(!GodotObject.IsInstanceValid(selectedMoth) || live)} {observation}");
            }
            catch (Exception error) { SplitDiagnosticError(error); }
        }
