                    $"{steamBellLastDanger.SourceActorId}/{steamBellLastDanger.AttackId}/{steamBellLastDanger.Phase} " +
                    $"guard_source={steamBellLastDanger.GuardSource} decision=[{steamBellDecision}] " +
                    $"valve={(DiagnosticLive(steamBellValve) ? steamBellValve.IsActivated.ToString() : "unavailable")} " +
                    $"jet_live={jetLive} jet={(jetLive ? steamBellJet.GetInstanceId() : 0)} " +
                    $"jet_disabled={(jetLive ? steamBellJet.DisabledForRun.ToString() : "unavailable")} " +
                    $"jet_hazard={(jetLive ? steamBellJet.Frame.HazardActive.ToString() : "unavailable")} " +
                    $"jet_monitoring={(jetLive && steamBellJet.Monitoring)} " +
                    $"recoveries={monitor.RecoveryRequested}/{monitor.RecoveryCompleted} {detail} diagnostic_only=true observer_only=true");
            }
            catch (Exception) { steamBellErrors++; }
        }
        Action<BellBackLaborerFrame, int> steamBellFrameChanged = (frame, facing) =>
        {
            string identity = $"{frame.State}/{frame.AttackTimeline.AttackId}/{frame.AttackTimeline.Phase}/{facing}";
            if (identity == steamBellLastState) return;
            steamBellLastState = identity;
            SteamBellSnapshot("post_move_frame", $"facing={facing}");
        };
        Action<AttackPresentationFrame> steamBellAttackChanged = frame =>
        {
            steamBellPublishedAttack = frame.Timeline;
            string identity = $"{frame.Timeline.AttackId}/{frame.Timeline.Phase}/{frame.Timeline.HasLockedTarget}";
            if (identity == steamBellLastAttack) return;
            steamBellLastAttack = identity;
            SteamBellSnapshot("pre_move_attack_publication");
        };
        Action<PlayerShieldResult, ulong> steamBellShieldResolved = (result, transition) =>
            SteamBellSnapshot("shield_resolved", $"local_shield_transition={transition} result={result} not_source_identity=true");
        BellBoltSentry trackedSentry = null;
        BellBoltProjectile trackedBolt = null;
        Hitbox trackedBoltHitbox = null;
        Hurtbox playerHurtbox = steamSentryDiagnostic
            ? player.GetNodeOrNull<Hurtbox>("Hurtbox") : null;
        string sentryIdentity = "unavailable";
        string boltIdentity = "unavailable";
        string hitboxIdentity = "unavailable";
        string playerHurtboxIdentity = GodotObject.IsInstanceValid(playerHurtbox) &&
            playerHurtbox.IsInsideTree()
            ? $"{playerHurtbox.GetPath()}#{playerHurtbox.GetInstanceId()}" : "unavailable";
        ulong sentryStartPhysics = 0;
        int sentrySnapshotCount = 0;
        int sentryDamageEvents = 0;
        int sentryConnectedEvents = 0;
        int sentryShieldEvents = 0;
        int sentryPolicyLines = 0;
        bool sentryGuardRequested = false;
        bool sentryGuardAcknowledged = false;
        int sentryGuardSamples = 0;
        ulong sentryGuardRequestSequence = 0;
        ulong sentryLastGuardSample = 0;
        bool sentryReleaseRequested = false;
        bool sentryReleaseSampled = false;
        ulong sentryReleaseRequestSequence = 0;
        bool sentryBoltWasLive = false;
        bool steamSentryBoltRetired = false;
        SteamSentryRecoveryDriver steamSentryRecovery = null;
        int steamRecoveryCastCommands = 0, steamRecoveryAttackCommands = 0;
        string lastSentryState = null;
        ulong lastSentryAttackId = 0;
        AttackPhase lastSentryPhase = AttackPhase.None;
        bool lastSentryLock = false;

        bool SteamWindow() => steamSentryDiagnostic && trackedSentry != null &&
            Engine.GetPhysicsFrames() - sentryStartPhysics < 150;

        void SteamSnapshot(string reason, bool eventLine = false, string detail = "")
        {
            if (!SteamWindow()) return;
            if (eventLine)
            {
                if (reason == "player_damaged")
                {
                    if (sentryDamageEvents >= 12) return;
                    sentryDamageEvents++;
                }
                else if (reason == "bolt_connected")
                {
                    if (sentryConnectedEvents >= 12) return;
                    sentryConnectedEvents++;
                }
                else
                {
                    if (sentryShieldEvents >= 24) return;
                    sentryShieldEvents++;
                }
            }
            else
            {
                if (sentrySnapshotCount >= 24) return;
                sentrySnapshotCount++;
            }
            bool sentryLive = GodotObject.IsInstanceValid(trackedSentry) &&
                trackedSentry.IsInsideTree();
            bool boltLive = GodotObject.IsInstanceValid(trackedBolt) && trackedBolt.IsInsideTree();
            bool playerLive = GodotObject.IsInstanceValid(player) && player.IsInsideTree();
            bool inputLive = GodotObject.IsInstanceValid(input) && input.IsInsideTree();
            bool healthLive = GodotObject.IsInstanceValid(playerHealth) && playerHealth.IsInsideTree();
            bool shieldLive = GodotObject.IsInstanceValid(shield) && shield.IsInsideTree();
            bool combatLive = GodotObject.IsInstanceValid(combat) && combat.IsInsideTree();
            bool modesLive = GodotObject.IsInstanceValid(modes) && modes.IsInsideTree();
            bool energyLive = GodotObject.IsInstanceValid(energy) && energy.IsInsideTree();
            BellBoltSentryFrame sentryFrame = sentryLive ? trackedSentry.CurrentFrame : default;
            AttackTimelineFrame timeline = sentryFrame.AttackTimeline;
            GD.Print($"TASK10_STEAM_SENTRY_{(eventLine ? "EVENT" : "STATE")} reason={reason} " +
                $"physics={Engine.GetPhysicsFrames()} loop={currentFrame} " +
                $"sample={(inputLive ? input.CurrentFrameSequence.ToString() : "unavailable")} " +
                $"sentry={sentryIdentity} state={(sentryLive ? sentryFrame.State.ToString() : "unavailable")} " +
                $"attack_id={(sentryLive ? timeline.AttackId.ToString() : "unavailable")} " +
                $"phase={(sentryLive ? timeline.Phase.ToString() : "unavailable")} " +
                $"target_lock={(sentryLive ? timeline.HasLockedTarget.ToString() : "unavailable")} " +
                $"locked_world_target={(sentryLive ? timeline.LockedWorldTarget.ToString() : "unavailable")} " +
                $"aim={(sentryLive ? sentryFrame.AimDirection.ToString() : "unavailable")} " +
                $"fire={(sentryLive ? sentryFrame.FireRequested.ToString() : "unavailable")} " +
                $"bolt={boltIdentity} bolt_xy={(boltLive ? trackedBolt.GlobalPosition.ToString() : "unavailable")} " +
                $"bolt_distance={(boltLive ? trackedBolt.TravelledDistance.ToString("0.000") : "unavailable")} " +
                $"bolt_retired={(boltLive ? trackedBolt.IsRetired.ToString() : "unavailable")} " +
                $"hitbox={hitboxIdentity} bolt_live={boltLive} " +
                $"hitbox_live={(GodotObject.IsInstanceValid(trackedBoltHitbox) && trackedBoltHitbox.IsInsideTree())} " +
                $"player_hurtbox={playerHurtboxIdentity} " +
                $"player_xy={(playerLive ? player.GlobalPosition.ToString() : "unavailable")} " +
                $"player_velocity={(playerLive ? player.Velocity.ToString() : "unavailable")} " +
                $"hp={(healthLive ? playerHealth.CurrentHealth.ToString() : "unavailable")} " +
                $"move={(inputLive ? input.Current.MoveAxis.ToString() : "unavailable")} " +
                $"primary={(inputLive ? $"{input.Current.PrimaryPressed}/{input.Current.PrimaryHeld}" : "unavailable")} " +
                $"shield_held={(inputLive ? input.Current.ShieldHeld.ToString() : "unavailable")} " +
                $"raw_mouse_right={Input.IsMouseButtonPressed(MouseButton.Right)} " +
                $"shield_active={(shieldLive ? shield.IsActive.ToString() : "unavailable")} " +
                $"guard_direction={(shieldLive ? shield.GuardDirection.ToString() : "unavailable")} " +
                $"attacking={(combatLive ? combat.IsAttacking.ToString() : "unavailable")} " +
                $"mode={(modesLive ? modes.CurrentMode.ToString() : "unavailable")} " +
                $"energy={(energyLive ? energy.EnergyRatio.ToString("0.000") : "unavailable")} " +
                $"heat={(energyLive ? energy.HeatRatio.ToString("0.000") : "unavailable")} {detail}");
        }

        void SteamPolicyLog(string reason, string detail = "")
        {
            if (sentryPolicyLines++ >= 40) return;
            GD.Print($"TASK10_STEAM_POLICY reason={reason} physics={Engine.GetPhysicsFrames()} " +
                $"loop={currentFrame} sample={input.CurrentFrameSequence} " +
                $"player={player.GlobalPosition} hp={playerHealth.CurrentHealth} " +
                $"energy={energy.EnergyRatio:0.000} heat={energy.HeatRatio:0.000} " +
                $"held={input.Current.ShieldHeld} active={shield.IsActive} " +
                $"direction={shield.GuardDirection} {detail}");
        }

        Hitbox.ConnectedEventHandler boltConnected = targetHurtbox =>
        {
            string targetIdentity = GodotObject.IsInstanceValid(targetHurtbox) &&
                targetHurtbox.IsInsideTree()
                ? $"{targetHurtbox.GetPath()}#{targetHurtbox.GetInstanceId()}" : "unavailable";
            bool isPlayer = GodotObject.IsInstanceValid(targetHurtbox) &&
                GodotObject.IsInstanceValid(playerHurtbox) &&
                targetHurtbox.GetInstanceId() == playerHurtbox.GetInstanceId();
            SteamSnapshot("bolt_connected", true,
                $"target_hurtbox={targetIdentity} target_is_player={isPlayer}");
        };

        void ObserveSteamBolt()
        {
            if (!GodotObject.IsInstanceValid(trackedSentry) || !trackedSentry.IsInsideTree()) return;
            BellBoltProjectile bolt = trackedSentry.GetChildren().OfType<BellBoltProjectile>()
                .FirstOrDefault(candidate => GodotObject.IsInstanceValid(candidate) &&
                    candidate.IsInsideTree() && !candidate.IsRetired);
            if (ReferenceEquals(bolt, trackedBolt)) return;
            if (GodotObject.IsInstanceValid(trackedBoltHitbox))
                trackedBoltHitbox.Connected -= boltConnected;
            trackedBolt = bolt;
            trackedBoltHitbox = null;
            if (bolt == null) return;
            boltIdentity = $"{bolt.GetPath()}#{bolt.GetInstanceId()}";
            trackedBoltHitbox = bolt.GetNodeOrNull<Hitbox>("Hitbox");
            hitboxIdentity = GodotObject.IsInstanceValid(trackedBoltHitbox) &&
                trackedBoltHitbox.IsInsideTree()
                ? $"{trackedBoltHitbox.GetPath()}#{trackedBoltHitbox.GetInstanceId()}" : "unavailable";
            if (GodotObject.IsInstanceValid(trackedBoltHitbox))
                trackedBoltHitbox.Connected += boltConnected;
            SteamSnapshot("bolt_discovered");
        }

        Action<BellBoltSentryFrame> sentryFrameChanged = frame =>
        {
            if (!SteamWindow()) return;
            ObserveSteamBolt();
            bool changed = frame.State.ToString() != lastSentryState ||
                frame.AttackTimeline.AttackId != lastSentryAttackId ||
                frame.AttackTimeline.Phase != lastSentryPhase ||
                frame.AttackTimeline.HasLockedTarget != lastSentryLock;
            lastSentryState = frame.State.ToString();
            lastSentryAttackId = frame.AttackTimeline.AttackId;
            lastSentryPhase = frame.AttackTimeline.Phase;
            lastSentryLock = frame.AttackTimeline.HasLockedTarget;
            if (frame.FireRequested) SteamSnapshot("fire_requested");
            else if (changed) SteamSnapshot("state_or_timeline_change");
            else if (GodotObject.IsInstanceValid(trackedBolt) && !trackedBolt.IsRetired &&
                (Engine.GetPhysicsFrames() - sentryStartPhysics) % 10 == 0)
                SteamSnapshot("bolt_10_frames");
        };
        Action<PlayerShieldResult, ulong> sentryShieldResolved = (result, transitionId) =>
            SteamSnapshot("shield_resolved", true,
                $"transition_id={transitionId} result={result}");

        string GearDiagnosticFloor()
        {
            if (!GodotObject.IsInstanceValid(player) || !player.IsInsideTree())
                return "unavailable_player";
            if (!player.IsOnFloor()) return "airborne";
            for (int index = 0; index < player.GetSlideCollisionCount(); index++)
            {
                KinematicCollision2D collision = player.GetSlideCollision(index);
                if (!GodotObject.IsInstanceValid(collision)) return "invalid_contact";
                if (collision.GetNormal().Y >= -.7f) continue;
                GodotObject collider = collision.GetCollider();
                if (!GodotObject.IsInstanceValid(collider)) return "invalid_collider";
                if (collider is Node node)
                    return node.IsInsideTree()
                        ? $"{node.GetPath()}#{node.GetInstanceId()}"
                        : $"detached_collider#{node.GetInstanceId()}";
                return collider.GetInstanceId().ToString();
            }
            return "floor_without_slide_collider";
        }

        void GearDiagnosticSnapshot(string reason, Vector2? suppliedImpulse = null)
        {
            if (!gearDiagnostic || !GodotObject.IsInstanceValid(player) ||
                !GodotObject.IsInstanceValid(input) || !GodotObject.IsInstanceValid(energy) ||
                !GodotObject.IsInstanceValid(shield) || !GodotObject.IsInstanceValid(playerHealth)) return;
            bool laneValid = GodotObject.IsInstanceValid(diagnosticLane);
            CollisionShape2D laneCollider = laneValid
                ? diagnosticLane.GetNodeOrNull<CollisionShape2D>("Collision") : null;
            Rect2? laneEnvelope = GodotObject.IsInstanceValid(laneCollider) &&
                laneCollider.Shape is RectangleShape2D rectangle && GodotObject.IsInstanceValid(rectangle)
                ? WorldEnvelope(laneCollider, rectangle.Size / 2f) : null;
            CapsuleShape2D capsule = GodotObject.IsInstanceValid(diagnosticCapsule)
                ? diagnosticCapsule.Shape as CapsuleShape2D : null;
            if (!GodotObject.IsInstanceValid(capsule)) capsule = null;
            Rect2? capsuleEnvelope = capsule != null
                ? WorldEnvelope(diagnosticCapsule, new Vector2(capsule.Radius, capsule.Height / 2f)) : null;
            bool centerInside = laneEnvelope?.HasPoint(player.GlobalPosition) ?? false;
            bool capsuleAabbOverlap = laneEnvelope.HasValue && capsuleEnvelope.HasValue &&
                laneEnvelope.Value.Intersects(capsuleEnvelope.Value);
            bool monitoredOverlap = laneValid && diagnosticLane.GetOverlappingBodies().Contains(player);
            Node2D liveActor = GodotObject.IsInstanceValid(actorRoot)
                ? actorRoot.GetChildren().OfType<Node2D>().FirstOrDefault(candidate =>
                    GodotObject.IsInstanceValid(candidate) && candidate.Name.ToString().StartsWith(
                        encounterId.Replace('.', '_'), StringComparison.Ordinal)) : null;
            bool actorValid = GodotObject.IsInstanceValid(liveActor);
            string actorState = liveActor switch
            {
                RustShellSquire rust => rust.CurrentState.ToString(),
                BellBackLaborer bell => bell.CurrentState.ToString(),
                _ => "unreported"
            };
            string actorPhase = liveActor switch
            {
                RustShellSquire rust => rust.CurrentFrame.AttackTimeline.Phase.ToString(),
                BellBackLaborer bell => bell.CurrentFrame.AttackTimeline.Phase.ToString(),
                _ => "unreported"
            };
            Hitbox actorHitbox = actorValid ? liveActor.GetNodeOrNull<Hitbox>("AttackHitbox") : null;
            bool hitboxMonitoring = GodotObject.IsInstanceValid(actorHitbox) && actorHitbox.Monitoring;
            CollisionShape2D hitboxCollider = GodotObject.IsInstanceValid(actorHitbox)
                ? actorHitbox.GetNodeOrNull<CollisionShape2D>("AttackCollider") : null;
            string state = $"{input.Current.ShieldHeld}/{shield.IsActive}/{energy.IsOverheated}/" +
                $"{energy.IsShieldSustained}/{playerHealth.CurrentHealth}/{combat.IsAttacking}/" +
                $"{MathF.Round(shield.GuardDirection.X * 4f)}/{MathF.Round(shield.GuardDirection.Y * 4f)}/" +
                $"{centerInside}/{capsuleAabbOverlap}/{monitoredOverlap}/" +
                $"{(laneValid ? diagnosticLane.PulseCount : -1)}/{actorState}/{actorPhase}/{hitboxMonitoring}";
            if (reason == "state")
            {
                if (state == diagnosticLastState || diagnosticStateLogs >= 48) return;
                diagnosticLastState = state;
                diagnosticStateLogs++;
            }
            if (reason == "damage")
            {
                if (diagnosticDamageLogs >= 16 && playerHealth.CurrentHealth > 0) return;
                if (playerHealth.CurrentHealth <= 0 && diagnosticFatalLogged) return;
                if (playerHealth.CurrentHealth <= 0) diagnosticFatalLogged = true;
                diagnosticDamageLogs++;
            }
            GD.Print($"TASK10_GEAR_STATE reason={reason} physics={Engine.GetPhysicsFrames()} loop={currentFrame} " +
                $"sample={input.CurrentFrameSequence} player={player.GlobalPosition} velocity={player.Velocity} " +
                $"floor={GearDiagnosticFloor()} health={playerHealth.CurrentHealth} " +
                $"move={input.Current.MoveAxis} primary={input.Current.PrimaryPressed}/{input.Current.PrimaryHeld} " +
                $"shield_held={input.Current.ShieldHeld} shield_active={shield.IsActive} direction={shield.GuardDirection} " +
                $"energy={energy.EnergyRatio:0.000} heat={energy.HeatRatio:0.000} " +
                $"overheated={energy.IsOverheated} sustained={energy.IsShieldSustained} " +
                $"capsule_radius={capsule?.Radius} capsule_height={capsule?.Height} capsule_aabb={capsuleEnvelope} " +
                $"capsule_center={(GodotObject.IsInstanceValid(diagnosticCapsule) ? diagnosticCapsule.GlobalPosition.ToString() : "unavailable")} " +
                $"capsule_enabled={(GodotObject.IsInstanceValid(diagnosticCapsule) && !diagnosticCapsule.Disabled)} " +
                $"lane_valid={laneValid} lane_aabb={laneEnvelope} center_inside={centerInside} " +
                $"capsule_aabb_overlap={capsuleAabbOverlap} monitored_overlap={monitoredOverlap} " +
                $"lane_processing={(laneValid && diagnosticLane.IsPhysicsProcessing())} " +
                $"lane_monitoring={(laneValid && diagnosticLane.Monitoring)} " +
                $"lane_collider_enabled={(GodotObject.IsInstanceValid(laneCollider) && !laneCollider.Disabled)} " +
                $"lane_pulses={(laneValid ? diagnosticLane.PulseCount : -1)} " +
                $"lane_interval={(laneValid ? diagnosticLane.PulseIntervalSeconds : -1f):0.000} " +
                $"lane_damage={(laneValid ? diagnosticLane.Damage : -1)} lane_knockback={(laneValid ? diagnosticLane.Knockback : -1f)} " +
                $"arrival_active={(GodotObject.IsInstanceValid(group) && group.IsArrivalWarningActive)} " +
                $"actor={(actorValid ? liveActor.IsInsideTree() ? liveActor.GetPath().ToString() : "detached_actor" : "none")} " +
                $"actor_id={(actorValid ? liveActor.GetInstanceId() : 0)} " +
                $"actor_type={(actorValid ? liveActor.GetType().Name : "none")} " +
                $"actor_position={(actorValid ? liveActor.GlobalPosition.ToString() : "unavailable")} " +
                $"actor_state={actorState} actor_phase={actorPhase} hitbox_monitoring={hitboxMonitoring} " +
                $"hitbox_knockback={(GodotObject.IsInstanceValid(actorHitbox) ? actorHitbox.Knockback : -1f)} " +
                $"hitbox_collider_enabled={(GodotObject.IsInstanceValid(hitboxCollider) && !hitboxCollider.Disabled)} " +
                $"damage_impulse={(suppliedImpulse.HasValue ? suppliedImpulse.Value.ToString() : "not_supplied")}");
        }

        static Rect2 WorldEnvelope(CollisionShape2D collider, Vector2 halfSize)
        {
            Transform2D transform = collider.GlobalTransform;
            Rect2 envelope = new(transform * -halfSize, Vector2.Zero);
            envelope = envelope.Expand(transform * new Vector2(halfSize.X, -halfSize.Y));
            envelope = envelope.Expand(transform * halfSize);
            return envelope.Expand(transform * new Vector2(-halfSize.X, halfSize.Y));
        }

        Action<PlayerEnergyFrame> diagnosticEnergyChanged = _ => GearDiagnosticSnapshot("state");
        Action<bool> diagnosticShieldChanged = _ => GearDiagnosticSnapshot("state");
        int playerDamageEvents = 0;
        HealthComponent.DamagedEventHandler playerDamaged = (remaining, impulse) =>
        {
            playerDamageEvents++;
            if (counterweightSuppressionKeyboard)
                MixedResourceSnapshot("player_damaged_event", $"remaining_hp={remaining} impulse={impulse} request_source=unknown");
            GD.Print($"TASK10_PLAYER_DAMAGED id={encounterId} remaining={remaining} " +
                $"player={player.GlobalPosition} shield_held={input.Current.ShieldHeld} " +
                $"shield_active={shield.IsActive} frame={currentFrame}");
            GearDiagnosticSnapshot("damage", impulse);
            SteamSnapshot("player_damaged", true,
                $"remaining={remaining} damage_impulse={impulse}");
            if (SteamBellWindow())
            {
                steamBellDamageEvents++;
                steamBellLastDamagePhysics = Engine.GetPhysicsFrames();
                steamBellLastDamageSequence = steamBellSequence + 1;
                bool fatal = remaining == 0 && !steamBellFatalStack;
                SteamBellSnapshot("player_damaged_before_Died", $"remaining={remaining} impulse={impulse} attribution=pending", fatal);
                if (fatal)
                {
                    steamBellFatalStack = true;
                    string stack = System.Environment.StackTrace;
                    int retained = Math.Min(stack.Length, 32768);
                    GD.Print($"TASK10_STEAM_BELL_FATAL_STACK_BEGIN physics={Engine.GetPhysicsFrames()} seq={steamBellLastDamageSequence} " +
                        $"characters={stack.Length} retained={retained} truncated={retained != stack.Length}\n" +
                        stack[..retained] + "\nTASK10_STEAM_BELL_FATAL_STACK_END");
                }
            }
            CourtyardBellSnapshot("player-damaged", true);
            ObserveSplitBell("player-damaged", impulse: impulse);
        };
        CapsuleShape2D playerCapsule =
            (CapsuleShape2D)player.GetNode<CollisionShape2D>("BodyCollider").Shape;
        Rect2 arenaBounds = group.Definition.ArenaBounds;
        Rect2 activationBounds = group.Definition.ActivationBounds;
        PlayerCombat.AttackStartedEventHandler started = (_, _) =>
        {
            attacksStarted++;
            lastAttackStartedFrame = currentFrame;
            MixedResourceSnapshot("attack_started_after_spend");
            if (steamSentryDiagnostic && trackedSentry != null)
                SteamPolicyLog("attack_started", $"connected={attacksConnected}");
            CourtyardBellSnapshot("J-started");
            SteamBellSnapshot("player_J_started_after_spend");
        };
        PlayerCombat.AttackStartedEventHandler directionStarted = (_, direction) =>
            lastAttackDirection = direction;
        PlayerCombat.AttackConnectedEventHandler connected = _ =>
        {
            attacksConnected++;
            lastAttackConnectedFrame = currentFrame;
            if (steamSentryDiagnostic && trackedSentry != null)
                SteamPolicyLog("attack_connected", $"connected={attacksConnected}");
            CourtyardBellSnapshot("J-connected");
            SteamBellSnapshot("player_J_connected");
        };
        combat.AttackStarted += started;
        combat.AttackStarted += directionStarted;
        combat.AttackConnected += connected;
        playerHealth.Damaged += playerDamaged;
        SendAction(InputActions.SelectAttackMode, true);
        await PhysicsFrames(tree, monitor, 1);
        SendAction(InputActions.SelectAttackMode, false);
        try
        {
        if (counterweightSuppressionKeyboard)
        {
            energy.EnergyFrameChanged += mixedEnergyChanged;
            shield.ShieldFrameChanged += mixedShieldChanged;
            shield.ShieldResolved += mixedShieldResolved;
            MixedResourceSnapshot("entry_pre_node");
        }
        if (gearDiagnostic)
        {
            energy.EnergyFrameChanged += diagnosticEnergyChanged;
            shield.ShieldFrameChanged += diagnosticShieldChanged;
            GearDiagnosticSnapshot("entry");
        }
        if (steamSentryDiagnostic) shield.ShieldResolved += sentryShieldResolved;
        for (int frame = 0; frame < 900 && !group.IsComplete; frame++)
        {
            currentFrame = frame;
            if (steamSentryRecovery != null && steamSentryRecovery.TryFinishRetiredCounter())
            {
                // The encounter already removed its defeated Sentry. Complete
                // the real player's J2 tail using only original outer ticks.
                if (steamSentryRecovery.Completed)
                {
                    GD.Print($"STEAM_SENTRY_NORMAL_RETIRED_COUNTER_OK physics={Engine.GetPhysicsFrames()} " +
                        $"loop={frame} K={steamSentryRecovery.CastCommands} J={steamSentryRecovery.AttackCommands} " +
                        $"hp={playerHealth.CurrentHealth} original_budget=900 whole_goal=false");
                    steamSentryRecovery.Dispose();
                    steamSentryRecovery = null;
                }
                await PhysicsFrames(tree, monitor, 1);
                continue;
            }
            GearDiagnosticSnapshot("state");
            if (counterweightSuppressionRecovery) GuardCounterweightSuppression();
            if (!group.IsActive)
            {
                float reentryX = activationBounds.GetCenter().X;
                SendMouse(MouseButton.Right, false, player, player.GlobalPosition);
                SendAction(InputActions.MoveLeft, player.GlobalPosition.X > reentryX + 2f);
                SendAction(InputActions.MoveRight, player.GlobalPosition.X < reentryX - 2f);
                wasInStrikeRange = false;
                await PhysicsFrames(tree, monitor, 1);
                continue;
            }
            if (counterweightSuppressionKeyboard && !counterweightSuppressionRecovery &&
                group.CurrentBatch == 1 && group.LiveActorCount == 0 && group.SpawnSuppressed)
            {
                counterweightSuppressionFloor = group.GetNode<StaticBody2D>("../../Collision/LiftBackLanding");
                counterweightSuppressionFloorShape =
                    counterweightSuppressionFloor.GetNode<CollisionShape2D>("Collision");
                counterweightSuppressionMotor = player.GetNode<PlayerMotor>("Motor");
                counterweightSuppressionHealth = playerHealth.CurrentHealth;
                counterweightSuppressionJumps = counterweightSuppressionMotor.AcceptedJumpCount;
                counterweightSuppressionDashes = counterweightSuppressionMotor.AcceptedDashCount;
                counterweightSuppressionTelegraphPhysics = 0;
                counterweightSuppressionSettledLogged = false;
                counterweightSuppressionRecovery = true;
                KeyboardRouteInputDriver.Current.ReleaseAll(); // Actual key releases, not state/velocity writes.
                wasInStrikeRange = false;
                GuardCounterweightSuppression();
                LogCounterweightSuppression("actual_suppression_observed_release_old_inputs");
            }
            if (counterweightSuppressionRecovery)
            {
                GuardCounterweightSuppression();
                float rate = Engine.PhysicsTicksPerSecond;
                float deceleration = counterweightSuppressionMotor.Tuning.GroundDeceleration;
                TestAssert.True(float.IsFinite(rate) && rate > 0f &&
                    float.IsFinite(deceleration) && deceleration > 0f,
                    "RANGED_COUNTERWEIGHT_SUPPRESSION_RED requires actual positive braking tuning/rate");
                if (group.IsArrivalWarningActive && counterweightSuppressionTelegraphPhysics == 0)
                {
                    counterweightSuppressionTelegraphPhysics = Engine.GetPhysicsFrames();
                    LogCounterweightSuppression("fresh_arrival_telegraph_first_pre_node_sample");
                }
                if (group.LiveActorCount > 0)
                {
                    ulong observedTicks = counterweightSuppressionTelegraphPhysics == 0 ? 0 :
                        Engine.GetPhysicsFrames() - counterweightSuppressionTelegraphPhysics;
                    TestAssert.True(group.LiveActorCount == 2 && !group.IsArrivalWarningActive &&
                        counterweightSuppressionTelegraphPhysics != 0 && CounterweightSuppressionSettled() &&
                        observedTicks + 1 >= (ulong)Mathf.CeilToInt(.60f * rate),
                        "RANGED_COUNTERWEIGHT_SUPPRESSION_RED resumes only after observed fresh native " +
                        "arrival lifecycle, both mixed actors and an actually neutral 4700+-6 stance");
                    // Both boundaries are pre-node samples, not warning-node entry/actor Ready.
                    // The independent native suppression test, not this interval, proves .60s.
                    GD.Print($"RANGED_COUNTERWEIGHT_ARRIVAL_INTERVAL observed_ticks={observedTicks} " +
                        $"rate={rate:R} lower_seconds={Mathf.Max(0f, observedTicks - 1f) / rate:R} " +
                        $"upper_seconds={(observedTicks + 1f) / rate:R} " +
                        "sample_boundary=SceneTree_PhysicsFrame_pre_node independent_full_060_proof=false");
                    LogCounterweightSuppression("native_mixed_arrival_resume_original_combat");
                    counterweightSuppressionRecovery = false;
                    SendAction(InputActions.SelectAttackMode, true);
                    SendAction(InputActions.SelectAttackMode, false);
                    // Fall through to the unmodified first-child combat policy this same iteration.
                }
                else
                {
                    float delta = 4700f - player.GlobalPosition.X;
                    float towardSpeed = Mathf.Max(0f, Mathf.Sign(delta) * player.Velocity.X);
                    // Read-only stop estimate drives A/D release; actual sampled pose/support wins.
                    float brakingDistance = towardSpeed * towardSpeed / (2f * deceleration) +
                        towardSpeed / rate + 1f;
                    bool advance = Mathf.Abs(delta) > 3f &&
                        (towardSpeed <= 0f || Mathf.Abs(delta) > brakingDistance);
                    SendAction(InputActions.MoveLeft, advance && delta < 0f);
                    SendAction(InputActions.MoveRight, advance && delta > 0f);
                    if (CounterweightSuppressionSettled() && !counterweightSuppressionSettledLogged)
                    {
                        counterweightSuppressionSettledLogged = true;
                        LogCounterweightSuppression("actual_neutral_supported_center_stance");
                    }
                    counterweightSuppressionIterations++;
                    await PhysicsFrames(tree, monitor, 1); // Exactly one existing900-loop iteration, no inner budget.
                    GuardCounterweightSuppression();
                    continue;
                }
            }
            Node2D actor = actorRoot.GetChildren().OfType<Node2D>()
                .FirstOrDefault(candidate => candidate.Name.ToString().StartsWith(
                    encounterId.Replace('.', '_'), StringComparison.Ordinal));
            if (!GodotObject.IsInstanceValid(actor))
            {
                await PhysicsFrames(tree, monitor, 1);
                continue;
            }
            if (steamSentryDiagnostic && trackedSentry == null && actor is BellBoltSentry sentry)
            {
                trackedSentry = sentry;
                sentryStartPhysics = Engine.GetPhysicsFrames();
                sentryIdentity = $"{sentry.GetPath()}#{sentry.GetInstanceId()}";
                sentry.FrameChanged += sentryFrameChanged;
                ObserveSteamBolt();
                SteamSnapshot("admission");
            }
            if (skitterDiagnostic && trackedSkitter == null && actor is CanyonSkitter skitter)
            {
