                skitterStartPhysics = Engine.GetPhysicsFrames();
                skitterIdentity = $"{skitter.GetPath()}#{skitter.GetInstanceId()}";
                rushHitbox = skitter.GetNodeOrNull<Hitbox>("RushHitbox");
                skitterPlayerHurtbox = player.GetNodeOrNull<Hurtbox>("Hurtbox");
                if (DiagnosticLive(rushHitbox)) rushIdentity = $"{rushHitbox.GetPath()}#{rushHitbox.GetInstanceId()}";
                if (DiagnosticLive(skitterPlayerHurtbox))
                {
                    skitterPlayerHurtboxId = skitterPlayerHurtbox.GetInstanceId();
                    skitterHurtboxIdentity = $"{skitterPlayerHurtbox.GetPath()}#{skitterPlayerHurtboxId}";
                }
                skitter.FrameChanged += skitterFrameChanged;
                if (DiagnosticLive(rushHitbox)) rushHitbox.Connected += rushConnected;
                playerHealth.Damaged += skitterPlayerDamaged;
                shield.ShieldResolved += skitterShieldResolved;
                lastSkitterFrame = skitter.CurrentFrame;
                skitterObservedFrame = true;
                if (lastSkitterFrame.State == CanyonSkitterState.Rush)
                {
                    lastRushAttackId = lastSkitterFrame.AttackTimeline.AttackId;
                    lastRushPhysics = Engine.GetPhysicsFrames();
                }
