            Vector2 target = actor.GlobalPosition;
            if (actor is BellBackLaborer observedSplitBell) ObserveSplitBell("state", observedSplitBell);
            lastActorPosition = target;
            lastEnemyHealth = enemyHealth?.CurrentHealth;
            float dx = target.X - player.GlobalPosition.X;
            float dy = target.Y - player.GlobalPosition.Y;
