                                        $"stance_x={stanceX:R} stance_delta={error:R} braking={braking:R} " +
                                        $"stop_x={stopX:R} forecast_steps={stop.Steps} direction={direction}");
                                }
                            }
                            courtyardBellNeutralSequence = input.CurrentFrameSequence;
                        }
                        else if (courtyardBellSpacingPhase == 1)
                        {
                            courtyardBellSpacingPhase = 2;
                            CourtyardBellSnapshot("rearm-spacing-stopped", detail:
                                $"stance_x={stanceX:R} stance_delta={error:R} braking={braking:R} stop_x={stopX:R}");
                        }
                    }
