                            $"target={courtyardBellTarget.GetPath()} target_id={courtyardBellTarget.GetInstanceId()} " +
                            $"target_anchor={courtyardBellTarget.WorldAnchor} planned={courtyardBellPlanned} " +
                            $"available={targetAvailable} eligible={receiverEligible} receiver_is_bell={receiver == openingBell} " +
                            $"receiver_id={(GodotObject.IsInstanceValid(receiver) ? receiver.GetInstanceId() : 0UL)} " +
                            $"bell_id={openingBell.GetInstanceId()} selected={selection.Surface?.GetPath()} " +
                            $"selected_id={selection.Snapshot.RuntimeId} selected_exists={selection.Snapshot.Exists} " +
                            $"selected_anchor={selection.Snapshot.WorldAnchor} selected_los={selection.Snapshot.HasLineOfSight} " +
                            $"selected_legacy={selection.Snapshot.IsLegacyInteraction} selected_material={selection.Snapshot.Material}");
                        TestAssert.True(targetAvailable && receiverEligible && receiver == openingBell &&
                            enemyHealth?.CurrentHealth > 0 &&
                            selection.Surface == courtyardBellTarget && selection.Snapshot.RuntimeId == courtyardBellTarget.GetInstanceId() &&
                            selection.Snapshot.HasLineOfSight && selection.Snapshot.IsLegacyInteraction &&
                            (courtyardBellCycle == 1 || input.KeyboardAimDirection.Dot(courtyardBellPlanned) > .99f),
                            "keyboard courtyard opening has the exact live Bell native keyboard target and LOS");
                        if (courtyardBellCycle == 1) courtyardBellCastStanceX = player.GlobalPosition.X;
                        courtyardBellCast = courtyardBellClaw.CurrentFrame.NextCastId;
                        courtyardBellIssueSequence = courtyardBellLastSequence = input.CurrentFrameSequence;
                        SendAction(InputActions.SelectGrappleMode, true);
                        SendAction(InputActions.SelectGrappleMode, false);
                        courtyardBellIssued = true;
                        SendMouse(MouseButton.Left, true, player, courtyardBellTarget.WorldAnchor);
                        CourtyardBellSnapshot("opening-K-issued");
                    }
                }
                else
                {
                    if (input.CurrentFrameSequence > courtyardBellLastSequence)
                    {
                        courtyardBellLastSequence = input.CurrentFrameSequence;
                        if (input.CurrentFrame.ClawPressed)
                        {
                            courtyardBellEdges++;
                            courtyardBellEdgeSequence = input.CurrentFrameSequence;
                            TestAssert.True(courtyardBellEdges == 1 && input.CurrentFrame.KeyboardActions &&
                                input.KeyboardAimDirection.Dot(courtyardBellPlanned) > .999f &&
                                !input.CurrentFrame.AttackPressed && !input.CurrentFrame.ShieldHeld && !input.CurrentFrame.PrimaryPressed,
                                "keyboard courtyard opening samples exactly one real K/octant without J/L or legacy primary");
                            SendAction(InputActions.PrimaryAction, false);
                            SendAction(InputActions.Claw, false);
                            courtyardBellKeyReleased = true;
                            CourtyardBellSnapshot("opening-K-sampled-released");
                        }
                    }
                    TestAssert.True(!courtyardBellInvalidReceipt && courtyardBellClaw.CurrentFrame.Failure == MechanicalClawFailure.None &&
                        KeyboardRouteInputDriver.Current.ClawEdges == courtyardBellRawEdges + 1 &&
                        courtyardBellAdapter.ApplicationCount <= courtyardBellApplications + 1 &&
                        courtyardBellClaw.CurrentFrame.NextCastId >= courtyardBellCast &&
                        courtyardBellClaw.CurrentFrame.NextCastId <= courtyardBellCast + 1,
                        "keyboard courtyard opening never fails, repeats K/cast, or applies a second interaction");
                    if (courtyardBellReceipt && courtyardBellReleased && courtyardBellKeyReleased &&
                        Engine.GetPhysicsFrames() > courtyardBellReceiptPhysics &&
                        openingBell.CurrentState == BellBackLaborerState.Exposed &&
                        openingBell.GetNode<Hurtbox>("Hurtbox").DamageReceiverPath == new NodePath("../Health"))
                    {
                        TestAssert.True(courtyardBellEdges == 1 && courtyardBellEdgeSequence > courtyardBellIssueSequence &&
                            courtyardBellReceiptSequence >= courtyardBellEdgeSequence &&
                            courtyardBellAdapter.ApplicationCount == courtyardBellApplications + 1 &&
                            courtyardBellClaw.CurrentFrame.NextCastId == courtyardBellCast + 1 &&
                            !input.CurrentFrame.ClawPressed && !input.CurrentFrame.AttackPressed && !input.CurrentFrame.ShieldHeld &&
                            !Input.IsPhysicalKeyPressed(Key.J) && !Input.IsPhysicalKeyPressed(Key.K) && !Input.IsPhysicalKeyPressed(Key.L),
                            "keyboard courtyard opening independently observes one same-cast adapter receipt then real Health-exposed Bell before J");
                        courtyardBellComplete = true;
                        threadCasts++;
                        SendAction(InputActions.SelectAttackMode, true);
                        SendAction(InputActions.SelectAttackMode, false);
                        CourtyardBellSnapshot("opening-independent-exposed");
                    }
                }
                wasInStrikeRange = false;
                await PhysicsFrames(tree, monitor, 1);
                continue;
            }
            if (courtyardBellComplete && actor == courtyardBell)
            {
                string state = $"{courtyardBell.CurrentState}/{enemyHealth?.CurrentHealth}/{input.CurrentFrame.ShieldHeld}/{shield.IsActive}";
                if (state != courtyardBellLastState)
                {
                    courtyardBellLastState = state;
                    CourtyardBellSnapshot("combat-state");
                }
            }
            bool sentryPolicy = steamSentryDiagnostic && actor is BellBoltSentry;
            bool sentryGuardRequired = false;
            bool sentryAttackWouldOverlapGuard = false;
            bool sentryCounterEnergyReady = false;
            Vector2 sentryGuardSource = target;
            bool skitterPolicy = skitterDiagnostic && actor is CanyonSkitter;
            bool skitterThreat = false, skitterGuardRequired = false, skitterCanCounter = false;
            Vector2 skitterGuardSource = target;
            if (skitterPolicy)
            {
                CanyonSkitter liveSkitter = (CanyonSkitter)actor;
                CanyonSkitterFrame observed = liveSkitter.CurrentFrame;
                AttackTimelineFrame timeline = observed.AttackTimeline;
                bool monitoring = DiagnosticLive(rushHitbox) && rushHitbox.Monitoring;
                skitterThreat = observed.State is CanyonSkitterState.Telegraph or CanyonSkitterState.Rush || monitoring;
                skitterGuardRequired = (timeline.Phase == AttackPhase.Telegraph &&
                    timeline.PhaseRemainingSeconds <= .20f) || observed.State == CanyonSkitterState.Rush || monitoring;
                skitterGuardSource = DiagnosticLive(rushHitbox) ? rushHitbox.GlobalPosition : target;
                if (!Mathf.IsZeroApprox(dx)) desiredActorSide = Mathf.Sign(dx);
                if (skitterGuardRequired)
                {
                    skitterReleaseRequested = skitterReleaseSampled = false;
                    if (!skitterGuardRequested)
                    {
                        skitterGuardRequested = true;
                        skitterGuardAcknowledged = false;
                        skitterGuardSamples = 0;
                        skitterGuardSequence = skitterLastGuardSequence = input.CurrentFrameSequence;
                        SkitterPolicyLog("guard_request", $"source={skitterGuardSource}");
                    }
                    if (input.CurrentFrameSequence > skitterLastGuardSequence)
                    {
                        skitterLastGuardSequence = input.CurrentFrameSequence;
                        skitterGuardSamples++;
                        Vector2 direction = skitterGuardSource - player.GlobalPosition;
                        float dot = direction.LengthSquared() > 1f
                            ? shield.GuardDirection.Dot(direction.Normalized()) : -1f;
                        bool sampled = input.Current.ShieldHeld && shield.IsActive && dot >= .9f;
                        if (sampled && !skitterGuardAcknowledged)
                        {
                            skitterGuardAcknowledged = true;
                            SkitterPolicyLog("guard_sampled", $"request_sample={skitterGuardSequence} dot={dot:0.000}");
                        }
                        if (!sampled && (skitterGuardAcknowledged || skitterGuardSamples >= 6))
                            throw new InvalidOperationException($"Task10 Skitter required guard not sampled/sustained; " +
                                $"physics={Engine.GetPhysicsFrames()} loop={frame} request_sample={skitterGuardSequence} " +
                                $"sample={input.CurrentFrameSequence} observed={skitterGuardSamples} state={observed.State} " +
                                $"phase={timeline.Phase} remaining={timeline.PhaseRemainingSeconds:0.000} monitoring={monitoring} " +
                                $"source={skitterGuardSource} player={player.GlobalPosition} held={input.Current.ShieldHeld} " +
                                $"active={shield.IsActive} direction={shield.GuardDirection} dot={dot:0.000} " +
                                $"hp={playerHealth.CurrentHealth} energy={energy.EnergyRatio:0.000} " +
                                $"heat={energy.HeatRatio:0.000} overheated={energy.IsOverheated}");
                    }
                }
                else
                {
                    if (skitterGuardRequested) SkitterPolicyLog("guard_cleared");
                    skitterGuardRequested = skitterGuardAcknowledged = false;
                    if (!skitterReleaseRequested)
                    {
                        skitterReleaseRequested = true;
                        skitterReleaseSampled = false;
                        skitterReleaseSequence = input.CurrentFrameSequence;
                    }
                    if (!skitterReleaseSampled && input.CurrentFrameSequence > skitterReleaseSequence &&
                        !input.Current.ShieldHeld && !shield.IsActive)
                    {
                        skitterReleaseSampled = true;
                        SkitterPolicyLog("release_sampled", $"request_sample={skitterReleaseSequence}");
                    }
                }
                PlayerCombatSettings attackSettings = combat.Tuning.ToCombatSettings();
                float attackSeconds = attackSettings.StartupSeconds + attackSettings.ActiveSeconds + attackSettings.RecoverySeconds;
                float reserve = energy.Tuning.ShieldDrainPerSecond * (.20f + liveSkitter.Settings.RushSeconds + 3f / 60f);
                skitterCanCounter = !skitterThreat && observed.State == CanyonSkitterState.Recover &&
                    timeline.Phase == AttackPhase.Recovery && timeline.AttackId != 0 &&
                    timeline.PhaseRemainingSeconds >= attackSeconds + 2f / 60f && !monitoring &&
                    skitterReleaseSampled && !input.Current.ShieldHeld && !shield.IsActive &&
                    !energy.IsOverheated && energy.EnergyRatio * energy.Tuning.MaxEnergy >= energy.Tuning.AttackCost + reserve;
            }
            if (sentryPolicy)
            {
                BellBoltSentry liveSentry = (BellBoltSentry)actor;
                ObserveSteamBolt();
                BellBoltProjectile liveBolt = liveSentry.GetChildren()
                    .OfType<BellBoltProjectile>().FirstOrDefault(candidate =>
                        GodotObject.IsInstanceValid(candidate) && candidate.IsInsideTree() &&
                        !candidate.IsRetired);
                if (sentryBoltWasLive && liveBolt == null)
                {
                    steamSentryBoltRetired = true;
                    SteamPolicyLog("bolt_retired", $"bolt={boltIdentity}");
                }
                sentryBoltWasLive = liveBolt != null;
                Node2D muzzle = liveSentry.GetNodeOrNull<Node2D>("Muzzle");
                sentryGuardSource = liveBolt?.GlobalPosition ?? muzzle?.GlobalPosition ?? target;
                if ((sentryGuardSource - player.GlobalPosition).LengthSquared() <= 1f)
                    sentryGuardSource = muzzle?.GlobalPosition ?? target;
                BellBoltSentryFrame sentryFrame = liveSentry.CurrentFrame;
                AttackTimelineFrame timeline = sentryFrame.AttackTimeline;
                sentryGuardRequired = (timeline.Phase == AttackPhase.Telegraph &&
                    timeline.PhaseRemainingSeconds <= .40f) ||
                    sentryFrame.State == BellBoltSentryState.Fire || liveBolt != null;
                // A full .30s player attack must finish before the .40s guard window.
                sentryAttackWouldOverlapGuard = timeline.Phase == AttackPhase.Telegraph &&
                    timeline.PhaseRemainingSeconds <= .70f;
                sentryCounterEnergyReady = SentryCounterEnergyBudget.CanSpendAttack(
                    energy.EnergyRatio * energy.Tuning.MaxEnergy, energy.Tuning.ToSettings(),
                    liveSentry.Settings, Engine.PhysicsTicksPerSecond);
                if (!sentryCounterEnergyReady && !sentryGuardRequired && frame % 30 == 0)
                    SteamPolicyLog("counter_energy_reserved", $"energy={energy.EnergyRatio:0.000}");
                if (!Mathf.IsZeroApprox(dx)) desiredActorSide = Mathf.Sign(dx);
                if (sentryGuardRequired)
                {
                    sentryReleaseRequested = false;
                    sentryReleaseSampled = false;
                    if (!sentryGuardRequested)
                    {
                        sentryGuardRequested = true;
                        sentryGuardAcknowledged = false;
                        sentryGuardSamples = 0;
                        sentryGuardRequestSequence = input.CurrentFrameSequence;
                        sentryLastGuardSample = sentryGuardRequestSequence;
                        SteamPolicyLog("guard_request", $"state={sentryFrame.State} " +
                            $"phase={timeline.Phase} remaining={timeline.PhaseRemainingSeconds:0.000} " +
                            $"bolt={(liveBolt != null)} source={sentryGuardSource}");
                    }
                    if (input.CurrentFrameSequence > sentryLastGuardSample)
                    {
                        sentryLastGuardSample = input.CurrentFrameSequence;
                        sentryGuardSamples++;
                        Vector2 sourceDirection = sentryGuardSource - player.GlobalPosition;
                        bool correctDirection = sourceDirection.LengthSquared() > 1f &&
                            shield.GuardDirection.Dot(sourceDirection.Normalized()) >= .9f;
                        bool sampledGuard = input.Current.ShieldHeld && shield.IsActive &&
                            correctDirection;
                        if (sampledGuard && !sentryGuardAcknowledged)
                        {
                            sentryGuardAcknowledged = true;
                            SteamPolicyLog("guard_sampled", $"request_sample={sentryGuardRequestSequence} " +
                                $"observed={sentryGuardSamples} source={sentryGuardSource}");
                        }
                        if (!sampledGuard && (sentryGuardAcknowledged || sentryGuardSamples >= 6))
                            throw new InvalidOperationException($"Task10 Sentry required guard " +
                                $"not sampled/sustained; physics={Engine.GetPhysicsFrames()} " +
                                $"request_sample={sentryGuardRequestSequence} " +
                                $"sample={input.CurrentFrameSequence} observed={sentryGuardSamples} " +
                                $"state={sentryFrame.State} phase={timeline.Phase} " +
                                $"remaining={timeline.PhaseRemainingSeconds:0.000} " +
                                $"bolt={(liveBolt != null)} source={sentryGuardSource} " +
                                $"player={player.GlobalPosition} held={input.Current.ShieldHeld} " +
                                $"active={shield.IsActive} direction={shield.GuardDirection} " +
                                $"correct={correctDirection} hp={playerHealth.CurrentHealth} " +
                                $"energy={energy.EnergyRatio:0.000} heat={energy.HeatRatio:0.000} " +
                                $"overheated={energy.IsOverheated}");
                    }
                }
                else
                {
                    if (sentryGuardRequested)
                        SteamPolicyLog("guard_cleared", $"state={sentryFrame.State} " +
                            $"phase={timeline.Phase} bolt={(liveBolt != null)}");
                    sentryGuardRequested = false;
                    sentryGuardAcknowledged = false;
                    if (!sentryReleaseRequested)
                    {
                        sentryReleaseRequested = true;
                        sentryReleaseSampled = false;
                        sentryReleaseRequestSequence = input.CurrentFrameSequence;
                        SteamPolicyLog("release_request", $"state={sentryFrame.State}");
                    }
                    if (!sentryReleaseSampled &&
                        input.CurrentFrameSequence > sentryReleaseRequestSequence &&
                        !input.Current.ShieldHeld && !shield.IsActive)
                    {
                        sentryReleaseSampled = true;
                        SteamPolicyLog("release_sampled", $"request_sample={sentryReleaseRequestSequence}");
                    }
                }
            }
            bool steamSentryKeyboard = (tree is RunRealtimePrologueProbe || headlessNormalPlan) &&
                KeyboardRouteInputDriver.Current != null && steamSentryDiagnostic &&
                group.CurrentBatch == 1 && group.LiveActorCount == 1 && actor is BellBoltSentry &&
                actor.SceneFilePath == "res://scenes/enemies/BellBoltSentry.tscn";
            if (steamSentryKeyboard)
            {
                if (steamSentryRecovery != null && steamSentryRecovery.SentryId != actor.GetInstanceId())
                {
                    steamSentryRecovery.Dispose();
                    steamSentryRecovery = null;
                    steamRecoveryAttackCommands = steamRecoveryCastCommands = 0;
                    steamSentryBoltRetired = false;
                }
                steamSentryRecovery ??= new SteamSentryRecoveryDriver(player, (BellBoltSentry)actor,
                    KeyboardRouteInputDriver.Current);
                if (steamSentryRecovery.TryDrive(steamSentryBoltRetired, 900 - frame))
                {
                    attacks += steamSentryRecovery.AttackCommands - steamRecoveryAttackCommands;
                    threadCasts += steamSentryRecovery.CastCommands - steamRecoveryCastCommands;
                    steamRecoveryAttackCommands = steamSentryRecovery.AttackCommands;
                    steamRecoveryCastCommands = steamSentryRecovery.CastCommands;
                    await PhysicsFrames(tree, monitor, 1); // One original900 iteration, never an inner wait budget.
                    continue;
                }
            }
            else if (steamSentryRecovery != null)
            {
                steamSentryRecovery.Dispose();
                steamSentryRecovery = null;
            }
            float signedGap = dx * desiredActorSide;
            bool frozenRustPolicy = frozenLowerKeyboard && actor is RustShellSquire;
            if (frozenRustPolicy)
                TestAssert.True(playerHealth.CurrentHealth == playerHealthAtStart &&
                    monitor.RecoveryRequested == frozenLowerRequests &&
                    monitor.RecoveryCompleted == startingRecoveries &&
                    frozenLowerMotor.AcceptedJumpCount == frozenLowerJumps &&
                    frozenLowerMotor.AcceptedDashCount == frozenLowerDashes &&
                    TryTask10CapsuleCorridor(player, frozenLowerFloorShape, out _, out _, out _, out _) &&
                    HasFloorContact(player, frozenLowerFloor),
                    "keyboard frozen-lower Rust approach retains full actual FrozenExit support, HP and no jump/dash/recovery");
            lastDx = dx;
            lastDy = dy;
            lastSignedGap = signedGap;
            bool isMoth = actor is GraveLampMoth;
            bool splitMothPolicy = splitBellKeyboard && isMoth;
            if (isMoth && !Mathf.IsZeroApprox(dx))
            {
                desiredActorSide = Mathf.Sign(dx);
                signedGap = Math.Abs(dx);
                lastSignedGap = signedGap;
            }
            bool verticalStrike = dy is >= -74f and <= -10f &&
                                  Math.Abs(dx) <= (isMoth ? 36f : 30f);
            bool horizontalStrike = Math.Abs(dy) <= (isMoth ? 32f : 46f) &&
                                    signedGap is >= 8f and <= 64f;
            if (frozenRustPolicy) horizontalStrike &= signedGap >= 55f;
            bool strikeRange = verticalStrike || horizontalStrike;
            Task10EncounterDanger encounterDanger = Task10ObserveEncounterDanger(actorRoot, encounterId,
                actor, skitterThreat, rangedThreatLeaves);
            bool enemyThreat = encounterDanger.Threat;
            if (SteamBellWindow())
            {
                steamBellLastDanger = encounterDanger;
                steamBellDangerSequence = input.CurrentFrameSequence;
            }
            bool steamMissileKeyboard = (tree is RunRealtimePrologueProbe || headlessNormalPlan) && KeyboardRouteInputDriver.Current != null &&
                steamSentryDiagnostic && group.CurrentBatch == 2 && group.LiveActorCount == 1 &&
                actor is FurnaceMissileGunner && actor.SceneFilePath == CanyonEncounterCatalog.MissileScene;
            Task10SteamMissileDecision steamDecision = steamMissileKeyboard
                ? Task10SteamMissileKeyboardDecision(player, (RangedWeaponEnemy)actor, combat, energy, shield,
                    encounterDanger, strikeRange, frame, nextAttackFrame, rangedThreatLeaves) : default;
            bool skitterEligible = skitterPolicy && skitterCanCounter && strikeRange &&
                frame >= nextAttackFrame && !combat.IsAttacking && modes.CanAffordAttack && modes.CanBeginAttack;
            if (skitterEligible != skitterCounterEligible)
                SkitterPolicyLog("counter_eligibility", $"eligible={skitterEligible} strike_range={strikeRange}");
            skitterCounterEligible = skitterEligible;
            if (strikeRange && !wasInStrikeRange)
            {
                strikeBandEntries++;
                GD.Print($"TASK10_ATTACK_BAND_ENTRY id={encounterId} frame={frame} " +
                    $"dx={dx:0.000} dy={dy:0.000} signed_gap={signedGap:0.000} " +
                    $"side={desiredActorSide:0} velocity={player.Velocity} " +
                    $"floor={DescribeFloorCollider(player)} sample={input.CurrentFrameSequence} " +
                    $"actor_type={actor.GetType().Name} actor_velocity=" +
                    $"{(actor is CharacterBody2D bandBody ? bandBody.Velocity : Vector2.Zero)} " +
                    $"actor_floor={(actor is CharacterBody2D bandActorBody && bandActorBody.IsOnFloor())} " +
                    $"moth_state={(actor is GraveLampMoth bandMoth ? bandMoth.CurrentState.ToString() : "n/a")} " +
                    $"mode={modes.CurrentMode} slot={modes.ActiveSlot} " +
                    $"can_attack={modes.CanBeginAttack} shield_held={input.Current.ShieldHeld} " +
                    $"shield_active={shield.IsActive} energy={energy.EnergyRatio:0.000}");
            }
            wasInStrikeRange = strikeRange;
            bool moveLeft = verticalStrike
                ? dx < -20f
                : signedGap < 8f ? desiredActorSide > 0f :
                    signedGap > 64f && desiredActorSide < 0f;
            bool moveRight = verticalStrike
                ? dx > 20f
                : signedGap < 8f ? desiredActorSide < 0f :
                    signedGap > 64f && desiredActorSide > 0f;
            if (KeyboardRouteInputDriver.Current != null && skitterPolicy && !skitterThreat &&
                ((CanyonSkitter)actor).CurrentFrame.AttackTimeline.Phase != AttackPhase.Recovery)
            {
                // WASD is shared with shield aim. The old pointer strategy could stand
                // 50 units away and aim down-left without moving; A+S+L cannot. Bait
                // the real rush from farther away instead of cancelling its telegraph
                // by walking inside the production 34-unit minimum. Real recovery
                // still uses the original melee approach and counter-window checks.
                moveLeft = signedGap < 100f ? desiredActorSide > 0f :
                    signedGap > 110f && desiredActorSide < 0f;
                moveRight = signedGap < 100f ? desiredActorSide < 0f :
                    signedGap > 110f && desiredActorSide > 0f;
            }
            bool cooldownRetreat = !steamMissileKeyboard && !sentryPolicy && !skitterPolicy && !frozenRustPolicy && !courtyardBellPolicy && !splitBellPolicy &&
                                   strikeRange && !combat.IsAttacking &&
                                   frame < nextAttackFrame;
            if (cooldownRetreat)
            {
                moveLeft = desiredActorSide > 0f;
                moveRight = desiredActorSide < 0f;
            }
            float arenaMinimumX = arenaBounds.Position.X + playerCapsule.Radius + 2f;
            float arenaMaximumX = arenaBounds.End.X - playerCapsule.Radius - 2f;
            if (player.GlobalPosition.X <= arenaMinimumX && moveLeft)
            {
                moveLeft = false;
                moveRight = !cooldownRetreat;
            }
            if (player.GlobalPosition.X >= arenaMaximumX && moveRight)
            {
                moveRight = false;
                moveLeft = !cooldownRetreat;
            }
            if (sentryGuardRequired || skitterThreat) moveLeft = moveRight = false;
            bool generalDefendWindow = Task10GeneralDefendWindow(combat, energy,
                enemyThreat, strikeRange, frame, nextAttackFrame);
            if (SteamBellWindow()) steamBellDecision = $"generic_guard={generalDefendWindow} strike={strikeRange} " +
                $"move_LR={moveLeft}/{moveRight} next_J={nextAttackFrame} sample={input.CurrentFrameSequence}";
            if (steamMissileKeyboard) generalDefendWindow = steamDecision.Defend;
            if ((tree is RunRealtimePrologueProbe || headlessNormalPlan) && KeyboardRouteInputDriver.Current != null &&
                encounterId == "canyon.v2.encounter.pendulum-gallery" && group.CurrentBatch == 2 &&
                group.LiveActorCount == 1 && actor is PrismLaserGunner &&
                actor.SceneFilePath == CanyonEncounterCatalog.LaserScene)
                generalDefendWindow = Task10GalleryLaserDefendWindow(combat, energy, shield,
                    encounterDanger, strikeRange, frame, nextAttackFrame);
            if (counterweightSuppressionKeyboard && encounterDanger.HasRanged)
                generalDefendWindow = Task10MixedDefendWindow(shield, encounterDanger);
            if (splitMothPolicy)
            {
                // No idle L or periodic jump while preparing K. Guard actual attack
                // windows instead; the normal shield still owns availability/contact.
                generalDefendWindow = !combat.IsAttacking && shield.CanBeginGuard && enemyThreat;
                if (!enemyThreat) SendMouse(MouseButton.Right, false, player, target);
            }
            if (splitBellPolicy)
            {
                // The observed Exposed phase cannot attack. Idle L used energy and
                // changed A/D aiming in the RED; release it instead of holding guard.
                generalDefendWindow = false;
                SendMouse(MouseButton.Right, false, player, target);
            }
            if (courtyardBellPolicy)
            {
                TestAssert.True(courtyardBellExposed && !((BellBackLaborer)actor).CurrentFrame.AttackActive,
                    "keyboard courtyard J phase is the actual non-attacking Health-exposed Bell");
                // Exposed has no enemy attack to guard. Preserve energy with real L release,
                // and keep the existing strike stance rather than its generic cooldown retreat.
                generalDefendWindow = false;
                if (strikeRange) moveLeft = moveRight = false;
                SendMouse(MouseButton.Right, false, player, target);
            }
            bool frozenMothPolicy = frozenLowerKeyboard && actor is GraveLampMoth;
            ulong frozenMothCommandSequence = input.CurrentFrameSequence;
            if (frozenMothPolicy)
            {
                // The old test reserve (.35) skipped a legal normal guard at .350
                // energy. Request only the real late telegraph/dive window; the
                // production shield still decides sustain, direction and contact.
                GraveLampMoth guardMoth = (GraveLampMoth)actor;
                generalDefendWindow = !combat.IsAttacking && shield.CanBeginGuard &&
                    (guardMoth.CurrentState == GraveLampMothState.Dive ||
                     guardMoth.CurrentState == GraveLampMothState.Telegraph &&
                     guardMoth.CurrentFrame.AttackTimeline.PhaseRemainingSeconds <= .12f);
            }
            if (KeyboardRouteInputDriver.Current != null && !skitterPolicy && generalDefendWindow &&
                !(steamMissileKeyboard && steamDecision.AllowShieldApproach))
                moveLeft = moveRight = false;
            bool frozenRustReady = true;
            if (frozenRustPolicy)
            {
                // J and L share real A/D facing. Keep the original melee range's
                // outer portion: inside 34px the hitbox, unlike the actor origin,
                // can be behind the player's actor-facing shield. Brake with real
                // input before entering 55..64, then sample an inward-facing stop.
                float stanceX = target.X - desiredActorSide * 60f;
                float error = stanceX - player.GlobalPosition.X;
                float vx = player.Velocity.X;
                var stop = FreeMotionForecast.Neutral(vx, true, frozenLowerMotor.MotionSettings,
                    frozenLowerMotor.ThrusterState.Module, 1d / Engine.PhysicsTicksPerSecond,
                    900 - frame, 2f);
                TestAssert.True(stop.SpeedThresholdReached,
                    "frozen Rust neutral stance forecast fits the remaining original900 budget");
                float stopX = player.GlobalPosition.X + stop.NetDistance;
                float braking = stop.NetDistance;
                // Commit to neutral while its actual discrete endpoint is in the
                // original stance band; do not steer by current position alone.
                int direction = MathF.Abs(stanceX - stopX) <= 1.5f ? 0 : MathF.Sign(stanceX - stopX);
                // L uses the same real A/D aim. It cannot guard inward while
                // backpedalling outward; coast, then correct in a safe window.
                if (enemyThreat && direction == -(int)desiredActorSide) direction = 0;
                bool inwardFacing = input.KeyboardAimDirection.Dot(Vector2.Right * desiredActorSide) > .99f;
                if (direction == 0 && MathF.Abs(vx) <= 2f && !inwardFacing)
                    direction = (int)desiredActorSide;
                moveLeft = direction < 0;
                moveRight = direction > 0;
                frozenRustReady = horizontalStrike && direction == 0 && MathF.Abs(vx) <= 2f &&
                    inwardFacing && MathF.Abs(input.Current.MoveAxis) <= .001f;
                // Guard an actual incoming attack while braking, too. Stance
                // readiness remains a J prerequisite, not permission to defend.
                generalDefendWindow = !combat.IsAttacking &&
                    energy.EnergyRatio > .35f && enemyThreat;
                SendMouse(MouseButton.Right, generalDefendWindow, player, target);
                if (frozenLowerLines < 16 && frame % 12 == 0)
                {
                    frozenLowerLines++;
                    Vector2 source = actor.GetNode<Hitbox>("AttackHitbox").GlobalPosition;
                    GD.Print($"TASK10_FROZEN_LOWER_KEYBOARD record={frozenLowerLines}/16 loop={frame}/900 " +
                        $"sample={input.CurrentFrameSequence} player={player.GlobalPosition} velocity={player.Velocity} " +
                        $"actor={target} source={source} source_delta={source-player.GlobalPosition} " +
                        $"gap={signedGap:0.000} stance_delta={error:0.000} neutral_distance={braking:0.000} " +
                        $"predicted_stop_x={stopX:0.000} forecast_steps={stop.Steps} direction={direction} " +
                        $"ready={frozenRustReady} aim={input.KeyboardAimDirection} " +
                        $"shield={input.Current.ShieldHeld}/{shield.IsActive}/{shield.GuardDirection} " +
                        $"state={((RustShellSquire)actor).CurrentState} hp={playerHealthAtStart}->{playerHealth.CurrentHealth} " +
                        $"floor={DescribeFloorCollider(player)} recoveries={monitor.RecoveryRequested}/{monitor.RecoveryCompleted}");
                }
            }
            bool gearBellPolicy = gearBellKeyboard && actor is BellBackLaborer;
            bool gearBellReady = false;
            if (gearBellPolicy)
            {
                float stanceX = target.X - desiredActorSide * 60f;
                var stop = FreeMotionForecast.Neutral(player.Velocity.X, player.IsOnFloor(),
                    gearBellMotor.MotionSettings, gearBellMotor.ThrusterState.Module,
                    1d / Engine.PhysicsTicksPerSecond, 900 - frame, 2f);
                TestAssert.True(stop.SpeedThresholdReached,
                    "Gear Bell neutral stance forecast fits the remaining original900 budget");
                float stopX = player.GlobalPosition.X + stop.NetDistance;
                int direction = MathF.Abs(stanceX - stopX) <= 1.5f ? 0 : MathF.Sign(stanceX - stopX);
                // L and movement share actual keyboard aim. An outward correction
                // cannot coexist with inward guarding; prioritize the real threat.
                if (enemyThreat) direction = 0;
                bool inward = input.KeyboardAimDirection.Dot(Vector2.Right * desiredActorSide) > .99f;
                if (!enemyThreat && direction == 0 && MathF.Abs(player.Velocity.X) <= 2f && !inward)
                    direction = (int)desiredActorSide;
                // Preserve the original arena guard after this local override.
                // It must not be bypassed by the newly selected stance direction.
                if (player.GlobalPosition.X <= arenaMinimumX && direction < 0)
                    direction = cooldownRetreat ? 0 : 1;
                if (player.GlobalPosition.X >= arenaMaximumX && direction > 0)
                    direction = cooldownRetreat ? 0 : -1;
                moveLeft = direction < 0;
                moveRight = direction > 0;
                generalDefendWindow = !combat.IsAttacking && energy.EnergyRatio > .35f && enemyThreat;
                SendMouse(MouseButton.Right, generalDefendWindow, player,
                    enemyThreat ? encounterDanger.GuardSource : target);
                gearBellReady = GearBellNeutralSupport((BellBackLaborer)actor) &&
                    direction == 0 && !enemyThreat && !combat.IsAttacking &&
                    MathF.Abs(target.X - stopX) is >= 55f and <= 64f;
                if (gearBellLines < 16 && (frame % 12 == 0 || gearBellReady))
                {
                    gearBellLines++;
                    GD.Print($"TASK10_GEAR_BELL_STANCE record={gearBellLines}/16 loop={frame}/900 " +
                        $"sample={input.CurrentFrameSequence} player={player.GetInstanceId()}/{player.GlobalPosition} " +
                        $"velocity={player.Velocity} bell={actor.GetInstanceId()}/{target} " +
                        $"gap={signedGap:R} stop_x={stopX:R} stop_steps={stop.Steps} direction={direction} " +
                        $"support={gearBellStanceFloor} neutral_support_samples={gearBellSupportSamples} " +
                        $"raw_AD={Input.IsPhysicalKeyPressed(Key.A)}/{Input.IsPhysicalKeyPressed(Key.D)} " +
                        $"sample_axis={input.Current.MoveAxis:R} aim={input.KeyboardAimDirection} ready={gearBellReady} " +
                        $"threat={enemyThreat} hp={playerHealthAtStart}->{playerHealth.CurrentHealth} " +
                        $"recoveries={monitor.RecoveryRequested}/{monitor.RecoveryCompleted} encounter={encounterId} policy=shared_neutral_bell");
                }
            }
            if (splitMothDiagnostic && actor is GraveLampMoth)
                ObserveSplitMoth(actor, moveLeft, moveRight,
                    strikeRange && !enemyThreat && frame >= nextAttackFrame && !combat.IsAttacking && modes.CanAffordAttack);
            if (counterweightSuppressionKeyboard)
            {
                mixedDecisionId++;
                mixedLastDanger = encounterDanger;
                MixedResourceSnapshot("decision_pre_command", $"energy_gate={energy.EnergyRatio > .35f} " +
                    $"strike_range={strikeRange} cooldown={frame < nextAttackFrame} next_attack={nextAttackFrame} " +
                    $"general_defend={generalDefendWindow} safe_counter_seconds={encounterDanger.SafeCounterSeconds:R} " +
                    $"mixed_counter_ready={Task10MixedCounterWindow(combat, energy, encounterDanger)} " +
                    $"move_left={moveLeft} move_right={moveRight}");
            }
            SendAction(InputActions.MoveLeft, moveLeft);
            SendAction(InputActions.MoveRight, moveRight);
            bool safeMothCast = actor is GraveLampMoth castMoth && dy < -74f &&
                ((splitMothPolicy || frozenMothPolicy) ? SplitMothCastWindow(castMoth) : frame % 60 == 0) &&
                Task10KeyboardClawPlanSelects(player, actor.GetNode<ThreadTarget2D>("ThreadTarget"));
            if (sentryGuardRequired || skitterPolicy || frozenRustPolicy || gearBellPolicy || courtyardBellPolicy || splitMothPolicy ||
                frozenMothPolicy && (safeMothCast || generalDefendWindow))
            {
                SendAction(InputActions.Jump, false);
                SendAction(InputActions.PrimaryAction, false);
                SendAction(InputActions.MoveUp, false);
            }
            else if (!strikeRange && dy < -42f && player.IsOnFloor() && frame % 45 == 0)
                SendAction(InputActions.Jump, true);
            else if (!player.IsOnFloor() || frame % 45 == 7)
                SendAction(InputActions.Jump, false);
            MoveMouse(player, skitterGuardRequired ? skitterGuardSource : target);

            if (!courtyardBellPolicy && !splitBellPolicy && actor is BellBackLaborer laborer &&
                laborer.CurrentState != BellBackLaborerState.Exposed && frame % 75 == 0 &&
                (!gearBellPolicy || gearBellReady) &&
                Task10KeyboardClawPlanSelects(player, actor.GetNode<ThreadTarget2D>("ThreadTarget")))
            {
                SendMouse(MouseButton.Right, false, player, target);
                ThreadTarget2D threadTarget = actor.GetNode<ThreadTarget2D>("ThreadTarget");
                LegacyThreadInteractionAdapter gearAdapter = gearBellPolicy
                    ? threadTarget.GetNode<LegacyThreadInteractionAdapter>("LegacyThreadInteractionAdapter") : null;
                int gearApplications = gearAdapter?.ApplicationCount ?? 0;
                int gearHealth = playerHealth.CurrentHealth;
                ObserveSplitBell("before-CastAt");
                bool issued = await CastAt(tree, monitor, player, threadTarget,
                    () => gearBellPolicy
                        ? GodotObject.IsInstanceValid(laborer) && laborer.CurrentState == BellBackLaborerState.Exposed
                        : !GodotObject.IsInstanceValid(laborer) || laborer.CurrentState == BellBackLaborerState.Exposed,
                    45, observeGearBellAdmission: gearBellPolicy,
                    gearBellAdmission: gearBellPolicy ? () => GearBellNeutralSupport(laborer) &&
                        !Task10ObserveEncounterDanger(actorRoot, encounterId, laborer, false, rangedThreatLeaves).Threat : null);
                ObserveSplitBell("after-CastAt");
                if (issued)
                {
                    if (gearBellPolicy)
                    {
                        TestAssert.True(GodotObject.IsInstanceValid(laborer) &&
                            laborer.GetNode<ThreadTarget2D>("ThreadTarget") == threadTarget &&
                            laborer.CurrentState == BellBackLaborerState.Exposed &&
                            gearAdapter.ApplicationCount == gearApplications + 1 && playerHealth.CurrentHealth == gearHealth,
                            "Gear Bell issued K must produce one real application and live Exposed with unchanged HP in original45");
                        GD.Print($"TASK10_GEAR_BELL_CAST_OK bell={laborer.GetInstanceId()} " +
                            $"applications={gearApplications}->{gearAdapter.ApplicationCount} hp={gearHealth}->{playerHealth.CurrentHealth} " +
                            $"original_prefix_admission_wait=2/8/45 encounter={encounterId} policy=shared_neutral_bell");
                    }
                    threadCasts++;
                }
                SendAction(InputActions.SelectAttackMode, true);
                if (!issued)
                {
                    var freshDanger = Task10ObserveEncounterDanger(actorRoot, encounterId, laborer, false, rangedThreatLeaves);
                    SendMouse(MouseButton.Right, !combat.IsAttacking && energy.EnergyRatio > .35f && freshDanger.Threat,
                        player, freshDanger.Threat ? freshDanger.GuardSource : laborer.GlobalPosition);
                }
                await PhysicsFrames(tree, monitor, 1);
                SendAction(InputActions.SelectAttackMode, false);
                continue;
            }
            if (actor is GraveLampMoth airborneMoth && safeMothCast)
            {
                SendMouse(MouseButton.Right, false, player, target);
                ThreadTarget2D threadTarget = actor.GetNode<ThreadTarget2D>("ThreadTarget");
                LegacyThreadInteractionAdapter mothAdapter = splitMothPolicy || frozenMothPolicy
                    ? threadTarget.GetNode<LegacyThreadInteractionAdapter>("LegacyThreadInteractionAdapter") : null;
                int mothApplications = mothAdapter?.ApplicationCount ?? 0;
                ulong mothCastId = airborneMoth.GetInstanceId();
                int mothCastHealth = playerHealth.CurrentHealth;
                SplitMothEdge(airborneMoth, returned: false);
                await CastAt(tree, monitor, player, threadTarget,
                    () => (!splitMothPolicy && !GodotObject.IsInstanceValid(airborneMoth)) ||
                          GodotObject.IsInstanceValid(airborneMoth) &&
                          airborneMoth.CurrentState == GraveLampMothState.ThreadStunned, 45,
                    requireSafeFrozenMoth: frozenMothPolicy);
                if (splitMothPolicy || frozenMothPolicy)
                    TestAssert.True(GodotObject.IsInstanceValid(airborneMoth) &&
                        airborneMoth.GetInstanceId() == mothCastId &&
                        mothAdapter.ApplicationCount == mothApplications + 1 &&
                        airborneMoth.CurrentState == GraveLampMothState.ThreadStunned &&
                        (!frozenMothPolicy || playerHealth.CurrentHealth == mothCastHealth),
                        "keyboard split/frozen Moth observes one real application and live ThreadStunned before J");
                if (frozenMothPolicy)
                    GD.Print($"TASK10_FROZEN_MOTH_SAFE_CAST_OK actor={mothCastId} " +
                        $"applications={mothApplications}->{mothAdapter.ApplicationCount} state={airborneMoth.CurrentState} " +
                        $"health={mothCastHealth}->{playerHealth.CurrentHealth} original_wait_budget=45 " +
                        "fresh_neutral_Space_prefix=true");
                SplitMothEdge(airborneMoth, returned: true);
                threadCasts++;
                SendAction(InputActions.SelectAttackMode, true);
                await PhysicsFrames(tree, monitor, 1);
                SendAction(InputActions.SelectAttackMode, false);
                continue;
            }

            if (strikeRange && (!enemyThreat || steamMissileKeyboard && steamDecision.CanCounter ||
                    counterweightSuppressionKeyboard && encounterDanger.HasRanged &&
                    Task10MixedCounterWindow(combat, energy, encounterDanger)) &&
                (!steamMissileKeyboard || steamDecision.CanCounter) &&
                frame >= nextAttackFrame && !combat.IsAttacking &&
                (!counterweightSuppressionKeyboard || !encounterDanger.HasRanged ||
                    Task10MixedCounterWindow(combat, energy, encounterDanger)) &&
                (!splitBellPolicy || ((BellBackLaborer)actor).CurrentState == BellBackLaborerState.Exposed &&
                    actor.GetNode<Hurtbox>("Hurtbox").DamageReceiverPath == new NodePath("../Health")) &&
                (!courtyardBellPolicy || courtyardBellExposed) &&
                (!gearBellPolicy || ((BellBackLaborer)actor).CurrentState == BellBackLaborerState.Exposed && gearBellReady) &&
                (!frozenRustPolicy || frozenRustReady) &&
                (!sentryPolicy || (!sentryGuardRequired && sentryReleaseSampled &&
                    !sentryAttackWouldOverlapGuard && sentryCounterEnergyReady)) &&
                (!skitterPolicy || skitterEligible) &&
                modes.CanAffordAttack)
            {
                if (counterweightSuppressionKeyboard) MixedResourceSnapshot("J_release_request");
                SendMouse(MouseButton.Right, false, player, target);
                int releaseWaits = 0;
                for (int sample = 0; sample < 3 && input.Current.ShieldHeld; sample++)
                {
                    releaseWaits++;
                    await PhysicsFrames(tree, monitor, 1);
                }
                shieldReleaseSamples++;
                if (counterweightSuppressionKeyboard)
                    MixedResourceSnapshot("J_release_sample", $"waits={releaseWaits}");
                GD.Print($"TASK10_ATTACK_RELEASE_SAMPLE id={encounterId} frame={frame} " +
                    $"sample={input.CurrentFrameSequence} shield_held={input.Current.ShieldHeld} " +
                    $"shield_active={shield.IsActive} can_attack={modes.CanBeginAttack} " +
                    $"energy={energy.EnergyRatio:0.000}");
                if (input.Current.ShieldHeld || !modes.CanBeginAttack)
                {
                    if (counterweightSuppressionKeyboard) MixedResourceSnapshot("J_release_not_ready");
                    await PhysicsFrames(tree, monitor, 1);
                    continue;
                }
                Task10EncounterDanger freshDanger = Task10ObserveEncounterDanger(actorRoot, encounterId,
                    actor, false, rangedThreatLeaves);
                if (steamMissileKeyboard)
                {
                    if (!GodotObject.IsInstanceValid(actor) || actor.IsQueuedForDeletion() ||
                        !actor.IsInsideTree() || enemyHealth?.CurrentHealth is not > 0)
                    {
                        await PhysicsFrames(tree, monitor, 1);
                        continue;
                    }
                    // L release awaits are real moving physics samples. Recompute
                    // geometry rather than striking the pre-release position/facing.
                    target = actor.GlobalPosition;
                    dx = target.X - player.GlobalPosition.X;
                    dy = target.Y - player.GlobalPosition.Y;
                    signedGap = dx * desiredActorSide;
                    verticalStrike = dy is >= -74f and <= -10f && MathF.Abs(dx) <= 30f;
                    horizontalStrike = MathF.Abs(dy) <= 46f && signedGap is >= 8f and <= 64f;
                    strikeRange = verticalStrike || horizontalStrike;
                    if (!strikeRange)
                    {
                        await PhysicsFrames(tree, monitor, 1);
                        continue;
                    }
                }
                Task10SteamMissileDecision freshSteamDecision = steamMissileKeyboard
                    ? Task10SteamMissileKeyboardDecision(player, (RangedWeaponEnemy)actor, combat, energy, shield,
                        freshDanger, strikeRange, frame, nextAttackFrame, rangedThreatLeaves) : default;
                if (counterweightSuppressionKeyboard)
                {
                    mixedLastDanger = freshDanger;
                    MixedResourceSnapshot("J_fresh_danger");
                }
                if ((actor is RangedWeaponEnemy || freshDanger.HasRanged) &&
                    (!GodotObject.IsInstanceValid(actor) || actor.IsQueuedForDeletion() ||
                     !actor.IsInsideTree() || enemyHealth?.CurrentHealth <= 0 ||
                     freshDanger.Threat && !(steamMissileKeyboard && freshSteamDecision.CanCounter ||
                        counterweightSuppressionKeyboard && freshDanger.HasRanged &&
                        Task10MixedCounterWindow(combat, energy, freshDanger)) ||
                     steamMissileKeyboard && !freshSteamDecision.CanCounter ||
                     counterweightSuppressionKeyboard && freshDanger.HasRanged &&
                     !Task10MixedCounterWindow(combat, energy, freshDanger)))
                {
                    // Shield release awaits can cross a new warning or active-tail boundary.
                    // Recompute actual permission/leaves instead of striking a pre-await snapshot.
                    if (counterweightSuppressionKeyboard) MixedResourceSnapshot("J_fresh_rejected");
                    await PhysicsFrames(tree, monitor, 1);
                    continue;
                }
                if (sentryPolicy)
                {
                    BellBoltSentry currentSentry = (BellBoltSentry)actor;
                    BellBoltSentryFrame currentSentryFrame = currentSentry.CurrentFrame;
                    AttackTimelineFrame currentSentryTimeline = currentSentryFrame.AttackTimeline;
                    bool currentBoltLive = currentSentry.GetChildren().OfType<BellBoltProjectile>()
                        .Any(candidate => GodotObject.IsInstanceValid(candidate) &&
                            candidate.IsInsideTree() && !candidate.IsRetired);
                    // The existing release wait can advance the enemy timeline.
                    // Revalidate, never issue J using the pre-await guard snapshot.
                    if (currentSentryFrame.State == BellBoltSentryState.Fire || currentBoltLive ||
                        (currentSentryTimeline.Phase == AttackPhase.Telegraph &&
                         currentSentryTimeline.PhaseRemainingSeconds <= .70f) ||
                        shield.IsActive || !sentryReleaseSampled ||
                        !SentryCounterEnergyBudget.CanSpendAttack(
                            energy.EnergyRatio * energy.Tuning.MaxEnergy, energy.Tuning.ToSettings(),
                            currentSentry.Settings, Engine.PhysicsTicksPerSecond))
                    {
                        await PhysicsFrames(tree, monitor, 1);
                        continue;
                    }
                }
                if (courtyardBellPolicy &&
                    (!GodotObject.IsInstanceValid(actor) || actor != courtyardBell || group.CurrentBatch != 1 ||
                     enemyHealth?.CurrentHealth <= 0 ||
                     ((BellBackLaborer)actor).CurrentState != BellBackLaborerState.Exposed ||
                     actor.GetNode<Hurtbox>("Hurtbox").DamageReceiverPath != new NodePath("../Health")))
                {
                    // Any existing release-sample wait can cross the real exposure boundary.
                    // Return to the outer loop's rearm instead of issuing a stale J.
                    await PhysicsFrames(tree, monitor, 1);
                    continue;
                }
                if (splitBellPolicy &&
                    (((BellBackLaborer)actor).CurrentState != BellBackLaborerState.Exposed ||
                     actor.GetNode<Hurtbox>("Hurtbox").DamageReceiverPath != new NodePath("../Health")))
                {
                    await PhysicsFrames(tree, monitor, 1);
                    continue; // Release-sample waits must not turn a stale exposure into J against Armor.
                }
                StringName facingAction = desiredActorSide < 0f
                    ? InputActions.MoveLeft
                    : InputActions.MoveRight;
                bool facingPulseWithinArena = verticalStrike ||
                    (facingAction == InputActions.MoveLeft
                        ? player.GlobalPosition.X > arenaMinimumX
                        : player.GlobalPosition.X < arenaMaximumX);
                if (!facingPulseWithinArena)
                {
                    GD.Print($"TASK10_ATTACK_BOUNDARY_WAIT id={encounterId} frame={frame} " +
                        $"player={player.GlobalPosition} actor={target} side={desiredActorSide:0} " +
                        $"arena={arenaBounds} safe_x={arenaMinimumX:0.000}..{arenaMaximumX:0.000}");
                    await PhysicsFrames(tree, monitor, 1);
                    continue;
                }
                if (verticalStrike) SendAction(InputActions.MoveUp, true);
                else SendAction(facingAction, true);
                if (skitterPolicy) SkitterPolicyLog("counter_attempt");
                CourtyardBellSnapshot("J-request");
                ObserveSplitBell("J-request");
                if (counterweightSuppressionKeyboard) MixedResourceSnapshot("J_command");
                SendAction(InputActions.PrimaryAction, true);
                await PhysicsFrames(tree, monitor, 2);
                SendAction(InputActions.PrimaryAction, false);
                SendAction(InputActions.MoveUp, false);
                if (horizontalStrike)
                    SendAction(facingAction, false);
                attacks++;
                nextAttackFrame = frame + 24;
            }
            else
            {
                if (skitterPolicy)
                    SendMouse(MouseButton.Right, skitterGuardRequired && energy.EnergyRatio > 0f &&
                        !energy.IsOverheated, player, skitterGuardRequired ? skitterGuardSource : target);
                else if (sentryPolicy)
                    SendMouse(MouseButton.Right, sentryGuardRequired, player,
                        sentryGuardRequired ? sentryGuardSource : target);
                else
                {
                    if (counterweightSuppressionKeyboard)
                        MixedResourceSnapshot("fallback_shield_command", $"guard_command={generalDefendWindow}");
                    SendMouse(MouseButton.Right, generalDefendWindow, player,
                        enemyThreat ? encounterDanger.GuardSource : target);
                }
            }

            await PhysicsFrames(tree, monitor, 1);
            if (frozenRustPolicy && frame < 6 && GodotObject.IsInstanceValid(actor))
            {
                var rust = (RustShellSquire)actor;
                Vector2 source = actor.GetNode<Hitbox>("AttackHitbox").GlobalPosition;
                GD.Print($"TASK10_FROZEN_RUST_EARLY_SAMPLE loop={frame}/900 " +
                    $"sample={frozenMothCommandSequence}->{input.CurrentFrameSequence} " +
                    $"planned_axis={(moveLeft ? -1 : moveRight ? 1 : 0)} " +
                    $"raw_A={Input.IsPhysicalKeyPressed(Key.A)} raw_D={Input.IsPhysicalKeyPressed(Key.D)} " +
                    $"sampled_axis={input.Current.MoveAxis} requested_guard={generalDefendWindow} " +
                    $"held={input.Current.ShieldHeld} active={shield.IsActive} direction={shield.GuardDirection} " +
                    $"source={source} source_delta={source-player.GlobalPosition} " +
                    $"player={player.GlobalPosition} velocity={player.Velocity} scale={frozenLowerMotor.EffectiveMovementScale} " +
                    $"state={rust.CurrentState} remaining={rust.CurrentFrame.AttackTimeline.PhaseRemainingSeconds:R} " +
                    $"ready_J={frozenRustReady} attacking={combat.IsAttacking} hp={playerHealthAtStart}->{playerHealth.CurrentHealth} " +
                    "observation=physics_signal_before_node_process");
            }
            if (splitBellPolicy) GuardSplitBellPlayer();
            if (courtyardBellPolicy)
                TestAssert.True(player.GetInstanceId() == courtyardJumpPlayerId &&
                    monitor.Player.GetInstanceId() == courtyardJumpPlayerId &&
                    playerHealth.CurrentHealth == playerHealthAtStart &&
                    monitor.RecoveryRequested == courtyardRequestBaseline && monitor.RecoveryCompleted == courtyardRecoveryBaseline &&
                    courtyardJumpMotor.AcceptedJumpCount == courtyardJumpBaseline + 1 &&
                    courtyardJumpMotor.AcceptedDashCount == courtyardDashBaseline &&
                    CourtyardJumpSupport(courtyardJumpFloor, courtyardJumpFloorShape) &&
                    player.GlobalPosition.IsFinite() && player.Velocity.IsFinite(),
                    "keyboard courtyard Bell post-physics, including its final hit, preserves player HP, identity, support and jump/recovery counts");
            if (frozenMothPolicy && GodotObject.IsInstanceValid(actor) && frozenMothLines < 8 &&
                (generalDefendWindow || ((GraveLampMoth)actor).CurrentState == GraveLampMothState.Dive) &&
                frame % 3 == 0)
            {
                frozenMothLines++;
                GraveLampMoth guardMoth = (GraveLampMoth)actor;
                GD.Print($"TASK10_FROZEN_MOTH_GUARD record={frozenMothLines}/8 loop={frame}/900 " +
                    $"sample={frozenMothCommandSequence}->{input.CurrentFrameSequence} requested={generalDefendWindow} " +
                    $"state={guardMoth.CurrentState} phase={guardMoth.CurrentFrame.AttackTimeline.Phase} " +
                    $"remaining={guardMoth.CurrentFrame.AttackTimeline.PhaseRemainingSeconds:R} " +
                    $"energy={energy.EnergyRatio:R} heat={energy.HeatRatio:R} can_guard={shield.CanBeginGuard} " +
                    $"held={input.Current.ShieldHeld} active={shield.IsActive} direction={shield.GuardDirection} " +
                    $"aim={input.KeyboardAimDirection} player={player.GlobalPosition} source={guardMoth.GlobalPosition} " +
                    $"velocity={player.Velocity} hp={playerHealthAtStart}->{playerHealth.CurrentHealth} " +
                    $"floor={DescribeFloorCollider(player)} recoveries={monitor.RecoveryRequested}/{monitor.RecoveryCompleted}");
            }
            if (monitor.RecoveryCompleted != startingRecoveries)
            {
                SkitterSnapshot("recovery_boundary", "driver_post_physics");
                throw new InvalidOperationException($"Task10 encounter {encounterId} caused " +
                    $"unexpected recovery before its explicit recovery proof; player={player.GlobalPosition} " +
                    $"enemy={target} health={enemyHealth?.CurrentHealth} attacks={attacks} " +
                    $"thread_casts={threadCasts}");
            }
        }
        }
        finally
        {
            if (counterweightSuppressionKeyboard)
            {
                MixedResourceSnapshot("unwind_before_listener_removal");
                mixedClosed = true;
                void RemoveMixedListener(Node node, Action remove)
                {
                    try { if (GodotObject.IsInstanceValid(node)) remove(); }
                    catch (Exception) { mixedObservationErrors++; }
                }
                RemoveMixedListener(energy, () => energy.EnergyFrameChanged -= mixedEnergyChanged);
                RemoveMixedListener(shield, () => shield.ShieldFrameChanged -= mixedShieldChanged);
                RemoveMixedListener(shield, () => shield.ShieldResolved -= mixedShieldResolved);
                try
                {
                    GD.Print($"MIXED_RESOURCE_BEGIN capacity={mixedRecordCapacity} diagnostic_only=true " +
                        "event_danger_association=last_decision physics_frame_boundary=pre_node request_source=unknown");
                    foreach (string record in mixedRecords) GD.Print(record);
                    GD.Print($"MIXED_RESOURCE_END records={mixedRecords.Count} dropped={mixedDropped} " +
                        $"observer_errors={mixedObservationErrors} live_loop_stdout=false zero_overhead_claim=false whole_goal=false");
                }
                catch (Exception) { /* Preserve the original route failure if diagnostic output fails. */ }
            }
            if (splitBellDiagnostic)
            {
                try
                {
                    GD.Print($"TASK10_SPLIT_BELL_DIAGNOSTIC_END records={splitBellDiagnosticLines}/40 " +
                        $"observation_errors={splitBellDiagnosticErrors} diagnostic_only=true");
                }
                catch (Exception) { /* Preserve any original route failure. */ }
            }
            if (courtyardBellCycle > 0)
            {
                if (GodotObject.IsInstanceValid(courtyardBellClaw)) courtyardBellClaw.ClawFrameChanged -= ObserveCourtyardBellClaw;
                SendAction(InputActions.PrimaryAction, false);
                SendAction(InputActions.Claw, false);
            }
            if (courtyardJumpPreparing)
            {
                SendAction(InputActions.Jump, false);
                SendAction(InputActions.MoveRight, false);
            }
            if (splitMothDiagnostic)
            {
                try
                {
                    if (splitMothId != 0)
                        splitLastObservation = SplitObservation(out _, out splitLastCastIds);
                }
                catch (Exception error) { SplitDiagnosticError(error); }
                try
                {
                    GD.Print($"TASK10_SPLIT_MOTH_SUMMARY timing=existing_unwind moth={splitMothIdentity} " +
                        $"selection_physics={splitSelectionPhysics} selection_loop={splitSelectionLoop} " +
                        $"selected_iterations={splitSelectedIterations} dy_gate_pass={splitDyPass} cadence_pass={splitCadencePass} " +
                        $"combined_cast_gate_pass={splitCombinedPass} moth_branch_entries={splitBranchEntries} CastAt_returns={splitCastReturns} " +
                        $"min_dx={splitMinDx:R} max_dx={splitMaxDx:R} min_dy={splitMinDy:R} max_dy={splitMaxDy:R} " +
                        $"selection_cast_ids={splitFirstCastIds} final_cast_ids={splitLastCastIds} " +
                        $"state_lines={splitStateLines} state_cap=24 state_suppressed={splitStateSuppressed} " +
                        $"window_frames=180 window_expired={(splitMothId != 0 && Engine.GetPhysicsFrames() - splitSelectionPhysics >= 180)} " +
                        $"window_expired_samples={splitWindowExpiredSamples} edge_lines={splitEdgeLines} edge_cap=6 edge_suppressed={splitEdgeSuppressed} " +
                        $"diagnostic_errors={splitDiagnosticErrors} last_error={splitLastError} " +
                        $"first=[{splitFirstObservation}] final=[{splitLastObservation}]");
                }
                catch (Exception error)
                {
                    SplitDiagnosticError(error);
                    // A reporting failure must not mask the existing gameplay exception.
                    try { GD.Print($"TASK10_SPLIT_MOTH_SUMMARY diagnostic_errors={splitDiagnosticErrors} last_error={splitLastError} summary_failed=True"); }
                    catch (Exception) { /* No safe output remains; preserve gameplay failure. */ }
                }
            }
            if (trackedSkitter != null)
            {
                // Each removal is independent; diagnostics must never replace the route failure.
                int removed = 0, retired = 0;
                void RemoveSkitterListener(Node node, Action remove)
                {
                    try
                    {
                        if (GodotObject.IsInstanceValid(node)) { remove(); removed++; }
                        else retired++;
                    }
                    catch (Exception) { skitterDiagnosticErrors++; }
                }
                RemoveSkitterListener(trackedSkitter, () => trackedSkitter.FrameChanged -= skitterFrameChanged);
                RemoveSkitterListener(rushHitbox, () => rushHitbox.Connected -= rushConnected);
                RemoveSkitterListener(playerHealth, () => playerHealth.Damaged -= skitterPlayerDamaged);
                RemoveSkitterListener(shield, () => shield.ShieldResolved -= skitterShieldResolved);
                try
                {
                    GD.Print($"TASK10_PENDULUM_SKITTER_SUMMARY physics={Engine.GetPhysicsFrames()} loop={currentFrame} " +
                        $"state_lines={skitterStateLines} event_lines={skitterEventLines} " +
                        $"state_suppressed={skitterStateSuppressed} event_suppressed={skitterEventSuppressed} " +
                        $"window_closed={skitterWindowClosed} window_expired={Engine.GetPhysicsFrames() - skitterStartPhysics >= 180} " +
                        $"listeners_removed={removed} retired_listener_sources={retired} diagnostic_errors={skitterDiagnosticErrors}");
                }
                catch (Exception) { /* Preserve the original route failure. */ }
            }
            if (steamSentryDiagnostic)
            {
                void RemoveSteamBellListener(Node source, Action remove)
                {
                    try { if (GodotObject.IsInstanceValid(source)) remove(); }
                    catch (Exception) { steamBellErrors++; }
                }
                RemoveSteamBellListener(trackedSteamBell, () => trackedSteamBell.FrameChanged -= steamBellFrameChanged);
                RemoveSteamBellListener(trackedSteamBell, () => trackedSteamBell.AttackFrameChanged -= steamBellAttackChanged);
                if (steamBellConnected != null)
                    RemoveSteamBellListener(steamBellHitbox, () => steamBellHitbox.Connected -= steamBellConnected);
                if (steamBellShieldSubscribed)
                    RemoveSteamBellListener(shield, () => shield.ShieldResolved -= steamBellShieldResolved);
                GD.Print($"TASK10_STEAM_BELL_TRACE_END lines={steamBellLines} omitted={steamBellOmitted} " +
                    $"damage_events={steamBellDamageEvents} hitbox_connections={steamBellConnections} " +
                    $"fatal_stack={steamBellFatalStack} fatal_connection={steamBellFatalConnection} " +
                    $"diagnostic_errors={steamBellErrors} observer_only=true normal_cap=64 terminal_reserved=2");
                steamSentryRecovery?.Dispose();
                if (GodotObject.IsInstanceValid(trackedBoltHitbox))
                    trackedBoltHitbox.Connected -= boltConnected;
                if (GodotObject.IsInstanceValid(trackedSentry))
                    trackedSentry.FrameChanged -= sentryFrameChanged;
                if (GodotObject.IsInstanceValid(shield))
                    shield.ShieldResolved -= sentryShieldResolved;
            }
            if (gearDiagnostic)
            {
                if (GodotObject.IsInstanceValid(energy)) energy.EnergyFrameChanged -= diagnosticEnergyChanged;
                if (GodotObject.IsInstanceValid(shield)) shield.ShieldFrameChanged -= diagnosticShieldChanged;
                GearDiagnosticSnapshot("unwind");
            }
            combat.AttackStarted -= started;
            combat.AttackStarted -= directionStarted;
            combat.AttackConnected -= connected;
            if (GodotObject.IsInstanceValid(playerHealth)) playerHealth.Damaged -= playerDamaged;
            if (GodotObject.IsInstanceValid(observedEnemyHealth))
                observedEnemyHealth.Damaged -= damaged;
        }
        string lastActorState = GodotObject.InstanceFromId(trackedActorId) is Node2D liveActor
            ? $"type={liveActor.GetType().Name} velocity=" +
              $"{(liveActor is CharacterBody2D body ? body.Velocity : Vector2.Zero)} " +
              $"floor={(liveActor is CharacterBody2D actorBody && actorBody.IsOnFloor())} " +
              $"moth_state={(liveActor is GraveLampMoth moth ? moth.CurrentState.ToString() : "n/a")}"
            : "actor_retired=True";
        string preCleanupSnapshot =
            $"pre_cleanup_frame={currentFrame} dx={lastDx:0.000} dy={lastDy:0.000} " +
            $"signed_gap={lastSignedGap:0.000} side={desiredActorSide:0} " +
            $"velocity={player.Velocity} floor={DescribeFloorCollider(player)} " +
            $"sample={input.CurrentFrameSequence} mode={modes.CurrentMode} slot={modes.ActiveSlot} " +
            $"can_attack={modes.CanBeginAttack} shield_held={input.Current.ShieldHeld} " +
            $"shield_active={shield.IsActive} energy={energy.EnergyRatio:0.000} " +
            $"frames_since_start={(lastAttackStartedFrame < 0 ? -1 : currentFrame - lastAttackStartedFrame)} " +
            $"frames_since_contact={(lastAttackConnectedFrame < 0 ? -1 : currentFrame - lastAttackConnectedFrame)}";
        ReleaseAll(player.GlobalPosition);
        await PhysicsFrames(tree, monitor, 3);
        TestAssert.True(group.IsComplete,
            $"Task10 real attack/defend/thread input defeats {encounterId}; " +
            $"player={player.GlobalPosition} active={group.IsActive} batch={group.CurrentBatch} " +
            $"live={group.LiveActorCount} attacks={attacks} thread_casts={threadCasts} " +
            $"started={attacksStarted} connected={attacksConnected} " +
            $"band_entries={strikeBandEntries} shield_release_samples={shieldReleaseSamples} " +
            $"health_damage_events={healthDamageEvents} last_damaged_health={lastDamagedHealth} " +
            $"last_attack_direction={lastAttackDirection} batch={group.CurrentBatch} " +
            $"activation_bounds={group.Definition?.ActivationBounds} {lastActorState} " +
            $"last_actor={lastActorPosition} enemy_health={lastEnemyHealth} " +
            $"{preCleanupSnapshot} " +
            $"mode={modes.CurrentMode} " +
            $"facing={combat.LastAttackFacing} attacking={combat.IsAttacking} " +
            $"energy={energy.EnergyRatio:0.000} shield={shield.IsActive} " +
            $"input_primary={input.Current.PrimaryPressed}/{input.Current.PrimaryHeld} " +
            $"player_health={player.GetNode<HealthComponent>("Health").CurrentHealth}");
        GD.Print($"TASK10_ENCOUNTER_INPUT_OK id={encounterId} attacks={attacks} " +
            $"started={attacksStarted} connected={attacksConnected} " +
            $"thread_casts={threadCasts} player={player.GlobalPosition} " +
            $"health={playerHealthAtStart}->{playerHealth.CurrentHealth} " +
            $"damage_events={playerDamageEvents}");
    }

    private static string DescribeFloorCollider(CharacterBody2D player)
    {
        if (!player.IsOnFloor()) return "airborne";
        for (int index = 0; index < player.GetSlideCollisionCount(); index++)
        {
            KinematicCollision2D collision = player.GetSlideCollision(index);
            if (collision.GetNormal().Y >= -.7f) continue;
            GodotObject collider = collision.GetCollider();
            return collider is Node node
                ? $"{node.GetPath()}#{node.GetInstanceId()}"
                : collider?.GetInstanceId().ToString() ?? "unknown";
        }
        return "floor_without_slide_collider";
    }

    private static bool TryTask10FullFloorSupport(CharacterBody2D player, out ulong floorId)
    {
        floorId = 0;
        if (!player.IsOnFloor()) return false;
        for (int index = 0; index < player.GetSlideCollisionCount(); index++)
        {
            KinematicCollision2D contact = player.GetSlideCollision(index);
            if (contact.GetNormal().Y >= -.7f || contact.GetCollider() is not StaticBody2D floor ||
                !GodotObject.IsInstanceValid(floor) || !floor.IsInsideTree() ||
                floor.ShapeOwnerGetOwner(floor.ShapeFindOwner(contact.GetColliderShapeIndex()))
                    is not CollisionShape2D shape ||
                !TryTask10CapsuleCorridor(player, shape, out _, out _, out _, out _)) continue;
            floorId = floor.GetInstanceId();
            return true;
        }
        return false;
    }

    private static async Task WaitForStoppedRiftCatch(SceneTree tree, CharacterBody2D player,
        RouteMonitor monitor, StaticBody2D support)
    {
        // The former support wait already owned90 frames. Use its original
        // budget for real reverse-key braking, not an extra settling delay.
        const int budget = 90;
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        CollisionShape2D shape = support.GetNode<CollisionShape2D>("Collision");
        TestAssert.True(!motor.IsDashing, "rift catch cannot forecast an active jet as unpowered motion");
        var forecast = FreeMotionForecast.Reverse(player.Velocity.X, player.IsOnFloor(),
            motor.MotionSettings, motor.ThrusterState.Module,
            1d / Engine.PhysicsTicksPerSecond, budget, .5f);
        TestAssert.True(forecast.BrakeReachedZero || forecast.SpeedThresholdReached,
            "rift reverse braking fits the original support-wait budget");
        float originalSign = Mathf.Sign(player.Velocity.X);
        int brakeFrames = 0;
        for (int frame = 0; frame < budget; frame++)
        {
            bool reverse = originalSign * player.Velocity.X > .5f;
            SendAction(InputActions.MoveLeft, reverse && originalSign > 0f);
            SendAction(InputActions.MoveRight, reverse && originalSign < 0f);
            if (reverse) brakeFrames++;
            await PhysicsFrames(tree, monitor, 1);
            if (HasFloorContact(player, support) && Mathf.Abs(player.Velocity.X) <= .5f &&
                Mathf.Abs(input.Current.MoveAxis) <= .001f &&
                TryTask10CapsuleCorridor(player, shape, out _, out _, out _, out _))
            {
                GD.Print($"THRUSTER_RIFT_CATCH_OK target={support.Name} player={player.GlobalPosition} " +
                    $"velocity={player.Velocity} frames={frame + 1}/{budget} reverse_frames={brakeFrames} " +
                    $"forecast_steps={forecast.Steps} full_support=true sampled_neutral=true");
                return;
            }
        }
        SendAction(InputActions.MoveLeft, false); SendAction(InputActions.MoveRight, false);
        throw new InvalidOperationException($"rift catch fails its original90-frame full-support handoff; " +
            $"target={support.Name} player={player.GlobalPosition} velocity={player.Velocity} " +
            $"floor={DescribeFloorCollider(player)}");
    }

    private static async Task TraverseTask10ControlledAbyss(SceneTree tree,
        PrologueLevelController level, SeamlessPrologueWorld world, CharacterBody2D player,
        RouteMonitor monitor, StaticBody2D commitment, StaticBody2D safeBottom,
        bool stopAfterLanding = false)
    {
        await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 2140f, 210);
        await PrologueCanyonTraversalTests.Task4WaitSupport(tree, player,
            commitment.GetParent().GetParent().GetParent<PrologueSector>(), commitment.Name);
        TestAssert.True(HasFloorContact(player, commitment),
            $"Task10 main variant starts the long fall on actual commitment support; " +
            $"player={player.GlobalPosition}");
        await CanyonUpdraftRuntimeTests.CaptureWorldProbe(tree,player,"01-before-fall");
        MechanicalClawController claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        int acceptedJumps = motor.AcceptedJumpCount;
        int acceptedDashes = motor.AcceptedDashCount;
        SendAction(InputActions.MoveRight, true);
        int onset = -1;
        int landed = -1;
        ulong onsetPhysics = 0, landedPhysics = 0;
        bool capturedMid = false;
        for (int frame = 0; frame < 540; frame++)
        {
            await PhysicsFrames(tree, monitor, 1);
            if (!player.IsOnFloor() && onset < 0)
            {
                onset = frame;
                onsetPhysics = Engine.GetPhysicsFrames();
                SendAction(InputActions.MoveRight, false);
                GD.Print($"TASK10_MAIN_ABYSS_ONSET frame={frame} player={player.GlobalPosition} " +
                    $"velocity={player.Velocity}");
            }
            if (onset >= 0)
            {
                if (!capturedMid && player.GlobalPosition.Y > 2060f)
                {
                    capturedMid = true;
                    await CanyonUpdraftRuntimeTests.CaptureWorldProbe(tree,player,"02-in-updraft");
                }
                TestAssert.Equal(Vector2.Zero, claw.CurrentFrame.VelocityCorrection,
                    "Task10 main long fall never borrows grapple correction");
                if (HasFloorContact(player, safeBottom))
                {
                    landed = frame;
                    landedPhysics = Engine.GetPhysicsFrames();
                    break;
                }
            }
        }
        SendAction(InputActions.MoveRight, false);
        double seconds = landedPhysics > onsetPhysics
            ? (landedPhysics - onsetPhysics) / (double)Engine.PhysicsTicksPerSecond : -1d;
        TestAssert.True(onset >= 0 && landed > onset && seconds >= 4d && seconds < 6d,
            $"Task10 main variant physically performs the authored 4-6 second long fall; " +
            $"onset={onset} landed={landed} seconds={seconds:0.000} " +
            $"player={player.GlobalPosition}");
        TestAssert.True(motor.AcceptedJumpCount == acceptedJumps &&
                        motor.AcceptedDashCount == acceptedDashes,
            "Task10 main long fall uses no jump or dash input");
        TestAssert.True(HasFloorContact(player, safeBottom) &&
            TryTask10CapsuleCorridor(player, safeBottom.GetNode<CollisionShape2D>("Collision"),
                out _, out _, out _, out _),
            $"main abyss ends on full native safe-bottom support; player={player.GlobalPosition}");
        GD.Print($"TASK10_MAIN_ABYSS_LANDING seconds={seconds:0.000} " +
            $"physics={onsetPhysics}->{landedPhysics} player={player.GlobalPosition} " +
            $"velocity={player.Velocity} full_support=true " +
            $"health={player.GetNode<HealthComponent>("Health").CurrentHealth} " +
            $"jump_delta={motor.AcceptedJumpCount - acceptedJumps} " +
            $"jet_delta={motor.AcceptedDashCount - acceptedDashes} original_loop_budget=540");
        await CanyonUpdraftRuntimeTests.CaptureWorldProbe(tree,player,"03-safe-bottom");
        if (stopAfterLanding) return;
        await DefeatTask10Encounter(tree, level, world, player, monitor,
            "canyon.v2.encounter.controlled-abyss");
        GD.Print($"TASK10_MAIN_ABYSS_OK seconds={seconds:0.000} player={player.GlobalPosition}");
    }

    private static async Task DropRightFromSupportToBasin(SceneTree tree,
        CharacterBody2D player, RouteMonitor monitor, StaticBody2D frozenExit, StaticBody2D campFloor)
    {
        bool keyboardReturn = KeyboardRouteInputDriver.Current != null;
        CollisionShape2D campShape = campFloor?.GetNode<CollisionShape2D>("Collision");
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        HealthComponent health = player.GetNode<HealthComponent>("Health");
        ulong playerId = player.GetInstanceId(), landingsBefore = motor.LandingCount;
        int healthBefore = health.CurrentHealth, jumpsBefore = motor.AcceptedJumpCount,
            dashesBefore = motor.AcceptedDashCount, requestsBefore = monitor.RecoveryRequested,
            recoveriesBefore = monitor.RecoveryCompleted;
        bool FullCampSupport() => HasFloorContact(player, campFloor) &&
            TryTask10CapsuleCorridor(player, campShape, out _, out _, out _, out _);
        TestAssert.True(HasFloorContact(player, frozenExit),
            $"Task10 exploration return starts on actual FrozenExit; player={player.GlobalPosition}");
        SendAction(InputActions.MoveRight, true);
        for (int frame = 0; frame < 120 &&
             (HasFloorContact(player, frozenExit) || player.IsOnFloor()); frame++)
            await PhysicsFrames(tree, monitor, 1);
        SendAction(InputActions.MoveRight, false);
        TestAssert.True(!HasFloorContact(player, frozenExit) && !player.IsOnFloor(),
            $"Task10 exploration leaves FrozenExit through real right-edge input; " +
            $"player={player.GlobalPosition} floor={DescribeFloorCollider(player)}");
        int fallFrames = 0;
        for (; fallFrames < 160 &&
             (keyboardReturn ? !FullCampSupport() : player.GlobalPosition.Y < 3900f); fallFrames++)
            await PhysicsFrames(tree, monitor, 1);
        TestAssert.True(player.GlobalPosition.X is >= 1300f and <= 2060f,
            $"Task10 exploration fall remains inside BasinCamp full-support corridor; " +
            $"player={player.GlobalPosition}");
        if (keyboardReturn)
        {
            bool full = FullCampSupport();
            GD.Print($"TASK10_EXPLORATION_CAMP_LANDING full_support={full} fall_frames={fallFrames}/160 " +
                $"player={player.GlobalPosition} velocity={player.Velocity} floor={DescribeFloorCollider(player)} " +
                $"health={healthBefore}->{health.CurrentHealth} landings={landingsBefore}->{motor.LandingCount} " +
                $"fall_height={motor.LastFallHeight:R} fall_damage={motor.LastFallDamage} " +
                $"damage_applied={motor.LastFallDamageApplied} " +
                $"recoveries={requestsBefore}/{recoveriesBefore}->{monitor.RecoveryRequested}/{monitor.RecoveryCompleted}");
            TestAssert.True(full && player.GetInstanceId() == playerId &&
                motor.LandingCount == landingsBefore + 1 && motor.LastFallDamage == 1 &&
                motor.LastFallDamageApplied && health.CurrentHealth == healthBefore - 1 && health.CurrentHealth > 0 &&
                motor.AcceptedJumpCount == jumpsBefore && motor.AcceptedDashCount == dashesBefore &&
                monitor.RecoveryRequested == requestsBefore && monitor.RecoveryCompleted == recoveriesBefore,
                "keyboard exploration return proves complete actual Camp support and the original one-damage fall without heal/jump/dash/recovery in its 160-frame budget");
        }
        GD.Print($"TASK10_EXPLORATION_BASIN_RETURN_OK player={player.GlobalPosition} " +
            $"input={player.GetNode<PlayerInputReader>("Input").Current.MoveAxis:0.000}");
    }

    private static async Task DropFromSupportToLowerShelf(SceneTree tree,
        CharacterBody2D player, RouteMonitor monitor, StaticBody2D source,
        StaticBody2D target)
    {
        RectangleShape2D sourceShape =
            (RectangleShape2D)source.GetNode<CollisionShape2D>("Collision").Shape;
        RectangleShape2D targetShape =
            (RectangleShape2D)target.GetNode<CollisionShape2D>("Collision").Shape;
        CapsuleShape2D playerShape =
            (CapsuleShape2D)player.GetNode<CollisionShape2D>("BodyCollider").Shape;
        float sourceLeft = source.GlobalPosition.X - sourceShape.Size.X / 2f;
        float targetLeft = target.GlobalPosition.X - targetShape.Size.X / 2f;
        float targetRight = target.GlobalPosition.X + targetShape.Size.X / 2f;
        float radius = playerShape.Radius;
        float safeReleaseMin = targetLeft + radius;
        float safeReleaseMax = targetRight - radius;
        TestAssert.True(HasFloorContact(player, source),
            $"Task10 input drop starts on actual {source.Name}; player={player.GlobalPosition} " +
            $"floor={DescribeFloorCollider(player)}");
        TestAssert.True(safeReleaseMin <= safeReleaseMax,
            $"Task10 input drop has a full-capsule target corridor; source_left={sourceLeft} " +
            $"target={targetLeft}..{targetRight} radius={radius}");

        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        MechanicalClawController claw =
            player.GetNode<MechanicalClawController>("MechanicalClaw");
        bool frozenKeyboardDrop = KeyboardRouteInputDriver.Current != null &&
            source.Name == "FrozenRightCatch" && target.Name == "FrozenExit";
        HealthComponent dropHealth = frozenKeyboardDrop ? player.GetNode<HealthComponent>("Health") : null;
        int dropHealthBefore = dropHealth?.CurrentHealth ?? 0;
        ulong dropLandingsBefore = motor.LandingCount;
        int jumpsBefore = motor.AcceptedJumpCount;
        int dashesBefore = motor.AcceptedDashCount;
        MechanicalClawState clawBefore = claw.CurrentFrame.State;
        bool keyboardDrop = KeyboardRouteInputDriver.Current != null;
        double stepSeconds = 1d / Engine.PhysicsTicksPerSecond;
        float targetStandingY = target.GlobalPosition.Y - targetShape.Size.Y / 2f -
            playerShape.Height / 2f - player.GetNode<CollisionShape2D>("BodyCollider").Position.Y;
        float NeutralStopX(Vector2 position, Vector2 velocity)
        {
            // This only selects input; native collision/contact below remains
            // the acceptance authority. Neither shelf lies in the shaft wind.
            for (int frame = 0; frame < 120; frame++)
            {
                velocity = ThrusterDynamics.Step(new(velocity, 0f, false, Vector2.Zero, 0f),
                    motor.ThrusterState.Module, motor.MotionSettings, stepSeconds).Velocity;
                position += velocity * (float)stepSeconds;
                if (velocity.Y >= 0f && position.Y >= targetStandingY)
                {
                    var ground = FreeMotionForecast.Neutral(velocity.X, true,
                        motor.MotionSettings, motor.ThrusterState.Module, stepSeconds, 60, .5f);
                    return ground.SpeedThresholdReached ? position.X + ground.NetDistance : float.NaN;
                }
            }
            return float.NaN;
        }
        TestAssert.True(!keyboardDrop || !motor.IsDashing,
            "keyboard walk-off never predicts an active jet as an unpowered fall");
        ReleaseAll(player.GlobalPosition);
        int departureFrames = 0;
        int preparationNeutralFrames = 0;
        int supportedApproachFrames = 0;
        while (departureFrames < 120 &&
               (HasFloorContact(player, source) || player.IsOnFloor()))
        {
            bool walkLeft = true;
            if (keyboardDrop)
            {
                Vector2 predictedPosition = player.GlobalPosition;
                Vector2 predictedVelocity = player.Velocity;
                // Two held samples conservatively cover the next move and the
                // input handoff. They consume no engine tick or extra budget.
                for (int sample = 0; sample < 2; sample++)
                {
                    predictedVelocity = ThrusterDynamics.Step(new(predictedVelocity, -1f,
                        true, Vector2.Zero, 0f), motor.ThrusterState.Module,
                        motor.MotionSettings, stepSeconds).Velocity;
                    predictedPosition += predictedVelocity * (float)stepSeconds;
                }
                float stopX = NeutralStopX(predictedPosition, predictedVelocity);
                // A hypothetical immediate fall from a distant supported point
                // can still end right of the lower target. Keep approaching on
                // the source; apply the upper bound once the projected centre
                // leaves it. The measured airborne release retains both bounds.
                bool stillApproaching = predictedPosition.X >= sourceLeft;
                walkLeft = float.IsFinite(stopX) && stopX >= safeReleaseMin &&
                    (stopX <= safeReleaseMax || stillApproaching);
                if (walkLeft && stopX > safeReleaseMax) supportedApproachFrames++;
                if (!walkLeft) preparationNeutralFrames++;
            }
            SendAction(InputActions.MoveLeft, walkLeft);
            departureFrames++;
            await PhysicsFrames(tree, monitor, 1);
        }
        SendAction(InputActions.MoveLeft, false);
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        for (int sample = 0; sample < 3 && input.Current.MoveAxis < -.001f; sample++)
            await PhysicsFrames(tree, monitor, 1);
        Vector2 releasePosition = player.GlobalPosition;
        Vector2 releaseVelocity = player.Velocity;
        float releaseX = releasePosition.X;
        float predictedStopX = keyboardDrop ? NeutralStopX(releasePosition, releaseVelocity) : float.NaN;
        TestAssert.True(!HasFloorContact(player, source) && !player.IsOnFloor(),
            $"Task10 leaves {source.Name} through its real left edge; " +
            $"player={player.GlobalPosition} velocity={player.Velocity} " +
            $"floor={DescribeFloorCollider(player)} frames={departureFrames} " +
            $"supported_approach_frames={supportedApproachFrames} " +
            $"sample={input.CurrentFrameSequence} move_axis={input.Current.MoveAxis:0.000}");
        TestAssert.True(Mathf.Abs(input.Current.MoveAxis) <= .001f,
            $"Task10 drop observes the real sampled A release before measuring its corridor; " +
            $"sample={input.CurrentFrameSequence} move_axis={input.Current.MoveAxis:0.000}");
        TestAssert.True(releaseX >= safeReleaseMin - .5f && releaseX <= safeReleaseMax + .5f,
            $"Task10 releases left input inside the target's full-support corridor; " +
            $"release_x={releaseX:0.000} corridor={safeReleaseMin:0.000}..{safeReleaseMax:0.000} " +
            $"source={source.Name} target={target.Name}");
        TestAssert.True(releaseX < sourceLeft,
            $"Task10 real departure stays on the source's left path; " +
            $"release_x={releaseX:0.000} source_left={sourceLeft:0.000}");
        TestAssert.True(!keyboardDrop || (float.IsFinite(predictedStopX) &&
            predictedStopX >= safeReleaseMin && predictedStopX <= safeReleaseMax),
            $"keyboard release forecasts a neutral landing and ground stop inside full target support; " +
            $"source={source.Name} target={target.Name} release={releasePosition} " +
            $"velocity={releaseVelocity} predicted_stop_x={predictedStopX:0.000} " +
            $"full_center={safeReleaseMin:0.000}..{safeReleaseMax:0.000}");

        int fallFrames = 0;
        while (fallFrames < 120 && !HasFloorContact(player, target))
        {
            TestAssert.True(!keyboardDrop || Mathf.Abs(input.Current.MoveAxis) <= .001f,
                "after the measured keyboard release, the entire fall remains sampled-neutral");
            fallFrames++;
            await PhysicsFrames(tree, monitor, 1);
        }
        Vector2 contactPosition = player.GlobalPosition;
        int stoppingFrames = 0;
        while (stoppingFrames < 60 && HasFloorContact(player, target) &&
               MathF.Abs(player.Velocity.X) > .5f)
        {
            TestAssert.True(!keyboardDrop || Mathf.Abs(input.Current.MoveAxis) <= .001f,
                "the ground-neutral tail does not hide a second steering intervention");
            stoppingFrames++;
            await PhysicsFrames(tree, monitor, 1);
        }
        TestAssert.True(HasFloorContact(player, target) &&
                        player.GlobalPosition.X >= targetLeft + radius - .5f &&
                        player.GlobalPosition.X <= targetRight - radius + .5f,
            $"Task10 zero-input fall lands the full capsule on actual {target.Name}; " +
            $"player={player.GlobalPosition} target={targetLeft:0.000}..{targetRight:0.000} " +
            $"radius={radius:0.000} velocity={player.Velocity} " +
            $"floor={DescribeFloorCollider(player)} fall_frames={fallFrames} " +
            $"contact={contactPosition} stop_frames={stoppingFrames} " +
            $"input_axis={input.Current.MoveAxis:0.000}");
        TestAssert.True(Mathf.Abs(input.Current.MoveAxis) <= .001f &&
                        MathF.Abs(player.Velocity.X) <= .5f,
            $"Task10 Archive fall reaches a zero-input stop on the actual target; " +
            $"release={releasePosition} release_velocity={releaseVelocity} " +
            $"contact={contactPosition} stop={player.GlobalPosition} " +
            $"stop_velocity={player.Velocity} sample={input.CurrentFrameSequence} " +
            $"move_axis={input.Current.MoveAxis:0.000}");
        if (keyboardDrop && source.Name == "ArchiveShelf" && target.Name == "ArchiveFloor")
            TestAssert.Near(predictedStopX, player.GlobalPosition.X, .03f,
                "unobstructed Archive fall and ground tail match the pre-release forecast, not just any platform");
        TestAssert.True(motor.AcceptedJumpCount == jumpsBefore &&
                        motor.AcceptedDashCount == dashesBefore &&
                        claw.CurrentFrame.State == clawBefore,
            $"Task10 shelf drop uses only real horizontal walk-off input; " +
            $"jumps={jumpsBefore}->{motor.AcceptedJumpCount} " +
            $"dashes={dashesBefore}->{motor.AcceptedDashCount} " +
            $"claw={clawBefore}->{claw.CurrentFrame.State}");
        GD.Print($"TASK10_INPUT_DROP_OK source={source.Name} target={target.Name} " +
            $"departure_frames={departureFrames} release_x={releaseX:0.000} " +
            $"release_velocity={releaseVelocity} fall_frames={fallFrames} " +
            $"preparation_neutral_frames={preparationNeutralFrames} predicted_stop_x={predictedStopX:0.000} " +
            $"supported_approach_frames={supportedApproachFrames} " +
            $"contact={contactPosition} stop_frames={stoppingFrames} " +
            $"stop={player.GlobalPosition} stop_velocity={player.Velocity} " +
            $"input_axis={input.Current.MoveAxis:0.000}");
        if (frozenKeyboardDrop)
            GD.Print($"TASK10_FROZEN_KEYBOARD_FALL health={dropHealthBefore}->{dropHealth.CurrentHealth} " +
                $"landings={dropLandingsBefore}->{motor.LandingCount} " +
                $"fall_height={motor.LastFallHeight:R} fall_damage={motor.LastFallDamage} " +
                $"damage_applied={motor.LastFallDamageApplied} player={player.GlobalPosition} " +
                $"floor={DescribeFloorCollider(player)}");
    }

    private static async Task TraverseArchiveFloorToFrozenLeft(SceneTree tree,
        CharacterBody2D player, RouteMonitor monitor, StaticBody2D archiveFloor,
        StaticBody2D frozenCeiling, StaticBody2D frozenLeft)
    {
        static (float Left, float Right, float Top) Bounds(StaticBody2D body)
        {
            RectangleShape2D shape =
                (RectangleShape2D)body.GetNode<CollisionShape2D>("Collision").Shape;
            return (body.GlobalPosition.X - shape.Size.X / 2f,
                body.GlobalPosition.X + shape.Size.X / 2f,
                body.GlobalPosition.Y - shape.Size.Y / 2f);
        }

        CapsuleShape2D capsule =
            (CapsuleShape2D)player.GetNode<CollisionShape2D>("BodyCollider").Shape;
        float radius = capsule.Radius;
        var archive = Bounds(archiveFloor);
        var ceiling = Bounds(frozenCeiling);
        var target = Bounds(frozenLeft);
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        MechanicalClawController claw =
            player.GetNode<MechanicalClawController>("MechanicalClaw");
        int jumpsBefore = motor.AcceptedJumpCount;
        int dashesBefore = motor.AcceptedDashCount;
        int recoveriesBefore = monitor.RecoveryCompleted;
        MechanicalClawState clawBefore = claw.CurrentFrame.State;
        TestAssert.True(HasFloorContact(player, archiveFloor),
            $"Task10 frozen detour starts on actual ArchiveFloor; " +
            $"player={player.GlobalPosition} floor={DescribeFloorCollider(player)}");

        if (Mathf.Abs(archive.Left - ceiling.Left) < .5f)
        {
            // The new72px slot continues beside both floor and ice. The old
            // jump-then-steer-right strategy deliberately re-entered the ice top
            // and stopped on a partial edge. Take the authored direct left drop.
            await DropFromSupportToLowerShelf(tree, player, monitor, archiveFloor, frozenLeft);
            TestAssert.True(HasFloorContact(player, frozenLeft) &&
                player.GlobalPosition.X >= target.Left + radius &&
                player.GlobalPosition.X + radius <= ceiling.Left &&
                motor.AcceptedJumpCount == jumpsBefore && motor.AcceptedDashCount == dashesBefore &&
                monitor.RecoveryCompleted == recoveriesBefore &&
                claw.CurrentFrame.State == clawBefore && claw.CurrentFrame.VelocityCorrection == Vector2.Zero,
                "new Archive slot keeps the full capsule clear of ice, naturally supported, no extra jump/claw/recovery");
            GD.Print($"TASK10_ARCHIVE_SLOT_OK player={player.GlobalPosition} jump=0 dash=0 recovery=0 full_capsule=true");
            return;
        }

        ReleaseAll(player.GlobalPosition);
        Vector2 jumpStart = player.GlobalPosition;
        SendAction(InputActions.MoveLeft, true);
        SendAction(InputActions.Jump, true);
        bool jumpReleased = false;
        bool clearedArchiveLeft = false;
        Vector2 leftClearPosition = Vector2.Zero;
        int ceilingFrames = 0;
        while (ceilingFrames < 240 && !HasFloorContact(player, frozenCeiling) &&
               !HasFloorContact(player, frozenLeft))
        {
            ceilingFrames++;
            await PhysicsFrames(tree, monitor, 1);
            if (!jumpReleased && ceilingFrames >= 7)
            {
                SendAction(InputActions.Jump, false);
                jumpReleased = true;
            }
            if (!clearedArchiveLeft && player.GlobalPosition.X <= archive.Left - radius)
            {
                clearedArchiveLeft = true;
                leftClearPosition = player.GlobalPosition;
                SendAction(InputActions.MoveLeft, false);
                SendAction(InputActions.MoveRight, true);
            }
            if (clearedArchiveLeft)
            {
                float minimum = ceiling.Left + radius + 12f;
                float maximum = ceiling.Right - radius - 12f;
                if (player.GlobalPosition.X < minimum)
                {
                    SendAction(InputActions.MoveLeft, false);
                    SendAction(InputActions.MoveRight, true);
                }
                else if (player.GlobalPosition.X > maximum)
                {
                    SendAction(InputActions.MoveRight, false);
                    SendAction(InputActions.MoveLeft, true);
                }
                else
                {
                    SendAction(InputActions.MoveLeft, false);
                    SendAction(InputActions.MoveRight, false);
                }
            }
        }
        ReleaseAll(player.GlobalPosition);
        await PhysicsFrames(tree, monitor, 2);
        bool directLanding = HasFloorContact(player, frozenLeft);
        Vector2 ceilingLanding = directLanding ? Vector2.Zero : player.GlobalPosition;
        TestAssert.True(clearedArchiveLeft && (directLanding &&
                            player.GlobalPosition.X >= target.Left + radius - .5f &&
                            player.GlobalPosition.X <= target.Right - radius + .5f ||
                        HasFloorContact(player, frozenCeiling) &&
                            ceilingLanding.X >= ceiling.Left + radius - .5f &&
                            ceilingLanding.X <= ceiling.Right - radius + .5f),
            $"Task10 one real jump clears ArchiveFloor's left edge and reaches a real " +
            $"frozen support; jump_start={jumpStart} left_clear={leftClearPosition} " +
            $"landing={player.GlobalPosition} direct_left={directLanding} " +
            $"velocity={player.Velocity} archive={archive.Left:0.0}..{archive.Right:0.0} " +
            $"ceiling={ceiling.Left:0.0}..{ceiling.Right:0.0} " +
            $"target={target.Left:0.0}..{target.Right:0.0} frames={ceilingFrames} " +
            $"floor={DescribeFloorCollider(player)}");

        int departureFrames = 0;
        Vector2 ceilingDeparture = Vector2.Zero;
        int targetFrames = 0;
        if (!directLanding)
        {
            SendAction(InputActions.MoveLeft, true);
            while (departureFrames < 120 &&
                   (HasFloorContact(player, frozenCeiling) || player.IsOnFloor()))
            {
                departureFrames++;
                await PhysicsFrames(tree, monitor, 1);
            }
            SendAction(InputActions.MoveLeft, false);
            SendAction(InputActions.MoveRight, true);
            ceilingDeparture = player.GlobalPosition;
            while (targetFrames < 180 && !HasFloorContact(player, frozenLeft))
            {
                targetFrames++;
                await PhysicsFrames(tree, monitor, 1);
                float minimum = target.Left + radius + 10f;
                float maximum = target.Right - radius - 10f;
                if (player.GlobalPosition.X < minimum || player.Velocity.X < -5f)
                {
                    SendAction(InputActions.MoveLeft, false);
                    SendAction(InputActions.MoveRight, true);
                }
                else if (player.GlobalPosition.X > maximum)
                {
                    SendAction(InputActions.MoveRight, false);
                    SendAction(InputActions.MoveLeft, true);
                }
                else
                {
                    SendAction(InputActions.MoveLeft, false);
                    SendAction(InputActions.MoveRight, false);
                }
            }
            ReleaseAll(player.GlobalPosition);
            await PhysicsFrames(tree, monitor, 2);
        }
        Vector2 targetLanding = player.GlobalPosition;
        TestAssert.True(HasFloorContact(player, frozenLeft) &&
                        targetLanding.X >= target.Left + radius - .5f &&
                        targetLanding.X <= target.Right - radius + .5f,
            $"Task10 leaves FrozenCeiling left and air-corrects onto actual FrozenLeftCatch; " +
            $"departure={ceilingDeparture} landing={targetLanding} " +
            $"velocity={player.Velocity} target={target.Left:0.0}..{target.Right:0.0} " +
            $"departure_frames={departureFrames} fall_frames={targetFrames} " +
            $"floor={DescribeFloorCollider(player)}");
        TestAssert.True(motor.AcceptedJumpCount == jumpsBefore + 1 &&
                        motor.AcceptedDashCount == dashesBefore &&
                        claw.CurrentFrame.State == clawBefore &&
                        monitor.RecoveryCompleted == recoveriesBefore,
            $"Task10 archive-to-frozen path uses one real jump plus A/D only; " +
            $"jumps={jumpsBefore}->{motor.AcceptedJumpCount} " +
            $"dashes={dashesBefore}->{motor.AcceptedDashCount} " +
            $"claw={clawBefore}->{claw.CurrentFrame.State} " +
            $"recoveries={recoveriesBefore}->{monitor.RecoveryCompleted}");
        PrologueSector sector = archiveFloor.GetParent().GetParent()
            .GetParent<PrologueSector>();
        TraversalSegment2D contract = sector.GetNode<TraversalSegment2D>(
            "Gameplay/TraversalContracts/canyonv2routearchive-to-frozen-detour");
        Vector2 localJumpStart = sector.ToLocal(jumpStart);
        Vector2 localTargetLanding = sector.ToLocal(targetLanding);
        bool authoredRightLaunchContainsActual = contract.LaunchZone.HasPoint(localJumpStart);
        TestAssert.True(authoredRightLaunchContainsActual,
            $"archive-to-frozen SingleJump launch metadata contains the physically proven " +
            $"normal-input takeoff; local_takeoff={localJumpStart} launch={contract.LaunchZone}");
        TestAssert.True(contract.LandingZone.HasPoint(localTargetLanding),
            $"archive-to-frozen SingleJump landing metadata contains the actual FrozenLeft " +
            $"landing; local_landing={localTargetLanding} landing={contract.LandingZone}");
        GD.Print($"TASK10_ARCHIVE_FROZEN_INPUT_OK jump_start={jumpStart} " +
            $"left_clear={leftClearPosition} ceiling_landing={ceilingLanding} " +
            $"ceiling_departure={ceilingDeparture} target_landing={targetLanding} " +
            $"direct_frozen_left={directLanding} " +
            $"single_jump=True dash=False claw=False " +
            $"authored_right_launch_contains_actual={authoredRightLaunchContainsActual} " +
            $"metadata_mismatch={!authoredRightLaunchContainsActual}");
    }

    private readonly record struct Task10LiftSupportSample(bool LiftFloor, bool FullSupport,
        bool InactiveLower, float CapsuleLeft, float CapsuleRight, float CarriageLeft,
        float CarriageRight, string Facts)
    {
        public bool Boarded => LiftFloor && FullSupport && InactiveLower;
        public float CenterX => (CarriageLeft + CarriageRight) * .5f;
        public float SafeLeftX => CarriageLeft + (CapsuleRight - CapsuleLeft) * .5f;
        public float SafeRightX => CarriageRight - (CapsuleRight - CapsuleLeft) * .5f;
    }

    private static bool TryTask10CapsuleCorridor(CharacterBody2D player,
        CollisionShape2D support, out float capsuleLeft, out float capsuleRight,
        out float supportLeft, out float supportRight)
    {
        capsuleLeft = capsuleRight = supportLeft = supportRight = float.NaN;
        bool Live(Node node) => node != null && GodotObject.IsInstanceValid(node) &&
            node.IsInsideTree();
        CollisionShape2D body = Live(player)
            ? player.GetNodeOrNull<CollisionShape2D>("BodyCollider") : null;
        if (!Live(body) || body.Disabled || !Live(support) || support.Disabled ||
            body.Shape is not CapsuleShape2D capsule ||
            support.Shape is not RectangleShape2D rectangle ||
            !GodotObject.IsInstanceValid(capsule) || !GodotObject.IsInstanceValid(rectangle))
            return false;
        Transform2D bodyTransform = body.GlobalTransform;
        Transform2D supportTransform = support.GlobalTransform;
        bool axisAligned = bodyTransform.Origin.IsFinite() && bodyTransform.X.IsFinite() &&
            bodyTransform.Y.IsFinite() && supportTransform.Origin.IsFinite() &&
            supportTransform.X.IsFinite() && supportTransform.Y.IsFinite() &&
            Mathf.Abs(bodyTransform.X.Y) < .001f &&
            Mathf.Abs(bodyTransform.Y.X) < .001f &&
            Mathf.Abs(supportTransform.X.Y) < .001f &&
            Mathf.Abs(supportTransform.Y.X) < .001f;
        if (!axisAligned || !float.IsFinite(capsule.Radius) || capsule.Radius <= 0f ||
            !rectangle.Size.IsFinite() || rectangle.Size.X <= 0f || rectangle.Size.Y <= 0f ||
            bodyTransform.X.X == 0f || supportTransform.X.X == 0f)
            return false;
        float radius = capsule.Radius * Mathf.Abs(bodyTransform.X.X);
        float halfWidth = rectangle.Size.X * Mathf.Abs(supportTransform.X.X) * .5f;
        capsuleLeft = bodyTransform.Origin.X - radius;
        capsuleRight = bodyTransform.Origin.X + radius;
        supportLeft = supportTransform.Origin.X - halfWidth;
        supportRight = supportTransform.Origin.X + halfWidth;
        return capsuleLeft >= supportLeft && capsuleRight <= supportRight;
    }

    private static Task10LiftSupportSample ReadTask10LiftSupport(CharacterBody2D player,
        CanyonCounterweightLift lift, RouteMonitor monitor)
    {
        bool Live(Node node) => node != null && GodotObject.IsInstanceValid(node) &&
            node.IsInsideTree();
        bool playerLive = Live(player);
        bool liftLive = Live(lift);
        CollisionShape2D body = playerLive
            ? player.GetNodeOrNull<CollisionShape2D>("BodyCollider") : null;
        CollisionShape2D carriage = liftLive
            ? lift.GetNodeOrNull<CollisionShape2D>("Collision") : null;
        bool bodyEnabled = Live(body) && !body.Disabled &&
            body.Shape is CapsuleShape2D;
        bool carriageEnabled = Live(carriage) && !carriage.Disabled &&
            carriage.Shape is RectangleShape2D;

        string floorPath = "none";
        bool liftFloor = false;
        if (playerLive && player.IsOnFloor())
        {
            for (int index = 0; index < player.GetSlideCollisionCount(); index++)
            {
                KinematicCollision2D collision = player.GetSlideCollision(index);
                if (!GodotObject.IsInstanceValid(collision) || collision.GetNormal().Y >= -.7f)
                    continue;
                GodotObject collider = collision.GetCollider();
                if (collider is Node floor && Live(floor))
                {
                    floorPath = $"{floor.GetPath()}#{floor.GetInstanceId()}";
                    if (floor == lift) liftFloor = true;
                }
                else
                    floorPath = "floor-collider-unavailable";
                if (liftFloor) break;
            }
        }

        bool fullSupport = TryTask10CapsuleCorridor(player, carriage,
            out float capsuleLeft, out float capsuleRight, out float carriageLeft,
            out float carriageRight);

        bool inactiveLower = false;
        if (liftLive && lift.GetParent() is Node2D parent && Live(parent))
        {
            Vector2 lowerWorld = parent.ToGlobal(lift.LowerPosition);
            inactiveLower = !lift.IsActivated && lift.Frame.Phase01 == 0f &&
                lowerWorld.IsFinite() && lift.GlobalPosition.IsFinite() &&
                lift.GlobalPosition.DistanceTo(lowerWorld) <= .5f;
        }
        HealthComponent health = playerLive
            ? player.GetNodeOrNull<HealthComponent>("Health") : null;
        string facts =
            $"physics={Engine.GetPhysicsFrames()} " +
            $"player={(playerLive ? player.GlobalPosition.ToString() : "unavailable")} " +
            $"velocity={(playerLive ? player.Velocity.ToString() : "unavailable")} " +
            $"lift={(liftLive ? lift.GlobalPosition.ToString() : "unavailable")} " +
            $"floor={floorPath} on_floor={(playerLive && player.IsOnFloor())} " +
            $"body_enabled={bodyEnabled} carriage_enabled={carriageEnabled} " +
            $"capsule_edges=({capsuleLeft:R},{capsuleRight:R}) " +
            $"carriage_edges=({carriageLeft:R},{carriageRight:R}) " +
            $"lift_floor={liftFloor} full_support={fullSupport} inactive_lower={inactiveLower} " +
            $"activated={(liftLive ? lift.IsActivated.ToString() : "unavailable")} " +
            $"frame={(liftLive ? lift.Frame.ToString() : "unavailable")} " +
            $"health={(Live(health) ? health.CurrentHealth.ToString() : "unavailable")} " +
            $"recovery={monitor.RecoveryRequested}/{monitor.RecoveryCompleted}";
        return new Task10LiftSupportSample(liftFloor, fullSupport, inactiveLower,
            capsuleLeft, capsuleRight, carriageLeft, carriageRight, facts);
    }

    private static void AssertTask10BoardedInactiveLowerLift(CharacterBody2D player,
        CanyonCounterweightLift lift, RouteMonitor monitor)
    {
        Task10LiftSupportSample support = ReadTask10LiftSupport(player, lift, monitor);
        TestAssert.True(support.Boarded,
            "Task10 Main must board the same live, enabled counterweight carriage " +
            "with full capsule support at its inactive lower endpoint before control input; " +
            support.Facts);
    }

    private static async Task RideTask10CounterweightLift(SceneTree tree,
        CharacterBody2D player, CanyonCounterweightLift lift, GrappleSurface2D control,
        StaticBody2D upperLanding, RouteMonitor monitor, Action observe)
    {
        bool Live(Node node) => node != null && GodotObject.IsInstanceValid(node) &&
            node.IsInsideTree();
        HealthComponent health = player.GetNode<HealthComponent>("Health");
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        PlayerInputReader reader = player.GetNode<PlayerInputReader>("Input");
        PlayerActionModeController modes = player.GetNode<PlayerActionModeController>("ActionModes");
        MechanicalClawController claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
        LegacyThreadInteractionAdapter adapter = control.GetNode<LegacyThreadInteractionAdapter>(
            "LegacyThreadInteractionAdapter");
        ulong playerId = player.GetInstanceId();
        ulong liftId = lift.GetInstanceId();
        int initialHealth = health.CurrentHealth;
        int initialRequests = monitor.RecoveryRequested;
        int initialRecoveries = monitor.RecoveryCompleted;
        int initialJumps = motor.AcceptedJumpCount;
        int initialDashes = motor.AcceptedDashCount;
        string stage = "board";
        string firstContact = "none";
        string firstLoss = "none";
        bool requireLiftSupport = false;
        bool keyboard = KeyboardRouteInputDriver.Current != null;
        ulong controlInputSequence = 0UL, sampledClawSequence = 0UL;
        int sampledClawEdges = 0;

        string Snapshot()
        {
            Task10LiftSupportSample support = ReadTask10LiftSupport(player, lift, monitor);
            return $"stage={stage} {support.Facts} player_id={playerId} lift_id={liftId} " +
                $"claw={(Live(claw) ? $"{claw.CurrentFrame.State}/{claw.CurrentFrame.CastId}/{claw.CurrentFrame.Failure}" : "unavailable")} " +
                $"mode={(Live(modes) ? modes.CurrentMode.ToString() : "unavailable")} " +
                $"jumps={(Live(motor) ? motor.AcceptedJumpCount.ToString() : "unavailable")}/{initialJumps} " +
                $"dashes={(Live(motor) ? motor.AcceptedDashCount.ToString() : "unavailable")}/{initialDashes} " +
                $"first_contact=[{firstContact}] first_loss=[{firstLoss}]";
        }
        void Check(string condition, bool passed) =>
            TestAssert.True(passed, $"Task10 physical lift {condition}; {Snapshot()}");
        async Task Tick()
        {
            await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
            observe();
            if (keyboard && controlInputSequence != 0UL &&
                reader.CurrentFrameSequence > controlInputSequence &&
                reader.CurrentFrameSequence != sampledClawSequence && reader.CurrentFrame.ClawPressed)
            {
                sampledClawSequence = reader.CurrentFrameSequence;
                sampledClawEdges++;
            }
            Check("preserves player, lift, HP, accepted movement and paired recoveries",
                Live(player) && Live(lift) && Live(health) && Live(motor) &&
                player.GetInstanceId() == playerId && lift.GetInstanceId() == liftId &&
                health.CurrentHealth == initialHealth && initialHealth > 0 &&
                monitor.RecoveryRequested == initialRequests &&
                monitor.RecoveryCompleted == initialRecoveries &&
                motor.AcceptedJumpCount == initialJumps &&
                motor.AcceptedDashCount == initialDashes);
            if (requireLiftSupport)
            {
                Task10LiftSupportSample support = ReadTask10LiftSupport(player, lift, monitor);
                Check("retains same named upward carriage contact and full capsule support",
                    support.LiftFloor && support.FullSupport);
            }
        }
        void Move(bool left, bool right)
        {
            SendAction(InputActions.MoveLeft, left);
            SendAction(InputActions.MoveRight, right);
        }
        // Opposite directional input is used only to brake ordinary walking, never to propel
        // the lift. The braking distance is recomputed from measured speed each physics tick.
        void SteerToward(float centerX)
        {
            float x = player.GlobalPosition.X;
            float speed = player.Velocity.X;
            float brake = speed * speed / (2f * motor.Tuning.AirAcceleration) + 4f;
            bool right = x < centerX - 2f && (speed <= 0f || x + brake < centerX);
            bool left = x > centerX + 2f && (speed >= 0f || x - brake > centerX);
            Move(left, right);
        }

        SendAction(InputActions.MoveLeft, false);
        SendAction(InputActions.MoveRight, false);
        SendAction(InputActions.MoveUp, false);
        SendAction(InputActions.MoveDown, false);
        SendAction(InputActions.Jump, false);
        SendAction(InputActions.Dash, false);
        SendAction(InputActions.SelectAttackMode, false);
        SendAction(InputActions.SelectGrappleMode, false);
        SendMouse(MouseButton.Left, false, player, player.GlobalPosition);
        SendMouse(MouseButton.Right, false, player, player.GlobalPosition);
        try
        {
            bool boarded = false;
            for (int frame = 0; frame < 160; frame++)
            {
                Task10LiftSupportSample support = ReadTask10LiftSupport(player, lift, monitor);
                if (support.Boarded)
                {
                    boarded = true;
                    break;
                }
                Check("boarding uses the live inactive lower carriage corridor",
                    support.InactiveLower && float.IsFinite(support.CenterX) &&
                    support.SafeLeftX < support.SafeRightX);
                SteerToward(support.CenterX);
                await Tick();
                support = ReadTask10LiftSupport(player, lift, monitor);
                if (firstContact == "none" && support.LiftFloor)
                    firstContact = support.Facts;
                if (firstContact != "none" && firstLoss == "none" && !support.LiftFloor)
                    firstLoss = support.Facts;
                Check("boarding remains within recoverable lower-carriage approach",
                    player.GlobalPosition.X <= support.CarriageRight + 20f &&
                    player.GlobalPosition.Y <= lift.GlobalPosition.Y + 60f);
            }
            Move(false, false);
            boarded |= ReadTask10LiftSupport(player, lift, monitor).Boarded;
            Check("boarding reaches first actual full carriage support", boarded);
            ulong boardReleaseSequence = reader.CurrentFrameSequence;
            for (int frame = 0; frame < 12; frame++)
            {
                Task10LiftSupportSample support = ReadTask10LiftSupport(player, lift, monitor);
                Check("neutral boarding settle retains full named lift support", support.Boarded);
                if (reader.CurrentFrameSequence > boardReleaseSequence &&
                    Mathf.IsZeroApprox(reader.CurrentFrame.MoveAxis) &&
                    Mathf.Abs(player.Velocity.X) <= 3f) break;
                await Tick();
            }
            AssertTask10BoardedInactiveLowerLift(player, lift, monitor);
            Check("neutral sampled boarding settles before control input",
                reader.CurrentFrameSequence > boardReleaseSequence &&
                Mathf.IsZeroApprox(reader.CurrentFrame.MoveAxis) &&
                Mathf.Abs(player.Velocity.X) <= 3f);
            GD.Print($"TASK10_LIFT_BOARD_OK {Snapshot()}");

            stage = "control";
            requireLiftSupport = true;
            Vector2 startPlayer = player.GlobalPosition;
            Vector2 startLift = lift.GlobalPosition;
            float initialRelativeY = startPlayer.Y - startLift.Y;
            int applications = adapter.ApplicationCount;
            MoveMouse(player, control.WorldAnchor);
            ulong beforeModeSequence = reader.CurrentFrameSequence;
            ulong sampledModeSequence = 0;
            SendAction(InputActions.SelectGrappleMode, true);
            try
            {
                if (keyboard)
                {
                    // The control is 15 degrees above right: neutral right, not W+D.
                    // Turn only through a real key if boarding did not already face right.
                    if (reader.KeyboardAimDirection.Dot(Vector2.Right) < .99f)
                    {
                        Move(false, true);
                        await Tick();
                        Move(false, false);
                    }
                    for (int frame = 0; frame < 12 &&
                         (!Mathf.IsZeroApprox(reader.CurrentFrame.MoveAxis) ||
                          Mathf.Abs(player.Velocity.X) > 3f); frame++) await Tick();
                    Check("keyboard idle control readiness uses neutral actual right aim without E",
                        modes.CanBeginGrapple && claw.CurrentFrame.State == MechanicalClawState.Idle &&
                        reader.CurrentFrame.KeyboardActions && reader.CurrentFrame.Aim.IsZeroApprox() &&
                        reader.KeyboardAimDirection.Dot(Vector2.Right) > .99f &&
                        Mathf.IsZeroApprox(reader.CurrentFrame.MoveAxis) &&
                        Mathf.Abs(player.Velocity.X) <= 3f &&
                        !Input.IsActionPressed(InputActions.Claw) &&
                        !Input.IsActionPressed(InputActions.Attack) &&
                        !reader.CurrentFrame.GrappleModePressed && !reader.CurrentFrame.AttackModePressed &&
                        !reader.CurrentFrame.PrimaryPressed && !reader.CurrentFrame.ShieldHeld);
                }
                else
                {
                    for (int frame = 0; frame < 8; frame++)
                    {
                        await Tick();
                        if (reader.CurrentFrameSequence > beforeModeSequence &&
                            reader.CurrentFrame.GrappleModePressed)
                            sampledModeSequence = reader.CurrentFrameSequence;
                        if (sampledModeSequence != 0 && modes.CanBeginGrapple &&
                            claw.CurrentFrame.State == MechanicalClawState.Idle) break;
                    }
                    Check($"real E sample selects idle grapple mode " +
                    $"before_seq={beforeModeSequence} sampled_seq={sampledModeSequence} " +
                    $"current_seq={reader.CurrentFrameSequence} " +
                    $"current_E={reader.CurrentFrame.GrappleModePressed} " +
                    $"mode={modes.CurrentMode} claw={claw.CurrentFrame.State}",
                    sampledModeSequence > beforeModeSequence && modes.CanBeginGrapple &&
                    claw.CurrentFrame.State == MechanicalClawState.Idle);
                }
                GD.Print($"TASK10_LIFT_MODE_OK keyboard={keyboard} physics={Engine.GetPhysicsFrames()} " +
                    $"before_seq={beforeModeSequence} sampled_seq={sampledModeSequence} " +
                    $"current_seq={reader.CurrentFrameSequence} " +
                    $"mode={modes.CurrentMode} claw={claw.CurrentFrame.State} " +
                    $"player={player.GlobalPosition} lift={lift.GlobalPosition}");
            }
            finally { SendAction(InputActions.SelectGrappleMode, false); }
            Vector2 anchor = control.WorldAnchor;
            var controlResolver = new MechanicalClawTargetResolver();
            MechanicalClawTargetResolution resolution = keyboard
                ? controlResolver.ResolveKeyboard(player, reader.KeyboardAimDirection)
                : controlResolver.Resolve(player, anchor);
            Check("visible same-space control resolves with real LOS and range",
                Live(control) && control.GetWorld2D() == player.GetWorld2D() &&
                IsTargetVisible(player, anchor) &&
                player.GlobalPosition.DistanceTo(anchor) <= MechanicalClawSettings.Default.MaxRange &&
                resolution.Surface == control && resolution.Snapshot.HasLineOfSight &&
                (!keyboard || claw.KeyboardPreview.Surface == control &&
                    claw.KeyboardPreview.Snapshot.HasLineOfSight));
            GD.Print($"TASK10_LIFT_CONTROL_EDGE_OK {Snapshot()} " +
                $"control={control.GetPath()}#{control.GetInstanceId()} anchor={anchor} " +
                $"viewport={ToViewport(player, anchor)} resolver={resolution.Surface?.GetInstanceId() ?? 0} " +
                $"los={resolution.Snapshot.HasLineOfSight} applications={applications}");
            ulong expectedCast = claw.CurrentFrame.NextCastId;
            controlInputSequence = reader.CurrentFrameSequence;
            SendMouse(MouseButton.Left, true, player, anchor);
            for (int frame = 0; frame < 6 && claw.CurrentFrame.State == MechanicalClawState.Idle;
                 frame++)
                await Tick();
            Check("fresh primary/K enters one real control cast",
                claw.CurrentFrame.State is MechanicalClawState.Aim or
                    MechanicalClawState.Windup or MechanicalClawState.Travel);
            if (keyboard)
                Check("one fresh K sample starts the selected control without legacy primary or J",
                    sampledClawEdges == 1 && sampledClawSequence > controlInputSequence &&
                    !reader.CurrentFrame.PrimaryPressed && !reader.CurrentFrame.AttackPressed &&
                    !reader.CurrentFrame.InteractPressed && reader.CurrentFrame.KeyboardActions &&
                    reader.KeyboardAimDirection.Dot(Vector2.Right) > .99f &&
                    Mathf.IsZeroApprox(reader.CurrentFrame.MoveAxis) &&
                    claw.CurrentTarget == control);
            SendMouse(MouseButton.Left, false, player, anchor);
            for (int frame = 0; frame < 6 && claw.CurrentFrame.CastId == 0; frame++)
                await Tick();
            ulong castId = claw.CurrentFrame.CastId;
            Check("real cast advances past Aim into assigned cast ID",
                castId == expectedCast && claw.CurrentFrame.State is MechanicalClawState.Windup or
                    MechanicalClawState.Travel);
            for (int frame = 0; frame < 90 && !lift.IsActivated; frame++)
            {
                MoveMouse(player, anchor);
                await Tick();
            }
            Check("same control cast applies to the real lift",
                lift.IsActivated && adapter.ApplicationCount == applications + 1 &&
                claw.CurrentFrame.NextCastId == expectedCast + 1UL &&
                (!keyboard || sampledClawEdges == 1));
            GD.Print($"TASK10_LIFT_CAST_OK {Snapshot()} cast={castId} " +
                $"applications={applications}->{adapter.ApplicationCount}");

            stage = "ride";
            bool sawMotion = false;
            Vector2 upperWorld = lift.GetParent<Node2D>().ToGlobal(lift.UpperPosition);
            for (int frame = 0; frame < 180; frame++)
            {
                float liftRise = startLift.Y - lift.GlobalPosition.Y;
                float playerRise = startPlayer.Y - player.GlobalPosition.Y;
                sawMotion |= liftRise > 1f && playerRise > 1f;
                Check("ride displacement stays coupled to the same carriage",
                    Mathf.Abs((player.GlobalPosition.Y - lift.GlobalPosition.Y) -
                        initialRelativeY) <= 8f && liftRise >= -1f && playerRise >= -1f);
                if (lift.GlobalPosition.DistanceTo(upperWorld) <= .5f &&
                    lift.Frame.Phase01 >= .999f) break;
                await Tick();
            }
            Check("supported transport rises over 400px to authored upper stop",
                sawMotion && startLift.Y - lift.GlobalPosition.Y > 400f &&
                startPlayer.Y - player.GlobalPosition.Y > 400f &&
                lift.GlobalPosition.DistanceTo(upperWorld) <= .5f &&
                lift.Frame.Phase01 >= .999f);
            GD.Print($"TASK10_LIFT_RIDE_OK {Snapshot()} " +
                $"lift_rise={startLift.Y - lift.GlobalPosition.Y:R} " +
                $"player_rise={startPlayer.Y - player.GlobalPosition.Y:R} " +
                $"relative_y={initialRelativeY:R}->{player.GlobalPosition.Y - lift.GlobalPosition.Y:R}");

            stage = "dismount";
            requireLiftSupport = false;
            CollisionShape2D landingShape = upperLanding.GetNode<CollisionShape2D>("Collision");
            string DismountFailureFacts()
            {
                string ColliderFacts(Node2D owner)
                {
                    if (!Live(owner)) return "unavailable-owner";
                    CollisionShape2D shape = owner.GetNodeOrNull<CollisionShape2D>("Collision");
                    if (!Live(shape)) return $"{owner.GetPath()}#{owner.GetInstanceId()}/collision-unavailable";
                    string size = shape.Shape is RectangleShape2D rectangle &&
                        GodotObject.IsInstanceValid(rectangle)
                        ? rectangle.Size.ToString() : "unavailable";
                    return $"{owner.GetPath()}#{owner.GetInstanceId()}/enabled={!shape.Disabled}" +
                        $"/rectangle_size={size}/global_transform={shape.GlobalTransform}";
                }

                var contacts = new List<string>();
                if (Live(player))
                {
                    for (int index = 0; index < player.GetSlideCollisionCount(); index++)
                    {
                        KinematicCollision2D collision = player.GetSlideCollision(index);
                        if (!GodotObject.IsInstanceValid(collision))
                        {
                            contacts.Add($"{index}:invalid-collision");
                            continue;
                        }
                        GodotObject collider = collision.GetCollider();
                        string path = collider is Node node && Live(node)
                            ? $"{node.GetPath()}#{node.GetInstanceId()}"
                            : "collider-unavailable";
                        contacts.Add($"{index}:{path}/normal={collision.GetNormal()}");
                    }
                }
                StaticBody2D grip = Live(upperLanding) && Live(upperLanding.GetParent())
                    ? upperLanding.GetParent().GetNodeOrNull<StaticBody2D>("AscentGrip2Grip")
                    : null;
                return $"input_seq={(Live(reader) ? reader.CurrentFrameSequence.ToString() : "unavailable")} " +
                    $"move_axis={(Live(reader) ? reader.CurrentFrame.MoveAxis.ToString("R") : "unavailable")} " +
                    $"effective_scale={(Live(motor) ? motor.EffectiveMovementScale.ToString("R") : "unavailable")} " +
                    $"slide_contacts=[{(contacts.Count > 0 ? string.Join(";", contacts) : "none")}] " +
                    $"lift_collider=[{ColliderFacts(lift)}] " +
                    $"landing_collider=[{ColliderFacts(upperLanding)}] " +
                    $"grip2grip_collider=[{ColliderFacts(grip)}]";
            }
            bool Landed()
            {
                bool full = TryTask10CapsuleCorridor(player, landingShape,
                    out _, out _, out _, out _);
                return full && HasFloorContact(player, upperLanding);
            }
            bool reachedLanding = false;
            string firstNonLiftDismountContact = "none";
            for (int frame = 0; frame < 150; frame++)
            {
                if (Landed())
                {
                    reachedLanding = true;
                    break;
                }
                TryTask10CapsuleCorridor(player, landingShape,
                    out float capsuleLeft, out float capsuleRight,
                    out float landingLeft, out float landingRight);
                float radius = (capsuleRight - capsuleLeft) * .5f;
                Check("upper landing collider defines a full-capsule destination",
                    Live(upperLanding) && Live(landingShape) &&
                    float.IsFinite(landingLeft) && float.IsFinite(landingRight) &&
                    landingLeft + radius < landingRight - radius);
                float desired = (landingLeft + landingRight) * .5f;
                SteerToward(desired);
                await Tick();
                if (firstNonLiftDismountContact == "none")
                {
                    for (int index = 0; index < player.GetSlideCollisionCount(); index++)
                    {
                        KinematicCollision2D collision = player.GetSlideCollision(index);
                        if (!GodotObject.IsInstanceValid(collision)) continue;
                        GodotObject collider = collision.GetCollider();
                        if (!GodotObject.IsInstanceValid(collider) ||
                            collider.GetInstanceId() == liftId) continue;
                        firstNonLiftDismountContact =
                            $"physics={Engine.GetPhysicsFrames()} contact_index={index} " +
                            $"collider_id={collider.GetInstanceId()} " +
                            $"player={player.GlobalPosition} lift={lift.GlobalPosition} " +
                            $"velocity={player.Velocity} {DismountFailureFacts()}";
                        break;
                    }
                }
                Task10LiftSupportSample liftSupport = ReadTask10LiftSupport(player, lift, monitor);
                if (liftSupport.LiftFloor)
                {
                    bool upperStop = lift.GlobalPosition.DistanceTo(upperWorld) <= .5f;
                    if (!upperStop)
                        Check("walk-off begins while the actual lift is at its upper stop; " +
                            DismountFailureFacts() +
                            $" first_non_lift_contact=[{firstNonLiftDismountContact}]", false);
                }
                Check("dismount stays within the authored upper catch",
                    player.GlobalPosition.X >= landingLeft - 20f &&
                    player.GlobalPosition.Y <= upperLanding.GlobalPosition.Y + 100f);
            }
            Move(false, false);
            reachedLanding |= Landed();
            Check("ordinary left walk/drop reaches first full AscentGrip2 support",
                reachedLanding);
            ulong landingReleaseSequence = reader.CurrentFrameSequence;
            for (int frame = 0; frame < 12; frame++)
            {
                Check("neutral dismount settle retains full named AscentGrip2 support", Landed());
                if (reader.CurrentFrameSequence > landingReleaseSequence &&
                    Mathf.IsZeroApprox(reader.CurrentFrame.MoveAxis) &&
                    Mathf.Abs(player.Velocity.X) <= 3f) break;
                await Tick();
            }
            Check("ordinary left walk/drop settles on full AscentGrip2 support",
                Landed() && reader.CurrentFrameSequence > landingReleaseSequence &&
                Mathf.IsZeroApprox(reader.CurrentFrame.MoveAxis) &&
                Mathf.Abs(player.Velocity.X) <= 3f);
            GD.Print($"TASK10_LIFT_DISMOUNT_OK {Snapshot()} " +
                $"landing={upperLanding.GetPath()}#{upperLanding.GetInstanceId()} " +
                $"supported={Landed()}");
        }
        finally
        {
            Move(false, false);
            SendAction(InputActions.MoveUp, false);
            SendAction(InputActions.MoveDown, false);
            SendAction(InputActions.Jump, false);
            SendAction(InputActions.Dash, false);
            SendAction(InputActions.SelectGrappleMode, false);
            SendMouse(MouseButton.Left, false, player,
                GodotObject.IsInstanceValid(player) ? player.GlobalPosition : Vector2.Zero);
        }
    }

    private static bool HasFloorContact(CharacterBody2D player, StaticBody2D support)
    {
        if (!player.IsOnFloor()) return false;
        for (int index = 0; index < player.GetSlideCollisionCount(); index++)
        {
            KinematicCollision2D collision = player.GetSlideCollision(index);
            if (collision.GetCollider() == support && collision.GetNormal().Y < -.7f)
                return true;
        }
        return false;
    }

    private static PrologueGameFlowController ConfigureTask10Persistence(
        PrologueLevelController level, Task10ApplicationPersistenceGuard persistence)
    {
        PrologueGameFlowController flow = level.GetNode<PrologueGameFlowController>("GameFlow");
        flow.SavePath = persistence.ResolveWritablePath("save.json");
        flow.SettingsPath = persistence.ResolveWritablePath("settings.json");
        ProloguePlaytestRecorder recorder = level.GetNode<ProloguePlaytestRecorder>(
            "PlaytestRecorder");
        recorder.OutputDirectory = persistence.ResolveWritablePath("playtests");
        persistence.AssertInjectedPaths(flow.SavePath, flow.SettingsPath,
            recorder.OutputDirectory);
        return flow;
    }

    private static void SendUiAccept(Node canvas, bool pressed)
    {
        if(KeyboardRouteInputDriver.Current!=null)
        {
            var physical = new InputEventKey { PhysicalKeycode=Key.Enter, Keycode=Key.Enter, Pressed=pressed };
            canvas.GetViewport().PushInput(physical,true);
            Input.ParseInputEvent(physical);
            Input.FlushBufferedEvents();
            return;
        }
        var input = new InputEventAction
        {
            Action = "ui_accept",
            Pressed = pressed,
            Strength = pressed ? 1f : 0f
        };
        canvas.GetViewport().PushInput(input, true);
        Input.ParseInputEvent(input);
        Input.FlushBufferedEvents();
    }

    public static async Task RunTask4(SceneTree tree, bool captureFrames = false)
    {
        string output=ResolveCaptureOutput(captureFrames);
        var level=GD.Load<PackedScene>(MainPath).Instantiate<PrologueLevelController>();
        level.Name="Task4GeneratedMainProof";
        var flow=level.GetNode<PrologueGameFlowController>("GameFlow");
        flow.AutomationAutoStart=true;
        string fixture=$"user://task4-generated-main/{Guid.NewGuid():N}";
        flow.SavePath=fixture+"/save.json"; flow.SettingsPath=fixture+"/settings.json";
        var player=level.GetNode<CharacterBody2D>("PlayerRoot/Player");
        TestAssert.Equal(new Vector2(160,600),player.Position,"main proof uses the generated spawn, not a route teleport");
        var camera=player.GetNode<Camera2D>("Camera2D");
        camera.Enabled=true; tree.Root.AddChild(level);
        var world=level.GetNode<SeamlessPrologueWorld>("WorldRoot/Sectors");
        using var monitor=new RouteMonitor(level,player,camera,world,player.GetInstanceId());
        try
        {
            await PhysicsFrames(tree,monitor,8);
            TestAssert.Equal(2,world.LayoutVersion,"actual generated main activates layout2");
            await PrologueCanyonTraversalTests.DriveTask4GeneratedMain(tree,world,player,() =>
                { monitor.Observe(); monitor.AssertFullCapsuleVisible(); },
                async name => { monitor.AssertNoProductionRecovery(name); await Capture(tree,captureFrames,output,name);
                    GD.Print($"TASK4_GENERATED_MAIN_MILESTONE name={name} sector={world.CurrentSector} position={player.GlobalPosition}"); });
            monitor.AssertNoProductionRecovery("v2 generated-main traversal");
            TestAssert.Equal(PrologueObjective.LearnAttackMode,level.GetNode<PrologueCompletionController>("Completion").CurrentObjective,
                "bypassing the entrance lesson never force-completes or changes its pending progress");
            TestAssert.True(level.Progress.RestoreCheckpoint() is {HasActivatedCheckpoint:true,SectorId:PrologueSectorId.LostTemple},
                "continuous main route physically activates the real pre-boss checkpoint");
            monitor.AssertComplete();
            GD.Print($"TASK4_GENERATED_MAIN_TO_PREBOSS_INPUT_OK sectors={string.Join(',',monitor.Visited)} frames={monitor.Frames} max_step={monitor.MaxStep} persistent_player=True recovery=0");
        }
        finally
        {
            ReleaseAll(Vector2.Zero); monitor.Dispose(); level.QueueFree();
            await tree.ToSignal(tree,SceneTree.SignalName.ProcessFrame);
            for(int i=0;i<4;i++) await tree.ToSignal(tree,SceneTree.SignalName.PhysicsFrame);
        }
    }

    public static async Task<bool> Run(SceneTree tree, bool captureFrames)
        => await Run(tree, captureFrames, observer: null);

    internal static async Task<bool> Run(SceneTree tree, bool captureFrames,
        ITask9GeneratedMainMilestoneObserver observer)
    {
        ReleaseAll(Vector2.Zero);
        string captureOutput = ResolveCaptureOutput(captureFrames);
        PackedScene packed = GD.Load<PackedScene>(MainPath) ??
            throw new InvalidOperationException($"exact generated main scene is missing: {MainPath}");
        PrologueLevelController level = packed.Instantiate<PrologueLevelController>();
        level.Name = "Task8Fix1GeneratedMainProof";
        CharacterBody2D player = level.GetNode<CharacterBody2D>("PlayerRoot/Player");
        player.Position = new Vector2(120f, 574f); // sole pre-tree spawn assignment
        PrologueGameFlowController flow = level.GetNode<PrologueGameFlowController>("GameFlow");
        flow.AutomationAutoStart = true;
        flow.SavePath = $"user://task8-fix1-proof/{Guid.NewGuid():N}/save.json";
        flow.SettingsPath = $"user://task8-fix1-proof/{Guid.NewGuid():N}/settings.json";
        observer?.Configure(level);
        Camera2D camera = player.GetNode<Camera2D>("Camera2D");
        camera.Enabled = true;
        ulong playerId = player.GetInstanceId();
        tree.Root.AddChild(level);
        SeamlessPrologueWorld world = level.GetNode<SeamlessPrologueWorld>("WorldRoot/Sectors");
        var monitor = new RouteMonitor(level, player, camera, world, playerId);
        try
        {
            await PhysicsFrames(tree, monitor, 5);
            monitor.AssertCurrent(PrologueSectorId.CanyonEntrance);
            await Capture(tree, captureFrames, captureOutput, "01-entrance");
            if (observer != null)
                await observer.BeforeBasin(new Task9GeneratedMainContext(level, player, world,
                    count => PhysicsFrames(tree, monitor, count)));

            await DriveHorizontalUntil(tree, monitor, moveRight: true,
                stop: () => world.CurrentSector == PrologueSectorId.CanyonDescent,
                maxFrames: 520, jumpPeriod: 52);
            await StableSector(tree, monitor, PrologueSectorId.CanyonDescent, "02-descent",
                captureFrames, captureOutput);
            if (observer != null)
                await observer.AtDescent(new Task9GeneratedMainContext(level, player, world,
                    count => PhysicsFrames(tree, monitor, count)));
            if (DisplayServer.GetName() == "headless" && observer == null)
            {
                GD.Print($"TASK8_GENERATED_MAIN_HEADLESS_STREAM_OK current={world.CurrentSector} " +
                    $"frames={monitor.Frames} mounted={string.Join(",", world.MountedSectorIds)} " +
                    $"max_step={monitor.MaxStep:0.00} recovery_requested={monitor.RecoveryRequested} " +
                    $"recovery_completed={monitor.RecoveryCompleted} pointer_boundary=DescentGrapple");
                monitor.AssertNoProductionRecovery("headless generated-main stream boundary");
                return false;
            }

            PrologueSector descent = Mounted(world, PrologueSectorId.CanyonDescent);
            await GrappleToLanding(tree, monitor, descent,
                "descent_grip_lesson", maxFrames: 220);
            if (observer != null)
                await observer.AfterDescentGrapple(new Task9GeneratedMainContext(level, player,
                    world, count => PhysicsFrames(tree, monitor, count)));
            if (observer != null)
            {
                await DriveHorizontalUntil(tree, monitor, moveRight: true,
                    stop: () => world.CurrentSector == PrologueSectorId.CanyonDescent &&
                        player.GlobalPosition.Y >= 1360f,
                    maxFrames: 600, jumpPeriod: 58);
                await observer.BeforeBasinSeam(new Task9GeneratedMainContext(level, player,
                    world, count => PhysicsFrames(tree, monitor, count)));
            }
            await DriveHorizontalUntil(tree, monitor, moveRight: true,
                stop: () => world.CurrentSector == PrologueSectorId.CanyonBasin,
                maxFrames: 720, jumpPeriod: 58);
            await StableSector(tree, monitor, PrologueSectorId.CanyonBasin, "03-basin",
                captureFrames, captureOutput);
            if (observer != null)
                await observer.AtBasinBeforeShieldLane(new Task9GeneratedMainContext(level, player,
                    world, count => PhysicsFrames(tree, monitor, count)));

            await WaitForFloor(tree, monitor, 300);
            await DriveHorizontalUntil(tree, monitor, moveRight: false,
                stop: () => player.GlobalPosition.X <= 2040f, maxFrames: 240, jumpPeriod: 0);
            int basinHealth = player.GetNode<Knight.Combat.HealthComponent>("Health").CurrentHealth;
            SendMouse(MouseButton.Right, true, player, player.GlobalPosition + Vector2.Right * 240f);
            await PhysicsFrames(tree, monitor, 3);
            TestAssert.True(player.GetNode<PlayerShieldController>("Shield").IsActive,
                "continuous reverse approach raises the real source-facing shield before the lane");
            await DriveHorizontalUntil(tree, monitor, moveRight: false,
                stop: () => player.GlobalPosition.X <= 1560f, maxFrames: 300, jumpPeriod: 0,
                mouseAim: () => player.GlobalPosition + Vector2.Right * 240f);
            SendMouse(MouseButton.Right, false, player, player.GlobalPosition + Vector2.Right * 240f);
            TestAssert.Equal(basinHealth,
                player.GetNode<Knight.Combat.HealthComponent>("Health").CurrentHealth,
                "source-facing shield prevents damage on the returnable reverse lane crossing");
            PlayerEnergyController basinEnergy = player.GetNode<PlayerEnergyController>("Energy");
            for (int frame = 0; frame < 360 &&
                 (basinEnergy.EnergyRatio < .98f || basinEnergy.HeatRatio > .02f); frame++)
                await PhysicsFrames(tree, monitor, 1);
            TestAssert.True(basinEnergy.EnergyRatio >= .98f && basinEnergy.HeatRatio <= .02f,
                "continuous route waits for visible shield cooldown/regeneration before returning");
            await DriveHorizontalUntil(tree, monitor, moveRight: true,
                stop: () => player.GlobalPosition.X >= 1600f,
                maxFrames: 80, jumpPeriod: 0);
            SendMouse(MouseButton.Right, true, player, player.GlobalPosition + Vector2.Right * 100f);
            await PhysicsFrames(tree, monitor, 3);
            TestAssert.True(player.GetNode<PlayerShieldController>("Shield").IsActive,
                "continuous mandatory crossing raises the regenerated right-facing shield");
            await DriveHorizontalUntil(tree, monitor, moveRight: true,
                stop: () => player.GlobalPosition.X >= 2000f,
                maxFrames: 320, jumpPeriod: 0,
                mouseAim: () => player.GlobalPosition + Vector2.Right * 240f);
            SendMouse(MouseButton.Right, false, player, player.GlobalPosition + Vector2.Right * 240f);
            TestAssert.Equal(basinHealth,
                player.GetNode<Knight.Combat.HealthComponent>("Health").CurrentHealth,
                "source-facing shield prevents damage on the mandatory forward lane crossing");
            if (observer != null)
            {
                await DriveHorizontalUntil(tree, monitor, moveRight: true,
                    stop: () => level.Progress.RestoreCheckpoint() is
                    { HasActivatedCheckpoint: true, SectorId: PrologueSectorId.CanyonBasin },
                    maxFrames: 240, jumpPeriod: 0);
                await observer.AfterBasinCheckpoint(new Task9GeneratedMainContext(level, player,
                    world, count => PhysicsFrames(tree, monitor, count)));
            }
            await DriveHorizontalUntil(tree, monitor, moveRight: true,
                stop: () => world.CurrentSector == PrologueSectorId.CanyonAscent,
                maxFrames: 560, jumpPeriod: 60);
            SendMouse(MouseButton.Right, false, player, player.GlobalPosition);
            await StableSector(tree, monitor, PrologueSectorId.CanyonAscent, "04-ascent",
                captureFrames, captureOutput);

            PrologueSector ascent = Mounted(world, PrologueSectorId.CanyonAscent);
            foreach (string segment in new[]
                     { "ascent_grapple_one", "ascent_grapple_two", "ascent_grapple_three" })
                await GrappleToLanding(tree, monitor, ascent, segment, maxFrames: 300);
            await DriveHorizontalUntil(tree, monitor, moveRight: true,
                stop: () => player.GlobalPosition.X >= 4080f,
                maxFrames: 320, jumpPeriod: 0);
            TraceFinalSeam(monitor, "before-press");
            SendAction(InputActions.MoveRight, true);
            PulseJump(true);
            await PhysicsFrames(tree, monitor, 1);
            TraceFinalSeam(monitor, "held-1");
            await PhysicsFrames(tree, monitor, 7);
            TraceFinalSeam(monitor, "held-8");
            PulseJump(false);
            for (int frame = 0; frame < 120 &&
                 world.CurrentSector != PrologueSectorId.LostTemple; frame++)
            {
                await PhysicsFrames(tree, monitor, 1);
                if (frame % 8 == 0) TraceFinalSeam(monitor, $"released-{frame}");
            }
            TraceFinalSeam(monitor, "end");
            SendAction(InputActions.MoveRight, false);
            TestAssert.Equal(PrologueSectorId.LostTemple, world.CurrentSector,
                "one real Space press clears the authored 82-pixel final seam step into Temple");
            await StableSector(tree, monitor, PrologueSectorId.LostTemple, "05-temple",
                captureFrames, captureOutput);

            PrologueSector temple = Mounted(world, PrologueSectorId.LostTemple);
            BellChainMechanism chain = temple.GetNode<BellChainMechanism>(
                "Gameplay/Mechanisms/BellChain");
            GrappleSurface2D bellTarget = chain.GetNode<GrappleSurface2D>("ThreadTarget");
            await DriveHorizontalUntil(tree, monitor, moveRight: true,
                stop: () => player.GlobalPosition.X >= 4840f, maxFrames: 320, jumpPeriod: 45);
            await CastAt(tree, monitor, player, bellTarget, () => chain.IsOpen, 150);
            TestAssert.True(chain.IsOpen,
                "continuous generated-main route opens BellChain through the real E+mouse cast");
            GD.Print($"TASK8_GENERATED_MAIN_BELL_OK target={bellTarget.WorldAnchor} " +
                $"player={player.GlobalPosition} open={chain.IsOpen}");
            if (observer != null)
            {
                await DriveHorizontalUntil(tree, monitor, moveRight: true,
                    stop: () => level.Progress.RestoreCheckpoint() is
                    { HasActivatedCheckpoint: true, SectorId: PrologueSectorId.LostTemple },
                    maxFrames: 240, jumpPeriod: 0);
                await observer.AfterTempleCheckpoint(new Task9GeneratedMainContext(level, player,
                    world, count => PhysicsFrames(tree, monitor, count)));
            }
            await DriveHorizontalUntil(tree, monitor, moveRight: true,
                stop: () => temple.GetNode<BossArenaController>(
                    "Gameplay/BossArenaController").IsEncounterActive,
                maxFrames: 520, jumpPeriod: 62);
            BossArenaController boss = temple.GetNode<BossArenaController>(
                "Gameplay/BossArenaController");
            TestAssert.True(boss.IsEncounterActive,
                "continuous generated-main route reaches the real physical boss trigger");
            await Capture(tree, captureFrames, captureOutput, "06-boss-trigger");
            if (observer != null)
            {
                await observer.AfterBossTrigger(new Task9GeneratedMainContext(level, player,
                    world, count => PhysicsFrames(tree, monitor, count)));
                await DriveHorizontalUntil(tree, monitor, moveRight: true,
                    stop: () => boss.IsEncounterActive,
                    maxFrames: 360, jumpPeriod: 54);
                await DriveHorizontalUntil(tree, monitor, moveRight: true,
                    stop: () => player.GlobalPosition.X >= 5600f,
                    maxFrames: 180, jumpPeriod: 0);
                await observer.AfterBossRetry(new Task9GeneratedMainContext(level, player,
                    world, count => PhysicsFrames(tree, monitor, count)));
            }

            monitor.AssertComplete();
            if (observer == null)
                monitor.AssertNoProductionRecovery("continuous generated-main route");
            else
                monitor.AssertTask9Recoveries("Task 9 generated-main route", expected: 4);
            TestAssert.Equal(0, player.GetNode<PlayerMotor>("Motor").AcceptedDashCount,
                "generated-main route uses no Dash");
            GD.Print($"TASK8_GENERATED_MAIN_ROUTE_OK sectors={string.Join(",", monitor.Visited)} " +
                $"seams=4 max_step={monitor.MaxStep:0.00} player_id={playerId} " +
                $"mounted_max={monitor.MaxMounted} recovery_requested={monitor.RecoveryRequested} " +
                $"recovery_completed={monitor.RecoveryCompleted} boss_trigger=True capture={captureFrames}");
            return true;
        }
        finally
        {
            monitor.Dispose();
            ReleaseAll(player.GlobalPosition);
            await TestSceneTeardown.FreeSceneAfterAudioDrain(tree, level);
            await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
            await tree.ToSignal(tree, SceneTree.SignalName.ProcessFrame);
        }
    }

    private static async Task StableSector(SceneTree tree, RouteMonitor monitor,
        PrologueSectorId expected, string captureName, bool captureFrames, string captureOutput)
    {
        await PhysicsFrames(tree, monitor, 12);
        monitor.AssertCurrent(expected);
        monitor.AssertCameraCoverage();
        await Capture(tree, captureFrames, captureOutput, captureName);
        GD.Print($"TASK8_GENERATED_MAIN_SEAM_OK current={expected} frames={monitor.Frames} " +
            $"mounted={string.Join(",", monitor.World.MountedSectorIds)} " +
            $"max_step={monitor.MaxStep:0.00} recovery_requested={monitor.RecoveryRequested} " +
            $"recovery_completed={monitor.RecoveryCompleted}");
    }

    private static PrologueSector Mounted(SeamlessPrologueWorld world, PrologueSectorId id) =>
        world.GetChildren().OfType<PrologueSector>().Single(sector => sector.SectorId == id);

    private static async Task GrappleToLanding(SceneTree tree, RouteMonitor monitor,
        PrologueSector sector, string segmentId, int maxFrames)
    {
        TraversalSegment2D segment = sector.GetNode<TraversalSegment2D>(
            $"Gameplay/TraversalContracts/{segmentId}");
        Rect2 launch = new(segment.LaunchZone.Position + sector.GlobalPosition,
            segment.LaunchZone.Size);
        Rect2 landing = new(segment.LandingZone.Position + sector.GlobalPosition,
            segment.LandingZone.Size);
        GrappleSurface2D target = sector.GetNode<GrappleSurface2D>(segment.AssistTargetPath);
        MechanicalClawController claw = monitor.Player.GetNode<MechanicalClawController>(
            "MechanicalClaw");
        int casts = 0;
        int latches = 0;
        int occludedSamples = 0;
        int clippedSamples = 0;
        int localCueOnlySamples = 0;
        int gameplayVisibleButClippedSamples = 0;
        bool traceEnabled = Array.Exists(OS.GetCmdlineUserArgs(), value => value == "--trace-grapple");
        List<string> trace = traceEnabled ? new() : null;
        MechanicalClawState lastTraceState = MechanicalClawState.Idle;
        claw.ClawFrameChanged += Observe;
        try
        {
            if (monitor.Player.GlobalPosition.X < launch.GetCenter().X - 8f)
                await DriveHorizontalUntil(tree, monitor, moveRight: true,
                    stop: () => monitor.Player.GlobalPosition.X >= launch.GetCenter().X - 8f,
                    maxFrames: 160, jumpPeriod: 0);
            else if (monitor.Player.GlobalPosition.X > launch.GetCenter().X + 8f)
                await DriveHorizontalUntil(tree, monitor, moveRight: false,
                    stop: () => monitor.Player.GlobalPosition.X <= launch.GetCenter().X + 8f,
                    maxFrames: 160, jumpPeriod: 0);
            TestAssert.True(launch.HasPoint(monitor.Player.GlobalPosition),
                $"continuous route enters the authored {segmentId} launch zone by real movement; " +
                $"position={monitor.Player.GlobalPosition} launch={launch}");
            if (segmentId == "ascent_grapple_three" &&
                Array.Exists(OS.GetCmdlineUserArgs(), value => value == "--check-ascent-return"))
            {
                await CheckAscentReleaseReturn(tree, monitor, target);
                if (monitor.Player.GlobalPosition.X < launch.GetCenter().X - 8f)
                    await DriveHorizontalUntil(tree, monitor, moveRight: true,
                        stop: () => monitor.Player.GlobalPosition.X >= launch.GetCenter().X - 8f,
                        maxFrames: 160, jumpPeriod: 0);
                else if (monitor.Player.GlobalPosition.X > launch.GetCenter().X + 8f)
                    await DriveHorizontalUntil(tree, monitor, moveRight: false,
                        stop: () => monitor.Player.GlobalPosition.X <= launch.GetCenter().X + 8f,
                        maxFrames: 160, jumpPeriod: 0);
                TestAssert.True(launch.HasPoint(monitor.Player.GlobalPosition) &&
                    monitor.Player.IsOnFloor(),
                    $"return probe realigns to the supported {segmentId} launch by real A/D input; " +
                    $"position={monitor.Player.GlobalPosition} launch={launch}");
                casts = 0;
                latches = 0;
            }
            if (sector.SectorId == PrologueSectorId.CanyonAscent)
            {
                TestAssert.True(monitor.Player.IsOnFloor(),
                    $"{segmentId}: anchor preview is checked at a supported standing launch");
                Vector2 preview = ToViewport(monitor.Player, target.WorldAnchor);
                TestAssert.True(monitor.Player.GetViewport().GetVisibleRect().Grow(-64f).HasPoint(preview),
                    $"{segmentId}: standing launch must show the next anchor with 64px center margin " +
                    $"before a jump or mouse cast; viewport_anchor={preview} player={monitor.Player.GlobalPosition}");
                GD.Print($"ASCENT_STANDING_ANCHOR_VISIBLE segment={segmentId} viewport_anchor={preview}");
            }
            int jumpsBefore = monitor.Player.GetNode<PlayerMotor>("Motor").AcceptedJumpCount;
            Trace("before_jump");
            SendAction(InputActions.MoveRight, true);
            PulseJump(true);
            int visibilityWaitFrames = await WaitForVisibleTargetDuringJump(tree, monitor,
                target, segmentId, jumpsBefore);
            MoveMouse(monitor.Player, target.WorldAnchor);
            SendAction(InputActions.SelectGrappleMode, true);
            await PhysicsFrames(tree, monitor, 2);
            SendAction(InputActions.SelectGrappleMode, false);
            PlayerInputReader sampled = monitor.Player.GetNode<PlayerInputReader>("Input");
            TestAssert.True(IsTargetVisible(monitor.Player, target.WorldAnchor),
                $"{segmentId}: grapple target remains on-screen at the real LMB press; " +
                $"viewport_target={ToViewport(monitor.Player, target.WorldAnchor)}");
            GD.Print($"TASK8_GENERATED_MAIN_GRAPPLE_INPUT segment={segmentId} " +
                $"player={monitor.Player.GlobalPosition} target={target.WorldAnchor} " +
                $"distance={monitor.Player.GlobalPosition.DistanceTo(target.WorldAnchor):0.0} " +
                $"mouse={sampled.Current.MouseWorld} viewport_target={ToViewport(monitor.Player, target.WorldAnchor)} " +
                $"canvas={monitor.Player.GetViewport().GetCanvasTransform()} " +
                $"final={monitor.Player.GetViewport().GetFinalTransform()} " +
                $"visible=True visibility_wait_frames={visibilityWaitFrames} mode=" +
                $"{monitor.Player.GetNode<PlayerActionModeController>("ActionModes").CurrentMode}");
            SendMouse(MouseButton.Left, true, monitor.Player, target.WorldAnchor);
            await PhysicsFrames(tree, monitor, 1);
            ReleasePrimaryAtCurrentCursor(monitor.Player);
            Trace("primary_dispatched");
            int stable = 0;
            bool released = false;
            for (int frame = 0; frame < maxFrames; frame++)
            {
                if (frame == 8) PulseJump(false);
                // Once the claw is locked, the pointer may leave the screen; the saved
                // target remains authoritative after the one-frame click has ended.
                if (IsTargetVisible(monitor.Player, target.WorldAnchor))
                    MoveMouse(monitor.Player, target.WorldAnchor);
                await PhysicsFrames(tree, monitor, 1);
                if (traceEnabled) Trace($"loop_{frame}");
                MechanicalClawFrame attachedFrame = claw.CurrentFrame;
                var attachedLine = monitor.Player.GetNode<Knight.Vfx.ThreadLineVisual>("VisualRoot/MechanicalClaw/Line");
                if (attachedFrame.State is MechanicalClawState.Latched or MechanicalClawState.Reel or
                    MechanicalClawState.Swing or MechanicalClawState.Boost &&
                    (!attachedFrame.EffectiveVisibility || attachedLine.IsConnectionObscured))
                {
                    occludedSamples++;
                    if (attachedFrame.EffectiveVisibility) gameplayVisibleButClippedSamples++;
                    var shuttle = monitor.Player.GetNode<Knight.Vfx.ThreadShuttleVisual>("VisualRoot/MechanicalClaw");
                    TestAssert.True(shuttle.ObscuredConnectionVisible && shuttle.LatchVisible,
                        "every obscured real attachment retains local connection and locked-target feedback");
                    if (attachedLine.ActiveStrandCount > 0)
                    {
                        clippedSamples++;
                        TestAssert.True(attachedLine.CurrentState == Knight.Vfx.ThreadLineState.Occluded &&
                            attachedLine.LastWorldStart.DistanceTo(attachedLine.LastWorldEnd) <
                            attachedFrame.CasterWorldPosition.DistanceTo(attachedFrame.AnchorPoint),
                            "the obscured connection shows a partial rope, never the full through-wall rope");
                    }
                    else localCueOnlySamples++;
                    if (occludedSamples == 1)
                    {
                        var query = PhysicsRayQueryParameters2D.Create(
                            attachedFrame.CasterWorldPosition, attachedFrame.AnchorPoint,
                            Knight.Combat.CombatCollisionLayers.World | Knight.Combat.CombatCollisionLayers.Enemy |
                            Knight.Combat.CombatCollisionLayers.ThreadTarget);
                        query.CollideWithAreas = true;
                        query.Exclude = new Godot.Collections.Array<Rid> { monitor.Player.GetRid() };
                        foreach (Node child in monitor.Player.FindChildren("*", "", true, false))
                            if (child is CollisionObject2D collision) query.Exclude.Add(collision.GetRid());
                        Godot.Collections.Dictionary hit = monitor.Player.GetWorld2D().DirectSpaceState.IntersectRay(query);
                        string blocker = hit.Count > 0 ? (hit["collider"].AsGodotObject() as Node)?.GetPath().ToString() : "none";
                        GD.Print($"CLAW_OCCLUSION_FIRST segment={segmentId} origin={attachedFrame.CasterWorldPosition} " +
                            $"blocker={blocker} hit={(hit.Count > 0 ? hit["position"].AsVector2() : Vector2.Zero)}");
                        TestAssert.True(attachedLine.ActiveStrandCount > 0,
                            "an attached claw must retain a visible near-side rope when the first ascent obstruction appears");
                    }
                }
                if (monitor.Player.GlobalPosition.X >= landing.GetCenter().X)
                    SendAction(InputActions.MoveRight, false);
                if (!released && latches > 0 &&
                    monitor.Player.GlobalPosition.Y <= landing.GetCenter().Y &&
                    PredictLandingX(monitor.Player, landing.GetCenter().Y) is float predicted &&
                    predicted >= landing.Position.X && predicted <= landing.End.X)
                {
                    Trace("release_decision");
                    SendMouse(MouseButton.Left, true, monitor.Player,
                        monitor.Player.GetNode<PlayerInputReader>("Input").Current.MouseWorld);
                    await PhysicsFrames(tree, monitor, 1);
                    ReleasePrimaryAtCurrentCursor(monitor.Player);
                    released = true;
                }
                stable = monitor.Player.IsOnFloor() &&
                    HasLandingMargin(landing, monitor.Player.GlobalPosition)
                    ? stable + 1 : 0;
                if (stable >= StableLandingFrames) break;
            }
            TestAssert.True(stable >= StableLandingFrames && casts == 1 && latches == 1,
                $"continuous {segmentId} uses one real cast/latch and lands for twelve frames " +
                "with at least 15% horizontal/vertical margin; " +
                $"position={monitor.Player.GlobalPosition} casts={casts} latches={latches}");
            GD.Print($"TASK8_GENERATED_MAIN_GRAPPLE_OK segment={segmentId} casts={casts} " +
                $"latches={latches} landing={monitor.Player.GlobalPosition} occluded_samples={occludedSamples} " +
                $"clipped_samples={clippedSamples} local_cue_only={localCueOnlySamples} " +
                $"gameplay_visible_but_obscured={gameplayVisibleButClippedSamples}");
        }
        finally
        {
            claw.ClawFrameChanged -= Observe;
            if (trace != null)
                foreach (string sample in trace) GD.Print(sample);
            PulseJump(false);
            SendAction(InputActions.MoveRight, false);
            ReleasePrimaryAtCurrentCursor(monitor.Player);
        }

        void Observe(MechanicalClawFrame frame, GrappleSurface2D observed)
        {
            if (traceEnabled && frame.State != lastTraceState)
            {
                Trace($"publish_{frame.State}");
                lastTraceState = frame.State;
            }
            if (frame.State == MechanicalClawState.Windup && frame.CastId != 0) casts++;
            if (frame.State == MechanicalClawState.Latched && frame.CastId != 0) latches++;
        }

        void Trace(string moment)
        {
            if (!traceEnabled) return;
            CharacterBody2D body = monitor.Player;
            PlayerInputReader reader = body.GetNode<PlayerInputReader>("Input");
            PlayerInputFrame input = reader.Current;
            MechanicalClawFrame state = claw.CurrentFrame;
            var line = body.GetNode<Knight.Vfx.ThreadLineVisual>("VisualRoot/MechanicalClaw/Line");
            var shuttle = body.GetNode<Knight.Vfx.ThreadShuttleVisual>("VisualRoot/MechanicalClaw");
            var contacts = new List<string>();
            for (int contact = 0; contact < body.GetSlideCollisionCount(); contact++)
                contacts.Add((body.GetSlideCollision(contact).GetCollider() as Node)?.Name.ToString() ?? "unknown");
            trace.Add($"GRAPPLE_TRACE segment={segmentId} moment={moment} physics={Engine.GetPhysicsFrames()} " +
                $"sample={reader.CurrentFrameSequence} pos={body.GlobalPosition} vel={body.Velocity} " +
                $"floor={body.IsOnFloor()} jumps={body.GetNode<PlayerMotor>("Motor").AcceptedJumpCount} " +
                $"move={input.MoveAxis} aim={input.Aim} jump={input.JumpPressed}/{input.JumpHeld} " +
                $"primary={input.PrimaryPressed}/{input.PrimaryHeld}/{input.PrimaryReleased} shield={input.ShieldHeld} " +
                $"state={state.State} failure={state.Failure} cast={state.CastId} " +
                $"effective_visible={state.EffectiveVisibility} line_state={line.CurrentState} " +
                $"strands={line.ActiveStrandCount} line_end={line.LastWorldEnd} " +
                $"caster_origin={state.CasterWorldPosition} obscured_cue={shuttle.ObscuredConnectionVisible} " +
                $"target={claw.CurrentTarget?.Name.ToString() ?? "none"} rope={state.RopeLength:0.00} " +
                $"correction={state.VelocityCorrection} predicted_x={PredictLandingX(body, landing.GetCenter().Y):0.00} " +
                $"contacts={string.Join(",", contacts)}");
        }
    }

    private static async Task CheckAscentReleaseReturn(SceneTree tree,
        RouteMonitor monitor, GrappleSurface2D target)
    {
        CharacterBody2D player = monitor.Player;
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        MechanicalClawController claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
        Node landingTwo = Mounted(monitor.World, PrologueSectorId.CanyonAscent)
            .GetNode("Gameplay/Collision/LandingTwo");
        CollisionShape2D landingShape = landingTwo.GetNode<CollisionShape2D>("Collision");
        RectangleShape2D landingRectangle = (RectangleShape2D)landingShape.Shape;
        Control loadout = player.GetNode<Control>("../../Hud/FormalHud/Loadout");
        PrologueGuidanceController guidance = player.GetNode<PrologueGuidanceController>("../../Guidance");
        WorldTargetMarkerVisual guidanceVisual = player.GetNode<WorldTargetMarkerVisual>(
            "../../Hud/Guidance/VisualRoot");
        int jumps = motor.AcceptedJumpCount;
        int dash = motor.AcceptedDashCount;
        int recoveriesRequested = monitor.RecoveryRequested;
        int recoveriesCompleted = monitor.RecoveryCompleted;
        int casts = 0;
        int latches = 0;
        int releases = 0;
        ulong castId = 0;
        bool wrongCastOrTarget = false;
        bool releaseRequested = false;
        bool boostSeen = false;
        bool detachedGuidanceChecked = false;
        int outsideSafeMargin = 0;
        int descendingSamples = 0;
        int loadoutOverlapSamples = 0;
        float maxLoadoutOverlapArea = 0f;
        int stable = 0;
        claw.ClawFrameChanged += Observe;
        try
        {
            await PhysicsFrames(tree, monitor, 12);
            TestAssert.True(IsSupportedOnLandingTwo(), "return probe starts supported on LandingTwo");
            guidance.RefreshNow();
            string beforeAttachmentText = guidance.CurrentInstruction.StepText;
            TestAssert.True(!beforeAttachmentText.Contains("W/S", StringComparison.Ordinal),
                "standing temple approach keeps route guidance before attaching");
            float supportedY = player.GlobalPosition.Y;
            MoveMouse(player, target.WorldAnchor);
            SendAction(InputActions.SelectGrappleMode, true);
            await PhysicsFrames(tree, monitor, 2);
            SendAction(InputActions.SelectGrappleMode, false);
            SendMouse(MouseButton.Left, true, player, target.WorldAnchor);
            await PhysicsFrames(tree, monitor, 1);
            ReleasePrimaryAtCurrentCursor(player);
            for (int frame = 0; frame < 60 && !IsAttachedToTarget(); frame++)
                await PhysicsFrames(tree, monitor, 1);
            TestAssert.True(IsAttachedToTarget() && latches == 1,
                "standing left click reaches a real attached state on the third anchor");
            AssertAttachedTeaching("latched");
            for (int frame = 0; frame < 180 && player.GlobalPosition.Y > supportedY - 180f; frame++)
            {
                await PhysicsFrames(tree, monitor, 1);
            }
            TestAssert.True(!player.IsOnFloor() && player.GlobalPosition.Y <= supportedY - 180f,
                $"automatic pull lifts the real player without vertical input, Jump, or Boost; player={player.GlobalPosition}");
            AssertAttachedTeaching("auto-pull");
            GD.Print($"ASCENT_RETURN_RELEASE physics={Engine.GetPhysicsFrames()} " +
                $"player={player.GlobalPosition} velocity={player.Velocity} support_y={supportedY}");
            releaseRequested = true;
            SendMouse(MouseButton.Left, true, player, target.WorldAnchor);
            await PhysicsFrames(tree, monitor, 1);
            ReleasePrimaryAtCurrentCursor(player);
            for (int frame = 0; frame < 240; frame++)
            {
                await PhysicsFrames(tree, monitor, 1);
                if (!detachedGuidanceChecked && claw.CurrentFrame.State is
                    MechanicalClawState.Released or MechanicalClawState.Retract)
                {
                    TestAssert.True(claw.CurrentTarget == target,
                        "release guidance probe observes the still-retained target before cleanup");
                    guidance.RefreshNow();
                    TestAssert.Equal(beforeAttachmentText, guidance.CurrentInstruction.StepText,
                        "actual detach restores route guidance even while the claw retains its target");
                    TestAssert.True(guidanceVisual.HasVisiblePrompt && guidanceVisual.RenderedTextContained &&
                        guidanceVisual.GetNode<Label>("Text").Text.Contains(beforeAttachmentText,
                            StringComparison.Ordinal), "detached route guidance reaches the mounted label");
                    detachedGuidanceChecked = true;
                    GD.Print($"ASCENT_RETURN_GUIDANCE_DETACHED state={claw.CurrentFrame.State} " +
                        "target_retained=True route_restored=True");
                }
                // LandingTwo is the authored platform directly beneath this neutral return.
                // Its active top is local y=1012 (world y=1732), spanning world x=3530..3890.
                Vector2 supportScreen = ToViewport(player, new Vector2(player.GlobalPosition.X, 1732f));
                bool descending = !player.IsOnFloor() && player.Velocity.Y > 0f;
                if (descending && supportedY - player.GlobalPosition.Y >= 100f)
                {
                    descendingSamples++;
                    if (!player.GetViewport().GetVisibleRect().Grow(-48f).HasPoint(supportScreen))
                        outsideSafeMargin++;
                    // Use the mounted collision bounds and visible runtime HUD, not the layout
                    // calculator or a guessed world height, to catch a clear but HUD-covered ledge.
                    // HUD global rectangles use logical canvas coordinates, before the window's
                    // final stretch transform; project the world bounds into that same space.
                    Transform2D worldToHud = player.GetViewport().GetCanvasTransform();
                    Vector2 landingTopLeft = worldToHud *
                        landingShape.ToGlobal(-landingRectangle.Size * .5f);
                    Vector2 landingBottomRight = worldToHud *
                        landingShape.ToGlobal(landingRectangle.Size * .5f);
                    Rect2 landingScreenRect = new(landingTopLeft, landingBottomRight - landingTopLeft);
                    TestAssert.True(loadout.IsVisibleInTree(), "return probe keeps the loadout visible");
                    Rect2 overlap = landingScreenRect.Intersection(loadout.GetGlobalRect());
                    float overlapArea = overlap.Size.X * overlap.Size.Y;
                    if (overlapArea > 0f) loadoutOverlapSamples++;
                    maxLoadoutOverlapArea = Mathf.Max(maxLoadoutOverlapArea, overlapArea);
                }
                if (frame % 6 == 0)
                    GD.Print($"ASCENT_RETURN_SAMPLE frame={frame} player={player.GlobalPosition} " +
                        $"velocity={player.Velocity} floor={player.IsOnFloor()} support_screen={supportScreen}");
                stable = IsSupportedOnLandingTwo() && player.GlobalPosition.X > 3584f &&
                    player.GlobalPosition.X < 3836f && Math.Abs(player.GlobalPosition.Y - supportedY) < 1f
                    ? stable + 1 : 0;
                if (stable >= StableLandingFrames) break;
            }
            TestAssert.True(stable >= StableLandingFrames, "neutral claw release returns to supported LandingTwo");
            TestAssert.True(detachedGuidanceChecked,
                "route guidance is checked before the released target reference is cleared");
            guidance.RefreshNow();
            TestAssert.Equal(beforeAttachmentText, guidance.CurrentInstruction.StepText,
                "releasing and landing restores the route instruction, not stale attached controls");
            GD.Print("ASCENT_RETURN_GUIDANCE_RESTORED actual_release=True stable_landing=True");
            TestAssert.True(casts == 1 && latches == 1 && releases == 1 && !wrongCastOrTarget,
                $"return probe observes one matching Windup/Latched/Released cast; " +
                $"casts={casts} latches={latches} releases={releases} invalid={wrongCastOrTarget}");
            TestAssert.Equal(jumps, motor.AcceptedJumpCount, "return probe adds no ordinary jump");
            TestAssert.Equal(dash, motor.AcceptedDashCount, "return probe adds no dash");
            TestAssert.Equal(recoveriesRequested, monitor.RecoveryRequested,
                "return probe requests no recovery");
            TestAssert.Equal(recoveriesCompleted, monitor.RecoveryCompleted,
                "return probe completes no recovery");
            TestAssert.True(!boostSeen, "return probe publishes neither Boost nor BoostConsumed");
            GD.Print($"ASCENT_RETURN_VISIBILITY descending_samples={descendingSamples} " +
                $"outside_safe_margin={outsideSafeMargin} stable={stable}");
            TestAssert.True(descendingSamples > 0 && outsideSafeMargin == 0,
                "the return platform stays inside the 48px screen safe margin during early descent " +
                $"after 180px of auto-pull; outside_safe_margin={outsideSafeMargin} samples={descendingSamples}");
            GD.Print($"ASCENT_RETURN_HUD descending_samples={descendingSamples} " +
                $"loadout_overlap_samples={loadoutOverlapSamples} max_overlap_area={maxLoadoutOverlapArea:0.00} " +
                $"loadout={loadout.GetGlobalRect()}");
            TestAssert.Equal(0, loadoutOverlapSamples,
                "the visible loadout does not cover the return platform during early descent at default UI scale");
        }
        finally
        {
            claw.ClawFrameChanged -= Observe;
            ReleasePrimaryAtCurrentCursor(player);
        }

        bool IsAttachedToTarget() => claw.CurrentTarget == target &&
            claw.CurrentFrame.State is MechanicalClawState.Latched or MechanicalClawState.Reel or
                MechanicalClawState.Swing;

        void AssertAttachedTeaching(string phase)
        {
            guidance.RefreshNow();
            string step = guidance.CurrentInstruction.StepText;
            TestAssert.True(step.Contains("A/D", StringComparison.Ordinal) &&
                step.Contains("SPACE", StringComparison.Ordinal) &&
                step.Contains("Q", StringComparison.Ordinal) &&
                step.Contains("RMB", StringComparison.Ordinal) &&
                !step.Contains("W/S", StringComparison.Ordinal) &&
                !step.Contains("松开 LMB", StringComparison.Ordinal),
                $"actual {phase} state teaches attached controls through the live guidance controller; text={step}");
            TestAssert.True(guidanceVisual.Visible && guidanceVisual.HasVisiblePrompt &&
                guidanceVisual.RenderedTextContained &&
                guidanceVisual.GetNode<Label>("Text").Text.Contains(step, StringComparison.Ordinal),
                $"actual {phase} teaching is visible and contained in the mounted label");
            GD.Print($"ASCENT_RETURN_GUIDANCE_ATTACHED phase={phase} state={claw.CurrentFrame.State} " +
                $"prompt={guidanceVisual.PromptRect} text={step}");
        }

        bool IsSupportedOnLandingTwo()
        {
            if (!player.IsOnFloor()) return false;
            for (int index = 0; index < player.GetSlideCollisionCount(); index++)
            {
                KinematicCollision2D collision = player.GetSlideCollision(index);
                if (collision.GetCollider() == landingTwo && collision.GetNormal().Y < -.7f)
                    return true;
            }
            return false;
        }

        void Observe(MechanicalClawFrame frame, GrappleSurface2D observed)
        {
            boostSeen |= frame.State == MechanicalClawState.Boost || frame.BoostConsumed;
            if (frame.State == MechanicalClawState.Windup)
            {
                casts++;
                castId = frame.CastId;
                wrongCastOrTarget |= castId == 0;
            }
            if (frame.State == MechanicalClawState.Latched)
            {
                latches++;
                wrongCastOrTarget |= frame.CastId == 0 || frame.CastId != castId || observed != target;
            }
            if (frame.State == MechanicalClawState.Released)
            {
                releases++;
                wrongCastOrTarget |= !releaseRequested || frame.CastId == 0 || frame.CastId != castId;
            }
        }
    }

    private static async Task<int> WaitForVisibleTargetDuringJump(SceneTree tree,
        RouteMonitor monitor, GrappleSurface2D target, string segmentId, int jumpsBefore)
    {
        CharacterBody2D player = monitor.Player;
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        // This is only the already-requested ordinary jump: no second Space edge, dash,
        // grapple boost, player-state write, or camera adjustment may reveal the target.
        int apexFrameBudget = Mathf.CeilToInt(motor.Tuning.JumpSpeed / motor.Tuning.Gravity *
            Engine.PhysicsTicksPerSecond) + 2;
        int waited = 0;
        while (!IsTargetVisible(player, target.WorldAnchor) && waited < apexFrameBudget)
        {
            bool jumpStarted = motor.AcceptedJumpCount > jumpsBefore;
            if (jumpStarted && (player.IsOnFloor() || player.Velocity.Y >= 0f)) break;
            await PhysicsFrames(tree, monitor, 1);
            waited++;
        }
        TestAssert.True(IsTargetVisible(player, target.WorldAnchor),
            $"{segmentId}: target is not human-aimable before the ordinary jump apex; " +
            $"player={player.GlobalPosition} velocity={player.Velocity} target={target.WorldAnchor} " +
            $"viewport_target={ToViewport(player, target.WorldAnchor)} " +
            $"visible_rect={player.GetViewport().GetVisibleRect()} waited_frames={waited} " +
            $"apex_budget={apexFrameBudget} accepted_jumps={motor.AcceptedJumpCount - jumpsBefore}; " +
            "no off-screen mouse event was sent");
        return waited;
    }

    private static bool IsTargetVisible(CharacterBody2D player, Vector2 worldPosition) =>
        player.GetViewport().GetVisibleRect().Grow(-32f)
            .HasPoint(ToViewport(player, worldPosition));

    private static void ReleasePrimaryAtCurrentCursor(CharacterBody2D player)
    {
        Vector2 viewport = player.GetNode<PlayerInputReader>("Input")
            .LastObservedMouseViewportPosition;
        Input.ParseInputEvent(new InputEventMouseButton
        {
            ButtonIndex = MouseButton.Left,
            Pressed = false,
            Position = viewport,
            GlobalPosition = viewport,
            ButtonMask = (MouseButtonMask)0
        });
        Input.FlushBufferedEvents();
    }

    private static bool HasLandingMargin(Rect2 zone, Vector2 point)
    {
        Vector2 inset = zone.Size * LandingMarginRatio;
        return new Rect2(zone.Position + inset, zone.Size - inset * 2f).HasPoint(point);
    }

    private static bool Task10KeyboardClawPlanSelects(CharacterBody2D player, GrappleSurface2D target)
    {
        if (KeyboardRouteInputDriver.Current == null) return true;
        // Planner filter only: do not fire an opportunistic combat cast already
        // known to select terrain. CastAt still proves the actual K sample/target.
        Vector2 planned = PlayerKeyboardAimModel.ResolveDirection(target.WorldAnchor - player.GlobalPosition, 1);
        MechanicalClawTargetResolution selection = new MechanicalClawTargetResolver().ResolveKeyboard(player, planned);
        return selection.Surface == target && selection.Snapshot.HasLineOfSight;
    }

    private static async Task<bool> CastAt(SceneTree tree, RouteMonitor monitor,
        CharacterBody2D player, GrappleSurface2D target, Func<bool> completed, int maxFrames,
        bool requireSafeFrozenMoth = false, bool observeGearBellAdmission = false,
        Func<bool> gearBellAdmission = null)
    {
        ulong castPlayerId = player.GetInstanceId();
        int castRecoveryRequests = monitor.RecoveryRequested, castRecoveryCompletions = monitor.RecoveryCompleted;
        HealthComponent castPlayerHealth = player.GetNode<HealthComponent>("Health");
        int castStartingHealth = castPlayerHealth.CurrentHealth;
        MechanicalClawController gearClaw = gearBellAdmission != null
            ? player.GetNode<MechanicalClawController>("MechanicalClaw") : null;
        LegacyThreadInteractionAdapter gearAdapter = gearBellAdmission != null
            ? target.GetNode<LegacyThreadInteractionAdapter>("LegacyThreadInteractionAdapter") : null;
        int gearRawEdges = gearBellAdmission != null ? KeyboardRouteInputDriver.Current.ClawEdges : 0;
        int gearApplications = gearAdapter?.ApplicationCount ?? 0;
        ulong gearNextCast = gearClaw?.CurrentFrame.NextCastId ?? 0;
        void ObserveGearBellCast(string boundary)
        {
            if (!observeGearBellAdmission) return;
            var reader = player.GetNode<PlayerInputReader>("Input");
            var controller = player.GetNode<MechanicalClawController>("MechanicalClaw");
            Vector2 direction = PlayerKeyboardAimModel.ResolveDirection(target.WorldAnchor-player.GlobalPosition,1);
            var selection = new MechanicalClawTargetResolver().ResolveKeyboard(player,direction);
            var circle = (CircleShape2D)target.GetNode<CollisionShape2D>("TargetCollision/Collision").Shape;
            GD.Print($"TASK10_GEAR_BELL_CAST_BOUNDARY stage={boundary} physics={Engine.GetPhysicsFrames()} " +
                $"sample={reader.CurrentFrameSequence} player={player.GlobalPosition} velocity={player.Velocity} " +
                $"target={target.GetInstanceId()} target_world={target.WorldAnchor} " +
                $"distance={player.GlobalPosition.DistanceTo(target.WorldAnchor):R} circle_radius={circle.Radius:R} " +
                $"planned={direction} sampled_aim={reader.KeyboardAimDirection} axis={reader.Current.MoveAxis} " +
                $"selected={selection.Surface?.GetPath()} selected_anchor={selection.Snapshot.WorldAnchor} " +
                $"actual_target={controller.CurrentTarget?.GetPath()} claw={controller.CurrentFrame.State} " +
                $"hp={castPlayerHealth.CurrentHealth} floor={DescribeFloorCollider(player)} " +
                "diagnostic_only=true no_control_change=true");
        }
        void GuardCastLifetime() => TestAssert.True(
            GodotObject.IsInstanceValid(player) && player.GetInstanceId() == castPlayerId &&
            monitor.Player.GetInstanceId() == castPlayerId && castPlayerHealth.CurrentHealth > 0 &&
            monitor.RecoveryRequested == castRecoveryRequests && monitor.RecoveryCompleted == castRecoveryCompletions &&
            (!(requireSafeFrozenMoth || gearBellAdmission != null) || castPlayerHealth.CurrentHealth == castStartingHealth),
            "CastAt cannot accept target retirement or continue its route after player death/recovery");
        async Task CastFrames(int count)
        {
            for (int index = 0; index < count; index++)
            {
                GuardCastLifetime();
                await PhysicsFrames(tree, monitor, 1);
                GuardCastLifetime();
            }
        }
        GuardCastLifetime();
        ObserveGearBellCast("caller_before_prefix");
        MoveMouse(player, target.WorldAnchor);
        SendAction(InputActions.SelectGrappleMode, true);
        await CastFrames(2);
        if (requireSafeFrozenMoth)
        {
            var jumpInput = player.GetNode<PlayerInputReader>("Input").CurrentFrame;
            TestAssert.True(!jumpInput.JumpPressed && !jumpInput.JumpHeld && !Input.IsPhysicalKeyPressed(Key.Space),
                "frozen safe Moth cast observes neutral Space in original mode prefix before K");
        }
        SendAction(InputActions.SelectGrappleMode, false);
        ObserveGearBellCast("prefix_complete_before_K");
        if (gearBellAdmission != null)
        {
            GuardCastLifetime();
            TestAssert.True(GodotObject.IsInstanceValid(target) && target.IsInsideTree() &&
                target.IsAvailable && !completed() && gearClaw.CurrentFrame.State == MechanicalClawState.Idle &&
                gearClaw.CurrentFrame.Failure == MechanicalClawFailure.None,
                "Gear Bell prefix retains its live unexposed target and real Idle without a claw failure");
            if (!gearBellAdmission() || !Task10KeyboardClawPlanSelects(player, target))
            {
                TestAssert.True(KeyboardRouteInputDriver.Current.ClawEdges == gearRawEdges &&
                    gearClaw.CurrentFrame.NextCastId == gearNextCast && gearAdapter.ApplicationCount == gearApplications &&
                    !Input.IsPhysicalKeyPressed(Key.K),
                    "Gear Bell prefix rejection issues no K/cast/application and cannot count as a thread success");
                GD.Print($"TASK10_GEAR_BELL_PREFIX_NO_K player={player.GetInstanceId()} " +
                    $"target={target.GetInstanceId()} sample={player.GetNode<PlayerInputReader>("Input").CurrentFrameSequence} " +
                    $"raw_edges={gearRawEdges}->{KeyboardRouteInputDriver.Current.ClawEdges} " +
                    $"next_cast={gearNextCast}->{gearClaw.CurrentFrame.NextCastId} " +
                    $"applications={gearApplications}->{gearAdapter.ApplicationCount} original_prefix=2 " +
                    "issued=false no_wait45=true");
                return false;
            }
        }
        if (KeyboardRouteInputDriver.Current is { } keyboard)
        {
            PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
            MechanicalClawController claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
            ulong issue = input.CurrentFrameSequence, sampled = 0, last = issue;
            ulong initialNextCast = claw.CurrentFrame.NextCastId;
            int edges = 0, rawEdges = keyboard.ClawEdges;
            Vector2 planned = PlayerKeyboardAimModel.ResolveDirection(target.WorldAnchor - player.GlobalPosition, 1);
            TestAssert.True(claw.CurrentFrame.State == MechanicalClawState.Idle,
                "keyboard CastAt begins from real Idle, not a K cancellation");
            TestAssert.True(!completed(), "keyboard CastAt cannot reuse an already-completed target predicate");
            try
            {
                SendMouse(MouseButton.Left, true, player, target.WorldAnchor);
                for (int frame = 0; frame < 8; frame++)
                {
                    await CastFrames(1);
                    if (input.CurrentFrameSequence > last)
                    {
                        last = input.CurrentFrameSequence;
                        if (input.CurrentFrame.ClawPressed) { sampled = last; edges++; }
                    }
                    if (sampled > issue && (claw.CurrentFrame.State != MechanicalClawState.Idle || completed())) break;
                }
                ObserveGearBellCast("sampled_K_before_admission_assert");
                TestAssert.True(sampled > issue && edges == 1 && keyboard.ClawEdges == rawEdges + 1 &&
                    input.CurrentFrame.KeyboardActions && input.KeyboardAimDirection.Dot(planned) > .999f &&
                    !input.CurrentFrame.PrimaryPressed && !input.CurrentFrame.AttackPressed && !input.CurrentFrame.InteractPressed &&
                    claw.CurrentFrame.Failure == MechanicalClawFailure.None &&
                    (claw.CurrentTarget == target || completed()),
                    $"keyboard CastAt retains one real K/octant through production target admission: {target.GetPath()} " +
                    $"issue={issue} sampled={sampled} current={input.CurrentFrameSequence} edges={edges}/{keyboard.ClawEdges - rawEdges} " +
                    $"planned={planned} actual={input.KeyboardAimDirection} axis={input.CurrentFrame.Aim} " +
                    $"player={player.GlobalPosition} target_anchor={target.WorldAnchor} " +
                    $"state={claw.CurrentFrame.State}/{claw.CurrentFrame.Failure} current_target={claw.CurrentTarget?.GetPath()} " +
                    $"selected_anchor={claw.CurrentFrame.AnchorPoint} completed={completed()}");
                TestAssert.True(claw.CurrentFrame.State == MechanicalClawState.Aim
                    ? claw.CurrentFrame.CastId == 0 && claw.CurrentFrame.NextCastId == initialNextCast
                    : claw.CurrentFrame.NextCastId == initialNextCast + 1 &&
                        (claw.CurrentFrame.CastId == initialNextCast || completed()),
                    "keyboard CastAt admits exactly the next new cast, not stale completion or cancellation");
            }
            finally { SendMouse(MouseButton.Left, false, player, target.WorldAnchor); }
        }
        else
        {
            SendMouse(MouseButton.Left, true, player, target.WorldAnchor);
            await CastFrames(1);
            SendMouse(MouseButton.Left, false, player, target.WorldAnchor);
        }
        for (int frame = 0; frame < maxFrames && !completed(); frame++)
        {
            MoveMouse(player, target.WorldAnchor);
            await CastFrames(1);
        }
        await CastFrames(3);
        return true;
    }

    private static void TraceFinalSeam(RouteMonitor monitor, string moment)
    {
        if (!Array.Exists(OS.GetCmdlineUserArgs(), value => value == "--trace-grapple")) return;
        CharacterBody2D body = monitor.Player;
        PlayerInputFrame input = body.GetNode<PlayerInputReader>("Input").Current;
        var contacts = new List<string>();
        for (int contact = 0; contact < body.GetSlideCollisionCount(); contact++)
            contacts.Add((body.GetSlideCollision(contact).GetCollider() as Node)?.Name.ToString() ?? "unknown");
        GD.Print($"FINAL_SEAM_TRACE moment={moment} sector={monitor.World.CurrentSector} " +
            $"pos={body.GlobalPosition} vel={body.Velocity} floor={body.IsOnFloor()} " +
            $"input_move={input.MoveAxis} jump={input.JumpPressed}/{input.JumpHeld} " +
            $"jumps={body.GetNode<PlayerMotor>("Motor").AcceptedJumpCount} " +
            $"processing={body.IsPhysicsProcessing()} focus={body.GetWindow().HasFocus()} " +
            $"contacts={string.Join(",", contacts)}");
    }

    private static async Task DriveHorizontalUntil(SceneTree tree, RouteMonitor monitor,
        bool moveRight, Func<bool> stop, int maxFrames, int jumpPeriod,
        Func<Vector2> mouseAim = null)
    {
        StringName direction = moveRight ? InputActions.MoveRight : InputActions.MoveLeft;
        List<string> samples = Array.Exists(OS.GetCmdlineUserArgs(), value => value == "--trace-grapple")
            ? new() : null;
        SendAction(direction, true);
        try
        {
            for (int frame = 0; frame < maxFrames && !stop(); frame++)
            {
                if (mouseAim != null) MoveMouse(monitor.Player, mouseAim());
                if (jumpPeriod > 0 && frame % jumpPeriod == 0 && monitor.Player.IsOnFloor())
                    PulseJump(true);
                if (jumpPeriod > 0 && frame % jumpPeriod == 8) PulseJump(false);
                await PhysicsFrames(tree, monitor, 1);
                if (samples != null && frame % 8 == 0)
                {
                    CharacterBody2D body = monitor.Player;
                    PlayerInputFrame input = body.GetNode<PlayerInputReader>("Input").Current;
                    var contacts = new List<string>();
                    for (int contact = 0; contact < body.GetSlideCollisionCount(); contact++)
                        contacts.Add((body.GetSlideCollision(contact).GetCollider() as Node)?.Name.ToString() ?? "unknown");
                    samples.Add($"HORIZONTAL_TRACE frame={frame} sector={monitor.World.CurrentSector} " +
                        $"pos={body.GlobalPosition} vel={body.Velocity} floor={body.IsOnFloor()} " +
                        $"input_move={input.MoveAxis} jump={input.JumpPressed}/{input.JumpHeld} " +
                        $"jumps={body.GetNode<PlayerMotor>("Motor").AcceptedJumpCount} " +
                        $"focus={body.GetWindow().HasFocus()} contacts={string.Join(",", contacts)}");
                }
            }
        }
        finally
        {
            PulseJump(false);
            SendAction(direction, false);
            if (samples != null)
                foreach (string sample in samples) GD.Print(sample);
        }
        TestAssert.True(stop(),
            $"continuous input route reaches its next physical condition; " +
            $"position={monitor.Player.GlobalPosition} current={monitor.World.CurrentSector}");
    }

    private static async Task WaitForFloor(SceneTree tree, RouteMonitor monitor, int maxFrames)
    {
        for (int frame = 0; frame < maxFrames && !monitor.Player.IsOnFloor(); frame++)
            await PhysicsFrames(tree, monitor, 1);
        TestAssert.True(monitor.Player.IsOnFloor(),
            $"persistent player reaches production floor support; position={monitor.Player.GlobalPosition}");
    }

    private static float PredictLandingX(CharacterBody2D player, float landingY)
    {
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        Vector2 position = player.GlobalPosition;
        Vector2 velocity = player.Velocity;
        const float seconds = 1f / 60f;
        for (int frame = 0; frame < 300; frame++)
        {
            velocity.X = Mathf.MoveToward(velocity.X, motor.Tuning.MaxRunSpeed,
                motor.Tuning.AirAcceleration * seconds);
            velocity.Y = Mathf.Min(velocity.Y + motor.Tuning.Gravity * seconds,
                motor.Tuning.MaxFallSpeed);
            position += velocity * seconds;
            if (velocity.Y >= 0f && position.Y >= landingY) return position.X;
        }
        return float.NaN;
    }

    private static async Task PhysicsFrames(SceneTree tree, RouteMonitor monitor, int count)
    {
        for (int index = 0; index < count; index++)
        {
            await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
            monitor.Observe();
        }
    }

    private static void PulseJump(bool pressed) => SendAction(InputActions.Jump, pressed);

    private static void SendAction(StringName action, bool pressed)
    {
        if(KeyboardRouteInputDriver.Current!=null)
        { KeyboardRouteInputDriver.Current.Command(action,pressed); return; }
        var input = new InputEventAction
        {
            Action = action,
            Pressed = pressed,
            Strength = pressed ? 1f : 0f
        };
        Input.ParseInputEvent(input);
        Input.FlushBufferedEvents();
    }

    private static void MoveMouse(CharacterBody2D player, Vector2 worldPosition,
        Task11PointerAdmissionTrace pointerTrace = null)
    {
        if(KeyboardRouteInputDriver.Current!=null)
        { KeyboardRouteInputDriver.Current.AimAt(player,worldPosition); return; }
        // Route one real MouseMotion event through both the spawned target viewport and
        // InputMap. PlayerInputReader observes that normal event in production, so this does
        // not depend on an OS cursor warp or synthesize a PlayerInputFrame.
        Vector2 internalViewport = player.GetViewport().GetFinalTransform() *
            (player.GetGlobalTransformWithCanvas() * player.ToLocal(worldPosition));
        var motion = new InputEventMouseMotion
        {
            Position = internalViewport,
            GlobalPosition = internalViewport
        };
        pointerTrace?.Driver("motion_created_before_PushInput", player, worldPosition, motion);
        player.GetViewport().PushInput(motion, true);
        pointerTrace?.Driver("motion_after_PushInput_before_ParseInputEvent", player, worldPosition, motion);
        Input.ParseInputEvent(motion);
        pointerTrace?.Driver("motion_after_ParseInputEvent_before_FlushBufferedEvents", player, worldPosition, motion);
        Input.FlushBufferedEvents();
        pointerTrace?.Driver("motion_after_FlushBufferedEvents", player, worldPosition, motion);
    }

    private static void SendMouse(MouseButton button, bool pressed, CharacterBody2D player,
        Vector2 worldPosition, Task11PointerAdmissionTrace pointerTrace = null)
    {
        if(KeyboardRouteInputDriver.Current!=null)
        { KeyboardRouteInputDriver.Current.PointerButton(button,pressed,player,worldPosition); return; }
        if (GodotObject.IsInstanceValid(player)) MoveMouse(player, worldPosition, pointerTrace);
        Vector2 viewport = GodotObject.IsInstanceValid(player)
            ? player.GetViewport().GetFinalTransform() *
              (player.GetGlobalTransformWithCanvas() * player.ToLocal(worldPosition))
            : Vector2.Zero;
        var mouseButton = new InputEventMouseButton
        {
            ButtonIndex = button,
            Pressed = pressed,
            Position = viewport,
            GlobalPosition = viewport,
            ButtonMask = pressed ? button == MouseButton.Left
                ? MouseButtonMask.Left
                : MouseButtonMask.Right
                : (MouseButtonMask)0
        };
        pointerTrace?.Driver("button_created_before_ParseInputEvent", player, worldPosition, mouseButton);
        Input.ParseInputEvent(mouseButton);
        pointerTrace?.Driver("button_after_ParseInputEvent_before_FlushBufferedEvents", player, worldPosition, mouseButton);
        Input.FlushBufferedEvents();
        pointerTrace?.Driver("button_after_FlushBufferedEvents", player, worldPosition, mouseButton);
    }

    // VisibleRect and its aimable insets are logical viewport coordinates. FinalTransform
    // maps those logical coordinates to window/output pixels for mouse events, not checks.
    private static Vector2 ToViewport(CharacterBody2D player, Vector2 worldPosition) =>
        player.GetViewport().GetCanvasTransform() * worldPosition;

    private static void ReleaseAll(Vector2 worldPosition)
    {
        if(KeyboardRouteInputDriver.Current!=null)
        { KeyboardRouteInputDriver.Current.ReleaseAll(); return; }
        foreach (StringName action in new[]
                 { InputActions.MoveLeft, InputActions.MoveRight, InputActions.MoveUp,
                     InputActions.MoveDown, InputActions.Jump, InputActions.Dash,
                     InputActions.SelectAttackMode, InputActions.SelectGrappleMode,
                     InputActions.PrimaryAction, InputActions.Shield })
            Input.ActionRelease(action);
        Input.ParseInputEvent(new InputEventMouseButton
            { ButtonIndex = MouseButton.Left, Pressed = false, Position = worldPosition });
        Input.ParseInputEvent(new InputEventMouseButton
            { ButtonIndex = MouseButton.Right, Pressed = false, Position = worldPosition });
    }

    private static string ResolveCaptureOutput(bool captureFrames)
    {
        if (!captureFrames) return null;
        string argument = Array.Find(OS.GetCmdlineUserArgs(), value => value.StartsWith("--output="));
        if (argument == null || !Path.IsPathFullyQualified(argument[9..]))
            throw new ArgumentException("--output=<external absolute directory> is required when captureFrames=true");
        string output = Path.GetFullPath(argument[9..]);
        string project = Path.GetFullPath(ProjectSettings.GlobalizePath("res://"));
        if ((output.TrimEnd('/', '\\') + Path.DirectorySeparatorChar).StartsWith(
            project.TrimEnd('/', '\\') + Path.DirectorySeparatorChar,
            StringComparison.OrdinalIgnoreCase))
            throw new ArgumentException("Generated-main capture output must be outside the project.");
        Directory.CreateDirectory(output);
        return output;
    }

    private static async Task Capture(SceneTree tree, bool enabled, string output, string name)
    {
        if (!enabled) return;
        await tree.ToSignal(RenderingServer.Singleton, RenderingServer.SignalName.FramePostDraw);
        Image image = tree.Root.GetTexture().GetImage();
        TestAssert.Equal(1280, image.GetWidth(), $"{name} proof frame width is 1280");
        TestAssert.Equal(720, image.GetHeight(), $"{name} proof frame height is 720");
        Error error = image.SavePng(Path.Combine(output, name + ".png"));
        TestAssert.Equal(Error.Ok, error, $"{name} proof frame saves successfully");
    }

    private sealed class RouteMonitor : IDisposable
    {
        private readonly PrologueLevelController _level;
        private readonly ulong _playerId;
        private Vector2 _previous;
        private int _highestRouteIndex;
        private int _lastRouteIndex;
        private readonly bool _allowRouteBacktracking;
        private Action _additionalObservation;
        private bool _recoveryRepositionPending;
        private bool _recoveryRequestPending;
        private readonly PlayerMotor _recoveryMotor;
        private readonly HealthComponent _recoveryHealth;
        private string _lastRecoveryReason = "none";
        private Vector2 _lastRecoveryPosition, _lastRecoveryVelocity;
        private int _lastRecoveryHp, _lastRecoveryDamage, _reportedRecoveries;
        private ulong _lastRecoveryLanding;
        private float _lastRecoveryHeight;

        public RouteMonitor(PrologueLevelController level, CharacterBody2D player, Camera2D camera,
            SeamlessPrologueWorld world, ulong playerId, bool allowRouteBacktracking = false,
            Action additionalObservation = null)
        {
            _level = level;
            Player = player;
            _recoveryMotor = player.GetNode<PlayerMotor>("Motor");
            _recoveryHealth = player.GetNode<HealthComponent>("Health");
            Camera = camera;
            World = world;
            _playerId = playerId;
            _allowRouteBacktracking = allowRouteBacktracking;
            _additionalObservation = additionalObservation;
            _previous = player.GlobalPosition;
            Visited.Add(world.CurrentSector);
            _lastRouteIndex = Array.IndexOf(OrderedRoute, world.CurrentSector);
            _level.RecoveryRequested += OnRecoveryRequested;
            _level.RecoveryCompleted += OnRecoveryCompleted;
        }

        public CharacterBody2D Player { get; }
        public Camera2D Camera { get; }
        public SeamlessPrologueWorld World { get; }
        public List<PrologueSectorId> Visited { get; } = new();
        public int Frames { get; private set; }
        public float MaxStep { get; private set; }
        public int MaxMounted { get; private set; }
        public int RecoveryRequested { get; private set; }
        public int RecoveryCompleted { get; private set; }

        public void Dispose()
        {
            _additionalObservation = null;
            if (!GodotObject.IsInstanceValid(_level)) return;
            _level.RecoveryRequested -= OnRecoveryRequested;
            _level.RecoveryCompleted -= OnRecoveryCompleted;
        }

        public void AssertNoProductionRecovery(string context)
        {
            TestAssert.Equal(0, RecoveryRequested,
                $"{context} emits zero measured production RecoveryRequested events");
            TestAssert.Equal(0, RecoveryCompleted,
                $"{context} emits zero measured production RecoveryCompleted events");
        }

        public void AssertTask9Recoveries(string context, int expected)
        {
            TestAssert.Equal(expected, RecoveryRequested,
                $"{context} emits the exact measured RecoveryRequested count");
            TestAssert.Equal(expected, RecoveryCompleted,
                $"{context} pairs every RecoveryRequested with RecoveryCompleted");
            TestAssert.True(!_recoveryRequestPending && !_recoveryRepositionPending,
                $"{context} closes every recovery and its single displacement exemption");
        }

        public void Observe()
        {
            Frames++;
            if (_reportedRecoveries != RecoveryRequested)
            {
                _reportedRecoveries = RecoveryRequested;
                GD.Print($"TASK10_RECOVERY_REQUEST_OBSERVATION count={RecoveryRequested} reason={_lastRecoveryReason} " +
                    $"player={_lastRecoveryPosition} velocity={_lastRecoveryVelocity} hp={_lastRecoveryHp} " +
                    $"landings={_lastRecoveryLanding} fall_height={_lastRecoveryHeight:R} fall_damage={_lastRecoveryDamage} " +
                    "captured=synchronous_pre_recovery_event output=next_driver_observation applied_flag_not_sampled=true");
            }
            KeyboardRouteInputDriver.Current?.ObserveFrame();
            TestAssert.Equal(_playerId, Player.GetInstanceId(),
                "one persistent production player survives every seam");
            TestAssert.True(Player.GetParent()?.Name == "PlayerRoot",
                "persistent player is never reparented into a streamed sector");
            float step = Player.GlobalPosition.DistanceTo(_previous);
            MaxStep = Mathf.Max(MaxStep, step);
            if (_recoveryRepositionPending)
            {
                PrologueCheckpointSnapshot checkpoint = _level.Progress.RestoreCheckpoint();
                TestAssert.True(Player.GlobalPosition.DistanceTo(checkpoint.WorldPosition) < 1.1f,
                    $"the only displacement exemption is a measured recovery to the explicit " +
                    $"checkpoint; expected={checkpoint.WorldPosition} actual={Player.GlobalPosition}");
                _recoveryRepositionPending = false;
            }
            else TestAssert.True(step <= 72f,
                $"no frame performs a position reset or teleport; step={step:0.00} " +
                $"from={_previous} to={Player.GlobalPosition}");
            _previous = Player.GlobalPosition;

            int routeIndex = Array.IndexOf(OrderedRoute, World.CurrentSector);
            bool validTransition = _allowRouteBacktracking
                ? Math.Abs(routeIndex - _lastRouteIndex) <= 1
                : routeIndex >= _highestRouteIndex && routeIndex <= _highestRouteIndex + 1;
            TestAssert.True(validTransition,
                $"streaming current route crosses only adjacent sector seams; " +
                $"previous={OrderedRoute[_lastRouteIndex]} current={World.CurrentSector}");
            _lastRouteIndex = routeIndex;
            if (routeIndex > _highestRouteIndex)
            {
                _highestRouteIndex = routeIndex;
                Visited.Add(World.CurrentSector);
            }
            TestAssert.True(World.MountedSectorIds.Contains(World.CurrentSector),
                $"current sector {World.CurrentSector} is mounted on every observed frame");
            MaxMounted = Math.Max(MaxMounted, World.MountedSectorIds.Count);
            if (_highestRouteIndex > 0)
                TestAssert.True(Player.GlobalPosition.DistanceTo(new Vector2(120f, 574f)) > 160f,
                    "route never respawns early at the round-start coordinate");
            _additionalObservation?.Invoke();
        }

        public void AssertCurrent(PrologueSectorId expected) =>
            TestAssert.Equal(expected, World.CurrentSector,
                $"streaming resolves expected continuous sector {expected}");

        public void AssertCameraCoverage()
        {
            Vector2 position = Player.GlobalPosition;
            const float tolerance = 96f;
            TestAssert.True(Camera.Enabled && position.X >= Camera.LimitLeft - tolerance &&
                position.X <= Camera.LimitRight + tolerance &&
                position.Y >= Camera.LimitTop - tolerance &&
                position.Y <= Camera.LimitBottom + tolerance,
                $"camera limits cover the persistent player after seam; player={position} " +
                $"limits=({Camera.LimitLeft},{Camera.LimitTop})-({Camera.LimitRight},{Camera.LimitBottom})");
        }

        public void AssertFullCapsuleVisible()
        {
            Transform2D canvas = Player.GetViewport().GetCanvasTransform();
            Vector2 topLeft = canvas * (Player.GlobalPosition - new Vector2(20,36));
            Vector2 bottomRight = canvas * (Player.GlobalPosition + new Vector2(20,36));
            Rect2 viewport = Player.GetViewport().GetVisibleRect();
            TestAssert.True(viewport.Encloses(new Rect2(topLeft,bottomRight-topLeft)),
                $"full real capsule stays visible during the main route; player={Player.GlobalPosition} " +
                $"capsule_screen={topLeft}..{bottomRight} viewport={viewport} camera={Camera.GetScreenCenterPosition()} frame={Frames}");
        }

        public void AssertComplete()
        {
            TestAssert.Equal(string.Join("|", OrderedRoute), string.Join("|", Visited),
                "generated-main proof crosses all four seams in exact route order");
            TestAssert.True(MaxMounted is >= 2 and <= 3,
                $"streaming keeps the current route and bounded neighbours mounted; max={MaxMounted}");
            AssertCameraCoverage();
        }

        private void OnRecoveryRequested(string reason)
        {
            TestAssert.True(!_recoveryRequestPending,
                "a Task 9 recovery request cannot overlap an unfinished recovery");
            _recoveryRequestPending = true;
            RecoveryRequested++;
            // Scalar capture only; formatting is deferred to the next driver
            // observation. DamageApplied may not yet have returned to Motor.
            _lastRecoveryReason = reason;
            _lastRecoveryPosition = Player.GlobalPosition;
            _lastRecoveryVelocity = Player.Velocity;
            _lastRecoveryHp = _recoveryHealth.CurrentHealth;
            _lastRecoveryLanding = _recoveryMotor.LandingCount;
            _lastRecoveryHeight = _recoveryMotor.LastFallHeight;
            _lastRecoveryDamage = _recoveryMotor.LastFallDamage;
        }

        private void OnRecoveryCompleted(string _)
        {
            TestAssert.True(_recoveryRequestPending,
                "RecoveryCompleted is paired with a preceding measured RecoveryRequested");
            _recoveryRequestPending = false;
            RecoveryCompleted++;
            _recoveryRepositionPending = true;
        }
    }

    // Test-only, read-only observation of the existing raise/walk window. In particular,
    // PhysicsFrame is a pre-node-physics boundary, not a claim that input was just sampled.
    private sealed class Task24ShieldLaneObservation
    {
        private const int MaximumRecords = 256;
        private const int PreLossRecords = 64;
        private readonly SceneTree _tree;
        private readonly PrologueLevelController _level;
        private readonly CharacterBody2D _player;
        private readonly PlayerShieldController _shield;
        private readonly HealthComponent _health;
        private readonly StaticBody2D _gearEntry;
        private readonly Func<int> _recoveryRequests;
        private readonly Func<int> _recoveryCompletions;
        private readonly List<string> _records = new(MaximumRecords);
        private PlayerInputReader _input;
        private PlayerEnergyController _energy;
        private PlayerMotor _motor;
        private bool _physicsAttached, _shieldAttached, _energyAttached;
        private bool _damageAttached, _deathAttached, _requestsAttached, _completionsAttached;
        private bool _sawActive;
        private ulong _sequence, _firstLossSequence;
        private int _protectedPrefix, _discarded, _errors;
        private string _firstError = "none";

        public Task24ShieldLaneObservation(SceneTree tree, PrologueLevelController level,
            CharacterBody2D player, PlayerShieldController shield, HealthComponent health,
            StaticBody2D gearEntry, Func<int> recoveryRequests, Func<int> recoveryCompletions)
        {
            _tree = tree; _level = level; _player = player; _shield = shield;
            _health = health; _gearEntry = gearEntry;
            _recoveryRequests = recoveryRequests; _recoveryCompletions = recoveryCompletions;
        }

        public void Begin()
        {
            Safely(() => _input = _player.GetNodeOrNull<PlayerInputReader>("Input"));
            Safely(() => _energy = _player.GetNodeOrNull<PlayerEnergyController>("Energy"));
            Safely(() => _motor = _player.GetNodeOrNull<PlayerMotor>("Motor"));
            Record("before_raise");
            Safely(() => { _tree.PhysicsFrame += OnPhysics; _physicsAttached = true; });
            Safely(() => { _shield.ShieldFrameChanged += OnShield; _shieldAttached = true; });
            Safely(() => { if (_energy != null) { _energy.EnergyFrameChanged += OnEnergy; _energyAttached = true; } });
            Safely(() => { _health.Damaged += OnDamage; _damageAttached = true; });
            Safely(() => { _health.Died += OnDeath; _deathAttached = true; });
            Safely(() => { _level.RecoveryRequested += OnRecoveryRequested; _requestsAttached = true; });
            Safely(() => { _level.RecoveryCompleted += OnRecoveryCompleted; _completionsAttached = true; });
        }

        public void Record(string boundary)
        {
            Safely(() =>
            {
                ulong sequence = ++_sequence;
                bool active = _shield.IsActive;
                bool firstLoss = _sawActive && !active && _firstLossSequence == 0;
                _sawActive |= active;
                PlayerInputFrame sampled = _input?.CurrentFrame ?? default;
                ulong supportId = 0;
                for (int index = 0; index < _player.GetSlideCollisionCount(); index++)
                {
                    KinematicCollision2D contact = _player.GetSlideCollision(index);
                    if (contact.GetNormal().Y >= -.7f) continue;
                    GodotObject collider = contact.GetCollider();
                    if (GodotObject.IsInstanceValid(collider)) supportId = collider.GetInstanceId();
                    break;
                }
                string row =
                    $"sequence={sequence} physics={Engine.GetPhysicsFrames()} boundary={boundary} first_loss={firstLoss} " +
                    $"input_sequence={(_input == null ? "unavailable" : _input.CurrentFrameSequence.ToString())} " +
                    $"sampled_shield_held={(_input == null ? "unavailable" : sampled.ShieldHeld.ToString())} " +
                    $"sampled_move_axis={(_input == null ? "unavailable" : sampled.MoveAxis.ToString("R", System.Globalization.CultureInfo.InvariantCulture))} " +
                    $"action_shield_held={Input.IsActionPressed(InputActions.Shield)} " +
                    $"action_move_axis={Input.GetAxis(InputActions.MoveLeft, InputActions.MoveRight).ToString("R", System.Globalization.CultureInfo.InvariantCulture)} " +
                    $"energy_ratio={(_energy == null ? "unavailable" : _energy.EnergyRatio.ToString("R", System.Globalization.CultureInfo.InvariantCulture))} " +
                    $"heat_ratio={(_energy == null ? "unavailable" : _energy.HeatRatio.ToString("R", System.Globalization.CultureInfo.InvariantCulture))} " +
                    $"sustained={(_energy == null ? "unavailable" : _energy.IsShieldSustained.ToString())} " +
                    $"overheated={(_energy == null ? "unavailable" : _energy.IsOverheated.ToString())} " +
                    $"shield_active={active} guard_direction={_shield.GuardDirection} hp={_health.CurrentHealth} position={_player.GlobalPosition} velocity={_player.Velocity} " +
                    $"on_floor={_player.IsOnFloor()} floor_support_id={supportId} gear_entry_contact={HasFloorContact(_player, _gearEntry)} " +
                    $"window_focus={_player.GetWindow().HasFocus()} recovery_requests={_recoveryRequests()} recovery_completions={_recoveryCompletions()} " +
                    $"shield_movement_scale={(_motor == null ? "unavailable" : _motor.ShieldMovementScale.ToString("R", System.Globalization.CultureInfo.InvariantCulture))} " +
                    $"effective_movement_scale={(_motor == null ? "unavailable" : _motor.EffectiveMovementScale.ToString("R", System.Globalization.CultureInfo.InvariantCulture))}";
                if (firstLoss)
                {
                    // Keep the two raise boundaries and the nearby ordered pre-loss history
                    // permanently; the remaining capacity is a rolling post-loss tail.
                    while (_records.Count > PreLossRecords + 2)
                    {
                        _records.RemoveAt(2);
                        _discarded++;
                    }
                }
                if (_records.Count == MaximumRecords)
                {
                    _records.RemoveAt(_protectedPrefix == 0 ? 2 : _protectedPrefix);
                    _discarded++;
                }
                _records.Add(row);
                if (firstLoss)
                {
                    _firstLossSequence = sequence;
                    _protectedPrefix = _records.Count;
                }
            });
        }

        private void OnPhysics() => Record("physics_frame_pre_node_process");
        private void OnShield(bool active) => Record(active ? "shield_became_active" : "shield_became_inactive");
        private void OnEnergy(PlayerEnergyFrame frame) => Record(FormattableString.Invariant(
            $"energy_frame_changed raw_energy={frame.State.Energy:R} raw_heat={frame.State.Heat:R}"));
        private void OnDamage(int remaining, Vector2 impulse) => Record("health_damaged");
        private void OnDeath() => Record("health_died");
        private void OnRecoveryRequested(string _) => Record("recovery_requested");
        private void OnRecoveryCompleted(string _) => Record("recovery_completed");

        public void End()
        {
            ITask24ShieldEndTimingSink timing = _tree as ITask24ShieldEndTimingSink;
            bool timingAccepted = false;
            try { if (timing != null) timingAccepted = timing.BeginTask24ShieldEnd(_errors); }
            catch (Exception) { /* Timing must not rewrite the shield observer's errors or route failure. */ }
            Record("window_end_finally");
            try { if (timingAccepted) timing.MarkTask24ShieldEnd(Task24ShieldEndBoundary.T1, _errors); }
            catch (Exception) { /* Preserve original End work and later timing boundaries. */ }
            // Every detach is independent and guarded. Observation failure never replaces
            // the original raise/walk/assertion exception, including on the failure path.
            Safely(() => { if (_physicsAttached) _tree.PhysicsFrame -= OnPhysics; });
            Safely(() => { if (_shieldAttached) _shield.ShieldFrameChanged -= OnShield; });
            Safely(() => { if (_energyAttached) _energy.EnergyFrameChanged -= OnEnergy; });
            Safely(() => { if (_damageAttached) _health.Damaged -= OnDamage; });
            Safely(() => { if (_deathAttached) _health.Died -= OnDeath; });
            Safely(() => { if (_requestsAttached) _level.RecoveryRequested -= OnRecoveryRequested; });
            Safely(() => { if (_completionsAttached) _level.RecoveryCompleted -= OnRecoveryCompleted; });
            try { if (timingAccepted) timing.MarkTask24ShieldEnd(Task24ShieldEndBoundary.T2, _errors); }
            catch (Exception) { /* Preserve original output and later timing boundaries. */ }
            // One formatting/order implementation. These factories are consumed synchronously,
            // never retained by the batch/sink. Immediate output keeps the original per-line Safely guard.
            void VisitOutput(Action<Func<string>> consume)
            {
                consume(() => $"TASK24_SHIELD_OBSERVATION_BEGIN records={_records.Count} maximum={MaximumRecords} " +
                    $"discarded={_discarded} first_loss_sequence={_firstLossSequence} observation_errors={_errors} first_error={_firstError} " +
                    "input_sample_physics=unavailable raw_energy_state_getter=unavailable private_guard_broken=unavailable");
                foreach (string record in _records)
                    consume(() => "TASK24_SHIELD_OBSERVATION " + record);
                consume(() => "TASK24_SHIELD_OBSERVATION_END");
            }
            string snapshotRejection = null;
            Task24ShieldOutputDisposition disposition = Task24ShieldOutputDispatch.Dispatch(_tree, () =>
            {
                var lines = new List<string>(_records.Count + 2);
                VisitOutput(factory => lines.Add(factory()));
                return Task24ShieldOutputBatch.TryCreate(lines, _records.Count, _errors, _firstError,
                    out var batch, out snapshotRejection) ? batch : null;
            });
            if (snapshotRejection != null) disposition = disposition with { Reason = snapshotRejection };
            if (disposition.Kind != Task24ShieldOutputKind.Deferred)
                VisitOutput(factory => Safely(() => GD.Print(factory())));
            try { if (timing != null) timing.RecordTask24ShieldOutputDisposition(disposition); }
            catch (Exception) { /* Unknown disposition must not be assumed to be immediate output. */ }
            try { if (timingAccepted) timing.MarkTask24ShieldEnd(Task24ShieldEndBoundary.T3, _errors); }
            catch (Exception) { /* Ancillary timing cannot replace the original route outcome. */ }
        }

        private void Safely(Action action)
        {
            try { action(); }
            catch (Exception exception)
            {
                _errors++;
                if (_errors == 1) _firstError = exception.GetType().Name;
            }
        }
    }

    // Observer only: no input, model Step, health writes, actor movement or gameplay decisions.
    // Native wrappers exist only in live bindings; retained receipts are detached value copies.
    private sealed class Task10NormalRangedEvidence : IDisposable
    {
        private const int MaxInstances = 64, MaxEventsPerInstance = 128;
        private readonly SceneTree _tree;
        private readonly PrologueLevelController _level;
        private readonly SeamlessPrologueWorld _world;
        private readonly CharacterBody2D _player;
        private readonly Task10RouteVariant _variant;
        private readonly ulong _playerId;
        private readonly PlayerCombat _combat;
        private readonly ulong _hitboxId;
        private ulong _lastPlayerAttackId;
        private readonly Dictionary<ulong, RangedBinding> _live = new();
        private readonly Dictionary<ulong, GroupBinding> _groups = new();
        private readonly List<RangedReceipt> _receipts = new();
        private string _observerError;
        private int _requests, _completions;
        private bool _disposed;

        private sealed class RangedReceipt
        {
            public string Encounter, Scene, Path, Role;
            public ulong ActorId, PlayerId;
            public int Batch, DamageEvents, PlayerCombatConnections, DefeatedEvents, DefeatedHealth = -1;
            public ulong WarningPhysics, ShotPhysics, DefeatedPhysics;
            public readonly HashSet<ulong> Warnings = new(), Shots = new();
            public readonly List<Task10NormalRangedEvent> Events = new();
            public Task10NormalRangedInstance Copy() => new(Encounter, Scene, Path, Role,
                ActorId, PlayerId, Batch, Warnings.Count, Shots.Count, DamageEvents, PlayerCombatConnections,
                DefeatedEvents, DefeatedHealth, WarningPhysics, ShotPhysics, DefeatedPhysics,
                Array.AsReadOnly(Events.ToArray()));
        }

        private sealed class RangedBinding
        {
            public RangedWeaponEnemy Actor;
            public HealthComponent Health;
            public RangedReceipt Receipt;
            public Action<AttackPresentationFrame> Attack;
            public Action<RangedWeaponFrame> Frame;
            public Action<ulong, Vector2> Shot;
            public Action Defeated;
            public HealthComponent.DamagedEventHandler Damaged;
            public Action Exit;
            public RangedWeaponState LastState;
        }

        private sealed class GroupBinding
        {
            public CanyonEncounterGroup Group;
            public CanyonEncounterGroup.CompletedEventHandler Completed;
            public Action Exit;
            public string Encounter;
            public int CompletionEvents;
            public ulong CompletionPhysics;
        }

        public Task10NormalRangedEvidence(SceneTree tree, PrologueLevelController level,
            SeamlessPrologueWorld world, CharacterBody2D player, Task10RouteVariant variant)
        {
            _tree = tree; _level = level; _world = world; _player = player;
            _variant = variant; _playerId = player.GetInstanceId();
            _combat = player.GetNode<PlayerCombat>("Combat");
            _hitboxId = _combat.GetNode<Hitbox>("AttackHitbox").GetInstanceId();
            // Installed before mounting PrologueLevel. NodeAdded observes every new root,
            // not only the actor selected by the existing first-child combat controller.
            _tree.NodeAdded += OnNodeAdded;
            _level.RecoveryRequested += OnRecoveryRequested;
            _level.RecoveryCompleted += OnRecoveryCompleted;
            _combat.AttackStarted += OnPlayerAttackStarted;
            _combat.AttackConnected += OnPlayerAttackConnected;
        }

        private void Callback(Action observation)
        {
            if (_disposed || _observerError != null) return;
            try { observation(); }
            catch (Exception error) { _observerError = error.ToString(); }
            // Do not throw through a production event and interrupt its remaining listeners.
        }

        public void AssertObserverHealthy() => TestAssert.True(_observerError == null,
            $"RANGED_NORMAL_OBSERVER_RED variant={_variant} error={_observerError}");

        private static string SavedScene(RangedWeaponRole role) => role switch
        {
            RangedWeaponRole.Scatter => CanyonEncounterCatalog.ScatterScene,
            RangedWeaponRole.Burst => CanyonEncounterCatalog.BurstScene,
            RangedWeaponRole.Laser => CanyonEncounterCatalog.LaserScene,
            RangedWeaponRole.Missile => CanyonEncounterCatalog.MissileScene,
            _ => throw new InvalidOperationException("unknown actual ranged role")
        };

        private static EnemyAttackKind AttackKind(RangedWeaponRole role) => role switch
        {
            RangedWeaponRole.Scatter => EnemyAttackKind.RivetScatterShot,
            RangedWeaponRole.Burst => EnemyAttackKind.BeltBurstShot,
            RangedWeaponRole.Laser => EnemyAttackKind.PrismLaserBeam,
            RangedWeaponRole.Missile => EnemyAttackKind.FurnaceMissileShot,
            _ => EnemyAttackKind.None
        };

        private void OnNodeAdded(Node node) => Callback(() =>
        {
            if (node is not RangedWeaponEnemy actor || !_world.IsAncestorOf(actor)) return;
            ulong id = actor.GetInstanceId();
            if (_live.ContainsKey(id)) return;
            TestAssert.True(_receipts.Count < MaxInstances,
                "RANGED_NORMAL_OBSERVER_RED bounded instance capacity exceeded");
            Godot.Collections.Array<Node> candidates = _world.FindChildren("*", "", true, false);
            using Godot.Collections.Array candidatesBacking = (Godot.Collections.Array)candidates;
            CanyonEncounterGroup group = candidates
                .OfType<CanyonEncounterGroup>().Single(candidate =>
                    candidate.GetNodeOrNull(candidate.ActorRootPath) == actor.GetParent() &&
                    actor.Name.ToString().StartsWith(candidate.EncounterId.ToString().Replace('.', '_') +
                        "_batch", StringComparison.Ordinal));
            string scene = actor.SceneFilePath;
            TestAssert.True(scene == SavedScene(actor.Role) && group.Definition != null &&
                group.Definition.Enemies.Any(placement => placement.ScenePath == scene &&
                    placement.ActivationBatch == group.CurrentBatch),
                "RANGED_NORMAL_OBSERVER_RED root must be the actual saved authored role/batch");
            BindGroup(group);
            using NodePath runtimePath = actor.GetPath();
            var receipt = new RangedReceipt
            {
                Encounter = group.EncounterId.ToString(), Scene = scene,
                Path = runtimePath.ToString(), Role = actor.Role.ToString(),
                ActorId = id, PlayerId = _playerId, Batch = group.CurrentBatch
            };
            var binding = new RangedBinding
            {
                Actor = actor, Health = actor.GetNode<HealthComponent>("Health"),
                Receipt = receipt, LastState = actor.CurrentFrame.State
            };
            binding.Attack = frame => Callback(() =>
            {
                if (frame.Timeline.Phase != AttackPhase.Telegraph) return;
                TestAssert.True(frame.Timeline.Kind == AttackKind(actor.Role) &&
                    frame.Timeline.AttackId != 0 && frame.Shape.Kind != AttackShapeKind.None,
                    "RANGED_NORMAL_OBSERVER_RED warning must have real role-typed geometry");
                if (!receipt.Warnings.Add(frame.Timeline.AttackId)) return;
                if (receipt.WarningPhysics == 0) receipt.WarningPhysics = Engine.GetPhysicsFrames();
                Record(binding, "typed_telegraph", frame.Timeline.AttackId, 0,
                    frame.Shape.Kind.ToString(), frame.Shape.Origin);
            });
            binding.Frame = frame => Callback(() =>
            {
                if (frame.State == binding.LastState) return;
                binding.LastState = frame.State;
                Record(binding, "state", frame.AttackTimeline.AttackId, 0, "", null);
            });
            binding.Shot = (ordinal, origin) => Callback(() =>
            {
                TestAssert.True(ordinal != 0, "RANGED_NORMAL_OBSERVER_RED zero actual shot ordinal");
                if (!receipt.Shots.Add(ordinal)) return;
                TestAssert.True(receipt.Warnings.Contains(actor.CurrentFrame.AttackTimeline.AttackId),
                    $"RANGED_NORMAL_ROLE_EXERCISE_RED actual shot has no prior typed telegraph " +
                    $"actor_id={id} attack_id={actor.CurrentFrame.AttackTimeline.AttackId}");
                if (receipt.ShotPhysics == 0) receipt.ShotPhysics = Engine.GetPhysicsFrames();
                Record(binding, "shot_emitted", actor.CurrentFrame.AttackTimeline.AttackId,
                    ordinal, "", origin);
            });
            binding.Damaged = (remaining, _) => Callback(() =>
            {
                receipt.DamageEvents++;
                Record(binding, "health_damaged", actor.CurrentFrame.AttackTimeline.AttackId,
                    0, "", null);
                TestAssert.True(binding.Health.CurrentHealth == remaining,
                    "RANGED_NORMAL_OBSERVER_RED damage receipt matches actual Health");
            });
            binding.Defeated = () =>
            {
                Callback(() =>
                {
                    receipt.DefeatedEvents++;
                    receipt.DefeatedHealth = binding.Health.CurrentHealth;
                    receipt.DefeatedPhysics = Engine.GetPhysicsFrames();
                    Record(binding, "defeated", actor.CurrentFrame.AttackTimeline.AttackId, 0, "", null);
                });
                Detach(id); // A genuine defeat ends this observation lifetime immediately.
            };
            binding.Exit = () =>
            {
                Callback(() => Record(binding, "tree_exiting_without_defeat",
                    actor.CurrentFrame.AttackTimeline.AttackId, 0, "", null));
                Detach(id);
            };
            _receipts.Add(receipt); _live.Add(id, binding);
            actor.AttackFrameChanged += binding.Attack;
            actor.FrameChanged += binding.Frame;
            actor.ShotEmitted += binding.Shot;
            actor.Defeated += binding.Defeated;
            binding.Health.Damaged += binding.Damaged;
            actor.TreeExiting += binding.Exit;
            // Bind is logged without pretending the not-yet-ready Health is initialized.
            GD.Print($"RANGED_NORMAL_BOUND variant={_variant} encounter={receipt.Encounter} " +
                $"scene={scene} path={receipt.Path} role={receipt.Role} actor_id={id} " +
                $"batch={receipt.Batch} player_id={_playerId} physics={Engine.GetPhysicsFrames()} " +
                $"actor={actor.GlobalPosition} muzzle={actor.GetNode<Node2D>("Muzzle").GlobalPosition} " +
                $"player={_player.GlobalPosition} worldpath_at_bind=unmeasured full_capsule_support=unmeasured");
        });

        private void BindGroup(CanyonEncounterGroup group)
        {
            ulong id = group.GetInstanceId();
            if (_groups.ContainsKey(id)) return;
            var binding = new GroupBinding { Group = group, Encounter = group.EncounterId.ToString() };
            binding.Completed = encounter => Callback(() =>
            {
                binding.CompletionEvents++;
                binding.CompletionPhysics = Engine.GetPhysicsFrames();
                GD.Print($"RANGED_NORMAL_GROUP_COMPLETED variant={_variant} encounter={encounter} " +
                    $"group_id={id} count={binding.CompletionEvents} physics={binding.CompletionPhysics}");
            });
            binding.Exit = () => DetachGroup(binding);
            group.Completed += binding.Completed; group.TreeExiting += binding.Exit;
            _groups.Add(id, binding);
        }

        private void OnPlayerAttackStarted(ulong attackId, int _) => _lastPlayerAttackId = attackId;

        private void OnPlayerAttackConnected(Hurtbox hurtbox) => Callback(() =>
        {
            if (hurtbox.GetParent() is not RangedWeaponEnemy actor) return;
            ulong id = actor.GetInstanceId();
            RangedReceipt receipt = _receipts.SingleOrDefault(candidate => candidate.ActorId == id);
            if (receipt == null) return;
            HealthComponent health = actor.GetNode<HealthComponent>("Health");
            TestAssert.True(_lastPlayerAttackId != 0 &&
                ReferenceEquals(hurtbox.ResolveDamageReceiver(), health),
                "RANGED_NORMAL_OBSERVER_RED player connection resolves the same actual actor Health");
            receipt.PlayerCombatConnections++;
            // Connected follows Health.Died/Defeated synchronously in Hitbox.TryConnect, so
            // a lethal connection may arrive after that actor's live binding was released.
            Record(new RangedBinding { Actor = actor, Health = health, Receipt = receipt },
                "player_attack_connected", actor.CurrentFrame.AttackTimeline.AttackId, 0, "", null);
        });

        private void Record(RangedBinding binding, string kind, ulong attackId, ulong shotOrdinal,
            string shape, Vector2? actualOrigin)
        {
            RangedReceipt receipt = binding.Receipt;
            TestAssert.True(receipt.Events.Count < MaxEventsPerInstance,
                "RANGED_NORMAL_OBSERVER_RED bounded transition capacity exceeded");
            RangedWeaponEnemy actor = binding.Actor;
            Node2D muzzle = actor.GetNode<Node2D>("Muzzle");
            Vector2 source = actor.GlobalPosition, origin = actualOrigin ?? muzzle.GlobalPosition;
            Vector2 player = _player.GlobalPosition;
            Rect2 viewport = actor.GetViewport().GetVisibleRect();
            var exclude = new Godot.Collections.Array<Rid> { actor.GetRid() };
            using Godot.Collections.Array excludeBacking = (Godot.Collections.Array)exclude;
            bool worldClear = RangedAttackGeometry.HasClearWorldPath(
                actor.GetWorld2D().DirectSpaceState, muzzle.GlobalPosition, player, exclude);
            var sample = new Task10NormalRangedEvent(kind, Engine.GetPhysicsFrames(), attackId,
                shotOrdinal, actor.CurrentFrame.State.ToString(), actor.CurrentFrame.AttackTimeline.Phase.ToString(),
                shape, binding.Health.CurrentHealth, _player.GetNode<HealthComponent>("Health").CurrentHealth,
                source.X, source.Y, origin.X, origin.Y, player.X, player.Y, _player.IsOnFloor(),
                actor.IsOnFloor(), viewport.HasPoint(muzzle.GetGlobalTransformWithCanvas().Origin),
                worldClear, _requests, _completions, _lastPlayerAttackId, _hitboxId, _combat.IsAttacking);
            receipt.Events.Add(sample);
            GD.Print("RANGED_NORMAL_EVENT " + System.Text.Json.JsonSerializer.Serialize(new
            {
                variant = _variant.ToString(), receipt.Encounter, receipt.Scene, receipt.Path,
                receipt.Role, receipt.ActorId, receipt.PlayerId, receipt.Batch, sample
            }));
        }

        private void OnRecoveryRequested(string _) => Callback(() =>
        {
            _requests++;
            _observerError = $"RANGED_NORMAL_ZERO_RECOVERY_RED request={_requests} " +
                $"completion={_completions} physics={Engine.GetPhysicsFrames()}";
        });
        private void OnRecoveryCompleted(string _) { if (!_disposed) _completions++; }

        public IReadOnlyList<Task10NormalRangedInstance> Snapshot() =>
            Array.AsReadOnly(_receipts.Select(receipt => receipt.Copy()).ToArray());

        public void AssertComplete(int requests, int completions)
        {
            AssertObserverHealthy();
            TestAssert.True(requests == 0 && completions == 0 && _requests == 0 && _completions == 0,
                $"RANGED_NORMAL_ZERO_RECOVERY_RED variant={_variant} monitor={requests}/{completions} " +
                $"observer={_requests}/{_completions}");
            AssertNormalRangedExercise(_variant.ToString(), Snapshot());
            foreach (GroupBinding group in _groups.Values)
                TestAssert.True(group.CompletionEvents == 1 && _receipts
                    .Where(receipt => receipt.Encounter == group.Encounter)
                    .All(receipt => receipt.DefeatedEvents == 1 &&
                        receipt.DefeatedPhysics <= group.CompletionPhysics),
                    $"RANGED_NORMAL_ROLE_EXERCISE_RED group={group.Encounter} requires exactly one " +
                    "real final completion after its observed individual defeats");
        }

        private void Detach(ulong id)
        {
            if (!_live.Remove(id, out RangedBinding binding)) return;
            RangedWeaponEnemy actor = binding.Actor;
            if (GodotObject.IsInstanceValid(actor))
            {
                actor.AttackFrameChanged -= binding.Attack; actor.FrameChanged -= binding.Frame;
                actor.ShotEmitted -= binding.Shot; actor.Defeated -= binding.Defeated;
                actor.TreeExiting -= binding.Exit;
            }
            if (GodotObject.IsInstanceValid(binding.Health)) binding.Health.Damaged -= binding.Damaged;
            binding.Actor = null; binding.Health = null;
            binding.Attack = null; binding.Frame = null; binding.Shot = null;
            binding.Defeated = null; binding.Damaged = null; binding.Exit = null;
        }

        private static void DetachGroup(GroupBinding binding)
        {
            if (GodotObject.IsInstanceValid(binding.Group))
            {
                binding.Group.Completed -= binding.Completed;
                binding.Group.TreeExiting -= binding.Exit;
            }
            binding.Group = null; binding.Completed = null; binding.Exit = null;
        }

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            _tree.NodeAdded -= OnNodeAdded;
            if (GodotObject.IsInstanceValid(_level))
            {
                _level.RecoveryRequested -= OnRecoveryRequested;
                _level.RecoveryCompleted -= OnRecoveryCompleted;
            }
            if (GodotObject.IsInstanceValid(_combat))
            {
                _combat.AttackStarted -= OnPlayerAttackStarted;
                _combat.AttackConnected -= OnPlayerAttackConnected;
            }
            foreach (ulong id in _live.Keys.ToArray()) Detach(id);
            foreach (GroupBinding group in _groups.Values) DetachGroup(group);
            foreach (RangedReceipt receipt in _receipts)
                GD.Print($"RANGED_NORMAL_INSTANCE_END variant={_variant} role={receipt.Role} " +
                    $"actor_id={receipt.ActorId} player_id={receipt.PlayerId} encounter={receipt.Encounter} " +
                    $"batch={receipt.Batch} telegraphs={receipt.Warnings.Count} shots={receipt.Shots.Count} " +
                    $"damage={receipt.DamageEvents} player_connections={receipt.PlayerCombatConnections} " +
                    $"defeated={receipt.DefeatedEvents} health={receipt.DefeatedHealth} " +
                    $"physics={receipt.WarningPhysics}/{receipt.ShotPhysics}/{receipt.DefeatedPhysics}");
            GD.Print($"RANGED_NORMAL_OBSERVER_END variant={_variant} instances={_receipts.Count} " +
                $"recoveries={_requests}/{_completions} observer_fault={_observerError ?? "none"}");
        }
    }

    internal static void AssertNormalRangedExercise(string variant,
        IReadOnlyList<Task10NormalRangedInstance> instances)
    {
        TestAssert.True(variant is nameof(Task10RouteVariant.Main) or nameof(Task10RouteVariant.Exploration),
            "RANGED_NORMAL_ROLE_EXERCISE_RED unknown actual route variant");
        // These are the original route's actual branches, not a mirrored actor model.
        string[] required = variant == nameof(Task10RouteVariant.Main)
            ? new[] { "Scatter", "Burst", "Laser" } : new[] { "Laser", "Missile" };
        foreach (string role in required)
            TestAssert.True(instances.Any(instance => instance.Role == role),
                $"RANGED_NORMAL_ROLE_EXERCISE_RED variant={variant} missing real saved role={role}");
        foreach (Task10NormalRangedInstance instance in instances)
            TestAssert.True(instance.ActorId != 0 && instance.PlayerId != 0 && instance.Batch >= 0 &&
                instance.WarningCount > 0 && instance.ShotCount > 0 && instance.DamageEvents > 0 &&
                instance.PlayerCombatConnections > 0 &&
                instance.DefeatedEvents == 1 && instance.DefeatedHealth == 0 &&
                instance.WarningPhysics <= instance.ShotPhysics && instance.ShotPhysics <= instance.DefeatedPhysics,
                $"RANGED_NORMAL_ROLE_EXERCISE_RED variant={variant} role={instance.Role} " +
                $"scene={instance.Scene} path={instance.Path} actor_id={instance.ActorId} " +
                $"player_id={instance.PlayerId} encounter={instance.Encounter} batch={instance.Batch} " +
                $"telegraphs={instance.WarningCount} shots={instance.ShotCount} damage={instance.DamageEvents} " +
                $"player_connections={instance.PlayerCombatConnections} " +
                $"defeated={instance.DefeatedEvents} health={instance.DefeatedHealth} " +
                $"physics={instance.WarningPhysics}/{instance.ShotPhysics}/{instance.DefeatedPhysics}");
    }

    private sealed class Task10RouteEvidence
    {
        private readonly PrologueLevelController _level;
        private readonly SeamlessPrologueWorld _world;
        private readonly CharacterBody2D _player;
        private readonly List<CanyonRouteNodeId> _routeNodes = new();
        private readonly HashSet<CanyonChallengeKind> _challengeKinds = new();
        private readonly HashSet<string> _encounterActivations = new(StringComparer.Ordinal);
        private readonly HashSet<string> _encounterDefeats = new(StringComparer.Ordinal);
        private readonly HashSet<string> _mechanisms = new(StringComparer.Ordinal);
        private readonly HashSet<string> _shortcuts = new(StringComparer.Ordinal);
        private readonly HashSet<string> _checkpoints = new(StringComparer.Ordinal);
        private CanyonRouteNodeId? _shortcutEntry;
        private bool _insideShortcut;
        public ulong PlayerInstanceId { get; }
        public Task10TerminalProof TerminalProof { get; private set; }

        public Task10RouteEvidence(PrologueLevelController level, SeamlessPrologueWorld world,
            CharacterBody2D player)
        {
            _level = level;
            _world = world;
            _player = player;
            PlayerInstanceId = player.GetInstanceId();
        }

        public void RecordTerminal(Task10TerminalProof proof)
        {
            if (proof == null) throw new ArgumentNullException(nameof(proof));
            TestAssert.True(TerminalProof == null, "Task10 terminal receipt is published exactly once");
            TestAssert.True(PlayerInstanceId != 0 && proof.PlayerInstanceId == PlayerInstanceId,
                "Task10 terminal receipt belongs to the original player identity");
            TerminalProof = proof;
        }

        public IReadOnlyList<CanyonRouteNodeId> RouteNodes => _routeNodes;
        public IReadOnlyList<CanyonChallengeKind> ChallengeKinds =>
            _challengeKinds.OrderBy(value => value).ToArray();
        public IReadOnlyList<string> EncounterActivations =>
            _encounterActivations.OrderBy(value => value, StringComparer.Ordinal).ToArray();
        public IReadOnlyList<string> EncounterDefeats =>
            _encounterDefeats.OrderBy(value => value, StringComparer.Ordinal).ToArray();
        public IReadOnlyList<string> MechanismsActivated =>
            _mechanisms.OrderBy(value => value, StringComparer.Ordinal).ToArray();
        public IReadOnlyList<string> ShortcutDirections =>
            _shortcuts.OrderBy(value => value, StringComparer.Ordinal).ToArray();
        public IReadOnlyList<string> CheckpointsActivated =>
            _checkpoints.OrderBy(value => value, StringComparer.Ordinal).ToArray();

        public void Observe()
        {
            CanyonRouteNodeDefinition current = CanyonWorldLayout.Nodes.FirstOrDefault(node =>
                node.WorldBounds.HasPoint(_player.GlobalPosition));
            if (current != null)
            {
                if (_routeNodes.Count == 0 || _routeNodes[^1] != current.Id)
                    _routeNodes.Add(current.Id);
                if (current.ChallengeKind.HasValue)
                    _challengeKinds.Add(current.ChallengeKind.Value);
            }

            foreach (CanyonEncounterGroup encounter in _world.FindChildren("*", "", true, false)
                         .OfType<CanyonEncounterGroup>())
            {
                string id = encounter.EncounterId.ToString();
                if (encounter.IsActive) _encounterActivations.Add(id);
                if (encounter.IsComplete) _encounterDefeats.Add(id);
            }
            foreach (string mechanism in _level.Progress.ActivatedMechanisms)
                _mechanisms.Add(mechanism);
            PrologueCheckpointSnapshot checkpoint = _level.Progress.RestoreCheckpoint();
            if (checkpoint.HasActivatedCheckpoint) _checkpoints.Add(checkpoint.CheckpointId);

            CanyonFireflyGuidanceController firefly = _level.GetNodeOrNull<CanyonFireflyGuidanceController>(
                "WorldRoot/FireflyGuidance");
            if (GodotObject.IsInstanceValid(firefly?.CurrentMarker))
                TestAssert.True(CanyonWorldLayout.DesignBounds.Grow(1f)
                        .HasPoint(firefly.CurrentMarker.GlobalPosition),
                    $"firefly route marker remains within reachable canyon bounds; " +
                    $"target={firefly.CurrentMarker.GetPath()} position={firefly.CurrentMarker.GlobalPosition}");

            ObserveShortcut();
        }

        private void ObserveShortcut()
        {
            CanyonShortcutWinch winch = _world.FindChildren("*", "", true, false)
                .OfType<CanyonShortcutWinch>().FirstOrDefault();
            if (!GodotObject.IsInstanceValid(winch) || !winch.IsOpen)
            {
                _insideShortcut = false;
                _shortcutEntry = null;
                return;
            }
            Rect2 corridor = new(winch.ToGlobal(winch.CorridorBounds.Position),
                winch.CorridorBounds.Size);
            bool inside = corridor.HasPoint(_player.GlobalPosition);
            float middleY = corridor.GetCenter().Y;
            if (inside && !_insideShortcut)
                _shortcutEntry = _player.GlobalPosition.Y > middleY
                    ? CanyonRouteNodeId.BasinCamp : CanyonRouteNodeId.SplitLevelEncounter;
            else if (!inside && _insideShortcut && _shortcutEntry.HasValue)
            {
                CanyonRouteNodeId exit = _player.GlobalPosition.Y > middleY
                    ? CanyonRouteNodeId.BasinCamp : CanyonRouteNodeId.SplitLevelEncounter;
                if (exit != _shortcutEntry.Value)
                    _shortcuts.Add($"{_shortcutEntry.Value}->{exit}");
                _shortcutEntry = null;
            }
            _insideShortcut = inside;
        }
    }

    private sealed class Task10ApplicationPersistenceGuard
    {
        private const string StorageArgument = "--case-storage-root=";
        private readonly Dictionary<string, string> _protectedBefore;

        private Task10ApplicationPersistenceGuard(string caseRoot,
            Dictionary<string, string> protectedBefore)
        {
            CaseRoot = caseRoot;
            _protectedBefore = protectedBefore;
        }

        public string CaseRoot { get; }

        public static Task10ApplicationPersistenceGuard CreateFromArguments()
        {
            string[] args = OS.GetCmdlineUserArgs();
            string supplied = Array.Find(args, value =>
                value.StartsWith(StorageArgument, StringComparison.Ordinal));
            TestAssert.True(supplied != null &&
                args.Count(value => value.StartsWith(StorageArgument,
                    StringComparison.Ordinal)) == 1,
                "Task10 route requires exactly one --case-storage-root=<absolute path>");
            string caseRoot = Task10RouteProofContract.ValidateRawStorageRoot(
                supplied![StorageArgument.Length..]);
            TestAssert.True(Path.IsPathFullyQualified(caseRoot) && Directory.Exists(caseRoot) &&
                !Directory.EnumerateFileSystemEntries(caseRoot).Any(),
                "Task10 case storage starts as an existing unique empty absolute directory");
            AssertNoReparseAncestors(caseRoot);

            string project = Path.GetFullPath(ProjectSettings.GlobalizePath("res://"))
                .TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            string actualUserData = Path.GetFullPath(OS.GetUserDataDir())
                .TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            TestAssert.True(!IsWithin(caseRoot, project) && !IsWithin(caseRoot, actualUserData),
                "Task10 case storage is outside both the project and real OS user-data directory");
            TestAssert.True(!args.Any(value =>
                    value == "--knight-playtest-grant-file" ||
                    value == "--knight-playtest-grant-nonce") &&
                !OS.HasEnvironment("KNIGHT_PLAYTEST_SOURCE"),
                "automated route rejects hands-on evidence grants and source environment");

            Dictionary<string, string> snapshot = CaptureProtectedDefaults(actualUserData);
            GD.Print($"TASK10_PERSISTENCE_GUARD actual_user_data={actualUserData} " +
                $"case_storage={caseRoot} protected_entries={snapshot.Count} " +
                "mode=off_tree_absolute_injection");
            return new Task10ApplicationPersistenceGuard(caseRoot, snapshot);
        }

        public string ResolveWritablePath(string relative)
        {
            string resolved = Path.GetFullPath(Path.Combine(CaseRoot, relative));
            TestAssert.True(IsWithin(resolved, CaseRoot),
                $"Task10 writable path stays inside case storage: {relative}");
            return resolved;
        }

        public void AssertInjectedPaths(string save, string settings, string playtests)
        {
            foreach (string path in new[] { save, settings, playtests })
                TestAssert.True(IsWithin(Path.GetFullPath(path), CaseRoot),
                    $"off-tree writable path resolves inside Task10 case storage: {path}");
            string legacy = Path.Combine(Path.GetDirectoryName(Path.GetFullPath(save))!,
                Path.GetFileName(PrologueGameFlowController.LegacySavePath));
            TestAssert.True(IsWithin(Path.GetFullPath(legacy), CaseRoot),
                "legacy save lookup sibling resolves inside Task10 case storage");
        }

        public void AssertProtectedDefaultsUnchanged()
        {
            string actualUserData = Path.GetFullPath(OS.GetUserDataDir())
                .TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            Dictionary<string, string> after = CaptureProtectedDefaults(actualUserData);
            TestAssert.Equal(string.Join("\n", _protectedBefore.OrderBy(pair => pair.Key)
                    .Select(pair => pair.Key + "=" + pair.Value)),
                string.Join("\n", after.OrderBy(pair => pair.Key)
                    .Select(pair => pair.Key + "=" + pair.Value)),
                "normal route leaves default user://knight and user://playtests inventories byte-identical");
            GD.Print($"TASK10_PERSISTENCE_GUARD_OK protected_entries={after.Count} " +
                "default_application_data_unchanged=True");
        }

        private static Dictionary<string, string> CaptureProtectedDefaults(string userData)
        {
            var result = new Dictionary<string, string>(StringComparer.Ordinal);
            foreach (string relativeRoot in new[] { "knight", "playtests", "logs" })
            {
                string root = Path.Combine(userData, relativeRoot);
                result[relativeRoot + "/"] = Directory.Exists(root) ? "directory" : "missing";
                if (!Directory.Exists(root)) continue;
                CaptureDirectory(root, relativeRoot, result);
            }
            return result;
        }

        private static void CaptureDirectory(string root, string relative,
            IDictionary<string, string> result)
        {
            foreach (string entry in Directory.EnumerateFileSystemEntries(root)
                         .OrderBy(value => value, StringComparer.OrdinalIgnoreCase))
            {
                FileAttributes attributes = File.GetAttributes(entry);
                string child = relative + "/" + Path.GetFileName(entry);
                if ((attributes & FileAttributes.ReparsePoint) != 0)
                {
                    result[child] = "reparse";
                    continue;
                }
                if ((attributes & FileAttributes.Directory) != 0)
                {
                    result[child + "/"] = "directory";
                    CaptureDirectory(entry, child, result);
                    continue;
                }
                var info = new FileInfo(entry);
                using FileStream stream = File.Open(entry, FileMode.Open, System.IO.FileAccess.Read,
                    FileShare.ReadWrite | FileShare.Delete);
                result[child] = $"file|{info.Length}|{Convert.ToHexString(SHA256.HashData(stream))}";
            }
        }

        private static void AssertNoReparseAncestors(string path)
        {
            for (DirectoryInfo current = new(path); current != null; current = current.Parent)
                if (current.Exists)
                    TestAssert.True((current.Attributes & FileAttributes.ReparsePoint) == 0,
                        $"Task10 case storage rejects reparse ancestor: {current.FullName}");
        }

        internal static bool IsWithin(string candidate, string root)
        {
            string normalizedCandidate = Path.GetFullPath(candidate).TrimEnd(
                Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            string normalizedRoot = Path.GetFullPath(root).TrimEnd(
                Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            return string.Equals(normalizedCandidate, normalizedRoot,
                       StringComparison.OrdinalIgnoreCase) ||
                   normalizedCandidate.StartsWith(normalizedRoot + Path.DirectorySeparatorChar,
                       StringComparison.OrdinalIgnoreCase);
        }
    }
}

// Immutable value observations from genuine fatal death, completion and held60 boundaries.
// Synthetic unit fixtures use this same shape but are never actual route evidence.
public sealed record Task10TerminalProof
{
    public ulong PlayerInstanceId { get; init; }
    public ulong BossInstanceId { get; init; }
    public ulong FatalAttackId { get; init; }
    public ulong ExposurePhysics { get; init; }
    public ulong AttackPhysics { get; init; }
    public ulong DamagePhysics { get; init; }
    public ulong DefeatedPhysics { get; init; }
    public ulong CompletionPhysics { get; init; }
    public ulong HeldEndPhysics { get; init; }
    public int BossDiedEvents { get; init; }
    public int ArenaDefeatedEvents { get; init; }
    public int CompletionEvents { get; init; }
    public int CompletionCount { get; init; }
    public ulong RightInputIssueSequence { get; init; }
    public ulong RightInputSampleSequence { get; init; }
    public Rect2 CompletionBody { get; init; }
    public Rect2 CompletionFloor { get; init; }
    public Rect2 CompletionDoor { get; init; }
    public bool SupportedAtCompletion { get; init; }
    public PrologueGameFlowState CompletionFlowState { get; init; }
    public bool PlayerPhysicsEnabledAtCompletion { get; init; }
    public bool CompletionPanelVisible { get; init; }
    public bool SavedBossDefeatedBeforeExit { get; init; }
    public bool SavedBossDefeatedAfterExit { get; init; }
    public bool SavedCompletedBeforeExit { get; init; }
    public bool SavedCompletedAfterExit { get; init; }
    public string CheckpointBeforeExit { get; init; } = string.Empty;
    public string CheckpointAfterExit { get; init; } = string.Empty;
    public int HeldInputFrameCount { get; init; }
    public Vector2 CompletionPosition { get; init; }
    public Vector2 HeldEndPosition { get; init; }
    public Vector2 CompletionVelocity { get; init; }
    public Vector2 HeldEndVelocity { get; init; }
    public Rect2 HeldEndBody { get; init; }
    public string CompletionSaveSha256 { get; init; } = string.Empty;
    public string HeldEndSaveSha256 { get; init; } = string.Empty;
}

public sealed record Task10NormalRangedEvent(string Kind, ulong Physics, ulong AttackId,
    ulong ShotOrdinal, string State, string Phase, string Shape, int ActorHealth, int PlayerHealth,
    float ActorX, float ActorY, float OriginX, float OriginY, float PlayerX, float PlayerY,
    bool PlayerOnFloor, bool ActorOnFloor, bool MuzzleInViewport, bool ClearWorldPath,
    int RecoveryRequests, int RecoveryCompletions, ulong PlayerAttackId, ulong PlayerHitboxId,
    bool PlayerAttacking);

public sealed record Task10NormalRangedInstance(string Encounter, string Scene, string Path,
    string Role, ulong ActorId, ulong PlayerId, int Batch, int WarningCount, int ShotCount,
    int DamageEvents, int PlayerCombatConnections, int DefeatedEvents, int DefeatedHealth, ulong WarningPhysics,
    ulong ShotPhysics, ulong DefeatedPhysics, IReadOnlyList<Task10NormalRangedEvent> Events);

public sealed record PrologueContinuousRouteResult
{
    public static PrologueContinuousRouteResult Empty { get; } = new();
    public bool StartedFromTitle { get; init; }
    public string Variant { get; init; } = string.Empty;
    public bool PersistentPlayer { get; init; }
    public ulong PlayerInstanceId { get; init; }
    public Task10TerminalProof TerminalProof { get; init; } = null;
    public IReadOnlyList<CanyonRouteNodeId> RouteNodes { get; init; } =
        Array.Empty<CanyonRouteNodeId>();
    public IReadOnlyList<CanyonChallengeKind> ChallengeKinds { get; init; } =
        Array.Empty<CanyonChallengeKind>();
    public IReadOnlyList<string> EncounterActivations { get; init; } = Array.Empty<string>();
    public IReadOnlyList<string> EncounterDefeats { get; init; } = Array.Empty<string>();
    public IReadOnlyList<string> MechanismsActivated { get; init; } = Array.Empty<string>();
    public IReadOnlyList<string> ShortcutDirections { get; init; } = Array.Empty<string>();
    public IReadOnlyList<string> CheckpointsActivated { get; init; } = Array.Empty<string>();
    public bool BossDefeated { get; init; }
    public bool SafeExitReached { get; init; }
    public PrologueGameFlowState FlowState { get; init; }
    public int RecoveryRequests { get; init; }
    public int RecoveryCompletions { get; init; }
    public bool NormalRangedExerciseRequired { get; init; }
    public IReadOnlyList<Task10NormalRangedInstance> NormalRangedInstances { get; init; } =
        Array.Empty<Task10NormalRangedInstance>();

    public void AssertComplete(string expectedVariant) =>
        Task10RouteProofContract.AssertApplicable(this, expectedVariant);

    private static bool IsBranchEncounter(string id) => id is
        "canyon.v2.encounter.archive-side-cave" or
        "canyon.v2.encounter.frozen-upper" or
        "canyon.v2.encounter.steam-valves" or
        "canyon.v2.encounter.frozen-lower";
}
